(function(){"use strict";var w=window.ScripturaJosephusTexts||(window.ScripturaJosephusTexts={});var a=w.antiguidades||(w.antiguidades={});a[13]={"book":13,"title":"Τάδε ἔνεστιν ἐν τῇ τρισκαιδεκάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς Ἰωνάθης ἀδελφὸς ὢν Ἰούδα τελευτήσαντος αὐτοῦ τὴν ἡγεμονίαν παρέλαβεν.\n\nὡς πολεμήσας Βακχίδην ἠνάγκασεν φιλίαν ποιησάμενον πρὸς αὐτὸν ἀπελθεῖν ἐκ τῆς χώρας.\n\nὅτι Ἀλέξανδρος ὁ τοῦ Ἐπιφανοῦς Ἀντιόχου υἱὸς ἐλθὼν εἰς Συρίαν ἐξήνεγκεν πόλεμον πρὸς Δημήτριον.\n\nὡς Δημήτριος πρεσβευσάμενος πρὸς Ἰωνάθην ποιεῖται συμμαχίαν πρὸς αὐτὸν αὐτόν τε πολλοῖς δωρησάμενος καὶ τὸ ἔθνος ἡμῶν.\n\nὡς Ἀλέξανδρος ταῦτα ἀκούσας καὶ ὑπερβαλὼν τὰ παρὰ τοῦ Δημητρίου καὶ ἀποδείξας Ἰωνάθην ἀρχιερέα συμμαχεῖν ἔπεισεν αὐτῷ.\n\nἡ Ὀνίου φιλία πρὸς τὸν Φιλομήτορα Πτολεμαῖον κατὰ τὸν αὐτὸν καιρὸν γενομένη, καὶ ὡς ᾠκοδόμησεν τὸν Ὀνίου καλούμενον ναὸν πρὸς τὸν ἐν Ἱεροσολύμοις ὄντα.\n\nὅτι Ἀλέξανδρος ἀποθανόντος Δημητρίου σφόδρα ἐτίμησεν Ἰωνάθην.\n\nὡς Δημήτριος ὁ Δημητρίου παῖς πλεύσας εἰς τὴν Συρίαν ἀπὸ Κρήτης καὶ πολεμήσας τὸν Ἀλέξανδρον καὶ κρατήσας αὐτοῦ αὐτὸς ἐβασίλευσεν φιλίαν πρὸς Ἰωνάθην ποιησάμενος.\n\nὡς Τρύφων ὁ Ἀπαμεὺς καταπολεμήσας Δημήτριον Ἀντιόχῳ τῷ Ἀλεξάνδρου υἱῷ παρέδωκεν τὴν βασιλείαν ποιησάμενος καὶ αὐτὸς σύμμαχον Ἰωνάθην.\n\nὡς Δημητρίου ὑπὸ Πάρθων αἰχμαλώτου ληφθέντος παρεσπόνδησεν τὸν Ἰωνάθην καὶ δόλῳ λαβὼν αὐτὸν ἀπέκτεινεν καὶ πόλεμον ἐξήνεγκεν πρὸς τὸν ἀδελφὸν αὐτοῦ Σίμωνα.\n\nὡς Σίμωνι τῷ ἀδελφῷ αὐτοῦ τὴν στρατηγίαν ἐνεχείρισεν τὸ ἔθνος καὶ ἀπέδειξεν αὐτὸν ἀρχιερέα.\n\nὡς ἐπολιόρκησεν ἐν Δώροις Τρύφωνα σύμμαχος γενόμενος Ἀντιόχῳ τῷ Δημητρίου ἀδελφῷ τῷ καὶ Εὐσεβεῖ ἐπικληθέντι.\n\nὡς Τρύφωνος ἀναιρεθέντος Ἀντίοχος ἐπολέμησεν Σίμωνα κἀκεῖνος Κενδεβαῖον τὸν στρατηγὸν αὐτοῦ νικήσας τῆς Ἰουδαίας ἐξέβαλεν.\n\nὅτι ὑπὸ τοῦ γαμβροῦ Πτολεμαίου ἐν συμποσίῳ δολοφονηθεὶς ἀπέθανεν, καὶ Πτολεμαῖος δήσας αὐτοῦ τὴν γυναῖκα καὶ τὰ τέκνα τὴν ἀρχὴν αὐτὸς ἐπεχείρησεν κατασχεῖν.\n\nὡς ὁ νεώτατος τῶν Σίμωνος υἱῶν Ὑρκανὸς φθάσας αὐτὸν καὶ τὴν ἡγεμονίαν παραλαβὼν ἐπολιόρκησεν τὸν Πτολεμαῖον εἴς τι φρούριον ἐγκλείσας Δαγὼν καλούμενον.\n\nὡς στρατευσάμενος ἐπὶ Ὑρκανὸν Ἀντίοχος ὁ καλούμενος Εὐσεβὴς καὶ προσκαθίσας τῇ τῶν Ἱεροσολυμιτῶν πόλει διέλυσε τὴν πολιορκίαν λαβὼν παρὰ Ὑρκανοῦ τάλαντα τριακόσια καὶ συμμαχίαν πρὸς αὐτὸν καὶ φιλίαν συνθέμενος.\n\nὙρκανοῦ στρατεία μετὰ τὴν Ἀντιόχου τελευτὴν ἐν Μήδοις ἀποθανόντος ἐπὶ Συρίαν καὶ ὡς πολλὰς πόλεις κατὰ κράτος εἷλεν.\n\nφιλία πρὸς Ὑρκανὸν Ἀλεξάνδρου τοῦ Ζαβίνα κληθέντος.\n\nὡς ἡττηθεὶς ὑφ' Ὑρκανοῦ Ἀντίοχος ὁ Κυζικηνὸς ἐξέπεσεν τῆς Ἰουδαίας.\n\nὡς παραλαβὼν Ἀριστόβουλος τὴν ἀρχὴν διάδημα περιέθετο πρῶτος.\n\nὡς τελευτήσαντος Ἀριστοβούλου ὁ ἀδελφὸς αὐτοῦ τὴν ἀρχὴν παραλαβὼν Ἀλέξανδρος ἐστράτευσεν ἐπὶ Συρίαν καὶ Φοινίκην καὶ Ἀραβίαν καὶ πολλὰ τῶν ἐθνῶν ἐχειρώσατο.\n\nΠτολεμαίου τοῦ Λαθούρου πρὸς αὐτὸν μάχη καὶ νίκη.\n\nὡς στρατευσάμενος Δημήτριος ὁ Εὔκαιρος λεγόμενος ἐπὶ Ἀλέξανδρον ἐκράτησεν αὐτοῦ.\n\nἈντιόχου τοῦ καὶ Διονύσου λεγομένου στρατεία ἐπὶ Ἰουδαίαν καὶ ὡς ἐκράτησεν τῇ μάχῃ.\n\nὡς μετὰ τὴν Ἀλεξάνδρου τελευτὴν ἡ γυνὴ αὐτοῦ Ἀλεξάνδρα τὴν βασιλείαν ἔτεσιν ἐννέα κατασχοῦσα καὶ βιώσασα μετὰ εἰρήνης καὶ δόξης ἀπέθανεν.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ὀγδοήκοντα καὶ δύο."},"chapters":{"1":[{"number":1,"text":"Τίνα μὲν οὖν τρόπον τὸ τῶν Ἰουδαίων ἔθνος καταδουλωσαμένων αὐτὸ τῶν Μακεδόνων ἀνεκτήσατο τὴν ἐλευθερίαν καὶ διʼ ὅσων καὶ πηλίκων ἀγώνων ὁ στρατηγὸς αὐτῶν ἐλθὼν Ἰούδας ἀπέθανεν ὑπὲρ αὐτῶν μαχόμενος, ἐν τῇ πρὸ ταύτης βίβλῳ δεδηλώκαμεν."},{"number":2,"text":"μετὰ δὲ τὴν τελευτὴν τὴν Ἰούδου πᾶν ὅσον ἦν ἔτι τῶν ἀσεβῶν καὶ παραβεβηκότων τὴν πάτριον πολιτείαν ἐπεφύη τοῖς Ἰουδαίοις καὶ πανταχόθεν αὐτοὺς ἀκμάζον ἐκάκου."},{"number":3,"text":"συνελάμβανε δὲ τῇ τούτων πονηρίᾳ καὶ λιμὸς τὴν χώραν καταλαβών, ὡς πολλοὺς διὰ τὴν σπάνιν τῶν ἀναγκαίων καὶ τὸ μὴ δύνασθαι τοῖς παρʼ ἀμφοτέρων ἀπό τε τοῦ λιμοῦ καὶ τῶν ἐχθρῶν δεινοῖς ἀντέχειν αὐτομολῆσαι πρὸς τοὺς Μακεδόνας."},{"number":4,"text":"Βακχίδης δὲ τῶν Ἰουδαίων τοὺς ἀποστάντας τῆς πατρίου συνηθείας καὶ τὸν κοινὸν βίον προῃρημένους συναθροίσας τούτοις ἐνεχείρισεν τὴν τῆς χώρας ἐπιμέλειαν, οἳ καὶ συλλαμβάνοντες τοὺς Ἰούδου φίλους καὶ τὰ ἐκείνου φρονοῦντας τῷ Βακχίδῃ παρέδοσαν· ὁ δὲ βασανίζων πρῶτον αὐτοὺς καὶ πρὸς ἡδονὴν αἰκιζόμενος ἔπειθʼ οὕτως διέφθειρεν."},{"number":5,"text":"ταύτης δὲ τῆς συμφορᾶς τοῖς Ἰουδαίοις τηλικαύτης γενομένης, ἡλίκης οὐκ ἦσαν πεπειραμένοι μετὰ τὴν ἐκ Βαβυλῶνος ἐπάνοδον, οἱ περιλειφθέντες τῶν ἑταίρων τῶν Ἰούδου βλέποντες ἀπολλύμενον οἰκτρῶς τὸ ἔθνος προσελθόντες αὐτοῦ τῷ ἀδελφῷ Ἰωνάθῃ μιμεῖσθαι τὸν ἀδελφὸν αὐτοῦ καὶ τὴν ἐκείνου περὶ τῶν ὁμοφύλων πρόνοιαν ἠξίουν ἀποθανόντος ὑπὲρ τῆς ἐκείνων ἐλευθερίας, καὶ μὴ περιορᾶν ἀπροστάτητον τὸ ἔθνος μηδʼ ἐν οἷς φθείρεται."},{"number":6,"text":"ὁ δʼ Ἰωνάθης φήσας ἑτοίμως ἔχειν ἀποθνήσκειν ὑπὲρ αὐτῶν καὶ νομισθεὶς κατὰ μηδὲν εἶναι χείρων τἀδελφοῦ στρατηγὸς ἀποδείκνυται τῶν Ἰουδαίων."},{"number":7,"text":"Ὁ δὲ Βακχίδης ἀκούσας καὶ φοβηθείς, μὴ παράσχῃ πράγματα τῷ βασιλεῖ καὶ τοῖς Μακεδόσιν ὁ Ἰωνάθης, ὡς καὶ πρότερον Ἰούδας, ἀποκτεῖναι δόλῳ τοῦτον ἐζήτει."},{"number":8,"text":"ταύτην δὲ ἔχων τὴν προαίρεσιν οὐκ ἔλαθεν τὸν Ἰωνάθην οὐδὲ τὸν ἀδελφὸν αὐτοῦ Σίμωνα, ἀλλὰ γὰρ μαθόντες οὗτοι καὶ παραλαβόντες τοὺς ἑταίρους ἅπαντας εἰς τὴν ἐρημίαν τὴν ἔγγιστα τῆς πόλεως τὸ τάχος ἔφυγον, καὶ παραγενόμενοι ἐπὶ τὸ ὕδωρ τὸ καλούμενον λάκκου Ἀσφὰρ αὐτόθι διῆγον."},{"number":9,"text":"ὁ δὲ Βακχίδης αἰσθόμενος αὐτοὺς ἀπηρκότας καὶ ἐν ἐκείνῳ τῷ τόπῳ τυγχάνοντας ὥρμησεν ἐπʼ αὐτοὺς μετὰ πάσης τῆς δυνάμεως, καὶ πέραν τοῦ Ἰορδάνου στρατοπεδευσάμενος ἀνελάμβανε τὴν δύναμιν."},{"number":10,"text":"Ἰωνάθης δὲ γνοὺς τὸν Βακχίδην ἐπʼ αὐτὸν ἥκοντα πέμπει τὸν ἀδελφὸν Ἰωάννην τὸν καὶ Γάδδειν λεγόμενον πρὸς τοὺς Ναβαταίους Ἄραβας, ἵνα παρʼ αὐτοῖς ἀποθῆται τὴν ἀποσκευὴν ἕως οὗ πολεμήσουσι πρὸς Βακχίδην· ἦσαν γὰρ φίλοι."},{"number":11,"text":"τὸν δὲ Ἰωάννην ἀπιόντα πρὸς τοὺς Ναβαταίους ἐνεδρεύσαντες ἐκ Μηδάβας πόλεως οἱ Ἀμαραίου παῖδες αὐτόν τε συλλαμβάνουσι καὶ τοὺς σὺν αὐτῷ, καὶ διαρπάσαντες ὅσα ἐπεκομίζετο κτείνουσι τὸν Ἰωάννην καὶ τοὺς ἑταίρους αὐτοῦ πάντας. δίκην μέντοι γε τούτων ὑπέσχον τοῖς ἀδελφοῖς αὐτοῦ τὴν ἀξίαν, ἣν μετʼ οὐ πολὺ δηλώσομεν."},{"number":12,"text":"Ὁ δὲ Βακχίδης γνοὺς τὸν Ἰωνάθην ἐν τοῖς ἕλεσι τοῦ Ἰορδάνου κατεστρατοπεδευμένον παραφυλάξας τὴν τῶν σαββάτων ἡμέραν ἐπʼ αὐτὸν ἧκεν ὡς οὐ μαχούμενον ἐκείνῃ διὰ τὸν νόμον."},{"number":13,"text":"ὁ δὲ παρορμήσας τοὺς ἑταίρους καὶ περὶ τῶν ψυχῶν αὐτοῖς εἶναι τὸν κίνδυνον εἰπὼν μέσοις ἀπειλημμένοις τοῦ τε ποταμοῦ καὶ τῶν πολεμίων ὡς φυγὴν οὐκ ἔχουσιν, οἱ μὲν γὰρ ἔμπροσθεν ἐπῄεσαν ὁ ποταμὸς δʼ ἦν κατόπιν αὐτῶν, εὐξάμενος δὲ καὶ τῷ θεῷ νίκην αὐτοῖς παρασχεῖν συνάπτει τοῖς πολεμίοις."},{"number":14,"text":"ὧν πολλοὺς καταβαλὼν ἐπεὶ τολμηρῶς εἶδεν ἐπερχόμενον αὐτῷ τὸν Βακχίδην, ἐξέτεινε τὴν δεξιὰν ὡς πλήξων αὐτόν. τοῦ δὲ προϊδομένου καὶ τὴν πληγὴν ἐκκλίναντος ἀποπηδήσας μετὰ τῶν ἑταίρων εἰς τὸν ποταμὸν διενήξατο, καὶ τοῦτον διασώζονται τὸν τρόπον εἰς τὸ πέραν τοῦ Ἰορδάνου, τῶν πολεμίων οὐκέτι τὸν ποταμὸν ἀντιδιαβάντων ὑποστρέψαντος εὐθὺς τοῦ Βακχίδου εἰς τὴν ἐν Ἱεροσολύμοις ἄκραν."},{"number":15,"text":"ἀπέβαλεν δὲ τῆς στρατιᾶς ὡς περὶ δισχιλίους. πολλὰς δὲ τῆς Ἰουδαίας καταλαβόμενος πόλεις ὁ Βακχίδης ὠχύρωσεν, καὶ τὴν Ἱεριχοῦντα καὶ Ἀμμαοῦν καὶ Βαιθωροῦν καὶ Βέθηλα καὶ Θαμναθὰ καὶ Φαραθὼ καὶ Τοχόαν καὶ Γάζαρα,"},{"number":16,"text":"καὶ πύργους ἐν ἑκάστῃ τῶν πόλεων οἰκοδομήσας καὶ τείχη περιβαλὼν αὐταῖς καρτερὰ καὶ τῷ μεγέθει διαφέροντα δύναμιν εἰς αὐτὰς κατέστησεν, ὅπως κακοῦν ἐκεῖθεν ὁρμώμενοι τοὺς Ἰουδαίους ἔχωσιν."},{"number":17,"text":"μάλιστα δὲ τὴν ἐν Ἱεροσολύμοις ἄκραν ὠχύρωσεν. λαβὼν δὲ καὶ τοὺς τῶν πρώτων τῆς Ἰουδαίας παῖδας ὁμήρους εἰς τὴν ἄκραν αὐτοὺς ἐνέκλεισεν καὶ τοῦτον ἐφύλαττεν τὸν τρόπον."},{"number":18,"text":"Ὑπὸ τὸν αὐτὸν δὲ καιρὸν παραγενόμενός τις πρὸς Ἰωνάθην καὶ τὸν ἀδελφὸν αὐτοῦ Σίμωνα τοὺς Ἀμαραίου παῖδας ἀπήγγειλεν αὐτοῖς γάμον ἐπιτελοῦντας καὶ τὴν νύμφην ἄγοντας ἀπὸ Ναβαθὰ πόλεως θυγατέρα τινὸς οὖσαν τῶν ἐπιφανῶν παρὰ τοῖς Ἄραψιν, μέλλειν δὲ γίνεσθαι παραπομπὴν τῆς κόρης λαμπρὰν καὶ πολυτελῆ."},{"number":19,"text":"οἱ δὲ περὶ τὸν Ἰωνάθην καὶ Σίμωνα καιρὸν ἐπιτηδειότατον εἰς τὴν ἐκδικίαν τἀδελφοῦ νομίσαντες αὐτοῖς παραφανῆναι, καὶ λήψεσθαι τὴν ὑπὲρ Ἰωάννου δίκην παρʼ αὐτῶν ἐπὶ πολλῆς ἐξουσίας ὑπολαβόντες ἐξώρμησαν εἰς τὰ Μήδαβα καὶ τοὺς ἐχθροὺς ἐν τῷ ὄρει λοχῶντες ἔμενον."},{"number":20,"text":"ὡς δʼ εἶδον αὐτοὺς ἄγοντας τὴν παρθένον καὶ τὸν νυμφίον καὶ φίλων σὺν αὐτοῖς οἷον εἰκὸς ἐν γάμοις ὄχλον, ἀναπηδήσαντες ἐκ τῆς ἐνέδρας ἀπέκτειναν ἅπαντας καὶ τὸν κόσμον καὶ τὴν ἄλλην ὅση τότε εἵπετο λεία τοῖς ἀνθρώποις λαβόντες ὑπέστρεψαν."},{"number":21,"text":"καὶ τιμωρίαν μὲν ὑπὲρ Ἰωάννου τἀδελφοῦ παρὰ τῶν υἱῶν Ἀμαραίου τοιαύτην ἀπέλαβον· αὐτοί τε γὰρ οὗτοι καὶ οἱ συνεπόμενοι τούτοις φίλοι καὶ γυναῖκες αὐτῶν καὶ τέκνα διεφθάρησαν ὄντες τετρακόσιοι."},{"number":22,"text":"Σίμων μὲν οὖν καὶ Ἰωνάθης εἰς τὰ ἕλη τοῦ ποταμοῦ ὑποστρέψαντες αὐτόθι κατέμενον. Βακχίδης δὲ τὴν Ἰουδαίαν ἅπασαν φρουραῖς ἀσφαλισάμενος ὑπέστρεψεν πρὸς τὸν βασιλέα. καὶ τότε μὲν ἐπʼ ἔτη δύο τὰ τῶν Ἰουδαίων ἠρέμησεν πράγματα."},{"number":23,"text":"οἱ δὲ φυγάδες καὶ οἱ ἀσεβεῖς ὁρῶντες τὸν Ἰωνάθην καὶ τοὺς σὺν αὐτῷ μετὰ πολλῆς ἀδείας ἐνδιατρίβοντας τῇ χώρᾳ διὰ τὴν εἰρήνην πέμπουσιν πρὸς Δημήτριον τὸν βασιλέα, παρακαλοῦντες ἀποστεῖλαι Βακχίδην ἐπὶ τὴν Ἰωνάθου σύλληψιν· ἐδήλουν γὰρ αὐτὴν ἀπόνως ἐσομένην, καὶ νυκτὶ μιᾷ μὴ προσδοκῶσιν αὐτοῖς ἐπιπεσόντες ἀποκτενεῖν ἅπαντας."},{"number":24,"text":"τοῦ δὲ βασιλέως ἐκπέμψαντος τὸν Βακχίδην, γενόμενος οὗτος ἐν τῇ Ἰουδαίᾳ πᾶσιν ἔγραψεν τοῖς φίλοις καὶ Ἰουδαίοις καὶ συμμάχοις συλλαβεῖν αὐτῷ τὸν Ἰωνάθην."},{"number":25,"text":"σπουδαζόντων δὲ πάντων καὶ μὴ δυναμένων κρατῆσαι τοῦ Ἰωνάθου, ἐφυλάσσετο γὰρ σφόδρα τὴν ἐπιβουλὴν ᾐσθημένος, ὁ Βακχίδης ὀργισθεὶς τοῖς φυγάσιν ὡς ψευσαμένοις αὐτόν τε καὶ τὸν βασιλέα πεντήκοντα αὐτῶν τοὺς ἡγουμένους συλλαβὼν ἀπέκτεινεν."},{"number":26,"text":"ὁ δὲ Ἰωνάθης σὺν τἀδελφῷ καὶ τοῖς ἑταίροις εἰς Βηθαλαγὰν ἀναχωρεῖ κώμην οὖσαν ἐν τῇ ἐρήμῳ φοβηθεὶς τὸν Βακχίδην, καὶ οἰκοδομήσας πύργους καὶ τείχη περιβαλόμενος αὑτὸν ἔσχεν ἀσφαλῶς πεφρουρημένον."},{"number":27,"text":"Βακχίδης δὲ ταῦτʼ ἀκούσας τήν τε μεθʼ ἑαυτοῦ στρατιὰν ἄγων καὶ τῶν Ἰουδαίων τοὺς συμμάχους παραλαβὼν ἐπὶ τὸν Ἰωνάθην ἧκεν, καὶ προσβαλὼν αὐτοῦ τοῖς ὀχυρώμασιν ἐπὶ πολλὰς αὐτὸν ἡμέρας ἐπολιόρκει."},{"number":28,"text":"ὁ δὲ πρὸς τὴν σπουδὴν τῆς πολιορκίας οὐκ ἐνδίδωσιν, ἀλλὰ καρτερῶς ἀντιστὰς Σίμωνα μὲν τὸν ἀδελφὸν ἐν τῇ πόλει καταλείπει τῷ Βακχίδῃ πολεμήσοντα, λάθρα δʼ αὐτὸς εἰς τὴν χώραν ἐξελθὼν καὶ συναγαγὼν χεῖρα πολλὴν παρὰ τῶν τὰ αὐτοῦ φρονούντων νυκτὸς ἐπιπίπτει τῷ τοῦ Βακχίδου στρατοπέδῳ καὶ συχνοὺς αὐτῶν διαφθείρας φανερὸς καὶ τἀδελφῷ Σίμωνι γίνεται τοῖς ἐχθροῖς ἐπιπεσών."},{"number":29,"text":"καὶ γὰρ οὗτος αἰσθόμενος ὑπʼ αὐτοῦ κτεινομένους τοὺς πολεμίους ἐπέξεισιν αὐτοῖς, καὶ τά τε μηχανήματα τὰ πρὸς τὴν πολιορκίαν ἐνέπρησε τῶν Μακεδόνων καὶ φόνον αὐτῶν ἱκανὸν εἰργάσατο."},{"number":30,"text":"θεασάμενος δʼ αὑτὸν ὁ Βακχίδης ὑπὸ τῶν ἐχθρῶν ἀπειλημμένον καὶ τοὺς μὲν ἔμπροσθεν αὐτῶν τοὺς δʼ ὄπισθεν προσκειμένους, εἰς ἀθυμίαν ἅμα καὶ ταραχὴν τῆς διανοίας ἐνέπεσεν τῷ παρʼ ἐλπίδας ἀποβάντι τῆς πολιορκίας συγχυθείς."},{"number":31,"text":"τὸν μέντοι γε ὑπὲρ τούτων θυμὸν εἰς τοὺς φυγάδας, οἳ μετεπέμψαντο παρὰ τοῦ βασιλέως αὐτόν, ἀπέσκηψεν ὡς ἐξηπατηκότας, ἐβούλετο δὲ τελευτήσας τὴν πολιορκίαν, εἰ δυνατόν, εὐπρεπῶς εἰς τὴν οἰκείαν ὑποστρέψαι."},{"number":32,"text":"Μαθὼν δʼ αὐτοῦ τὴν διάνοιαν Ἰωνάθης πρεσβεύεται πρὸς αὐτὸν περὶ φιλίας καὶ συμμαχίας, ὅπως ἀποδῶσιν ἀλλήλοις οὓς εἰλήφασιν αἰχμαλώτους ἑκάτεροι."},{"number":33,"text":"νομίσας δὲ ταύτην εὐπρεπεστάτην ὁ Βακχίδης τὴν ἀναχώρησιν σπένδεται πρὸς τὸν Ἰωνάθην φιλίαν, καὶ ὤμοσαν μὴ στρατεύσειν ἔτι κατʼ ἀλλήλων, καὶ τούς τε αἰχμαλώτους ἀποδοὺς καὶ τοὺς οἰκείους κομισάμενος ὑπέστρεψεν εἰς Ἀντιόχειαν πρὸς τὸν βασιλέα καὶ μετὰ ταύτην τὴν ἀναχώρησιν οὐκέτι εἰς τὴν Ἰουδαίαν ἐνέβαλεν."},{"number":34,"text":"ὁ δὲ Ἰωνάθης ταύτης τῆς ἀδείας λαβόμενος καὶ ποιούμενος ἐν Μαχμᾶ πόλει τὴν δίαιταν αὐτόθι τοῖς ὄχλοις διεῖπε τὰ πράγματα καὶ τοὺς πονηροὺς καὶ ἀσεβεῖς κολάζων ἐκάθηρεν οὕτως ἀπὸ τούτων τὸ ἔθνος."}],"2":[{"number":35,"text":"Ἔτει δʼ ἑξηκοστῷ καὶ ἑκατοστῷ τὸν Ἀντιόχου τοῦ Ἐπιφανοῦς υἱὸν Ἀλέξανδρον ἀναβάντα εἰς Συρίαν συνέβη καταλαβέσθαι Πτολεμαΐδα ἐκ προδοσίας τῶν ἔνδον στρατιωτῶν· ἀπεχθῶς γὰρ εἶχον πρὸς τὸν Δημήτριον διὰ τὴν ὑπερηφανίαν αὐτοῦ καὶ τὸ δυσέντευκτον."},{"number":36,"text":"ἀποκλείσας γὰρ αὑτὸν εἰς τετραπύργιόν τι βασίλειον, ὃ κατεσκεύασεν αὐτὸς οὐκ ἄπωθεν τῆς Ἀντιοχείας, οὐδένα προσίετο, ἀλλὰ περὶ τὰ πράγματα ῥάθυμος ἦν καὶ ὀλίγωρος, ὅθεν αὐτῷ καὶ μᾶλλον τὸ παρὰ τῶν ὑποτεταγμένων μῖσος ἐξήφθη, καθὼς ἤδη καὶ ἐν ἄλλοις δεδηλώκαμεν."},{"number":37,"text":"γενόμενον οὖν ἐν Πτολεμαΐδι τὸν Ἀλέξανδρον ἀκούσας ὁ Δημήτριος ἦγεν ἅπασαν ἀναλαβὼν ἐπʼ αὐτὸν τὴν δύναμιν. ἔπεμψεν δὲ καὶ πρὸς Ἰωνάθην πρέσβεις περὶ συμμαχίας καὶ εὐνοίας· φθάσαι γὰρ τὸν Ἀλέξανδρον διέγνω, μὴ προδιαλεχθεὶς ἐκεῖνος αὐτῷ σχῇ τὴν παρʼ αὐτοῦ βοήθειαν."},{"number":38,"text":"τοῦτο δʼ ἐποίει φοβηθείς, μὴ μνησικακήσας ὁ Ἰωνάθης αὐτῷ τῆς ἔχθρας συνεπιθῆται. προσέταξεν οὖν αὐτῷ συναθροίζειν δύναμιν καὶ κατασκευάζειν ὅπλα καὶ τοὺς ὁμήρους, οὓς τῶν Ἰουδαίων ἐνέκλεισε Βακχίδης ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων, ἀπολαβεῖν."},{"number":39,"text":"τοιούτων οὖν αὐτῷ τῶν παρὰ Δημητρίου προσπεσόντων ὁ Ἰωνάθης παραγενόμενος εἰς τὰ Ἱεροσόλυμα τὴν ἐπιστολὴν ἀνέγνω τοῦ βασιλέως ἀκουόντων τοῦ τε λαοῦ καὶ τῶν φρουρούντων τὴν ἀκρόπολιν."},{"number":40,"text":"ἀναγνωσθέντων δὲ τούτων οἱ ἀσεβεῖς καὶ φυγάδες οἱ ἐκ τῆς ἀκροπόλεως λίαν ἔδεισαν ἐπιτετροφότος Ἰωνάθῃ τοῦ βασιλέως στρατιὰν συλλέγειν καὶ τοὺς ὁμήρους ἀπολαβεῖν. ὁ δὲ τοῖς γονεῦσιν ἑκάστῳ τὸν ἴδιον ἀπέδωκεν."},{"number":41,"text":"καὶ οὕτως μὲν Ἰωνάθης ἐν Ἱεροσολύμοις τὴν μονὴν ἐποιεῖτο καινίζων τὰ κατὰ τὴν πόλιν καὶ πρὸς τὴν αὐτοῦ βούλησιν κατασκευάζων ἕκαστον. ἐκέλευσε γὰρ οἰκοδομηθῆναι καὶ τὰ τείχη τῆς πόλεως ἐκ λίθων τετραγώνων, ὡς ἂν ᾖ καὶ πρὸς τοὺς πολέμους ἀσφαλέστερα."},{"number":42,"text":"ταῦτα δʼ ὁρῶντες οἱ τῶν φρουρίων τῶν ἐν τῇ Ἰουδαίᾳ φύλακες ἐκλιπόντες αὐτὰ πάντες ἔφυγον εἰς Ἀντιόχειαν πάρεξ τῶν ἐν Βαιθσούρᾳ πόλει καὶ τῶν ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων· οὗτοι γὰρ ἡ πλείων μοῖρα τῶν ἀσεβῶν καὶ πεφευγότων Ἰουδαίων ἦσαν καὶ διὰ τοῦτο τὰς φρουρὰς οὐκ ἐγκατέλιπον."},{"number":43,"text":"Γνοὺς δὲ ὁ Ἀλέξανδρος τάς τε ὑποσχέσεις, ἃς ἐποιήσατο Δημήτριος πρὸς Ἰωνάθην, καὶ τὴν ἀνδρείαν αὐτοῦ καὶ ὁπόσα διέθηκεν πολεμῶν τοὺς Μακεδόνας καὶ πάλιν οἷα πεπονθὼς αὐτὸς εἴη ὑπὸ Δημητρίου καὶ Βακχίδου τοῦ Δημητρίου στρατηγοῦ, σύμμαχον οὐκ ἂν εὑρεῖν Ἰωνάθου ἀμείνω πρὸς τοὺς φίλους ἔλεγεν ἐν τῷ παρόντι καιρῷ, ὃς καὶ πρὸς τοὺς πολέμους ἐστὶν ἀνδρεῖος, καὶ μῖσος οἰκεῖον ἔχει πρὸς Δημήτριον πολλὰ πεπονθὼς ὑπʼ αὐτοῦ κακὰ καὶ πεποιηκώς."},{"number":44,"text":"εἰ τοιγαροῦν δοκεῖ φίλον ποιεῖσθαι αὐτὸν κατὰ Δημητρίου, νῦν ἐστιν οὐκ ἄλλοτε χρησιμώτερον παρακαλεῖν αὐτὸν ἐπὶ τὴν συμμαχίαν. δόξαν οὖν αὐτῷ καὶ τοῖς φίλοις πέμπειν πρὸς τὸν Ἰωνάθην γράφει τοιαύτην ἐπιστολήν·"},{"number":45,"text":"βασιλεὺς Ἀλέξανδρος Ἰωνάθῃ τῷ ἀδελφῷ χαίρειν. τὴν μὲν ἀνδρείαν σου καὶ πίστιν ἀκηκόαμεν πάλαι καὶ διὰ τοῦτο πεπόμφαμεν πρὸς σὲ περὶ φιλίας καὶ συμμαχίας. χειροτονοῦμεν δέ σε σήμερον ἀρχιερέα τῶν Ἰουδαίων καὶ φίλον ἐμὸν καλεῖσθαι. ἀπέσταλκά σοι καὶ δωρεὰς στολὴν πορφυρᾶν καὶ στέφανον χρύσεον καὶ παρακαλῶ τιμηθέντα ὑφʼ ἡμῶν ὅμοιον γίνεσθαι περὶ ἡμᾶς."},{"number":46,"text":"Δεξάμενος δὲ ὁ Ἰωνάθης τὴν ἐπιστολὴν ἐνδύεται μὲν τὴν ἱερατικὴν στολὴν τῆς σκηνοπηγίας ἐνστάσης μετὰ ἔτη τέσσαρα ἢ τὸν ἀδελφὸν αὐτοῦ Ἰούδαν ἀποθανεῖν· καὶ γὰρ οὐδὲ κατὰ τοῦτον τὸν χρόνον ἀρχιερεύς τις ἐγεγόνει· συνάγει δὲ δύναμιν πολλὴν καὶ πλῆθος ὅπλων ἐχάλκευεν."},{"number":47,"text":"Δημήτριον δὲ σφόδρα ταῦτʼ ἐλύπησεν μαθόντα καὶ τῆς βραδυτῆτος ἑαυτὸν ἐποίησεν αἰτιᾶσθαι, ὅτι μὴ προλαβὼν Ἀλέξανδρον αὐτὸς ἐφιλανθρωπεύσατο τὸν Ἰωνάθην, ἀλλʼ ἐκείνῳ καταλίποι καιρὸν εἰς τοῦτο. γράφει τοίνυν καὶ αὐτὸς ἐπιστολὴν τῷ Ἰωνάθῃ καὶ τῷ δήμῳ δηλοῦσαν τάδε·"},{"number":48,"text":"βασιλεὺς Δημήτριος Ἰωνάθῃ καὶ τῷ ἔθνει τῶν Ἰουδαίων χαίρειν. ἐπειδὴ διετηρήσατε τὴν πρὸς ἡμᾶς φιλίαν καὶ πειράσασιν ὑμᾶς τοῖς ἐμοῖς ἐχθροῖς οὐ προσέθεσθε, καὶ ταύτην μὲν ὑμῶν ἐπαινῶ τὴν πίστιν καὶ παρακαλῶ δὲ τοῖς αὐτοῖς ἐμμένειν ἀποληψομένους ἀμοιβὰς παρʼ ἡμῶν καὶ χάριτας."},{"number":49,"text":"τοὺς γὰρ πλείστους ὑμῶν ἀνήσω τῶν φόρων καὶ τῶν συντάξεων, ἃς ἐτελεῖτε τοῖς πρὸ ἐμοῦ βασιλεῦσιν καὶ ἐμοί, νῦν τε ὑμῖν ἀφίημι τοὺς φόρους, οὓς ἀεὶ παρέχετε. πρὸς τούτοις καὶ τὴν τιμὴν ὑμῖν χαρίζομαι τῶν ἁλῶν καὶ τῶν στεφάνων, οὓς προσεφέρετε ἡμῖν, καὶ ἀντὶ τῶν τρίτων τοῦ καρποῦ καὶ τοῦ ἡμίσους τοῦ ξυλίνου καρποῦ τὸ γινόμενον ἐμοὶ μέρος ὑμῖν ἀφίημι ἀπὸ τῆς σήμερον ἡμέρας."},{"number":50,"text":"καὶ ὑπὲρ κεφαλῆς ἑκάστης ὃ ἔδει μοι δίδοσθαι τῶν ἐν τῇ Ἰουδαίᾳ κατοικούντων καὶ τῶν τριῶν τοπαρχιῶν τῶν τῇ Ἰουδαίᾳ προσκειμένων Σαμαρείας καὶ Γαλιλαίας καὶ Περαίας, τούτους παραχωρῶ ὑμῖν ἀπὸ τοῦ νῦν εἰς τὸν ἅπαντα χρόνον."},{"number":51,"text":"καὶ τὴν Ἱεροσολυμιτῶν πόλιν ἱερὰν καὶ ἄσυλον εἶναι βούλομαι καὶ ἐλευθέραν ἕως τῶν ὅρων αὐτῆς ἀπὸ τῆς δεκάτης καὶ τῶν τελῶν. τὴν δὲ ἄκραν ἐπιτρέπω τῷ ἀρχιερεῖ ὑμῶν Ἰωνάθῃ, οὓς δʼ ἂν αὐτὸς δοκιμάσῃ πιστοὺς καὶ φίλους τούτους ἐν αὐτῇ φρουροὺς καταστῆσαι, ἵνα φυλάσσωσιν ἡμῖν αὐτήν."},{"number":52,"text":"καὶ Ἰουδαίων δὲ τοὺς αἰχμαλωτισθέντας καὶ δουλεύοντας ἐν τῇ ἡμετέρᾳ ἀφίημι ἐλευθέρους. κελεύω δὲ μηδὲ ἀγγαρεύεσθαι τὰ Ἰουδαίων ὑποζύγια· τὰ δὲ σάββατα καὶ ἑορτὴν ἅπασαν καὶ τρεῖς καὶ πρὸ τῆς ἑορτῆς ἡμέρας ἔστωσαν ἀτελεῖς."},{"number":53,"text":"τὸν αὐτὸν τρόπον καὶ τοὺς ἐν τῇ ἐμῇ κατοικοῦντας Ἰουδαίους ἐλευθέρους καὶ ἀνεπηρεάστους ἀφίημι, καὶ τοῖς στρατεύεσθαι μετʼ ἐμοῦ βουλομένοις ἐπιτρέπω καὶ μέχρις τρισμυρίων ἐξέστω τοῦτο· τῶν δʼ αὐτῶν, ὅποι ἂν ἀπίωσι, τεύξονται ὧν καὶ τὸ ἐμὸν στράτευμα μεταλαμβάνει. καταστήσω δʼ αὐτῶν οὓς μὲν εἰς τὰ φρούρια, τινὰς δὲ περὶ τὴν φυλακὴν τοὐμοῦ σώματος, καὶ ἡγεμόνας δὲ ποιήσω τῶν περὶ τὴν ἐμὴν αὐλήν."},{"number":54,"text":"ἐπιτρέπω δὲ καὶ τοῖς πατρῴοις χρῆσθαι νόμοις καὶ τούτους φυλάττειν, καὶ τοῖς τρισὶν τοῖς προσκειμένοις τῇ Ἰουδαίᾳ νομοῖς ὑποτάσσεσθαι βούλομαι, καὶ τῷ ἀρχιερεῖ δὲ ἐπιμελὲς εἶναι, ἵνα μηδὲ εἷς Ἰουδαῖος ἄλλο ἔχῃ ἱερὸν προσκυνεῖν ἢ μόνον τὸ ἐν Ἱεροσολύμοις."},{"number":55,"text":"δίδωμι δʼ ἐκ τῶν ἐμῶν καὶ εἰς τὴν δαπάνην τῶν θυσιῶν κατʼ ἔτος μυριάδας πεντεκαίδεκα, τὰ δὲ περισσεύοντα τῶν χρημάτων ὑμέτερα εἶναι βούλομαι· τὰς δὲ μυρίας δραχμάς, ἃς ἐλάμβανον ἐκ τοῦ ἱεροῦ οἱ βασιλεῖς, ὑμῖν ἀφίημι διὰ τὸ προσήκειν αὐτὰς τοῖς ἱερεῦσιν τοῖς λειτουργοῦσιν τῷ ἱερῷ."},{"number":56,"text":"καὶ ὅσοι δʼ ἂν φύγωσιν εἰς τὸ ἱερὸν τὸ ἐν Ἱεροσολύμοις καὶ εἰς τὰ ἀπʼ αὐτοῦ χρηματίζοντα ἢ βασιλικὰ ὀφείλοντες χρήματα ἢ διʼ ἄλλην αἰτίαν, ἀπολελύσθωσαν οὗτοι καὶ τὰ ὑπάρχοντα αὐτοῖς σῶα ἔστω."},{"number":57,"text":"ἐπιτρέπω δὲ καὶ ἀνακαινίζειν τὸ ἱερὸν καὶ οἰκοδομεῖν τῆς εἰς ταῦτα δαπάνης ἐκ τῶν ἐμῶν γινομένης, καὶ τὰ τείχη δὲ συγχωρῶ τὰ τῆς πόλεως οἰκοδομεῖσθαι καὶ πύργους ὑψηλοὺς ἐγείρειν καὶ ταῦτα ἐκ τῶν ἐμῶν ἀνιστᾶν πάντα. εἰ δέ τι καὶ φρούριόν ἐστιν, ὃ συμφέρει τῇ χώρᾳ τῇ Ἰουδαίων ὀχυρὸν εἶναι, καὶ τοῦτʼ ἐκ τῶν ἐμῶν κατασκευασθήτω."},{"number":58,"text":"Ταῦτα μὲν ὑπισχνούμενος καὶ χαριζόμενος ἔγραψεν τοῖς Ἰουδαίοις Δημήτριος. Ἀλέξανδρος δὲ ὁ βασιλεὺς δύναμιν μεγάλην συναγαγὼν μισθοφόρων καὶ τῶν προσθεμένων ἐκ τῆς Συρίας αὐτῷ στρατιωτῶν ἐπὶ τὸν Δημήτριον ἐστράτευσεν."},{"number":59,"text":"καὶ μάχης γενομένης τὸ μὲν εὐώνυμον κέρας τοῦ Δημητρίου τρέπεται τοὺς ἐναντίους εἰς φυγὴν καὶ ἐδίωξεν ἄχρι πολλοῦ κτείνει τε συχνοὺς αὐτῶν καὶ διαρπάζει τὸ στρατόπεδον, τὸ δὲ δεξιόν, οὗ συνέβαινεν εἶναι τὸν Δημήτριον, ἡττᾶται."},{"number":60,"text":"καὶ οἱ μὲν ἄλλοι πάντες ἔφυγον, Δημήτριος δὲ γενναίως μαχόμενος οὐκ ὀλίγους μὲν ἀναιρεῖ τῶν πολεμίων, διώκων δὲ τοὺς ἄλλους ἐλαύνει τὸν ἵππον εἰς τέλμα βαθὺ καὶ δυσεκπόρευτον, ἔνθα συνέβη πεσόντος αὐτῷ τοῦ ἵππου μὴ δυνάμενον διαφυγεῖν ἀναιρεθῆναι."},{"number":61,"text":"τὸ γὰρ συμβεβηκὸς περὶ αὐτὸν ἰδόντες οἱ πολέμιοι ἀνέστρεψαν καὶ κυκλωσάμενοι τὸν Δημήτριον πάντες ἐπʼ αὐτὸν ἠκόντιζον. ὁ δὲ πεζὸς ὢν γενναίως ἀπεμάχετο, καὶ τελευταῖον τραύματα λαβὼν πολλὰ καὶ μηκέτʼ ἀντέχειν δυνάμενος κατέπεσεν. καὶ τέλος μὲν τοιοῦτον τὸν Δημήτριον κατέλαβεν ἔτη βασιλεύσαντα ἕνδεκα, ὡς καὶ ἐν ἄλλοις δεδηλώκαμεν."}],"3":[{"number":62,"text":"Ὁ δὲ Ὀνίου τοῦ ἀρχιερέως υἱὸς ὁμώνυμος δὲ ὢν τῷ πατρί, ὃς ἐν Ἀλεξανδρείᾳ φυγὼν πρὸς τὸν βασιλέα Πτολεμαῖον τὸν ἐπικαλούμενον Φιλομήτορα διῆγεν, ὡς καὶ πρότερον εἰρήκαμεν, ἰδὼν τὴν Ἰουδαίαν κακουμένην ὑπὸ τῶν Μακεδόνων καὶ τῶν βασιλέων αὐτῶν,"},{"number":63,"text":"βουλόμενος αὑτῷ δόξαν καὶ μνήμην αἰώνιον κατασκευάσαι, διέγνω πέμψας πρὸς Πτολεμαῖον τὸν βασιλέα καὶ τὴν βασίλισσαν Κλεοπάτραν αἰτήσασθαι παρʼ αὐτῶν ἐξουσίαν, ὅπως οἰκοδομήσειεν ναὸν ἐν Αἰγύπτῳ παραπλήσιον τῷ ἐν Ἱεροσολύμοις καὶ Λευίτας καὶ ἱερεῖς ἐκ τοῦ ἰδίου γένους καταστήσῃ."},{"number":64,"text":"τοῦτο δʼ ἐβούλετο θαρρῶν μάλιστα τῷ προφήτῃ Ἡσαΐᾳ, ὃς ἔμπροσθεν ἔτεσιν ἑξακοσίοις πλέον γεγονὼς προεῖπεν, ὡς δεῖ πάντως ἐν Αἰγύπτῳ οἰκοδομηθῆναι ναὸν τῷ μεγίστῳ θεῷ ὑπʼ ἀνδρὸς Ἰουδαίου. διὰ ταῦτα οὖν ἐπηρμένος Ὀνίας γράφει Πτολεμαίῳ καὶ Κλεοπάτρᾳ τοιαύτην ἐπιστολήν·"},{"number":65,"text":"πολλὰς καὶ μεγάλας ὑμῖν χρείας τετελεκὼς ἐν τοῖς κατὰ πόλεμον ἔργοις μετὰ τῆς τοῦ θεοῦ βοηθείας, καὶ γενόμενος ἔν τε τῇ κοίλῃ Συρίᾳ καὶ Φοινίκῃ, καὶ εἰς Λεόντων δὲ πόλιν τοῦ Ἡλιοπολίτου σὺν τοῖς Ἰουδαίοις καὶ εἰς ἄλλους τόπους ἀφικόμενος τοῦ ἔθνους,"},{"number":66,"text":"καὶ πλείστους εὑρὼν παρὰ τὸ καθῆκον ἔχοντας ἱερὰ καὶ διὰ τοῦτο δύσνους ἀλλήλοις, ὃ καὶ Αἰγυπτίοις συμβέβηκεν διὰ τὸ πλῆθος τῶν ἱερῶν καὶ τὸ περὶ τὰς θρησκείας οὐχ ὁμόδοξον, ἐπιτηδειότατον εὑρὼν τόπον ἐν τῷ προσαγορευομένῳ τῆς ἀγρίας Βουβάστεως ὀχυρώματι βρύοντα ποικίλης ὕλης καὶ τῶν ἱερῶν ζῴων μεστόν,"},{"number":67,"text":"δέομαι συγχωρῆσαί μοι τὸ ἀδέσποτον ἀνακαθάραντι ἱερὸν καὶ συμπεπτωκὸς οἰκοδομῆσαι ναὸν τῷ μεγίστῳ θεῷ καθʼ ὁμοίωσιν τοῦ ἐν Ἱεροσολύμοις αὐτοῖς μέτροις ὑπὲρ σοῦ καὶ τῆς σῆς γυναικὸς καὶ τῶν τέκνων, ἵνʼ ἔχωσιν οἱ τὴν Αἴγυπτον κατοικοῦντες Ἰουδαῖοι εἰς αὐτὸ συνιόντες κατὰ τὴν πρὸς ἀλλήλους ὁμόνοιαν ταῖς σαῖς ἐξυπηρετεῖν χρείαις·"},{"number":68,"text":"καὶ γὰρ Ἡσαΐας ὁ προφήτης τοῦτο προεῖπεν· ἔσται θυσιαστήριον ἐν Αἰγύπτῳ κυρίῳ τῷ θεῷ· καὶ πολλὰ δὲ προεφήτευσεν ἄλλα τοιαῦτα διὰ τὸν τόπον."},{"number":69,"text":"Καὶ ταῦτα μὲν ὁ Ὀνίας τῷ βασιλεῖ Πτολεμαίῳ γράφει. κατανοήσειε δʼ ἄν τις αὐτοῦ τὴν εὐσέβειαν καὶ Κλεοπάτρας τῆς ἀδελφῆς αὐτοῦ καὶ γυναικὸς ἐξ ἧς ἀντέγραψαν ἐπιστολῆς· τὴν γὰρ ἁμαρτίαν καὶ τὴν τοῦ νόμου παράβασιν εἰς τὴν Ὀνίου κεφαλὴν ἀνέθεσαν·"},{"number":70,"text":"ἀντέγραψαν γὰρ οὕτως· βασιλεὺς Πτολεμαῖος καὶ βασίλισσα Κλεοπάτρα Ὀνίᾳ χαίρειν. ἀνέγνωμέν σου τὴν ἐπιστολὴν ἀξιοῦντος ἐπιτραπῆναί σοι τὸ ἐν Λεόντων πόλει τοῦ Ἡλιοπολίτου ἱερὸν συμπεπτωκὸς ἀνακαθᾶραι, προσαγορευόμενον δὲ τῆς ἀγρίας Βουβάστεως. διὸ καὶ θαυμάζομεν, εἰ ἔσται τῷ θεῷ κεχαρισμένον τὸ καθιδρυσόμενον ἱερὸν ἐν ἀσελγεῖ τόπῳ καὶ πλήρει ζῴων ἱερῶν."},{"number":71,"text":"ἐπεὶ δὲ σὺ φῂς Ἡσαΐαν τὸν προφήτην ἐκ πολλοῦ χρόνου τοῦτο προειρηκέναι, συγχωροῦμέν σοι, εἰ μέλλει τοῦτʼ ἔσεσθαι κατὰ τὸν νόμον· ὥστε μηδὲν ἡμᾶς δοκεῖν εἰς τὸν θεὸν ἐξημαρτηκέναι."},{"number":72,"text":"Λαβὼν οὖν τὸν τόπον ὁ Ὀνίας κατεσκεύασεν ἱερὸν καὶ βωμὸν τῷ θεῷ ὅμοιον τῷ ἐν Ἱεροσολύμοις, μικρότερον δὲ καὶ πενιχρότερον. τὰ δὲ μέτρα αὐτοῦ καὶ τὰ σκεύη νῦν οὐκ ἔδοξέ μοι δηλοῦν· ἐν γὰρ τῇ ἑβδόμῃ μου βίβλῳ τῶν Ἰουδαϊκῶν ἀναγέγραπται."},{"number":73,"text":"εὗρεν δὲ Ὀνίας καὶ Ἰουδαίους τινὰς ὁμοίους αὐτῷ ἱερεῖς καὶ Λευίτας τοὺς ἐκεῖ θρησκεύσοντας. ἀλλὰ περὶ μὲν τοῦ ἱεροῦ τούτου ἀρκούντως ἡμῖν δεδήλωται."},{"number":74,"text":"Τοὺς δʼ ἐν Ἀλεξανδρείᾳ Ἰουδαίους καὶ Σαμαρεῖς, οἳ τὸ ἐν Γαριζεὶν προσεκύνουν ἱερόν, κατὰ τοὺς Ἀλεξάνδρου χρόνους συνέβη στασιάσαι πρὸς ἀλλήλους, καὶ περὶ τῶν ἱερῶν ἐπʼ αὐτοῦ Πτολεμαίου διεκρίνοντο, τῶν μὲν Ἰουδαίων λεγόντων κατὰ τοὺς Μωυσέος νόμους ᾠκοδομῆσθαι τὸ ἐν Ἱεροσολύμοις, τῶν δὲ Σαμαρέων τὸ ἐν Γαριζείν."},{"number":75,"text":"παρεκάλεσάν τε σὺν τοῖς φίλοις καθίσαντα τὸν βασιλέα τοὺς περὶ τούτων ἀκοῦσαι λόγους καὶ τοὺς ἡττηθέντας θανάτῳ ζημιῶσαι. τὸν μὲν οὖν ὑπὲρ τῶν Σαμαρέων λόγον Σαββαῖος ἐποιήσατο καὶ Θεοδόσιος, τοὺς δʼ ὑπὲρ τῶν Ἱεροσολυμιτῶν καὶ Ἰουδαίων Ἀνδρόνικος ὁ Μεσαλάμου."},{"number":76,"text":"ὤμοσαν δὲ τὸν θεὸν καὶ τὸν βασιλέα ἦ μὴν ποιήσεσθαι τὰς ἀποδείξεις κατὰ τὸν νόμον, παρεκάλεσάν τε τὸν Πτολεμαῖον, ὅπως ὃν ἂν λάβῃ παραβαίνοντα τοὺς ὅρκους ἀποκτείνῃ. ὁ μὲν οὖν βασιλεὺς πολλοὺς τῶν φίλων εἰς συμβουλίαν παραλαβὼν ἐκάθισεν ἀκουσόμενος τῶν λεγόντων."},{"number":77,"text":"οἱ δʼ ἐν τῇ Ἀλεξανδρείᾳ τυγχάνοντες Ἰουδαῖοι σφόδρα ἠγωνίων περὶ τῶν ἀνδρῶν, οἷς ἀγανακτεῖν περὶ τοῦ ἐν τοῖς Ἱεροσολύμοις συνέβαινεν ἱεροῦ· χαλεπῶς γὰρ ἔφερον, εἰ τοῦτό τινες καταλύσουσιν οὕτως ἀρχαῖον καὶ διασημότατον τῶν κατὰ τὴν οἰκουμένην ὑπάρχον."},{"number":78,"text":"τοῦ δὲ Σαββαίου καὶ Θεοδοσίου συγχωρησάντων τῷ Ἀνδρονίκῳ πρώτῳ ποιήσασθαι τοὺς λόγους, ἤρξατο τῶν ἀποδείξεων ἐκ τοῦ νόμου καὶ τῶν διαδοχῶν τῶν ἀρχιερέων, ὡς ἕκαστος παρὰ πατρὸς τὴν τιμὴν ἐκδεξάμενος ἦρξε τοῦ ναοῦ, καὶ ὅτι πάντες οἱ τῆς Ἀσίας βασιλεῖς τὸ ἱερὸν ἐτίμησαν ἀναθήμασιν καὶ λαμπροτάταις δωρεαῖς, τοῦ δʼ ἐν Γαριζεὶν ὡς οὐδὲ ὄντος οὐδεὶς λόγον οὐδʼ ἐπιστροφὴν ἐποιήσατο."},{"number":79,"text":"ταῦτα λέγων Ἀνδρόνικος καὶ πολλὰ τούτοις ὅμοια πείθει τὸν βασιλέα κρῖναι μὲν κατὰ τοὺς Μωυσέος νόμους οἰκοδομηθῆναι τὸ ἐν Ἱεροσολύμοις ἱερόν, ἀποκτεῖναι δὲ τοὺς περὶ τὸν Σαββαῖον καὶ Θεοδόσιον. καὶ τὰ μὲν γενόμενα τοῖς ἐν Ἀλεξανδρείᾳ Ἰουδαίοις κατὰ Πτολεμαῖον τὸν Φιλομήτορα ταῦτα ἦν."}],"4":[{"number":80,"text":"Δημητρίου δʼ ἀποθανόντος ἐν τῇ μάχῃ, καθὼς ἐπάνω δεδηλώκαμεν, Ἀλέξανδρος τὴν τῆς Συρίας παραλαβὼν βασιλείαν γράφει τῷ Φιλομήτορι Πτολεμαίῳ μνηστευόμενος αὐτοῦ πρὸς γάμον τὴν θυγατέρα, δίκαιον εἶναι λέγων τῷ τὴν πατρῴαν ἀρχὴν κομισαμένῳ καὶ διὰ τὴν τοῦ θεοῦ πρόνοιαν εἰς αὐτὴν προαχθέντι καὶ κρατήσαντι Δημητρίου καὶ μηδὲ τἆλλα ἐσομένῳ τῆς πρὸς αὐτὸν οἰκειότητος ἀναξίῳ συνάψαι συγγένειαν."},{"number":81,"text":"Πτολεμαῖος δὲ προσδεξάμενος ἡδέως τὴν μνηστείαν ἀντιγράφει χαίρειν τε λέγων ἐπὶ τῷ τὴν ἀρχὴν αὐτῷ πατρῴαν οὖσαν ἀπειληφέναι, καὶ τὴν θυγατέρα δώσειν ὑπισχνεῖται, ἀπαντᾶν δʼ αὐτὸν εἰς Πτολεμαΐδα τὴν θυγατέρα μέλλοντι ἄγειν ἐκέλευσεν· αὐτὸς γὰρ αὐτὴν μέχρι ταύτης παραπέμψειν ἀπʼ Αἰγύπτου κἀκεῖ συνοικίσειν αὐτῷ τὴν παῖδα."},{"number":82,"text":"καὶ Πτολεμαῖος μὲν ταῦτα γράψας παραγίνεται μετὰ σπουδῆς εἰς Πτολεμαΐδα καὶ Κλεοπάτραν ἄγων τὴν θυγατέρα. εὑρὼν δʼ ἐκεῖ τὸν Ἀλέξανδρον καθὼς ἐπέστειλεν προαπηντηκότα δίδωσιν αὐτῷ τὴν παῖδα καὶ φερνὴν ἄργυρόν τε καὶ χρυσὸν ὅσον εἰκὸς ἦν δοῦναι βασιλέα."},{"number":83,"text":"Τῶν δὲ γάμων ἐπιτελουμένων Ἀλέξανδρος Ἰωνάθῃ τῷ ἀρχιερεῖ γράψας ἐκέλευσεν αὐτὸν ἥκειν εἰς Πτολεμαΐδα. παραγενόμενος δὲ πρὸς τοὺς βασιλέας καὶ δωρησάμενος αὐτοὺς λαμπρᾶς τῆς παρʼ ἀμφοτέρων ἀπέλαυσε τιμῆς."},{"number":84,"text":"Ἀλέξανδρος δʼ αὐτὸν ἠνάγκασεν καὶ ἀποδυσάμενον τὴν οἰκείαν ἐσθῆτα λαβεῖν πορφύραν, καὶ συγκαθεσθῆναι ποιήσας αὐτὸν ἐπὶ τοῦ βήματος προσέταξεν τοὺς ἡγεμόνας εἰς μέσην μετʼ αὐτοῦ προελθόντας τὴν πόλιν κηρῦξαι, μηδενὶ κατʼ αὐτοῦ λέγειν ἐφεῖσθαι μηδὲ παρέχειν αὐτῷ πράγματα."},{"number":85,"text":"τοῦτο δὲ ποιησάντων τῶν ἡγεμόνων ὁρῶντες τὴν παρὰ τοῦ βασιλέως κεκηρυγμένην Ἰωνάθῃ τιμὴν οἱ κατηγορεῖν παρεσκευασμένοι καὶ πρὸς αὐτὸν ἀπεχθῶς ἔχοντες ἀπέδρασαν, μὴ καὶ προσλάβωσίν τι κακὸν δεδιότες. τοσαύτῃ δὲ σπουδῇ περὶ τὸν Ἰωνάθην ὁ βασιλεὺς Ἀλέξανδρος ἐχρῆτο, ὥστʼ αὐτὸν καὶ πρῶτον ἀναγράψαι τῶν φίλων."},{"number":86,"text":"Ἔτει δὲ πέμπτῳ καὶ ἑξηκοστῷ πρὸς τοῖς ἑκατὸν Δημήτριος ὁ Δημητρίου μετὰ πολλῶν μισθοφόρων, οὓς παρέσχεν αὐτῷ Λασθένης ὁ Κρής, ἄρας ἀπὸ τῆς Κρήτης κατέπλευσεν εἰς Κιλικίαν."},{"number":87,"text":"τοῦτο δὲ Ἀλέξανδρον ἀκούσαντα εἰς ἀγωνίαν καὶ ταραχὴν ἐνέβαλεν καὶ παραχρῆμα ἐκ τῆς Φοινίκης εἰς Ἀντιόχειαν ἔσπευσεν, ἵνα τὰ ἐκεῖ πρὶν ἢ Δημήτριον ἐλθεῖν ἀσφαλῶς θῆται."},{"number":88,"text":"κατέλιπεν δὲ τῆς κοίλης Συρίας Ἀπολλώνιον τὸν Τάον ἡγεμόνα, ὃς μετὰ πολλῆς δυνάμεως εἰς Ἰάμνειαν ἐλθὼν ἔπεμψε πρὸς Ἰωνάθην τὸν ἀρχιερέα, λέγων ἄδικον εἶναι μόνον αὐτὸν ἐπʼ ἀδείας ζῆν καὶ μετὰ ἐξουσίας οὐχ ὑποτασσόμενον τῷ βασιλεῖ· τοῦτο δʼ αὐτῷ παρὰ πάντων ὄνειδος φέρειν, ὅτι μὴ ὑποτάξειεν αὐτὸν τῷ βασιλεῖ."},{"number":89,"text":"μὴ τοίνυν σαυτὸν ἐν τοῖς ὄρεσιν καθήμενος ἐξαπάτα νομίζων ἰσχὺν ἔχειν, ἀλλʼ εἰ θαρρεῖς τῇ σαυτοῦ δυνάμει καταβὰς εἰς τὸ πεδίον τῇ ἡμετέρᾳ στρατιᾷ συγκρίθητι, καὶ τὸ τέλος τῆς νίκης ἐπιδείξει τὸν ἀνδρειότατον."},{"number":90,"text":"ἴσθι μέντοι γε τοὺς ἀρίστους ἐξ ἑκάστης πόλεως ἐμοὶ συστρατεύεσθαι· καὶ γὰρ δὴ τοὺς σοὺς προγόνους οἱ ἀεὶ νικῶντές εἰσιν οὗτοι. ποιήσῃ δὲ τὸν πρὸς ἡμᾶς ἀγῶνα ἐν τοιαύτῃ γῇ, ἐν ᾗ λίθοις οὐκ ἔστιν ἀλλʼ ὅπλοις ἀμύνασθαι οὐδὲ τόπος εἰς ὃν ἡττώμενος φεύξῃ."},{"number":91,"text":"Παροξυνθεὶς δʼ ἐπὶ τούτοις ὁ Ἰωνάθης μυρίους ἐπιλεξάμενος στρατιώτας ὥρμησεν ἐξ Ἱεροσολύμων μετὰ καὶ Σίμωνος τἀδελφοῦ, καὶ γενόμενος ἐν Ἰόππῃ στρατοπεδεύεται τῆς πόλεως ἔξω τῶν Ἰοππηνῶν ἀποκλεισάντων αὐτῷ τὰς πύλας· φρουρὰν γὰρ ἔνδον εἶχον ὑπὸ Ἀπολλωνίου κατασταθεῖσαν."},{"number":92,"text":"τοῦ δὲ Ἰωνάθου πρὸς πολιορκίαν αὐτῶν παρασκευαζομένου, φοβηθέντες μὴ τὴν πόλιν αὐτῶν ἐξέλῃ κατὰ κράτος ἀνοίγουσιν αὐτῷ τὰς πύλας. ὁ δὲ Ἀπολλώνιος ἀκούσας τὴν Ἰόππην κατειλημμένην ὑπὸ τοῦ Ἰωνάθου τρισχιλίους ἱππεῖς παραλαβὼν καὶ πεζοὺς ὀκτακισχιλίους εἰς Ἄζωτον ἦλθεν κἀκεῖθεν ἄρας ἠρέμα καὶ βάδην ἐποιεῖτο τὴν πορείαν, ἐλθὼν δʼ εἰς τὴν Ἰόππην ἀναχωρῶν ἕλκει τὸν Ἰωνάθην εἰς τὸ πεδίον τῇ ἵππῳ καταφρονῶν καὶ τὰς τῆς νίκης ἐλπίδας ἔχων ἐν αὐτῇ."},{"number":93,"text":"προελθὼν δʼ Ἰωνάθης ἐδίωκεν εἰς Ἄζωτον τὸν Ἀπολλώνιον. ὁ δʼ, ὡς ἐν τῷ πεδίῳ συνέβη γενέσθαι τὸν πολέμιον, ὑποστρέψας εἰς μάχην αὐτῷ συνέβαλεν."},{"number":94,"text":"τοῦ δʼ Ἀπολλωνίου χιλίους ἱππεῖς καθίσαντος εἰς ἐνέδραν ἔν τινι χειμάρρῳ, ὡς ἂν κατόπιν ἐπιφανεῖεν τοῖς πολεμίοις, αἰσθόμενος ὁ Ἰωνάθης οὐ κατεπλάγη· τάξας δὲ τὴν στρατιὰν ἐν πλινθίῳ κατʼ ἀμφότερα τοὺς πολεμίους ἀμύνασθαι παρεσκευάσατο, καὶ κατὰ πρόσωπον καὶ τοῖς ὄπισθεν ἐπελευσομένοις αὑτὸν ἀντιτάξας."},{"number":95,"text":"τῆς δὲ μάχης ἕως ἑσπέρας προβαινούσης, δοὺς Σίμωνι τἀδελφῷ μέρος τῆς δυνάμεως τοῦτον μὲν ἐκέλευσε συμβαλεῖν τῇ φάλαγγι τῶν ἐχθρῶν, αὐτὸς δὲ τοὺς σὺν αὐτῷ προσέταξεν φραξαμένους τοῖς ὅπλοις ἀποδέχεσθαι τὰ βέλη τὰ παρὰ τῶν ἱππέων."},{"number":96,"text":"καὶ οἱ μὲν ἐποίησαν τὸ κελευσθέν, οἱ δὲ τῶν πολεμίων ἱππεῖς ἐπʼ αὐτοὺς ἀφέντες τὰ βέλη μέχρι καὶ ἐξεκενώθησαν οὐδὲν αὐτοὺς ἔβλαπτον· οὐ γὰρ διικνεῖτο τῶν σωμάτων τὰ βαλλόμενα, συμπεφραγμένοις δὲ ταῖς ἀσπίσιν συνηνωμέναις ὑπὸ πυκνότητος ἐπαφιέμενα ῥᾳδίως ἐκρατεῖτο καὶ ἄπρακτα ἐφέρετο."},{"number":97,"text":"ὡς δὲ παρείθησαν ἀπὸ πρωῒ μέχρι δείλης ὀψίας ἀκοντίζοντες εἰς αὐτοὺς οἱ πολέμιοι, νοήσας Σίμων κεκμηκότας αὐτοὺς συμβάλλει τῇ φάλαγγι, καὶ προθυμίᾳ χρησαμένων πολλῇ τῶν στρατιωτῶν αὐτοῦ τρέπει τοὺς ἐχθροὺς εἰς φυγήν."},{"number":98,"text":"θεασάμενοι δὲ τοὺς πεζοὺς φεύγοντας οἱ ἱππεῖς οὐδʼ αὐτοὶ μένουσιν, ἀλλὰ πάρετοι μὲν ὄντες αὐτοὶ διὰ τὸ μέχρι δείλης μάχεσθαι, τῆς δὲ παρὰ τῶν πεζῶν ἐλπίδος αὐτοῖς ἀπολωλυίας, ἀκόσμως καὶ συγκεχυμένως ἔφευγον, ὡς διασχισθέντας αὐτοὺς διὰ παντὸς σκορπισθῆναι τοῦ πεδίου."},{"number":99,"text":"διώκων δʼ αὐτοὺς Ἰωνάθης μέχρι τῆς Ἀζώτου καὶ πολλοὺς ἀναιρῶν ἀπογνόντας τῆς σωτηρίας ἠνάγκασεν ἐπὶ τὸν τοῦ Δαγῶνος ναὸν καταφυγεῖν, ὃς ἦν ἐν Ἀζώτῳ. λαβὼν δʼ ἐξ ἐπιδρομῆς Ἰωνάθης τὴν πόλιν αὐτήν τε ἐνέπρησεν καὶ τὰς περὶ αὐτὴν κώμας."},{"number":100,"text":"ἀπέσχετο δʼ οὐδὲ τοῦ Δαγῶνος ἱεροῦ, ἀλλὰ καὶ τοῦτʼ ἐνέπρησεν καὶ τοὺς εἰς αὐτὸ συμφυγόντας διέφθειρεν. τὸ δὲ πᾶν πλῆθος τῶν ἐν τῇ μάχῃ πεσόντων καὶ καταφλεγέντων ἐν τῷ ἱερῷ τῶν πολεμίων ἦσαν ὀκτακισχίλιοι."},{"number":101,"text":"κρατήσας οὖν τοσαύτης δυνάμεως ἄρας ἀπὸ τῆς Ἀζώτου εἰς Ἀσκάλωνα παραγίνεται, καὶ καταστρατοπεδεύσαντος ἔξω τῆς πόλεως αὐτοῦ προῆλθον εἰς ἀπάντησιν αὐτῷ οἱ Ἀσκαλωνῖται ξένια προσφέροντες αὐτῷ καὶ τιμῶντες. ὁ δὲ ἀποδεξάμενος αὐτοὺς τῆς προαιρέσεως ἀνέστρεψεν ἐκεῖθεν εἰς Ἱεροσόλυμα πολλὴν ἐπαγόμενος λείαν, ἣν ἔλαβεν νικήσας τοὺς πολεμίους."},{"number":102,"text":"Ἀλέξανδρος δʼ ἀκούσας ἡττημένον τὸν αὐτοῦ στρατηγὸν Ἀπολλώνιον προσεποιεῖτο χαίρειν, ὅτι παρὰ τὴν αὐτοῦ γνώμην Ἰωνάθῃ συνέβαλεν φίλῳ ὄντι καὶ συμμάχῳ, καὶ πέμπει πρὸς Ἰωνάθην μαρτυρῶν αὐτῷ καὶ γέρα καὶ τιμὰς διδοὺς πόρπην χρυσέαν, ὡς ἔστιν ἔθος δίδοσθαι τοῖς τῶν βασιλέων συγγενέσιν, καὶ τὴν Ἀκκάρωνα καὶ τὴν τοπαρχίαν αὐτῆς εἰς κληρουχίαν ἐπιτρέπει."},{"number":103,"text":"Ὑπὸ δὲ τοῦτον τὸν καιρὸν καὶ βασιλεὺς Πτολεμαῖος ὁ Φιλομήτωρ ἐπικληθεὶς ναυτικὴν ἄγων δύναμιν καὶ πεζὴν εἰς Συρίαν ἧκεν συμμαχήσων Ἀλεξάνδρῳ· γαμβρὸς γὰρ ἦν αὐτοῦ."},{"number":104,"text":"καὶ πᾶσαι προθύμως αὐτὸν αἱ πόλεις Ἀλεξάνδρου κελεύσαντος ἐκδεχόμεναι παρέπεμπον ἕως Ἀζώτου πόλεως, ἔνθα πάντες κατεβόων αὐτοῦ περὶ τοῦ ἐμπεπρησμένου ἱεροῦ αὐτῶν Δαγῶνος κατηγοροῦντες Ἰωνάθου τοῦτο ἀφανίσαντος καὶ τὴν χώραν πυρπολήσαντος καὶ πολλοὺς αὐτῶν ἀποκτείναντος."},{"number":105,"text":"καὶ Πτολεμαῖος μὲν ταῦτʼ ἀκούσας ἡσύχασεν, Ἰωνάθης δὲ εἰς Ἰόππην ἀπαντήσας Πτολεμαίῳ ξενίων τε λαμπρῶν παρʼ αὐτοῦ τυγχάνει καὶ τιμῆς ἁπάσης, ἔπειτα προπέμψας αὐτὸν ἕως τοῦ Ἐλευθέρου καλουμένου ποταμοῦ πάλιν ὑπέστρεψεν εἰς Ἱεροσόλυμα."},{"number":106,"text":"Γενόμενος δʼ ἐν Πτολεμαΐδι παρὰ πᾶσαν προσδοκίαν μικροῦ διεφθάρη Πτολεμαῖος ἐπιβουλευθεὶς ὑπὸ Ἀλεξάνδρου διʼ Ἀμμωνίου, ὃς ἐτύγχανεν αὐτῷ φίλος ὤν."},{"number":107,"text":"φανερᾶς δὲ τῆς ἐπιβουλῆς γενομένης Πτολεμαῖος γράφει τῷ Ἀλεξάνδρῳ πρὸς κόλασιν ἐξαιτῶν τὸν Ἀμμώνιον, ἐπιβουλευθῆναι λέγων ὑπʼ αὐτοῦ καὶ δίκην διὰ τοῦτʼ αὐτὸν ὑποσχεῖν ἀξιῶν. οὐκ ἐκδιδόντος δὲ τοῦ Ἀλεξάνδρου συνεὶς αὐτὸν ἐκεῖνον εἶναι τὸν ἐπιβουλεύσαντα χαλεπῶς διετέθη πρὸς αὐτόν."},{"number":108,"text":"τοῖς δὲ Ἀντιοχεῦσιν καὶ πρότερον ἦν προσκεκρουκὼς Ἀλέξανδρος διὰ τὸν Ἀμμώνιον· πολλὰ γὰρ ὑπʼ αὐτοῦ πεπόνθεισαν κακά. τιμωρίαν μέντοι τῶν τετολμημένων Ἀμμώνιος ὑπέσχεν κατασφαγεὶς αἰσχρῶς ὡς γυνή, κρύπτειν ἑαυτὸν σπουδάσας στολῇ γυναικείῳ, καθὼς ἐν ἄλλοις δεδηλώκαμεν."},{"number":109,"text":"Πτολεμαῖος δὲ μεμψάμενος αὑτὸν τοῦ τε συνοικίσαι τὴν θυγατέρα Ἀλεξάνδρῳ τῆς τε συμμαχίας τῆς κατὰ Δημητρίου διαλύεται τὴν πρὸς αὐτὸν συγγένειαν·"},{"number":110,"text":"ἀποσπάσας γὰρ τὴν θυγατέρα πέμπει πρὸς Δημήτριον εὐθὺς περὶ συμμαχίας καὶ φιλίας συντιθέμενος, τήν τε θυγατέρα δώσειν αὐτῷ ὑπισχνούμενος γυναῖκα καὶ καταστήσειν αὐτὸν εἰς τὴν πατρῴαν ἀρχήν. ὁ δὲ Δημήτριος ἡσθεὶς τοῖς πεπρεσβευμένοις δέχεται τὴν συμμαχίαν καὶ τὸν γάμον."},{"number":111,"text":"ἓν δʼ ἔτι Πτολεμαίῳ τὸ λοιπὸν ἀγώνισμα ὑπελείπετο πεῖσαι τοὺς Ἀντιοχεῖς δέξασθαι Δημήτριον ἀπεχθῶς πρὸς αὐτὸν διακειμένους ὑπὲρ ὧν ὁ πατὴρ αὐτοῦ Δημήτριος εἰς αὐτοὺς παρηνόμησεν. κατεπράξατο δὲ καὶ τοῦτο·"},{"number":112,"text":"μισοῦντες γὰρ τὸν Ἀλέξανδρον οἱ Ἀντιοχεῖς διὰ τὸν Ἀμμώνιον, ὡς δεδηλώκαμεν, ῥᾳδίως αὐτὸν ἐκ τῆς Ἀντιοχείας ἐξέβαλον. καὶ ὁ μὲν ἐκπεσὼν τῆς Ἀντιοχείας ἦλθεν εἰς Κιλικίαν."},{"number":113,"text":"ἐλθὼν δὲ πρὸς τοὺς Ἀντιοχεῖς Πτολεμαῖος βασιλεὺς ὑπʼ αὐτῶν καὶ τῶν στρατευμάτων ἀναδείκνυται καὶ ἀναγκασθεὶς δύο περιτίθεται διαδήματα, ἓν μὲν τὸ τῆς Ἀσίας, ἕτερον δὲ τὸ τῆς Αἰγύπτου."},{"number":114,"text":"χρηστὸς δὲ ὢν φύσει καὶ δίκαιος καὶ τῶν λαμπρῶν οὐκ ἐφιέμενος πρὸς δὲ τούτοις καὶ λογίσασθαι τὰ μέλλοντα συνετός, φείσασθαι τοῦ μὴ δόξαι εἶναι Ῥωμαίοις ἐπίφθονος ἔκρινεν, καὶ συναγαγὼν τοὺς Ἀντιοχεῖς εἰς ἐκκλησίαν πείθει δέξασθαι τὸν Δημήτριον αὐτούς,"},{"number":115,"text":"λέγων οὐδενὸς μνησικακήσειν αὐτοῖς περὶ τοῦ πατρὸς αὐτὸν εὐεργετηθέντα, διδάσκαλός τε ἀγαθῶν καὶ ἡγεμὼν ἔσεσθαι αὐτῷ διωμολογήσατο καὶ φαύλοις ἐγχειροῦντι πράγμασιν οὐκ ἐπιτρέψειν ὑπέσχετο. αὐτῷ δʼ ἔφασκεν ἀρκεῖν τὴν τῆς Αἰγύπτου βασιλείαν. ταῦτʼ εἰπὼν πείθει τοὺς Ἀντιοχεῖς δέξασθαι τὸν Δημήτριον."},{"number":116,"text":"Τοῦ δʼ Ἀλεξάνδρου σὺν στρατεύματι πολλῷ καὶ μεγάλῃ παρασκευῇ ὁρμήσαντος ἐκ τῆς Κιλικίας εἰς τὴν Συρίαν καὶ τὴν Ἀντιοχέων γῆν ἐμπρήσαντος καὶ διαρπάσαντος Πτολεμαῖος ἐπʼ αὐτὸν ἐξεστράτευσεν μετὰ τοῦ γαμβροῦ Δημητρίου· ἤδη γὰρ αὐτῷ πρὸς γάμον ἐδεδώκει τὴν θυγατέρα· καὶ νικήσαντες εἰς φυγὴν ἐτρέψαντο τὸν Ἀλέξανδρον."},{"number":117,"text":"οὗτος μὲν οὖν εἰς Ἀραβίαν φεύγει. συνέβη δὲ ἐν τῇ μάχῃ τὸν ἵππον τὸν Πτολεμαίου φωνῆς ἀκούσαντα ἐλέφαντος ταραχθῆναι καὶ τὸν Πτολεμαῖον ἀποσεισάμενον καταβαλεῖν, τοὺς δὲ πολεμίους ἰδόντας ἐπʼ αὐτὸν ὁρμῆσαι καὶ τραύματα πολλὰ δόντας αὐτῷ κατὰ τῆς κεφαλῆς εἰς κίνδυνον τὸν περὶ θανάτου καταστῆσαι· τῶν γὰρ σωματοφυλάκων αὐτὸν ἐξαρπασάντων χαλεπῶς οὕτως εἶχεν, ὡς ἐφʼ ἡμέρας τέσσαρας μήτε συνεῖναί τι μήτε φθέγξασθαι δυνηθῆναι."},{"number":118,"text":"τοῦ δὲ Ἀλεξάνδρου τὴν κεφαλὴν ὁ τῶν Ἀράβων δυνάστης ἀποτεμὼν Ζάβειλος ἀπέστειλεν Πτολεμαίῳ, ὃς τῇ πέμπτῃ τῶν ἡμερῶν ἀνενεγκὼν ἐκ τῶν τραυμάτων καὶ φρονήσας ἥδιστον ἄκουσμα καὶ θέαμα τὴν Ἀλεξάνδρου τελευτὴν ἅμα καὶ τὴν κεφαλὴν ἀκούει καὶ θεᾶται."},{"number":119,"text":"καὶ μετʼ οὐ πολὺ πλησθεὶς τῆς ἐπʼ Ἀλεξάνδρῳ τεθνηκότι χαρᾶς καὶ αὐτὸς κατέστρεψε τὸν βίον. ἐβασίλευσεν δὲ τῆς Ἀσίας Ἀλέξανδρος ὁ Βάλας ἐπιλεγόμενος ἔτη πέντε, καθὼς καὶ ἐν ἄλλοις δεδηλώκαμεν."},{"number":120,"text":"Παραλαβὼν δὲ τὴν βασιλείαν Δημήτριος ὁ Νικάτωρ ἐπιλεγόμενος ὑπὸ πονηρίας ἤρξατο διαφθείρειν τὰ τοῦ Πτολεμαίου στρατεύματα, τῆς τε πρὸς αὐτὸν συμμαχίας ἐκλαθόμενος καὶ ὅτι πενθερὸς ἦν αὐτοῦ καὶ διὰ τὸν τῆς Κλεοπάτρας γάμον συγγενής. οἱ μὲν οὖν στρατιῶται φεύγουσιν αὐτοῦ τὴν πεῖραν εἰς Ἀλεξάνδρειαν, τῶν δʼ ἐλεφάντων Δημήτριος ἐγκρατὴς γίνεται."},{"number":121,"text":"Ἰωνάθης δʼ ὁ ἀρχιερεὺς ἐξ ἁπάσης τῆς Ἰουδαίας στρατιὰν συναγαγὼν προσβαλὼν ἐπολιόρκει τὴν ἐν τοῖς Ἱεροσολύμοις ἄκραν ἔχουσαν Μακεδονικὴν φρουρὰν καὶ τῶν ἀσεβῶν τινας καὶ πεφευγότων τὴν πάτριον συνήθειαν."},{"number":122,"text":"οὗτοι δὲ τὸ μὲν πρῶτον κατεφρόνουν ὧν Ἰωνάθης ἐμηχανᾶτο περὶ τὴν αἵρεσιν πεπιστευκότες τῇ ὀχυρότητι τοῦ χωρίου, νυκτὸς δέ τινες τῶν ἐν αὐτῷ πονηρῶν ἐξελθόντες ἧκον πρὸς Δημήτριον καὶ τὴν πολιορκίαν αὐτῷ τῆς ἄκρας ἐμήνυσαν."},{"number":123,"text":"ὁ δὲ τοῖς ἠγγελμένοις παροξυνθείς, ἀναλαβὼν τὴν δύναμιν ἧκεν ἐκ τῆς Ἀντιοχείας ἐπὶ τὸν Ἰωνάθην. γενόμενος δὲ ἐν Πτολεμαΐδι γράφει κελεύων αὐτὸν σπεῦσαι πρὸς αὐτὸν εἰς Πτολεμαΐδα."},{"number":124,"text":"ὁ δὲ τὴν μὲν πολιορκίαν οὐκ ἔπαυσεν, τοὺς δὲ πρεσβυτέρους τοῦ λαοῦ παραλαβὼν καὶ τοὺς ἱερεῖς καὶ χρυσὸν καὶ ἄργυρον καὶ ἐσθῆτα καὶ πλῆθος ξενίων κομίζων ἧκεν πρὸς τὸν Δημήτριον, καὶ τούτοις δωρησάμενος αὐτὸν θεραπεύει τὴν ὀργὴν τοῦ βασιλέως, καὶ τιμηθεὶς ὑπʼ αὐτοῦ λαμβάνει βεβαίαν ἔχειν τὴν ἀρχιερωσύνην, καθὼς καὶ παρὰ τῶν πρὸ αὐτοῦ βασιλέων ἐκέκτητο."},{"number":125,"text":"κατηγορούντων δὲ αὐτοῦ τῶν φυγάδων ὁ Δημήτριος οὐκ ἐπίστευσεν, ἀλλὰ καὶ παρακαλέσαντος αὐτόν, ὅπως ὑπὲρ τῆς Ἰουδαίας ἁπάσης καὶ τῶν τριῶν τοπαρχιῶν Σαμαρείας καὶ Ἰόππης καὶ Γαλιλαίας τριακόσια τελῇ τάλαντα, δίδωσιν καὶ περὶ πάντων ἐπιστολάς, αἳ περιεῖχον τοῦτον τὸν τρόπον·"},{"number":126,"text":"βασιλεὺς Δημήτριος Ἰωνάθῃ τῷ ἀδελφῷ καὶ τῷ ἔθνει τῶν Ἰουδαίων χαίρειν. τὸ ἀντίγραφον τῆς ἐπιστολῆς ἧς ἔγραψα Λασθένει τῷ συγγενεῖ ἡμῶν ἀπεστάλκαμεν ὑμῖν, ἵνα εἰδῆτε."},{"number":127,"text":"βασιλεὺς Δημήτριος Λασθένει τῷ πατρὶ χαίρειν. τῷ Ἰουδαίων ἔθνει ὄντι φίλῳ καὶ τὰ δίκαια τὰ πρὸς ἡμᾶς φυλάττοντι τῆς εὐνοίας ἔκρινα χάριν παρασχεῖν. καὶ τοὺς τρεῖς νομοὺς Ἀφαίρεμα καὶ Λύδδα καὶ Ῥαμαθαιν, οἳ τῇ Ἰουδαίᾳ προσετέθησαν ἀπὸ τῆς Σαμαρείτιδος, καὶ τὰ προσκυροῦντα τούτοις,"},{"number":128,"text":"ἔτι τε ὅσα παρὰ τῶν θυόντων ἐν Ἱεροσολύμοις ἐλάμβανον οἱ πρὸ ἐμοῦ βασιλεῖς, καὶ ὅσα ἀπὸ τῶν καρπῶν τῆς γῆς καὶ τῶν φυτῶν, καὶ τἆλλα τὰ προσήκοντα ἡμῖν, καὶ τὰς λίμνας τῶν ἁλῶν καὶ τοὺς κομιζομένους ἡμῖν στεφάνους ἀφίημι αὐτοῖς, καὶ οὐδὲν παραβιβασθήσεται τούτων ἀπὸ τοῦ νῦν οὐδὲ εἰς τὸν ἅπαντα χρόνον. φρόντισον οὖν,"},{"number":129,"text":"ἵνα τούτων ἀντίγραφον γένηται καὶ δοθῇ Ἰωνάθῃ καὶ ἐν ἐπισήμῳ τόπῳ τοῦ ἁγίου ἱεροῦ τεθῇ. τὰ μὲν δὴ γραφέντα ταῦτα ἦν. ὁρῶν δὲ ὁ Δημήτριος εἰρήνην οὖσαν καὶ μηδένα κίνδυνον μηδὲ πολέμου φόβον ὑπάρχοντα διέλυσε τὴν στρατιὰν καὶ τὸν μισθὸν αὐτῶν ἐμείωσεν, καὶ μόνοις τοῦτον ἐχορήγει τοῖς ξενολογηθεῖσιν, οἳ συνανέβησαν ἐκ Κρήτης αὐτῷ καὶ ἐκ τῶν ἄλλων νήσων."},{"number":130,"text":"ἔχθρα τοιγαροῦν αὐτῷ καὶ μῖσος ἐκ τούτου γίνεται παρὰ τῶν στρατιωτῶν, οἷς αὐτὸς μὲν οὐδὲν οὐκέτι παρεῖχεν, οἱ δὲ πρὸ αὐτοῦ βασιλεῖς καὶ ἐπʼ εἰρήνης χορηγοῦντες αὐτοῖς ὁμοίως διετέλουν, ἵνʼ εὐνοοῦντας ἔχωσιν καὶ ἐν τοῖς ὑπὲρ αὐτῶν ἀγῶσιν εἰ δεήσειέν ποτε προθύμους."}],"5":[{"number":131,"text":"Ἀμέλει ταύτην νοήσας τὴν δύσνοιαν τῶν στρατιωτῶν πρὸς Δημήτριον Ἀλεξάνδρου τις στρατηγὸς Ἀπαμεὺς τὸ γένος Διόδοτος ὁ καὶ Τρύφων ἐπικληθείς, παραγίνεται πρὸς Μάλχον τὸν Ἄραβα, ὃς ἔτρεφε τὸν Ἀλεξάνδρου υἱὸν Ἀντίοχον, καὶ δηλώσας αὐτῷ τὴν δυσμένειαν τὴν τῶν στρατευμάτων πρὸς Δημήτριον ἔπειθεν αὐτῷ δοῦναι τὸν Ἀντίοχον· βασιλέα γὰρ αὐτὸν ποιήσειν καὶ τὴν ἀρχὴν αὐτῷ τὴν τοῦ πατρὸς ἀποκαταστήσειν."},{"number":132,"text":"ὁ δὲ τὸ μὲν πρῶτον ἀντεῖχεν ὑπʼ ἀπιστίας, ὕστερον δὲ πολλῷ χρόνῳ προσλιπαρήσαντος τοῦ Τρύφωνος νικᾶται τὴν προαίρεσιν εἰς ἃ Τρύφων παρεκάλει. καὶ τὰ μὲν περὶ τούτου τἀνδρὸς ἐν τούτοις ὑπῆρχεν."},{"number":133,"text":"Ὁ δʼ ἀρχιερεὺς Ἰωνάθης ἐξελθεῖν βουλόμενος τοὺς ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων καὶ τοὺς Ἰουδαίων φυγάδας καὶ ἀσεβεῖς καὶ τοὺς ἐν ἁπάσῃ τῇ χώρᾳ φρουρούς, πέμψας πρὸς Δημήτριον δῶρα καὶ πρεσβευτὰς παρεκάλει τοὺς ἐν τοῖς ὀχυρώμασι τῆς Ἰουδαίας ἐκβαλεῖν."},{"number":134,"text":"ὁ δʼ οὐ ταῦτα μόνον αὐτῷ παρέξειν, ἀλλὰ καὶ μείζω τούτων ὑπισχνεῖται μετὰ τὸν ἐν χερσὶ πόλεμον· τούτῳ γὰρ νῦν εὐσχολεῖν. ἠξίου δʼ αὐτὸν καὶ συμμαχίαν πέμψαι δηλῶν ἀποστῆναι τὴν δύναμιν αὐτοῦ. καὶ Ἰωνάθης μὲν τρισχιλίους ἐπιλεξάμενος στρατιώτας ἔπεμψεν."},{"number":135,"text":"Ἀντιοχεῖς δὲ μισοῦντες τὸν Δημήτριον ὑπὲρ ὧν πεπόνθεισαν ὑπʼ αὐτοῦ κακῶς, ἀπεχθανόμενοι δʼ αὐτῷ καὶ διὰ τὸν πατέρα Δημήτριον πολλὰ εἰς αὐτοὺς ἐξαμαρτόντα, καιρὸν ἐπετήρουν λαβεῖν καθʼ ὃν ἐπιθοῖντο αὐτῷ."},{"number":136,"text":"νοήσαντες δὲ συμμαχίαν παροῦσαν παρὰ Ἰωνάθου τῷ Δημητρίῳ καὶ συμφρονήσαντες, ὅτι πολλὴν ἀθροίσει δύναμιν, εἰ μὴ φθάσαντες προκαταλάβοιεν αὐτόν, ἁρπάσαντες τὰ ὅπλα καὶ περιστάντες τοῖς βασιλείοις αὐτοῦ τρόπῳ πολιορκίας καὶ τὰς ἐξόδους διαλαβόντες ἐζήτουν χειρώσασθαι τὸν βασιλέα."},{"number":137,"text":"ὁ δὲ τὸν δῆμον ὁρῶν τὸν τῶν Ἀντιοχέων ἐκπεπολεμωμένον πρὸς αὐτὸν καὶ ἐν ὅπλοις ὄντα, παραλαβὼν τοὺς μισθοφόρους καὶ τοὺς πεμφθέντας ὑπὸ Ἰωνάθου Ἰουδαίους συμβάλλει τοῖς Ἀντιοχεῦσιν καὶ βιασθεὶς ὑπʼ αὐτῶν, πολλαὶ γὰρ ἦσαν μυριάδες, ἡττᾶται."},{"number":138,"text":"βλέποντες δὲ τοὺς Ἀντιοχεῖς κρατοῦντας οἱ Ἰουδαῖοι ἐπὶ τὰς στέγας τῶν βασιλείων ἀναβάντες ἐκεῖθεν ἔβαλλον τοὺς Ἀντιοχεῖς, καὶ τοῦ μὲν αὐτοί τι πάσχειν ὑπʼ αὐτῶν ὄντες πορρωτάτω διὰ τὸ ὕψος, ποιοῦντες δʼ αὐτοὺς κακῶς διὰ τὸ ἄνωθεν μάχεσθαι τῶν σύνεγγυς αὐτοὺς οἰκιῶν ἀπώσαντο."},{"number":139,"text":"καὶ ταύταις μὲν εὐθὺς πῦρ ἐνῆκαν, ἡ δὲ φλὸξ ἐφʼ ὅλην διατείνουσα τὴν πόλιν πυκνῶν τῶν οἰκιῶν οὐσῶν καὶ τὰ πλεῖστα ἐκ ξύλων ᾠκοδομημένων πᾶσαν αὐτὴν ἐνέμετο."},{"number":140,"text":"οἱ δʼ Ἀντιοχεῖς μὴ δυνάμενοι βοηθῆσαι μηδὲ κρατῆσαι τοῦ πυρὸς εἰς φυγὴν ἐτράπησαν. τῶν δὲ Ἰουδαίων ἀπὸ δώματος ἐπὶ δῶμα διαπηδώντων καὶ τοῦτον αὐτοὺς διωκόντων τὸν τρόπον παράδοξον συνέβη γενέσθαι τὴν δίωξιν."},{"number":141,"text":"ὁ δὲ βασιλεὺς ὁρῶν τοὺς Ἀντιοχεῖς σῶσαι τὰ τέκνα καὶ τὰς γυναῖκας ἐσπουδακότας καὶ διὰ τοῦτο μηκέτι μαχομένους διʼ ἄλλων αὐτοῖς ἐπιτίθεται στενωπῶν, καὶ συμβαλὼν πολλοὺς μὲν αὐτῶν ἀπέκτεινεν, ὡς ἀναγκασθῆναι ῥῖψαι τὰς πανοπλίας καὶ παραδοῦναι αὑτοὺς τῷ Δημητρίῳ."},{"number":142,"text":"συγγνοὺς δʼ αὐτοῖς τῶν τετολμημένων καταπαύει τὴν στάσιν. δωρησάμενος δὲ τοῖς Ἰουδαίοις τὰς ἐκ τῶν σκύλων ὠφελείας καὶ ὡς αἰτιωτάτοις τῆς νίκης αὐτῷ γεγενημένοις εὐχαριστήσας ἀπέπεμψεν εἰς Ἱεροσόλυμα πρὸς Ἰωνάθην μαρτυρῶν αὐτῷ τῆς συμμαχίας."},{"number":143,"text":"ὕστερον δὲ πονηρὸς εἰς αὐτὸν ἐγένετο καὶ τὰς ὑποσχέσεις διεψεύσατο καὶ πόλεμον ἠπείλησεν, εἰ μὴ τοὺς φόρους αὐτῷ πάντας ἀποδώσει, οὓς ὤφειλεν τὸ τῶν Ἰουδαίων ἔθνος ἀπὸ τῶν πρώτων βασιλέων. καὶ ταῦτʼ ἐποίησεν ἄν, εἰ μὴ Τρύφων αὐτὸν ἐπέσχεν καὶ τὴν ἐπὶ τὸν Ἰωνάθην αὐτοῦ παρασκευὴν ἀντιμετέσπασεν εἰς τὰς περὶ αὐτοῦ φροντίδας."},{"number":144,"text":"ὑποστρέψας γὰρ ἐκ τῆς Ἀραβίας εἰς τὴν Συρίαν μετὰ τοῦ παιδὸς Ἀντιόχου, μειράκιον δʼ ἦν οὗτος τὴν ἡλικίαν, περιτίθησιν αὐτῷ τὸ διάδημα. καὶ προσχωρήσαντος τοῦ στρατιωτικοῦ παντός, ὃ καταλελοίπει τὸν Δημήτριον διὰ τὸ μὴ τυγχάνειν μισθῶν, πόλεμον ἐκφέρει πρὸς τὸν Δημήτριον, καὶ συμβαλὼν αὐτῷ κρατεῖ τῇ μάχῃ καὶ τούς τε ἐλέφαντας καὶ τὴν τῶν Ἀντιοχέων πόλιν λαμβάνει."},{"number":145,"text":"Δημήτριος μὲν οὖν ἡττηθεὶς ἀνεχώρησεν εἰς Κιλικίαν, ὁ δὲ παῖς Ἀντίοχος πέμψας πρὸς Ἰωνάθην πρεσβευτὰς καὶ γράμματα φίλον τε καὶ σύμμαχον αὐτὸν ἐποιεῖτο καὶ τὴν ἀρχιερωσύνην ἐβεβαίου καὶ τῶν τεσσάρων παρεχώρει νομῶν, οἳ τῇ χώρᾳ τῶν Ἰουδαίων προσετέθησαν."},{"number":146,"text":"ἔτι γε μὴν σκεύη χρυσᾶ καὶ ἐκπώματα καὶ πορφυρᾶν ἐσθῆτα χρῆσθαι τούτοις ἐπιτρέπων ἀπέστειλεν καὶ πόρπῃ δʼ αὐτὸν δωρεῖται χρυσέᾳ καὶ τῶν πρώτων αὐτοῦ καλεῖσθαι φίλων. τὸν ἀδελφὸν δʼ αὐτοῦ Σίμωνα στρατηγὸν τῆς στρατιᾶς ἀπὸ κλίμακος τῆς Τυρίων ἕως Αἰγύπτου καθίστησιν."},{"number":147,"text":"Ἰωνάθης δʼ ἐπὶ τοῖς παρʼ Ἀντιόχου γεγενημένοις εἰς αὐτὸν ἡσθεὶς πέμψας πρὸς αὐτόν τε καὶ Τρύφωνα πρεσβευτὰς εἶναί τε φίλος ὡμολόγει καὶ σύμμαχος καὶ πολεμήσειν σὺν αὐτῷ πρὸς Δημήτριον, διδάσκων ὡς οὐδʼ αὐτῷ χάριτας ἀποδοίη πολλῶν παρʼ αὐτοῦ χρηστῶν ἐν οἷς ἐδεῖτο τυχών, ἀλλὰ προσαδικήσειεν ἀνθʼ ὧν εὖ πάθοι."},{"number":148,"text":"Συγχωρήσαντος οὖν Ἀντιόχου δύναμιν αὐτῷ συναγαγόντι πολλὴν ἔκ τε Συρίας καὶ Φοινίκης τοῖς Δημητρίου πολεμῆσαι στρατηγοῖς εὐθὺς ὥρμησεν εἰς τὰς πόλεις. αἱ δὲ λαμπρῶς μὲν ἐξεδέξαντο, στρατιὰν δʼ οὐκ ἔδοσαν."},{"number":149,"text":"παραγενόμενος δʼ ἐκεῖθεν πρὸς Ἀσκάλωνα πόλιν καὶ τῶν Ἀσκαλωνιτῶν φιλοτίμως αὐτῷ μετὰ δώρων ἀπαντησάντων, αὐτούς τε τούτους παρεκάλει καὶ τῶν ἐν τῇ κοίλῃ Συρίᾳ πόλεων ἑκάστην ἀποστᾶσαν Δημητρίου προσθέσθαι μὲν Ἀντιόχῳ, σὺν αὐτῷ δὲ πολεμούσας πειρᾶσθαι παρὰ Δημητρίου δίκην λαμβάνειν ὧν ἁμάρτοι ποτʼ εἰς αὐτάς· εἶναι δʼ αὐταῖς βουλομέναις ταῦτα φρονεῖν πολλὰς αἰτίας."},{"number":150,"text":"πείσας δʼ ὁμολογῆσαι πρὸς τὸν Ἀντίοχον συμμαχεῖν τὰς πόλεις εἰς Γάζαν παρεγένετο προσαξόμενος καὶ τὴν παρὰ τούτων εὔνοιαν Ἀντιόχῳ. πολὺ δʼ εὗρεν τῆς προσδοκίας τοὺς Γαζαίους ἀλλοτριώτερον ἔχοντας· ἀπέκλεισαν γὰρ αὐτῷ τὰς πύλας καὶ τὸν Δημήτριον ἐγκαταλιπόντες οὐκ ἔγνωσαν Ἀντιόχῳ προσχωρῆσαι."},{"number":151,"text":"τοῦτο παρώξυνεν εἰς πολιορκίαν τὸν Ἰωνάθην καὶ τῆς χώρας τὴν κάκωσιν· μέρος γὰρ τῆς στρατιᾶς περικαθίσας τῇ Γάζῃ τῷ λοιπῷ τὴν γῆν αὐτὸς ἐπιὼν διέφθειρεν καὶ ἐνεπίμπρα. ταῦτα δὲ πάσχοντας ἑαυτοὺς ὁρῶντες οἱ Γαζῖται καὶ μηδεμίαν ἀπὸ Δημητρίου βοήθειαν αὐτοῖς γινομένην, ἀλλὰ τὸ μὲν λυποῦν ἤδη παρόν, τὸ δʼ ὠφελῆσον μακρὰν ἔτι καὶ ἄδηλον εἰ παραγένοιτο, σῶφρον ἔκριναν εἶναι τοῦτʼ ἀφέντες παραμένειν ἐκεῖνο θεραπεύειν."},{"number":152,"text":"πέμψαντες οὖν πρὸς τὸν Ἰωνάθην φιλίαν τε ὡμολόγουν καὶ συμμαχίαν· οἱ μὲν γὰρ ἄνθρωποι πρὸ πείρας τῶν δεινῶν οὐ συνιᾶσιν τὸ συμφέρον, ἀλλʼ ὅταν ἔν τινι κακῷ γενόμενοι τύχωσιν, τότε γνωσιμαχήσαντες ἃ μηδʼ ὅλως βλαβέντας ἄμεινον ἦν ποιεῖν ταῦθʼ ὕστερον ζημιωθέντες αἱροῦνται."},{"number":153,"text":"ὁ δὲ συνθέμενος πρὸς αὐτοὺς φιλίαν καὶ λαβὼν ὁμήρους τούτους μὲν ἀπέστειλεν εἰς Ἱεροσόλυμα, αὐτὸς δὲ τὴν χώραν ἅπασαν ἐπῆλθεν ἄχρι Δαμασκοῦ."},{"number":154,"text":"Τῶν δὲ Δημητρίου στρατηγῶν ἀκουσθέντων αὐτῷ προελθεῖν εἰς Κέδασαν σὺν πολλῇ στρατιᾷ, μεταξὺ δʼ ἐστὶν αὕτη τῆς τε Τυρίων γῆς καὶ τῆς Γαλιλαίας· ἀπάξειν γὰρ αὐτὸν ἐκ τῆς Συρίας ὑπέλαβον ἐπὶ τὴν τῶν Γαλιλαίων συμμαχίαν· τῆς γὰρ Γαλιλαίας ὄντας αὐτοὺς οὐ περιόψεσθαι πολεμουμένους· ὑπήντησεν αὐτοῖς τὸν ἀδελφὸν Σίμωνα καταλιπὼν ἐν τῇ Ἰουδαίᾳ,"},{"number":155,"text":"ὃς στρατὸν ἐκ τῆς χώρας συναγαγὼν ὡς ἐνῆν ἱκανώτατον τὴν Βεθσούραν πολιορκῶν προσεκάθητο χωρίον τῆς Ἰουδαίας ὀχυρώτατον· κατεῖχεν γὰρ αὐτὸ φρουρὰ Δημητρίου. δεδήλωται δʼ ἡμῖν τοῦτο καὶ πρότερον."},{"number":156,"text":"ὡς δὲ χώματα μὲν ἐγείραντος τοῦ Σίμωνος, μηχανήματα δʼ ἱστάντος καὶ πολλῇ σπουδῇ χρωμένου περὶ τὴν τῆς Βεθσούρου πολιορκίαν ἔδεισαν οἱ φρουροί, μὴ κατὰ κράτος ἐξαιρεθέντος τοῦ χωρίου διαφθαρῶσιν, πέμψαντες πρὸς τὸν Σίμωνα ἠξίουν ὅρκους λαβόντες, ὥστε μηδὲν ὑπʼ αὐτοῦ παθεῖν, καταλιπεῖν τὸ χωρίον καὶ πρὸς Δημήτριον ἀπελθεῖν."},{"number":157,"text":"ὁ δὲ δοὺς ταύτας αὐτοῖς τὰς πίστεις ἐκβάλλει μὲν ἐκείνους ἐκ τῆς πόλεως, αὐτὸς δὲ φρουρὰν καθίστησιν ἰδίαν."},{"number":158,"text":"Ἰωνάθης δὲ ἄρας ἐκ τῆς Γαλιλαίας ἀπὸ τῶν ὑδάτων τῶν Γενησάρων λεγομένων, ἐκεῖ γὰρ ἐτύγχανεν ἐστρατοπεδευκώς, εἰς τὸ καλούμενον Ἀσὼρ πεδίον προῆλθεν οὐκ εἰδὼς ὄντας ἐν αὐτῇ τοὺς πολεμίους."},{"number":159,"text":"μαθόντες δὲ πρὸ μιᾶς ἡμέρας οἱ τοῦ Δημητρίου μέλλειν Ἰωνάθην ἐπʼ αὐτοὺς βαδίζειν ἐνέδραν αὐτῷ καὶ τοὺς λοχήσοντας ἐν τῷ ὄρει καθίσαντες αὐτοὶ μετὰ τῆς στρατιᾶς ἀπήντων εἰς τὸ πεδίον· οὓς ἰδὼν ὁ Ἰωνάθης ἑτοίμους πρὸς μάχην παρεσκευάζετο καὶ αὐτὸς τοὺς ἰδίους στρατιώτας πρὸς τὸν ἀγῶνα, ὡς ἠδύνατο."},{"number":160,"text":"τῶν δὲ εἰς τὴν ἐνέδραν ὑπὸ τῶν Δημητρίου στρατηγῶν κατασταθέντων κατὰ νώτου τοῖς Ἰουδαίοις γενομένων, δείσαντες μὴ μέσοι ληφθέντες ἀπόλωνται, φεύγειν ὥρμησαν."},{"number":161,"text":"καὶ οἱ μὲν ἄλλοι πάντες τὸν Ἰωνάθην κατέλιπον, ὀλίγοι δέ τινες ὡς περὶ πεντήκοντα τὸν ἀριθμὸν ὑπέμειναν, καὶ Ματθίας ὁ Ἀψαλώμου καὶ Ἰούδας ὁ Χαψέου τῆς ἁπάσης δυνάμεως ἡγεμόνες ὄντες· τολμηρῶς δὲ καὶ μετὰ ἀπογνώσεως εἰς τοὺς πολεμίους ὠσάμενοι τῷ τε θάρσει κατέπληξαν αὐτοὺς καὶ ταῖς χερσὶν ἀπέστρεψαν εἰς φυγήν."},{"number":162,"text":"οἱ δʼ ἀναχωρήσαντες τῶν Ἰωνάθου στρατιωτῶν ὡς εἶδον τοὺς πολεμίους τραπέντας, ἐπισυλλεγέντες ἐκ τῆς φυγῆς ὥρμησαν αὐτοὺς διώκειν καὶ τοῦτʼ ἐποίησαν μέχρι Κεδάσων, οὗ τὸ στρατόπεδον ἦν τοῖς πολεμίοις."},{"number":163,"text":"Κρατήσας οὖν Ἰωνάθης τῇ μάχῃ λαμπρῶς καὶ δισχιλίους τῶν ἐχθρῶν ἀποκτείνας ὑπέστρεψεν εἰς Ἱεροσόλυμα. ὁρῶν οὖν, ὅτι πάντʼ αὐτῷ κατὰ νοῦν προνοίᾳ θεοῦ χωρεῖ, πρὸς Ῥωμαίους πρεσβευτὰς ἀπέστειλεν, ἀνανεώσασθαι βουλόμενος τὴν γενομένην τῷ ἔθνει πρὸς αὐτοὺς ἔμπροσθεν φιλίαν."},{"number":164,"text":"τοῖς δʼ αὐτοῖς πρεσβευταῖς ἐπέστειλεν ἀπὸ τῆς Ῥώμης ἀναστρέφουσιν πρὸς τοὺς Σπαρτιάτας ἀφικέσθαι καὶ τὴν πρὸς αὐτοὺς ὑπομνῆσαι φιλίαν καὶ συγγένειαν. οἱ δʼ ὡς ἦλθον εἰς τὴν Ῥώμην παρελθόντες εἰς τὴν βουλὴν αὐτῶν καὶ τὰ παρὰ Ἰωνάθου τοῦ ἀρχιερέως εἰπόντες, ὡς πέμψειεν αὐτοὺς ἐπὶ τῇ τῆς συμμαχίας βεβαιώσει,"},{"number":165,"text":"τῆς βουλῆς ἐπικυρωσάσης τὰ πρότερον αὐτῇ περὶ τῆς Ἰουδαίων φιλίας ἐγνωσμένα καὶ δούσης ἐπιστολὰς πρὸς ἅπαντας τοὺς βασιλεῖς τῆς Ἀσίας καὶ Εὐρώπης καὶ τῶν πόλεων ἄρχοντας αὐτοῖς κομίζειν, ὅπως ἀσφαλοῦς τῆς εἰς τὴν οἰκείαν κομιδῆς διʼ αὐτῶν τύχωσιν, ἀναστρέφοντες εἰς τὴν Σπάρτην παρεγένοντο καὶ τὰς ἐπιστολάς, ἃς ἔλαβον παρὰ Ἰωνάθου, αὐτοῖς ἀπέδοσαν."},{"number":166,"text":"τὸ δʼ ἀντίγραφον ἦν τόδε· ἀρχιερεὺς Ἰωνάθης τοῦ ἔθνους τῶν Ἰουδαίων καὶ ἡ γερουσία καὶ τὸ κοινὸν τῶν ἱερέων Λακεδαιμονίων ἐφόροις καὶ γερουσίᾳ καὶ δήμῳ τοῖς ἀδελφοῖς χαίρειν. εἰ ἐρρωμένοις ὑμῖν καὶ τὰ κοινὰ καὶ τὰ ἴδια χωρεῖ κατὰ νοῦν, οὕτως ἂν ἔχοι ὡς βουλόμεθα, ἐρρώμεθα δὲ καὶ ἡμεῖς."},{"number":167,"text":"ἐπειδὴ τοῖς ἔμπροσθεν χρόνοις κομισθείσης Ὀνίᾳ τῷ γενομένῳ ἀρχιερεῖ παρʼ ἡμῖν παρὰ Ἀρέως τοῦ βασιλεύσαντος ὑμῶν ἐπιστολῆς διὰ Δημοτέλους περὶ τῆς ὑπαρχούσης ὑμῖν πρὸς ἡμᾶς συγγενείας, ἧς ὑποτέτακται τὸ ἀντίγραφον, τήν τε ἐπιστολὴν ἐδεξάμεθα προθύμως καὶ τῷ Δημοτέλει καὶ τῷ Ἀρεῖ εὐνοϊκῶς διετέθημεν, οὐ δεόμενοι τῆς τοιαύτης ἀποδείξεως διὰ τὸ ἐκ τῶν ἱερῶν ἡμῶν πεπιστεῦσθαι γραμμάτων,"},{"number":168,"text":"τὸ μὲν προκατάρχειν τῆς ἀναγνωρίσεως οὐδὲ δοκιμάζομεν μὴ καὶ προαρπάζειν δοκῶμεν τὴν παρʼ ὑμῶν διδομένην δόξαν, πολλῶν δὲ χρόνων διαγενομένων ἀπὸ τῆς ἐξ ἀρχῆς ἀναποληθείσης ἡμῖν οἰκειότητος ἐν ταῖς ἱεραῖς καὶ ἐπωνύμοις ἡμέραις θυσίας τῷ θεῷ προσφέροντες καὶ ὑπὲρ τῆς ὑμετέρας σωτηρίας τε καὶ νίκης αὐτὸν παρακαλοῦμεν."},{"number":169,"text":"πολλῶν δʼ ἡμᾶς πολέμων περιστάντων διὰ τὴν τῶν γειτνιώντων πλεονεξίαν οὔθʼ ὑμῖν οὔτʼ ἄλλῳ τῶν προσηκόντων ἡμῖν ἐνοχλεῖν ἐκρίναμεν. καταγωνισάμενοι δὲ τοὺς πολεμίους πέμποντες πρὸς Ῥωμαίους Νουμήνιον τὸν Ἀντιόχου καὶ Ἀντίπατρον τὸν Ἰάσονος τῶν ἀπὸ τῆς γερουσίας ὄντων παρʼ ἡμῖν ἐν τιμῇ, ἐδώκαμεν αὐτοῖς καὶ πρὸς ὑμᾶς ἐπιστολάς, ὅπως ἀνανεώσωνται τὴν πρὸς ὑμᾶς ἡμῖν συγγένειαν."},{"number":170,"text":"καλῶς οὖν ποιήσετε καὶ αὐτοὶ γράφοντες ἡμῖν καὶ περὶ ὧν ἂν δέησθε ἐπιστέλλοντες, ὡς εἰς ἅπαντα προθυμησομένοις ὑπὲρ τῆς ὑμετέρας προαιρέσεως. οἱ μὲν οὖν Λακεδαιμόνιοι τούς τε πρεσβευτὰς φιλοφρόνως ὑπεδέξαντο καὶ ψήφισμα ποιησάμενοι περὶ συμμαχίας καὶ φιλίας πρὸς αὐτοὺς ἀπέστειλαν."},{"number":171,"text":"Κατὰ δὲ τὸν χρόνον τοῦτον τρεῖς αἱρέσεις τῶν Ἰουδαίων ἦσαν, αἳ περὶ τῶν ἀνθρωπίνων πραγμάτων διαφόρως ὑπελάμβανον, ὧν ἡ μὲν Φαρισαίων ἐλέγετο, ἡ δὲ Σαδδουκαίων, ἡ τρίτη δὲ Ἐσσηνῶν."},{"number":172,"text":"οἱ μὲν οὖν Φαρισαῖοι τινὰ καὶ οὐ πάντα τῆς εἱμαρμένης ἔργον εἶναι λέγουσιν, τινὰ δʼ ἐφʼ ἑαυτοῖς ὑπάρχειν συμβαίνειν τε καὶ μὴ γίνεσθαι. τὸ δὲ τῶν Ἐσσηνῶν γένος πάντων τὴν εἱμαρμένην κυρίαν ἀποφαίνεται καὶ μηδὲν ὃ μὴ κατʼ ἐκείνης ψῆφον ἀνθρώποις ἀπαντᾶν."},{"number":173,"text":"Σαδδουκαῖοι δὲ τὴν μὲν εἱμαρμένην ἀναιροῦσιν οὐδὲν εἶναι ταύτην ἀξιοῦντες οὐδὲ κατʼ αὐτὴν τὰ ἀνθρώπινα τέλος λαμβάνειν, ἅπαντα δὲ ἐφʼ ἡμῖν αὐτοῖς κεῖσθαι, ὡς καὶ τῶν ἀγαθῶν αἰτίους ἡμᾶς γινομένους καὶ τὰ χείρω παρὰ τὴν ἡμετέραν ἀβουλίαν λαμβάνοντας. ἀλλὰ περὶ μὲν τούτων ἀκριβεστέραν πεποίημαι δήλωσιν ἐν τῇ δευτέρᾳ βίβλῳ τῆς Ἰουδαϊκῆς πραγματείας."},{"number":174,"text":"Οἱ δὲ τοῦ Δημητρίου στρατηγοὶ τὴν γεγενημένην ἧτταν ἀναμαχέσασθαι βουλόμενοι, πλείω τῆς προτέρας δύναμιν συναγαγόντες ἦλθον ἐπὶ τὸν Ἰωνάθην. ὁ δὲ ἐπιόντας πυθόμενος ὀξέως ἀπήντησεν αὐτοῖς εἰς τὴν Ἀμαθῖτιν· οὐ γὰρ ἔγνω σχολὴν αὐτοῖς παρασχεῖν, ὥστʼ εἰς τὴν Ἰουδαίαν ἐμβαλεῖν."},{"number":175,"text":"στρατοπεδευσάμενος δὲ τῶν πολεμίων ἄπωθεν σταδίοις πεντήκοντα πέμπει τοὺς κατοψομένους αὐτῶν τὴν παρεμβολὴν καὶ πῶς εἶεν ἐστρατοπεδευκότες. τῶν δὲ κατασκόπων πάντʼ αὐτῷ φρασάντων καί τινας συλλαβόντων νυκτός, οἳ αὐτοῖς μέλλειν ἐπιτίθεσθαι τοὺς πολεμίους ἐμήνυον, προγνοὺς ἠσφαλίσατο,"},{"number":176,"text":"προφυλακάς τε ποιησάμενος ἔξω τοῦ στρατοπέδου καὶ τὴν δύναμιν διʼ ὅλης τῆς νυκτὸς ἐν τοῖς ὅπλοις ἔχων ἅπασαν καὶ παρηγγελκὼς αὐτοῖς τὰς ψυχὰς ἐρρωμένους εἶναι καὶ ταῖς διανοίαις οὕτως ἔχειν, ὡς καὶ διὰ τῆς νυκτὸς εἰ δεήσειε μαχεσομένους, ὥστε μὴ λαθεῖν αὐτῶν τὴν προαίρεσιν."},{"number":177,"text":"οἱ δὲ τοῦ Δημητρίου στρατηγοὶ πυθόμενοι τὸν Ἰωνάθην ἐγνωκότα οὐκέτι τὴν γνώμην ἦσαν ὑγιεῖς, ἀλλʼ ἐτάραττεν αὐτοὺς τὸ καταφώρους τοῖς ἐχθροῖς γεγονέναι καὶ μηδενὶ προσδοκᾶν αὐτῶν ἐπικρατήσειν ἑτέρῳ τῆς ἐπιβουλῆς διημαρτημένης· ἐκ γὰρ τοῦ φανεροῦ διακινδυνεύοντες οὐκ ἐνόμιζον εἶναι τοῖς Ἰωνάθου ἀξιόμαχοι."},{"number":178,"text":"φυγὴν οὖν ἐβουλεύσαντο, καὶ πυρὰ καύσαντες πολλά, ὡς ὁρῶντες οἱ πολέμιοι μένειν αὐτοὺς ὑπολάβοιεν, ἀνεχώρησαν. ὁ δὲ Ἰωνάθης ἕωθεν προσμίξας αὐτῶν τῷ στρατοπέδῳ καὶ καταλαβὼν ἔρημον αὐτό, συνεὶς ὅτι πεφεύγασιν ἐδίωκεν."},{"number":179,"text":"οὐ μέντοι φθάνει καταλαβεῖν· ἤδη γὰρ τὸν Ἐλεύθερον ποταμὸν διαβεβηκότες ἦσαν ἐν ἀσφαλεῖ. ποιησάμενος οὖν ἐκεῖθεν τὴν ὑποστροφὴν εἰς τὴν Ἀραβίαν καὶ πολεμήσας τοὺς Ναβατηνοὺς καὶ πολλὴν αὐτῶν λείαν ἀπελάσας καὶ λαβὼν αἰχμαλώτους ἐλθὼν εἰς Δαμασκὸν ἐκεῖ πάντα ἀπέδοτο."},{"number":180,"text":"ὑπὸ δὲ τὸν αὐτὸν καιρὸν καὶ Σίμων ὁ ἀδελφὸς αὐτοῦ τὴν Ἰουδαίαν ἅπασαν ἐπελθὼν καὶ τὴν Παλαιστίνην ἕως Ἀσκάλωνος ἠσφαλίσατο φρουρίοις, καὶ ποιήσας ταῦτα καὶ τοῖς οἰκοδομήμασιν ὀχυρώτατα καὶ ταῖς φυλακαῖς ἦλθεν εἰς Ἰόππην καὶ καταλαβόμενος αὐτὴν εἰσήγαγεν μεγάλην φρουράν· ἤκουσε γὰρ τοὺς Ἰοππηνοὺς βουλομένους τοῖς Δημητρίου στρατηγοῖς παραδοῦναι τὴν πόλιν."},{"number":181,"text":"Ταῦτʼ οὖν διοικησάμενοι ὅ τε Σίμων καὶ Ἰωνάθης ἦλθον εἰς Ἱεροσόλυμα. συναγαγὼν δὲ τὸν λαὸν ἅπαντα εἰς τὸ ἱερὸν Ἰωνάθης συνεβουλεύετο τά τε τείχη τῶν Ἱεροσολυμιτῶν ἐπισκευάσαι καὶ τὸ καθῃρημένον τοῦ περὶ τὸ ἱερὸν περιβόλου πάλιν ἀναστῆσαι καὶ πύργοις ὑψηλοῖς ἐξοχυρῶσαι τὰ περὶ αὐτό,"},{"number":182,"text":"πρὸς τούτοις δὲ καὶ μέσον τῆς πόλεως ἄλλο τεῖχος ἀνοικοδομησαμένους ἀποφράξαι τοῖς ἐν τῇ ἄκρᾳ φρουροῖς τὴν πόλιν καὶ τῆς εὐπορίας αὐτοὺς τῶν σιτίων τοῦτον ἀποκλεῖσαι τὸν τρόπον, ἔτι γε μὴν καὶ τὰ ἐν τῇ χώρᾳ φρούρια ποιῆσαι πολὺ τῆς ὑπαρχούσης αὐτοῖς ἀσφαλείας ὀχυρώτερα."},{"number":183,"text":"τῆς δὲ γνώμης καὶ τῷ πλήθει δοκιμασθείσης καλῶς ἔχειν αὐτὸς μὲν τὰ κατὰ τὴν πόλιν ᾠκοδόμει, Σίμωνα δὲ τὰ κατὰ τὴν χώραν ἐξέπεμψεν ἀσφαλισόμενον."},{"number":184,"text":"ὁ δὲ Δημήτριος διαβὰς εἰς τὴν Μεσοποταμίαν ἧκεν ταύτην τε βουλόμενος καὶ τὴν Βαβυλῶνα κατασχεῖν,"},{"number":185,"text":"καὶ τῶν ἄνω σατραπειῶν ἐγκρατὴς γενόμενος ἐντεῦθεν ποιεῖσθαι τὰς ὅλης τῆς βασιλείας ἀφορμάς· καὶ γὰρ οἱ ταύτῃ κατοικοῦντες Ἕλληνες καὶ Μακεδόνες συνεχῶς ἐπρεσβεύοντο πρὸς αὐτόν, εἰ πρὸς αὐτοὺς ἀφίκοιτο, παραδώσειν μὲν αὑτοὺς ὑπισχνούμενοι, συγκαταπολεμήσειν δὲ Ἀρσάκην τὸν Πάρθων βασιλέα."},{"number":186,"text":"ταύταις ἐπαρθεὶς ταῖς ἐλπίσιν ὥρμησεν πρὸς αὐτούς, εἰ καταστρέψαιτο τοὺς Πάρθους καὶ γένοιτʼ αὐτῷ δύναμις, τὸν Τρύφωνα πολεμῆσαι διεγνωκὼς καὶ τῆς Συρίας ἐκβαλεῖν. δεξαμένων δὲ αὐτὸν προθύμως τῶν ἐν τῇ χώρᾳ, συναγαγὼν δύναμιν ἐπολέμησεν πρὸς τὸν Ἀρσάκην, καὶ τὴν στρατιὰν πᾶσαν ἀποβαλὼν αὐτὸς ζῶν ἐλήφθη, καθὼς καὶ ἐν ἄλλοις δεδήλωται."}],"6":[{"number":187,"text":"Τρύφων δʼ ἐπειδὴ τὰ περὶ τὸν Δημήτριον ἔγνω τοιοῦτο λαβόντα τέλος οὐκέτʼ ἦν Ἀντιόχῳ βέβαιος, ἀλλʼ ἐπεβούλευεν ὥστʼ αὐτὸν ἀποκτείνας τὴν βασιλείαν αὐτὸς κατασχεῖν. ἐνεπόδιζέ γε μὴν αὐτοῦ τὴν προαίρεσιν ταύτην ὁ παρὰ Ἰωνάθου φόβος φίλου τυγχάνοντος Ἀντιόχῳ, καὶ διὰ τοῦτʼ ἐκποδὼν ποιήσασθαι τὸν Ἰωνάθην πρῶτον ἔγνω καὶ τότε τοῖς περὶ τὸν Ἀντίοχον ἐγχειρεῖν."},{"number":188,"text":"ἀπάτῃ δʼ αὐτὸν καὶ δόλῳ κρίνας ἀνελεῖν εἰς Βαιθσὰν ἐκ τῆς Ἀντιοχείας παραγίνεται τὴν καλουμένην ὑφʼ Ἑλλήνων Σκυθόπολιν, εἰς ἣν μετὰ τεσσάρων αὐτῷ μυριάδων Ἰωνάθης ἀπήντησεν ἐπιλέκτου στρατοῦ· πολεμήσοντα γὰρ αὐτὸν ἥκειν ὑπελάμβανεν."},{"number":189,"text":"ὁ δʼ ἕτοιμον εἰς μάχην γνοὺς τὸν Ἰωνάθην ὑπέρχεται δώροις αὐτὸν καὶ φιλοφρονήσει, καὶ τοῖς ἡγεμόσιν αὐτοῦ πειθαρχεῖν Ἰωνάθῃ προσέταξεν, τούτοις πιστώσασθαι βουλόμενος εὔνοιαν καὶ πᾶσαν ὑπόνοιαν ἐξελεῖν εἰς τὸ καταφρονήσαντα λαβεῖν ἀφύλακτον οὐδὲν προορώμενον."},{"number":190,"text":"τήν τε στρατιὰν συνεβούλευεν ἀπολῦσαι· καὶ γὰρ νῦν οὐ δεόντως αὐτὴν ἐπάγεσθαι, πολέμου μὲν οὐκ ὄντος, εἰρήνης δὲ ἐχούσης τὰ πράγματα· κατασχόντα μέντοι γε περὶ αὐτὸν ὀλίγους εἰς Πτολεμαΐδα συνελθεῖν παρεκάλει· παραδώσειν γὰρ αὐτῷ τὴν πόλιν τά τε ἄλλα πάνθʼ ὅσα κατὰ τὴν χώραν ἐστὶν ὀχυρώματα ποιήσειν ἐπʼ αὐτῷ· καὶ γὰρ τούτων ἕνεκα παρεῖναι."},{"number":191,"text":"Ὁ μὲν οὖν Ἰωνάθης οὐδὲν τούτων ὑπονοήσας, ἀλλʼ ὑπʼ εὐνοίας καὶ γνώμης ἀληθοῦς τὸν Τρύφωνα συμβουλεῦσαι ταῦτα πιστεύσας τὴν μὲν στρατιὰν ἀπέλυσεν, τρισχιλίους δὲ κατασχὼν μόνους τοὺς μὲν δισχιλίους ἐν τῇ Γαλιλαίᾳ κατέλιπεν, αὐτὸς δὲ μετὰ τῶν χιλίων ἧκεν εἰς Πτολεμαΐδα σὺν Τρύφωνι."},{"number":192,"text":"τῶν δʼ ἐν τῇ Πτολεμαΐδι κλεισάντων τὰς πύλας, τοῦτο γὰρ ἦν αὐτοῖς ὑπὸ τοῦ Τρύφωνος προστεταγμένον, Ἰωνάθην ἐζώγρησεν, τοὺς δὲ σὺν αὐτῷ πάντας ἀπέκτεινεν. ἔπεμψεν δὲ καὶ ἐπὶ τοὺς ἐν τῇ Γαλιλαίᾳ καταλειφθέντας δισχιλίους, ὅπως ἂν καὶ τούτους ἀπολέσωσιν·"},{"number":193,"text":"ἀλλʼ οὗτοι μὲν ὑπὸ φήμης τῶν περὶ τὸν Ἰωνάθην συμβεβηκότων ἔφθησαν πρὶν ἢ τοὺς ὑπὸ Τρύφωνος ἀπεσταλμένους ἀφικέσθαι φραξάμενοι τοῖς ὅπλοις ἐκ τῆς χώρας ἀπελθεῖν. οἱ δʼ ἐπʼ αὐτοὺς πεμφθέντες ἰδόντες ἑτοίμους ὑπὲρ τῶν ψυχῶν ἀγωνίζεσθαι μηδὲν αὐτοῖς ἐνοχλήσαντες πρὸς τὸν Τρύφωνα ὑπέστρεψαν."},{"number":194,"text":"Οἱ δʼ ἐν τοῖς Ἱεροσολύμοις ἀκούσαντες τὴν Ἰωνάθου σύλληψιν καὶ τὴν τῶν σὺν αὐτῷ στρατιωτῶν ἀπώλειαν αὐτόν τε ἐκεῖνον ἐπὶ τοῖς συμβεβηκόσιν ὠλοφύροντο καὶ δεινὴ τἀνδρὸς ἐπιζήτησις παρὰ πᾶσιν ἦν,"},{"number":195,"text":"δέος τε μέγα καὶ κατὰ λόγον αὐτοῖς ἐμπεσὸν ἐλύπει, μὴ τῆς Ἰωνάθου ἀνδρείας ἅμα καὶ προνοίας ἀφῃρημένων τὰ πέριξ ἔθνη χαλεπῶς ἔχοντα πρὸς αὐτοὺς καὶ διὰ Ἰωνάθην ἠρεμοῦντα νῦν αὐτοῖς ἐπισυστῇ καὶ πολεμοῦντες εἰς τοὺς περὶ τῶν ἐσχάτων κινδύνους ἀναγκάζωνται καθίστασθαι."},{"number":196,"text":"καὶ δὴ τοῦτʼ αὐτοῖς ὡς ὑπενόουν συνέπεσεν· τὸν γὰρ Ἰωνάθου ἀκούσαντες θάνατον οἱ ἐκ τῶν ἐθνῶν πολεμεῖν ἤρξαντο τοὺς Ἰουδαίους ὡς ἀποροῦντας ἡγεμόνος. αὐτὸς δʼ ὁ Τρύφων δύναμιν συναγαγὼν γνώμην εἶχεν ἀναβὰς εἰς τὴν Ἰουδαίαν πολεμεῖν τοὺς ἐν αὐτῇ."},{"number":197,"text":"Σίμων δʼ ὁρῶν πρὸς ταῦτα τοὺς Ἱεροσολυμίτας καταπεπληγότας, βουλόμενος αὐτοὺς εἰς τὸ ὑποστῆναι προθύμως ἐπιόντα τὸν Τρύφωνα θαρραλεωτέρους ποιῆσαι τῷ λόγῳ, συγκαλέσας τὸν δῆμον εἰς τὸν ἱερὸν ἐντεῦθεν αὐτοὺς παρακαλεῖν ἤρξατο·"},{"number":198,"text":"τὸ μὲν ὑπὲρ τῆς ὑμετέρας ἐλευθερίας, ὁμόφυλοι, μετὰ τοῦ πατρὸς ἐγώ τε καὶ οἱ ἀδελφοί μου ὡς ἐτολμήσαμεν ἀσμένως ἀποθανεῖν οὐκέτʼ ἀγνοεῖτε. παραδειγμάτων δὲ τοιούτων εὐποροῦντός μου κἀκ τοῦ θνήσκειν ὑπὲρ τῶν νόμων καὶ τῆς θρησκείας τοὺς ἐκ τῆς ἡμετέρας οἰκίας γενομένους ἡγησαμένου φόβος οὐδὲ εἷς ἔσται τηλικοῦτος, ὃς ταύτην ἡμῶν τὴν διάνοιαν ἐκβαλεῖ τῆς ψυχῆς, ἀντεισάξει δʼ εἰς αὐτὴν φιλοζωΐαν καὶ δόξης καταφρόνησιν."},{"number":199,"text":"ὅθεν ὡς οὐκ ἀποροῦντες ἡγεμόνος οἵου τε καὶ πάσχειν ὑπὲρ ὑμῶν τὰ μέγιστα καὶ δρᾶν ἕπεσθέ μοι προθύμως ἐφʼ οὓς ἂν ἡγῶμαι· οὔτε γὰρ κρείττων ἐγὼ τῶν ἀδελφῶν τῶν ἐμῶν, ἵνα φείδωμαι τῆς ἐμαυτοῦ ψυχῆς, οὔτε χείρων, ἵνʼ ὃ κάλλιστον ἐκείνοις ἔδοξεν τὸ τελευτᾶν ὑπὲρ τῶν νόμων καὶ τῆς τοῦ θεοῦ θρησκείας ὑμῶν τοῦτʼ ἐγὼ φύγω καὶ καταλίπω."},{"number":200,"text":"οἷς δέ με δεῖ γνήσιον ἐκείνων ἀδελφὸν φανῆναι τούτοις ἀδελφὸν ἐμαυτὸν ἐπιδείξω· θαρρῶ γὰρ ὡς καὶ δίκην ληψόμενος παρὰ τῶν πολεμίων καὶ πάντας ὑμᾶς μετὰ γυναικῶν καὶ τέκνων τῆς ἐξ αὐτῶν ὕβρεως ῥυσόμενος καὶ τὸ ἱερὸν ἀπόρθητον μετὰ τοῦ θεοῦ διαφυλάξων· τὰ γὰρ ἔθνη βλέπω καταφρονήσαντα ὑμῶν ὡς οὐκ ἐχόντων ἡγεμόνα πρὸς τὸ πολεμεῖν ὡρμημένα."},{"number":201,"text":"Τούτους ποιησαμένου τοῦ Σίμωνος τοὺς λόγους ἀνεθάρσησεν τὸ πλῆθος, καὶ ταῖς ψυχαῖς ἐνδεδωκὸς ὑπὸ δειλίας ἀνηγέρθη πρὸς τὴν ἀμείνω καὶ ἀγαθὴν ἐλπίδα, ὡς ἀθρόως πάντα τὸν λαὸν ἐκβοῆσαι τὸν Σίμωνα αὐτῶν ἡγεῖσθαι καὶ ἀντὶ Ἰούδου καὶ Ἰωνάθου τῶν ἀδελφῶν αὐτοῦ τὴν προστασίαν ἔχειν· ἔσεσθαι γὰρ πρὸς ὅ τι κελεύσαι πειθηνίους."},{"number":202,"text":"συναθροίσας δʼ εὐθὺς πᾶν ὅσον ἦν τὸ πολεμικὸν τῆς οἰκείας ἰσχύος ἔσπευδε τὰ τείχη τῆς πόλεως ἀνοικοδομῆσαι, καὶ πύργοις αὐτὴν ὑψηλοτάτοις καὶ καρτεροῖς ἀσφαλισάμενος ἀπέστειλεν μὲν Ἰωνάθην τινὰ φίλον Ἀψαλώμου παῖδα μετὰ στρατιᾶς εἰς Ἰόππην προστάξας αὐτῷ τοὺς οἰκήτορας ἐκβαλεῖν· ἐδεδίει γάρ, μὴ παραδῶσιν οὗτοι τὴν πόλιν τῷ Τρύφωνι. αὐτὸς δʼ ὑπομείνας ἐφύλαττε τὰ Ἱεροσόλυμα."},{"number":203,"text":"Ὁ δὲ Τρύφων ἄρας ἐκ Πτολεμαΐδος μετὰ στρατιᾶς πολλῆς εἰς τὴν Ἰουδαίαν παραγίνεται καὶ τὸν Ἰωνάθην δέσμιον ἄγων. ἀπήντησε δʼ αὐτῷ καὶ Σίμων μετὰ τῆς αὐτοῦ δυνάμεως εἰς Ἄδδιδα πόλιν, ἥτις ἐπʼ ὄρους κειμένη τυγχάνει, ὑφʼ ἧς ὑπόκειται τὰ τῆς Ἰουδαίας πεδία."},{"number":204,"text":"γνοὺς δὲ Τρύφων ἡγεμόνα τὸν Σίμωνα ὑπὸ τῶν Ἰουδαίων καθεσταμένον ἔπεμψεν πρὸς αὐτὸν καὶ τοῦτον ἀπάτῃ καὶ δόλῳ περιελθεῖν βουλόμενος, κελεύων αὐτόν, εἰ θέλει λυθῆναι τὸν ἀδελφὸν Ἰωνάθην, πέμψαι τάλαντα ἑκατὸν ἀργυρίου καὶ δύο τῶν παίδων τῶν Ἰωνάθου ὁμήρους, ὅπως μὴ ἀφεθεὶς ἀποστήσῃ τὴν Ἰουδαίαν βασιλέως· ἄρτι γὰρ αὐτὸν διὰ τὸ ἀργύριον, ὃ τῷ βασιλεῖ χρησάμενος ὤφειλε, φυλάττεσθαι δεδεμένον."},{"number":205,"text":"ὁ δὲ Σίμων τὴν τέχνην τὴν τοῦ Τρύφωνος οὐκ ἠγνόησεν, ἀλλὰ συνεὶς ὅτι καὶ τὸ ἀργύριον ἀπολέσει δοὺς καὶ τὸν ἀδελφὸν οὐ λύσει, μετʼ αὐτοῦ δὲ καὶ τοὺς παῖδας ἐκδώσει τῷ πολεμίῳ, φοβούμενος δέ, μὴ διαβληθῇ πρὸς τὸ πλῆθος ὡς αἴτιος αὐτὸς τἀδελφῷ θανάτου γενόμενος, ὅτι μήτε τὰ χρήματα μήτε τοὺς υἱοὺς ἔδωκεν ὑπὲρ αὐτοῦ, συναγαγὼν τὴν στρατιὰν ἐδήλωσεν αὐτῇ τὰ παρὰ τοῦ Τρύφωνος,"},{"number":206,"text":"εἰπὼν ὅτι ταῦτα καὶ ἐνέδραν καὶ ἐπιβουλὴν ἔχει· ὅμως αἱρετώτερον εἶναι πέμψαι τὰ χρήματʼ αὐτῷ καὶ τοὺς υἱοὺς ἢ τοῖς ὑπὸ Τρύφωνος προβαλλομένοις μὴ ὑπακούσαντα λαβεῖν αἰτίαν ὡς τὸν ἀδελφὸν σῶσαι μὴ θελήσας. καὶ Σίμων μὲν τούς τε Ἰωνάθου παῖδας ἐξέπεμψεν καὶ τὰ χρήματα."},{"number":207,"text":"λαβὼν δὲ ὁ Τρύφων οὐκ ἐτήρησεν τὴν πίστιν οὐδὲ ἀπέλυσε τὸν Ἰωνάθην, ἀλλὰ τὴν στρατιὰν ἀναλαβὼν ἐκπεριῆλθε τὴν χώραν καὶ διὰ τῆς Ἰδουμαίας ἀναβαίνειν διεγνώκει τὸ λοιπὸν εἰς Ἱεροσόλυμα, καὶ παραγενόμενος ἧκεν εἰς Ἄδωρα πόλιν τῆς Ἰδουμαίας. ἀντιπαρῆγεν δʼ ὁ Σίμων μετὰ τῆς στρατιᾶς ἀεὶ καταστρατοπεδευόμενος ἐξ ἐναντίας αὐτοῦ."},{"number":208,"text":"Τῶν δʼ ἐν τῇ ἄκρᾳ πεμψάντων πρὸς Τρύφωνα καὶ παρακαλούντων σπεῦσαι πρὸς αὐτοὺς καὶ τροφὰς αὐτοῖς πέμψαι, παρεσκεύασε τὴν ἵππον ὡς διὰ τῆς νυκτὸς ἐκείνης ἐν Ἱεροσολύμοις ἐσόμενος. ἀλλὰ χιὼν διὰ νυκτὸς πολλὴ πεσοῦσα καὶ τάς τε ὁδοὺς καλύψασα καὶ ἄπορον ἵπποις μάλιστα πεζεύειν ὑπὸ βάθους τὴν πορείαν παρασχοῦσα διεκώλυσεν αὐτὸν ἐλθεῖν εἰς τὰ Ἱεροσόλυμα."},{"number":209,"text":"διόπερ ἐκεῖθεν ἄρας ὁ Τρύφων εἰς τὴν κοίλην ἀφικνεῖται Συρίαν, σπουδῇ τε εἰς τὴν Γαλαδῖτιν ἐμβαλὼν τόν τε Ἰωνάθην ἀποκτείνας αὐτόθι καὶ ταφῆναι κελεύσας αὐτὸς εἰς τὴν Ἀντιόχειαν ὑπέστρεψεν."},{"number":210,"text":"ὁ δὲ Σίμων πέμψας εἰς Βασκὰ πόλιν μετακομίζει τὰ τοῦ ἀδελφοῦ ὀστᾶ, καὶ κηδεύει μὲν ταῦτα ἐν Μωδεεῖ τῇ πατρίδι, πένθος δʼ ἐπʼ αὐτῷ μέγα πᾶς ὁ λαὸς ἐποιήσατο."},{"number":211,"text":"Σίμων δὲ καὶ μνημεῖον μέγιστον ᾠκοδόμησεν τῷ τε πατρὶ καὶ τοῖς ἀδελφοῖς ἐκ λίθου λευκοῦ καὶ ἀνεξεσμένου. εἰς πολὺ δʼ αὐτὸ καὶ περίοπτον ἀναγαγὼν ὕψος στοὰς περὶ αὐτὸ βάλλεται καὶ στύλους μονολίθους θαυμαστὸν ἰδεῖν χρῆμα ἀνίστησιν, πρὸς τούτοις δὲ καὶ πυραμίδας ἑπτὰ τοῖς τε γονεῦσιν καὶ τοῖς ἀδελφοῖς ἑκάστῳ μίαν ᾠκοδόμησεν εἰς ἔκπληξιν μεγέθους τε ἕνεκα καὶ κάλλους πεποιημένας, αἳ καὶ μέχρι δεῦρο σώζονται."},{"number":212,"text":"καὶ περὶ μὲν τῆς Ἰωνάθου ταφῆς καὶ τῆς τῶν μνημείων οἰκοδομίας τοῖς οἰκείοις Σίμωνος τοσαύτην σπουδὴν οἴδαμεν γενομένην. ἀπέθανεν δὲ Ἰωνάθης ἀρχιερατεύων ἔτη τέσσαρα προστὰς τοῦ γένους. καὶ τὰ μὲν περὶ τῆς τούτου τελευτῆς ἐν τούτοις ἦν."},{"number":213,"text":"Σίμων δὲ κατασταθεὶς ἀρχιερεὺς ὑπὸ τοῦ πλήθους τῷ πρώτῳ τῆς ἀρχιερωσύνης ἔτει τῆς ἐπὶ τοῖς Μακεδόσι δουλείας τὸν λαὸν ἠλευθέρωσεν ὡς μηκέτι φόρους αὐτοῖς τελεῖν· ἡ δὲ ἐλευθερία καὶ τὸ ἀνείσφορον τοῖς Ἰουδαίοις μετὰ ἑβδομήκοντα καὶ ἑκατὸν ἔτη τῶν Συρίας βασιλέων ἐξ οὗ χρόνου Σέλευκος ὁ Νικάτωρ ἐπικληθεὶς κατέσχεν Συρίαν ὑπῆρξεν."},{"number":214,"text":"τοσαύτη δʼ ἦν ἡ τοῦ πλήθους περὶ τὸν Σίμωνα φιλοτιμία, ὥστʼ ἐν τοῖς πρὸς ἀλλήλους συμβολαίοις καὶ τοῖς δημοσίοις γράμμασιν ἐπὶ πρώτου ἔτους γράφειν Σίμωνος καὶ εὐεργέτου Ἰουδαίων καὶ ἐθνάρχου· εὐτύχησαν γὰρ ἐπʼ αὐτοῦ σφόδρα καὶ τῶν ἐχθρῶν τῶν περιοίκων ἐκράτησαν."},{"number":215,"text":"κατεστρέψατο γὰρ Σίμων Γάζαρά τε πόλιν καὶ Ἰόππην καὶ Ἰάμνειαν, ἐκπολιορκήσας δὲ καὶ τὴν ἐν τοῖς Ἱεροσολύμοις ἄκραν εἰς ἔδαφος αὐτὴν καθεῖλεν, ὡς ἂν μὴ τοῖς ἐχθροῖς ὁρμητήριον ᾖ καταλαμβανομένοις αὐτὴν τοῦ κακῶς ποιεῖν, ὡς καὶ τότε. καὶ τοῦτο ποιήσας ἄριστον ἐδόκει καὶ συμφέρον καὶ τὸ ὄρος ἐφʼ οὗ τὴν ἄκραν εἶναι συνέβαινεν καθελεῖν, ὅπως ὑψηλότερον ᾖ τὸ ἱερόν."},{"number":216,"text":"καὶ δὴ τοῦτʼ ἔπειθεν εἰς ἐκκλησίαν καλέσας τὸ πλῆθος ὑπʼ αὐτοῦ γίνεσθαι, ὧν τε ἔπαθον ὑπὸ τῶν φρουρῶν καὶ τῶν φυγάδων Ἰουδαίων ὑπομιμνήσκων, ἅ τε πάθοιεν ἄν, εἰ πάλιν κατάσχοι τὴν βασιλείαν ἀλλόφυλος φρουρᾶς ἐν αὐτῇ κατασταθείσης."},{"number":217,"text":"ταῦτα λέγων πείθει τὸ πλῆθος παραινῶν αὐτῷ τὰ συμφέροντα. καὶ πάντες προσβαλόντες καθῄρουν τὸ ὄρος καὶ μήτε νυκτὸς μήθʼ ἡμέρας ἀπολυόμενοι τοῦ ἔργου τρισὶν αὐτὸ τοῖς πᾶσιν ἔτεσιν κατήγαγον εἰς ἔδαφος καὶ πεδινὴν λειότητα. καὶ τὸ λοιπὸν ἐξεῖχεν ἁπάντων τὸ ἱερὸν τῆς ἄκρας καὶ τοῦ ὄρους ἐφʼ ᾧ ἦν καθῃρημένων. καὶ τὰ μὲν ἐπὶ Σίμωνος πραχθέντα τοῦτον εἶχεν τὸν τρόπον."}],"7":[{"number":218,"text":"Μετʼ οὐ πολὺ δὲ τῆς αἰχμαλωσίας τῆς Δημητρίου τὸν Ἀλεξάνδρου υἱὸν Ἀντίοχον, ὃς καὶ Θεὸς ἐπεκλήθη, Τρύφων διέφθειρεν ἐπιτροπεύων αὐτοῦ τέσσαρα βασιλεύσαντα ἔτη. καὶ τὸν μέν, ὡς χειριζόμενος ἀποθάνοι, διήγγειλεν·"},{"number":219,"text":"τοὺς δὲ φίλους καὶ τοὺς οἰκειοτάτους διέπεμπε πρὸς τοὺς στρατιώτας, ἐπαγγελλόμενος αὐτοῖς χρήματα πολλὰ δώσειν, εἰ βασιλέα χειροτονήσουσιν αὐτόν, Δημήτριον μὲν ὑπὸ Πάρθων αἰχμάλωτον γεγονέναι μηνύων, τὸν δʼ ἀδελφὸν αὐτοῦ Ἀντίοχον παρελθόντα εἰς τὴν ἀρχὴν πολλὰ ποιήσειν αὐτοῖς κακὰ τῆς ἀποστάσεως ἀμυνόμενον."},{"number":220,"text":"οἱ δʼ ἐλπίσαντες εὐπορίαν ἐκ τῆς Τρύφωνι δοθείσης βασιλείας ἀποδεικνύουσιν αὐτὸν ἄρχοντα. γενόμενος δὲ τῶν πραγμάτων ἐγκρατὴς ὁ Τρύφων διέδειξεν τὴν αὐτοῦ φύσιν οὖσαν πονηράν· ἰδιώτης μὲν γὰρ ὢν ἐθεράπευεν τὸ πλῆθος καὶ μετριότητα ὑπεκρίνατο δελεάζων αὐτὸ τούτοις εἰς ἅπερ ἐβούλετο, τὴν δὲ βασιλείαν λαβὼν ἀπεδύσατο τὴν ὑπόκρισιν καὶ ὁ ἀληθὴς Τρύφων ἦν."},{"number":221,"text":"τοὺς οὖν ἐχθροὺς διὰ ταῦτʼ ἐποίει κρείττονας· τὸ μὲν γὰρ στρατιωτικὸν αὐτὸν μισοῦν ἀφίστατο πρὸς Κλεοπάτραν τὴν Δημητρίου γυναῖκα τότε ἐν Σελευκείᾳ μετὰ τῶν τέκνων ἐγκεκλεισμένην."},{"number":222,"text":"ἀλωμένου δὲ καὶ Ἀντιόχου τοῦ Δημητρίου ἀδελφοῦ, ὃς ἐπεκαλεῖτο Σωτήρ, καὶ μηδεμιᾶς αὐτὸν πόλεως δεχομένης διὰ Τρύφωνα, πέμπει πρὸς αὐτὸν Κλεοπάτρα καλοῦσα πρὸς αὐτὴν ἐπί τε γάμῳ καὶ βασιλείᾳ. ἐκάλει δὲ τὸν Ἀντίοχον ἐπὶ τούτοις ἅμα μὲν τῶν φίλων αὐτὴν ἀναπεισάντων, ἅμα δὲ καὶ τὴν πόλιν ἐνδιδόντων τινῶν ἐκ τῆς Σελευκείας τῷ Τρύφωνι δείσασα."},{"number":223,"text":"Γενόμενος δʼ ἐν τῇ Σελευκείᾳ ὁ Ἀντίοχος καὶ τῆς ἰσχύος αὐτῷ καθʼ ἡμέραν αὐξανομένης ὥρμησε πολεμήσων τὸν Τρύφωνα, καὶ κρατήσας αὐτοῦ τῇ μάχῃ τῆς ἄνω Συρίας ἐξέβαλεν εἰς τὴν Φοινίκην διώξας ἄχρι ταύτης εἴς τε Δῶρα φρούριόν τι δυσάλωτον ἐπολιόρκει συμφυγόντα. πέμπει δὲ καὶ πρὸς Σίμωνα τὸν τῶν Ἰουδαίων ἀρχιερέα περὶ φιλίας καὶ συμμαχίας πρέσβεις."},{"number":224,"text":"ὁ δὲ προσδέχεται προθύμως αὐτοῦ τὴν ἀξίωσιν, καὶ χρήματά τε πολλὰ καὶ τροφὴν τοῖς τὰ Δῶρα στρατιώταις πολιορκοῦσι πέμψας τὸν Ἀντίοχον ἀφθόνως ἐχορήγησεν, ὡς τῶν ἀναγκαιοτάτων αὐτῷ πρὸς ὀλίγον καιρὸν κριθῆναι φίλων. ὁ μὲν γὰρ Τρύφων ἐκ τῆς Δώρας φυγὼν εἰς Ἀπάμειαν καὶ ληφθεὶς ἐν αὐτῇ πολιορκίᾳ διεφθάρη βασιλεύσας ἔτη τρία."},{"number":225,"text":"Ὁ δʼ Ἀντίοχος ὑπὸ πλεονεξίας καὶ φαυλότητος λήθην τῶν ἐκ Σίμωνος αὐτῷ πρὸς τὰς χρείας ὑπηρετηθέντων ἐποιήσατο, καὶ δύναμιν στρατιωτικὴν Κενδεβαίῳ παραδοὺς τῶν φίλων ἐπὶ τὴν τῆς Ἰουδαίας πόρθησιν καὶ τὴν Σίμωνος ἅλωσιν ἐξαπέστειλεν."},{"number":226,"text":"Σίμων δʼ ἀκούσας τὴν Ἀντιόχου παρανομίαν καὶ πρεσβύτερος ὢν ἤδη ὅμως ὑπὸ τοῦ μὴ δικαίων τῶν παρʼ Ἀντιόχου γινομένων τυγχάνειν παρορμηθεὶς καὶ τῆς ἡλικίας φρόνημα κρεῖττον λαβὼν νεανικῶς ἐστρατήγει τοῦ πολέμου."},{"number":227,"text":"καὶ τοὺς μὲν υἱεῖς μετὰ τῶν μαχιμωτέρων προεκπέμπει στρατιωτῶν, αὐτὸς δὲ κατʼ ἄλλο μέρος προῄει μετὰ τῆς δυνάμεως, καὶ πολλοὺς ἐν τοῖς φαραγγώδεσι τῶν ὀρῶν τούτους εἰς ἐνέδραν καταστήσας διαμαρτάνει μὲν οὐδεμιᾶς τῶν ἐπιχειρήσεων, κρατήσας δὲ διὰ πάσης τῶν πολεμίων ἐν εἰρήνῃ τὸν λοιπὸν διήγαγεν χρόνον, ποιησάμενος καὶ αὐτὸς πρὸς Ῥωμαίους συμμαχίαν."},{"number":228,"text":"Ἦρξε μὲν οὖν ὀκτὼ τὰ πάντα τῶν Ἰουδαίων ἔτη, τελευτᾷ δὲ ἐξ ἐπιβουλῆς ἐν συμποσίῳ Πτολεμαίου τοῦ γαμβροῦ ταύτην ἐπʼ αὐτὸν συστησαμένου, ὃς καὶ τὴν γυναῖκα αὐτοῦ καὶ τοὺς δύο παῖδας συλλαβὼν καὶ δεδεμένους ἔχων ἔπεμψεν καὶ ἐπὶ Ἰωάννην τὸν τρίτον, τούτῳ δὲ καὶ Ὑρκανὸς ἦν ὄνομα, τοὺς διαφθεροῦντας."},{"number":229,"text":"αἰσθόμενος δὲ τοὺς ἐλθόντας ὁ νεανίσκος διαφυγὼν τὸν ἐξ αὐτῶν κίνδυνον εἰς τὴν πόλιν ἠπείγετο, θαρρῶν τῷ πλήθει διὰ τὰς τοῦ πατρὸς εὐεργεσίας καὶ διὰ τὸ Πτολεμαίου τοῖς ὄχλοις μῖσος. σπουδάσαντα δὲ καὶ Πτολεμαῖον εἰσελθεῖν διʼ ἄλλης πύλης ὁ δῆμος ἀπεώσατο τὸν Ὑρκανὸν ἤδη προσδεδεγμένος."}],"8":[{"number":230,"text":"Καὶ ὁ μὲν εἰς ἕν τι τῶν ὑπὲρ Ἱεριχοῦντος ἐρυμάτων ἀνεχώρησεν Δαγὼν λεγόμενον. ἀπολαβὼν δὲ τὴν πάτριον ἀρχιερωσύνην Ὑρκανὸς καὶ τὸν θεὸν πρώταις θυσίαις παραστησάμενος ἐπὶ τὸν Πτολεμαῖον ἐξεστράτευσεν, καὶ προσβαλὼν τῷ χωρίῳ τοῖς μὲν ἄλλοις περιῆν αὐτοῦ, ἡττᾶτο δὲ μόνῳ τῷ πρὸς τὴν μητέρα καὶ τοὺς ἀδελφοὺς οἴκτῳ."},{"number":231,"text":"τούτους γὰρ Πτολεμαῖος ἀναγαγὼν ἐπὶ τὸ τεῖχος ἐξ ἀπόπτου ᾐκίζετο καὶ κατακρημνίσειν οὐκ ἀφισταμένου τῆς πολιορκίας ἠπείλει. ὁ δʼ ὅσον ἂν ἐνδοίη τῆς περὶ τὴν αἵρεσιν τοῦ χωρίου σπουδῆς, τοσοῦτο χαρίζεσθαι τοῖς φιλτάτοις ἡγούμενος πρὸς τὸ μὴ κακῶς πάσχειν, ἐξέλυε τὸ πρόθυμον."},{"number":232,"text":"ἡ μέντοι μήτηρ ὀρέγουσα τὰς χεῖρας ἱκέτευε μὴ μαλακίζεσθαι διʼ αὐτήν, ἀλλὰ πολὺ πλέον ὀργῇ χρώμενον ἑλεῖν σπουδάσαι τὸ χωρίον καὶ τὸν ἐχθρὸν ὑπʼ αὐτῷ ποιήσαντα τιμωρῆσαι τοῖς φιλτάτοις· ἡδὺν γὰρ αὐτῇ τὸν μετʼ αἰκίας εἶναι θάνατον, εἰ δίκην ὑπόσχοι τῆς εἰς αὐτοὺς παρανομίας ὁ ταῦτα ποιῶν πολέμιος."},{"number":233,"text":"τὸν δὲ Ὑρκανὸν ταῦτα μὲν λεγούσης τῆς μητρὸς ὁρμή τις ἐλάμβανεν πρὸς τὴν αἵρεσιν τοῦ φρουρίου, ἡνίκα δʼ αὐτὴν ἴδοι τυπτομένην καὶ σπαραττομένην, ἐξελύετο καὶ τῆς ἐπὶ τοῖς εἰς τὴν μητέρα πραττομένοις συμπαθείας ἥττων ἐγίνετο."},{"number":234,"text":"ἑλκομένης δʼ οὕτως εἰς χρόνον τῆς πολιορκίας ἐνίσταται τὸ ἔτος ἐκεῖνο, καθʼ ὃ συμβαίνει τοὺς Ἰουδαίους ἀργεῖν· κατὰ δὲ ἑπτὰ ἔτη τοῦτο παρατηροῦσιν, ὡς ἐν ταῖς ἑβδομάσιν ἡμέραις."},{"number":235,"text":"καὶ Πτολεμαῖος, ὑπὸ ταύτης ἀνεθεὶς τοῦ πολέμου τῆς αἰτίας ἀποκτείνει τοὺς ἀδελφοὺς τοῦ Ὑρκανοῦ καὶ τὴν μητέρα καὶ τοῦτο δράσας πρὸς Ζήνωνα φεύγει τὸν ἐπικληθέντα Κοτυλᾶν, τυραννεύοντα τῆς Φιλαδελφέων πόλεως."},{"number":236,"text":"Ἀντίοχος δὲ χαλεπῶς ἔχων ἐφʼ οἷς ὑπὸ Σίμωνος ἔπαθεν εἰς τὴν Ἰουδαίαν ἐνέβαλεν τετάρτῳ μὲν ἔτει τῆς βασιλείας αὐτοῦ, πρώτῳ δὲ τῆς Ὑρκανοῦ ἀρχῆς, ὀλυμπιάδι ἑκατοστῇ καὶ ἑξηκοστῇ καὶ δευτέρᾳ."},{"number":237,"text":"δῃώσας δὲ τὴν χώραν τὸν Ὑρκανὸν εἰς αὐτὴν ἐνέκλεισε τὴν πόλιν, ἣν ἑπτὰ στρατοπέδοις περιλαβὼν ἤνυσε μὲν οὐδὲν ὅλως τὸ πρῶτον διά τε τὴν τῶν τειχῶν ὀχυρότητα καὶ διʼ ἀρετὴν τῶν ἐμπολιορκουμένων ἔτι γε μὴν ὕδατος ἀπορίαν, ἧς αὐτοὺς ἀπέλυσεν ὄμβρος κατενεχθεὶς πολὺς δυομένης πλειάδος."},{"number":238,"text":"κατὰ δὲ τὸ βόρειον μέρος τοῦ τείχους, καθʼ ὃ συνέβαινεν αὐτὸ καὶ ἐπίπεδον εἶναι, πύργους ἀναστήσας ἑκατὸν τριωρόφους ἀνεβίβασεν ἐπʼ αὐτοὺς στρατιωτικὰ τάγματα."},{"number":239,"text":"καὶ προσβολὰς ὁσημέραι ποιησάμενος τάφρον τε βαθεῖαν καὶ πολλὴν τὸ εὖρος καὶ διπλῆν τεμόμενος, ἀπετείχισεν τοὺς ἐνοικοῦντας. οἱ δὲ πολλὰς ἐκδρομὰς ἀντεπινοοῦντες, εἰ μὲν ἀφυλάκτοις που προσπέσοιεν τοῖς πολεμίοις, πολλὰ ἔδρων αὐτούς, αἰσθομένων δὲ ἀνεχώρουν εὐχερῶς."},{"number":240,"text":"ἐπεὶ δὲ βλαβερὰν κατενόησεν Ὑρκανὸς τὴν πολυανθρωπίαν, ἀναλισκομένων τε τῶν ἐπιτηδείων τάχιον ὑπʼ αὐτῆς καὶ μηδενὸς οἷον εἰκὸς ἐκ πολυχειρίας ἔργου γιγνομένου, τὸ μὲν ἀχρεῖον αὐτῆς ἀποκρίνας ἐξέβαλεν, ὅσον δʼ ἦν ἀκμαῖον καὶ μάχιμον τοῦτο μόνον κατέσχεν."},{"number":241,"text":"Ἀντίοχος μὲν οὖν τοὺς ἀπολεχθέντας ἐξελθεῖν ἐκώλυεν, οἱ δʼ ἐν τοῖς μεταξὺ τείχεσι κακούμενοι ταῖς βασάνοις ἀπέθνησκον οἰκτρῶς. ἐπιστάσης γε μὴν τῆς σκηνοπηγίας ἑορτῆς ἐλεοῦντες αὐτοὺς οἱ ἐντὸς πάλιν εἰσεδέξαντο."},{"number":242,"text":"πέμψαντος δʼ Ὑρκανοῦ πρὸς Ἀντίοχον καὶ σπονδὰς ἡμερῶν ἑπτὰ διὰ τὴν ἑορτὴν ἀξιώσαντος γενέσθαι, τῇ πρὸς τὸ θεῖον εὐσεβείᾳ εἴκων σπένδεται καὶ προσέτι θυσίαν εἰσέπεμψε μεγαλοπρεπῆ, ταύρους χρυσοκέρωτας καὶ μεστὰ παντοίων ἀρωμάτων ἐκπώματα χρύσεά τε καὶ ἀργύρεα."},{"number":243,"text":"καὶ τὴν μὲν θυσίαν δεξάμενοι παρὰ τῶν κομιζόντων οἱ πρὸς ταῖς πύλαις ὄντες ἄγουσιν εἰς τὸ ἱερόν, Ἀντίοχος δὲ τὴν στρατιὰν εἱστία, πλεῖστον Ἀντιόχου τοῦ Ἐπιφανοῦς διενέγκας, ὃς τὴν πόλιν ἑλὼν ὗς μὲν κατέθυσεν ἐπὶ τὸν βωμόν, τὸν νεὼν δὲ τῷ ζωμῷ τούτων περιέρρανε συγχέας τὰ Ἰουδαίων νόμιμα καὶ τὴν πάτριον αὐτῶν εὐσέβειαν, ἐφʼ οἷς ἐξεπολεμώθη τὸ ἔθνος καὶ ἀκαταλλάκτως εἶχεν."},{"number":244,"text":"τοῦτον μέντοι τὸν Ἀντίοχον διʼ ὑπερβολὴν τῆς θρησκείας Εὐσεβῆ πάντες ἐκάλεσαν."},{"number":245,"text":"Ἀποδεξάμενος δὲ αὐτοῦ τὴν ἐπιείκειαν Ὑρκανὸς καὶ μαθὼν τὴν περὶ τὸ θεῖον σπουδὴν ἐπρεσβεύσατο πρὸς αὐτόν, ἀξιῶν τὴν πάτριον αὐτοῖς πολιτείαν ἀποδοῦναι. ὁ δὲ ἀπωσάμενος τὴν ἐπιβουλὴν τῶν μὲν παραινούντων ἐξελεῖν τὸ ἔθνος διὰ τὴν πρὸς ἄλλους αὐτῶν τῆς διαίτης ἀμιξίαν οὐκ ἐφρόντιζεν,"},{"number":246,"text":"πειθόμενος δὲ κατʼ εὐσέβειαν πάντα ποιεῖν τοῖς πρεσβευταῖς ἀπεκρίνατο, παραδοῦναι μὲν τὰ ὅπλα τοὺς πολιορκουμένους καὶ δασμὸν αὐτῷ τελεῖν Ἰόππης καὶ τῶν ἄλλων πόλεων πάρεξ τῆς Ἰουδαίας φρουράν τε δεξαμένους ἐπὶ τούτοις ἀπηλλάχθαι τοῦ πολέμου."},{"number":247,"text":"οἱ δὲ τἆλλα μὲν ὑπομένειν, τὴν δὲ φρουρὰν οὐχ ὡμολόγουν διὰ τὴν ἀμιξίαν οὐκ ἐφικνούμενοι πρὸς ἄλλους. ἀντὶ μέντοι γε τῆς φρουρᾶς ὁμήρους ἐδίδοσαν καὶ τάλαντα ἀργυρίου πεντακόσια, ὧν εὐθὺς τὰ τριακόσια καὶ τοὺς ὁμήρους προσδεξαμένου τοῦ βασιλέως ἔδοσαν, ἐν οἷς ἦν καὶ Ὑρκανοῦ ἀδελφός, καθεῖλεν δὲ καὶ τὴν στεφάνην τῆς πόλεως."},{"number":248,"text":"ἐπὶ τούτοις μὲν οὖν Ἀντίοχος τὴν πολιορκίαν λύσας ἀνεχώρησεν."},{"number":249,"text":"Ὑρκανὸς δὲ τὸν Δαυίδου τάφον ἀνοίξας, ὃς πλούτῳ τούς ποτε βασιλεῖς ὑπερέβαλεν, τρισχίλια μὲν ἀργυρίου τάλαντα ἐξεκόμισεν, ὁρμώμενος δʼ ὑπὸ τούτων πρῶτος Ἰουδαίων ξενοτροφεῖν ἤρξατο."},{"number":250,"text":"γίνεται δʼ αὐτῷ καὶ πρὸς Ἀντίοχον φιλία καὶ συμμαχία, καὶ δεξάμενος αὐτὸν εἰς τὴν πόλιν ἀφθόνως πάντα τῇ στρατιᾷ καὶ φιλοτίμως παρέσχεν. καὶ ποιουμένῳ τὴν ἐπὶ Πάρθους αὐτῷ στρατείαν συνεξώρμησεν Ὑρκανός. μάρτυς δὲ τούτων ἡμῖν ἐστιν καὶ Νικόλαος ὁ Δαμασκηνὸς οὕτως ἱστορῶν·"},{"number":251,"text":"τρόπαιον δὲ στήσας Ἀντίοχος ἐπὶ τῷ Λύκῳ ποταμῷ νικήσας Ἰνδάτην τὸν Πάρθων στρατηγὸν αὐτόθι ἔμεινεν ἡμέρας δύο δεηθέντος Ὑρκανοῦ τοῦ Ἰουδαίου διά τινα ἑορτὴν πάτριον, ἐν ᾗ τοῖς Ἰουδαίοις οὐκ ἦν νόμιμον ἐξοδεύειν. καὶ ταῦτα μὲν οὐ ψεύδεται λέγων·"},{"number":252,"text":"ἐνέστη γὰρ ἡ πεντηκοστὴ ἑορτὴ μετὰ τὸ σάββατον, οὐκ ἔξεστι δʼ ἡμῖν οὔτε τοῖς σαββάτοις οὔτʼ ἐν τῇ ἑορτῇ ὁδεύειν."},{"number":253,"text":"συμβαλὼν δʼ Ἀντίοχος Ἀρσάκῃ τῷ Πάρθῳ πολλήν τε τῆς στρατιᾶς ἀπέβαλεν καὶ αὐτὸς ἀπόλλυται, τὴν δὲ τῶν Σύρων βασιλείαν ὁ ἀδελφὸς αὐτοῦ διαδέχεται Δημήτριος Ἀρσάκου αὐτὸν ἐκ τῆς αἰχμαλωσίας ἀπολύσαντος καθʼ ὃν χρόνον Ἀντίοχος εἰς τὴν Παρθυηνὴν ἐνέβαλεν, ὡς καὶ πρότερον ἐν ἄλλοις δεδήλωται."}],"9":[{"number":254,"text":"Ὑρκανὸς δὲ ἀκούσας τὸν Ἀντιόχου θάνατον εὐθὺς ἐπὶ τὰς ἐν Συρίᾳ πόλεις ἐξεστράτευσεν οἰόμενος αὐτὰς εὑρήσειν, ὅπερ ἦν, ἐρήμους τῶν μαχίμων καὶ ῥύεσθαι δυναμένων."},{"number":255,"text":"Μήδαβαν μὲν οὖν πολλὰ τῆς στρατιᾶς αὐτῷ ταλαιπωρηθείσης ἕκτῳ μηνὶ εἷλεν, ἔπειτα καὶ Σαμόγαν καὶ τὰ πλησίον εὐθὺς αἱρεῖ Σίκιμά τε πρὸς τούτοις καὶ Γαριζεὶν τό τε Κουθαίων γένος,"},{"number":256,"text":"ὃ περιοικεῖ τὸν εἰκασθέντα τῷ ἐν Ἱεροσολύμοις ἱερῷ ναόν, ὃν Ἀλέξανδρος ἐπέτρεψεν οἰκοδομῆσαι Σαναβαλλέτῃ τῷ στρατηγῷ διὰ τὸν γαμβρὸν Μανασσῆν τὸν Ἰαδδοῦς τοῦ ἀρχιερέως ἀδελφόν, ὡς πρότερον δεδηλώκαμεν. συνέβη δὲ τὸν ναὸν τοῦτον ἔρημον γενέσθαι μετὰ ἔτη διακόσια."},{"number":257,"text":"Ὑρκανὸς δὲ καὶ τῆς Ἰδουμαίας αἱρεῖ πόλεις Ἄδωρα καὶ Μάρισαν, καὶ ἅπαντας τοὺς Ἰδουμαίους ὑπὸ χεῖρα ποιησάμενος ἐπέτρεψεν αὐτοῖς μένειν ἐν τῇ χώρᾳ, εἰ περιτέμνοιντο τὰ αἰδοῖα καὶ τοῖς Ἰουδαίων νόμοις χρήσασθαι θέλοιεν."},{"number":258,"text":"οἱ δὲ πόθῳ τῆς πατρίου γῆς καὶ τὴν περιτομὴν καὶ τὴν ἄλλην τοῦ βίου δίαιταν ὑπέμειναν τὴν αὐτὴν Ἰουδαίοις ποιήσασθαι. κἀκείνοις αὐτοῖς χρόνος ὑπῆρχεν ὥστε εἶναι τὸ λοιπὸν Ἰουδαίους."},{"number":259,"text":"Ὑρκανὸς δὲ ὁ ἀρχιερεὺς ἀνανεώσασθαι τὴν πρὸς Ῥωμαίους φιλίαν βουλόμενος πέμπει πρὸς αὐτοὺς πρεσβείαν. καὶ ἡ σύγκλητος δεξαμένη τὰ παρʼ αὐτοῦ γράμματα ποιεῖται πρὸς αὐτὸν φιλίαν τούτῳ τῷ τρόπῳ·"},{"number":260,"text":"Φάννιος Μάρκου υἱὸς στρατηγὸς βουλὴν ἤγαγεν πρὸ ὀκτὼ εἰδῶν Φεβρουαρίων ἐν Κομιτίῳ παρόντος Λουκίου Μαννίου Λουκίου υἱοῦ Μεντίνα καὶ Γαΐου Σεμπρωνίου πενναίου υἱοῦ Φαλέρνα περὶ ὧν ἐπρέσβευσεν Σίμων Δοσιθέου καὶ Ἀπολλώνιος Ἀλεξάνδρου καὶ Διόδωρος Ἰάσονος ἄνδρες καλοὶ καὶ ἀγαθοὶ πεμφθέντες ὑπὸ δήμου τοῦ Ἰουδαίων,"},{"number":261,"text":"οἳ καὶ διελέχθησαν περὶ φιλίας τῆς ὑπαρχούσης τούτοις καὶ συμμαχίας πρὸς Ῥωμαίους καὶ τῶν δημοσίων πραγμάτων, ὅπως τε Ἰόππη καὶ λιμένες καὶ Γάζωρα καὶ πηγαὶ καὶ ὅσας πόλεις αὐτῶν ἄλλας καὶ χωρία πολεμῶν ἔλαβεν Ἀντίοχος παρὰ τὸ τῆς συγκλήτου δόγμα ταῦτα ἀποκατασταθῇ,"},{"number":262,"text":"ἵνα τε τοῖς στρατιώταις τοῖς βασιλικοῖς μὴ ἐξῇ διὰ τῆς χώρας τῆς αὐτῶν καὶ τῶν ὑπηκόων αὐτῶν διέρχεσθαι, καὶ ὅπως τὰ κατὰ τὸν πόλεμον ἐκεῖνον ψηφισθέντα ὑπὸ Ἀντιόχου παρὰ τὸ τῆς συγκλήτου δόγμα ἄκυρα γένηται,"},{"number":263,"text":"ἵνα τε πρέσβεις πέμψαντες ἀποδοθῆναί τε αὐτοῖς ποιήσωσιν τὰ ὑπʼ Ἀντιόχου ἀφαιρεθέντα καὶ τὴν χώραν διατιμήσωνται τὴν ἐν τῷ πολέμῳ διεφθαρμένην, ὅπως τε αὐτοῖς πρός τε βασιλεῖς καὶ δήμους ἐλευθέρους γράμματα δῶσιν εἰς ἀσφάλειαν τῆς εἰς οἶκον ἐπανόδου."},{"number":264,"text":"ἔδοξεν οὖν περὶ τούτων ταῦτα· ἀνανεώσασθαι φιλίαν καὶ συμμαχίαν πρὸς ἄνδρας ἀγαθοὺς καὶ ὑπὸ δήμου πεμφθέντας ἀγαθοῦ καὶ φίλου."},{"number":265,"text":"περὶ μέντοι γραμμάτων ἀπεκρίναντο βουλεύσεσθαι, ὅταν ἀπὸ τῶν ἰδίων ἡ σύγκλητος εὐσχολήσῃ, σπουδάσειν τε τοῦ λοιποῦ μηδὲν εἰς αὐτοὺς ἀδίκημα τοιοῦτο γενέσθαι, δοῦναί τε αὐτοῖς τὸν στρατηγὸν Φάννιον χρήματα ἐκ τοῦ δημοσίου, ὅπως ἂν εἰς τὴν οἰκείαν ἐπανέλθοιεν."},{"number":266,"text":"Φάννιος μὲν οὖν οὕτως ἀποπέμπει τοὺς τῶν Ἰουδαίων πρέσβεις χρήματά τε δοὺς αὐτοῖς ἐκ τοῦ δημοσίου καὶ δόγμα συγκλήτου πρὸς τοὺς διαπέμψοντας καὶ ἀσφαλῆ παρεξομένους τὴν οἴκαδε παρουσίαν."},{"number":267,"text":"Τὰ μὲν οὖν περὶ Ὑρκανὸν τὸν ἀρχιερέα ἐν τούτοις ὑπῆρχεν, Δημητρίῳ δὲ τῷ βασιλεῖ προθυμουμένῳ στρατεύειν ἐπὶ Ὑρκανὸν οὐκ ἐξεγένετο καιρὸς οὐδὲ ἀφορμὴ τῶν τε Σύρων καὶ τῶν στρατιωτῶν πρὸς αὐτὸν ἀπεχθανομένων, πονηρὸς γὰρ ἦν, καὶ πεμψάντων πρὸς Πτολεμαῖον τὸν Φύσκωνα ἐπικληθέντα πρέσβεις, ὅπως τινὰ τῶν ἐκ τοῦ Σελεύκου γένους παραδῷ αὐτοῖς ἀποληψόμενον τὴν βασιλείαν."},{"number":268,"text":"τοῦ δὲ Πτολεμαίου πέμψαντος Ἀλέξανδρον μετὰ στρατιᾶς τὸν Ζεβίναν ἐπιλεγόμενον καὶ μάχης πρὸς τὸν Δημήτριον γενομένης, ὁ μὲν ἡττηθεὶς τῇ μάχῃ φεύγει πρὸς Κλεοπάτραν τὴν γυναῖκα εἰς Πτολεμαΐδα καὶ μὴ δεξαμένης αὐτὸν τῆς γυναικὸς ἐκεῖθεν ἀπελθὼν εἰς Τύρον ἁλίσκεται καὶ πολλὰ παθὼν ὑπὸ τῶν μισούντων ἀπέθανεν."},{"number":269,"text":"Ἀλέξανδρος δὲ τὴν βασιλείαν παραλαβὼν φιλίαν ποιεῖται πρὸς Ὑρκανὸν τὸν ἀρχιερέα. ἔπειτα πολεμήσαντος αὐτῷ τοῦ Δημητρίου παιδὸς Ἀντιόχου τοῦ Γρυποῦ ἐπικληθέντος, ἡττηθεὶς τῇ μάχῃ διαφθείρεται."}],"10":[{"number":270,"text":"Παραλαβὼν δὲ τὴν τῆς Συρίας βασιλείαν ὁ Ἀντίοχος ἐπὶ μὲν τὴν Ἰουδαίαν στρατεύειν εὐλαβὴς ἦν τὸν ἀδελφὸν ἀκούων τὸν ὁμομήτριον, Ἀντίοχος δὲ κἀκεῖνος ἐκαλεῖτο, δύναμιν ἐπʼ αὐτὸν ἀπὸ Κυζίκου συλλέγειν."},{"number":271,"text":"μένων δὲ κατὰ χώραν ἔγνω παρασκευάζειν αὑτὸν πρὸς τὴν ἔφοδον τὴν τἀδελφοῦ, ὃς Κυζικηνὸς μὲν ἐπεκλήθη διὰ τὸ τραφῆναι ἐν ταύτῃ τῇ πόλει, πατρὸς δʼ ἦν Ἀντιόχου τοῦ Σωτῆρος ἐπικληθέντος, ὃς ἐν Πάρθοις ἀπέθανεν· οὗτος δὲ ἀδελφὸς ἦν Δημητρίου τοῦ Γρυποῦ πατρός. συνέβη μέντοι μίαν τοῖς δυσὶν ἀδελφοῖς γῆμαι Κλεοπάτραν, ὡς καὶ ἐν ἄλλοις ἱστορήκαμεν."},{"number":272,"text":"ὁ δὲ Κυζικηνὸς Ἀντίοχος παραγενόμενος εἰς τὴν Συρίαν πολλοῖς ἔτεσιν πρὸς τὸν ἀδελφὸν πολεμῶν διετέλει. Ὑρκανὸς δὲ πάντα ἐκεῖνον τὸν χρόνον ἐν εἰρήνῃ διῆγεν·"},{"number":273,"text":"καὶ γὰρ αὐτὸς μετὰ τὴν Ἀντιόχου τελευτὴν τῶν Μακεδόνων ἀπέστη καὶ οὔτε ὡς ὑπήκοος οὔτε ὡς φίλος αὐτοῖς οὐδὲν ἔτι παρεῖχεν, ἀλλʼ ἦν αὐτῷ τὰ πράγματα ἐν ἐπιδόσει πολλῇ καὶ ἀκμῇ κατὰ τοὺς Ἀλεξάνδρου τοῦ Ζαβιναίου καιρούς, καὶ μάλιστʼ ἐπὶ τούτοις τοῖς ἀδελφοῖς. ὁ γὰρ πρὸς ἀλλήλους αὐτοῖς πόλεμος σχολὴν Ὑρκανῷ καρποῦσθαι τὴν Ἰουδαίαν ἐπʼ ἀδείας παρεῖχεν, ὡς ἄπειρόν τι χρημάτων πλῆθος συναγαγεῖν."},{"number":274,"text":"τοῦ μέντοι γε Κυζικηνοῦ τὴν γῆν κακοῦντος φανερῶς καὶ αὐτὸς τὴν αὐτοῦ προαίρεσιν ἐπεδείκνυτο, καὶ τῶν ἀπʼ Αἰγύπτου συμμάχων ἔρημον ὁρῶν τὸν Ἀντίοχον καὶ αὐτόν τε πράττοντα κακῶς καὶ τὸν ἀδελφὸν αὐτοῦ ἐν τοῖς πρὸς ἀλλήλους ἀγῶσιν, ἀμφοτέρων κατεφρόνησεν."},{"number":275,"text":"Καὶ στρατεύει μὲν ἐπὶ Σαμάρειαν πόλιν ὀχυρωτάτην, περὶ ἧς, ὅτι καλεῖται νῦν Σεβαστὴ κτισθεῖσα ὑπὸ Ἡρώδου, κατὰ χώραν δηλώσομεν. προσβαλὼν δʼ αὐτῇ φιλοπόνως ἐπολιόρκει μισοπονηρῶν τοῖς Σαμαρεῦσιν ὑπὲρ ὧν Μαρισηνοὺς ἀποίκους ὄντας Ἰουδαίων καὶ συμμάχους ἠδίκησαν ὑπακούοντες τοῖς τῶν Σύρων βασιλεῦσιν."},{"number":276,"text":"περιβαλὼν οὖν τάφρον πανταχόθεν τῇ πόλει καὶ διπλοῦν τεῖχος ὡς ἀπὸ σταδίων ὀγδοήκοντα τοὺς υἱοὺς ἐφίστησιν Ἀντίγονον καὶ Ἀριστόβουλον. ὧν ἐπικειμένων εἰς τοῦτο ἀνάγκης ὑπὸ λιμοῦ προαχθῆναι τοὺς Σαμαρεῖς συνέπεσεν, ὡς ἅψασθαι μὲν καὶ τῶν ἀήθων, ἐπικαλέσασθαι δὲ βοηθὸν Ἀντίοχον τὸν Κυζικηνόν."},{"number":277,"text":"ὃς ἑτοίμως ἐπὶ τὴν συμμαχίαν ἀφικόμενος ὑπὸ τῶν περὶ Ἀριστόβουλον ἡττᾶται, διωχθεὶς δʼ ἄχρι Σκυθοπόλεως ὑπὸ τῶν ἀδελφῶν διέφυγεν. οἱ δʼ ἐπὶ τοὺς Σαμαρεῖς ὑποστρέψαντες συγκλείουσι πάλιν εἰς τὸ τεῖχος αὐτούς, ὡς καὶ δεύτερον ἐπικαλέσασθαι σύμμαχον πέμψαντες τὸν αὐτὸν Ἀντίοχον."},{"number":278,"text":"ὃς παρὰ Πτολεμαίου τοῦ Λαθούρου μεταπεμψάμενος ἄνδρας εἰς ἑξακισχιλίους, οὓς ἀκούσης τῆς μητρὸς ἐκεῖνος καὶ ὅσον οὔπω τῆς ἀρχῆς αὐτὸν ἐκβεβληκυίας ἐξαπέστειλεν, τὸ μὲν πρῶτον ἐπιὼν ἐπόρθει τὴν Ὑρκανοῦ χώραν μετὰ τῶν Αἰγυπτίων λῃστρικῶς, μάχεσθαι μὲν αὐτῷ κατὰ πρόσωπον οὐ τολμῶν, οὐ γὰρ ἦν ἀξιόχρεως ἡ δύναμις αὐτοῦ, νομίζων δὲ τῇ κακώσει τῆς γῆς ἀναγκάσειν Ὑρκανὸν λῦσαι τὴν τῆς Σαμαρείας πολιορκίαν."},{"number":279,"text":"ἐπεὶ δὲ πολλοὺς τῶν στρατιωτῶν ἀπώλλυεν ἐνέδραις περιπίπτων, ἀπῆρεν εἰς Τρίπολιν Καλλιμάνδρῳ καὶ Ἐπικράτει τὸν πρὸς τοὺς Ἰουδαίους πόλεμον ἐπιτρέψας."},{"number":280,"text":"Καλλίμανδρος μὲν οὖν θρασύτερον τοῖς πολεμίοις προσενεχθεὶς εἰς φυγὴν τραπόμενος παραχρῆμα διεφθάρη. Ἐπικράτης δὲ ὑπὸ φιλοχρηματίας τήν τε Σκυθόπολιν καὶ τὰ ἄλλα πρὸς ταύτῃ χωρία προύδωκε φανερῶς τοῖς Ἰουδαίοις, τὴν δὲ Σαμαρείας πολιορκίαν διαλύειν οὐκ ἠδύνατο."},{"number":281,"text":"Ὑρκανὸς μὲν οὖν τὴν πόλιν ἑλὼν ἐνιαυτῷ πολιορκήσας οὐκ ἠρκέσθη μόνῳ τούτῳ, ἀλλὰ καὶ πᾶσαν αὐτὴν ἠφάνισεν ἐπίκλυστον τοῖς χειμάρροις ποιήσας· διασκάψας γὰρ αὐτὴν ὥστʼ εἰς χαράδρας μεταπεσεῖν τὰ σημεῖα τοῦ γενέσθαι ποτὲ πόλιν αὐτὴν ἀφείλετο."},{"number":282,"text":"παράδοξον δέ τι καὶ περὶ τοῦ ἀρχιερέως Ὑρκανοῦ λέγεται, τίνα τρόπον αὐτῷ τὸ θεῖον εἰς λόγους ἦλθεν· φασὶν γάρ, ὅτι κατʼ ἐκείνην τὴν ἡμέραν, καθʼ ἣν οἱ παῖδες αὐτοῦ τῷ Κυζικηνῷ συνέβαλον, αὐτὸς ἐν τῷ ναῷ θυμιῶν μόνος ὢν ἀρχιερεὺς ἀκούσειε φωνῆς, ὡς οἱ παῖδες αὐτοῦ νενικήκασιν ἀρτίως τὸν Ἀντίοχον."},{"number":283,"text":"καὶ τοῦτο προελθὼν ἐκ τοῦ ναοῦ παντὶ τῷ πλήθει φανερὸν ἐποίησεν, καὶ συνέβη οὕτως γενέσθαι. καὶ τὰ μὲν περὶ Ὑρκανὸν ἐν τούτοις ἦν."},{"number":284,"text":"Κατὰ δὲ τοῦτον ἔτυχε τὸν καιρὸν μὴ μόνον τοὺς ἐν Ἱεροσολύμοις καὶ τῇ χώρᾳ Ἰουδαίους εὐπραγεῖν, ἀλλὰ καὶ τοὺς ἐν Ἀλεξανδρείᾳ κατοικοῦντας καὶ ἐν Αἰγύπτῳ καὶ Κύπρῳ·"},{"number":285,"text":"Κλεοπάτρα γὰρ ἡ βασίλισσα πρὸς τὸν υἱὸν στασιάζουσα Πτολεμαῖον τὸν Λάθουρον ἐπιλεγόμενον κατέστησεν ἡγεμόνας Χελκίαν καὶ Ἀνανίαν υἱοὺς ὄντας Ὀνίου τοῦ οἰκοδομήσαντος τὸν ναὸν ἐν τῷ Ἡλιοπολίτῃ νομῷ πρὸς τὸν ἐν τοῖς Ἱεροσολύμοις, ὡς καὶ πρόσθεν δεδηλώκαμεν."},{"number":286,"text":"παραδοῦσα δὲ τούτοις ἡ Κλεοπάτρα τὴν στρατιὰν οὐδὲν δίχα τῆς τούτων γνώμης ἔπραττεν, ὡς μαρτυρεῖ καὶ Στράβων ἡμῖν ὁ Καππάδοξ λέγων οὕτως·"},{"number":287,"text":"οἱ γὰρ πλείους, οἵ τε συνελθόντες καὶ οἱ ὕστερον ἐπιπεμπόμενοι παρὰ τῆς Κλεοπάτρας εἰς Κύπρον, μετεβάλοντο παραχρῆμα πρὸς τὸν Πτολεμαῖον· μόνοι δὲ οἱ ἐκ τῆς Ὀνίου γενόμενοι Ἰουδαῖοι συνέμενον διὰ τὸ τοὺς πολίτας αὐτῶν εὐδοκιμεῖν μάλιστα παρὰ τῇ βασιλίσσῃ Χελκίαν τε καὶ Ἀνανίαν. ταῦτα μὲν οὖν ὁ Στράβων φησίν."},{"number":288,"text":"Ὑρκανῷ δὲ φθόνον ἐκίνησεν παρὰ τῶν Ἰουδαίων ἡ εὐπραγία, μάλιστα δʼ οἱ Φαρισαῖοι κακῶς πρὸς αὐτὸν εἶχον, αἵρεσις ὄντες μία τῶν Ἰουδαίων, ὡς καὶ ἐν τοῖς ἐπάνω δεδηλώκαμεν. τοσαύτην δὲ ἔχουσι τὴν ἰσχὺν παρὰ τῷ πλήθει, ὡς καὶ κατὰ βασιλέως τι λέγοντες καὶ κατʼ ἀρχιερέως εὐθὺς πιστεύεσθαι."},{"number":289,"text":"μαθητὴς δὲ αὐτῶν ἦν καὶ Ὑρκανὸς καὶ σφόδρα ὑπʼ αὐτῶν ἠγαπᾶτο. καὶ δὴ καλέσας αὐτοὺς ἐφʼ ἑστίασιν καὶ φιλοφρόνως ὑποδεξάμενος, ἐπεὶ σφόδρα ἡδομένους ἑώρα, λέγειν ἤρξατο πρὸς αὐτούς, ὡς ἴσασιν μὲν αὐτὸν βουλόμενον εἶναι δίκαιον καὶ πάντα ποιοῦντα ἐξ ὧν ἀρέσειεν ἂν τῷ θεῷ καὶ αὐτοῖς·"},{"number":290,"text":"οἱ γὰρ Φαρισαῖοι φιλοσοφοῦσιν· ἠξίου γε μήν, εἰ βλέπουσιν αὐτὸν ἁμαρτάνοντα καὶ τῆς ὁδοῦ τῆς δικαίας ἐκτρεπόμενον εἰς αὐτὴν ἐπαναγαγεῖν καὶ ἐπανορθοῦν. τῶν δὲ μαρτυρησάντων αὐτῷ πᾶσαν ἀρετὴν ὁ μὲν ἥσθη τοῖς ἐπαίνοις,"},{"number":291,"text":"εἷς δέ τις τῶν κατακειμένων Ἐλεάζαρος ὄνομα, κακοήθης ὢν φύσει καὶ στάσει χαίρων ἐπεί, φησίν, ἠξίωσας γνῶναι τὴν ἀλήθειαν, θέλεις δὲ εἶναι δίκαιος, τὴν ἀρχιερωσύνην ἀπόθου, καὶ μόνον ἀρκείτω σοι τὸ ἄρχειν τοῦ λαοῦ. τὴν δʼ αἰτίαν αὐτοῦ πυθομένου,"},{"number":292,"text":"διʼ ἣν ἀποθοῖτο τὴν ἀρχιερωσύνην ὅτι, φησίν, ἀκούομεν παρὰ τῶν πρεσβυτέρων αἰχμάλωτόν σου γεγονέναι τὴν μητέρα βασιλεύοντος Ἀντιόχου τοῦ Ἐπιφανοῦς. ψευδὴς λόγος ἦν· καὶ πρὸς αὐτὸν Ὑρκανὸς παρωξύνθη καὶ πάντες δʼ οἱ Φαρισαῖοι σφοδρῶς ἠγανάκτησαν."},{"number":293,"text":"Τῶν δʼ ἐκ τῶν Σαδδουκαίων τῆς αἱρέσεως, οἳ τὴν ἐναντίαν τοῖς Φαρισαίοις προαίρεσιν ἔχουσιν, Ἰωνάθης τις ἐν τοῖς μάλιστα φίλος ὢν Ὑρκανῷ τῇ κοινῇ πάντων Φαρισαίων γνώμῃ ποιήσασθαι τὰς βλασφημίας τὸν Ἐλεάζαρον ἔλεγεν· καὶ τοῦτʼ ἔσεσθαι φανερὸν αὐτῷ πυθομένῳ παρʼ ἐκείνων, τίνος ἄξιός ἐστιν ἐπὶ τοῖς εἰρημένοις κολάσεως."},{"number":294,"text":"τοῦ δὲ Ὑρκανοῦ τοὺς Φαρισαίους ἐρομένου, τίνος αὐτὸν ἄξιον ἡγοῦνται τιμωρίας· πειραθήσεσθαι γὰρ οὐ μετὰ τῆς ἐκείνων γνώμης γεγονέναι τὰς βλασφημίας τιμησαμένων αὐτὸν τῷ μέτρῳ τῆς δίκης, πληγῶν ἔφασαν καὶ δεσμῶν· οὐ γὰρ ἐδόκει λοιδορίας ἕνεκα θανάτῳ ζημιοῦν, ἄλλως τε καὶ φύσει πρὸς τὰς κολάσεις ἐπιεικῶς ἔχουσιν οἱ Φαρισαῖοι."},{"number":295,"text":"πρὸς τοῦτο λίαν ἐχαλέπηνεν καὶ δοκοῦν ἐκείνοις ποιήσασθαι τὰς βλασφημίας τὸν ἄνθρωπον ἐνόμισεν. μάλιστα δʼ αὐτὸν ἐπιπαρώξυνεν Ἰωνάθης καὶ διέθηκεν οὕτως,"},{"number":296,"text":"ὥστε τῇ Σαδδουκαίων ἐποίησεν προσθέσθαι μοίρᾳ τῶν Φαρισαίων ἀποστάντα καὶ τά τε ὑπʼ αὐτῶν κατασταθέντα νόμιμα τῷ δήμῳ καταλῦσαι καὶ τοὺς φυλάττοντας αὐτὰ κολάσαι. μῖσος οὖν ἐντεῦθεν αὐτῷ τε καὶ τοῖς υἱοῖς παρὰ τοῦ πλήθους ἐγένετο."},{"number":297,"text":"περὶ μέντοι τούτων αὖθις ἐροῦμεν. νῦν δὲ δηλῶσαι βούλομαι, ὅτι νόμιμά τινα παρέδοσαν τῷ δήμῳ οἱ Φαρισαῖοι ἐκ πατέρων διαδοχῆς, ἅπερ οὐκ ἀναγέγραπται ἐν τοῖς Μωυσέως νόμοις, καὶ διὰ τοῦτο ταῦτα τὸ Σαδδουκαίων γένος ἐκβάλλει, λέγον ἐκεῖνα δεῖν ἡγεῖσθαι νόμιμα τὰ γεγραμμένα, τὰ δʼ ἐκ παραδόσεως τῶν πατέρων μὴ τηρεῖν."},{"number":298,"text":"καὶ περὶ τούτων ζητήσεις αὐτοῖς καὶ διαφορὰς γίνεσθαι συνέβαινεν μεγάλας, τῶν μὲν Σαδδουκαίων τοὺς εὐπόρους μόνον πειθόντων τὸ δὲ δημοτικὸν οὐχ ἑπόμενον αὐτοῖς ἐχόντων, τῶν δὲ Φαρισαίων τὸ πλῆθος σύμμαχον ἐχόντων. ἀλλὰ περὶ μὲν τούτων τῶν δύο καὶ τῶν Ἐσσηνῶν ἐν τῇ δευτέρᾳ μου τῶν Ἰουδαϊκῶν ἀκριβῶς δεδήλωται."},{"number":299,"text":"Ὑρκανὸς δὲ παύσας τὴν στάσιν καὶ μετʼ αὐτὴν βιώσας εὐδαιμόνως καὶ τὴν ἀρχὴν διοικησάμενος ἄριστον τρόπον ἔτεσιν ἑνὶ καὶ τριάκοντα τελευτᾷ καταλιπὼν υἱοὺς πέντε, τριῶν τῶν μεγίστων ἄξιος ὑπὸ τοῦ θεοῦ κριθείς, ἀρχῆς τοῦ ἔθνους καὶ τῆς ἀρχιερατικῆς τιμῆς καὶ προφητείας·"},{"number":300,"text":"συνῆν γὰρ αὐτῷ τὸ θεῖον καὶ τὴν τῶν μελλόντων πρόγνωσιν παρεῖχεν αὐτῷ τε εἰδέναι καὶ προλέγειν οὕτως, ὥστε καὶ περὶ τῶν δύο τῶν πρεσβυτέρων παίδων ὅτι μὴ μενοῦσιν τῶν πραγμάτων κύριοι προεῖπεν. ὧν τὴν καταστροφὴν εἰς τὸ μαθεῖν ὅσον τῆς τοῦ πατρὸς ὑπέβησαν εὐτυχίας ἄξιον ἀφηγήσασθαι."}],"11":[{"number":301,"text":"Τελευτήσαντος γὰρ αὐτοῖς τοῦ πατρὸς ὁ πρεσβύτατος Ἀριστόβουλος τὴν ἀρχὴν εἰς βασιλείαν μεταθεῖναι δόξας, ἔκρινεν γὰρ οὕτω, διάδημα πρῶτος ἐπιτίθεται μετὰ τετρακοσίων ἀριθμὸν ἐτῶν καὶ ὀγδοήκοντα καὶ ἑνὸς καὶ μηνῶν τριῶν ἀφʼ οὗ τῆς ὑπὸ Βαβυλωνίοις δουλείας ἀπαλλαγεὶς ὁ λαὸς εἰς τὴν οἰκείαν κατῆλθεν."},{"number":302,"text":"στέργων δὲ τῶν ἀδελφῶν τὸν μετʼ αὐτὸν Ἀντίγονον τοῦτον μὲν τῶν ὁμοίων ἠξίου, τοὺς δὲ ἄλλους εἶχεν ἐν δεσμοῖς. εἶρξε δὲ καὶ τὴν μητέρα περὶ τῆς ἀρχῆς αὐτῷ διενεχθεῖσαν, ἐκείνην γὰρ Ὑρκανὸς τῶν ὅλων κυρίαν καταλείπει, καὶ μέχρι τοσαύτης ὠμότητος προῆλθεν, ὥστʼ αὐτὴν καὶ λιμῷ διέφθειρεν δεδεμένην."},{"number":303,"text":"προστίθησιν δὲ τῇ μητρὶ καὶ τὸν ἀδελφὸν Ἀντίγονον, ὃν στέργειν ἐδόκει μάλιστα καὶ κοινωνὸν εἶχεν τῆς βασιλείας, ἐκ διαβολῶν ἀπαλλοτριωθεὶς πρὸς αὐτόν, αἷς τὸ μὲν πρῶτον οὐκ ἐπίστευεν, τὰ μὲν ὑπὸ τοῦ φιλεῖν αὐτὸν οὐ προσέχων τοῖς λεγομένοις, τὰ δὲ καὶ φθονούμενον ἡγούμενος διαβάλλεσθαι."},{"number":304,"text":"τοῦ δὲ Ἀντιγόνου ποτὲ λαμπρῶς ἀπὸ στρατείας ἐπανελθόντος καὶ τῆς ἑορτῆς, καθʼ ἣν σκηνοπηγοῦσιν τῷ θεῷ, κατʼ ἐκεῖνον τὸν καιρὸν ἐνστάσης, ἔτυχεν τὸν μὲν Ἀριστόβουλον εἰς νόσον καταπεσεῖν, τὸν δὲ Ἀντίγονον ἐπιτελοῦντα τὴν ἑορτὴν ἀναβῆναι λαμπρῶς σφόδρα κεκοσμημένον μετὰ τῶν περὶ αὐτὸν ὁπλιτῶν εἰς τὸ ἱερὸν καὶ τὰ πλείω περὶ τῆς σωτηρίας τἀδελφοῦ εὔχεσθαι,"},{"number":305,"text":"τοὺς δὲ πονηροὺς καὶ διαστῆσαι τὴν ὁμόνοιαν αὐτῶν ἐσπουδακότας ἀφορμῇ χρησαμένους τῇ τε περὶ τὴν πομπὴν τοῦ Ἀντιγόνου φιλοτιμίᾳ καὶ τοῖς ὑπʼ αὐτοῦ κατωρθωμένοις ἐλθεῖν πρὸς τὸν βασιλέα καὶ κακοήθως ἐπὶ τὸ μεῖζον ἐξαίρειν τὰ περὶ τὴν πομπὴν τὴν ἐν τῇ ἑορτῇ,"},{"number":306,"text":"καὶ ὡς οὐ κατʼ ἰδιώτην ἕκαστον ἦν τῶν γινομένων, ἀλλὰ φρονήματος ἔνδειξιν ἔχειν βασιλικοῦ τὰ πραττόμενα, καὶ ὡς κτείνειν αὐτὸν μέλλοι μετὰ στίφους ἐληλυθὼς καρτεροῦ, λογιζόμενον εὐήθως αὐτὸν βασιλεύειν ἐνὸν τιμῆς μεταλαμβάνοντα δοκεῖν μεγάλων τυγχάνειν."},{"number":307,"text":"Ἀριστόβουλος δὲ τούτοις ἄκων πειθόμενος καὶ τοῦ ἀνύποπτος εἶναι τἀδελφῷ προνοῶν καὶ τῆς ἀσφαλείας ἅμα φροντίζων, διίστησι τοὺς σωματοφύλακας ἔν τινι τῶν ὑπογείων ἀφωτίστῳ, κατέκειτο δὲ ἐν τῇ βάρει μετονομασθείσῃ δὲ Ἀντωνίᾳ, καὶ προσέταξεν ἀνόπλου μὲν ἅπτεσθαι μηδένα, κτείνειν δὲ τὸν Ἀντίγονον, ἂν ὡπλισμένος πρὸς αὐτὸν εἰσίῃ."},{"number":308,"text":"πέμπει μέντοι πρὸς Ἀντίγονον αὐτὸς ἄνοπλον αὐτὸν ἀξιῶν ἥκειν. ἡ δὲ βασίλισσα καὶ οἱ συνεπιβουλεύοντες αὐτῇ κατʼ Ἀντιγόνου πείθουσι τὸν πεμφθέντα τἀναντία λέγειν, ὡς ὁ ἀδελφὸς ἀκούσας, ὅτι κατασκευάσειεν ὅπλα καὶ κόσμον πολεμικόν, παραγίνεσθαι πρὸς αὐτὸν παρακαλεῖ ὡπλισμένον, ὅπως ἴδοι τὴν κατασκευήν."},{"number":309,"text":"ὁ δʼ Ἀντίγονος μηδὲν ὑπιδόμενος κακοῦργον, ἀλλὰ θαρρῶν τῇ παρὰ τἀδελφοῦ διαθέσει, ὡς εἶχεν ἐνδεδυμένος τὴν πανοπλίαν παρεγένετο πρὸς τὸν Ἀριστόβουλον ἐπιδείξων αὐτῷ τὰ ὅπλα. γενόμενον δʼ αὐτὸν κατὰ τὸν Στράτωνος λεγόμενον πύργον, οὗ συνέβαινεν ἀφώτιστον εἶναι σφόδρα τὴν πάροδον, ἀποκτείνουσιν οἱ σωματοφύλακες."},{"number":310,"text":"διέδειξέν γε μὴν ὁ τούτου θάνατος, ὅτι μηδὲν μήτε φθόνου μήτε διαβολῆς ἰσχυρότερον, μηδʼ ὅ τι μᾶλλον εὔνοιαν καὶ φυσικὴν οἰκειότητα διίστησιν, ἢ ταῦτα τὰ πάθη."},{"number":311,"text":"μάλιστα δʼ ἄν τις θαυμάσειεν καὶ Ἰούδαν τινά, Ἐσσηνὸν μὲν τὸ γένος, οὐδέποτε δʼ ἐν οἷς προεῖπεν διαψευσάμενον τἀληθές· οὗτος γὰρ ἰδὼν τὸν Ἀντίγονον παριόντα τὸ ἱερὸν ἀνεβόησεν ἐν τοῖς ἑταίροις αὐτοῦ καὶ γνωρίμοις, οἳ διδασκαλίας ἕνεκα τοῦ προλέγειν τὰ μέλλοντα παρέμενον,"},{"number":312,"text":"ὡς ἀποθανεῖν αὐτῷ καλὸν διεψευσμένῳ ζῶντος Ἀντιγόνου, ὃν σήμερον τεθνήξεσθαι προειπὼν ἐν τῷ καλουμένῳ Στράτωνος πύργῳ περιόντα ὁρᾷ, καὶ τοῦ μὲν χωρίου περὶ σταδίους ἀπέχοντος νῦν ἑξακοσίους, ὅπου φονευθήσεσθαι προεῖπεν αὐτόν, τῆς δʼ ἡμέρας ἤδη τὸ πλεῖστον ἠνυσμένον, ὥστʼ αὐτῷ κινδυνεύειν τὸ μάντευμα ψεῦδος εἶναι."},{"number":313,"text":"ταῦτʼ οὖν λέγοντος αὐτοῦ καὶ κατηφοῦντος ἀγγέλλεται τεθνεὼς Ἀντίγονος ἐν τῷ ὑπογείῳ, ὃ καὶ αὐτὸ Στράτωνος ἐκαλεῖτο πύργος, ὁμώνυμον τῇ παραλίῳ Καισαρείᾳ. τὸν μὲν οὖν μάντιν τοῦτο διετάραξεν."},{"number":314,"text":"Ἀριστόβουλον δὲ τῆς ἀδελφοκτονίας εὐθὺς εἰσῆλθεν μετάνοια καὶ νόσος ἐπʼ αὐτῇ τῆς διανοίας ὑπὸ τοῦ μύσους κεκακωμένης, ὡς διαφθαρέντων αὐτῷ ὑπὸ ἀκράτου τῆς ὀδύνης τῶν ἐντὸς αἷμα ἀναφέρειν. ὃ τῶν διακονουμένων τις παίδων κατὰ δαιμόνιον οἶμαι πρόνοιαν εἰς τὸν αὐτὸν τόπον, οὗ σφαγέντος Ἀντιγόνου σπίλους ἔτι τοῦ αἵματος ἐκείνου συνέβαινεν εἶναι, κομίζων ὀλισθὼν ἐξέχεεν."},{"number":315,"text":"γενομένης δὲ βοῆς παρὰ τῶν ἰδόντων ὡς τοῦ παιδὸς ἐξεπίτηδες ἐκχέαντος ἐκεῖ τὸ αἷμα, ἀκούσας Ἀριστόβουλος τὴν αἰτίαν ἐπύθετο, καὶ μὴ λεγόντων ἔτι μᾶλλον ἐπετείνετο μαθεῖν, φύσει τῶν ἀνθρώπων ὑπονοούντων ἐν τοῖς τοιούτοις εἶναι χείρονα τὰ σιγώμενα."},{"number":316,"text":"ὡς δʼ ἀπειλοῦντος καὶ βιαζομένου τοῖς φόβοις τἀληθὲς εἶπον, προχεῖται μὲν αὐτῷ πληγέντι τὴν διάνοιαν ὑπὸ τοῦ συνειδότος πολλὰ δάκρυα, βύθιον δὲ ἀνοιμώξας, οὐκ ἄρʼ, εἶπεν, λήσειν ἐπʼ ἀσεβέσιν οὕτω καὶ μιαροῖς τολμήμασι τὸν θεὸν ἔμελλον, ἀλλά με ταχεῖα ποινὴ συγγενοῦς φόνου μετελήλυθεν."},{"number":317,"text":"καὶ μέχρι τίνος, ὦ σῶμα ἀναιδέστατον, ψυχὴν ὀφειλομένην ἀδελφοῦ καὶ μητρὸς καθέξεις δαίμοσιν; τί δʼ οὐκ ἀθρόαν αὐτὴν ταύτην ἀποδίδως, κατὰ μέρος δʼ ἐπισπένδω τοὐμὸν αἷμα τοῖς μιαιφονηθεῖσιν;"},{"number":318,"text":"ταῦτʼ εἰπὼν ἐπαποθνήσκει τοῖς λόγοις βασιλεύσας ἐνιαυτόν, χρηματίσας μὲν Φιλέλλην, πολλὰ δʼ εὐεργετήσας τὴν πατρίδα, πολεμήσας Ἰτουραίους καὶ πολλὴν αὐτῶν τῆς χώρας τῇ Ἰουδαίᾳ προσκτησάμενος ἀναγκάσας τε τοὺς ἐνοικοῦντας, εἰ βούλονται μένειν ἐν τῇ χώρᾳ, περιτέμνεσθαι καὶ κατὰ τοὺς Ἰουδαίων νόμους ζῆν."},{"number":319,"text":"φύσει δʼ ἐπιεικεῖ κέχρητο καὶ σφόδρα ἦν αἰδοῦς ἥττων, ὡς μαρτυρεῖ τούτῳ καὶ Στράβων ἐκ τοῦ Τιμαγένους ὀνόματος λέγων οὕτως· ἐπιεικής τε ἐγένετο οὗτος ὁ ἀνὴρ καὶ πολλὰ τοῖς Ἰουδαίοις χρήσιμος· χώραν τε γὰρ αὐτοῖς προσεκτήσατο καὶ τὸ μέρος τοῦ τῶν Ἰτουραίων ἔθνους ᾠκειώσατο δεσμῷ συνάψας τῇ τῶν αἰδοίων περιτομῇ."}],"12":[{"number":320,"text":"Τελευτήσαντος δὲ Ἀριστοβούλου Σαλίνα ἡ γυνὴ αὐτοῦ, λεγομένη δὲ ὑπὸ Ἑλλήνων Ἀλεξάνδρα, λύσασα τοὺς ἀδελφοὺς αὐτοῦ, δεδεμένους γὰρ αὐτοὺς εἶχεν Ἀριστόβουλος, ὡς προειρήκαμεν, Ἰαναῖον τὸν καὶ Ἀλέξανδρον βασιλέα καθίστησιν τὸν καὶ καθʼ ἡλικίαν προύχοντα καὶ μετριότητα,"},{"number":321,"text":"ᾧ καὶ συνέβη γεννηθέντι εὐθὺς μισηθῆναι ὑπὸ τοῦ πατρὸς καὶ μέχρι τῆς τελευτῆς αὐτοῦ μηκέτι εἰς ὄψιν ἀφικέσθαι. τὸ δʼ αἴτιον τοῦ μίσους τοιόνδε λέγεται γενέσθαι·"},{"number":322,"text":"στέργων μάλιστα τῶν παίδων Ὑρκανὸς τοὺς πρεσβυτέρους Ἀντίγονον καὶ Ἀριστόβουλον φανέντα κατὰ τοὺς ὕπνους αὐτῷ τὸν θεὸν ἐπηρώτα, τίς αὐτοῦ τῶν παίδων μέλλει ἔσεσθαι διάδοχος. τοῦ δὲ θεοῦ τοὺς τούτου χαρακτῆρας δείξαντος, λυπηθεὶς ὅτι τῶν ἀγαθῶν αὐτοῦ πάντων οὗτος ἔσται κληρονόμος, γενόμενον εἴασεν ἐν τῇ Γαλιλαίᾳ τρέφεσθαι. ὁ μέντοι θεὸς οὐ διεψεύσατο τὸν Ὑρκανόν."},{"number":323,"text":"τὴν δὲ βασιλείαν μετὰ τὴν Ἀριστοβούλου τελευτὴν οὗτος παραλαβὼν τὸν μὲν τῶν ἀδελφῶν ἐπιχειροῦντα τῇ βασιλείᾳ διεχρήσατο, τὸν δʼ ἕτερον ἀπραγμόνως ζῆν προαιρούμενον εἶχεν ἐν τιμῇ."},{"number":324,"text":"Καταστησάμενος δὲ τὴν ἀρχὴν ὃν ᾤετο συμφέρειν αὐτῷ τρόπον στρατεύει ἐπὶ Πτολεμαΐδα, τῇ δὲ μάχῃ κρατήσας ἐνέκλεισε τοὺς ἀνθρώπους εἰς τὴν πόλιν καὶ περικαθίσας αὐτοὺς ἐπολιόρκει. τῶν γὰρ ἐν τῇ παραλίᾳ Πτολεμαῒς αὐτῷ καὶ Γάζα μόναι χειρωθῆναι ὑπελείποντο, καὶ Ζώιλος δὲ ὁ κατασχὼν τὸν Στράτωνος πύργον τύραννος καὶ Δῶρα."},{"number":325,"text":"τοῦ δὲ Φιλομήτορος Ἀντιόχου καὶ τοῦ ἀδελφοῦ αὐτοῦ Ἀντιόχου, ὃς ἐπεκαλεῖτο Κυζικηνός, πολεμούντων ἀλλήλους καὶ τὴν αὐτῶν δύναμιν ἀπολλύντων ἦν οὐδεμία τοῖς Πτολεμαεῦσιν βοήθεια παρʼ αὐτῶν."},{"number":326,"text":"ἀλλὰ πονουμένοις τῇ πολιορκίᾳ Ζώιλος ὁ τὸν Στράτωνος πύργον κατεσχηκὼς παρῆν καὶ τὰ Δῶρα σύνταγμα τρέφων στρατιωτικὸν καὶ τυραννίδι ἐπιχειρῶν διὰ τὴν τῶν βασιλέων πρὸς ἀλλήλους ἅμιλλαν μικρὰ τοῖς Πτολεμαιεῦσι παρεβοήθει·"},{"number":327,"text":"οὐδὲ γὰρ οἱ βασιλεῖς οὕτως εἶχον οἰκείως πρὸς αὐτούς, ὥστʼ ἐλπίσαι τινὰ παρʼ αὐτῶν ὠφέλειαν. ἑκάτεροι γὰρ ταὐτὸν τοῖς ἀθληταῖς ἔπασχον, οἳ τῇ δυνάμει μὲν ἀπηγορευκότες αἰσχυνόμενοι δὲ παραχωρῆσαι διετέλουν ἀργίᾳ καὶ ἀναπαύσει διαφέροντες τὸν ἀγῶνα."},{"number":328,"text":"λοιπὴ δʼ αὐτοῖς ἐλπὶς ἦν ἡ παρὰ τῶν Αἰγύπτου βασιλέων καὶ τοῦ Κύπρον ἔχοντος Πτολεμαίου τοῦ Λαθούρου, ὃς ὑπὸ τῆς μητρὸς Κλεοπάτρας τῆς ἀρχῆς ἐκπεσὼν εἰς Κύπρον παρεγένετο. πέμψαντες οὖν πρὸς τοῦτον οἱ Πτολεμαιεῖς παρεκάλουν ἐλθόντα σύμμαχον ἐκ τῶν Ἀλεξάνδρου χειρῶν αὐτοὺς ῥύσασθαι κινδυνεύοντας."},{"number":329,"text":"ἐπελπισάντων δʼ αὐτὸν τῶν πρέσβεων, ὡς διαβὰς εἰς Συρίαν ἕξει Γαζαίους συνεστῶτας μετὰ τῶν Πτολεμαιῶν καὶ Ζώιλον, ἔτι γε μὴν Σιδωνίους καὶ πολλοὺς ἄλλους αὐτῷ συλλήψεσθαι λεγόντων, ἐπαρθεὶς πρὸς τὸν ἔκπλουν ἔσπευδεν."},{"number":330,"text":"Ἐν τούτῳ δὲ τοὺς Πτολεμαιᾶς Δημαίνετος πιθανὸς ὢν αὐτοῖς τότε καὶ δημαγωγῶν μεταβαλέσθαι τὰς γνώμας ἐποίησεν, ἄμεινον εἶναι φήσας ἐπʼ ἀδήλῳ τῷ γενησομένῳ διακινδυνεύειν πρὸς τοὺς Ἰουδαίους μᾶλλον ἢ φανερὰν εἰσδέξασθαι δουλείαν δεσπότῃ παραδόντας αὑτούς, καὶ πρὸς τούτῳ μὴ τὸν παρόντα μόνον ἔχειν πόλεμον, ἀλλὰ καὶ πολὺ μείζω τὸν ἀπʼ Αἰγύπτου."},{"number":331,"text":"τὴν γὰρ Κλεοπάτραν οὐ περιόψεσθαι δύναμιν αὐτῷ κατασκευαζόμενον Πτολεμαῖον ἐκ γειτόνων, ἀλλʼ ἥξειν ἐπʼ αὐτοὺς μετὰ μεγάλης στρατιᾶς· σπουδάσαι γὰρ αὐτὴν ὥστε καὶ τῆς Κύπρου τὸν υἱὸν ἐκβαλεῖν· εἶναι δὲ Πτολεμαίῳ μὲν διαμαρτόντι τῆς ἐλπίδος ἀποφυγὴν πάλιν τὴν Κύπρον, αὐτοῖς δὲ κινδύνων τὸν ἔσχατον."},{"number":332,"text":"ὁ μὲν οὖν Πτολεμαῖος κατὰ τὸν πόρον μαθὼν τὴν τῶν Πτολεμαιῶν μεταβολὴν οὐδὲν ἧττον ἔπλευσεν καὶ καταχθεὶς εἰς τὴν καλουμένην Συκάμινον ἐνταυθοῖ τὴν δύναμιν ἐξεβίβασεν."},{"number":333,"text":"ἦν δὲ ὁ πᾶς στρατὸς αὐτῷ πεζοί τε ἅμα καὶ ἱππεῦσιν περὶ τρισμυρίους, οὓς προαγαγὼν πλησίον τῆς Πτολεμαΐδος καὶ στρατοπεδευσάμενος, ἐπεὶ μήτε τοὺς παρʼ αὐτοῦ πρέσβεις ἐδέχοντο μήτε τῶν λόγων ἠκροῶντο, μεγάλως ἐφρόντιζεν."},{"number":334,"text":"Ἐλθόντων δὲ πρὸς αὐτὸν Ζωίλου τε καὶ τῶν Γαζαίων καὶ δεομένων συμμαχεῖν αὐτοῖς πορθουμένης αὐτοῖς τῆς χώρας ὑπὸ τῶν Ἰουδαίων καὶ Ἀλεξάνδρου, λύει μὲν τὴν πολιορκίαν δείσας τὸν Πτολεμαῖον ὁ Ἀλέξανδρος, ἀπαγαγὼν δὲ τὴν στρατιὰν εἰς τὴν οἰκείαν ἐστρατήγει τὸ λοιπὸν λάθρα μὲν τὴν Κλεοπάτραν ἐπὶ τὸν Πτολεμαῖον μεταπεμπόμενος, φανερῶς δὲ φιλίαν καὶ συμμαχίαν πρὸς αὐτὸν ὑποκρινόμενος."},{"number":335,"text":"καὶ τετρακόσια δὲ ἀργυρίου τάλαντα δώσειν ὑπέσχετο χάριν ἀντὶ τούτων αἰτῶν Ζώιλον ἐκποδὼν ποιήσασθαι τὸν τύραννον καὶ τὴν χώραν τοῖς Ἰουδαίοις προσνεῖμαι. τότε μὲν οὖν ὁ Πτολεμαῖος ἡδέως τὴν πρὸς Ἀλέξανδρον ποιησάμενος φιλίαν χειροῦται τὸν Ζώιλον."},{"number":336,"text":"ὕστερον δὲ ἀκούσας λάθρα διαπεμψάμενον αὐτὸν πρὸς τὴν μητέρα αὐτοῦ Κλεοπάτραν λύει τοὺς γεγενημένους πρὸς αὐτὸν ὅρκους καὶ προσβαλὼν ἐπολιόρκει τὴν Πτολεμαΐδα μὴ δεξαμένην αὐτόν. καταλιπὼν δʼ ἐπὶ τῆς πολιορκίας στρατηγοὺς καὶ μέρος τι τῆς δυνάμεως αὐτὸς τῷ λοιπῷ τὴν Ἰουδαίαν καταστρεψόμενος ὥρμησεν."},{"number":337,"text":"ὁ δὲ Ἀλέξανδρος τὴν τοῦ Πτολεμαίου διάνοιαν μαθὼν συνήθροισεν καὶ αὐτὸς περὶ πέντε μυριάδας τῶν ἐγχωρίων, ὡς δʼ ἔνιοι συγγραφεῖς εἰρήκασιν ὀκτώ, καὶ ἀναλαβὼν τὴν δύναμιν ἀπήντα τῷ Πτολεμαίῳ. Πτολεμαῖος δʼ ἐξαίφνης ἐπιπεσὼν Ἀσωχειτω τῆς Γαλιλαίας πόλει σάββασιν αἱρεῖ κατὰ κράτος αὐτὴν καὶ περὶ μύρια σώματα καὶ πολλὴν ἑτέραν ἔλαβε λείαν."},{"number":338,"text":"Πειράσας δὲ καὶ Σέπφωριν μικρὸν ἄπωθεν τῆς πεπορθημένης πολλοὺς ἀποβαλὼν ᾔει πολεμήσων Ἀλεξάνδρῳ. ὑπήντησε δʼ αὐτῷ πρὸς τῷ Ἰορδάνῃ ποταμῷ Ἀλέξανδρος περί τινα τόπον λεγόμενον Ἀσωφὼν οὐ πόρρωθεν τοῦ Ἰορδάνου ποταμοῦ καὶ βάλλεται στρατόπεδον πλησίον τῶν πολεμίων."},{"number":339,"text":"εἶχεν μέντοι τοὺς προμαχομένους ὀκτακισχιλίους, οὓς ἑκατονταμάχους προσηγόρευσεν, ἐπιχάλκοις χρωμένους τοῖς θυρεοῖς. ἦσαν δὲ καὶ τοῖς τοῦ Πτολεμαίου προμαχοῦσιν ἐπίχαλκοι αἱ ἀσπίδες. τοῖς μέντοι γε ἄλλοις ἔλαττον ἔχοντες οἱ τοῦ Πτολεμαίου εὐλαβέστερον συνῆψαν εἰς τὸν κίνδυνον."},{"number":340,"text":"θάρσος δὲ αὐτοῖς οὐκ ὀλίγον ἐνεποίησεν ὁ τακτικὸς Φιλοστέφανος διαβῆναι κελεύσας τὸν ποταμόν, οὗ μεταξὺ ἦσαν ἐστρατοπεδευκότες. Ἀλεξάνδρῳ δὲ κωλύειν αὐτῶν τὴν διάβασιν οὐκ ἔδοξεν· ἐνόμιζεν γάρ, εἰ κατὰ νώτου λάβοιεν τὸν ποταμόν, ῥᾷον αἱρήσειν τοὺς πολεμίους φεύγειν ἐκ τῆς μάχης οὐ δυναμένους."},{"number":341,"text":"κατʼ ἀρχὰς μὲν οὖν παρʼ ἀμφοτέρων ἦν ἔργα χειρῶν καὶ προθυμίας παραπλήσια καὶ πολὺς ἐγένετο φόνος ἐξ ἑκατέρων τῶν στρατευμάτων, ὑπερτέρων δὲ τῶν Ἀλεξάνδρου γινομένων Φιλοστέφανος διελὼν τὴν δύναμιν δεξιῶς τοῖς ἐνδιδοῦσιν ἐπεκούρει."},{"number":342,"text":"μηδενὸς δὲ τῷ κλιθέντι μέρει τῶν Ἰουδαίων προσβοηθοῦντος τούτους μὲν συνέβαινε φεύγειν μὴ βοηθούντων τῶν πλησίον ἀλλὰ κοινωνούντων τῆς φυγῆς, οἱ δὲ τοῦ Πτολεμαίου τὰ ἐναντία τούτων ἔπραττον·"},{"number":343,"text":"ἑπόμενοι γὰρ ἔκτεινον τοὺς Ἰουδαίους, καὶ τὸ τελευταῖον τραπέντας αὐτοὺς ἅπαντας ἐδίωκον φονεύοντες ἕως οὗ καὶ ὁ σίδηρος αὐτοῖς ἠμβλύνθη κτείνουσιν καὶ αἱ χεῖρες παρείθησαν."},{"number":344,"text":"τρισμυρίους γοῦν ἔφασαν αὐτῶν ἀποθανεῖν, Τιμαγένης δὲ πεντακισμυρίους εἴρηκεν, τῶν δὲ ἄλλων τοὺς μὲν αἰχμαλώτους ληφθῆναι, τοὺς δʼ εἰς τὰ οἰκεῖα διαφεύγειν χωρία."},{"number":345,"text":"Πτολεμαῖος δὲ μετὰ τὴν νίκην προσκαταδραμὼν τὴν χώραν ὀψίας ἐπιγενομένης ἔν τισι κώμαις τῆς Ἰουδαίας κατέμεινεν, ἃς γυναικῶν εὑρὼν μεστὰς καὶ νηπίων ἐκέλευσεν τοὺς στρατιώτας ἀποσφάττοντας αὐτοὺς καὶ κρεουργοῦντας ἔπειτα εἰς λέβητας ζέοντας ἐνιέντας τὰ μέλη ἀπάρχεσθαι."},{"number":346,"text":"τοῦτο δὲ προσέταξεν, ἵνʼ οἱ διαφυγόντες ἐκ τῆς μάχης καὶ πρὸς αὑτοὺς ἐλθόντες σαρκοφάγους ὑπολάβωσιν εἶναι τοὺς πολεμίους, καὶ διὰ τοῦτο ἔτι μᾶλλον αὐτοὺς καταπλαγῶσι ταῦτʼ ἰδόντες."},{"number":347,"text":"λέγει δὲ καὶ Στράβων καὶ Νικόλαος, ὅτι τοῦτον αὐτοῖς ἐχρήσαντο τὸν τρόπον, καθὼς κἀγὼ προείρηκα. ἔλαβον δὲ καὶ τὴν Πτολεμαΐδα κατὰ κράτος, ὡς καὶ ἐν ἄλλοις φανερὸν πεποιήκαμεν."}],"13":[{"number":348,"text":"Κλεοπάτρα δʼ ὁρῶσα τὸν υἱὸν αὐξανόμενον καὶ τήν τε Ἰουδαίαν ἀδεῶς πορθοῦντα καὶ τὴν Γαζαίων πόλιν ὑπήκοον ἔχοντα, περιιδεῖν οὐκ ἔγνω τοῦτον ἐπὶ ταῖς πύλαις ὄντα καὶ ποθοῦντα τὴν τῶν Αἰγυπτίων μείζω γενόμενον,"},{"number":349,"text":"ἀλλὰ παραχρῆμα μετὰ καὶ ναυτικῆς καὶ πεζῆς δυνάμεως ἐπʼ αὐτὸν ἐξώρμησεν ἡγεμόνας τῆς ὅλης στρατιᾶς ἀποδείξασα Χελκίαν καὶ Ἀνανίαν τοὺς Ἰουδαίους, τὰ δὲ πολλὰ τοῦ πλούτου καὶ τοὺς υἱωνοὺς καὶ διαθήκας πέμψασα Κῴοις παρέθετο."},{"number":350,"text":"κελεύσασα δὲ τὸν υἱὸν Ἀλέξανδρον στόλῳ μεγάλῳ παραπλεῖν εἰς Φοινίκην ἡ Κλεοπάτρα μετὰ πάσης αὐτὴ τῆς δυνάμεως ἧκεν εἰς Πτολεμαΐδα, μὴ δεξαμένων δὲ αὐτὴν τῶν Πτολεμαιῶν πολιορκεῖ τὴν πόλιν."},{"number":351,"text":"Πτολεμαῖος δʼ ἐκ τῆς Συρίας ἀπελθὼν ἐπὶ τὴν Αἴγυπτον ἔσπευσεν, αἰφνιδίως αὐτὴν οἰόμενος κενὴν οὖσαν στρατιᾶς καθέξειν· ἀλλὰ διαμαρτάνει τῆς ἐλπίδος. κατὰ τοῦτον δὴ τὸν χρόνον συνέβη καὶ Χελκίαν τὸν ἕτερον τῶν τῆς Κλεοπάτρας ἡγεμόνων ἀποθανεῖν περὶ κοίλην Συρίαν διώκοντα Πτολεμαῖον."},{"number":352,"text":"Ἀκούσασα δʼ ἡ Κλεοπάτρα τὴν ἐπιχείρησιν τὴν τοῦ υἱοῦ καὶ ὅτι τὰ περὶ τὴν Αἴγυπτον οὐχ ὃν προσεδόκα τρόπον προκεχώρηκεν αὐτῷ, πέμψασα μέρος τῆς στρατιᾶς ἐξέβαλεν αὐτὸν ἀπὸ τῆς χώρας. καὶ ὁ μὲν ἐκ τῆς Αἰγύπτου πάλιν ὑποστρέψας τὸν χειμῶνα διέτριψεν ἐν Γάζῃ."},{"number":353,"text":"Κλεοπάτρα δʼ ἐν τούτῳ τὴν ἐν Πτολεμαΐδι φρουρὰν ἐκ πολιορκίας λαμβάνει καὶ τὴν πόλιν. Ἀλεξάνδρου δʼ αὐτὴν μετὰ δώρων περιελθόντος καὶ θεραπείας ὁποίας ἄξιον ἦν πεπονθότα μὲν κακῶς ὑπὸ Πτολεμαίου, καταφυγῆς δʼ οὐκ ἄλλης ἢ ταύτης εὐποροῦντα, τινὲς μὲν τῶν φίλων καὶ ταῦτα συνεβούλευον αὐτῇ λαβεῖν καὶ τὴν χώραν ἐπελθούσῃ κατασχεῖν καὶ μὴ περιιδεῖν ἐπʼ ἀνδρὶ ἑνὶ τοσοῦτο πλῆθος ἀγαθῶν Ἰουδαίων κείμενον."},{"number":354,"text":"Ἀνανίας δὲ συνεβούλευσε τούτοις ἐναντία, λέγων ἄδικα ποιήσειν αὐτήν, εἰ σύμμαχον ἄνθρωπον ἀφαιρήσεται τῆς ἰδίας ἐξουσίας καὶ ταῦτα συγγενῆ ἡμέτερον· οὐ γὰρ ἀγνοεῖν βούλομαί σε, φησίν, εἰ τὸ πρὸς τοῦτον ἄδικον ἐχθροὺς ἅπαντας ἡμᾶς σοι τοὺς Ἰουδαίους κατασκευάζει."},{"number":355,"text":"ταῦτα δὲ Ἀνανία παραινέσαντος ἡ Κλεοπάτρα πείθεται μηδὲν ἀδικῆσαι τὸν Ἀλέξανδρον, ἀλλὰ συμμαχίαν πρὸς αὐτὸν ἐποιήσατο ἐν Σκυθοπόλει τῆς κοίλης Συρίας."},{"number":356,"text":"Ὁ δὲ τῶν ἐκ Πτολεμαίου φόβων ἐλευθερωθεὶς στρατεύεται μὲν εὐθὺς ἐπὶ τὴν κοίλην Συρίαν, αἱρεῖ δὲ Γάδαρα πολιορκήσας δέκα μησίν, αἱρεῖ δὲ καὶ Ἀμαθοῦντα μέγιστον ἔρυμα τῶν ὑπὲρ τὸν Ἰορδάνην κατῳκημένων, ἔνθα καὶ τὰ κάλλιστα καὶ σπουδῆς ἄξια Θεόδωρος ὁ Ζήνωνος εἶχεν. ὃς οὐ προσδοκῶσιν ἐπιπεσὼν τοῖς Ἰουδαίοις μυρίους αὐτῶν ἀποκτείνει καὶ τὴν ἀποσκευὴν Ἀλεξάνδρου διαρπάζει."},{"number":357,"text":"ταῦτα μὲν οὖν οὐ καταπλήττει τὸν Ἀλέξανδρον, ἀλλʼ ἐπιστρατεύει τοῖς θαλαττίοις μέρεσιν, Ῥαφείᾳ καὶ Ἀνθηδόνι, ἣν ὕστερον βασιλεὺς Ἡρώδης Ἀγριππιάδα προσηγόρευσεν, καὶ κατὰ κράτος εἷλεν καὶ ταύτην."},{"number":358,"text":"ὁρῶν δὲ τὸν Πτολεμαῖον ἐκ τῆς Γάζης εἰς Κύπρον ἀνακεχωρηκότα, τὴν δὲ μητέρα αὐτοῦ Κλεοπάτραν εἰς Αἴγυπτον, ὀργιζόμενος δὲ τοῖς Γαζαίοις, ὅτι Πτολεμαῖον ἐπεκαλέσαντο βοηθόν, ἐπολιόρκει τὴν πόλιν καὶ τὴν χώραν αὐτῶν προενόμευσεν."},{"number":359,"text":"Ἀπολλοδότου δὲ τοῦ στρατηγοῦ τῶν Γαζαίων μετὰ δισχιλίων ξένων καὶ μυρίων οἰκετῶν νύκτωρ ἐπιπεσόντος τῷ τῶν Ἰουδαίων στρατοπέδῳ ἐφʼ ὅσον μὲν ὑπῆρχεν ἡ νὺξ ἐνίκων οἱ Γαζαῖοι δόκησιν παρασχόντες τοῖς πολεμίοις ὡς ἐπεληλυθότος αὐτοῖς Πτολεμαίου, γενομένης δὲ ἡμέρας καὶ τῆς δόξης ἐλεγχθείσης μαθόντες οἱ Ἰουδαῖοι τἀληθὲς ἐπισυστρέφονται καὶ τοῖς Γαζαίοις προσβαλόντες ἀναιροῦσιν αὐτῶν περὶ χιλίους."},{"number":360,"text":"τῶν δὲ Γαζαίων ἀντεχόντων καὶ μήτε ὑπὸ τῆς ἐνδείας μήτε ὑπὸ τοῦ πλήθους τῶν ἀναιρουμένων ἐνδιδόντων, πᾶν γὰρ ὁτιοῦν ὑπέμενον παθεῖν ἢ ὑπὸ τῷ πολεμίῳ γενέσθαι, προσεπήγειρεν δʼ αὐτῶν τὴν προθυμίαν καὶ Ἀρέτας ὁ Ἀράβων βασιλεὺς ἐπίδοξος ὢν ἥξειν αὐτοῖς σύμμαχος."},{"number":361,"text":"ἀλλὰ συνέβη πρῶτον τὸν Ἀπολλόδοτον διαφθαρῆναι· Λυσίμαχος γὰρ ἀδελφὸς αὐτοῦ ζηλοτυπῶν αὐτὸν ἐπὶ τῷ παρὰ τοῖς πολίταις εὐδοκιμεῖν, κτείνας αὐτὸν καὶ στρατιωτικὸν συγκροτήσας ἐνδίδωσιν Ἀλεξάνδρῳ τὴν πόλιν."},{"number":362,"text":"ὁ δʼ εὐθὺς μὲν εἰσελθὼν ἠρέμει, μετὰ δὲ ταῦτα τὴν δύναμιν ἐπαφῆκε τοῖς Γαζαίοις ἐπιτρέψας τιμωρεῖν αὐτούς· οἱ δὲ ἄλλοι ἀλλαχῆ τρεπόμενοι τοὺς Γαζαίους ἀπέκτειναν. ἦσαν δʼ οὐδʼ ἐκεῖνοι τὰς ψυχὰς ἀγεννεῖς, ἀλλὰ καὶ τοῖς παραπίπτουσιν ἀμυνόμενοι τοὺς Ἰουδαίους οὐκ ἐλάττονας αὐτῶν διέφθειραν."},{"number":363,"text":"ἔνιοι δὲ μονούμενοι τὰς οἰκίας ἐνεπίμπρασαν, ὡς μηδὲν ἐξ αὐτῶν λάφυρον εἶναι τοῖς πολεμίοις λαβεῖν. οἱ δὲ καὶ τῶν τέκνων καὶ τῶν γυναικῶν αὐτόχειρες ἐγένοντο τῆς ὑπὸ τοῖς ἐχθροῖς αὐτὰ δουλείας οὕτως ἀπαλλάττειν ἠναγκασμένοι."},{"number":364,"text":"τῶν δὲ βουλευτῶν ἦσαν οἱ πάντες πεντακόσιοι συμφυγόντες εἰς τὸ τοῦ Ἀπόλλωνος ἱερόν· συνεδρευόντων γὰρ τὴν ἐπίθεσιν συνέβη γενέσθαι· ὁ δὲ Ἀλέξανδρος τούτους τε ἀναιρεῖ καὶ τὴν πόλιν αὐτοῖς ἐπικατασκάψας ὑπέστρεψεν εἰς Ἱεροσόλυμα ἐνιαυτῷ πολιορκήσας."},{"number":365,"text":"Ὑπὸ τὸν αὐτὸν δὲ τοῦτον καιρὸν καὶ Ἀντίοχος ὁ ἐπικληθεὶς Γρυπὸς ἀποθνήσκει ὑπὸ Ἡρακλέωνος ἐπιβουλευθείς, βιώσας μὲν ἔτη τεσσαράκοντα καὶ πέντε, βασιλεύσας δὲ ἐννέα καὶ εἴκοσι."},{"number":366,"text":"διαδεξάμενος δὲ τὴν βασιλείαν αὐτοῦ ὁ παῖς Σέλευκος ἐπολέμει μὲν τῷ τοῦ πατρὸς ἀδελφῷ Ἀντιόχῳ, ὃς ἐπεκαλεῖτο Κυζικηνός, νικήσας δʼ αὐτὸν καὶ λαβὼν ἀπέκτεινεν."},{"number":367,"text":"μετʼ οὐ πολὺ δὲ τοῦ Κυζικηνοῦ παῖς Ἀντίοχος, ὁ Εὐσεβὴς καλούμενος, παραγενηθεὶς εἰς Ἄραδον καὶ περιθέμενος διάδημα πολεμεῖ τῷ Σελεύκῳ, καὶ κρατήσας ἐξήλασεν αὐτὸν ἐκ πάσης τῆς Συρίας."},{"number":368,"text":"ὁ δὲ φυγὼν εἰς Κιλικίαν καὶ γενόμενος ἐν τῇ Μόψου ἑστίᾳ πάλιν αὐτοὺς εἰσέπραττε χρήματα. ὁ δὲ τῶν Μοψεστέων δῆμος ἀγανακτήσας ὑφῆψεν αὐτοῦ τὰ βασίλεια καὶ διέφθειρεν αὐτὸν μετὰ τῶν φίλων."},{"number":369,"text":"Ἀντιόχου δὲ τοῦ Κυζικηνοῦ παιδὸς βασιλεύοντος τῆς Συρίας Ἀντίοχος ὁ Σελεύκου ἀδελφὸς ἐκφέρει πόλεμον πρὸς αὐτὸν καὶ νικηθεὶς ἀπόλλυται μετὰ τῆς στρατιᾶς. μετὰ δʼ αὐτὸν ὁ ἀδελφὸς αὐτοῦ Φίλιππος ἐπιθέμενος διάδημα μέρους τινὸς τῆς Συρίας ἐβασίλευσεν."},{"number":370,"text":"Πτολεμαῖος δὲ ὁ Λάθουρος τὸν τρίτον αὐτῶν ἀδελφὸν Δημήτριον τὸν Ἄκαιρον λεγόμενον ἐκ Κνίδου μεταπεμψάμενος κατέστησεν ἐν Δαμασκῷ βασιλέα."},{"number":371,"text":"τούτοις δὲ τοῖς δυσὶν ἀδελφοῖς καρτερῶς ἀνθιστάμενος Ἀντίοχος ταχέως ἀπέθανεν· Λαοδίκῃ γὰρ ἐλθὼν σύμμαχος τῇ τῶν Σαμηνῶν βασιλίσσῃ Πάρθους πολεμούσῃ μαχόμενος ἀνδρείως ἔπεσεν. τὴν δὲ Συρίαν οἱ δύο κατεῖχον ἀδελφοὶ Δημήτριος καὶ Φίλιππος, καθὼς ἐν ἄλλοις δεδήλωται."},{"number":372,"text":"Ἀλέξανδρος δὲ τῶν οἰκείων πρὸς αὐτὸν στασιασάντων, ἐπανέστη γὰρ αὐτῷ τὸ ἔθνος ἑορτῆς ἀγομένης καὶ ἑστῶτος αὐτοῦ ἐπὶ τοῦ βωμοῦ καὶ θύειν μέλλοντος κιτρίοις αὐτὸν ἔβαλλον, νόμου ὄντος παρὰ τοῖς Ἰουδαίοις ἐν τῇ σκηνοπηγίᾳ ἔχειν ἕκαστον θύρσους ἐκ φοινίκων καὶ κιτρίων, δεδηλώκαμεν δὲ καὶ ταῦτα ἐν ἄλλοις, προσεξελοιδόρησαν δʼ αὐτὸν ὡς ἐξ αἰχμαλώτων γεγονότα καὶ τῆς τιμῆς καὶ τοῦ θύειν ἀνάξιον,"},{"number":373,"text":"ἐπὶ τούτοις ὀργισθεὶς κτείνει μὲν αὐτῶν περὶ ἑξακισχιλίους, δρύφακτον δὲ ξύλινον περὶ τὸν βωμὸν καὶ τὸν ναὸν βαλόμενος μέχρι τοῦ θριγκοῦ, εἰς ὃν μόνοις ἐξῆν τοῖς ἱερεῦσιν εἰσιέναι, τούτῳ τὴν τοῦ πλήθους ἐπʼ αὐτὸν ἀπέφραττεν εἴσοδον."},{"number":374,"text":"ἔτρεφεν δὲ καὶ ξένους Πισίδας καὶ Κίλικας· Σύροις γὰρ πολέμιος ὢν οὐκ ἐχρῆτο. καταστρεψάμενος δὲ τῶν Ἀράβων Μωαβίτας καὶ Γαλααδίτας εἰς φόρου ἀπαγωγήν, κατερείπει καὶ Ἀμαθοῦντα Θεοδώρου μὴ τολμῶντος αὐτῷ συμβαλεῖν."},{"number":375,"text":"συνάψας δὲ μάχην πρὸς Ὀβέδαν τὸν Ἀράβων βασιλέα καὶ πεσὼν εἰς ἐνέδραν ἐν χωρίοις τραχέσι καὶ δυσβάτοις ὑπὸ πλήθους καμήλων εἰς βαθεῖαν κατερράχθη φάραγγα κατὰ Γάδαρα κώμην τῆς ϊουδάνιδος καὶ μόλις αὐτὸς διασώζεται, φεύγων δʼ ἐκεῖθεν εἰς Ἱεροσόλυμα παραγίνεται."},{"number":376,"text":"καὶ πρὸς τὴν κακοπραγίαν αὐτοῦ ἐπιθεμένου τοῦ ἔθνους πολεμήσας πρὸς αὐτὸ ἔτεσιν ἓξ ἀναιρεῖ τῶν Ἰουδαίων οὐκ ἔλαττον πέντε μυριάδας. παρακαλοῦντος δὲ παῦσαι τὴν πρὸς αὐτὸν δυσμένειαν ἔτι μᾶλλον ἐμίσουν αὐτὸν διὰ τὰ συμβεβηκότα. πυνθανομένου δʼ αὐτοῦ τί βούλονται, πάντες γενέσθαι ἐβόησαν ἀποθανεῖν αὐτόν, καὶ πρὸς Δημήτριον τὸν Ἄκαιρον ἔπεμψαν παρακαλοῦντες ἐπὶ συμμαχίαν."}],"14":[{"number":377,"text":"Ὁ δὲ μετὰ στρατιᾶς ἐλθὼν καὶ παραλαβὼν τοὺς ἐπικαλεσαμένους περὶ Σίκιμα πόλιν ἐστρατοπέδευσεν. Ἀλέξανδρος δὲ μετὰ μισθοφόρων ἑξακισχιλίων καὶ διακοσίων Ἰουδαίων τε περὶ δισμυρίους οἳ ἐφρόνουν τὰ ἐκείνου παραλαβὼν ἀντεπῄει τῷ Δημητρίῳ· τούτῳ δʼ ἦσαν ἱππεῖς μὲν τρισχίλιοι, πεζῶν δὲ τέσσαρες μυριάδες."},{"number":378,"text":"πολλὰ μὲν οὖν ἑκατέροις ἐπράχθη, τοῦ μὲν ἀποστῆσαι τοὺς μισθοφόρους ὡς ὄντας Ἕλληνας πειρωμένου, τοῦ δὲ τοὺς σὺν Δημητρίῳ Ἰουδαίους. μηδετέρου δὲ πεῖσαι δυνηθέντος, ἀλλʼ εἰς μάχην συμβαλόντων, νικᾷ Δημήτριος, καὶ ἀποθνήσκουσι μὲν οἱ Ἀλεξάνδρου μισθοφόροι πάντες πίστεως ἅμα καὶ ἀνδρείας ἐπίδειξιν ποιησάμενοι, πολλοὶ δὲ καὶ τῶν Δημητρίου στρατιωτῶν."},{"number":379,"text":"Φεύγοντος δʼ Ἀλεξάνδρου εἰς τὰ ὄρη κατὰ οἶκτον τῆς μεταβολῆς συλλέγονται παρʼ αὐτὸν Ἰουδαίων ἑξακισχίλιοι. καὶ τότε μὲν δείσας ὑποχωρεῖ Δημήτριος. μετὰ ταῦτα δὲ οἱ Ἰουδαῖοι ἐπολέμουν Ἀλεξάνδρῳ καὶ νικώμενοι πολλοὶ ἀπέθνησκον ἐν ταῖς μάχαις."},{"number":380,"text":"κατακλείσας δὲ τοὺς δυνατωτάτους αὐτᾶν ἐν Βαιθομμει πόλει ἐπολιόρκει, λαβὼν δὲ τὴν πόλιν καὶ γενόμενος ἐγκρατὴς αὐτῶν ἀνήγαγεν εἰς Ἱεροσόλυμα καὶ πάντων ὠμότατον ἔργον ἔδρασεν· ἑστιώμενος γὰρ ἐν ἀπόπτῳ μετὰ τῶν παλλακίδων ἀνασταυρῶσαι προσέταξεν αὐτῶν ὡς ὀκτακοσίους, τοὺς δὲ παῖδας αὐτῶν καὶ τὰς γυναῖκας ἔτι ζώντων παρὰ τὰς ἐκείνων ὄψεις ἀπέσφαττεν,"},{"number":381,"text":"ὑπὲρ μὲν ὧν ἠδίκητο ἀμυνόμενος, ἄλλως δὲ ὑπὲρ ἄνθρωπον ταύτην εἰσπραττόμενος τὴν δίκην, εἰ καὶ τὰ μάλιστα, ὅπερ ἦν εἰκός, ἐταλαιπωρήθη τοῖς πρὸς αὐτοὺς πολέμοις καὶ εἰς τοὔσχατον ἧκε κινδύνου ψυχῆς τε πέρι καὶ βασιλείας, οὐκ ἀρκουμένων ἀγωνίζεσθαι κατὰ σφᾶς αὐτούς,"},{"number":382,"text":"ἀλλὰ καὶ ἀλλοφύλους ἐπαγόντων καὶ τὸ τελευταῖον εἰς τοῦτο ἀνάγκης ἀγαγόντων, ὥστε ἣν κατεστρέψατο γῆν ἐν Γαλααδίτιδι καὶ Μωαβίτιδι καὶ τὰ χωρία τῶν Ἀράβων τῷ βασιλεῖ παραδοῦναι, ὅπως ἂν μὴ ξυνάρηται σφίσι τὸν κατʼ αὐτοῦ πόλεμον, ἄλλα τε μυρία ἐς ὕβριν αὐτοῦ καὶ ἐπήρειαν πραξάντων."},{"number":383,"text":"ἀλλʼ οὖν οὐκ ἐπιτηδείως δοκεῖ ταῦτα δρᾶσαι, ὥστε διὰ τὴν τῆς ὠμότητος ὑπερβολὴν ἐπικληθῆναι αὐτὸν ὑπὸ τῶν Ἰουδαίων Θρακίδαν. οἱ δʼ ἀντιστασιῶται αὐτοῦ τὸ πλῆθος ὄντες περὶ ὀκτακισχιλίους φεύγουσιν νυκτὸς καὶ παρʼ ὃν ἔζη χρόνον Ἀλέξανδρος ἦσαν ἐν τῇ φυγῇ. καὶ οὗτος μὲν ἀπηλλαγμένος τῆς ἐκ τούτων ταραχῆς μετὰ πάσης τὸ λοιπὸν ἠρεμίας ἐβασίλευσεν."},{"number":384,"text":"Δημήτριος δʼ ἐκ τῆς Ἰουδαίας ἀπελθὼν εἰς Βέροιαν ἐπολιόρκει τὸν ἀδελφὸν αὐτοῦ Φίλιππον ὄντων αὐτῷ πεζῶν μὲν μυρίων, χιλίων δὲ ἱππέων. Στράτων δʼ ὁ τῆς Βεροίας τύραννος Φιλίππῳ συμμαχῶν Ἄζιζον τὸν Ἀράβων φύλαρχον ἐπεκαλεῖτο καὶ Μιθριδάτην τὸν Σινάκην τὸν Παρθυαίων ὕπαρχον."},{"number":385,"text":"ὧν ἀφικομένων μετὰ πολλῆς δυνάμεως καὶ πολιορκούντων Δημήτριον ἐντὸς τοῦ χαρακώματος, εἴσω τοῖς τε τοξεύμασι καὶ τῇ δίψῃ συνέχοντες αὐτὸν ἠνάγκασαν τοὺς σὺν αὐτῷ σφᾶς παραδοῦναι. λαφυραγωγήσαντες δὲ τὰ ἐν τῇ χώρᾳ καὶ τὸν Δημήτριον παραλαβόντες τὸν μὲν τῷ Μιθριδάτῃ τῷ τότε βασιλεύοντι Πάρθων ἔπεμψαν, τῶν δʼ αἰχμαλώτων οὓς Ἀντιοχέων εἶναι πολίτας συνέβαινε τούτους προῖκα τοῖς Ἀντιοχεῦσιν ἀπέδωκαν."},{"number":386,"text":"Μιθριδάτης δʼ ὁ τῶν Πάρθων βασιλεὺς Δημήτριον εἶχεν ἐν τιμῇ τῇ πάσῃ μέχρι νόσῳ κατέστρεψε Δημήτριος τὸν βίον. Φίλιππος δὲ ἀπὸ τῆς μάχης εὐθὺς εἰς Ἀντιόχειαν ἐλθὼν καὶ κατασχὼν αὐτὴν ἐβασίλευσεν τῆς Συρίας."}],"15":[{"number":387,"text":"Ἔπειτα Ἀντίοχος ὁ κληθεὶς Διόνυσος ἀδελφὸς ὢν Φιλίππου, τῆς ἀρχῆς ἀντιποιούμενος εἰς Δαμασκὸν παραγίνεται, καὶ τῶν ἐκεῖ πραγμάτων ἐγκρατὴς γενόμενος ἐβασίλευσεν. ἐκστρατεύσαντος δὲ ἐπὶ τοὺς Ἄραβας αὐτοῦ Φίλιππος ὁ ἀδελφὸς τοῦτʼ ἀκούσας ἐπὶ Δαμασκὸν ἦλθεν."},{"number":388,"text":"Μιλησίου δʼ, ὃς καταλέλειπτο τῆς ἄκρας φύλαξ καὶ τῶν Δαμασκηνῶν, παραδόντος αὐτῷ τὴν πόλιν, ἀχάριστος εἰς αὐτὸν γενόμενος καὶ μηδὲν ὧν ἐλπίσας ἐδέξατο αὐτὸν παρασχών, ἀλλὰ τῷ παρʼ αὐτοῦ φόβῳ βουληθεὶς δοκεῖν παραλαβεῖν τὴν πόλιν ἢ τῇ χάριτι τῇ Μιλησίου δωρούμενος αὐτὸν οἷς ἐχρῆν, ὑπωπτεύετο καὶ πάλιν ἐκπίπτει τῆς Δαμασκοῦ·"},{"number":389,"text":"ἐξορμήσαντος γὰρ αὐτοῦ εἰς ἱππόδρομον ἀπέκλεισεν ὁ Μιλήσιος καὶ τὴν Δαμασκὸν Ἀντιόχῳ διεφύλαξεν. ὃς ἀκούσας τὰ περὶ τὸν Φίλιππον ὑπέστρεψεν ἐκ τῆς Ἀραβίας, στρατεύεται δʼ εὐθὺς ἐλθὼν ἐπὶ τὴν Ἰουδαίαν ὁπλίταις μὲν ὀκτακισχιλίοις, ἱππεῦσι δὲ ὀκτακοσίοις."},{"number":390,"text":"δείσας δὲ Ἀλέξανδρος τὴν ἔφοδον αὐτοῦ τάφρον ὀρύττει βαθεῖαν ἀπὸ τῆς Χαβερσαβᾶ ἀρξάμενος, ἣ νῦν Ἀντιπατρὶς καλεῖται, ἄχρι τῆς εἰς Ἰόππην θαλάσσης, ᾗ καὶ μόνον ἦν ἐπίμαχον· τεῖχός τʼ ἐγείρας καὶ πύργους ἀναστήσας ξυλίνους καὶ μεταπύργια ἐπὶ σταδίους ἑκατὸν ἑξήκοντα ἐξεδέχετο τὸν Ἀντίοχον."},{"number":391,"text":"ὁ δὲ ταῦτα πάντα ἐμπρήσας διεβίβαζε ταύτῃ τὴν δύναμιν ἐπὶ τὴν Ἀραβίαν. ἀναχωροῦντος δὲ τοῦ Ἄραβος τὰ πρῶτα, ἔπειτα μετὰ μυρίων ἱππέων ἐξαίφνης ἐπιφανέντος ὑπαντήσας τούτοις Ἀντίοχος καρτερῶς ἐμάχετο, καὶ δὴ νικῶν ἀπέθανεν παραβοηθῶν τῷ πονοῦντι μέρει. πεσόντος δʼ Ἀντιόχου καὶ τὸ στράτευμα φεύγει εἰς Κανὰ κώμην, ἔνθα τὸ πλεῖον αὐτῶν λιμῷ φθείρεται."},{"number":392,"text":"Βασιλεύει δὲ μετʼ αὐτὸν τῆς κοίλης Συρίας Ἀρέτας κληθεὶς εἰς τὴν ἀρχὴν ὑπὸ τῶν τὴν Δαμασκὸν ἐχόντων διὰ τὸ πρὸς Πτολεμαῖον τὸν Μενναίου μῖσος. στρατεύσας δʼ ἐκεῖθεν ἐπὶ τὴν Ἰουδαίαν καὶ περὶ Ἄδιδα χωρίον μάχῃ νικήσας Ἀλέξανδρον ἐπὶ συνθήκαις ἀνεχώρησεν ἐκ τῆς Ἰουδαίας."},{"number":393,"text":"Ἀλέξανδρος δʼ ἐλάσας αὖθις ἐπὶ Δίαν πόλιν αἱρεῖ ταύτην, καὶ στρατεύσας ἐπὶ Ἔσσαν, οὗ τὰ πλείστου ἄξια Ζήνωνι συνέβαινεν εἶναι, τρισὶν μὲν περιβάλλει τείχεσιν τὸ χωρίον, ἀμαχὶ δὲ λαβὼν τὴν πόλιν ἐπὶ Γαύλαναν καὶ Σελεύκειαν ἐξώρμησεν."},{"number":394,"text":"παραλαβὼν δὲ καὶ ταύτας προσεξεῖλεν καὶ τὴν Ἀντιόχου λεγομένην φάραγγα καὶ Γάμαλα τὸ φρούριον. ἐγκαλῶν δὲ πολλὰ Δημητρίῳ τῷ τῶν τόπων ἄρχοντι περιέδυσεν αὐτόν, καὶ τρίτον ἤδη πεπληρωκὼς ἔτος τῆς στρατείας εἰς τὴν οἰκείαν ὑπέστρεψεν προθύμως αὐτὸν τῶν Ἰουδαίων διὰ τὴν εὐπραγίαν δεχομένων."},{"number":395,"text":"Κατὰ δὴ τοῦτον τὸν καιρὸν ἤδη τῶν Σύρων καὶ Ἰδουμαίων καὶ Φοινίκων πόλεις εἶχον οἱ Ἰουδαῖοι πρὸς θαλάσσῃ μὲν Στράτωνος πύργον Ἀπολλωνίαν Ἰόππην Ἰάμνειαν Ἄζωτον Γάζαν Ἀνθηδόνα Ῥάφειαν Ῥινοκόρουρα,"},{"number":396,"text":"ἐν δὲ τῇ μεσογαίᾳ κατὰ τὴν Ἰδουμαίαν Ἄδωρα καὶ Μάρισαν καὶ ὅλην Ἰδουμαίαν, Σαμάρειαν Καρμήλιον ὄρος καὶ τὸ Ἰταβύριον ὄρος Σκυθόπολιν Γάδαρα, Γαυλανίτιδας Σελεύκειαν Γάβαλα,"},{"number":397,"text":"Μωαβίτιδας Ἠσεβὼν Μήδαβα Λεμβὰ Ορωναιμαγελεθων Ζόαρα Κιλίκων αὐλῶνα Πέλλαν, ταύτην κατέσκαψεν ὑποσχομένων τῶν ἐνοικούντων ἐς πάτρια τῶν Ἰουδαίων ἔθη μεταβαλεῖσθαι, ἄλλας τε πόλεις πρωτευούσας τῆς Συρίας ἦσαν κατεστραμμένοι."},{"number":398,"text":"Μετὰ δὲ ταῦτα ὁ βασιλεὺς Ἀλέξανδρος ἐκ μέθης εἰς νόσον καταπεσὼν καὶ τρισὶν ἔτεσιν τεταρταίῳ πυρετῷ συσχεθεὶς οὐκ ἀπέστη τῶν στρατειῶν, ἕως οὗ τοῖς πόνοις ἐξαναλωθεὶς ἀπέθανεν ἐν τοῖς Γερασηνῶν ὅροις πολιορκῶν Ῥάγαβα φρούριον πέραν τοῦ Ἰορδάνου."},{"number":399,"text":"ὁρῶσα δʼ αὐτὸν ἡ βασίλισσα πρὸς τῷ τελευτᾶν ὄντα καὶ μηδεμίαν ὑπογράφοντα μηκέτι σωτηρίας ἐλπίδα, κλαίουσα καὶ κοπτομένη τῆς μελλούσης ἐρημίας αὐτήν τε καὶ τοὺς παῖδας ἀπωδύρετο καί τίνι καταλείπεις οὕτως ἐμέ τε καὶ τὰ τέκνα τῆς παρʼ ἄλλων βοηθείας δεόμενα πρὸς αὐτὸν ἔλεγεν καὶ ταῦτʼ εἰδώς, πῶς διάκειται πρὸς σὲ δυσμενῶς τὸ ἔθνος."},{"number":400,"text":"ὁ δὲ συνεβούλευεν αὐτῇ πείθεσθαι μὲν οἷς ὑποθήσεται πρὸς τὸ τὴν βασιλείαν ἀσφαλῶς κατέχειν μετὰ τῶν τέκνων, κρύψαι δὲ τὸν θάνατον αὐτοῦ πρὸς τοὺς στρατιώτας, ἕως ἂν ἐξέλῃ τὸ χωρίον."},{"number":401,"text":"ἔπειτα ὡς ἀπὸ νίκης λαμπρῶς εἰς τὰ Ἱεροσόλυμα παραγινομένην τοῖς Φαρισαίοις ἐξουσίαν τινὰ παρασχεῖν· τούτους γὰρ ἐπαινοῦντας αὐτὴν ἀντὶ τῆς τιμῆς εὔνουν καταστήσειν αὐτῇ τὸ ἔθνος, δύνασθαι δὲ πολὺ παρὰ τοῖς Ἰουδαίοις τούτους ἔφασκε βλάψαι τε μισοῦντας καὶ φίλους διακειμένους ὠφελῆσαι·"},{"number":402,"text":"μάλιστα γὰρ πιστεύεσθαι παρὰ τῷ πλήθει περὶ ὧν ἂν κἂν φθονῶσίν τι χαλεπὸν λέγωσιν, αὐτόν τε προσκροῦσαι τῷ ἔθνει διὰ τούτους ἔλεγεν ὑβρισθέντας ὑπʼ αὐτοῦ."},{"number":403,"text":"σὺ τοίνυν, εἶπεν, ἐν τοῖς Ἱεροσολύμοις γενομένη μετάπεμψαι μὲν τοὺς στασιώτας αὐτῶν, ἐπιδείξασα δὲ τὸ σῶμα τοὐμὸν ἐκείνοις ὅπως μοι βούλονται χρῆσθαι μετὰ πολλῆς ἀξιοπιστίας ἐπίτρεπε, εἴτε καθυβρίζειν ἀταφίᾳ μου θελήσουσι τὸν νεκρὸν ὡς πολλὰ πεπονθότες ἐξ ἐμοῦ, εἴτʼ ἄλλην τινὰ κατʼ ὀργὴν αἰκίαν τῷ σώματι προσφέρειν. ὑπόσχου τε καὶ μηδὲν δίχα τῆς ἐκείνων γνώμης ἐν τῇ βασιλείᾳ διαπράξεσθαι."},{"number":404,"text":"ταῦτά σου πρὸς αὐτοὺς εἰπούσης ἐγώ τε λαμπροτέρας ἀξιωθήσομαι πρὸς αὐτῶν κηδείας ἧς ἂν ἔτυχον ἐκ σοῦ, μηδὲν διὰ τὸ ἐξεῖναι ποιεῖν μου κακῶς τὸν νεκρὸν διαθεῖναι θελησάντων, σύ τε βεβαίως ἄρξεις. ταῦτα παραινέσας τῇ γυναικὶ τελευτᾷ βασιλεύσας ἔτη ἑπτὰ καὶ εἴκοσι, βιώσας δʼ ἓν καὶ πεντήκοντα."}],"16":[{"number":405,"text":"Ἡ δὲ Ἀλεξάνδρα τὸ φρούριον ἐξελοῦσα κατὰ τὰς τοῦ· ἀνδρὸς ὑποθήκας τοῖς τε Φαρισαίοις διελέχθη καὶ πάντα ἐπʼ ἐκείνοις θεμένη τά τε περὶ τοῦ νεκροῦ καὶ τῆς βασιλείας, τῆς μὲν ὀργῆς αὐτοὺς τῆς πρὸς Ἀλέξανδρον ἔπαυσεν, εὔνους δʼ ἐποίησεν καὶ φίλους."},{"number":406,"text":"οἱ δʼ εἰς τὸ πλῆθος παρελθόντες ἐδημηγόρουν τὰς πράξεις τὰς Ἀλεξάνδρου διηγούμενοι, καὶ ὅτι δίκαιος αὐτοῖς ἀπόλοιτο βασιλεύς, καὶ τὸν δῆμον εἰς πένθος καὶ τὴν ὑπὲρ αὐτοῦ κατήφειαν ἐξεκαλέσαντο τοῖς ἐπαίνοις, ὥστε καὶ λαμπρότερον ἤ τινα τῶν πρὸ αὐτοῦ βασιλέων αὐτὸν ἐκήδευσαν."},{"number":407,"text":"δύο μέντοι γε υἱοὺς Ἀλέξανδρος κατέλιπεν Ὑρκανὸν καὶ Ἀριστόβουλον, τὴν δὲ βασιλείαν εἰς τὴν Ἀλεξάνδραν διέθετο. τῶν δὲ παίδων Ὑρκανὸς μὲν ἀσθενὴς ἦν πράγματα διοικεῖν καὶ βίον ἡσύχιον μᾶλλον ἠγαπηκώς, ὁ δὲ νεώτερος Ἀριστόβουλος δραστήριός τε ἦν καὶ θαρσαλέος. ἐστέργετο μὲν οὖν ὑπὸ τοῦ πλήθους ἡ γυνὴ διὰ τὸ δοκεῖν ἐφʼ οἷς ὁ ἀνὴρ αὐτῆς ἐξήμαρτεν δυσχεραίνειν."},{"number":408,"text":"Ἡ δὲ ἀρχιερέα μὲν ἀπεδείκνυεν Ὑρκανὸν διὰ τὴν ἡλικίαν, πολὺ μέντοι πλέον διὰ τὸ ἄπραγμον αὐτοῦ, καὶ πάντα τοῖς Φαρισαίοις ἐπέτρεπεν ποιεῖν, οἷς καὶ τὸ πλῆθος ἐκέλευσεν πειθαρχεῖν καὶ εἴ τι δὲ καὶ τῶν νομίμων Ὑρκανὸς ὁ πενθερὸς αὐτῆς κατέλυσεν ὧν εἰσήνεγκαν οἱ Φαρισαῖοι κατὰ τὴν πατρῴαν παράδοσιν, τοῦτο πάλιν ἀποκατέστησεν."},{"number":409,"text":"τὸ μὲν οὖν ὄνομα τῆς βασιλείας εἶχεν αὐτή, τὴν δὲ δύναμιν οἱ Φαρισαῖοι· καὶ γὰρ φυγάδας οὗτοι κατῆγον καὶ δεσμώτας ἔλυον καὶ καθάπαξ οὐδὲν δεσποτῶν διέφερον. ἐποιεῖτο μέντοι καὶ ἡ γυνὴ τῆς βασιλείας πρόνοιαν, καὶ πολὺ μισθοφορικὸν συνίστησιν, καὶ τὴν ἰδίαν δύναμιν ἀπέδειξεν διπλασίονα, ὡς καταπλῆξαι τοὺς πέριξ τυράννους καὶ λαβεῖν ὅμηρα αὐτῶν."},{"number":410,"text":"ἠρέμει δʼ ἡ χώρα πᾶσα πάρεξ τῶν Φαρισαίων· οὗτοι γὰρ ἐπετάρασσον τὴν βασίλειαν πείθοντες, ὅπως κτείνειεν τοὺς Ἀλεξάνδρῳ παραινέσαντας ἀνελεῖν τοὺς ὀκτακοσίους. εἶτα αὐτοὶ τούτων ἕνα σφάττουσιν Διογένην καὶ μετʼ αὐτὸν ἄλλους ἐπʼ ἄλλοις,"},{"number":411,"text":"ἕως οὗ οἱ δυνατοὶ παρελθόντες εἰς τὸ βασίλειον καὶ μετʼ αὐτῶν Ἀριστόβουλος, ἐῴκει γὰρ τοῖς γινομένοις δυσανασχετῶν καὶ δῆλος ἦν, καθάπαξ εἰ ἀφορμῆς λάβοιτο, μὴ ἐπιτρέψων τῇ μητρί, ἀνεμίμνησκον ὅσα κατώρθωσαν τοσούτοις κινδύνοις, διʼ ὧν τὸ βέβαιον τῆς ἐν σφίσι πίστεως πρὸς τὸν δεσπότην ἐπεδείξαντο, ἀνθʼ ὧν ὑπʼ αὐτοῦ μεγίστων ἠξιώθησαν."},{"number":412,"text":"καὶ ἐδέοντο μὴ ἄχρι τοῦ παντὸς ἔμπαλιν τρέψαι σφίσι τὰς ἐλπίδας· ἀποφυγόντας γὰρ τὸν ἐκ πολεμίων κίνδυνον ἐν τῇ οἰκείᾳ ὑπʼ ἐχθρῶν δίκην βοσκημάτων κόπτεσθαι μηδεμιᾶς τιμωρίας οὔσης."},{"number":413,"text":"ἔλεγόν τε ὡς, εἰ μὲν ἀρκεσθεῖεν τοῖς ἀνῃρημένοις οἱ ἀντίδικοι, διὰ τὸ πρὸς τοὺς δεσπότας γνήσιον μετρίως οἴσειν τὰ ξυμβάντα, εἰ δʼ αὖ μέλλοιεν ταὐτὰ μετιέναι, ᾐτοῦντο μάλιστα μὲν δοθῆναι σφίσιν ἀπαλλαγήν· οὐδὲ γὰρ ἂν ὑπομεῖναι χωρὶς αὐτῆς πορίσασθαι τὸ σωτήριον, ἀλλʼ ἀσμενίζειν θνήσκοντες πρὸς τοῖς βασιλείοις, ὡς μὴ συγγνοῖεν ἀπιστίαν αὐτοῖς."},{"number":414,"text":"αἶσχός τε εἶναι σφίσι τε καὶ τῇ βασιλευούσῃ, εἰ πρὸς αὐτῆς ἀμελούμενοι ὑπὸ τῶν ἐχθρῶν τοῦ ἀνδρὸς ἐκδεχθείησαν· ἀντὶ παντὸς γὰρ τιμήσεσθαι Ἀρέταν τε τὸν Ἄραβα καὶ τοὺς μονάρχους, εἰ ἀποξενολογήσειεν τοσούσδε ἄνδρας, οἷς ἦν τάχα που φρικῶδες αὐτῶν καὶ τοὔνομα τὸ πρὶν ἀκουσθῆναι."},{"number":415,"text":"εἰ δὲ μή, τό γε δεύτερον, εἰ τοὺς Φαρισαίους αὐτῇ προτιμᾶν ἔγνωσται, κατατάξαι ἕκαστον αὐτῶν ἐν τοῖς φρουρίοις· εἰ γὰρ ὧδε δαίμων τις ἐπενεμέσησεν τῷ Ἀλεξάνδρου οἴκῳ, αὐτούς γε μὴν ἂν ἀποδεῖξαι καὶ ἐν ταπεινῷ σχήματι βιοτεύοντας."},{"number":416,"text":"Πολλὰ τοιαῦτα λεγόντων καὶ εἰς οἶκτον τῶν τεθνεώτων καὶ τῶν κινδυνευόντων τοὺς Ἀλεξάνδρου δαίμονας ἐπικαλουμένων, ἅπαντες οἱ περιεστῶτες ὥρμησαν εἰς δάκρυα, καὶ μάλιστα Ἀριστόβουλος ὅπως ἔχοι γνώμης ἐδήλου πολλὰ τὴν μητέρα κακίζων."},{"number":417,"text":"ἀλλὰ γὰρ ἐκεῖνοι μὲν αὐτοὶ σφίσι τῶν συμφορῶν ἐγένοντο αἴτιοι, κατὰ φιλαρχίαν ἐκλελυσσηκυίᾳ γυναικὶ παρὰ τὸ εἰκὸς βασιλεύειν γενεᾶς ἐν ἀκμῇ οὔσης ἐπιτρέψαντες· ἡ δὲ οὐκ ἔχουσα ὅ τι πράξειε μετὰ τοῦ εὐπρεποῦς τὴν φυλακὴν τῶν χωρίων σφίσιν ἐπέτρεψεν, ὅτι μὴ Ὑρκανίας καὶ Ἀλεξανδρείου καὶ Μαχαιροῦντος, ἔνθα τὰ πλείστου ἄξια ἦν αὐτῇ."},{"number":418,"text":"καὶ μετʼ οὐ πολὺ τὸν υἱὸν Ἀριστόβουλον μετὰ στρατιᾶς ἐξέπεμψεν ἐπὶ Δαμασκὸν κατὰ Πτολεμαίου τοῦ Μενναίου λεγομένου, ὃς βαρὺς ἦν τῇ πόλει γείτων. ἀλλʼ οἱ μὲν οὐδὲν ἐργασάμενοι σπουδῆς ἄξιον ὑπέστρεψαν."},{"number":419,"text":"Κατὰ δὲ τοῦτον τὸν καιρὸν ἀγγέλλεται Τιγράνης στρατοῦ μυριάσι τριάκοντα ἐμβεβληκὼς εἰς τὴν Συρίαν καὶ ἐπὶ τῆς Ἰουδαίας ἀφιξόμενος. τοῦτο ὥσπερ εἰκὸς ἐφόβησε τὴν βασίλισσαν καὶ τὸ ἔθνος. δῶρα δὴ καὶ πολλὰ καὶ λόγου ἄξια πέμπουσιν αὐτῷ καὶ πρέσβεις πολιορκοῦντι Πτολεμαΐδα."},{"number":420,"text":"βασίλισσα γὰρ Σελήνη ἡ καὶ Κλεοπάτρα καλουμένη τῶν ἐν τῇ Συρίᾳ κατέχειν, ἣ καὶ ἐνήγαγεν τοὺς ἐνοικοῦντας ἀποκλεῖσαι Τιγράνη νῦν ἐτύγχανεν καὶ ἐδέοντο χρηστὰ περὶ τῆς βασιλίσσης καὶ τοῦ ἔθνους συγγινώσκειν."},{"number":421,"text":"ὁ δὲ ἀποδεξάμενος αὐτοὺς τῆς ἐκ διαστήματος θεραπείας ἐλπίδας ὑπέθετο χρηστάς. ἄρτι δὲ τῆς Πτολεμαΐδος ἑαλωκυίας ἀγγέλλεται Τιγράνῃ Λεύκολλον διώκοντα Μιθριδάτην ἐκείνου μὲν διαμαρτεῖν εἰς τοὺς Ἴβηρας ἀναφυγόντος, τὴν δὲ Ἀρμενίαν πορθήσαντα πολιορκεῖν Τιγράνης δὲ καὶ ταῦτʼ ἐπιγνοὺς ἀνεχώρει τὴν ἐπʼ οἴκου."},{"number":422,"text":"Μετὰ δὲ τοῦτο τῆς βασιλίσσης εἰς νόσον χαλεπὴν ἐμπεσούσης δόξαν Ἀριστοβούλῳ τοῖς πράγμασιν ἐπιτίθεσθαι τῆς νυκτὸς ὑπεξελθὼν μεθʼ ἑνὸς τῶν θεραπόντων ᾔει ἐπὶ τὰ φρούρια, ἵνα οἱ πατρῷοι κατετάχθησαν αὐτῷ φίλοι."},{"number":423,"text":"πάλαι γὰρ ἀχθόμενος οἷς ἔπραττεν ἡ μήτηρ πολὺ μᾶλλον ἔδεισε, μὴ ἀποθανούσης ἐπὶ τοῖς Φαρισαίοις τὸ πᾶν γένος αὐτοῖς ὑπάρξειεν· ἑώρα γὰρ τὸ ἀδύνατον τοῦ μέλλοντος διαδέχεσθαι τὴν ἀρχὴν ἀδελφοῦ."},{"number":424,"text":"ξυνῄδει δὲ ἡ γυνὴ μόνη τῇ πράξει, ἣν κατέλιπεν αὐτόθι μετὰ τῆς γενεᾶς. καὶ πρῶτον ἀφικόμενος εἰς Ἄγαβα, ἔνθα Γαλαίστης ἦν τῶν δυνατῶν, ὑπεδέχθη πρὸς αὐτοῦ."},{"number":425,"text":"μεθʼ ἡμέραν δὲ αἴσθησις γίνεται τῇ βασιλίσσῃ τῆς Ἀριστοβούλου φυγῆς, καὶ μέχρι τινὸς ᾤετο γεγονέναι τὴν ἀναχώρησιν οὐκ ἐπὶ νεωτερισμῷ· ὡς μέντοι ἧκον ἀπαγγέλλοντες ἄλλοι ἐπʼ ἄλλοις, ὅτι κατειλήφει τὸ πρῶτον χωρίον καὶ τὸ δεύτερον καὶ ξύμπαντα, εὐθὺς γὰρ ἑνὸς ἀρξαμένου πάντα ἠπείγετο πρὸς τὸ ἐκείνου βούλημα, τότε δὴ ἐν μεγίσταις ταραχαῖς ὑπῆρχεν ἥ τε βασίλισσα καὶ τὸ ἔθνος."},{"number":426,"text":"ᾔδεισαν γὰρ οὐ πόρρω τοῦ δύνασθαι τὴν ἀρχὴν αὐτῷ κρατῦναι τὸν Ἀριστόβουλον ὄντα, ἐδεδίεσάν τε, μὴ ποινὴν εἰσπράξαιτο ὧν παρῴνησαν αὐτῷ τὸν οἶκον. δόξαν οὖν τήν τε γυναῖκα αὐτοῦ καὶ γενεὰν εἰς τὸ ὑπὲρ τοῦ ἱεροῦ φρούριον κατέθεσαν."},{"number":427,"text":"Ἀριστοβούλῳ δὲ ὡς ἂν ἐκ πολλῶν συχνὰ ἀνήχθη, ἀφʼ ὧν ἤδη καὶ κόσμος βασίλειος περὶ αὐτὸν ἦν· σχεδὸν γὰρ ἐν ἡμέραις δεκαπέντε χωρίων ἐκράτησεν εἰκοσιδύο, ὅθεν ἀφορμὰς ἔχων στρατιὰν ἤθροιζεν ἀπὸ Λιβάνου καὶ Τράχωνος καὶ τῶν μονάρχων· οἱ γὰρ ἄνθρωποι τῷ πλείονι ὑπαγόμενοι ῥᾳδίως ὑπήκουον· ἄλλως δὲ νομίζοντες, εἰ δὴ ξυλλάβοιεν αὐτῷ, τῶν μὴ προσδοκωμένων οὐχ ἧσσον καρπώσεσθαι τὴν βασιλείαν ὡς αὐτοὶ τοῦ κρατῆσαι πρόφασις γενηθέντες."},{"number":428,"text":"τῶν δὲ Ἰουδαίων οἱ πρεσβύτεροι καὶ Ὑρκανὸς ἐσῄεσαν ὡς τὴν βασίλισσαν καὶ ἐδέοντο ὑποθέσθαι γνώμην περὶ τῶν ἐνεστώτων· τὸν γὰρ Ἀριστόβουλον τῶν πάντων σχεδὸν ἤδη κυριεύειν, ὁπότε χωρίων τοσούτων κρατήσειεν· ἄτοπον δέ, εἰ καὶ τὰ μάλιστα κάμνοι, περιούσης αὐτῆς κατὰ σφᾶς βουλεύεσθαι· περιεστάναι δὲ τὸν κίνδυνον οὐ διὰ μακροῦ σφίσιν."},{"number":429,"text":"ἡ δὲ αὐτοὺς ἐκέλευσε πράττειν ὅ τι δοκοῦσι χρήσιμον εἶναι· πολλὰς δʼ ἀφορμὰς αὐτοῖς λείπεσθαι, τὸ ἔθνος ἐρρωμένον καὶ τὴν δύναμιν καὶ τὰ ἐν τοῖς γαζοφυλακίοις χρήματα· αὐτῇ μὲν γὰρ μικρὸν ἔτι μέλειν τῶν πραγμάτων ὡς ἂν ὑπολείποντος ἤδη τοῦ σώματος."},{"number":430,"text":"Ταῦτʼ εἰποῦσα μετʼ οὐ πολὺ ἐτελεύτησεν βασιλεύσασα ἔτη ἐννέα, τὰ δὲ σύμπαντα βιώσασα τρία καὶ ἑβδομήκοντα, γυνὴ τῷ ἀσθενεῖ τοῦ φύλου κατʼ οὐδὲν χρησαμένη· δεινὴ γὰρ εἰς τὸ φίλαρχον ἐν ταῖς μάλιστα γενομένη διήλεγξεν ἔργοις τό τε πρακτικὸν τῆς ἐν αὐτῇ γνώμης καὶ τὸ ἀσύνετον τῶν ἀεὶ πταιόντων περὶ τὰς δυναστείας ἀνδρῶν."},{"number":431,"text":"τὸ γὰρ παρὸν κρεῖττον ἀξιοῦσα τοῦ μέλλοντος καὶ πάντα δεύτερα τιθεμένη τοῦ ἐγκρατῶς ἄρχειν, οὔτε καλοῦ οὔτε δικαίου ἕνεκά γε τούτων ἐπεστρέφετο."},{"number":432,"text":"εἰς γοῦν τοῦτο τῷ οἴκῳ ἀτυχίας τὰ πράγματα περιέστησεν, ὥσθʼ ἣν μετὰ πλείστων κινδύνων καὶ ταλαιπωρίας περιεκτήσατο δυναστείαν ἐπιθυμίᾳ τῶν μὴ προσηκόντων γυναικὶ χρόνοις οὐ πολλοῖς ὕστερον ἀφαιρεθῆναι, τοῖς μὲν δυσμενῶς ἔχουσιν πρὸς τὸ γένος αὐτῶν τὴν αὐτὴν γνώμην προσθεῖσα, τὴν δὲ ἀρχὴν ἔρημον τῶν προκηδομένων ποιησαμένη."},{"number":433,"text":"καὶ ξυμφορῶν δὲ ἐνέπλησε καὶ ταραχῆς ἐξ ὧν ζῶσα ἐπολιτεύσατο καὶ μετὰ τὴν τελευτὴν τὸ βασίλειον· οὐ μὴν ἀλλὰ καίπερ οὕτως ἄρξασα ἐν εἰρήνῃ καὶ ἀταραξίᾳ τὸ ἔθνος διεφύλαξεν. τὰ μὲν οὖν περὶ Ἀλεξάνδραν τὴν βασίλισσαν τοῦτο εἶχεν τὸ τέλος· ἔρχομαι δὲ λέξων τὰ τοῖς υἱέσιν αὐτῆς συμβεβηκότα Ἀριστοβούλῳ καὶ Ὑρκανῷ μετὰ τὴν ἐκείνης τελευτὴν ἐν τῇ μετὰ ταύτην μου βίβλῳ."}]},"count":433};a[14]={"book":14,"title":"Τάδε ἔνεστιν ἐν τῇ τεσσαρεσκαιδεκάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς μετὰ τὸν Ἀλεξάνδρας θάνατον ὁ νεώτερος αὐτῆς τῶν παίδων Ἀριστόβουλος ἐπολέμησεν πρὸς Ὑρκανὸν τὸν ἀδελφὸν περὶ τῆς βασιλείας καὶ κρατήσας αὐτοῦ συνεδίωξεν εἰς τὴν ἐν Ἱεροσολύμοις βᾶριν, ἔπειθ' ὡς συμβάντες ἔκριναν βασιλεύειν μὲν Ἀριστόβουλον, Ὑρκανὸν δὲ ἰδιωτεύειν.\n\nπερὶ Ἀντιπάτρου καὶ γένους αὐτοῦ καὶ τίνα τρόπον ἐκ μικρᾶς καὶ τῆς τυχούσης ἀφορμῆς εἰς λαμπρότητα καὶ δόξαν ἅμα τοῖς παισὶν προήχθη καὶ μέγεθος δυνάμεως, καὶ ὅτι πείσαντος Ὑρκανὸν Ἀντιπάτρου φυγεῖν ἐξ Ἱεροσολύμων πρὸς Ἀρέταν τὸν τῶν Ἀράβων βασιλέα ἱκέτευσεν ἐλθὼν καταγαγεῖν αὐτὸν εἰς τὴν βασιλείαν γῆν τε πολλὴν δώσειν καὶ χρήματα ὑποσχόμενος.\n\nὡς Ἀρέτας προσδεξάμενος τὸν Ὑρκανὸν ἐστράτευσεν ἐπὶ τὸν Ἀριστόβουλον καὶ συμβαλὼν καὶ κρατήσας τῇ μάχῃ συνεδίωξεν ἐπὶ Ἱεροσόλυμα καὶ περικαθίσας τὸ στρατόπεδον ἐπολιόρκει τὴν πόλιν.\n\nὡς Σκαῦρον πέμψαντος ἀπὸ Ἀρμενίας εἰς Συρίαν Μάγνου Πομπηίου ἧκον πρὸς αὐτὸν ἀπό τε Ὑρκανοῦ καὶ Ἀριστοβούλου πρέσβεις περὶ συμμαχίας παρακαλοῦντες.\n\nὅτι Σκαῦρος τετρακοσίοις διαφθαρεὶς ταλάντοις Ἀριστοβούλῳ προσέθετο.\n\nὡς Ὑρκανὸς καὶ Ἀριστόβουλος περὶ τῆς βασιλείας ἐπὶ Πομπηίου δικαιολογοῦνται.\n\nὡς Πομπηίου εἰς Δαμασκὸν ἐκ τῆς Ἀρμενίας ἐλθόντος Ἀριστόβουλος καὶ Ὑρκανὸς ἐπὶ αὐτὸν ἧκον περὶ τῆς βασιλείας δικαιολογούμενοι.\n\n*πομπηίου ὑπέρθεσις διαγνώσεσθαι φήσαντος περὶ ὧν ἀλλήλοις ἐνεκάλουν, ἐπειδὰν εἰς τὴν ἐκείνων χώραν παραγένηται, καὶ ὅτι συνεὶς Ἀριστόβουλος τίνα ἔχει διάνοιαν Πομπήιος ἀνεχώρησεν εἰς Ἰουδαίαν, καὶ ὡς ἀγανακτήσαντος αὐτοῦ καὶ στρατεύσαντος ἐπ' αὐτὸν εἰς Ἀλεξάνδρειον Ἀριστόβουλος ἀνεχώρησεν τὸ φρούριον ὀχυρὸν ὂν καὶ δυσκαταμάχητον.\n\nὡς Πομπήιος τοῦτο συνιδὼν στρατηγήματι χρησάμενος ἔπεισεν τὸν Ἀριστόβουλον καταλιπόντα τὸ φρούριον καταβῆναι πρὸς αὐτὸν ὡς βεβαιωσόμενον αὐτῷ τὴν ἡγεμονίαν, οἷς πεισθέντα καὶ πολλάκις δικαιολογησάμενον πρὸς τὸν ἀδελφὸν ἠνάγκασε τοῖς φουράρχοις τῇ αὐτοῦ χειρὶ γράψαι καὶ παραδοῦναι αὐτῷ τὰ φρούρια.\n\nὡς Ἀριστόβουλος τοῦτο ποιήσας διὰ φόβον ἔπειτα δυσχεράνας ἐπὶ τῷ μηδενὸς ὧν προσεδόκα παρὰ Πομπηίου τυγχάνειν ἀνεχώρησεν εἰς Ἱεροσόλυμα.\n\nὡς Πομπηίου κατὰ πόδας μετὰ τῆς στρατιᾶς παρακολουθήσαντος μετενόησεν Ἀριστόβουλος καὶ προελθὼν ἄχρι Ἱεριχοῦντος ἀπήντησεν αὐτῷ καὶ συγγνώμης τυχεῖν δεηθεὶς περὶ τῶν ἡμαρτημένων τήν τε πόλιν καὶ τὰ χρήματα παραδώσειν ὑπέσχετο, καὶ Πομπηίου πέμψαντος Γαβίνιον μετὰ ἐπιλέκτων στρατιωτῶν ἐπί τε τὴν τῆς πόλεως παράληψιν καὶ τῶν χρημάτων οἱ Ἱεροσολυμῖται τὸν Ἀριστόβουλον ὁρῶντες ἐν φυλακῇ καθεστῶτα τὰς πύλας ἀπέκλεισαν τοῖς Ῥωμαίοις.\n\nὡς ἐπὶ τούτῳ παροξυνθεὶς Πομπήιος Ἀριστόβουλον μὲν ἔδησεν, προσαγαγὼν δὲ τὴν δύναμιν ἐπολιόρκει τὴν πόλιν, καὶ δέχονται μὲν αὐτὸν οἱ τὰ Ὑρκανοῦ φρονοῦντες εἰς τὴν πόλιν τὴν ἄνω, οἱ δὲ τὰ Ἀριστοβούλου φεύγουσιν εἰς τὸ ἱερόν.\n\nὡς αἱρεῖ κατὰ κράτος τὸ ἱερὸν καὶ τὴν κάτω πόλιν ὁ Πομπήιος τῷ τρίτῳ μηνί.\n\nπερὶ τῆς ἐπιεικείας αὐτοῦ καὶ θεοσεβείας, ὅτι μηδενὸς ἔψαυσεν τῶν ἐν τῷ ἱερῷ πολλῶν ὄντων τῶν ἐν αὐτῷ χρημάτων.\n\nὅτι ταῦτα διαπραξάμενος καὶ τὴν Ἰουδαίαν ποιήσας φόροις ὑποτελῆ καὶ Ὑρκανὸν ἀποδείξας ἐθνάρχην Ἀριστόβουλον μὲν δέσμιον μετὰ τῆς γενεᾶς εἰς Ῥώμην ἀνήγαγεν, Σκαῦρον δὲ τῆς Συρίας ἐπίτροπον κατέλιπεν.\n\nὅτι Σκαύρου στρατεύσαντος ἐπὶ Πέτραν βασίλειον οὖσαν τῶν Ἀράβων καὶ πολιορκοῦντος, ἐν ἐνδείᾳ τῶν στρατιωτῶν αὐτοῦ γενομένων Ἀντίπατρος πείθει τὸν Ἄραβα δόντα Σκαύρῳ τάλαντα τριακόσια συμμαχίαν πρὸς αὐτὸν ποιήσασθαι.\n\nὡς Ἀλέξανδρος ὁ Ἀριστοβούλου παῖς φυγὼν Πομπήιον καὶ παραγενόμενος εἰς Ἰουδαίαν στρατιᾶς αὐτῷ πολλῆς γενομένης πόλεμον ἐξήνεγκεν πρὸς Ὑρκανὸν καὶ Ἀντίπατρον.\n\nὡς ὑπὸ Γαβινίου κρατηθεὶς τῇ μάχῃ καὶ κατακλεισθεὶς εἰς Ἀλεξάνδρειον τὸ φρούριον ἐπολιορκεῖτο.\n\nὡς Γαβίνιος πεισάσης τῆς μητρὸς τῆς Ἀλεξάνδρου παραδοῦναι αὐτόν τε καὶ τὸ φρούριον λαβὼν τὸν μὲν Ἀλέξανδρον ἀφῆκεν, ἔγραψεν δὲ καὶ τῇ συγκλήτῳ τοὺς ἀδελφοὺς αὐτοῦ, οἳ ἦσαν μετὰ Ἀριστοβούλου τοῦ πατρὸς δεδεμένοι, λῦσαι καὶ ἀποπέμψαι πρὸς τὴν μητέρα, δηλῶν αὐτῆς τὸ πρὸς Ῥωμαίους πισὸν καὶ ὡς ἔστιν ἀξία ταύτης τῆς χάριτος τυγχάνειν.\n\nὡς μετὰ ταῦτα φυγόντα ἐκ Ῥώμης Ἀριστόβουλον εἰς Ἰουδαίαν λαβὼν Γαβίνιος αἰχμάλωτον πάλιν ἀνέπεμψεν εἰς Ῥώμην.\n\nΚράσσου κατὰ τὴν ἐπὶ Πάρθους στρατείαν εἰς τὴν Ἰουδαίαν ἀνάβασις καὶ σύλησις τῶν ἐν τῷ ἱερῷ χρημάτων.\n\nφυγὴ Πομπηίου εἰς Ἤπειρον καὶ Σκιπίωνος ὑπ' αὐτοῦ πεμφθέντος εἰς Συρίαν ἄφιξις ἐντολὴν ἔχοντος ἀποκτεῖναι Ἀλέξανδρον.\n\nὅτι Καῖσαρ λύσας Ἀριστόβουλον οἷός τε ἦν πέμψαι μετὰ δύο ταγμάτων εἰς Ἰουδαίαν, ἔφθη δ' ὑπὸ τῶν τὰ Πομπηίου φρονούντων διαφθαρεὶς Ἀριστόβουλος φαρμάκῳ.\n\nΚαίσαρος ἐπ' Αἰγύπτου στρατεία, καὶ ὡς συνεμάχησαν αὐτῷ Ὑρκανός τε καὶ Ἀντίπατρος καὶ τοὺς Ἰουδαίους αὐτῷ συμμάχους ἐποίησαν.\n\nἈντιπάτρου προθύμως ἀγωνισαμένου κατὰ τὴν μάχην ἀριστεία καὶ διὰ τοῦτο φιλία πρὸς Καίσαρα, καὶ ὡς Ὑρκανὸν Καῖσαρ ἐπὶ τῇ νίκῃ χαίρων ἐτίμησεν μεγάλως ἐπιτρέψας αὐτῷ τὰ τῆς πατρίδος ἀναστῆσαι τείχη.\n\nὡς Ἀντιπάτρῳ τὴν τῆς Ἰουδαίας ἐπιτροπὴν ἐνεχείρισεν.\n\nΚαίσαρος ἐπιστολαὶ καὶ δόγματα συγκλήτου περὶ τῆς πρὸς Ἰουδαίους φιλίας.\n\nὅτι Ἀντίπατρος τοῖς παισὶν Ἡρώδῃ μὲν τὴν τῆς Γαλιλαίας πρόνοιαν Φασαήλῳ δ' ἐπέτρεψεν τὴν Ἱεροσολύμων.\n\nὡς Καῖσαρ Σέξστος δωροδοκηθεὶς ὑφ' Ἡρώδου ἡγεμόνος ὄντος ἐν Συρίᾳ μέγαν καὶ ἔνδοξον ἐποίησεν Ἡρώδην καταστήσας ἄρχοντα τῆς κοίλης Συρίας.\n\nὡς Κάσσιος Καίσαρος ἀποθανόντος εἰς τὴν Ἰουδαίαν ἀναβὰς τήν τε χώραν ἐκάκωσεν καὶ τάλαντα ὀκτακόσια παρ' αὐτῶν εἰσεπράξατο, πῶς τε Ἡρώδης ἐκ τῆς εἰσπράξεως τῶν χρημάτων σπουδαῖος ἔδοξεν Κασσίῳ.\n\nΜαλίχου τελευτὴ τοῦ πρὸς Ἡρώδην στασιάσαντος Κασσίου κελεύσαντος.\n\nθάνατος τῶν ἀπὸ τῆς Ἰουδαίας πρεσβευτῶν ὑπὸ Ἀντωνίου μετὰ τὴν ἐν Μακεδονίᾳ νίκην ἐν Συρίᾳ γενομένου καὶ ἀγανακτήσαντος ἐπὶ τῷ Ἡρώδου κατηγορῆσαι. ταῦτα δ' ἔπραξεν χρήμασι πείσαντος αὐτὸν τοῦ Ἡρώδου.\n\nστρατεία Πάρθων εἰς Συρίαν, καθ' ἣν τὸν Ἀριστοβούλου υἱὸν Ἀντίγονον εἰς τὴν βασιλείαν κατήγαγον.\n\nὡς Ὑρκανὸν καὶ Φασάηλον τὸν ἀδελφὸν Ἡρώδου αἰχμαλώτους ἔλαβον.\n\nὡς Ἡρώδης φεύγων ἐκεῖθεν εἰς τὴν Ἰταλίαν παραγενόμενος εἰς τὴν Ῥώμην καὶ δεηθεὶς Ἀντωνίου χρήματα πολλὰ ὑποσχόμενος ἀπεδείχθη ὑπό τε τῆς συγκλήτου καὶ Καίσαρος βασιλεὺς τῆς Ἰουδαίας.\n\nἔκπλους Ἡρώδου μετὰ ταῦτα ἀπὸ Ῥώμης εἰς τὴν Ἰουδαίαν καὶ μάχη πρὸς Ἀντίγονον στρατιᾶς αὐτῷ Ῥωμαϊκῆς ἑπομένης καὶ ἡγεμόνος Σίλωνος.\n\nὡς Σίλωνος Ἱεροσόλυμα πολιορκήσαντος ὑπὸ Σοσσίου καὶ Ἡρώδου Ἀντίγονος διεφθάρη.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν λβ."},"chapters":{"1":[{"number":1,"text":"Τῶν δὲ περὶ Ἀλεξάνδραν τὴν βασίλισσαν καὶ τὸν θάνατον αὐτῆς ἐν τῇ πρὸ ταύτης ἡμῖν βίβλῳ δεδηλωμένων τὰ τούτοις ἀκόλουθα καὶ προσεχῆ νῦν ἐροῦμεν, οὐκ ἄλλου τινὸς ἢ τοῦ μηδὲν παραλιπεῖν τῶν πραγμάτων ἢ διʼ ἄγνοιαν ἢ διὰ κάματον τῆς μνήμης προμηθούμενοι."},{"number":2,"text":"τὴν γὰρ ἱστορίαν καὶ τὴν μήνυσιν τῶν ἀγνοουμένων τοῖς πολλοῖς πραγμάτων διὰ τὴν ἀρχαιότητα δεῖ μὲν καὶ τὸ τῆς ἀπαγγελίας κάλλος, ὅσον δὴ τοῦτʼ ἔστιν ἔκ τε τῶν ὀνομάτων καὶ τῆς τούτων ἁρμονίας καὶ ὅσα πρὸς τούτοις συμβάλλεται κόσμον τῷ λόγῳ,"},{"number":3,"text":"τοῖς ἀναγνωσομένοις ἔχειν, ὡς ἂν μετὰ χάριτός τινος καὶ ἡδονῆς τὴν ἐμπειρίαν παραλαμβάνοιεν, πάντων δὲ μᾶλλον τῆς ἀκριβείας τοὺς συγγραφεῖς στοχάζεσθαι μηδὲν τοῦ τἀληθῆ λέγειν τοῖς περὶ ὧν οὐκ ἴσασιν αὐτοὶ πιστεύειν αὐτοῖς μέλλουσιν προτιμῶντας."},{"number":4,"text":"Παραλαβόντος γὰρ τὴν βασιλείαν Ὑρκανοῦ τῷ τρίτῳ ἔτει τῆς ἑβδόμης καὶ ἑβδομηκοστῆς πρὸς ταῖς ἑκατὸν ὀλυμπιάδος, ὑπατεύοντος Ῥωμαίων Κυίντου Ὁρτησίου καὶ Κυίντου Μετέλλου, ὃς δὴ καὶ Κρητικὸς ἐπεκαλεῖτο, πόλεμον εὐθὺς ἐκφέρει πρὸς αὐτὸν Ἀριστόβουλος, καὶ τῆς μάχης αὐτῷ γενομένης πρὸς Ἱεριχοῦντι πολλοὶ τῶν στρατιωτῶν αὐτοῦ πρὸς τὸν ἀδελφὸν αὐτομολοῦσιν."},{"number":5,"text":"οὗ γενομένου φεύγει πρὸς τὴν ἀκρόπολιν Ὑρκανός, ἔνθα συνέβαινεν κατεῖρχθαι τὴν Ἀριστοβούλου γυναῖκα καὶ τοὺς παῖδας αὐτοῦ ὑπὸ τῆς μητρός, καθὼς προειρήκαμεν, καὶ τοὺς ἀντιστασιώτας δὲ καταφυγόντας εἰς τὸν τοῦ ἱεροῦ περίβολον αἱρεῖ προσβαλών."},{"number":6,"text":"καὶ λόγους ποιησάμενος πρὸς τὸν ἀδελφὸν περὶ συμβάσεως καταλύεται τὴν ἔχθραν ἐπὶ τῷ βασιλεύειν μὲν Ἀριστόβουλον, αὐτὸν δὲ ζῆν ἀπραγμόνως καρπούμενον ἀδεῶς τὴν ὑπάρχουσαν αὐτῷ κτῆσιν."},{"number":7,"text":"ταῦτα ἐπὶ τοῖς ἐν τῷ ἱερῷ συνθέμενοι καὶ ὅρκοις καὶ δεξιαῖς πιστωσάμενοι τὰς ὁμολογίας καὶ κατασπασάμενοι τοῦ πλήθους παντὸς ὁρῶντος ἀλλήλους ἀνεχώρησαν, ὁ μὲν εἰς τὰ βασίλεια, Ὑρκανὸς δʼ ὡς ἰδιώτης τυγχάνων εἰς τὴν οἰκίαν τὴν Ἀριστοβούλου."},{"number":8,"text":"Φίλος δέ τις Ὑρκανοῦ Ἰδουμαῖος Ἀντίπατρος λεγόμενος, πολλῶν μὲν εὐπόρει χρημάτων, δραστήριος δὲ ὢν τὴν φύσιν καὶ στασιαστὴς ἀλλοτρίως εἶχεν πρὸς τὸν Ἀριστόβουλον καὶ διαφόρως διὰ τὴν πρὸς τὸν Ὑρκανὸν εὔνοιαν."},{"number":9,"text":"Νικόλαος μέντοι φησὶν ὁ Δαμασκηνὸς τοῦτον εἶναι γένος ἐκ τῶν πρώτων Ἰουδαίων τῶν ἐκ Βαβυλῶνος εἰς τὴν Ἰουδαίαν ἀφικομένων. ταῦτα δὲ λέγει χαριζόμενος Ἡρώδῃ τῷ παιδὶ αὐτοῦ βασιλεῖ τῶν Ἰουδαίων ἐκ τύχης τινὸς γενομένῳ, περὶ οὗ κατὰ καιρὸν δηλώσομεν."},{"number":10,"text":"οὗτος τοίνυν ὁ Ἀντίπατρος Ἀντίπας τὸ πρῶτον ἐκαλεῖτο καὶ τῷ πατρὶ αὐτοῦ τοῦτο γὰρ ἦν τὸ ὄνομα, ὃν Ἀλεξάνδρου τοῦ βασιλέως καὶ τῆς γυναικὸς αὐτοῦ στρατηγὸν ἀποδειξάντων ὅλης τῆς Ἰδουμαίας ποιήσασθαι φιλίαν πρὸς τοὺς ὁμοροῦντας αὐτῷ Ἄραβας καὶ Γαζαίους καὶ Ἀσκαλωνίτας λέγουσιν πολλαῖς αὐτοὺς καὶ μεγάλαις ἐξιδιωσάμενον δωρεαῖς."},{"number":11,"text":"τὴν οὖν Ἀριστοβούλου δυναστείαν ὁ νεώτερος Ἀντίπατρος ὑφορώμενος καὶ δεδιώς, μή τι πάθῃ διὰ τὸ πρὸς αὐτὸν μῖσος, ἐπισυνιστᾷ κατʼ αὐτοῦ κρύφα διαλεγόμενος τῶν Ἰουδαίων τοὺς δυναστεύοντας, ἄδικον εἶναι λέγων περιορᾶν Ἀριστόβουλον ἀδίκως ἔχοντα τὴν ἀρχήν, καὶ τὸν μὲν ἀδελφὸν ταύτης ἐκβεβληκότα πρεσβύτερον ὄντα, κατέχοντα δʼ αὐτὴν οὖσαν ἐκείνου διὰ τὸ πρεσβεῖον."},{"number":12,"text":"τούτους τε συνεχῶς πρὸς τὸν Ὑρκανὸν ποιούμενος διετέλει τοὺς λόγους, καὶ ὅτι κινδυνεύσει τῷ ζῆν, εἰ μὴ φυλάξαιτο ποιήσας αὑτὸν ἐκποδών· τοὺς γὰρ φίλους τοὺς Ἀριστοβούλου μηδένα παραλείπειν καιρὸν ἔλεγεν συμβουλεύοντας αὐτὸν ἀνελεῖν ὡς τότε βεβαίως ἕξοντα τὴν ἀρχήν."},{"number":13,"text":"τούτοις Ὑρκανὸς ἠπίστει τοῖς λόγοις φύσει χρηστὸς ὢν καὶ διαβολὴν διʼ ἐπιείκειαν οὐ προσιέμενος ῥᾳδίως. ἐποίει δʼ αὐτὸν τὸ ἄπραγμον καὶ τὸ παρειμένον τῆς διανοίας τοῖς ὁρῶσιν ἀγεννῆ καὶ ἄνανδρον δοκεῖν· τῆς δʼ ἐναντίας φύσεως ἦν Ἀριστόβουλος, δραστήριος καὶ διεγηγερμένος τὸ φρόνημα."},{"number":14,"text":"Ἐπειδὴ τοίνυν ὁ Ἀντίπατρος οὐ προσέχοντα ἑώρα τοῖς λόγοις τὸν Ὑρκανόν, οὐ διέλιπεν ἑκάστης ἡμέρας πλαττόμενος καὶ διαβάλλων πρὸς αὐτὸν τὸν Ἀριστόβουλον ὡς ἀποκτεῖναι θέλοντα, καὶ μόλις ἐγκείμενος πείθει πρὸς Ἀρέταν αὐτῷ συμβουλεύσας φυγεῖν τὸν Ἀράβων βασιλέα· πεισθέντι γὰρ ἔσεσθαι καὶ αὐτὸς σύμμαχος ὑπισχνεῖτο."},{"number":15,"text":"ὁ δὲ ταῦτʼ ἀκούων συμφέρειν ἦν ἐπὶ τῷ πρὸς τὸν Ἀρέταν ἀποδρᾶναι, ἔστιν δὲ ὅμορος τῇ Ἰουδαίᾳ Ἀραβία, καὶ δὴ πέμπει πρῶτον Ὑρκανὸς πρὸς τὸν τῶν Ἀράβων βασιλέα τὸν Ἀντίπατρον ληψόμενον πίστεις, ὡς οὐκ ἐκδώσει τοῖς ἐχθροῖς ἱκέτην αὐτοῦ γενόμενον."},{"number":16,"text":"λαβὼν δὲ τὰς πίστεις ὁ Ἀντίπατρος ὑπέστρεψε πρὸς Ὑρκανὸν εἰς Ἱεροσόλυμα, καὶ μετʼ οὐ πολὺ παραλαβὼν αὐτὸν καὶ τῆς πόλεως ὑπεξελθὼν νύκτωρ καὶ πολλὴν ἀνύσας ὁδὸν ἧκεν ἄγων εἰς τὴν καλουμένην Πέτραν, ὅπου τὰ βασίλεια ἦν τῷ Ἀρέτᾳ."},{"number":17,"text":"μάλιστα δὲ ὢν φίλος τῷ βασιλεῖ κατάγειν τὸν Ὑρκανὸν εἰς τὴν Ἰουδαίαν παρεκάλει· καὶ τοῦθʼ ἑκάστης ἡμέρας ποιῶν καὶ οὐκ ἀνιείς, ἀλλὰ καὶ δωρεὰς προϊέμενος, πείθει τὸν Ἀρέταν."},{"number":18,"text":"οὐ μὴν ἀλλὰ καὶ Ὑρκανὸς ὑπέσχετο αὐτῷ καταχθεὶς καὶ τὴν βασιλείαν κομισάμενος ἀποδώσειν τήν τε χώραν καὶ τὰς δώδεκα πόλεις, ἃς Ἀλέξανδρος ὁ πατὴρ αὐτοῦ τῶν Ἀράβων ἀφείλετο. ἦσαν δʼ αὗται Μήδαβα, Λιββα, Ναβαλώθ, Ἀραβαθα, Γαλανθώνη, Ζωϊρα, Ὠρωναιδιγωβασιλισσαρυδδα, Αλουσα, Ωρυβδα."}],"2":[{"number":19,"text":"Τούτων αὐτῷ τῶν ὑποσχέσεων γενομένων ὁ Ἀρέτας ἐστράτευσεν ἐπὶ τὸν Ἀριστόβουλον μετὰ πέντε μυριάδων ἱππέων ἅμα καὶ πεζῆς στρατιᾶς, καὶ νικᾷ τῇ μάχῃ. πολλῶν δὲ μετὰ τὴν νίκην πρὸς Ὑρκανὸν αὐτομολησάντων μονωθεὶς ὁ Ἀριστόβουλος ἔφυγεν εἰς Ἱεροσόλυμα."},{"number":20,"text":"ὁ δὲ τῶν Ἀράβων βασιλεὺς πᾶσαν τὴν στρατιὰν ἀγαγὼν καὶ προσβαλὼν τῷ ἱερῷ τὸν Ἀριστόβουλον ἐπολιόρκει προστιθεμένου καὶ τοῦ δήμου τῷ Ὑρκανῷ καὶ συμπολιορκοῦντος αὐτῷ, μόνων δὲ τῶν ἱερέων τῷ Ἀριστοβούλῳ προσμενόντων."},{"number":21,"text":"ὁ μὲν οὖν Ἀρέτας ἑξῆς βαλόμενος στρατόπεδα τῶν Ἀράβων καὶ τῶν Ἰουδαίων ἰσχυρῶς ἐνέκειτο τῇ πολιορκίᾳ. τούτων δὲ γινομένων κατὰ τὸν καιρὸν τῆς τῶν ἀζύμων ἑορτῆς, ἣν πάσχα λέγομεν, οἱ δοκιμώτατοι τῶν Ἰουδαίων ἐκλιπόντες τὴν χώραν εἰς Αἴγυπτον ἔφυγον."},{"number":22,"text":"Ὀνίαν δέ τινα ὄνομα δίκαιον ὄντα καὶ θεοφιλῆ, ὃς ἀνομβρίας ποτὲ οὔσης ηὔξατο τῷ θεῷ λῦσαι τὸν αὐχμὸν καὶ γενόμενος ἐπήκοος ὁ θεὸς ὗσεν, κρύψαντα ἑαυτὸν διὰ τὸ τὴν στάσιν ὁρᾶν ἰσχυρὰν ἐπιμένουσαν, ἀναχθέντα εἰς τὸ στρατόπεδον τῶν Ἰουδαίων ἠξίουν, ὡς ἔπαυσε τὴν ἀνομβρίαν εὐξάμενος, ἵνʼ οὕτως ἀρὰς θῇ κατὰ Ἀριστοβούλου καὶ τῶν συστασιαστῶν αὐτοῦ."},{"number":23,"text":"ἐπεὶ δὲ ἀντιλέγων καὶ παραιτούμενος ἐβιάσθη ὑπὸ τοῦ πλήθους, στὰς μέσος αὐτῶν εἶπεν·"},{"number":24,"text":"ὦ θεὲ βασιλεῦ τῶν ὅλων, ἐπεὶ οἱ μετʼ ἐμοῦ συνεστῶτες σὸς δῆμός ἐστιν καὶ οἱ πολιορκούμενοι δὲ ἱερεῖς σοί, δέομαι μήτε κατὰ τούτων ἐκείνοις ὑπακοῦσαι μήτε κατʼ ἐκείνων ἃ οὗτοι παρακαλοῦσιν εἰς τέλος ἀγαγεῖν. καὶ τὸν μὲν ταῦτʼ εὐξάμενον περιστάντες οἱ πονηροὶ τῶν Ἰουδαίων κατέλευσαν."},{"number":25,"text":"Ὁ δὲ θεὸς ταύτης αὐτοὺς παραχρῆμα ἐτιμωρήσατο τῆς ὠμότητος καὶ δίκην εἰσεπράξατο τοῦ Ὀνίου φόνου τούτῳ τῷ τρόπῳ· πολιορκουμένων τῶν ἱερέων καὶ τοῦ Ἀριστοβούλου συνέβη τὴν ἑορτὴν ἐπιστῆναι τὴν καλουμένην φάσκα, καθʼ ἣν ἔθος ἐστὶν ἡμῖν πολλὰ θύειν τῷ θεῷ."},{"number":26,"text":"ἀποροῦντες δὲ θυμάτων οἱ περὶ τὸν Ἀριστόβουλον ἠξίωσαν αὐτοῖς τοὺς ὁμοφύλους παρασχεῖν χρήματα λαβόντας ἀντὶ τῶν θυμάτων ὅσα θέλουσιν. τῶν δέ, εἰ βούλονται λαβεῖν, χιλίας δραχμὰς ὑπὲρ ἑκάστης κεφαλῆς καταβαλεῖν κελευόντων, προθύμως ὅ τε Ἀριστόβουλος καὶ οἱ ἱερεῖς ὑπέστησαν καὶ διὰ τῶν τειχῶν καθιμήσαντες ἔδωκαν αὐτοῖς τὰ χρήματα."},{"number":27,"text":"κἀκεῖνοι λαβόντες οὐκ ἀπέδωκαν τὰ θύματα, ἀλλʼ εἰς τοῦτο πονηρίας ἦλθον, ὥστε παραβῆναι τὰς πίστεις καὶ ἀσεβῆσαι τὸν θεὸν τὰ πρὸς τὰς θυσίας μὴ παρασχόντες τοῖς δεομένοις."},{"number":28,"text":"παρασπονδηθέντες δὲ οἱ ἱερεῖς ηὔξαντο τὸν θεὸν δίκην αὐτῶν εἰσπράξασθαι παρὰ τῶν ὁμοφύλων, ὁ δὲ οὐκ ἀνεβάλετο τὴν τιμωρίαν, ἀλλὰ πνεῦμα πολὺ καὶ βίαιον ἐπιπέμψας τὸν καρπὸν ἁπάσης τῆς χώρας διέφθειρεν, ὡς τὸν μόδιον τοῦ σίτου τότε αὐτοὺς ἐξωνεῖσθαι δραχμῶν ἕνδεκα."},{"number":29,"text":"Ἐν τούτῳ πέμπει Σκαῦρον εἰς Συρίαν Πομπήιος αὐτὸς ὢν ἐν Ἀρμενίᾳ καὶ πολεμῶν ἔτι Τιγράνῃ. ὁ δὲ ἀφικόμενος εἰς Δαμασκὸν Λόλλιον καὶ Μέτελλον νεωστὶ τὴν πόλιν ᾑρηκότας εὑρὼν αὐτὸς εἰς τὴν Ἰουδαίαν ἠπείγετο."},{"number":30,"text":"παραγενομένου δὲ πρέσβεις ἧκον πρὸς αὐτὸν παρά τε Ἀριστοβούλου καὶ Ὑρκανοῦ συμμαχεῖν ἀξιούντων ἑκατέροις. ὑπισχνουμένου δὲ Ἀριστοβούλου τετρακόσια δώσειν τάλαντα, τοῦ δὲ Ὑρκανοῦ τούτων οὐκ ἐλάττονα παρέξειν, προσδέχεται τὴν Ἀριστοβούλου ὑπόσχεσιν·"},{"number":31,"text":"καὶ γὰρ εὔπορος χρημάτων καὶ μεγαλόψυχος ἦν καὶ μετριωτέρων ἠξίου τυγχάνειν, ὁ δὲ πένης ἦν καὶ γλίσχρος καὶ περὶ μειζόνων τὴν ἄπιστον προύτεινεν ἐπαγγελίαν. οὐ γὰρ ἴσον ἦν βίᾳ πόλιν ἑλεῖν ἐν ταῖς μάλιστα ὀχυρὰν καὶ δυνατήν, ἢ φυγάδας ἐκβαλεῖν μετὰ τοῦ Ναβαταίων πλήθους οὐκ εὖ πρὸς πόλεμον διακειμένων."},{"number":32,"text":"τούτῳ τοίνυν προσθέμενος διὰ τὰς προειρημένας αἰτίας λαβὼν τὰ χρήματα λύει τὴν πολιορκίαν, κελεύσας ἀναχωρεῖν τὸν Ἀρέταν ἢ πολέμιον αὐτὸν Ῥωμαίων ἀποδειχθήσεσθαι."},{"number":33,"text":"καὶ Σκαῦρος μὲν εἰς Δαμασκὸν πάλιν ἀνεχώρησεν, Ἀριστόβουλος δὲ μετὰ πολλῆς δυνάμεως ἐπί τε Ἀρέταν καὶ Ὑρκανὸν ἐστράτευσεν καὶ συμβαλὼν αὐτοῖς περὶ τὸν καλούμενον Παπυρῶνα νικᾷ τῇ μάχῃ καὶ κτείνει περὶ ἑξακισχιλίους τῶν πολεμίων, μεθʼ ὧν ἔπεσεν καὶ Φαλλίων ὁ Ἀντιπάτρου ἀδελφός."}],"3":[{"number":34,"text":"Μετʼ οὐ πολὺ δὲ Πομπηίου εἰς Δαμασκὸν ἀφικομένου καὶ κοίλην Συρίαν ἐπιόντος ἧκον παρʼ αὐτὸν πρέσβεις ἐξ ὅλης Συρίας καὶ Αἰγύπτου καὶ ἐκ τῆς Ἰουδαίας· ἔπεμψε γὰρ αὐτῷ μέγα δῶρον Ἀριστόβουλος ἄμπελον χρυσῆν ἐκ πεντακοσίων ταλάντων."},{"number":35,"text":"μέμνηται δὲ τοῦ δώρου καὶ Στράβων ὁ Καππάδοξ λέγων οὕτως· ἦλθεν δὲ καὶ ἐξ Αἰγύπτου πρεσβεία καὶ στέφανος ἀπὸ χρυσῶν τετρακισχιλίων καὶ ἐκ τῆς Ἰουδαίας εἴτε ἄμπελος εἴτε κῆπος· τερπωλὴν ὠνόμαζον τὸ δημιούργημα."},{"number":36,"text":"τοῦτο μέντοι τὸ δῶρον ἱστορήκαμεν καὶ ἡμεῖς ἀνακείμενον ἐν Ῥώμῃ ἐν τῷ ἱερῷ τοῦ Διὸς τοῦ Καπετωλίου ἐπιγραφὴν ἔχον Ἀλεξάνδρου τοῦ τῶν Ἰουδαίων βασιλέως. ἐτιμήθη δὲ εἶναι πεντακοσίων ταλάντων Ἀριστόβουλον μὲν οὖν τοῦτο λέγεται πέμψαι τὸν Ἰουδαίων δυνάστην."},{"number":37,"text":"Μετʼ οὐ πολὺ δὲ ἧκον πάλιν πρέσβεις πρὸς αὐτὸν Ἀντίπατρος μὲν ὑπὲρ Ὑρκανοῦ, Νικόδημος δὲ ὑπὲρ Ἀριστοβούλου, ὃς δὴ καὶ κατηγόρει τῶν λαβόντων χρήματα Γαβινίου μὲν πρότερον Σκαύρου δὲ ὕστερον, τοῦ μὲν τριακόσια τοῦ δὲ τετρακόσια τάλαντα, πρὸς τοῖς ἄλλοις καὶ τούτους ἐχθροὺς αὐτῷ κατασκευάζων."},{"number":38,"text":"κελεύσας δὲ ἥκειν τοὺς διαμφισβητοῦντας ἐνισταμένου τοῦ ἔαρος ἀναλαβὼν τὴν δύναμιν ἐκ τῶν χειμαδίων ὥρμησεν ἐπὶ τῆς Δαμασκηνῆς. καὶ τήν τε ἄκραν ἐν παρόδῳ τὴν ἐν Ἀπαμείᾳ κατέσκαψεν, ἣν ὁ Κυζικηνὸς ἐτείχισεν Ἀντίοχος,"},{"number":39,"text":"καὶ τὴν Πτολεμαίου τοῦ Μενναίου χώραν κατενόησεν, ἀνδρὸς πονηροῦ καὶ οὐδὲν ἐλάσσονος Διονυσίου τοῦ Τριπολίτου τοῦ πελεκισθέντος, ᾧπερ καὶ κηδεύων ἐτύγχανεν, χιλίοις μέντοι ταλάντοις ἐξωνησαμένου τὴν ὑπὲρ τῶν ἁμαρτημάτων τιμωρίαν, οἷς Πομπήιος τοὺς στρατιώτας ἐμισθοδότησεν."},{"number":40,"text":"ἐξεῖλεν δὲ καὶ Λυσιάδα χωρίον, οὗ τύραννος ἦν Σίλας ὁ Ἰουδαῖος. διελθὼν δὲ τὰς πόλεις τήν τε Ἡλιούπολιν καὶ τὴν Χαλκίδα καὶ τὸ διεῖργον ὄρος ὑπερβαλὼν τὴν κοίλην προσαγορευομένην Συρίαν ἀπὸ τῆς ἄλλης εἰς Δαμασκὸν ἧκεν."},{"number":41,"text":"ἔνθα δὴ καὶ τῶν Ἰουδαίων διήκουσεν καὶ τῶν ἡγουμένων αὐτῶν, οἳ πρός τε ἀλλήλους διεφέροντο Ὑρκανὸς καὶ Ἀριστόβουλος καὶ τὸ ἔθνος πρὸς ἀμφοτέρους, τὸ μὲν οὐκ ἀξιοῦν βασιλεύεσθαι· πάτριον γὰρ εἶναι τοῖς ἱερεῦσι τοῦ τιμωμένου παρʼ αὐτοῖς θεοῦ πειθαρχεῖν, ὄντας δὲ τούτους ἀπογόνους τῶν ἱερέων εἰς ἄλλην μετάγειν ἀρχὴν τὸ ἔθνος ζητῆσαι, ὅπως καὶ δοῦλον γένοιτο."},{"number":42,"text":"Ὑρκανὸς δὲ κατηγόρει, ὅτι πρεσβύτερος ὢν ἀφαιρεθείη τὸ πρεσβεῖον ὑπὸ Ἀριστοβούλου καὶ μικρὸν ἔχοι μέρος τῆς χώρας ὑφʼ αὑτῷ, τὴν δὲ ἄλλην βίᾳ λαβὼν Ἀριστόβουλος·"},{"number":43,"text":"τάς τε καταδρομὰς τὰς ἐπὶ τοὺς ὁμόρους καὶ τὰ πειρατήρια τὰ ἐν τῇ θαλάττῃ τοῦτον εἶναι τὸν συστήσαντα διέβαλεν, οὐκ ἂν οὐδʼ ἀποστῆναι λέγων τὸ ἔθνος αὐτοῦ, εἰ μὴ βίαιός τις καὶ ταραχώδης ὑπῆρχεν. συνηγόρουν δὲ αὐτῷ ταῦτα λέγοντι πλείους ἢ χίλιοι τῶν δοκιμωτάτων Ἰουδαίων Ἀντιπάτρου παρασκευάσαντος."},{"number":44,"text":"ὁ δὲ τοῦ μὲν ἐκπεσεῖν αὐτὸν τῆς ἀρχῆς τὴν ἐκείνου φύσιν ᾐτιᾶτο ἄπρακτον οὖσαν καὶ διὰ τοῦτʼ εὐκαταφρόνητον, αὐτὸν δʼ ἔλεγεν φόβῳ τοῦ μὴ πρὸς ἄλλους μεταστῆναι τὴν ἀρχὴν ἐν ἀνάγκης αὐτὴν ὑπελθεῖν, προσαγορεύεσθαι δὲ αὐτὸν τοῦτο ὅπερ καὶ Ἀλέξανδρον τὸν πατέρα."},{"number":45,"text":"καὶ δὴ μάρτυρας τούτων ἐκάλει τοὺς νέους καὶ σοβαρωτέρους, ὧν ἐβδελύττοντο τὰς πορφυρίδας καὶ τὰς κόμας καὶ τὰ φάλαρα καὶ τὸν ἄλλον κόσμον, ὃν ὥσπερ οὐ δίκην ὑφέξοντες, ἀλλʼ ὡς εἰς πομπὴν προϊόντες περιέκειντο."},{"number":46,"text":"Πομπήιος δὲ τούτων ἀκούσας καὶ καταγνοὺς Ἀριστοβούλου βίαν, τότε μὲν αὐτοὺς ἀπέπεμψεν διαλεχθεὶς πρᾴως, ἐλθὼν δʼ εἰς τὴν χώραν αὐτῶν ἔλεγεν διατάξειν ἕκαστα, ἐπειδὰν τὰ τῶν Ναβαταίων πρῶτον ἴδῃ. τέως δὲ ἐκέλευσεν ἡσυχίαν ἄγειν θεραπεύων ἅμα τὸν Ἀριστόβουλον, μὴ τὴν χώραν ἀποστήσῃ καὶ διακλεισθείη τῶν παρόδων."},{"number":47,"text":"ἔτυχεν μέντοι τοῦτο ἐξ Ἀριστοβούλου γενόμενον· οὐ γὰρ ἀναμείνας οὐδὲν ὧν διελέχθη πρὸς αὐτὸν ὁ Πομπήιος εἰς Δειλον πόλιν ἦλθεν κἀκεῖθεν εἰς τὴν Ἰουδαίαν ἀπῆρεν."},{"number":48,"text":"Ὀργίζεται δʼ ἐπὶ τούτοις ὁ Πομπήιος, καὶ τὴν ἐπὶ τοὺς Ναβαταίους ἀναλαβὼν στρατιὰν ἔκ τε Δαμασκοῦ καὶ τῆς ἄλλης Συρίας ἐπικουρικὰ σὺν τοῖς ὑπάρχουσιν αὐτῷ Ῥωμαίων τάγμασιν ἐστράτευσεν ἐπὶ τὸν Ἀριστόβουλον."},{"number":49,"text":"ὡς δὲ παραμειψάμενος Πέλλαν καὶ Σκυθόπολιν εἰς Κορέας ἧκεν, ἥτις ἐστὶν ἀρχὴ τῆς Ἰουδαίας διεξιόντι τὴν μεσόγειον, ἐνταῦθα εἴς τι περικαλλὲς ἔρυμα ἐπʼ ἄκρου τοῦ ὄρους ἱδρυμένον Ἀλεξάνδρειον Ἀριστοβούλου συμπεφευγότος, πέμψας ἐκέλευσεν ἥκειν πρὸς αὐτόν."},{"number":50,"text":"ὁ δὲ παραινούντων πολλῶν μὴ πολεμεῖν Ῥωμαίοις κάτεισιν καὶ δικαιολογησάμενος πρὸς τὸν ἀδελφὸν περὶ τῆς ἀρχῆς πάλιν εἰς τὴν ἀκρόπολιν ἀναβαίνει Πομπηίου συγχωρήσαντος."},{"number":51,"text":"καὶ τοῦτʼ ἐποίησεν δὶς καὶ τρίς, ἅμα μὲν κολακεύων τὴν ἀπʼ αὐτοῦ περὶ τῆς βασιλείας ἐλπίδα καὶ πρὸς ἕκαστον ὧν κελεύσειεν Πομπήιος ὑπακούειν ὑποκρινόμενος, ἅμα δὲ ἀναχωρῶν εἰς τὸ ἔρυμα ὑπὲρ τοῦ μὴ καταλύειν αὑτὸν καὶ πρὸς τὸ πολεμεῖν ἀφορμὴν αὑτῷ παρασκευαζόμενος, δεδιὼς μὴ τὴν ἀρχὴν εἰς Ὑρκανὸν περιστήσῃ."},{"number":52,"text":"κελεύοντος δὲ Πομπηίου παραδιδόναι τὰ ἐρύματα καὶ τοῖς φρουράρχοις ἐπιστέλλειν τῇ ἑαυτοῦ χειρί, παραδέχεσθαι δὲ ἄλλως ἀπείρητο, πείθεται μέν, δυσανασχετῶν δʼ ἀνεχώρησεν εἰς Ἱεροσόλυμα καὶ ἐν παρασκευῇ τοῦ πολεμεῖν ἐγίνετο."},{"number":53,"text":"καὶ μετʼ οὐ πολὺ Πομπηίῳ στρατιὰν ἐπʼ αὐτὸν ἄγοντι καθʼ ὁδὸν ἀφικόμενοί τινες ἐκ πόντου τὴν Μιθριδάτου τελευτὴν ἐμήνυον τὴν ἐκ Φαρνάκου τοῦ παιδὸς αὐτῷ γενομένην."}],"4":[{"number":54,"text":"Στρατοπεδευσάμενος δὲ περὶ Ἱεριχοῦντα, οὗ τὸν φοίνικα συμβέβηκε τρέφεσθαι καὶ τὸ ὀποβάλσαμον μύρων ἀκρότατον, ὃ τῶν θάμνων τεμνομένων ὀξεῖ λίθῳ ἀναπιδύει ὥσπερ ὀπός, ἕωθεν ἐπὶ Ἱεροσολύμων ἐχώρει."},{"number":55,"text":"καὶ μετανοήσας Ἀριστόβουλος ἀφικνεῖται πρὸς Πομπήιον, καὶ χρήματά τε διδοὺς καὶ τοῖς Ἱεροσολύμοις αὐτὸν εἰσδεχόμενος παρεκάλει παύσασθαι τοῦ πολέμου καὶ πράττειν μετʼ εἰρήνης ὅ τι βούλεται. συγγνοὺς δὲ ὁ Πομπήιος αὐτῷ δεομένῳ πέμπει Γαβίνιον καὶ στρατιώτας ἐπί τε τὰ χρήματα καὶ τὴν πόλιν."},{"number":56,"text":"οὐ μὴν ἐπράχθη τι τούτων, ἀλλʼ ἐπανῆλθεν ὁ Γαβίνιος τῆς τε πόλεως ἀποκλεισθεὶς καὶ τὰ χρήματα μὴ λαβών, τῶν Ἀριστοβούλου στρατιωτῶν οὐκ ἐπιτρεψάντων τὰ συγκείμενα γενέσθαι."},{"number":57,"text":"ὀργὴ δʼ ἐπὶ τούτοις Πομπήιον λαμβάνει, καὶ τὸν Ἀριστόβουλον ἐν φυλακῇ καταστήσας αὐτὸς ἐπὶ τὴν πόλιν ἔρχεται τὰ μὲν ἄλλα πάντα οὖσαν ὀχυράν, μόνῳ δὲ τῷ βορείῳ μέρει φαύλως ἔχουσαν· περιέρχεται γὰρ αὐτὴν φάραγξ εὐρεῖά τε καὶ βαθεῖα ἐντὸς ἀπολαμβάνουσα τὸ ἱερὸν λιθίνῳ περιβόλῳ καρτερῶς πάνυ τετειχισμένον."},{"number":58,"text":"Ἦν δὲ τῶν ἀνθρώπων ἔνδον στάσις οὐχ ὁμονοούντων περὶ τῶν ἐνεστώτων, ἀλλὰ τοῖς μὲν ἐδόκει παραδιδόναι Πομπηίῳ τὴν πόλιν, οἱ δὲ τὰ Ἀριστοβούλου φρονοῦντες ἀποκλείειν τε καὶ πολεμεῖν παρῄνουν τῷ κἀκεῖνον ἔχεσθαι δεδεμένον. φθάσαντες δὲ οὗτοι τὸ ἱερὸν καταλαμβάνουσι καὶ τὴν τείνουσαν ἀπʼ αὐτοῦ γέφυραν εἰς τὴν πόλιν εἰς πολιορκίαν εὐτρεπιζόμενοι."},{"number":59,"text":"οἱ δὲ ἕτεροι δεξάμενοι τὴν στρατιὰν ἐνεχείρισαν Πομπηίῳ τήν τε πόλιν καὶ τὰ βασίλεια. Πομπήιος δὲ Πείσωνα τὸν ὑποστράτηγον πέμψας σὺν στρατιᾷ τήν τε πόλιν καὶ τὰ βασίλεια ἐφρούρει καὶ τὰς οἰκίας τὰς πρὸς τῷ ἱερῷ καὶ ὅσα ἦν ἔξω περὶ τὸ ἱερὸν ὠχύρου."},{"number":60,"text":"καὶ τὸ μὲν πρῶτον λόγους συμβατηρίους τοῖς ἐντὸς προσέφερεν, οὐχ ὑπακουόντων δὲ εἰς ἃ προεκαλεῖτο τὰ πέριξ ἐτείχιζε χωρία πρὸς ἅπαντα Ὑρκανοῦ προθύμως ὑπηρετοῦντος. Πομπήιος δὲ ἕωθεν στρατοπεδεύεται κατὰ τὸ βόρειον τοῦ ἱεροῦ μέρος, ὅθεν ἦν ἐπίμαχον."},{"number":61,"text":"ἀνεστήκεσαν δὲ καὶ ἐνταῦθα μεγάλοι πύργοι καὶ τάφρος τε ὀρώρυκτο καὶ βαθείᾳ περιείχετο φάραγγι· ἀπερρώγει γὰρ καὶ τὰ πρὸς τὴν πόλιν τῆς γεφύρας ἀνατετραμμένης ἐφʼ οὗ δὴ Πομπήιος καὶ τὸ χῶμα ὁσημέραι ταλαιπωρούμενος ἐγήγερτο τεμνόντων τὴν πέριξ ὕλην Ῥωμαίων."},{"number":62,"text":"καὶ ἐπειδὴ τοῦτʼ εἶχεν ἱκανῶς μόλις πλησθείσης τῆς τάφρου διὰ βάθος ἄπειρον προσβαλὼν μηχανὰς καὶ ὄργανα ἐκ Τύρου κομισθέντα ἐπιστήσας κατήρασσε τὸ ἱερὸν τοῖς πετροβόλοις."},{"number":63,"text":"εἰ δὲ μὴ πάτριον ἦν ἡμῖν ἀργεῖν τὰς ἑβδομάδας ἡμέρας, οὐκ ἂν ἠνύσθη τὸ χῶμα κωλυόντων ἐκείνων· ἄρχοντας μὲν γὰρ μάχης καὶ τύπτοντας ἀμύνασθαι δίδωσιν ὁ νόμος, ἄλλο δέ τι δρῶντας τοὺς πολεμίους οὐκ ἐᾷ."},{"number":64,"text":"Ὃ δὴ καὶ Ῥωμαῖοι συνιδόντες κατʼ ἐκείνας τὰς ἡμέρας, ἃ δὴ σάββατα καλοῦμεν, οὔτʼ ἔβαλλον τοὺς Ἰουδαίους οὔτε εἰς χεῖρας αὐτοῖς ὑπήντων, χοῦν δὲ καὶ πύργους ἀνίστασαν καὶ τὰ μηχανήματα προσῆγον, ὥστʼ αὐτοῖς εἰς τὴν ἐπιοῦσαν ἐνεργὰ ταῦτʼ εἶναι."},{"number":65,"text":"μάθοι δʼ ἄν τις ἐντεῦθεν τὴν ὑπερβολὴν ἧς ἔχομεν περὶ τὸν θεὸν εὐσεβείας καὶ τὴν φυλακὴν τῶν νόμων, μηδὲν ὑπὸ τῆς πολιορκίας διὰ φόβον ἐμποδιζομένων πρὸς τὰς ἱερουργίας, ἀλλὰ δὶς τῆς ἡμέρας πρωΐ τε καὶ περὶ ἐνάτην ὥραν ἱερουργούντων ἐπὶ τοῦ βωμοῦ, καὶ μηδὲ εἴ τι περὶ τὰς προσβολὰς δύσκολον εἴη τὰς θυσίας παυόντων."},{"number":66,"text":"καὶ γὰρ ἁλούσης τῆς πόλεως περὶ τρίτον μῆνα τῇ τῆς νηστείας ἡμέρᾳ κατὰ ἐνάτην καὶ ἑβδομηκοστὴν καὶ ἑκατοστὴν ὀλυμπιάδα ὑπατευόντων Γαΐου Ἀντωνίου καὶ Μάρκου Τυλλίου Κικέρωνος οἱ πολέμιοι μὲν εἰσπεσόντες ἔσφαττον τοὺς ἐν τῷ ἱερῷ,"},{"number":67,"text":"οἱ δὲ πρὸς ταῖς θυσίαις οὐδὲν ἧττον ἱερουργοῦντες διετέλουν, οὔτε ὑπὸ τοῦ φόβου τοῦ περὶ τῆς ψυχῆς οὔθʼ ὑπὸ τοῦ πλήθους τῶν ἤδη φονευομένων ἀναγκασθέντες ἀποδρᾶναι πᾶν θʼ ὅ τι δέοι παθεῖν τοῦτο παρʼ αὐτοῖς ὑπομεῖναι τοῖς βωμοῖς κρεῖττον εἶναι νομίζοντες ἢ παρελθεῖν τι τῶν νομίμων."},{"number":68,"text":"ὅτι δὲ οὐ λόγος ταῦτα μόνον ἐστὶν ἐγκώμιον ψευδοῦς εὐσεβείας ἐμφανίζων, ἀλλʼ ἀλήθεια, μαρτυροῦσι πάντες οἱ τὰς κατὰ Πομπήιον πράξεις ἀναγράψαντες, ἐν οἷς καὶ Στράβων καὶ Νικόλαος καὶ πρὸς αὐτοῖς Τίτος Λίβιος ὁ τῆς Ῥωμαϊκῆς ἱστορίας συγγραφεύς."},{"number":69,"text":"Ἐπεὶ δὲ τοῦ μηχανήματος προσαχθέντος σεισθεὶς ὁ μέγιστος τῶν πύργων κατηνέχθη καὶ παρέρρηξέν τι χωρίον, εἰσεχέοντο μὲν οἱ πολέμιοι, πρῶτος δὲ αὐτῶν Κορνήλιος Φαῦστος Σύλλα παῖς σὺν τοῖς ἑαυτοῦ στρατιώταις ἐπέβη τοῦ τείχους, μετὰ δὲ αὐτὸν Φούριος ἑκατοντάρχης ἅμα τοῖς ἑπομένοις κατὰ θάτερον μέρος, διὰ μέσων δὲ Φάβιος καὶ αὐτὸς ἑκατοντάρχης σὺν στίφει καρτερῷ."},{"number":70,"text":"φόνου δὲ ἦν τὰ πάντα ἀνάπλεα. καὶ τῶν Ἰουδαίων οἱ μὲν ὑπὸ Ῥωμαίων, οἱ δʼ ὑπὸ ἀλλήλων ἀνῃροῦντο, εἰσὶν δʼ οἳ καὶ κατὰ κρημνῶν ἑαυτοὺς ἐρρίπτουν καὶ πῦρ ἐνιέντες εἰς τὰς οἰκίας ἐνεπίμπραντο τὰ γινόμενα καρτερεῖν οὐχ ὑπομένοντες."},{"number":71,"text":"ἔπεσον δὲ τῶν μὲν Ἰουδαίων εἰς μυρίους καὶ δισχιλίους, Ῥωμαίων δὲ πάνυ ὀλίγοι. ἐλήφθη δὲ αἰχμάλωτος καὶ Ἀψάλωμος, θεῖος ἅμα καὶ πενθερὸς Ἀριστοβούλου. παρηνομήθη δὲ οὐ σμικρὰ περὶ τὸν ναὸν ἄβατόν τε ὄντα ἐν τῷ πρὶν χρόνῳ καὶ ἀόρατον·"},{"number":72,"text":"παρῆλθεν γὰρ εἰς τὸ ἐντὸς ὁ Πομπήιος καὶ τῶν περὶ αὐτὸν οὐκ ὀλίγοι καὶ εἶδον ὅσα μὴ θεμιτὸν ἦν τοῖς ἄλλοις ἀνθρώποις ἢ μόνοις τοῖς ἀρχιερεῦσιν. ὄντων δὲ τραπέζης τε χρυσῆς καὶ λυχνίας ἱερᾶς καὶ σπονδείων καὶ πλήθους ἀρωμάτων, χωρὶς δὲ τούτων ἐν τοῖς θησαυροῖς ἱερῶν χρημάτων εἰς δύο χιλιάδας ταλάντων, οὐδενὸς ἥψατο διʼ εὐσέβειαν, ἀλλὰ κἀν τούτῳ ἀξίως ἔπραξεν τῆς περὶ αὐτὸν ἀρετῆς."},{"number":73,"text":"τῇ τε ὑστεραίᾳ καθαίρειν παραγγείλας τὸ ἱερὸν τοῖς ναοπόλοις καὶ τὰ νόμιμα ἐπιφέρειν τῷ θεῷ τὴν ἀρχιερωσύνην ἀπέδωκεν Ὑρκανῷ διά τε τἆλλα ὅσα χρήσιμος ὑπῆρξεν αὐτῷ, καὶ ὅτι τοὺς κατὰ τὴν χώραν Ἰουδαίους Ἀριστοβούλῳ συμπολεμεῖν ἐκώλυσεν, καὶ τοὺς αἰτίους τοῦ πολέμου τῷ πελέκει διεχρήσατο. τὸν δὲ Φαῦστον καὶ τοὺς ἄλλους ὅσοι τῷ τείχει προθύμως ἐπέβησαν τῶν πρεπόντων ἀριστείων ἠξίωσεν."},{"number":74,"text":"καὶ τὰ μὲν Ἱεροσόλυμα ὑποτελῆ φόρου Ῥωμαίοις ἐποίησεν, ἃς δὲ πρότερον οἱ ἔνοικοι πόλεις ἐχειρώσαντο τῆς κοίλης Συρίας ἀφελόμενος ὑπὸ τῷ σφετέρῳ στρατηγῷ ἔταξεν καὶ τὸ σύμπαν ἔθνος ἐπὶ μέγα πρότερον αἰρόμενον ἐντὸς τῶν ἰδίων ὅρων συνέστειλεν."},{"number":75,"text":"καὶ Γάδαρα μὲν μικρὸν ἔμπροσθεν καταστραφεῖσαν ἀνέκτισεν Δημητρίῳ χαριζόμενος τῷ Γαδαρεῖ ἀπελευθέρῳ αὐτοῦ· τὰς δὲ λοιπὰς Ἵππον καὶ Σκυθόπολιν καὶ Πέλλαν καὶ Δῖον καὶ Σαμάρειαν ἔτι τε Μάρισαν καὶ Ἄζωτον καὶ Ἰάμνειαν καὶ Ἀρέθουσαν τοῖς οἰκήτορσιν ἀπέδωκεν."},{"number":76,"text":"καὶ ταύτας μὲν ἐν τῇ μεσογείῳ χωρὶς τῶν κατεσκαμμένων, Γάζαν δὲ πρὸς τῇ θαλάττῃ καὶ Ἰόππην καὶ Δῶρα καὶ Στράτωνος πύργον, ἣ κτίσαντος αὐτὴν Ἡρώδου μεγαλοπρεπῶς καὶ λιμέσιν τε καὶ ναοῖς κοσμήσαντος, Καισάρεια μετωνομάσθη, πάσας ὁ Πομπήιος ἀφῆκεν ἐλευθέρας καὶ προσένειμεν τῇ ἐπαρχίᾳ."},{"number":77,"text":"Τούτου τοῦ πάθους τοῖς Ἱεροσολύμοις αἴτιοι κατέστησαν Ὑρκανὸς καὶ Ἀριστόβουλος πρὸς ἀλλήλους στασιάσαντες· τήν τε γὰρ ἐλευθερίαν ἀπεβάλομεν καὶ ὑπήκοοι Ῥωμαίοις κατέστημεν καὶ τὴν χώραν, ἣν τοῖς ὅπλοις ἐκτησάμεθα τοὺς Σύρους ἀφελόμενοι, ταύτην ἠναγκάσθημεν ἀποδοῦναι τοῖς Σύροις,"},{"number":78,"text":"καὶ προσέτι πλείω ἢ μύρια τάλαντα Ῥωμαῖοι ἐν βραχεῖ χρόνῳ παρʼ ἡμῶν εἰσεπράξαντο, καὶ ἡ βασιλεία πρότερον τοῖς κατὰ γένος ἀρχιερεῦσιν διδομένη, τιμὴ δημοτικῶν ἀνδρῶν ἐγένετο. καὶ περὶ μὲν τούτων κατὰ χώραν ἐροῦμεν."},{"number":79,"text":"Πομπήιος δὲ τήν τε κοίλην ἄλλην Συρίαν ἕως Εὐφράτου ποταμοῦ καὶ Αἰγύπτου Σκαύρῳ παραδοὺς καὶ δύο τάγματα Ῥωμαίων ἐπὶ Κιλικίας ᾤχετο ἐπειγόμενος εἰς Ῥώμην. ἐπήγετο δὲ μετὰ τῆς γενεᾶς καὶ Ἀριστόβουλον δεδεμένον· δύο γὰρ ἦσαν αὐτῷ θυγατέρες καὶ τοσοῦτοι υἱεῖς, ὧν Ἀλέξανδρος μὲν ἀπέδρα, ὁ δὲ νεώτερος Ἀντίγονος συναπεκομίζετο εἰς Ῥώμην ἅμα ταῖς ἀδελφαῖς."}],"5":[{"number":80,"text":"Σκαύρου δʼ ἐπὶ Πέτραν τῆς Ἀραβίας στρατεύσαντος καὶ διὰ τὸ δυσάλωτον εἶναι τὰ ἐν κύκλῳ δῃοῦντος αὐτῆς καὶ τοῦ στρατεύματος λιμήναντος Ἀντίπατρος κατʼ ἐντολὴν Ὑρκανοῦ σῖτον ἐκ τῆς Ἰουδαίας καὶ τὰ ἄλλα, ὅσων ἐνέδει, παρεῖχεν."},{"number":81,"text":"πεμφθεὶς δὲ πρὸς Ἀρέταν πρεσβευτὴς ὑπὸ Σκαύρου διὰ τὴν ὑπάρχουσαν ξενίαν πείθει αὐτὸν ἀργύριον ὑπὲρ τοῦ μὴ δῃωθῆναι τὴν χώραν δοῦναι, καὶ αὐτὸς ἐγγυητὴς τριακοσίων ταλάντων γίνεται. καὶ ἐπὶ τούτοις ἔλυσε τὸν πόλεμον Σκαῦρος οὐχ ἧττον αὐτὸς ἢ συνέβαινεν Ἀρέταν ἐπιθυμεῖν τοῦτο γενέσθαι βουλόμενος."},{"number":82,"text":"Χρόνῳ δʼ ὕστερον Ἀλεξάνδρου τὴν Ἰουδαίαν κατατρέχοντος τοῦ Ἀριστοβούλου παιδὸς Γαβίνιος ἐκ Ῥώμης στρατηγὸς εἰς Συρίαν ἧκεν, ὃς ἄλλα τε λόγου ἄξια διεπράξατο καὶ ἐπʼ Ἀλέξανδρον ἐστράτευσεν, μηκέτι Ὑρκανοῦ πρὸς τὴν ἐκείνου ῥώμην ἀντέχειν δυναμένου, ἀλλʼ ἀνεγείρειν ἤδη καὶ τὸ τῶν Ἱεροσολύμων τεῖχος ἐπιχειροῦντος, ὅπερ καθεῖλεν Πομπήιος."},{"number":83,"text":"ἀλλὰ τούτου μὲν αὐτὸν ἐπέσχον οἱ ἐνταῦθα Ῥωμαῖοι. περιιὼν δὲ ἐν κύκλῳ τὴν χώραν πολλοὺς ὥπλιζεν τῶν Ἰουδαίων καὶ συνέλεξεν ταχὺ μυρίους μὲν ὁπλίτας πεντακοσίους δὲ πρὸς τοῖς χιλίοις ἱππεῖς, Ἀλεξάνδρειόν τε ὠχύρου τὸ πρὸς ταῖς Κορέαις ἔρυμα καὶ Μαχαιροῦντα πρὸς τοῖς Ἀραβίοις ὄρεσιν."},{"number":84,"text":"ἔρχεται οὖν ἐπʼ αὐτὸν Γαβίνιος Μᾶρκον Ἀντώνιον προπέμψας σὺν ἄλλοις ἡγεμόσιν· οἱ δὲ ὁπλίσαντες Ῥωμαίων τοὺς ἑπομένους καὶ σὺν τούτοις τοὺς ὑπηκόους Ἰουδαίους, ὧν Πειθόλαος ἡγεῖτο καὶ Μάλιχος, προσλαβόντες δὲ καὶ τὸ Ἀντιπάτρου ἑταιρικὸν ὑπήντων Ἀλεξάνδρῳ· ἠκολούθει δὲ καὶ Γαβίνιος σὺν τῇ φάλαγγι."},{"number":85,"text":"καὶ ἀναχωρεῖ μὲν ἐγγὺς Ἱεροσολύμων Ἀλέξανδρος, συμπεσόντων δὲ ἀλλήλοις ἐκεῖ καὶ μάχης γενομένης κτείνουσι μὲν οἱ Ῥωμαῖοι τῶν πολεμίων περὶ τρισχιλίους, ζωγροῦσι δὲ οὐκ ἔλαττον."},{"number":86,"text":"Ἐν τούτῳ Γαβίνιος ἐπʼ Ἀλεξάνδρειον ἐλθὼν προυκαλεῖτο τοὺς ἔνδον εἰς διαλύσεις συγγνώσεσθαι περὶ τῶν πρόσθεν αὐτοῖς ἡμαρτημένων ὁμολογῶν. στρατοπεδευομένων δὲ πολλῶν πρὸ τοῦ ἐρύματος πολεμίων, ἐφʼ οὓς ἀνῄεσαν οἱ Ῥωμαῖοι, Μᾶρκος Ἀντώνιος ἐπιφανῶς ἀγωνισάμενος καὶ πολλοὺς ἀποκτείνας ἔδοξεν ἠριστευκέναι."},{"number":87,"text":"Γαβίνιος μὲν οὖν μέρος τῆς στρατιᾶς ἐνταυθοῖ καταλιπών, ἕως ἂν ἐκπολιορκηθῇ τὸ χωρίον, αὐτὸς ἐπῄει τὴν ἄλλην Ἰουδαίαν, καὶ ὅσαις ἐπετύγχανεν καθῃρημέναις τῶν πόλεων κτίζειν παρεκελεύετο."},{"number":88,"text":"καὶ ἀνεκτίσθησαν Σαμάρεια καὶ Ἄζωτος καὶ Σκυθόπολις καὶ Ἀνθηδὼν καὶ Ῥάφεια καὶ Ἄδωρα Μάρισά τε καὶ Γάζα καὶ ἄλλαι οὐκ ὀλίγαι. τῶν δὲ ἀνθρώπων πειθομένων οἷς ὁ Γαβίνιος προσέταττεν βεβαίως οἰκηθῆναι τότε συνέβαινε τὰς πόλεις πολὺν χρόνον ἐρήμους γενομένας."},{"number":89,"text":"Ταῦτα δὲ διαπραξάμενος κατὰ τὴν χώραν ἐπάνεισιν ἐπὶ τὸ Ἀλεξάνδρειον, καὶ τὴν πολιορκίαν αὐτοῦ κρατύνοντος διαπρεσβεύεται πρὸς αὐτὸν Ἀλέξανδρος συγγινώσκειν τε αὐτῷ τῶν ἡμαρτημένων δεόμενος καὶ παραδιδοὺς τῶν ἐρυμάτων Ὑρκανίαν τε καὶ Μαχαιροῦντα, ὕστερον δὲ καὶ Ἀλεξάνδρειον."},{"number":90,"text":"καὶ ταῦτα μὲν Γαβίνιος κατέσκαψεν. τῆς δʼ Ἀλεξάνδρου μητρὸς πρὸς αὐτὸν ἐλθούσης, ἣ ἐφρόνει τὰ Ῥωμαίων τοῦ τε ἀνδρὸς αὐτῆς καὶ τῶν ἄλλων τέκνων ἐν Ῥώμῃ ἐχομένων, συνεχώρησεν αὐτῇ ταῦτα ἅπερ ἠξίου, καὶ διοικησάμενος τὰ πρὸς αὐτὴν Ὑρκανὸν κατήγαγεν εἰς Ἱεροσόλυμα σχήσοντα τὴν τοῦ ἱεροῦ ἐπιμέλειαν."},{"number":91,"text":"πέντε δὲ συνέδρια καταστήσας εἰς ἴσας μοίρας διένειμε τὸ ἔθνος, καὶ ἐπολιτεύοντο οἱ μὲν ἐν Ἱεροσολύμοις οἱ δὲ ἐν Γαδάροις οἱ δὲ ἐν Ἀμαθοῦντι, τέταρτοι δʼ ἦσαν ἐν Ἱεριχοῦντι, καὶ τὸ πέμπτον ἐν Σαπφώροις τῆς Γαλιλαίας. καὶ οἱ μὲν ἀπηλλαγμένοι δυναστείας ἐν ἀριστοκρατίᾳ διῆγον."}],"6":[{"number":92,"text":"Ἀριστοβούλου δὲ διαδράντος ἐκ Ῥώμης εἰς τὴν Ἰουδαίαν καὶ τὸ Ἀλεξάνδρειον, ὅπερ ἦν νεωστὶ κατεσκαμμένον, ἀνακτίζειν προαιρουμένου, πέμπει Γαβίνιος ἐπʼ αὐτὸν στρατιώτας καὶ ἡγεμόνας Σισένναν τε καὶ Ἀντώνιον καὶ Σερουίλιον κωλύσοντάς τε τὸ χωρίον αὐτὸν κατασχεῖν καὶ συλληψομένους αὐτόν."},{"number":93,"text":"πολλοὶ δʼ Ἀριστοβούλῳ τῶν Ἰουδαίων κατὰ τὴν παλαιὰν εὔκλειαν προσέρρεον καὶ δὴ καὶ νεωτέροις χαίροντες ἀεὶ πράγμασιν· Πειθόλαος γοῦν τις ὑποστράτηγος ἐν Ἱεροσολύμοις ὢν μετὰ χιλίων ηὐτομόλησεν πρὸς αὐτόν·"},{"number":94,"text":"οἱ δὲ πολλοὶ τῶν προστιθεμένων ἦσαν ἄνοπλοι. διεγνώκει δʼ εἰς Μαχαιροῦντα ἀπανίστασθαι Ἀριστόβουλος· τούτους μὲν οὖν ἀπέλυσεν ἀπόρους ὄντας· οὐ γὰρ ἐγίνοντο αὐτῷ χρήσιμοι πρὸς τὰ ἔργα· τοὺς δʼ ὡπλισμένους περὶ ὀκτακισχιλίους ὄντας ἀναλαβὼν ᾤχετο."},{"number":95,"text":"καὶ προσπεσόντων αὐτοῖς τῶν Ῥωμαίων καρτερῶς ἡττῶνται τῇ μάχῃ γενναίως οἱ Ἰουδαῖοι καὶ προθύμως ἀγωνισάμενοι, βιασαμένων τε τῶν πολεμίων εἰς φυγὴν τρέπονται. καὶ φονεύονται μὲν αὐτῶν εἰς πεντακισχιλίους, οἱ δὲ λοιποὶ σκεδασθέντες ὡς ἐδύναντο σώζειν αὑτοὺς ἐπειρῶντο."},{"number":96,"text":"χιλίων μέντοι πλείονας ἔχων Ἀριστόβουλος εἰς Μαχαιροῦντα διέφυγεν ὠχύρου τε τὸ χωρίον καὶ πράττων κακῶς οὐδὲν ἧττον ἐλπίδος ἀγαθῆς εἴχετο. δύο δʼ ἡμέρας ἀντισχὼν τῇ πολιορκίᾳ καὶ πολλὰ τραύματα λαβὼν αἰχμάλωτος μετʼ Ἀντιγόνου τοῦ παιδός, ὃς δὴ καὶ συνέφυγεν ἐκ Ῥώμης αὐτῷ, πρὸς Γαβίνιον ἄγεται."},{"number":97,"text":"καὶ τοιαύτῃ μὲν Ἀριστόβουλος χρησάμενος τύχῃ πάλιν εἰς Ῥώμην ἀναπέμπεται καὶ δεθεὶς αὐτόθι κατείχετο, βασιλεύσας μὲν καὶ ἀρχιερατεύσας ἔτη τρία καὶ μῆνας ἕξ, ἀνὴρ δὲ λαμπρὸς καὶ μεγαλόψυχος γενόμενος. τὰ μέντοι τέκνα αὐτοῦ ἀνῆκεν ἡ σύγκλητος Γαβινίου γράψαντος τοῦθʼ ὑπεσχῆσθαι τῇ μητρὶ παραδούσῃ τὰ ἐρύματα. καὶ ταῦτα μὲν εἰς τὴν Ἰουδαίαν ἐπανέρχεται."},{"number":98,"text":"Γαβινίῳ δὲ ἐπὶ Πάρθους στρατεύοντι καὶ τὸν Εὐφράτην ἤδη πεπεραιωμένῳ μετέδοξεν εἰς τὴν Αἴγυπτον ὑποστρέψαντι καταστῆσαι Πτολεμαῖον εἰς αὐτήν. καὶ ταῦτα μὲν καὶ ἐν ἄλλοις δεδήλωται."},{"number":99,"text":"Γαβινίῳ μέντοι κατὰ τὴν στρατείαν ἣν ἐφʼ Ὑρκανὸν ἐστείλατο Ἀντίπατρος ὑπηρέτησεν σῖτον καὶ ὅπλα καὶ χρήματα, καὶ τοὺς ὑπὲρ Πηλούσιον τῶν Ἰουδαίων οὗτος αὐτῷ προσηγάγετο καὶ συμμάχους ἐποίησεν φύλακας ὄντας τῶν εἰς τὴν Αἴγυπτον ἐμβολῶν."},{"number":100,"text":"ἐπανελθὼν δʼ ἐκ τῆς Αἰγύπτου καταλαμβάνει τὴν Συρίαν στάσει καὶ ταραχῇ νοσοῦσαν· ὁ γὰρ Ἀριστοβούλου παῖς Ἀλέξανδρος παρελθὼν ἐξ ὑστέρου πάλιν εἰς τὴν ἀρχὴν κατὰ βίαν πολλοὺς μὲν τῶν Ἰουδαίων ἀπέστησεν, στρατεύματι δὲ μεγάλῳ τὴν χώραν ἐπερχόμενος ἔκτεινε πάντας ὅσους ἐπιτύχοι τῶν Ῥωμαίων εἴς τε ὄρος τὸ καλούμενον Γαριζεὶν συμφυγόντας προσέκειτο πολιορκῶν."},{"number":101,"text":"Ὁ δὲ Γαβίνιος τοιαῦτα τὰ κατὰ τὴν Συρίαν καταλαβὼν Ἀντίπατρον, συνετὸς γὰρ ἦν, πέμπει πρὸς τοὺς νενοσηκότας, εἰ παῦσαι δυνηθείη τῆς παραφροσύνης αὐτοὺς καὶ πεῖσαι πρὸς τὸν ἀμείνω λογισμὸν ἐπανελθεῖν."},{"number":102,"text":"ὁ δʼ ἐλθὼν πολλοὺς μὲν ἐσωφρόνισεν καὶ προσηγάγετο τῷ δέοντι, τὸν δὲ Ἀλέξανδρον οὐκ ἠδυνήθη κατασχεῖν· στρατοῦ γὰρ ἔχων οὗτος μυριάδας τρεῖς Ἰουδαίων ἀπήντησεν Γαβινίῳ καὶ συμβαλὼν ἡττᾶται πεσόντων αὐτῷ μυρίων περὶ τὸ Ἰταβύριον ὄρος."},{"number":103,"text":"Καταστησάμενος δὲ Γαβίνιος τὰ κατὰ τὴν Ἱεροσολυμιτῶν πόλιν, ὡς ἦν Ἀντιπάτρῳ θέλοντι, ἐπὶ τὴν Ναβαταίων ἔρχεται, καὶ κρατεῖ μὲν τούτων τῇ μάχῃ, Πάρθων δὲ φυγάδας Μιθριδάτην καὶ Ὀρσάνην ἐλθόντας προύπεμψεν, τῷ δὲ λόγῳ ἀπέδρασαν αὐτόν."},{"number":104,"text":"καὶ Γαβίνιος μὲν ἔργα μεγάλα καὶ λαμπρὰ κατὰ τὴν στρατηγίαν δράσας ἀπῆρεν εἰς Ῥώμην Κράσσῳ παραδοὺς τὴν ἀρχήν. περὶ δὲ τῆς Πομπηίου καὶ Γαβινίου στρατείας ἐπὶ Ἰουδαίους γράφει Νικόλαος ὁ Δαμασκηνὸς καὶ Στράβων ὁ Καππάδοξ οὐδὲν ἕτερος ἑτέρου καινότερον λέγων."}],"7":[{"number":105,"text":"Κράσσος δὲ ἐπὶ Πάρθους μέλλων στρατεύειν ἧκεν εἰς τὴν Ἰουδαίαν καὶ τὰ ἐν τῷ ἱερῷ χρήματα, ἃ Πομπήιος καταλελοίπει, δισχίλια δʼ ἦν τάλαντα, βαστάσας οἷός τε ἦν καὶ τὸν χρυσὸν ἅπαντα, τάλαντα δʼ οὗτος ἦν ὀκτακισχίλια, περιδύειν τοῦ ναοῦ."},{"number":106,"text":"λαμβάνει δὲ καὶ δοκὸν ὁλοσφύρητον χρυσῆν ἐκ μνῶν τριακοσίων πεποιημένην· ἡ δὲ μνᾶ παρʼ ἡμῖν ἰσχύει λίτρας δύο ἥμισυ. παρέδωκε δʼ αὐτῷ ταύτην τὴν δοκὸν ὁ τῶν χρημάτων φύλαξ ἱερεὺς Ἐλεάζαρος ὄνομα, οὐ διὰ πονηρίαν,"},{"number":107,"text":"ἀγαθὸς γὰρ ἦν καὶ δίκαιος, ἀλλὰ πεπιστευμένος τὴν τῶν καταπετασμάτων τοῦ ναοῦ φυλακὴν ὄντων θαυμασίων τὸ κάλλος καὶ πολυτελῶν τὴν κατασκευὴν ἐκ δὲ τῆς δοκοῦ ταύτης κρεμαμένων, ἐπεὶ τὸν Κράσσον ἑώρα περὶ τὴν τοῦ χρυσίου γινόμενον συλλογήν, δείσας περὶ τῷ παντὶ κόσμῳ καὶ τοῦ ναοῦ τὴν δοκὸν αὐτῷ τὴν χρυσῆν λύτρον ἀντὶ πάντων ἔδωκεν,"},{"number":108,"text":"ὅρκους παρʼ αὐτοῦ λαβὼν μηδὲν ἄλλο κινήσειν τῶν ἐκ τοῦ ναοῦ, μόνῳ δὲ ἀρκεσθήσεσθαι τῷ ὑπʼ αὐτοῦ δοθησομένῳ πολλῶν ὄντι μυριάδων ἀξίῳ. ἡ δὲ δοκὸς αὕτη ἦν ἐν ξυλίνῃ δοκῷ κενῇ, καὶ τοῦτο τοὺς μὲν ἄλλους ἐλάνθανεν ἅπαντας, ὁ δὲ Ἐλεάζαρος μόνος ἠπίστατο."},{"number":109,"text":"ὁ μέντοι Κράσσος καὶ ταύτην ὡς οὐδενὸς ἁψόμενος ἄλλου τῶν ἐν τῷ ἱερῷ λαμβάνει, καὶ παραβὰς τοὺς ὅρκους ἅπαντα τὸν ἐν τῷ ναῷ χρυσὸν ἐξεφόρησεν."},{"number":110,"text":"Θαυμάσῃ δὲ μηδείς, εἰ τοσοῦτος ἦν πλοῦτος ἐν τῷ ἡμετέρῳ ἱερῷ πάντων τῶν κατὰ τὴν οἰκουμένην Ἰουδαίων καὶ σεβομένων τὸν θεὸν ἔτι δὲ καὶ τῶν ἀπὸ τῆς Ἀσίας καὶ τῆς Εὐρώπης εἰς αὐτὸ συμφερόντων ἐκ πολλῶν πάνυ χρόνων."},{"number":111,"text":"οὐκ ἔστι δὲ ἀμάρτυρον τὸ μέγεθος τῶν προειρημένων χρημάτων, οὐδʼ ὑπὸ ἀλαζονείας ἡμετέρας καὶ περιττολογίας ἐπὶ τοσοῦτον ἐξαίρεται πλῆθος, ἀλλὰ πολλοί τε ἄλλοι τῶν συγγραφέων ἡμῖν μαρτυροῦσιν καὶ Στράβων ὁ Καππάδοξ λέγων οὕτως·"},{"number":112,"text":"πέμψας δὲ Μιθριδάτης εἰς Κῶ ἔλαβε τὰ χρήματα, ἃ παρέθετο ἐκεῖ Κλεοπάτρα βασίλισσα,"},{"number":113,"text":"καὶ τὰ τῶν Ἰουδαίων ὀκτακόσια τάλαντα. ἡμῖν δὲ δημόσια χρήματα οὐκ ἔστιν ἢ μόνα τὰ τοῦ θεοῦ, καὶ δῆλον, ὅτι ταῦτα μετήνεγκαν εἰς Κῶ τὰ χρήματα οἱ ἐν τῇ Ἀσίᾳ Ἰουδαῖοι διὰ τὸν Μιθριδάτου φόβον· οὐ γὰρ εἰκὸς τοὺς ἐν τῇ Ἰουδαίᾳ πόλιν τε ὀχυρὰν ἔχοντας καὶ τὸν ναὸν πέμπειν χρήματα εἰς Κῶ, ἀλλʼ οὐδὲ τοὺς ἐν Ἀλεξανδρείᾳ κατοικοῦντας Ἰουδαίους πιθανὸν τοῦτʼ ἐστὶ ποιῆσαι μηδὲν Μιθριδάτην δεδιότας."},{"number":114,"text":"μαρτυρεῖ δὲ καὶ ἐν ἑτέρῳ τόπῳ ὁ αὐτὸς Στράβων, ὅτι καθʼ ὃν καιρὸν διέβη Σύλλας εἰς τὴν Ἑλλάδα πολεμήσων Μιθριδάτῃ καὶ Λεύκολλον πέμψας ἐπὶ τὴν ἐν Κυρήνῃ στάσιν τοῦ ἔθνους ἡμῶν ἡ οἰκουμένη πεπλήρωτο, λέγων οὕτως·"},{"number":115,"text":"τέτταρες δʼ ἦσαν ἐν τῇ πόλει τῶν Κυρηναίων, ἥ τε τῶν πολιτῶν καὶ ἡ τῶν γεωργῶν τρίτη δʼ ἡ τῶν μετοίκων τετάρτη δʼ ἡ τῶν Ἰουδαίων. αὕτη δʼ εἰς πᾶσαν πόλιν ἤδη καὶ παρελήλυθεν καὶ τόπον οὐκ ἔστι ῥᾳδίως εὑρεῖν τῆς οἰκουμένης, ὃς οὐ παραδέδεκται τοῦτο τὸ φῦλον μηδʼ ἐπικρατεῖται ὑπʼ αὐτοῦ."},{"number":116,"text":"τήν τε Αἴγυπτον καὶ τὴν Κυρηναίων ἅτε τῶν αὐτῶν ἡγεμόνων τυχοῦσαν τῶν τε ἄλλων συχνὰ ζηλῶσαι συνέβη καὶ δὴ τὰ συντάγματα τῶν Ἰουδαίων θρέψαι διαφερόντως καὶ συναυξῆσαι χρώμενα τοῖς πατρίοις τῶν Ἰουδαίων νόμοις."},{"number":117,"text":"ἐν γοῦν Αἰγύπτῳ κατοικία τῶν Ἰουδαίων ἐστὶν ἀποδεδειγμένη χωρὶς καὶ τῆς Ἀλεξανδρέων πόλεως ἀφώρισται μέγα μέρος τῷ ἔθνει τούτῳ. καθίσταται δὲ καὶ ἐθνάρχης αὐτῶν, ὃς διοικεῖ τε τὸ ἔθνος καὶ διαιτᾷ κρίσεις καὶ συμβολαίων ἐπιμελεῖται καὶ προσταγμάτων, ὡς ἂν πολιτείας ἄρχων αὐτοτελοῦς."},{"number":118,"text":"ἐν Αἰγύπτῳ μὲν οὖν ἴσχυσε τὸ ἔθνος διὰ τὸ Αἰγυπτίους εἶναι τὸ ἐξ ἀρχῆς τοὺς Ἰουδαίους καὶ διὰ τὸ πλησίον ἔσεσθαι τὴν κατοικίαν τοὺς ἀπελθόντας ἐκεῖθεν, εἰς δὲ τὴν Κυρηναίαν μετέβη διὰ τὸ καὶ ταύτην ὅμορον εἶναι τῇ τῶν Αἰγυπτίων ἀρχῇ καθάπερ τὴν Ἰουδαίαν μᾶλλον δὲ τῆς ἀρχῆς ἐκείνης πρότερον. Στράβων μὲν δὴ ταῦτα λέγει."},{"number":119,"text":"Κράσσος δὲ πάντα διοικήσας ὃν αὐτὸς ἐβούλετο τρόπον ἐξώρμησεν ἐπὶ τὴν Παρθυαίαν· καὶ αὐτὸς μὲν σὺν ἅπαντι διεφθάρη τῷ στρατῷ, ὡς καὶ ἐν ἄλλοις δεδήλωται, Κάσσιος δὲ εἰς Συρίαν φυγὼν καὶ περιποιησάμενος αὐτὴν Πάρθοις ἐμποδὼν ἦν ἐκτρέχουσιν ἐπʼ αὐτὴν διὰ τὴν κατὰ Κράσσου νίκην."},{"number":120,"text":"αὖθις δʼ εἰς Τύρον ἀφικόμενος ἀνέβη καὶ εἰς τὴν Ἰουδαίαν. Ταριχέας μὲν οὖν εὐθὺς προσπεσὼν αἱρεῖ καὶ περὶ τρισμυρίους ἀνθρώπους ἀνδραποδίζει, Πειθόλαον δὲ τὸν τὴν Ἀριστοβούλου στάσιν διαδεδεγμένον κτείνει πρὸς τοῦτʼ αὐτὸν Ἀντιπάτρου παραστησαμένου,"},{"number":121,"text":"ᾧ πολύ τε καὶ παρʼ αὐτῷ συνέβαινε δύνασθαι καὶ πλείστου τότε ἄξιος ἦν καὶ παρὰ Ἰουδαίων οἷς παρὼν ἄγεται γυναῖκα τῶν ἐπισήμων ἐξ Ἀραβίας Κύπρον ὄνομα, ἐξ ἧς αὐτῷ τέσσαρες ἐγένοντο παῖδες, Φασάηλος καὶ Ἡρώδης, ὃς ὕστερον βασιλεὺς γίνεται, Ἰώσηπός τε καὶ Φερώρας, θυγάτηρ τε Σαλώμη."},{"number":122,"text":"οὗτος ὁ Ἀντίπατρος ἐπεποίητο καὶ πρὸς τοὺς ἄλλους δυνάστας φιλίαν τε καὶ ξενίαν, μάλιστα δὲ πρὸς τὸν Ἀράβων, ᾧ καὶ τὰ τέκνα πολεμῶν πρὸς Ἀριστόβουλον παρέθετο. Κάσσιος μὲν οὖν ἀναστρατευσάμενος ἐπὶ τὸν Εὐφράτην ἠπείγετο ὑπαντιάσων τοῖς ἐκεῖθεν ἐπιοῦσιν, ὡς καὶ ὑπʼ ἄλλων δεδήλωται."},{"number":123,"text":"Χρόνῳ δʼ ὕστερον Καῖσαρ κατασχὼν Ῥώμην μετὰ τὸ Πομπήιον καὶ τὴν σύγκλητον φυγεῖν πέραν τοῦ Ἰονίου παραλύσας τῶν δεσμῶν Ἀριστόβουλον εἰς Συρίαν πέμπειν διεγνώκει δύο παραδοὺς αὐτῷ τάγματα, ὡς ἂν εὐτρεπίζοι τὰ κατʼ αὐτὴν δυνατὸς ὤν."},{"number":124,"text":"Ἀριστόβουλος δʼ οὐκ ὤνατο τῶν ἐλπίδων, ἐφʼ αἷς ἔτυχε τῆς παρὰ Καίσαρος ἐξουσίας, ἀλλʼ αὐτὸν φθάσαντες οἱ τὰ Πομπηίου φρονοῦντες φαρμάκῳ διαφθείρουσιν, θάπτουσι δʼ αὐτὸν οἱ τὰ Καίσαρος θεραπεύοντες πράγματα, καὶ ὁ νεκρὸς ἔκειτο ἐν μέλιτι κεκηδευμένος ἐπὶ χρόνον πολὺν ἕως Ἀντώνιος αὐτὸν ὕστερον ἀποπέμψας εἰς τὴν Ἰουδαίαν ἐν ταῖς βασιλικαῖς θήκαις ἐποίησεν τεθῆναι."},{"number":125,"text":"Σκιπίων δʼ ἐπιστείλαντος αὐτῷ Πομπηίου ἀποκτεῖναι Ἀλέξανδρον τὸν Ἀριστοβούλου αἰτιασάμενος τὸν νεανίσκον ἐπὶ τοῖς τὸ πρῶτον εἰς Ῥωμαίους ἐξημαρτημένοις τῷ πελέκει διεχρήσατο. καὶ ὁ μὲν οὕτως ἐν Ἀντιοχείᾳ τελευτᾷ."},{"number":126,"text":"τοὺς δʼ ἀδελφοὺς αὐτοῦ Πτολεμαῖος ὁ Μενναίου παρέλαβεν δυναστεύων Χαλκίδος τῆς ὑπὸ τῷ Λιβάνῳ ὄρει, καὶ πέμψας τὸν υἱὸν Φιλιππίωνα εἰς Ἀσκάλωνα παρὰ τὴν Ἀριστοβούλου γυναῖκα ἐκέλευσεν αὐτῇ συναποστέλλειν τὸν υἱὸν Ἀντίγονον καὶ τὰς θυγατέρας, ὧν τῆς ἑτέρας ἐρασθεὶς Ἀλεξάνδρας ὁ Φιλιππίων ἄγεται γυναῖκα. μετὰ δὲ ταῦτα ἀνελὼν αὐτὸν ὁ πατὴρ Πτολεμαῖος γαμεῖ τε τὴν Ἀλεξάνδραν καὶ τῶν ἀδελφῶν αὐτῆς πρόνοιαν ποιούμενος διετέλει."}],"8":[{"number":127,"text":"Μετὰ δὲ τὸν Πομπηίου θάνατον καὶ τὴν νίκην τὴν ἐπʼ αὐτῷ Καίσαρι πολεμοῦντι κατʼ Αἴγυπτον πολλὰ χρήσιμον αὑτὸν παρέσχεν Ἀντίπατρος ὁ τῶν Ἰουδαίων ἐπιμελητὴς ἐξ ἐντολῆς Ὑρκανοῦ."},{"number":128,"text":"Μιθριδάτῃ τε γὰρ τῷ Περγαμηνῷ κομίζοντι ἐπικουρικὸν καὶ ἀδυνάτως ἔχοντι διὰ Πηλουσίου ποιήσασθαι τὴν πορείαν, περὶ δὲ Ἀσκάλωνα διατρίβοντι, ἧκεν Ἀντίπατρος ἄγων Ἰουδαίων ὁπλίτας τρισχιλίους ἐξ Ἀραβίας τε συμμάχους ἐλθεῖν ἐπραγματεύσατο τοὺς ἐν τέλει·"},{"number":129,"text":"καὶ διʼ αὐτὸν οἱ κατὰ τὴν Συρίαν ἅπαντες ἐπεκούρουν ἀπολείπεσθαι τῆς ὑπὲρ Καίσαρος προθυμίας οὐ θέλοντες, Ἰάμβλιχός τε ὁ δυνάστης καὶ Πτολεμαῖος ὁ Σοαίμου Λίβανον ὄρος οἰκῶν αἵ τε πόλεις σχεδὸν ἅπασαι."},{"number":130,"text":"Μιθριδάτης δὲ ἄρας ἐκ Συρίας εἰς Πηλούσιον ἀφικνεῖται καὶ μὴ δεχομένων αὐτὸν τῶν ἀνθρώπων ἐπολιόρκει τὴν πόλιν. ἠρίστευσε δὲ Ἀντίπατρος κατασύρας τι τοῦ τείχους καὶ ὁδὸν εἰσπεσεῖν παρέσχετο τοῖς ἄλλοις εἰς τὴν πόλιν."},{"number":131,"text":"καὶ τὸ μὲν Πηλούσιον οὕτως εἶχεν. τοὺς δὲ περὶ Ἀντίπατρον καὶ Μιθριδάτην ἀπιόντας πρὸς Καίσαρα διεκώλυον οἱ Ἰουδαῖοι οἱ τὴν Ὀνίου χώραν λεγομένην κατοικοῦντες. πείθει δὲ καὶ τούτους τὰ αὐτῶν φρονῆσαι κατὰ τὸ ὁμόφυλον Ἀντίπατρος καὶ μάλιστα ἐπιδείξας αὐτοῖς τὰς Ὑρκανοῦ τοῦ ἀρχιερέως ἐπιστολάς, ἐν αἷς αὐτοὺς φίλους εἶναι Καίσαρος παρεκάλει καὶ ξένια καὶ πάντα τὰ ἐπιτήδεια χορηγεῖν τῷ στρατῷ."},{"number":132,"text":"καὶ οἱ μὲν ὡς ἑώρων Ἀντίπατρον καὶ τὸν ἀρχιερέα συνθέλοντας ὑπήκουον. τούτους δὲ προσθεμένους ἀκούσαντες οἱ περὶ Μέμφιν ἐκάλουν καὶ αὐτοὶ τὸν Μιθριδάτην πρὸς ἑαυτούς· κἀκεῖνος ἐλθὼν καὶ τούτους παραλαμβάνει."},{"number":133,"text":"Ἐπεὶ δὲ τὸ καλούμενον Δέλτα ἤδη περιεληλύθει, συμβάλλει τοῖς πολεμίοις περὶ τὸ καλούμενον Ἰουδαίων στρατόπεδον. εἶχε δὲ τὸ μὲν δεξιὸν κέρας Μιθριδάτης, τὸ δʼ εὐώνυμον Ἀντίπατρος."},{"number":134,"text":"συμπεσόντων δὲ εἰς μάχην κλίνεται τὸ τοῦ Μιθριδάτου κέρας καὶ παθεῖν ἂν ἐκινδύνευσεν τὰ δεινότατα, εἰ μὴ παρὰ τὴν ᾐόνα τοῦ ποταμοῦ σὺν τοῖς οἰκείοις στρατιώταις Ἀντίπατρος παραθέων νενικηκὼς ἤδη τοὺς πολεμίους τὸν μὲν ῥύεται, προτρέπει δʼ εἰς φυγὴν τοὺς νενικηκότας Αἰγυπτίους."},{"number":135,"text":"αἱρεῖ δʼ αὐτῶν καὶ τὸ στρατόπεδον ἐπιμείνας τῇ διώξει, τόν τε Μιθριδάτην ἐκάλει πλεῖστον ἐν τῇ τροπῇ διασχόντα. ἔπεσον δὲ τῶν μὲν περὶ τοῦτον ὀκτακόσιοι, τῶν δʼ Ἀντιπάτρου πεντήκοντα."},{"number":136,"text":"Μιθριδάτης δὲ περὶ τούτων ἐπιστέλλει Καίσαρι τῆς τε νίκης αὐτοῖς ἅμα καὶ τῆς σωτηρίας αἴτιον τὸν Ἀντίπατρον ἀποφαίνων, ὥστε τὸν Καίσαρα τότε μὲν ἐπαινεῖν αὐτόν, κεχρῆσθαι δὲ παρὰ πάντα τὸν πόλεμον εἰς τὰ κινδυνωδέστατα τῷ Ἀντιπάτρῳ· καὶ δὴ καὶ τρωθῆναι συνέβη παρὰ τοὺς ἀγῶνας αὐτῷ."},{"number":137,"text":"Καταλύσας μέντοι Καῖσαρ μετὰ χρόνον τὸν πόλεμον καὶ εἰς Συρίαν ἀποπλεύσας ἐτίμησεν μεγάλως, Ὑρκανῷ μὲν τὴν ἀρχιερωσύνην βεβαιώσας, Ἀντιπάτρῳ δὲ πολιτείαν ἐν Ῥώμῃ δοὺς καὶ ἀτέλειαν πανταχοῦ."},{"number":138,"text":"λέγεται δʼ ὑπὸ πολλῶν Ὑρκανὸν ταύτης κοινωνῆσαι τῆς στρατείας καὶ ἐλθεῖν εἰς Αἴγυπτον, μαρτυρεῖ δέ μου τῷ λόγῳ καὶ Στράβων ὁ Καππάδοξ λέγων ἐξ Ἀσινίου ὀνόματος οὕτως· μετὰ τὸν Μιθριδάτην εἰσβαλεῖν εἰς τὴν Αἴγυπτον καὶ Ὑρκανὸν τὸν τῶν Ἰουδαίων ἀρχιερέα."},{"number":139,"text":"ὁ δʼ αὐτὸς οὗτος Στράβων καὶ ἐν ἑτέροις πάλιν ἐξ Ὑψικράτους ὀνόματος λέγει οὕτως· τὸν δὲ Μιθριδάτην ἐξελθεῖν μόνον, κληθέντα δʼ εἰς Ἀσκάλωνα Ἀντίπατρον ὑπʼ αὐτοῦ τὸν τῆς Ἰουδαίας ἐπιμελητὴν τρισχιλίους αὐτῷ στρατιώτας συμπαρασκευάσαι καὶ τοὺς ἄλλους δυνάστας προτρέψαι, κοινωνῆσαι δὲ τῆς στρατείας καὶ Ὑρκανὸν τὸν ἀρχιερέα. ταῦτα μὲν Στράβων φησίν."},{"number":140,"text":"Ἐλθὼν δὲ καὶ Ἀντίγονος ὁ Ἀριστοβούλου πρὸς Καίσαρα τήν τε τοῦ πατρὸς ἀπωδύρετο τύχην καὶ ὡς διʼ αὐτὸν ἀποθάνοι φαρμάκοις ἀναιρεθεὶς Ἀριστόβουλος καὶ ὁ ἀδελφὸς αὐτοῦ κτείναντος πελέκει Σκιπίωνος, ἐδεῖτό τε λαβεῖν οἶκτον αὐτοῦ τῆς ἀρχῆς ἐκβεβλημένου, Ὑρκανοῦ δὲ ἐπὶ τούτοις καὶ Ἀντιπάτρου κατηγόρει βιαίως ἐξηγουμένων τοῦ ἔθνους καὶ εἰς αὐτὸν παρανομησάντων."},{"number":141,"text":"παρὼν δʼ Ἀντίπατρος ἀπελογεῖτο μὲν ὑπὲρ ὧν ἑώρα τὴν κατηγορίαν κατʼ αὐτοῦ γεγενημένην, νεωτεριστὰς δʼ ἀπέφαινε τοὺς περὶ τὸν Ἀντίγονον καὶ στασιώδεις, ὅσα τε πονήσειεν αὐτὸς καὶ συνεργήσειεν ὑπεμίμνησκεν ἐπὶ τοῖς στρατεύμασιν ποιούμενος τοὺς λόγους ὧν αὐτὸς ἦν μάρτυς."},{"number":142,"text":"δικαίως τε ἔλεγεν Ἀριστόβουλον μὲν εἰς Ῥώμην ἀνάσπαστον γεγονέναι πολέμιον ἀεὶ καὶ μηδέποτε εὔνουν ὑπάρξαντα Ῥωμαίοις, τὸν δʼ ἀδελφὸν αὐτοῦ κολασθέντα ἐπὶ λῃστείᾳ ὑπὸ Σκιπίωνος τυχεῖν ὧν ἄξιος ἦν, ἀλλʼ οὐ κατὰ βίαν καὶ ἀδικίαν τοῦτο παθεῖν τοῦ δράσαντος."},{"number":143,"text":"Τούτους Ἀντιπάτρου ποιησαμένου τοὺς λόγους Καῖσαρ Ὑρκανὸν μὲν ἀποδείκνυσιν ἀρχιερέα, Ἀντιπάτρῳ δʼ ἐφίησιν δυναστείαν ἣν αὐτὸς προαιρεῖται. τούτου δὲ ἐπʼ αὐτῷ ποιησαμένου τὴν κρίσιν, ἐπίτροπον αὐτὸν ἀποδείκνυσιν τῆς Ἰουδαίας."},{"number":144,"text":"ἐπιτρέπει δὲ καὶ Ὑρκανῷ τὰ τῆς πατρίδος ἀναστῆσαι τείχη ταύτην αἰτησαμένῳ τὴν χάριν· ἔτι γὰρ ἐρήριπτο Πομπηίου καταβαλόντος· καὶ ταῦτα ἐπιστέλλει τοῖς ὑπάτοις εἰς Ῥώμην ἀναγράψαι ἐν τῷ Καπετωλίῳ. καὶ τὸ γενόμενον ὑπὸ τῆς συγκλήτου δόγμα τοῦτον ἔχει τὸν τρόπον·"},{"number":145,"text":"Λεύκιος Οὐαλέριος Λευκίου υἱὸς στρατηγὸς συνεβουλεύσατο τῇ συγκλήτῳ εἴδοις Δεκεμβρίαις ἐν τῷ τῆς Ὁμονοίας ναῷ. γραφομένῳ τῷ δόγματι παρῆσαν Λούκιος Κωπώνιος Λευκίου υἱὸς Κολλίνα καὶ Παπείριος Κυρίνα."},{"number":146,"text":"περὶ ὧν Ἀλέξανδρος Ἰάσονος καὶ Νουμήνιος Ἀντιόχου καὶ Ἀλέξανδρος Δωροθέου Ἰουδαίων πρεσβευταί, ἄνδρες ἀγαθοὶ καὶ σύμμαχοι διελέχθησαν ἀνανεούμενοι τὰς προϋπηργμένας πρὸς Ῥωμαίους χάριτας καὶ τὴν φιλίαν,"},{"number":147,"text":"καὶ ἀσπίδα χρυσῆν σύμβολον τῆς συμμαχίας γενομένην ἀνήνεγκαν ἀπὸ χρυσῶν μυριάδων πέντε, καὶ γράμματʼ αὐτοῖς ἠξίωσαν δοθῆναι πρός τε τὰς αὐτονομουμένας πόλεις καὶ πρὸς βασιλεῖς ὑπὲρ τοῦ τὴν χώραν αὐτῶν καὶ τοὺς λιμένας ἀδείας τυγχάνειν καὶ μηδὲν ἀδικεῖσθαι,"},{"number":148,"text":"ἔδοξεν συνθέσθαι φιλίαν καὶ χάριτας πρὸς αὐτούς, καὶ ὅσων ἐδεήθησαν τυχεῖν ταῦτʼ αὐτοῖς παρασχεῖν καὶ τὴν κομισθεῖσαν ἀσπίδα προσδέξασθαι. ταῦτα ἐγένετο ἐπὶ Ὑρκανοῦ ἀρχιερέως καὶ ἐθνάρχου ἔτους ἐνάτου μηνὸς Πανέμου."},{"number":149,"text":"Εὕρατο δὲ καὶ παρὰ τοῦ τῶν Ἀθηναίων δήμου τιμὰς Ὑρκανὸς πολλὰ καὶ αὐτὸς εἰς αὐτοὺς χρήσιμος γενόμενος, ἔπεμψάν τε αὐτῷ ψήφισμα τοῦτον περιέχον τὸν τρόπον· ἐπὶ πρυτάνεως καὶ ἱερέως Διονυσίου τοῦ Ἀσκληπιάδου μηνὸς Πανέμου πέμπτῃ ἀπιόντος ἐπεδόθη τοῖς στρατηγοῖς ψήφισμα Ἀθηναίων."},{"number":150,"text":"ἐπὶ Ἀγαθοκλέους ἄρχοντος Εὐκλῆς Μενάνδρου Ἀλιμούσιος ἐγραμμάτευε Μουνυχιῶνος ἑνδεκάτῃ τῆς πρυτανείας ἐκκλησίας ἀγομένης ἐν τῷ θεάτρῳ τῶν προέδρων ἐπεψήφισεν Δωρόθεος Ἐρχιεὺς καὶ οἱ συμπρόεδροι τῷ δήμῳ, Διονύσιος Διονυσίου εἶπεν·"},{"number":151,"text":"ἐπειδὴ Ὑρκανὸς Ἀλεξάνδρου ἀρχιερεὺς καὶ ἐθνάρχης τῶν Ἰουδαίων διατελεῖ κοινῇ τε τῷ δήμῳ καὶ ἰδίᾳ τῶν πολιτῶν ἑκάστῳ εὔνους ὢν καὶ πάσῃ χρώμενος περὶ αὐτοὺς σπουδῇ καὶ τοὺς παραγινομένους Ἀθηναίων ἢ κατὰ πρεσβείαν ἢ κατʼ ἰδίαν πρὸς αὐτὸν ὑποδέχεται φιλοφρόνως καὶ προπέμπει τῆς ἀσφαλοῦς αὐτῶν ἐπανόδου προνοούμενος,"},{"number":152,"text":"ἐμαρτυρήθη μὲν καὶ πρότερον περὶ τούτων, δεδόχθαι δὲ καὶ νῦν Διονυσίου τοῦ Θεοδώρου Σουνιέως εἰσηγησαμένου καὶ περὶ τῆς τἀνδρὸς ἀρετῆς ὑπομνήσαντος τὸν δῆμον, καὶ ὅτι προαίρεσιν ἔχει ποιεῖν ἡμᾶς ὅ τι ποτʼ ἂν δύνηται ἀγαθόν,"},{"number":153,"text":"τιμῆσαι τὸν ἄνδρα χρυσῷ στεφάνῳ ἀριστείῳ κατὰ τὸν νόμον, καὶ στῆσαι αὐτοῦ εἰκόνα χαλκῆν ἐν τῷ τεμένει τοῦ Δήμου καὶ τῶν Χαρίτων, ἀνειπεῖν δὲ τὸν στέφανον ἐν τῷ θεάτρῳ Διονυσίοις τραγῳδῶν τῶν καινῶν ἀγομένων καὶ Παναθηναίων καὶ Ἐλευσινίων καὶ ἐν τοῖς γυμνικοῖς ἀγῶσιν,"},{"number":154,"text":"ἐπιμεληθῆναι δὲ τοὺς στρατηγοὺς διαμένοντί τε αὐτῷ καὶ φυλάττοντι τὴν πρὸς ἡμᾶς εὔνοιαν εἶναι πᾶν ὅ τι ἂν ἐπινοήσωμεν εἰς τιμὴν καὶ χάριν τῆς τἀνδρὸς σπουδῆς καὶ φιλοτιμίας, ἵνα τούτων γινομένων φαίνηται ὁ δῆμος ἡμῶν ἀποδεχόμενος τοὺς ἀγαθοὺς καὶ τῆς προσηκούσης ἀμοιβῆς ἀξιῶν καὶ ζηλώσῃ τὴν περὶ ἡμᾶς σπουδὴν τῶν ἤδη τετιμημένων·"},{"number":155,"text":"ἑλέσθαι δὲ καὶ πρέσβεις ἐξ ἁπάντων Ἀθηναίων, οἵτινες τὸ ψήφισμά τε αὐτῷ κομιοῦσι καὶ παρακαλέσουσιν προσδεξάμενον τὰς τιμὰς πειρᾶσθαί τι ποιεῖν ἀγαθὸν ἡμῶν ἀεὶ τὴν πόλιν. αἱ μὲν οὖν παρὰ Ῥωμαίων καὶ τοῦ δήμου τοῦ Ἀθηναίων τιμαὶ πρὸς Ὑρκανὸν τὸν ἀρχιερέα καὶ διὰ τούτων ἡμῖν δεδήλωνται."}],"9":[{"number":156,"text":"Καῖσαρ δὲ διοικήσας τὰ κατὰ τὴν Συρίαν ἀπέπλευσεν. ὡς δὲ Καίσαρα προπέμψας ἐκ τῆς Συρίας Ἀντίπατρος εἰς τὴν Ἰουδαίαν ὑπέστρεψεν, ἀνεγείρει μὲν εὐθὺς τὸ τεῖχος ὑπὸ Πομπηίου καθῃρημένον καὶ τὸν κατὰ τὴν χώραν θόρυβον ἐπιὼν κατέστελλεν, ἀπειλῶν τε ἅμα καὶ συμβουλεύων ἠρεμεῖν·"},{"number":157,"text":"τοὺς μὲν γὰρ τὰ Ὑρκανοῦ φρονοῦντας ἐν εὑδίᾳ διάξειν καὶ βιώσεσθαι τῶν ἰδίων ἀπολαύοντας κτημάτων ἀταράχως, προστιθεμένους δὲ ταῖς ἐκ τοῦ νεωτερίζειν ἐλπίσιν καὶ τοῖς ἀπʼ αὐτῶν κέρδεσιν προσανέχοντας αὐτὸν μὲν ἕξειν ἀντὶ προστάτου δεσπότην, Ὑρκανὸν δὲ ἀντὶ βασιλέως τύραννον, Ῥωμαίους δὲ καὶ Καίσαρα πικροὺς ἀνθʼ ἡγεμόνων πολεμίους· οὐ γὰρ ἀνέξεσθαι μετακινούμενον ὃν αὐτοὶ κατέστησαν. ταῦτα λέγων καθίστα τὰ κατὰ τὴν χώραν."},{"number":158,"text":"Βραδὺν δʼ ὁρῶν καὶ νωθῆ τὸν Ὑρκανὸν Φασάηλον μὲν τὸν πρεσβύτατον τῶν παίδων Ἱεροσολύμων καὶ τῶν πέριξ στρατηγὸν ἀποδείκνυσιν, τῷ δὲ μετʼ αὐτὸν Ἡρώδῃ τὴν Γαλιλαίαν ἐπέτρεψεν νέῳ παντάπασιν ὄντι· πεντεκαίδεκα γὰρ ἐγεγόνει μόνα ἔτη."},{"number":159,"text":"βλάπτει δὲ οὐδὲν αὐτὸν ἡ νεότης, ἀλλʼ ὢν τὸ φρόνημα γενναῖος ὁ νεανίας ἀφορμὴν εὑρίσκει παραχρῆμα εἰς ἐπίδειξιν τῆς ἀρετῆς. καταλαβὼν γὰρ Ἐζεκίαν τὸν ἀρχιλῃστὴν τὰ προσεχῆ τῆς Συρίας κατατρέχοντα σὺν μεγάλῳ στίφει, τοῦτον συλλαβὼν κτείνει καὶ πολλοὺς τῶν σὺν αὐτῷ λῃστῶν."},{"number":160,"text":"σφόδρα δὲ αὐτοῦ τὸ ἔργον τοῦτο ἠγάπησαν οἱ Σύροι· ποθοῦσι γὰρ αὐτοῖς ἀπηλλάχθαι τοῦ λῃστηρίου τὴν χώραν ἐκαθάρευσεν. ὕμνουν γοῦν αὐτὸν ἐπὶ τούτῳ κατά τε κώμας καὶ κατὰ πόλεις ὡς εἰρήνην αὐτοῖς παρεσχηκότα καὶ ἀσφαλῆ τῶν κτημάτων ἀπόλαυσιν. ἐγένετο δὲ διὰ τοῦτο καὶ Σέξστῳ Καίσαρι γνώριμος ὄντι συγγενεῖ τοῦ μεγάλου Καίσαρος καὶ διέποντι τὴν Συρίαν."},{"number":161,"text":"ζῆλος δʼ ἐμπίπτει τῶν Ἡρώδῃ πεπραγμένων Φασαήλῳ τῷ ἀδελφῷ, καὶ πρὸς τὴν εὐδοκίμησιν αὐτοῦ κινηθεὶς ἐφιλοτιμεῖτο μὴ ἀπολειφθῆναι τῆς ὁμοίας εὐφημίας, καὶ τοὺς ἐν τοῖς Ἱεροσολύμοις εὐνουστέρους ἐποιεῖτο, διʼ αὐτοῦ μὲν ἔχων τὴν πόλιν, οὔτε δὲ ἀπειροκάλως τοῖς πράγμασι προσφερόμενος οὔτʼ ἐξυβρίζων εἰς τὴν ἐξουσίαν."},{"number":162,"text":"ταῦτʼ Ἀντίπατρον ἐποίει θεραπείας παρὰ τοῦ ἔθνους τυγχάνειν βασιλικῆς καὶ τιμῶν οἵων ἄν τις μεταλαμβάνοι τῶν ὅλων ὢν δεσπότης. ὑπὸ μέντοι τῆς ἐκ τούτων λαμπρότητος οὐδὲν οἷα φιλεῖ συμβαίνειν πολλάκις τῆς πρὸς Ὑρκανὸν εὐνοίας παρέβη καὶ πίστεως."},{"number":163,"text":"Οἱ δʼ ἐν τέλει τῶν Ἰουδαίων ὁρῶντες τὸν Ἀντίπατρον καὶ τοὺς υἱοὺς αὐτοῦ μεγάλως αὐξανομένους εὐνοίᾳ τε τῇ παρὰ τοῦ ἔθνους καὶ προσόδῳ τῇ τε παρὰ τῆς Ἰουδαίας καὶ τῶν Ὑρκανοῦ χρημάτων, κακοήθως εἶχον πρὸς αὐτόν·"},{"number":164,"text":"καὶ γὰρ φιλίαν ὁ Ἀντίπατρος ἦν πεποιημένος πρὸς τοὺς Ῥωμαίων αὐτοκράτορας καὶ χρήματα πείσας πέμψαι τὸν Ὑρκανὸν αὐτὸς λαβὼν νοσφίζεται τὴν δωρεάν· ὡς ἰδίαν γὰρ ἀλλʼ οὐχ ὡς Ὑρκανοῦ διδόντος ἔπεμψεν."},{"number":165,"text":"ταῦθʼ Ὑρκανὸς ἀκούων οὐκ ἐφρόντιζεν, ἐν δέει δὲ ἦσαν οἱ πρῶτοι τῶν Ἰουδαίων ὁρῶντες τὸν Ἡρώδην βίαιον καὶ τολμηρὸν καὶ τυραννίδος γλιχόμενον· καὶ προσελθόντες Ὑρκανῷ φανερῶς ἤδη κατηγόρουν Ἀντιπάτρου, καί μέχρι πότε, ἔφασαν, ἐπὶ τοῖς πραττομένοις ἡσυχάσεις; ἦ οὐχ ὁρᾷς Ἀντίπατρον μὲν καὶ τοὺς παῖδας αὐτοῦ τὴν ἀρχὴν διεζωσμένους, σαυτὸν μέντοι τῆς βασιλείας ὄνομα μόνον ἀκούοντα;"},{"number":166,"text":"ἀλλὰ μὴ λανθανέτω σε ταῦτα μηδὲ ἀκίνδυνος εἶναι νόμιζε ῥαθυμῶν περί τε σαυτῷ καὶ τῇ βασιλείᾳ· οὐ γὰρ ἐπίτροποί σοι τῶν πραγμάτων Ἀντίπατρος καὶ οἱ παῖδες αὐτοῦ νῦν εἰσιν, μηδὲ ἀπάτα σαυτὸν τοῦτο οἰόμενος, ἀλλὰ δεσπόται φανερῶς ἀνωμολόγηνται·"},{"number":167,"text":"καὶ γὰρ Ἡρώδης ὁ παῖς αὐτοῦ Ἐζεκίαν ἀπέκτεινεν καὶ πολλοὺς σὺν αὐτῷ παραβὰς τὸν ἡμέτερον νόμον, ὃς κεκώλυκεν ἄνθρωπον ἀναιρεῖν καὶ πονηρὸν ὄντα, εἰ μὴ πρότερον κατακριθείη τοῦτο παθεῖν ὑπὸ τοῦ συνεδρίου. μὴ λαβὼν δὲ ἐξουσίαν παρὰ σοῦ ταῦτα ἐτόλμησεν."},{"number":168,"text":"Ὑρκανὸς δὲ ἀκούσας ταῦτα πείθεται· προσεξῆψαν δὲ αὐτοῦ τὴν ὀργὴν καὶ αἱ μητέρες τῶν ὑπὸ Ἡρώδου πεφονευμένων· αὗται γὰρ καθʼ ἑκάστην ἡμέραν ἐν τῷ ἱερῷ παρακαλοῦσαι τὸν βασιλέα καὶ τὸν δῆμον, ἵνα δίκην Ἡρώδης ἐν τῷ συνεδρίῳ τῶν πεπραγμένων ὑπόσχῃ, διετέλουν."},{"number":169,"text":"κινηθεὶς οὖν ὑπὸ τούτων Ὑρκανὸς Ἡρώδην ἐκάλει δικασόμενον ὑπὲρ ὧν διεβάλλετο. ὁ δὲ ἧκεν τοῦ πατρὸς αὐτῷ παραινέσαντος μὴ ὡς ἰδιώτῃ μετὰ δʼ ἀσφαλείας εἰσελθεῖν καὶ φυλακῆς τῆς περὶ τὸ σῶμα, τά τε κατὰ τὴν Γαλιλαίαν ὡς ἐνόμισεν αὐτῷ συμφέρειν ἀσφαλίσασθαι. τοῦτον τὸν τρόπον ἁρμοσάμενος καὶ μετὰ στίφους ἀποχρῶντος αὐτῷ πρὸς τὴν ὁδόν, ὡς μήτε ἐπίφοβος Ὑρκανῷ δόξειε μετὰ μείζονος παραγενόμενος τάγματος μήτε γυμνὸς καὶ ἀφύλακτος, ᾔει πρὸς τὴν δίκην."},{"number":170,"text":"Σέξστος μέντοι ὁ τῆς Συρίας ἡγεμὼν γράφει παρακαλῶν Ὑρκανὸν ἀπολῦσαι τὸν Ἡρώδην ἐκ τῆς δίκης καὶ προσαπειλῶν παρακούσαντι. τῷ δʼ ἦν ἀφορμὴ τὸ παρὰ τοῦ Σέξστου γράμμα πρὸς τὸ μηδὲν ἐκ τοῦ συνεδρίου παθόντα ἀπολῦσαι τὸν Ἡρώδην· ἠγάπα γὰρ αὐτὸν ὡς υἱόν."},{"number":171,"text":"καταστὰς δὲ ἐν τῷ συνεδρίῳ μετὰ τοῦ σὺν αὐτῷ τάγματος Ἡρώδης κατέπληξεν ἅπαντας καὶ κατηγορεῖν ἐθάρρει τὸ λοιπὸν οὐδεὶς τῶν πρὶν ἀφικέσθαι διαβαλλόντων, ἀλλʼ ἦν ἡσυχία καὶ τοῦ τί χρὴ ποιεῖν ἀπορία."},{"number":172,"text":"διακειμένων δʼ οὕτως εἷς τις Σαμαίας ὄνομα, δίκαιος ἀνὴρ καὶ διὰ τοῦτο τοῦ δεδιέναι κρείττων, ἀναστὰς εἶπεν· ἄνδρες σύνεδροι καὶ βασιλεῦ, εἰς δίκην μὲν οὔτʼ αὐτὸς οἶδά τινα τῶν πώποτε εἰς ὑμᾶς κεκλημένων οὕτω παραστάντα οὔτε ὑμᾶς ἔχειν εἰπεῖν ὑπολαμβάνω, ἀλλὰ πᾶς ὁστισδηποτοῦν ἀφῖκται εἰς τὸ συνέδριον τοῦτο κριθησόμενος ταπεινὸς παρίσταται καὶ σχήματι δεδοικότος καὶ ἔλεον θηρωμένου παρʼ ὑμῶν, κόμην τʼ ἐπιθρέψας καὶ ἐσθῆτα μέλαιναν ἐνδεδυμένος."},{"number":173,"text":"ὁ δὲ βέλτιστος Ἡρώδης φόνου δίκην φεύγων καὶ ἐπʼ αἰτίᾳ τοιαύτῃ κεκλημένος ἕστηκε τὴν πορφύραν περικείμενος καὶ τὴν κεφαλὴν κεκοσμημένος τῇ συνθέσει τῆς κόμης καὶ περὶ αὐτὸν ἔχων ὁπλίτας, ἵνα ἂν κατακρίνωμεν αὐτοῦ κατὰ τὸν νόμον, κτείνῃ μὲν ἡμᾶς, αὐτὸν δὲ σώσῃ βιασάμενος τὸ δίκαιον."},{"number":174,"text":"ἀλλʼ Ἡρώδην μὲν ἐπὶ τούτοις οὐκ ἂν μεμψαίμην, εἰ τὸ αὐτοῦ συμφέρον ποιεῖται περὶ πλείονος ἢ τὸ νόμιμον, ὑμᾶς δὲ καὶ τὸν βασιλέα τοσαύτην ἄδειαν αὐτῷ παρασχόντας. ἴστε μέντοι τὸν θεὸν μέγαν, καὶ οὗτος, ὃν νῦν διʼ Ὑρκανὸν ἀπολῦσαι βούλεσθε, κολάσει ὑμᾶς τε καὶ αὐτὸν τὸν βασιλέα."},{"number":175,"text":"διήμαρτεν δʼ οὐδὲν τῶν εἰρημένων. ὁ γὰρ Ἡρώδης τὴν βασιλείαν παραλαβὼν πάντας ἀπέκτεινεν τοὺς ἐν τῷ συνεδρίῳ καὶ Ὑρκανὸν αὐτὸν χωρὶς τοῦ Σαμαίου·"},{"number":176,"text":"σφόδρα γὰρ αὐτὸν διὰ τὴν δικαιοσύνην ἐτίμησεν καὶ ὅτι τῆς πόλεως μετὰ ταῦτα πολιορκουμένης ὑπό τε Ἡρώδου καὶ Σοσσίου παρῄνεσεν τῷ δήμῳ δέξασθαι τὸν Ἡρώδην εἰπὼν διὰ τὰς ἁμαρτίας οὐ δύνασθαι διαφυγεῖν αὐτόν. καὶ περὶ μὲν τούτων κατὰ χώραν ἐροῦμεν."},{"number":177,"text":"Ὑρκανὸς δὲ ὁρῶν ὡρμημένους πρὸς τὴν ἀναίρεσιν τὴν Ἡρώδου τοὺς ἐν τῷ συνεδρίῳ τὴν δίκην εἰς ἄλλην ἡμέραν ἀνεβάλετο, καὶ πέμψας κρύφα πρὸς Ἡρώδην συνεβούλευσεν αὐτῷ φυγεῖν ἐκ τῆς πόλεως· οὕτω γὰρ τὸν κίνδυνον διαφεύξεσθαι."},{"number":178,"text":"καὶ ὁ μὲν ἀνεχώρησεν εἰς Δαμασκὸν ὡς φεύγων τὸν βασιλέα, καὶ παραγενόμενος πρὸς Σέξτον Καίσαρα καὶ τὰ κατʼ αὐτὸν ἀσφαλισάμενος οὕτως εἶχεν, ὡς εἰ καλοῖτο πάλιν εἰς τὸ συνέδριον ἐπὶ δίκην οὐχ ὑπακουσόμενος."},{"number":179,"text":"ἠγανάκτουν δὲ οἱ ἐν τῷ συνεδρίῳ καὶ τὸν Ὑρκανὸν ἐπειρῶντο διδάσκειν, ὅτι ταῦτα πάντα εἴη κατʼ αὐτοῦ. τὸν δʼ οὐκ ἐλάνθανε μέν, πράττειν δʼ οὐδὲν εἶχεν ὑπὸ ἀνανδρίας καὶ ἀνοίας."},{"number":180,"text":"Σέξστου δὲ ποιήσαντος Ἡρώδην στρατηγὸν κοίλης Συρίας, χρημάτων γὰρ αὐτῷ τοῦτο ἀπέδοτο, Ὑρκανὸς ἦν ἐν φόβῳ, μὴ στρατεύσηται Ἡρώδης ἐπʼ αὐτόν. οὐ πολὺ δὲ τοῦ δέους ἐβράδυνεν, ἀλλʼ ἧκεν ἄγων ἐπʼ αὐτὸν Ἡρώδης στρατιὰν ὀργιζόμενος τῆς δίκης αὐτῷ καὶ τοῦ κληθῆναι πρὸς τὸ λόγον ὑποσχεῖν ἐν τῷ συνεδρίῳ."},{"number":181,"text":"διεκώλυσαν δʼ αὐτὸν προσβαλεῖν τοῖς Ἱεροσολύμοις ὑπαντήσαντες ὅ τε πατὴρ Ἀντίπατρος καὶ ὁ ἀδελφός, καὶ τὴν ὁρμὴν αὐτοῦ καταπαύσαντες καὶ παρακαλέσαντες ἔργῳ μὲν ἐγχειρεῖν μηδενί, καταπληξάμενον δὲ ἀπειλῇ μόνον μὴ χωρῆσαι περαιτέρω κατὰ τοῦ παρασχόντος αὐτῷ εἰς τοῦτο παρελθεῖν τὸ ἀξίωμα."},{"number":182,"text":"ἠξίουν τε περὶ τοῦ κληθέντα ἐπὶ δίκην ἐλθεῖν ἀγανακτοῦντα μεμνῆσθαι καὶ τῆς ἀφέσεως καὶ χάριν αὐτῆς εἰδέναι καὶ μὴ πρὸς μὲν τὸ σκυθρωπότερον ἀπαντᾶν, περὶ δὲ τῆς σωτηρίας ἀχαριστεῖν·"},{"number":183,"text":"λογίζεσθαι δʼ ὡς, εἰ καὶ πολέμου ῥοπὰς βραβεύει τὸ θεῖον, πλέον ἐστὶ τῆς στρατείας τὸ ἄδικον, διὸ καὶ τὴν νίκην μὴ πάντῃ προσδοκᾶν μέλλοντα πολεμεῖν βασιλεῖ καὶ συντρόφῳ, καὶ πολλὰ μὲν εὐεργετήσαντι, μηδὲν δὲ χαλεπὸν αὐτὸν εἰργασμένῳ, περὶ δὲ ὧν ἐγκαλεῖ διὰ πονηροὺς συμβούλους ἀλλὰ μὴ διʼ αὐτὸν ὑπόνοιαν αὐτῷ καὶ σκιὰν δυσκόλου τινὸς παρεσχημένῳ."},{"number":184,"text":"πείθεται τούτοις Ἡρώδης ὑπολαβὼν εἰς τὰς ἐλπίδας ἀποχρῆν αὐτῷ τὸ καὶ τὴν ἰσχὺν ἐπιδείξασθαι τῷ ἔθνει μόνον. καὶ τὰ μὲν κατὰ τὴν Ἰουδαίαν οὕτως εἶχεν."}],"10":[{"number":185,"text":"Καῖσαρ δʼ ἐλθὼν εἰς Ῥώμην ἕτοιμος ἦν πλεῖν ἐπʼ Ἀφρικῆς πολεμήσων Σκιπίωνι καὶ Κάτωνι, πέμψας δʼ Ὑρκανὸς πρὸς αὐτὸν παρεκάλει βεβαιώσασθαι τὴν πρὸς αὐτὸν φιλίαν καὶ συμμαχίαν."},{"number":186,"text":"ἔδοξεν δʼ ἀναγκαῖον εἶναί μοι πάσας ἐκθέσθαι τὰς γεγενημένας Ῥωμαίοις καὶ τοῖς αὐτοκράτορσιν αὐτῶν τιμὰς καὶ συμμαχίας πρὸς τὸ ἔθνος ἡμῶν, ἵνα μὴ λανθάνῃ τοὺς ἄλλους ἅπαντας, ὅτι καὶ οἱ τῆς Ἀσίας καὶ οἱ τῆς Εὐρώπης βασιλεῖς διὰ σπουδῆς ἔσχον ἡμᾶς τήν τε ἀνδρείαν ἡμῶν καὶ τὴν πίστιν ἀγαπήσαντες."},{"number":187,"text":"ἐπεὶ δὲ πολλοὶ διὰ τὴν πρὸς ἡμᾶς δυσμένειαν ἀπιστοῦσι τοῖς ὑπὸ Περσῶν καὶ Μακεδόνων ἀναγεγραμμένοις περὶ ἡμῶν τῷ μηκέτʼ αὐτὰ πανταχοῦ μηδʼ ἐν τοῖς δημοσίοις ἀποκεῖσθαι τόποις, ἀλλὰ παρʼ ἡμῖν τε αὐτοῖς καί τισιν ἄλλοις τῶν βαρβάρων,"},{"number":188,"text":"πρὸς δὲ τὰ ὑπὸ Ῥωμαίων δόγματα οὐκ ἔστιν ἀντειπεῖν· ἔν τε γὰρ δημοσίοις ἀνάκειται τόποις τῶν πόλεων καὶ ἔτι νῦν ἐν τῷ Καπετωλίῳ χαλκαῖς στήλαις ἐγγέγραπται, οὐ μὴν ἀλλὰ καὶ Καῖσαρ Ἰούλιος τοῖς ἐν Ἀλεξανδρείᾳ Ἰουδαίοις ποιήσας χαλκῆν στήλην ἐδήλωσεν, ὅτι Ἀλεξανδρέων πολῖταί εἰσιν, ἐκ τούτων ποιήσομαι καὶ τὴν ἀπόδειξιν."},{"number":189,"text":"παραθήσομαι δὲ τὰ γενόμενα ὑπό τε τῆς συγκλήτου δόγματα καὶ Ἰουλίου Καίσαρος πρός τε Ὑρκανὸν καὶ τὸ ἔθνος ἡμῶν."},{"number":190,"text":"Γάιος Ἰούλιος Καῖσαρ αὐτοκράτωρ καὶ ἀρχιερεὺς δικτάτωρ τὸ δεύτερον Σιδωνίων ἄρχουσιν βουλῇ δήμῳ χαίρειν. εἰ ἔρρωσθε εὖ ἂν ἔχοι, κἀγὼ δὲ ἔρρωμαι σὺν τῷ στρατοπέδῳ."},{"number":191,"text":"τῆς γενομένης ἀναγραφῆς ἐν τῇ δέλτῳ πρὸς Ὑρκανὸν υἱὸν Ἀλεξάνδρου ἀρχιερέα καὶ ἐθνάρχην Ἰουδαίων πέπομφα ὑμῖν τὸ ἀντίγραφον, ἵνʼ ἐν τοῖς δημοσίοις ὑμῶν ἀνακέηται γράμμασιν. βούλομαι δὲ καὶ ἑλληνιστὶ καὶ ῥωμαϊστὶ ἐν δέλτῳ χαλκῇ τοῦτο ἀνατεθῆναι."},{"number":192,"text":"ἔστιν δὴ τοῦτο· Ἰούλιος Καῖσαρ αὐτοκράτωρ τὸ δεύτερον καὶ ἀρχιερεὺς μετὰ συμβουλίου γνώμης ἐπέκρινα. ἐπεὶ Ὑρκανὸς Ἀλεξάνδρου Ἰουδαῖος καὶ νῦν καὶ ἐν τοῖς ἔμπροσθεν χρόνοις ἔν τε εἰρήνῃ καὶ πολέμῳ πίστιν τε καὶ σπουδὴν περὶ τὰ ἡμέτερα πράγματα ἐπεδείξατο, ὡς αὐτῷ πολλοὶ μεμαρτυρήκασιν αὐτοκράτορες,"},{"number":193,"text":"καὶ ἐν τῷ ἔγγιστα ἐν Ἀλεξανδρείᾳ πολέμῳ μετὰ χιλίων πεντακοσίων στρατιωτῶν ἧκεν σύμμαχος καὶ πρὸς Μιθριδάτην ἀποσταλεὶς ὑπʼ ἐμοῦ πάντας ἀνδρείᾳ τοὺς ἐν τάξει ὑπερέβαλεν,"},{"number":194,"text":"διὰ ταύτας τὰς αἰτίας Ὑρκανὸν Ἀλεξάνδρου καὶ τὰ τέκνα αὐτοῦ ἐθνάρχας Ἰουδαίων εἶναι ἀρχιερωσύνην τε Ἰουδαίων διὰ παντὸς ἔχειν κατὰ τὰ πάτρια ἔθη, εἶναί τε αὐτὸν καὶ τοὺς παῖδας αὐτοῦ συμμάχους ἡμῖν ἔτι τε καὶ ἐν τοῖς κατʼ ἄνδρα φίλοις ἀριθμεῖσθαι,"},{"number":195,"text":"ὅσα τε κατὰ τοὺς ἰδίους αὐτῶν νόμους ἐστὶν ἀρχιερατικὰ φιλάνθρωπα, ταῦτα κελεύω κατέχειν αὐτὸν καὶ τὰ τέκνα αὐτοῦ· ἄν τε μεταξὺ γένηταί τις ζήτησις περὶ τῆς Ἰουδαίων ἀγωγῆς, ἀρέσκει μοι κρίσιν γίνεσθαι παρʼ αὐτοῖς. παραχειμασίαν δὲ ἢ χρήματα πράσσεσθαι οὐ δοκιμάζω."},{"number":196,"text":"Γαΐου Καίσαρος αὐτοκράτορος ὑπάτου δεδομένα συγκεχωρημένα προσκεκριμένα ἐστὶν οὕτως ἔχοντα. ὅπως τὰ τέκνα αὐτοῦ τοῦ Ἰουδαίων ἔθνους ἄρχῃ, καὶ τοὺς δεδομένους τόπους καρπίζωνται, καὶ ὁ ἀρχιερεὺς αὐτὸς καὶ ἐθνάρχης τῶν Ἰουδαίων προϊστῆται τῶν ἀδικουμένων."},{"number":197,"text":"πέμψαι δὲ πρὸς Ὑρκανὸν τὸν Ἀλεξάνδρου υἱὸν ἀρχιερέα τῶν Ἰουδαίων καὶ πρεσβευτὰς τοὺς περὶ φιλίας καὶ συμμαχίας διαλεξομένους· ἀνατεθῆναι δὲ καὶ χαλκῆν δέλτον ταῦτα περιέχουσαν ἔν τε τῷ Καπετωλίῳ καὶ Σιδῶνι καὶ Τύρῳ καὶ ἐν Ἀσκάλωνι καὶ ἐν τοῖς ναοῖς ἐγκεχαραγμένην γράμμασιν Ῥωμαϊκοῖς καὶ Ἑλληνικοῖς."},{"number":198,"text":"ὅπως τε τὸ δόγμα τοῦτο πᾶσι τοῖς κατὰ τὴν πόλιν ταμίαις καὶ τοῖς τούτων ἡγουμένοις εἴς τε τοὺς φίλους ἀνενέγκωσιν καὶ ξένια τοῖς πρεσβευταῖς παρασχεῖν καὶ τὰ διατάγματα διαπέμψαι πανταχοῦ."},{"number":199,"text":"Γάιος Καῖσαρ αὐτοκράτωρ δικτάτωρ ὕπατος τιμῆς καὶ ἀρετῆς καὶ φιλανθρωπίας ἕνεκεν συνεχώρησεν ἐπὶ συμφέροντι καὶ τῇ συγκλήτῳ καὶ τῷ δήμῳ τῶν Ῥωμαίων Ὑρκανὸν Ἀλεξάνδρου υἱὸν καὶ τέκνα αὐτοῦ ἀρχιερεῖς τε καὶ ἱερεῖς Ἱεροσολύμων καὶ τοῦ ἔθνους εἶναι ἐπὶ τοῖς δικαίοις, οἷς καὶ οἱ πρόγονοι αὐτῶν τὴν ἀρχιερωσύνην διακατέσχον."},{"number":200,"text":"Γάιος Καῖσαρ ὕπατος τὸ πέμπτον ἔκρινεν τούτους ἔχειν καὶ τειχίσαι τὴν Ἱεροσολυμιτῶν πόλιν, καὶ κατέχειν αὐτὴν Ὑρκανὸν Ἀλεξάνδρου ἀρχιερέα Ἰουδαίων καὶ ἐθνάρχην ὡς ἂν αὐτὸς προαιρῆται."},{"number":201,"text":"ὅπως τε Ἰουδαίοις ἐν τῷ δευτέρῳ τῆς μισθώσεως ἔτει τῆς προσόδου κόρον ὑπεξέλωνται καὶ μήτε ἐργολαβῶσί τινες μήτε φόρους τοὺς αὐτοὺς τελῶσιν."},{"number":202,"text":"Γάιος Καῖσαρ αὐτοκράτωρ τὸ δεύτερον ἔστησεν κατʼ ἐνιαυτὸν ὅπως τελῶσιν ὑπὲρ τῆς Ἱεροσολυμιτῶν πόλεως Ἰόππης ὑπεξαιρουμένης χωρὶς τοῦ ἑβδόμου ἔτους, ὃν σαββατικὸν ἐνιαυτὸν προσαγορεύουσιν, ἐπεὶ ἐν αὐτῷ μήτε τὸν ἀπὸ τῶν δένδρων καρπὸν λαμβάνουσιν μήτε σπείρουσιν."},{"number":203,"text":"καὶ ἵνα ἐν Σιδῶνι τῷ δευτέρῳ ἔτει τὸν φόρον ἀποδιδῶσιν τὸ τέταρτον τῶν σπειρομένων, πρὸς τούτοις ἔτι καὶ Ὑρκανῷ καὶ τοῖς τέκνοις αὐτοῦ τὰς δεκάτας τελῶσιν, ἃς ἐτέλουν καὶ τοῖς προγόνοις αὐτῶν."},{"number":204,"text":"καὶ ὅπως μηδεὶς μήτε ἄρχων μήτε ἀντάρχων μήτε στρατηγὸς ἢ πρεσβευτὴς ἐν τοῖς ὅροις τῶν Ἰουδαίων ἀνιστὰς συμμαχίαν καὶ στρατιώτας ἐξῇ τούτῳ χρήματα εἰσπράττεσθαι ἢ εἰς παραχειμασίαν ἢ ἄλλῳ τινὶ ὀνόματι, ἀλλʼ εἶναι πανταχόθεν ἀνεπηρεάστους."},{"number":205,"text":"ὅσα τε μετὰ ταῦτα ἔσχον ἢ ἐπρίαντο καὶ διακατέσχον καὶ ἐνεμήθησαν, ταῦτα πάντα αὐτοὺς ἔχειν. Ἰόππην τε πόλιν, ἣν ἀπʼ ἀρχῆς ἔσχον οἱ Ἰουδαῖοι ποιούμενοι τὴν πρὸς Ῥωμαίους φιλίαν αὐτῶν εἶναι, καθὼς καὶ τὸ πρῶτον, ἡμῖν ἀρέσκει,"},{"number":206,"text":"φόρους τε ὑπὲρ ταύτης τῆς πόλεως Ὑρκανὸν Ἀλεξάνδρου υἱὸν καὶ παῖδας αὐτοῦ παρὰ τῶν τὴν γῆν νεμομένων χώρας λιμένος ἐξαγωγίου κατʼ ἐνιαυτὸν Σιδῶνι μοδίους δισμυρίους χοε ὑπεξαιρουμένου τοῦ ἑβδόμου ἔτους, ὃν σαββατικὸν καλοῦσιν, καθʼ ὃν οὔτε ἀροῦσιν οὔτε τὸν ἀπὸ τῶν δένδρων καρπὸν λαμβάνουσιν."},{"number":207,"text":"τάς τε κώμας τὰς ἐν τῷ μεγάλῳ πεδίῳ, ἃς Ὑρκανὸς καὶ οἱ πρόγονοι πρότερον αὐτοῦ διακατέσχον, ἀρέσκει τῇ συγκλήτῳ ταῦτα Ὑρκανὸν καὶ Ἰουδαίους ἔχειν ἐπὶ τοῖς δικαίοις οἷς καὶ πρότερον εἶχον."},{"number":208,"text":"μένειν δὲ καὶ τὰ ἀπʼ ἀρχῆς δίκαια, ὅσα πρὸς ἀλλήλους Ἰουδαίοις καὶ τοῖς ἀρχιερεῦσιν καὶ ἱερεῦσιν ἦν τά τε φιλάνθρωπα ὅσα τε τοῦ δήμου ψηφισαμένου καὶ τῆς συγκλήτου ἔσχον. ἐπὶ τούτοις τε τοῖς δικαίοις χρῆσθαι αὐτοῖς ἐξεῖναι ἐν Λύδδοις."},{"number":209,"text":"τούς τε τόπους καὶ χώραν καὶ ἐποίκια, ὅσα βασιλεῦσι Συρίας καὶ Φοινίκης συμμάχοις οὖσι Ῥωμαίων κατὰ δωρεὰν ὑπῆρχε καρποῦσθαι, ταῦτα δοκιμάζει ἡ σύγκλητος Ὑρκανὸν τὸν ἐθνάρχην καὶ Ἰουδαίους ἔχειν."},{"number":210,"text":"δεδόσθαι δὲ Ὑρκανῷ καὶ παισὶ τοῖς αὐτοῦ καὶ πρεσβευταῖς τοῖς ὑπʼ αὐτοῦ πεμφθεῖσιν ἔν τε πυγμῇ μονομάχων καὶ θηρίων καθεζομένοις μετὰ τῶν συγκλητικῶν θεωρεῖν αἰτησαμένους παρὰ δικτάτορος ἢ παρὰ ἱππάρχου παρελθεῖν εἰς τὴν σύγκλητον εἰσάγωσιν καὶ τὰ ἀποκρίματα αὐτοῖς ἀποδιδῶσιν ἐν ἡμέραις δέκα ταῖς ἁπάσαις, ἀφʼ ἧς ἂν τὸ δόγμα γένηται."},{"number":211,"text":"Γάιος Καῖσαρ αὐτοκράτωρ δικτάτωρ τὸ τέταρτον ὕπατός τε τὸ πέμπτον δικτάτωρ ἀποδεδειγμένος διὰ βίου λόγους ἐποιήσατο περὶ τῶν δικαίων τῶν Ὑρκανοῦ τοῦ Ἀλεξάνδρου ἀρχιερέως Ἰουδαίων καὶ ἐθνάρχου τοιούτους·"},{"number":212,"text":"τῶν πρὸ ἐμοῦ αὐτοκρατόρων ἐν ταῖς ἐπαρχίαις μαρτυρησάντων Ὑρκανῷ ἀρχιερεῖ Ἰουδαίων καὶ Ἰουδαίοις ἐπί τε συγκλήτου καὶ δήμου Ῥωμαίων, εὐχαριστήσαντος δὲ καὶ τοῦ δήμου καὶ τῆς συγκλήτου αὐτοῖς, καλῶς ἔχει καὶ ἡμᾶς ἀπομνημονεύειν καὶ προνοεῖν, ὡς Ὑρκανῷ καὶ τῷ ἔθνει τῶν Ἰουδαίων καὶ τοῖς Ὑρκανοῦ παισὶν ὑπὸ συγκλήτου καὶ δήμου Ῥωμαίων ἀξία τῆς πρὸς ἡμᾶς εὐνοίας αὐτῶν καὶ ὧν εὐεργέτησαν ἡμᾶς χάρις ἀνταποδοθῇ."},{"number":213,"text":"Ἰούλιος Γάιος ὑιοσο στρατηγὸς ὕπατος Ῥωμαίων Παριανῶν ἄρχουσι βουλῇ δήμῳ χαίρειν. ἐνέτυχόν μοι οἱ Ἰουδαῖοι ἐν Δήλῳ καί τινες τῶν παροίκων Ἰουδαίων παρόντων καὶ τῶν ὑμετέρων πρέσβεων καὶ ἐνεφάνισαν, ὡς ὑμεῖς ψηφίσματι κωλύετε αὐτοὺς τοῖς πατρίοις ἔθεσι καὶ ἱεροῖς χρῆσθαι."},{"number":214,"text":"ἐμοὶ τοίνυν οὐκ ἀρέσκει κατὰ τῶν ἡμετέρων φίλων καὶ συμμάχων τοιαῦτα γίνεσθαι ψηφίσματα καὶ κωλύεσθαι αὐτοὺς ζῆν κατὰ τὰ αὐτῶν ἔθη καὶ χρήματα εἰς σύνδειπνα καὶ τὰ ἱερὰ εἰσφέρειν, τοῦτο ποιεῖν αὐτῶν μηδʼ ἐν Ῥώμῃ κεκωλυμένων."},{"number":215,"text":"καὶ γὰρ Γάιος Καῖσαρ ὁ ἡμέτερος στρατηγὸς καὶ ὕπατος ἐν τῷ διατάγματι κωλύων θιάσους συνάγεσθαι κατὰ πόλιν μόνους τούτους οὐκ ἐκώλυσεν οὔτε χρήματα συνεισφέρειν οὔτε σύνδειπνα ποιεῖν."},{"number":216,"text":"ὁμοίως δὲ κἀγὼ τοὺς ἄλλους θιάσους κωλύων τούτοις μόνοις ἐπιτρέπω κατὰ τὰ πάτρια ἔθη καὶ νόμιμα συνάγεσθαί τε καὶ ἑστιᾶσθαι. καὶ ὑμᾶς οὖν καλῶς ἔχει, εἴ τι κατὰ τῶν ἡμετέρων φίλων καὶ συμμάχων ψήφισμα ἐποιήσατε, τοῦτο ἀκυρῶσαι διὰ τὴν περὶ ἡμᾶς αὐτῶν ἀρετὴν καὶ εὔνοιαν."},{"number":217,"text":"Μετὰ δὲ τὸν Γαΐου θάνατον Μᾶρκος Ἀντώνιος καὶ Πόπλιος Δολαβέλλας ὕπατοι ὄντες τήν τε σύγκλητον συνήγαγον καὶ τοὺς παρʼ Ὑρκανοῦ πρέσβεις παραγαγόντες διελέχθησαν περὶ ὧν ἠξίουν καὶ φιλίαν πρὸς αὐτοὺς ἐποίησαν, καὶ πάντα συγχωρεῖν αὐτοῖς ἡ σύγκλητος ἐψηφίσατο ὅσων τυγχάνειν ἐβούλοντο."},{"number":218,"text":"παρατέθειμαι δὲ καὶ τὸ δόγμα, ὅπως τὴν ἀπόδειξιν τῶν λεγομένων ἐγγύθεν ἔχωσιν οἱ ἀναγινώσκοντες τὴν πραγματείαν. ἦν δὲ τοιοῦτον·"},{"number":219,"text":"Δόγμα συγκλήτου ἐκ τοῦ ταμιείου ἀντιγεγραμμένον ἐκ τῶν δέλτων τῶν δημοσίων τῶν ταμιευτικῶν Κοΐντω Ῥουτιλίω Κοΐντω Κορνηλίω ταμίαις κατὰ πόλιν, δέλτῳ δευτέρᾳ καὶ ἐκ τῶν πρώτων πρώτῃ. πρὸ τριῶν εἰδῶν Ἀπριλλίων ἐν τῷ ναῷ τῆς Ὁμονοίας. γραφομένῳ παρῆσαν Λούκιος Καλπούρνιος Μενηνία Πείσων,"},{"number":220,"text":"Σερουίνιος Παπίνιος Λεμωνία Κούιντος, Γάιος Κανείνιος Τηρητίνα Ῥέβιλος, Πόπλιος Τηδήτιος Λευκίου υἱὸς Πολλία, Λεύκιος Ἀπούλιος Λευκίου υἱὸς Σεργία, Φλάβιος Λευκίου Λεμωνία, Πόπλιος Πλαύτιος Ποπλίου Παπειρία, Μᾶρκος Σέλλιος Μάρκου Μαικία, Λεύκιος Ἐρούκιος Λουκίου Στηλητίνα, Μᾶρκος Κούιντος Μάρκου υἱὸς Πολλία Πλανκῖνος,"},{"number":221,"text":"Πούπλιος Σέρριος Πόπλιος Δολοβέλλας Μᾶρκος Ἀντώνιος ὕπατοι λόγους ἐποιήσαντο περὶ ὧν δόγματι συγκλήτου Γάιος Καῖσαρ ὑπὲρ Ἰουδαίων ἔκρινεν καὶ εἰς τὸ ταμιεῖον οὐκ ἔφθασεν ἀνενεχθῆναι, περὶ τούτων ἀρέσκει ἡμῖν γενέσθαι, ὡς καὶ Ποπλίῳ Δολαβέλλᾳ καὶ Μάρκῳ Ἀντωνίῳ τοῖς ὑπάτοις ἔδοξεν, ἀνενεγκεῖν τε ταῦτα εἰς δέλτους καὶ πρὸς τοὺς κατὰ πόλιν ταμίας, ὅπως φροντίσωσιν καὶ αὐτοὶ εἰς δέλτους ἀναθεῖναι διπτύχους."},{"number":222,"text":"ἐγένετο πρὸ πέντε εἰδῶν Φεβρουαρίων ἐν τῷ ναῷ τῆς Ὁμονοίας. οἱ δὲ πρεσβεύοντες παρὰ Ὑρκανοῦ τοῦ ἀρχιερέως ἦσαν οὗτοι· Λυσίμαχος Παυσανίου Ἀλέξανδρος Θεοδώρου Πάτροκλος Χαιρέου Ἰωάννης Ὀνείου."},{"number":223,"text":"Ἔπεμψεν δὲ τούτων Ὑρκανὸς τῶν πρεσβευτῶν ἕνα καὶ πρὸς Δολαβέλλαν τὸν τῆς Ἀσίας τότε ἡγεμόνα, παρακαλῶν ἀπολῦσαι τοὺς Ἰουδαίους τῆς στρατείας καὶ τὰ πάτρια τηρεῖν ἔθη καὶ κατὰ ταῦτα ζῆν ἐπιτρέπειν·"},{"number":224,"text":"οὗ τυχεῖν αὐτῷ ῥᾳδίως ἐγένετο· λαβὼν γὰρ ὁ Δολοβέλλας τὰ παρὰ τοῦ Ὑρκανοῦ γράμματα, μηδὲ βουλευσάμενος ἐπιστέλλει τοῖς κατὰ τὴν Ἀσίαν ἅπασιν γράψας τῇ Ἐφεσίων πόλει πρωτευούσῃ τῆς Ἀσίας περὶ τῶν Ἰουδαίων. ἡ δὲ ἐπιστολὴ τοῦτον περιεῖχεν τὸν τρόπον·"},{"number":225,"text":"Ἐπὶ πρυτάνεως Ἀρτέμωνος μηνὸς Ληναιῶνος προτέρᾳ. Δολοβέλλας αὐτοκράτωρ Ἐφεσίων ἄρχουσι βουλῇ δήμῳ χαίρειν."},{"number":226,"text":"Ἀλέξανδρος Θεοδώρου πρεσβευτὴς Ὑρκανοῦ τοῦ Ἀλεξάνδρου υἱοῦ ἀρχιερέως καὶ ἐθνάρχου τῶν Ἰουδαίων ἐνεφάνισέν μοι περὶ τοῦ μὴ δύνασθαι στρατεύεσθαι τοὺς πολίτας αὐτοῦ διὰ τὸ μήτε ὅπλα βαστάζειν δύνασθαι μήτε ὁδοιπορεῖν ἐν ταῖς ἡμέραις τῶν σαββάτων, μήτε τροφῶν τῶν πατρίων καὶ συνήθων κατὰ τούτους εὐπορεῖν."},{"number":227,"text":"ἐγώ τε οὖν αὐτοῖς, καθὼς καὶ οἱ πρὸ ἐμοῦ ἡγεμόνες, δίδωμι τὴν ἀστρατείαν καὶ συγχωρῶ χρῆσθαι τοῖς πατρίοις ἐθισμοῖς ἱερῶν ἕνεκα καὶ ἁγίοις συναγομένοις, καθὼς αὐτοῖς νόμιμον, καὶ τῶν πρὸς τὰς θυσίας ἀφαιρεμάτων, ὑμᾶς τε βούλομαι ταῦτα γράψαι κατὰ πόλεις."},{"number":228,"text":"Καὶ ταῦτα μὲν ὁ Δολαβέλλας Ὑρκανοῦ πρεσβευσαμένου πρὸς αὐτὸν ἐχαρίσατο τοῖς ἡμετέροις. Λεύκιος δὲ Λέντλος ὕπατος εἶπεν· πολίτας Ῥωμαίων Ἰουδαίους ἱερὰ Ἰουδαϊκὰ ἔχοντας καὶ ποιοῦντας ἐν Ἐφέσῳ πρὸ τοῦ βήματος δεισιδαιμονίας ἕνεκα στρατείας ἀπέλυσα πρὸ δώδεκα καλανδῶν Ὀκτωβρίων Λευκίω Λέντλω Γαΐω Μαρκέλλω ὑπάτοις."},{"number":229,"text":"παρῆσαν Τίτος Ἄμπιος Τίτου υἱὸς Βάλβος Ὁρατία πρεσβευτής, Τίτος Τόνγιος Τίτου υἱὸς Κροστομίνα, Κόιντος Καίσιος Κοΐντου, Τίτος Πομπήιος Τίτου Λογγῖνος, Γάιος Σερουίλιος Γαΐου υἱὸς Τηρητίνα Βράκκος χιλίαρχος, Πόπλιος Κλούσιος Ποπλίου Ἐτωρία Γάλλος, Γάιος Σέντιος Γαΐου υἱὸς Σαβατίνα."},{"number":230,"text":"Τίτος Ἄμπιος Τίτου υἱὸς Βάλβος πρεσβευτὴς καὶ ἀντιστράτηγος Ἐφεσίων ἄρχουσι βουλῇ δήμῳ χαίρειν. Ἰουδαίους τοὺς ἐν τῇ Ἀσίᾳ Λεύκιος Λέντλος ὁ ὕπατος ἐμοῦ ἐντυχόντος ἀπέλυσεν τῆς στρατείας. αἰτησάμενος δὲ μετὰ ταῦτα καὶ παρὰ Φαννίου τοῦ ἀντιστρατήγου καὶ παρὰ Λευκίου Ἀντωνίου τοῦ ἀντιταμίου ἐπέτυχον ὑμᾶς τε βούλομαι φροντίσαι, ἵνα μή τις αὐτοῖς διενοχλῇ."},{"number":231,"text":"Ψήφισμα Δηλίων. ἐπʼ ἄρχοντος Βοιωτοῦ μηνὸς Θαργηλιῶνος εἰκοστῇ χρηματισμὸς στρατηγῶν. Μᾶρκος Πείσων πρεσβευτὴς ἐνδημῶν ἐν τῇ πόλει ἡμῶν ὁ καὶ τεταγμένος ἐπὶ τῆς στρατολογίας προσκαλεσάμενος ἡμᾶς καὶ ἱκανοὺς τῶν πολιτῶν προσέταξεν,"},{"number":232,"text":"ἵνα εἴ τινές εἰσιν Ἰουδαῖοι πολῖται Ῥωμαίων τούτοις μηδεὶς ἐνοχλῇ περὶ στρατείας, διὰ τὸ τὸν ὕπατον Λούκιον Κορνήλιον Λέντλον δεισιδαιμονίας ἕνεκα ἀπολελυκέναι τοὺς Ἰουδαίους τῆς στρατείας. διὸ πείθεσθαι ἡμᾶς δεῖ τῷ στρατηγῷ. ὅμοια δὲ τούτοις καὶ Σαρδιανοὶ περὶ ἡμῶν ἐψηφίσαντο."},{"number":233,"text":"Γάιος Φάννιος Γαΐου υἱὸς στρατηγὸς ὕπατος Κῴων ἄρχουσι χαίρειν. βούλομαι ὑμᾶς εἰδέναι, ὅτι πρέσβεις Ἰουδαίων μοι προσῆλθον ἀξιοῦντες λαβεῖν τὰ συγκλήτου δόγματα τὰ περὶ αὐτῶν γεγονότα. ὑποτέτακται δὲ τὰ δεδογμένα. ὑμᾶς οὖν θέλω φροντίσαι καὶ προνοῆσαι τῶν ἀνθρώπων κατὰ τὸ τῆς συγκλήτου δόγμα, ὅπως διὰ τῆς ὑμετέρας χώρας εἰς τὴν οἰκείαν ἀσφαλῶς ἀνακομισθῶσιν."},{"number":234,"text":"Λεύκιος Λέντλος ὕπατος λέγει· πολίτας Ῥωμαίων Ἰουδαίους, οἵτινές μοι ἱερὰ ἔχειν καὶ ποιεῖν Ἰουδαϊκὰ ἐν Ἐφέσῳ ἐδόκουν, δεισιδαιμονίας ἕνεκα ἀπέλυσα. τοῦτο ἐγένετο πρὸ δώδεκα καλανδῶν Κουιντιλίων."},{"number":235,"text":"Λούκιος Ἀντώνιος Μάρκου υἱὸς ἀντιταμίας καὶ ἀντιστράτηγος Σαρδιανῶν ἄρχουσι βουλῇ δήμῳ χαίρειν. Ἰουδαῖοι πολῖται ἡμέτεροι προσελθόντες μοι ἐπέδειξαν αὐτοὺς σύνοδον ἔχειν ἰδίαν κατὰ τοὺς πατρίους νόμους ἀπʼ ἀρχῆς καὶ τόπον ἴδιον, ἐν ᾧ τά τε πράγματα καὶ τὰς πρὸς ἀλλήλους ἀντιλογίας κρίνουσιν, τοῦτό τε αἰτησαμένοις ἵνʼ ἐξῇ ποιεῖν αὐτοῖς τηρῆσαι καὶ ἐπιτρέψαι ἔκρινα."},{"number":236,"text":"Μᾶρκος Πόπλιος σπιρίου υἱὸς καὶ Μᾶρκος Μάρκου Ποπλίου υἱὸς Λουκίου λέγουσιν. Λέντλῳ τἀνθυπάτῳ προσελθόντες ἐδιδάξαμεν αὐτὸν περὶ ὧν Δοσίθεος Κλεοπατρίδου Ἀλεξανδρεὺς λόγους ἐποιήσατο,"},{"number":237,"text":"ὅπως πολίτας Ῥωμαίων Ἰουδαίους ἱερὰ Ἰουδαϊκὰ ποιεῖν εἰωθότας, ἂν αὐτῷ φανῇ, δεισιδαιμονίας ἕνεκα ἀπολύσῃ· καὶ ἀπέλυσε πρὸ δώδεκα καλανδῶν Κουιντιλίων Λευκίω Λέντλω Γαΐω Μαρκέλλω ὑπάτοις."},{"number":238,"text":"παρῆσαν Τίτος Ἄμπιος Τίτου υἱὸς Βάλβος Ὁρατία πρεσβευτής, Τίτος Τόνγιος Κροστομίνα, Κόιντος Καίσιος Κοΐντου, Τίτος Πήιος Τίτου υἱὸς Κορνηλία Λογγῖνος, Γάιος Σερουίλιος Γαΐου Τηρητείνα Βρόκχος χιλίαρχος, Πόπλιος Κλούσιος Ποπλίου υἱὸς Ἐτωρία Γάλλος,"},{"number":239,"text":"Γάιος Τεύτιος Γαΐου Αἰμιλία χιλίαρχος, Σέξστος Ἀτίλιος Σέξστου υἱὸς Αἰμιλία Σέσρανος, Γάιος Πομπήιος Γαΐου υἱὸς Σαβατίνα, Τίτος Ἄμπιος Τίτου Μένανδρος, Πόπλιος Σερουίλιος Ποπλίου υἱὸς Στράβων, Λεύκιος Πάκκιος Λευκίου Κολλίνα Καπίτων, Αὖλος Φούριος Αὔλου υἱὸς Τέρτιος, Ἄππιος Μηνᾶς."},{"number":240,"text":"ἐπὶ τούτων ὁ Λέντλος δόγμα ἐξέθετο· πολίτας Ῥωμαίων Ἰουδαίους, οἵτινες ἱερὰ Ἰουδαϊκὰ ποιεῖν εἰώθασιν, ἐν Ἐφέσῳ πρὸ τοῦ βήματος δεισιδαιμονίας ἕνεκα ἀπέλυσα."},{"number":241,"text":"Λαοδικέων ἄρχοντες Γαΐῳ Ῥαβελλίῳ Γαΐου υἱῷ ὑπάτῳ χαίρειν. Σώπατρος Ὑρκανοῦ τοῦ ἀρχιερέως πρεσβευτὴς ἀπέδωκεν ἡμῖν τὴν παρὰ σοῦ ἐπιστολήν, διʼ ἧς ἐδήλου ἡμῖν παρὰ Ὑρκανοῦ τοῦ Ἰουδαίων ἀρχιερέως ἐληλυθότας τινὰς γράμματα κομίσαι περὶ τοῦ ἔθνους αὐτῶν γεγραμμένα,"},{"number":242,"text":"ἵνα τά τε σάββατα αὐτοῖς ἐξῇ ἄγειν καὶ τὰ λοιπὰ ἱερὰ ἐπιτελεῖν κατὰ τοὺς πατρίους νόμους, ὅπως τε μηδεὶς αὐτοῖς ἐπιτάσσῃ διὰ τὸ φίλους αὐτοὺς ἡμετέρους εἶναι καὶ συμμάχους, ἀδικήσῃ τε μηδὲ εἷς αὐτοὺς ἐν τῇ ἡμετέρᾳ ἐπαρχίᾳ, ὡς Τραλλιανῶν τε ἀντειπόντων κατὰ πρόσωπον μὴ ἀρέσκεσθαι τοῖς περὶ αὐτῶν δεδογμένοις ἐπέταξας ταῦτα οὕτως γίνεσθαι· παρακεκλῆσθαι δέ σε, ὥστε καὶ ἡμῖν γράψαι περὶ αὐτῶν."},{"number":243,"text":"ἡμεῖς οὖν κατακολουθοῦντες τοῖς ἐπεσταλμένοις ὑπὸ σοῦ τήν τε ἐπιστολὴν τὴν ἀποδοθεῖσαν ἐδεξάμεθα καὶ κατεχωρίσαμεν εἰς τὰ δημόσια ἡμῶν γράμματα καὶ περὶ τῶν ἄλλων ὧν ἐπέσταλκας προνοήσομεν, ὥστε μηδὲν μεμφθῆναι."},{"number":244,"text":"Πόπλιος Σερουίλιος Ποπλίου υἱὸς Γάλβας ἀνθύπατος Μιλησίων ἄρχουσι βουλῇ δήμῳ χαίρειν."},{"number":245,"text":"Πρύτανις Ἑρμοῦ υἱὸς πολίτης ὑμέτερος προσελθών μοι ἐν Τράλλεσιν ἄγοντι τὴν ἀγόραιον ἐδήλου παρὰ τὴν ἡμετέραν γνώμην Ἰουδαίοις ὑμᾶς προσφέρεσθαι καὶ κωλύειν αὐτοὺς τά τε σάββατα ἄγειν καὶ τὰ ἱερὰ τὰ πάτρια τελεῖν καὶ τοὺς καρποὺς μεταχειρίζεσθαι, καθὼς ἔθος ἐστὶν αὐτοῖς, αὐτόν τε κατὰ τοὺς νόμους εὐθυνκέναι τὸ δίκαιον ψήφισμα."},{"number":246,"text":"βούλομαι οὖν ὑμᾶς εἰδέναι, ὅτι διακούσας ἐγὼ λόγων ἐξ ἀντικαταστάσεως γενομένων ἐπέκρινα μὴ κωλύεσθαι Ἰουδαίους τοῖς αὐτῶν ἔθεσι χρῆσθαι."},{"number":247,"text":"Ψήφισμα Περγαμηνῶν. ἐπὶ πρυτάνεως Κρατίππου μηνὸς Δαισίου πρώτῃ γνώμη στρατηγῶν. ἐπεὶ Ῥωμαῖοι κατακολουθοῦντες τῇ τῶν προγόνων ἀγωγῇ τοὺς ὑπὲρ τῆς κοινῆς ἁπάντων ἀνθρώπων ἀσφαλείας κινδύνους ἀναδέχονται καὶ φιλοτιμοῦνται τοὺς συμμάχους καὶ φίλους ἐν εὐδαιμονίᾳ καὶ βεβαίᾳ καταστῆσαι εἰρήνῃ,"},{"number":248,"text":"πέμψαντος πρὸς αὐτοὺς τοῦ ἔθνους τοῦ Ἰουδαίων καὶ Ὑρκανοῦ τοῦ ἀρχιερέως αὐτῶν πρέσβεις Στράτωνα Θεοδότου Ἀπολλώνιον Ἀλεξάνδρου Αἰνείαν Ἀντιπάτρου Ἀριστόβουλον Ἀμύντου Σωσίπατρον Φιλίππου ἄνδρας καλοὺς καὶ ἀγαθούς,"},{"number":249,"text":"καὶ περὶ τῶν κατὰ μέρη ἐμφανισάντων ἐδογμάτισεν ἡ σύγκλητος περὶ ὧν ἐποιήσαντο τοὺς λόγους, ὅπως μηδὲν ἀδικῇ Ἀντίοχος ὁ βασιλεὺς Ἀντιόχου υἱὸς Ἰουδαίους συμμάχους Ῥωμαίων, ὅπως τε φρούρια καὶ λιμένας καὶ χώραν καὶ εἴ τι ἄλλο ἀφείλετο αὐτῶν ἀποδοθῇ καὶ ἐξῇ αὐτοῖς ἐκ τῶν λιμένων μηδʼ ἐξαγαγεῖν,"},{"number":250,"text":"ἵνα τε μηδεὶς ἀτελὴς ᾖ ἐκ τῆς Ἰουδαίων χώρας ἢ τῶν λιμένων αὐτῶν ἐξάγων βασιλεὺς ἢ δῆμος ἢ μόνος Πτολεμαῖος ὁ Ἀλεξανδρέων βασιλεὺς διὰ τὸ εἶναι σύμμαχος ἡμέτερος καὶ φίλος, καὶ τὴν ἐν Ἰόππῃ φρουρὰν ἐκβαλεῖν, καθὼς ἐδεήθησαν·"},{"number":251,"text":"τῆς βουλῆς ἡμῶν Λούκιος Πέττιος ἀνὴρ καλὸς καὶ ἀγαθὸς προσέταξεν, ἵνα φροντίσωμεν ταῦτα οὕτως γενέσθαι, καθὼς ἡ σύγκλητος ἐδογμάτισεν, προνοῆσαί τε τῆς ἀσφαλοῦς εἰς οἶκον τῶν πρεσβευτῶν ἀνακομιδῆς."},{"number":252,"text":"ἀπεδεξάμεθα δὲ καὶ ἐπὶ τὴν βουλὴν καὶ τὴν ἐκκλησίαν τὸν Θεόδωρον, ἀπολαβόντες δὲ τὴν ἐπιστολὴν παρʼ αὐτοῦ καὶ τὸ τῆς συγκλήτου δόγμα, καὶ ποιησαμένου μετὰ πολλῆς σπουδῆς τοὺς λόγους καὶ τὴν Ὑρκανοῦ ἐμφανίσαντος ἀρετὴν καὶ μεγαλοψυχίαν,"},{"number":253,"text":"καὶ ὅτι κοινῇ πάντας εὐεργετεῖ καὶ κατʼ ἰδίαν τοὺς πρὸς αὐτὸν ἀφικομένους, τά τε γράμματα εἰς τὰ δημόσια ἡμῶν ἀπεθέμεθα καὶ αὐτοὶ πάντα ποιεῖν ὑπὲρ Ἰουδαίων σύμμαχοι ὄντες Ῥωμαίων κατὰ τὸ τῆς συγκλήτου δόγμα ἐψηφισάμεθα."},{"number":254,"text":"ἐδεήθη δὲ καὶ Θεόδωρος τὴν ἐπιστολὴν ἡμῖν ἀποδοὺς τῶν ἡμετέρων στρατηγῶν, ἵνα πέμψωσι πρὸς Ὑρκανὸν τὸ ἀντίγραφον τοῦ ψηφίσματος καὶ πρέσβεις δηλώσοντας τὴν τοῦ ἡμετέρου δήμου σπουδὴν καὶ παρακαλέσοντας συντηρεῖν τε καὶ αὔξειν αὐτὸν τὴν πρὸς ἡμᾶς φιλίαν καὶ ἀγαθοῦ τινος αἴτιον γίνεσθαι,"},{"number":255,"text":"ὡς ἀμοιβάς τε τὰς προσηκούσας ἀποληψόμενον μεμνημένον τε ὡς καὶ ἐν τοῖς κατὰ Ἄβραμον καιροῖς, ὃς ἦν πάντων Ἑβραίων πατήρ, οἱ πρόγονοι ἡμῶν ἦσαν αὐτοῖς φίλοι, καθὼς καὶ ἐν τοῖς δημοσίοις εὑρίσκομεν γράμμασιν."},{"number":256,"text":"Ψήφισμα Ἁλικαρνασέων. ἐπὶ ἱερέως Μέμνονος τοῦ Ἀριστείδου, κατὰ δὲ ποίησιν Εὐωνύμου, Ἀνθεστηριῶνος ἔδοξε τῷ δήμῳ εἰσηγησαμένου Μάρκου Ἀλεξάνδρου."},{"number":257,"text":"ἐπεὶ τὸ πρὸς τὸ θεῖον εὐσεβές τε καὶ ὅσιον ἐν ἅπαντι καιρῷ διὰ σπουδῆς ἔχομεν κατακολουθοῦντες τῷ δήμῳ τῶν Ῥωμαίων πάντων ἀνθρώπων ὄντι εὐεργέτῃ καὶ οἷς περὶ τῆς Ἰουδαίων φιλίας καὶ συμμαχίας πρὸς τὴν πόλιν ἔγραψεν, ὅπως συντελῶνται αὐτοῖς αἱ εἰς τὸν θεὸν ἱεροποιίαι καὶ ἑορταὶ αἱ εἰθισμέναι καὶ σύνοδοι,"},{"number":258,"text":"δεδόχθαι καὶ ἡμῖν Ἰουδαίων τοὺς βουλομένους ἄνδρας τε καὶ γυναῖκας τά τε σάββατα ἄγειν καὶ τὰ ἱερὰ συντελεῖν κατὰ τοὺς Ἰουδαίων νόμους καὶ τὰς προσευχὰς ποιεῖσθαι πρὸς τῇ θαλάττῃ κατὰ τὸ πάτριον ἔθος. ἂν δέ τις κωλύσῃ ἢ ἄρχων ἢ ἰδιώτης, τῷδε τῷ ζημιώματι ὑπεύθυνος ἔστω καὶ ὀφειλέτω τῇ πόλει."},{"number":259,"text":"Ψήφισμα Σαρδιανῶν. ἔδοξε τῇ βουλῇ καὶ τῷ δήμῳ στρατηγῶν εἰσηγησαμένων. ἐπεὶ οἱ κατοικοῦντες ἡμῶν ἐν τῇ πόλει ἀπʼ ἀρχῆς Ἰουδαῖοι πολῖται πολλὰ καὶ μεγάλα φιλάνθρωπα ἐσχηκότες διὰ παντὸς παρὰ τοῦ δήμου καὶ νῦν εἰσελθόντες ἐπὶ τὴν βουλὴν καὶ τὸν δῆμον παρεκάλεσαν,"},{"number":260,"text":"ἀποκαθισταμένων αὐτοῖς τῶν νόμων καὶ τῆς ἐλευθερίας ὑπὸ τῆς συγκλήτου καὶ τοῦ δήμου τοῦ Ῥωμαίων ἵνα κατὰ τὰ νομιζόμενα ἔθη συνάγωνται καὶ πολιτεύωνται καὶ διαδικάζωνται πρὸς αὑτούς, δοθῇ τε καὶ τόπος αὐτοῖς, εἰς ὃν συλλεγόμενοι μετὰ γυναικῶν καὶ τέκνων ἐπιτελοῦσιν τὰς πατρίους εὐχὰς καὶ θυσίας τῷ θεῷ·"},{"number":261,"text":"δεδόχθαι τῇ βουλῇ καὶ τῷ δήμῳ συγκεχωρῆσθαι αὐτοῖς συνερχομένοις ἐν ταῖς ἀποδεδειγμέναις ἡμέραις πράσσειν τὰ κατὰ τοὺς αὐτῶν νόμους, ἀφορισθῆναι δʼ αὐτοῖς καὶ τόπον ὑπὸ τῶν στρατηγῶν εἰς οἰκοδομίαν καὶ οἴκησιν αὐτῶν, ὃν ἂν ὑπολάβωσιν πρὸς τοῦτʼ ἐπιτήδειον εἶναι, ὅπως τε τοῖς τῆς πόλεως ἀγορανόμοις ἐπιμελὲς ᾖ καὶ τὰ ἐκείνοις πρὸς τροφὴν ἐπιτήδεια ποιεῖν εἰσάγεσθαι."},{"number":262,"text":"Ψήφισμα Ἐφεσίων. ἐπὶ πρυτάνεως Μηνοφίλου μηνὸς Ἀρτεμισίου τῇ προτέρᾳ ἔδοξε τῷ δήμῳ, Νικάνωρ Εὐφήμου εἶπεν εἰσηγησαμένων τῶν στρατηγῶν."},{"number":263,"text":"ἐπεὶ ἐντυχόντων τῶν ἐν τῇ πόλει Ἰουδαίων Μάρκῳ Ἰουλίῳ Ποντίου υἱῷ Βρούτῳ ἀνθυπάτῳ, ὅπως ἄγωσι τὰ σάββατα καὶ πάντα ποιῶσιν κατὰ τὰ πάτρια αὐτῶν ἔθη μηδενὸς αὐτοῖς ἐμποδὼν γινομένου,"},{"number":264,"text":"ὁ στρατηγὸς συνεχώρησεν, δεδόχθαι τῷ δήμῳ, τοῦ πράγματος Ῥωμαίοις ἀνήκοντος, μηδένα κωλύεσθαι παρατηρεῖν τὴν τῶν σαββάτων ἡμέραν μηδὲ πράττεσθαι ἐπιτίμιον, ἐπιτετράφθαι δʼ αὐτοῖς πάντα ποιεῖν κατὰ τοὺς ἰδίους αὐτῶν νόμους."},{"number":265,"text":"Πολλὰ μὲν οὖν ἐστιν καὶ ἄλλα τοιαῦτα τῇ συγκλήτῳ καὶ τοῖς αὐτοκράτορσι τοῖς Ῥωμαίων δόγματα πρὸς Ὑρκανὸν καὶ τὸ ἔθνος ἡμῶν γεγενημένα καὶ πόλεσιν ψηφίσματα καὶ γράμματα πρὸς τὰς περὶ τῶν ἡμετέρων δικαίων ἐπιστολὰς ἀντιπεφωνημένα τοῖς ἡγεμόσιν, περὶ ὧν ἁπάντων ἐξ ὧν παρατεθείμεθα πιστεύειν τοῖς ἀναγνωσομένοις οὐ βασκάνως ἡμῶν τὴν γραφὴν πάρεστιν."},{"number":266,"text":"ἐπεὶ γὰρ ἐναργῆ καὶ βλεπόμενα τεκμήρια παρεχόμεθα τῆς πρὸς Ῥωμαίους ἡμῖν φιλίας γενομένης ἐπιδεικνύντες αὐτὰ χαλκαῖς στήλαις καὶ δέλτοις ἐν τῷ Καπετωλίῳ μέχρι νῦν διαμένοντα καὶ διαμενοῦντα, τὴν μὲν πάντων παράθεσιν ὡς περιττήν τε ἅμα καὶ ἀτερπῆ παρῃτησάμην,"},{"number":267,"text":"οὐδένα δʼ οὕτως ἡγησάμην σκαιόν, ὃς οὐχὶ καὶ περὶ τῆς Ῥωμαίων ἡμῖν πιστεύσει φιλανθρωπίας, ὅτι ταύτην καὶ διὰ πλειόνων ἐπεδείξαντο πρὸς ἡμᾶς δογμάτων, καὶ ἡμᾶς οὐχ ὑπολήψεται περὶ ὧν εἶναί φαμεν ἀληθεύειν ἐξ ὧν ἐπεδείξαμεν. τὴν μὲν οὖν πρὸς Ῥωμαίους φιλίαν καὶ συμμαχίαν κατʼ ἐκείνους τοὺς καιροὺς γενομένην δεδηλώκαμεν."}],"11":[{"number":268,"text":"Συνέβη δʼ ὑπὸ τὸν αὐτὸν καιρὸν ταραχθῆναι τὰ κατὰ τὴν Συρίαν ἐξ αἰτίας τοιαύτης· Βάσσος Καικίλιος εἷς τῶν τὰ Πομπηίου φρονούντων ἐπιβουλὴν συνθεὶς ἐπὶ Σέξστον Καίσαρα κτείνει μὲν ἐκεῖνον, αὐτὸς δὲ τὸ στράτευμα αὐτοῦ παραλαβὼν ἐκράτει τῶν πραγμάτων, πόλεμός τε μέγας περὶ τὴν Ἀπάμειαν συνέστη τῶν Καίσαρος στρατηγῶν ἐπʼ αὐτὸν ἐλθόντων μετά τε ἱππέων καὶ πεζῆς δυνάμεως."},{"number":269,"text":"τούτοις δὲ καὶ Ἀντίπατρος συμμαχίαν ἔπεμψεν μετὰ τῶν τέκνων κατὰ μνήμην ὧν εὐεργετήθησαν ὑπὸ Καίσαρος καὶ διὰ τοῦτο τιμωρεῖν αὐτῷ καὶ δίκην παρὰ τοῦ πεφονευκότος εἰσπράξασθαι δίκαιον ἡγούμενος."},{"number":270,"text":"χρονιζομένου δὲ τοῦ πολέμου Μοῦρκος μὲν ἦλθεν ἐκ Ῥώμης εἰς τὴν ἀρχὴν τὴν Σέξστου, Καῖσαρ δʼ ὑπὸ τῶν περὶ Κάσσιον καὶ Βροῦτον ἐν τῷ βουλευτηρίῳ κτείνεται κατασχὼν τὴν ἀρχὴν ἔτη τρία καὶ μῆνας ἕξ. τοῦτο μὲν οὖν καὶ ἐν ἄλλοις δεδήλωται."},{"number":271,"text":"Τοῦ δʼ ἐπὶ τῷ Καίσαρος θανάτῳ πολέμου συνερρωγότος καὶ τῶν ἐν τέλει πάντων ἐπὶ στρατιᾶς συλλογὴν ἄλλου ἄλλῃ διεσπαρμένων, ἀφικνεῖται Κάσσιος εἰς Συρίαν παραληψόμενος τὰ περὶ τὴν Ἀπάμειαν στρατόπεδα·"},{"number":272,"text":"καὶ λύσας τὴν πολιορκίαν ἀμφοτέρους προσάγεται τόν τε Βάσσον καὶ τὸν Μοῦρκον τάς τε πόλεις ἐπερχόμενος ὅπλα τε καὶ στρατιώτας συνήθροιζεν καὶ φόρους αὐταῖς μεγάλους ἐπετίθει· μάλιστα δὲ τὴν Ἰουδαίαν ἐκάκωσεν ἑπτακόσια τάλαντα ἀργυρίου πραττόμενος."},{"number":273,"text":"Ἀντίπατρος δʼ ὁρῶν ἐν μεγάλῳ φόβῳ καὶ ταραχῇ τὰ πράγματα μερίζει τὴν τῶν χρημάτων εἴσπραξιν καὶ ἑκατέρῳ τῶν υἱῶν συνάγειν δίδωσιν τὰ μὲν Μαλίχῳ κακοήθως πρὸς αὐτὸν διακειμένῳ, τὰ δὲ ἄλλοις προσέταξεν εἰσπράττεσθαι."},{"number":274,"text":"καὶ πρῶτος Ἡρώδης ἀπὸ τῆς Γαλιλαίας εἰσπραξάμενος ὅσα ἦν αὐτῷ προστεταγμένα φίλος ἦν εἰς τὰ μάλιστα Κασσίῳ· σῶφρον γὰρ ἔδοξεν αὐτῷ Ῥωμαίους ἤδη θεραπεύειν καὶ τὴν παρʼ αὐτῶν κατασκευάζειν εὔνοιαν ἐκ τῶν ἀλλοτρίων πόνων."},{"number":275,"text":"ἐπιπράσκοντο δʼ αὔτανδροι οἱ τῶν ἄλλων πόλεων ἐπιμεληταί, καὶ τέσσαρας πόλεις ἐξηνδραπόδισε τότε Κάσσιος, ὧν ἦσαν αἱ δυνατώταται Γόφνα τε καὶ Ἀμμαοῦς, πρὸς ταύταις δὲ Λύδδα καὶ Θάμνα."},{"number":276,"text":"ἐπεξῆλθε δʼ ἂν ὑπʼ ὀργῆς Κάσσιος ὥστε καὶ Μάλιχον ἀνελεῖν, ὥρμητο γὰρ ἐπʼ αὐτόν, εἰ μὴ Ὑρκανὸς διʼ Ἀντιπάτρου ἑκατὸν τάλαντα ἐκ τῶν ἰδίων αὐτῷ πέμψας ἐπέσχε τῆς ὁρμῆς."},{"number":277,"text":"Ἐπεὶ δὲ Κάσσιος ἐκ τῆς Ἰουδαίας ἀπῆρεν, Μάλιχος ἐπεβούλευσεν Ἀντιπάτρῳ τὴν τούτου τελευτὴν ἀσφάλειαν Ὑρκανοῦ τῆς ἀρχῆς εἶναι νομίζων. οὐ μὴν ἔλαθεν τὸν Ἀντίπατρον ταῦτα φρονῶν, ἀλλʼ αἰσθόμενος γὰρ ἐκεῖνος ἐχώρει πέραν Ἰορδάνου καὶ στρατὸν Ἀράβιον ἅμα καὶ ἐγχώριον συνήθροιζεν."},{"number":278,"text":"δεινὸς δὲ ὢν ὁ Μάλιχος ἠρνεῖτο μὲν τὴν ἐπιβουλήν, ἀπολογούμενος δὲ μεθʼ ὅρκων αὐτῷ τε καὶ τοῖς παισίν, καὶ ὡς Φασαήλου μὲν Ἱεροσόλυμα φρουροῦντος, Ἡρώδου δὲ ἔχοντος τὴν φυλακὴν τῶν ὅπλων οὐδʼ ἂν εἰς νοῦν ἐβάλετο τοιοῦτον οὐδὲν ὁρῶν τὴν ἀπορίαν, καταλλάσσεται πρὸς τὸν Ἀντίπατρον,"},{"number":279,"text":"καὶ συνέβησαν Μούρκου κατὰ Συρίαν στρατηγοῦντος, ὃς αἰσθόμενος νεωτεροποιοῦντα τὰ κατὰ τὴν Ἰουδαίαν τὸν Μάλιχον ἦλθε μὲν ὡς παρὰ μικρὸν αὐτὸν ἀνελεῖν, Ἀντιπάτρου δὲ παρακαλέσαντος περιέσωσεν."},{"number":280,"text":"Ἦν δὲ ἄρα φονέα περισώσας Ἀντίπατρος αὐτοῦ τὸν Μάλιχον· Κάσσιος μὲν γὰρ καὶ Μοῦρκος στρατὸν ἀθροίζοντες τὴν ἐπιμέλειαν ἅπασαν ἐνεχείρισαν Ἡρώδῃ καὶ στρατηγὸν αὐτὸν κοίλης Συρίας ἐποίησαν πλοῖα δόντες καὶ δύναμιν ἱππικήν τε καὶ πεζικήν, ὑποσχόμενοί τε καὶ βασιλέα τῆς Ἰουδαίας ἀναδείξειν μετὰ τὸν πόλεμον· συνειστήκει γὰρ τότε πρός τε Ἀντώνιον καὶ τὸν νέον Καίσαρα."},{"number":281,"text":"Μάλιχος δὲ δείσας τότε μάλιστα τὸν Ἀντίπατρον ἐκποδὼν ἐποιεῖτο, καὶ πείσας ἀργυρίῳ τὸν Ὑρκανοῦ οἰνοχόον, παρʼ ᾧ ἑκάτεροι εἱστιῶντο, φαρμάκῳ κτείνει τὸν ἄνδρα, καὶ ὁπλίτας ἔχων εὐτρέπιζεν τὰ κατὰ τὴν πόλιν."},{"number":282,"text":"γνόντων δὲ τὴν ἐπιβουλὴν τὴν κατὰ τοῦ πατρὸς Ἡρώδου καὶ Φασαήλου καὶ χαλεπῶς ἐχόντων, ἠρνεῖτο πάλιν ὁ Μάλιχος καὶ ἔξαρνος ἦν τοῦ φόνου."},{"number":283,"text":"καὶ Ἀντίπατρος μὲν εὐσεβείᾳ τε καὶ δικαιοσύνῃ διενεγκὼν καὶ τῇ περὶ τὴν πατρίδα σπουδῇ τοῦτον ἐτελεύτησεν τὸν τρόπον. τῶν δὲ παίδων αὐτοῦ Ἡρώδης μὲν εὐθὺς ἔγνω τιμωρεῖν τῷ πατρὶ μετὰ στρατιᾶς ἐπὶ Μάλιχον ἐλθών. Φασαήλῳ δὲ τῷ πρεσβυτέρῳ δόλῳ μᾶλλον ἐδόκει περιγίνεσθαι τἀνδρός, μὴ πολέμου κατάρχειν νομισθῶσιν ἐμφυλίου."},{"number":284,"text":"τήν τε οὖν ἀπολογίαν τὴν Μαλίχου προσδέχεται καὶ πιστεύειν ὑποκρίνεται μηδὲν αὐτὸν περὶ τὸν Ἀντιπάτρου θάνατον κακουργῆσαι, τάφον τε ἐκόσμει τῷ πατρί. καὶ παραγενόμενος Ἡρώδης εἰς Σαμάρειαν καὶ καταλαβὼν αὐτὴν κεκακωμένην ἀνεκτᾶτο καὶ τὰ νείκη διέλυε τοῖς ἀνθρώποις."},{"number":285,"text":"Μετʼ οὐ πολὺ δʼ ἐνστάσης τῆς ἐν Ἱεροσολύμοις ἑορτῆς παρεγίνετο σὺν τοῖς στρατιώταις εἰς τὴν πόλιν, καὶ δείσας ὁ Μάλιχος ἀνέπεισεν Ὑρκανὸν μὴ ἐπιτρέπειν αὐτῷ εἰσιέναι. καὶ πείθεται μὲν Ὑρκανός, προβέβλητο δὲ αἰτίαν τῆς ἀποκωλύσεως τὸ μὴ δεῖν ὄχλον ἀλλοδαπὸν ἁγνεύοντος εἰσδέχεσθαι τοῦ πλήθους."},{"number":286,"text":"ὀλίγον δὲ φροντίσας Ἡρώδης τῶν ἀγγέλων νύκτωρ εἴσεισιν εἰς τὴν πόλιν καὶ φοβερὸς ἦν τῷ Μαλίχῳ, ὁ δʼ οὐκ ἀνίησιν τὴν ὑπόκρισιν, ἀλλʼ ἐδάκρυεν τὸν Ἀντίπατρον καὶ ἀνεκαλεῖτο φανερῶς ὡς φίλος, κρύφα δὲ φυλακὴν τοῦ σώματος ἐποιεῖτο."},{"number":287,"text":"ἔδοξε δὲ καὶ τοῖς περὶ Ἡρώδην μὴ ἀπελέγχειν αὐτοῦ τὴν προσποίησιν, ἀλλὰ καὶ αὐτοὺς εἰς τὸ ἀνύποπτον ἀντιφιλοφρονεῖσθαι τὸν Μάλιχον."},{"number":288,"text":"Κασσίῳ μέντοι περὶ τῆς τελευτῆς τοῦ πατρὸς Ἡρώδης ἐπέστελλεν, κἀκεῖνος εἰδώς, οἷος εἴη τὸν τρόπον Μάλιχος, ἀντεπιστέλλει τιμωρεῖν τῷ πατρί, καὶ λάθρα διαπέμπει πρὸς τοὺς ἐν Τύρῳ χιλιάρχους κελεύων αὐτοὺς συμπράττειν Ἡρώδῃ δίκαια μέλλοντι πράξειν."},{"number":289,"text":"ὡς δὲ Λαοδίκειαν ᾑρηκότος Κασσίου πρὸς αὐτὸν ἀπῄεσαν κοινῇ στεφάνους τε αὐτῷ καὶ χρήματα κομίζοντες, Ἡρώδης μὲν προσεδόκα δώσειν τὸν Μάλιχον τιμωρίαν ἐκεῖ γενόμενον,"},{"number":290,"text":"ὁ δὲ περὶ Τύρον τῆς Φοινίκης ὑπιδόμενος τὸ πρᾶγμα μειζόνων ἐφήπτετο, καὶ τοῦ παιδὸς αὐτῷ ὁμηρεύοντος ἐν Τύρῳ παρελθὼν εἰς τὴν πόλιν ἔγνω τοῦτόν τε ὑπεκκλέψαι καὶ εἰς τὴν Ἰουδαίαν ἀπαίρειν σπεύδοντος ἐπʼ Ἀντώνιον Κασσίου τό τε ἔθνος ἀποστήσας αὐτὸς τὴν ἀρχὴν κατέχειν."},{"number":291,"text":"τοῖς δὲ βεβουλευμένοις ὅ τε δαίμων ἀντέπραξεν καὶ δεινὸς ὢν Ἡρώδης τὴν προαίρεσιν αὐτοῦ κατανοῆσαι, ὃς προεισπέμψας θεράποντα τῷ μὲν δοκεῖν ἐπὶ δείπνου παρασκευήν, καὶ γὰρ ἑστιάσειν αὐτοὺς ἅπαντας προειρήκει, ταῖς δʼ ἀληθείαις πρὸς τοὺς χιλιάρχους, ἐξελθεῖν ἐπὶ Μάλιχον πείθει μετὰ ξιφιδίων."},{"number":292,"text":"οἱ δʼ ἐπεξελθόντες καὶ πλησίον τῆς πόλεως αὐτῷ περιτυχόντες ἐπὶ τοῦ αἰγιαλοῦ κατακεντοῦσι τὸν ἄνδρα. Ὑρκανὸς μὲν οὖν ὑπʼ ἐκπλήξεως τοῦ γεγονότος εἰς ἀφωνίαν ἐτράπη, μόλις δʼ ἀνενεγκὼν ἐπυνθάνετο τῶν περὶ Ἡρώδην, ὅ τι ποτε εἴη τὸ γεγενημένον καὶ τίς ὁ Μάλιχον ἀνῃρηκώς."},{"number":293,"text":"εἰπόντων δὲ Κάσσιον τοῦτο προστάξαι, ἐπῄνεσεν τὸ ἔργον, πονηρὸν γὰρ εἶναι πάνυ καὶ τῆς πατρίδος ἐπίβουλον. καὶ Μάλιχος μὲν ταύτην ὑπὲρ τῆς εἰς Ἀντίπατρον παρανομίας δίκην ἐξέτισεν."},{"number":294,"text":"Κασσίου δʼ ἐκ Συρίας ἀπάραντος ταραχὴ γίνεται κατὰ τὴν Ἰουδαίαν· Ἔλιξ γὰρ ὑπολειφθεὶς ἐν Ἱεροσολύμοις μετὰ στρατιᾶς ὥρμησεν ἐπὶ Φασάηλον ὅ τε δῆμος ἔνοπλος ἦν."},{"number":295,"text":"Ἡρώδης δὲ παρὰ Φάβιον ἐπορεύετο ἐν Δαμασκῷ στρατηγοῦντα, καὶ βουλόμενος προσδραμεῖν πρὸς τὸν ἀδελφὸν ὑπὸ νόσου κωλύεται, ἕως οὗ Φασάηλος διʼ αὐτοῦ κρείττων Ἔλικος γενόμενος κατακλείει μὲν αὐτὸν εἰς πύργον, εἶτα δὲ ὑπόσπονδον ἀφίησιν, τόν τε Ὑρκανὸν ἐμέμφετο πολλὰ μὲν εὖ παθόντα ὑπʼ αὐτῶν συμπράττοντα δὲ τοῖς ἐχθροῖς."},{"number":296,"text":"ὁ γὰρ ἀδελφὸς Μαλίχου τότε ἀποστήσας οὐκ ὀλίγα χωρία ἐφρούρει καὶ Μάσαδαν τὸ πάντων ἐρυμνότατον. ἐπὶ μὲν οὖν τοῦτον ῥαΐσας Ἡρώδης ἐκ τῆς νόσου παραγίνεται καὶ ἀφελόμενος αὐτοῦ πάντα ὅσα εἶχεν χωρία ὑπόσπονδον ἀπέλυσεν."}],"12":[{"number":297,"text":"Ἀντίγονον δὲ τὸν Ἀριστοβούλου στρατιὰν ἀθροίσαντα καὶ Φάβιον τεθεραπευκότα χρήμασιν κατῆγεν Πτολεμαῖος ὁ Μενναίου διὰ τὸ κήδευμα. συνεμάχει δʼ αὐτῷ καὶ Μαρίων, ὃν Τυρίων καταλελοίπει τύραννον Κάσσιος· τυραννίσι γὰρ διαλαβὼν τὴν Συρίαν οὗτος ὁ ἀνὴρ ἐφρούρησεν."},{"number":298,"text":"ὁ δὲ Μαρίων καὶ εἰς τὴν Γαλιλαίαν ὅμορον οὖσαν ἐνέβαλεν καὶ τρία καταλαβὼν ἐρύματα διὰ φρουρᾶς εἶχεν. ἐλθὼν δὲ καὶ ἐπὶ τοῦτον Ἡρώδης ἅπαντα μὲν αὐτὸν ἀφείλετο, τοὺς δὲ Τυρίων φρουροὺς φιλανθρώπως ἀπέλυσεν ἔστιν οἷς καὶ δωρεὰς δοὺς διὰ τὸ πρὸς τὴν πόλιν εὔνουν."},{"number":299,"text":"ταῦτα διαπραξάμενος ὑπήντησεν Ἀντιγόνῳ καὶ μάχην αὐτῷ συνάψας νικᾷ καὶ ὅσον οὔπω τῶν ἄκρων ἐπιβάντα τῆς Ἰουδαίας ἐξέωσεν. εἰς Ἱεροσόλυμα δὲ παραγενόμενον στεφάνοις ἀνέδουν Ὑρκανός τε καὶ ὁ δῆμος."},{"number":300,"text":"ἐγεγάμβρευτο δʼ ἤδη καθʼ ὁμολογίαν τῷ Ὑρκανοῦ γένει καὶ διὰ τοῦτο μᾶλλον αὐτοῦ προειστήκει μέλλων ἄγεσθαι τὴν Ἀλεξάνδρου τοῦ Ἀριστοβούλου θυγατέρα, Ὑρκανοῦ δὲ θυγατριδῆν, ἐξ ἧς πατὴρ μὲν γίνεται τριῶν ἀρρένων, δύο δὲ θηλειῶν. ἦκτο δὲ πρότερον καὶ γυναῖκα δημότιν Δῶριν ὄνομα ἐκ τοῦ ἔθνους, ἐξ ἧς αὐτῷ πρεσβύτατος γίνεται Ἀντίπατρος."},{"number":301,"text":"Κάσσιον μὲν οὖν χειροῦνται Ἀντώνιός τε καὶ Καῖσαρ περὶ Φιλίππους, ὡς καὶ παρʼ ἄλλοις δεδήλωται. μετὰ δὲ τὴν νίκην Καῖσαρ μὲν ἐπʼ Ἰταλίας ἐχώρει, Ἀντώνιος δὲ εἰς τὴν Ἀσίαν ἀπῆρεν· γενομένῳ δὲ ἐν τῇ Βιθυνίᾳ αἱ πανταχόθεν ἀπήντων πρεσβεῖαι."},{"number":302,"text":"παρῆσαν δὲ καὶ Ἰουδαίων οἱ ἐν τέλει κατηγοροῦντες τῶν περὶ Φασάηλον καὶ Ἡρώδην, πρόσχημα μὲν εἶναι λέγοντες τῆς βασιλείας Ὑρκανόν, τούτους δὲ τὴν πᾶσαν ἔχειν ἐξουσίαν."},{"number":303,"text":"Ἡρώδην δὲ Ἀντώνιος διὰ πολλῆς εἶχε τιμῆς ἐλθόντα πρὸς αὐτὸν ἐπὶ ἀπολογίᾳ τῶν κατηγορούντων, καὶ διὰ τοῦτο συνέβη μηδὲ λόγου τυχεῖν τοὺς ἀντιστασιώτας· διεπέπρακτο δὲ τοῦτο χρήμασιν Ἡρώδης παρʼ Ἀντωνίου."},{"number":304,"text":"ἐπεὶ δʼ εἰς Ἔφεσον ἧκεν Ἀντώνιος, ἔπεμψεν Ὑρκανὸς ὁ ἀρχιερεὺς καὶ τὸ ἔθνος τὸ ἡμέτερον πρεσβείαν πρὸς αὐτὸν στέφανόν τε κομίζουσαν χρυσοῦν καὶ παρακαλοῦσαν τοὺς αἰχμαλωτισθέντας ὑπὸ Κασσίου Ἰουδαίους οὐ νόμῳ πολέμου γράψαντα τοῖς κατὰ τὰς ἐπαρχίας ἐλευθέρους ἀπολῦσαι καὶ τὴν χώραν, ἣν ἐν τοῖς Κασσίου καιροῖς ἀφῃρέθησαν, ἀποδοῦναι."},{"number":305,"text":"ταῦτα κρίνας Ἀντώνιος ἀξιοῦν δίκαια τοὺς Ἰουδαίους παραχρῆμα ἔγραψεν Ὑρκανῷ καὶ τοῖς Ἰουδαίοις, ἐπέστειλεν δὲ καὶ τοῖς Τυρίοις καὶ διάταγμα ἔπεμπε περιέχον ταῦτα."},{"number":306,"text":"Μᾶρκος Ἀντώνιος αὐτοκράτωρ Ὑρκανῷ ἀρχιερεῖ καὶ ἐθνάρχῃ καὶ τῷ Ἰουδαίων ἔθνει χαίρειν. εἰ ἔρρωσθε, εὖ ἂν ἔχοι, ἔρρωμαι δὲ καὶ αὐτὸς μετὰ τοῦ στρατεύματος."},{"number":307,"text":"Λυσίμαχος Παυσανίου καὶ Ἰώσηπος Μενναίου καὶ Ἀλέξανδρος Θεοδώρου πρεσβευταὶ ἐν Ἐφέσῳ μοι συντυχόντες τήν τε ἔμπροσθεν ἐν Ῥώμῃ τελεσθεῖσαν αὐτοῖς πρεσβείαν ἀνενεώσαντο καὶ τὴν νῦν ὑπὲρ σοῦ καὶ τοῦ ἔθνους σπουδαίως διέθεντο, ἣν ἔχεις εὔνοιαν πρὸς ἡμᾶς ἐμφανίσαντες."},{"number":308,"text":"πεπεισμένος οὖν καὶ ἐκ τῶν πραγμάτων καὶ ἐκ τῶν λόγων, ὅτι οἰκειότατα ἔχετε πρὸς ἡμᾶς, καὶ τὸ ἀραρὸς ὑμῶν ἦθος καὶ θεοσεβὲς κατανοήσας,"},{"number":309,"text":"ἴδιον ἥγημαι καταδραμόντων δὲ τὴν Ἀσίαν ἅπασαν τῶν ἐναντιωθέντων ἡμῖν τε καὶ τῷ δήμῳ τῶν Ῥωμαίων καὶ μήτε πόλεων μήτε ἡρῴων ἀποσχομένων μήτε ὅρκους οὓς ἐποιήσαντο φυλαξάντων, ἡμεῖς ὡς οὐχ ὑπὲρ ἰδίου μόνον ἀγῶνος, ἀλλʼ ὡς ὑπὲρ ἁπάντων κοινοῦ, τοὺς αἰτίους καὶ τῶν εἰς ἀνθρώπους παρανομιῶν καὶ τῶν εἰς θεοὺς ἁμαρτημάτων ἠμυνάμεθα, διʼ ἃ καὶ τὸν ἥλιον ἀπεστράφθαι δοκοῦμεν, ὃς καὶ αὐτὸς ἀηδῶς ἐπεῖδεν τὸ ἐπὶ Καίσαρι μύσος."},{"number":310,"text":"ἀλλὰ τὰς ἐπιβουλὰς αὐτῶν τὰς θεημάχους, ἃς ὑπεδέξατο ἡ Μακεδονία καθάπερ ἴδιος αὐτοῖς τῶν ἀνοσίων τολμημάτων ἀήρ, καὶ τὴν σύγχυσιν τῆς ἡμιμανοῦς κακοηθείας κατὰ Φιλίππους τῆς Μακεδονίας συνεκρότουν, καὶ τόπους εὐφυεῖς καταλαμβανόμενοι μέχρι θαλάσσης ἀποτετειχισμένους ὄρεσιν, ὡς πύλῃ μιᾷ τὴν πάροδον ταμιεύεσθαι, τῶν θεῶν αὐτοὺς ἐπὶ τοῖς ἀδίκοις ἐγχειρήμασιν κατεψηφισμένων ἐκρατήσαμεν."},{"number":311,"text":"καὶ Βροῦτος συμφυγὼν εἰς Φιλίππους καὶ συγκλεισθεὶς ὑφʼ ἡμῶν ἐκοινώνησεν Κασσίῳ τῆς ἀπωλείας. τούτων κεκολασμένων εἰρήνης τὸ λοιπὸν ἀπολαύσειν ἐλπίζομεν καὶ ἀναπεπαῦσθαι τὴν Ἀσίαν ἐκ τοῦ πολέμου."},{"number":312,"text":"κοινὴν οὖν ποιούμεθα καὶ τοῖς συμμάχοις τὴν ὑπὸ θεοῦ δοθεῖσαν ἡμῖν εἰρήνην· ὥσπερ οὖν ἐκ νόσου μεγάλης τὸ τῆς Ἀσίας σῶμα νῦν διὰ τὴν ἡμετέραν νίκην ἀναφέρειν. ἔχων τοίνυν καὶ σὲ διὰ μνήμης καὶ τὸ ἔθνος αὔξειν φροντίσω τῶν ὑμῖν συμφερόντων."},{"number":313,"text":"ἐξέθηκα δὲ καὶ γράμματα κατὰ πόλεις, ὅπως εἴ τινες ἐλεύθεροι ἢ δοῦλοι ὑπὸ δόρυ ἐπράθησαν ὑπὸ Γαΐου Κασσίου ἢ τῶν ὑπʼ αὐτῷ τεταγμένων ἀπολυθῶσιν οὗτοι, τοῖς τε ὑπʼ ἐμοῦ δοθεῖσιν καὶ Δολαβέλλα φιλανθρώποις χρῆσθαι ὑμᾶς βούλομαι. Τυρίους τε κωλύω βιαίους εἶναι περὶ ὑμᾶς καὶ ὅσα κατέχουσιν Ἰουδαίων ταῦτα ἀποκαταστῆσαι κελεύω. τὸν δὲ στέφανον ὃν ἔπεμψας ἐδεξάμην."},{"number":314,"text":"Μᾶρκος Ἀντώνιος αὐτοκράτωρ Τυρίων ἄρχουσι βουλῇ δήμῳ χαίρειν. ἐμφανισάντων μοι ἐν Ἐφέσῳ Ὑρκανοῦ τοῦ ἀρχιερέως καὶ ἐθνάρχου πρεσβευτῶν καὶ χώραν αὐτῶν ὑμᾶς κατέχειν λεγόντων, εἰς ἣν ἐνέβητε κατὰ τὴν τῶν ἐναντιουμένων ἡμῖν ἐπικράτειαν,"},{"number":315,"text":"ἐπεὶ τὸν ὑπὲρ τῆς ἡγεμονίας πόλεμον ἀνεδεξάμεθα καὶ τῶν εὐσεβῶν καὶ δικαίων ποιούμενοι πρόνοιαν ἠμυνάμεθα τοὺς μήτε χάριτος ἀπομνημονεύσαντας μήτε ὅρκους φυλάξαντας, βούλομαι καὶ τὴν ἀφʼ ὑμῶν εἰρήνην τοῖς συμμάχοις ἡμῶν ὑπάρχειν καὶ ὅσα παρὰ τῶν ἡμετέρων ἐλάβετε ἀνταγωνιστῶν μὴ συγχωρεῖν, ἀλλὰ ταῦτα ἀποδοθῆναι τοῖς ἀφῃρημένοις."},{"number":316,"text":"οὔτε γὰρ ἐπαρχίας ἐκείνων οὐθεὶς οὔτε στρατόπεδα τῆς συγκλήτου δούσης ἔλαβεν, ἀλλὰ βίᾳ καθαρπάσαντες ἐχαρίσαντο βιαίως τοῖς πρὸς ἃ ἠδίκουν χρησίμοις αὐτοῖς γινομένοις."},{"number":317,"text":"δίκην οὖν αὐτῶν δεδωκότων τούς τε συμμάχους τοὺς ἡμετέρους ὅσα ποτʼ εἶχον ἀξιοῦμεν ἀκωλύτους διακατέχειν καὶ ὑμᾶς, εἴ τινα χωρία Ὑρκανοῦ ὄντα τοῦ ἐθνάρχου Ἰουδαίων πρὸ μιᾶς ἡμέρας ἢ Γάιον Κάσσιον πόλεμον οὐ συγκεχωρημένον ἐπάγοντα ἐπιβῆναι τῆς ἐπαρχίας ἡμῶν νῦν ἔχετε, ἀποδοῦναι αὐτῷ βίαν τε αὐτοῖς μηδεμίαν προσφέρειν ἐπὶ τῷ ἀσθενεῖς αὐτοὺς ποιεῖν τῶν ἰδίων δεσπόζειν."},{"number":318,"text":"εἰ δέ τινα ἔχετε πρὸς αὐτὸν δικαιολογίαν, ὅταν ἔλθωμεν ἐπὶ τοὺς τόπους ἐξέσται ὑμῖν ταύτῃ χρήσασθαι, ἡμῶν ἕκαστα τοῖς συμμάχοις ὁμοίως τοῖς κρίμασιν φυλασσόντων."},{"number":319,"text":"Μᾶρκος Ἀντώνιος αὐτοκράτωρ Τυρίων ἄρχουσι βουλῇ δήμῳ χαίρειν. διάταγμα ἐμὸν ἀπέσταλκα πρὸς ὑμᾶς, περὶ οὗ βούλομαι ὑμᾶς φροντίσαι, ἵνα αὐτὸ εἰς τὰς δημοσίας ἐντάξητε δέλτους γράμμασι Ῥωμαϊκοῖς καὶ Ἑλληνικοῖς καὶ ἐν τῷ ἐπιφανεστάτῳ ἔχητε αὐτὸ γεγραμμένον, ὅπως ὑπὸ πάντων ἀναγινώσκεσθαι δύνηται."},{"number":320,"text":"Μᾶρκος Ἀντώνιος αὐτοκράτωρ τριῶν ἀνδρῶν καταστάντων περὶ τῶν δημοσίων πραγμάτων εἶπεν· ἐπεὶ Γάιος Κάσσιος ταύτῃ τῇ ὑποστάσει ἀλλοτρίαν ἐπαρχίαν κατεχομένην ὑπὸ στρατοπέδων καὶ συμμάχους ὄντας διήρπασεν καὶ ἐξεπολιόρκησεν τὸ Ἰουδαίων ἔθνος φίλον ὑπάρχον τοῦ Ῥωμαίων δήμου,"},{"number":321,"text":"τὴν ἀπόνοιαν τὴν ἐκείνου τοῖς ὅπλοις κρατήσαντες διατάγμασιν καὶ κρίμασιν ἐπανορθούμεθα τὰ ὑπʼ αὐτοῦ διηρπασμένα, ὥστε ἀποκατασταθῆναι ταῦτα τοῖς συμμάχοις ἡμῶν· καὶ ὅσα ἐπράθη Ἰουδαίων ἤτοι σώματα Ἰουδαίων ἢ κτῆσις ταῦτα ἀφεθήτω, τὰ μὲν σώματα ἐλεύθερα, ὡς ἦν ἀπʼ ἀρχῆς, ἡ δὲ κτῆσις τοῖς πρότερον κυρίοις."},{"number":322,"text":"τὸν δʼ οὐχ ὑπακούσαντα τῷ ἐμῷ διατάγματι δίκην συστήσασθαι βούλομαι, κἂν ἁλῷ τότε κατὰ τὴν τοῦ πράγματος ἀξίαν μελήσει μοι ἐπεξελθεῖν τὸν οὐχ ὑπακούσαντα."},{"number":323,"text":"Τὸ δʼ αὐτὸ τοῦτο καὶ Σιδωνίοις καὶ Ἀντιοχεῦσιν καὶ Ἀραδίοις ἔγραψεν. παρεθέμεθα μὲν οὖν καὶ ταῦτα εὐκαίρως τεκμήρια γενησόμενα ἧς φαμὲν Ῥωμαίους ποιήσασθαι προνοίας ὑπὲρ τοῦ ἡμετέρου ἔθνους."}],"13":[{"number":324,"text":"Μετὰ δὲ ταῦτα εἰς Συρίαν Ἀντωνίου παραγενομένου Κλεοπάτρα περὶ Κιλικίαν ἐντυχοῦσα διʼ ἔρωτος αὐτὸν ἐκεχείρωτο. καὶ δὴ πάλιν Ἰουδαίων ἑκατὸν οἱ δυνατώτατοι παραγίνονται πρὸς αὐτὸν κατηγοροῦντες Ἡρώδου καὶ τῶν περὶ αὐτὸν προστησάμενοι σφῶν τοὺς δεινοτάτους λέγειν."},{"number":325,"text":"ἀντέλεγεν δὲ αὐτοῖς Μεσσάλας ὑπὲρ τῶν νεανίσκων παρόντος καὶ Ὑρκανοῦ, ὃς κηδεστὴς ἐτύγχανεν ἤδη γεγενημένος. ἀκροασάμενος δὲ ἀμφοτέρων Ἀντώνιος ἐπὶ Δάφνης πυνθάνεται Ὑρκανοῦ, πότεροι τοῦ ἔθνους ἄμεινον προΐστανται·"},{"number":326,"text":"φήσαντος δὲ τοὺς περὶ Ἡρώδην, Ἀντώνιος καὶ πάλαι οἰκείως ἔχων πρὸς αὐτοὺς διὰ τὴν πατρῴαν ξενίαν, ἣν ἡνίκα σὺν Γαβινίῳ παρῆν ἐπεποίητο πρὸς τὸν πατέρα αὐτῶν, τούτους μὲν ἀμφοτέρους τετράρχας καθίστησιν καὶ τὰ Ἰουδαίων αὐτοῖς ἐπιτρέπει πράγματα, γράφει δὲ καὶ γράμματα πεντεκαίδεκα τῶν ἀντιστασιαστῶν ἔδησεν, μέλλοντος δὲ καὶ κτείνειν αὐτοὺς παρῃτήσαντο οἱ περὶ Ἡρώδην."},{"number":327,"text":"Ἠρέμουν δʼ οὐδʼ οὕτως ἐπανελθόντες ἐκ τῆς πρεσβείας, ἀλλʼ ἀπήντων πάλιν Ἀντωνίῳ χίλιοι εἰς Τύρον ἐκεῖ δόξαντι ἀφικέσθαι. καὶ ὁ Ἀντώνιος πολλοῖς διεφθαρμένος ἤδη χρήμασιν ὑπό τε Ἡρώδου καὶ τοῦ ἀδελφοῦ αὐτοῦ τῷ κατὰ τόπον ἄρχοντι προσέταξεν κολάσαι τοὺς πρεσβευτὰς τῶν Ἰουδαίων νεωτέρων ἐπιθυμοῦντας πραγμάτων καὶ τοῖς περὶ Ἡρώδην συγκαθιστάναι τὴν ἀρχήν."},{"number":328,"text":"ταχὺ δὲ Ἡρώδης, ἵδρυντο γὰρ ἐπὶ τῆς ψάμμου πρὸ τῆς πόλεως, προϊὼν ἀπιέναι παρεκελεύετο, συνῆν δʼ αὐτοῖς καὶ Ὑρκανός, ὡς μεγάλου κακοῦ εἰ προέλθοιεν εἰς φιλονεικίαν ἐσομένου. καὶ οἱ μὲν οὐκ ἐπείθοντο."},{"number":329,"text":"παραχρῆμα δʼ ἐκδραμόντες Ῥωμαῖοι σὺν ἐγχειριδίοις τοὺς μὲν αὐτῶν ἀπέκτειναν, πλείους δὲ κατέτρωσαν, οἱ δὲ λοιποὶ διαφυγόντες ἐπʼ οἴκου ἡσύχαζον. τοῦ δὲ δήμου καταβοῶντος Ἡρώδου παροξυνθεὶς Ἀντώνιος τοὺς δεδεμένους ἀπέκτεινεν."},{"number":330,"text":"Δευτέρῳ δʼ ἔτει Συρίαν κατέσχον Πάκορός τε ὁ βασιλέως παῖς καὶ Βαζαφράνης σατράπης ὢν Πάρθων. τελευτᾷ δὲ καὶ Πτολεμαῖος ὁ Μενναίου καὶ τὴν ἀρχὴν ὁ παῖς αὐτοῦ Λυσανίας παραλαβὼν διαπράττεται φιλίαν πρὸς Ἀντίγονον τὸν Ἀριστοβούλου, πρὸς τοῦτο χρήσιμον τὸν σατράπην παραλαβὼν μέγα παρʼ αὐτῷ δυνάμενον."},{"number":331,"text":"Ἀντίγονος δʼ ὑπισχνεῖτο χίλια τάλαντα καὶ πεντακοσίας γυναῖκας δώσειν Πάρθοις, εἰ τὴν ἀρχὴν Ὑρκανὸν ἀφελόμενοι παραδώσουσιν αὐτῷ καὶ τοὺς περὶ τὸν Ἡρώδην ἀνέλοιεν."},{"number":332,"text":"οὐ μὴν ἔδωκεν· ἀλλʼ οἱ μὲν Πάρθοι διὰ τοῦτʼ ἐπὶ τὴν Ἰουδαίαν ἐστράτευσαν κατάγοντες Ἀντίγονον, Πάκορος μὲν διὰ τῆς παραθαλαττίου, ὁ δὲ σατράπης Βαζαφράνης διὰ τῆς μεσογείου."},{"number":333,"text":"Τύριοι μὲν οὖν ἀποκλείουσι Πάκορον, Σιδώνιοι δὲ καὶ Πτολεμαεῖς ἐδέξαντο. ἴλην μέντοι Πάκορος ἱππέων εἰς τὴν Ἰουδαίαν ἐξέπεμψεν κατασκεψομένην τε τὰ κατὰ τὴν χώραν καὶ Ἀντιγόνῳ συμπράξουσαν, ἡγεμόνα τε ὁμώνυμον τοῦ βασιλέως οἰνοχόον."},{"number":334,"text":"ἐκ δὲ τῶν περὶ Κάρμηλον τὸ ὄρος Ἰουδαίων πρὸς Ἀντίγονον ἐλθόντων καὶ συνεισβαλεῖν ἑτοίμως ἐχόντων, προσεδόκα δὲ τῆς χώρας μέρος τι λαβεῖν ὁ Ἀντίγονος, δρυμοὶ δὲ τὸ χωρίον καλεῖται, καί τινων ὑπαντιασάντων αὐτοὺς διεκπίπτουσιν εἰς Ἱεροσόλυμα οἱ ἄνθρωποι. προσγενομένων δέ τινων πολλοὶ συστραφέντες ἐπὶ τὰ βασίλεια ἧκον καὶ ταῦτα ἐπολιόρκουν."},{"number":335,"text":"προσβοηθούντων δὲ τῶν περὶ Φασάηλον καὶ Ἡρώδην καὶ μάχης γενομένης κατὰ τὴν ἀγορὰν νικῶσιν οἱ νεανίσκοι τοὺς πολεμίους, καὶ συνδιώξαντες εἰς τὸ ἱερὸν πέμπουσιν ὁπλίτας τινὰς εἰς τὰς πλησίον οἰκίας φρουρήσοντας αὐτάς, οὓς ἐπαναστὰς ὁ δῆμος συμμάχων ὄντας ἐρήμους σὺν αὐτοῖς οἴκοις κατέπρησεν."},{"number":336,"text":"ὑπὲρ μὲν οὖν τῆς ἀδικίας ταύτης Ἡρώδης μετʼ ὀλίγον τιμωρίαν παρὰ τῶν ἀντιστασιωτῶν λαμβάνει συμβαλὼν αὐτοῖς εἰς μάχην καὶ πολλοὺς αὐτῶν ἀποκτείνας."},{"number":337,"text":"Γινομένων δʼ ὁσημέραι ἀκροβολισμῶν αὐτοῖς ἀνέμενον οἱ πολέμιοι τὸν ἐκ τῆς χώρας ὄχλον εἰς τὴν καλουμένην πεντηκοστήν, ἑορτὴ δʼ ἐστίν, μέλλοντα ἥξειν."},{"number":338,"text":"τῆς δʼ ἡμέρας ἐνστάσης πολλαὶ περὶ τὸ ἱερὸν ἀθροίζονται μυριάδες ἀνθρώπων ὡπλισμένων τε καὶ ἀνόπλων. κατεῖχον δὲ τὴν πόλιν καὶ τὸ ἱερὸν οἱ παρόντες πλὴν τῶν περὶ τὰ βασίλεια· ταῦτα γὰρ σὺν ὀλίγοις στρατιώταις οἱ περὶ Ἡρώδην ἐφρούρουν."},{"number":339,"text":"Φασάηλος μὲν οὖν τὸ τεῖχος ἐφύλασσεν, Ἡρώδης δὲ λόχον ἔχων ἐπέξεισιν τοῖς πολεμίοις κατὰ τὸ προάστειον, καὶ καρτερῶς μαχεσάμενος πολλάς τε μυριάδας τρέπει, τῶν μὲν εἰς τὴν πόλιν φευγόντων, τῶν δʼ εἰς τὸ ἱερόν, ἔστιν δʼ ὧν εἰς τὸ ἔξω χαράκωμα· ἦν γάρ τι αὐτόθι· παρεβοήθει δὲ καὶ Φασάηλος."},{"number":340,"text":"Πάκορος δʼ ὁ Πάρθων στρατηγὸς σὺν ἱππεῦσιν ὀλίγοις Ἀντιγόνου δεηθέντος εἰς τὴν πόλιν ἔρχεται, λόγῳ μὲν ὡς καταπαύσειεν τὴν στάσιν, τὸ δʼ ἀληθὲς συμπράξων ἐκείνῳ τὴν ἀρχήν."},{"number":341,"text":"Φασαήλου δʼ ὑπαντήσαντος καὶ δεξαμένου ξενίᾳ Πάκορος πείθει πρεσβεύσασθαι παρὰ Βαζαφράνην αὐτόν, δόλον τινὰ τοῦτον συντιθείς. καὶ Φασάηλος οὐδὲν ὑπιδόμενος πείθεται μὴ ἐπαινοῦντος Ἡρώδου τοῖς πραττομένοις διὰ τὸ τῶν βαρβάρων ἄπιστον, ἀλλὰ καὶ Πακόρῳ καὶ τοῖς ἥκουσιν ἐπιτίθεσθαι κελεύοντος."},{"number":342,"text":"Ὤιχοντο δʼ οὖν πρεσβεύοντες Ὑρκανός τε καὶ Φασάηλος, Πάκορος δὲ καταλιπὼν Ἡρώδῃ διακοσίους ἱππεῖς καὶ δέκα τῶν λεγομένων ἐλευθέρων προύπεμψεν αὐτούς. γενομένοις δʼ ἐν τῇ Γαλιλαίᾳ μεθʼ ὅπλων ὑπαντῶσιν οἱ ταύτῃ τῶν πολεμίων ὑφεστῶτες."},{"number":343,"text":"καὶ Βαζαφράνης τὸ μὲν πρῶτον αὐτοὺς ὑποδέχεται προθύμως καὶ δῶρα δίδωσιν, ἔπειτα ἐπεβούλευεν. πλησίον δὲ μετὰ ἱππέων ὑπὲρ θαλάττης οἱ περὶ Φασάηλον κατάγονται καὶ ἐνταῦθʼ ἀκούσαντες, ὡς Ἀντίγονος ὑπόσχοιτο χίλια τάλαντα καὶ γυναῖκας πεντακοσίας τοῖς Πάρθοις κατʼ αὐτῶν, διʼ ὑποψίας εἶχον ἤδη τοὺς βαρβάρους."},{"number":344,"text":"οὐ μὴν ἀλλὰ καὶ νύκτωρ ἐπιβουλευομένους αὐτοὺς ἀπήγγειλέν τις φυλακῆς αὐτοὺς ἐκ τἀφανοῦς περιισταμένης, καὶ συνελήφθησαν ἄν, εἰ μὴ περιέμενον ἕως ἂν οἱ περὶ Ἱεροσόλυμα Πάρθοι Ἡρώδην συλλάβοιεν, μὴ προανῃρημένων τούτων ἐκεῖνος αἰσθόμενος διαφύγοι. καὶ ἦν ταῦθʼ οὕτως ἔχοντα καὶ οἱ φύλακες αὐτῶν ἑωρῶντο."},{"number":345,"text":"Φασαήλῳ μὲν οὖν παρῄνουν τινὲς εὐθὺς ἀφιππάσασθαι καὶ μὴ περιμένειν, μάλιστα μέντοι πρὸς ταῦτα αὐτὸν Ὀφέλλιος ἐνῆγεν, ὃς ἀκηκόει παρὰ Σαραμάλλα τοῦ πλουσιωτάτου τῶν ἐν Συρίᾳ τότε καὶ πλοῖα πρὸς τὴν φυγὴν ὑπισχνεῖτο· ἐγγὺς γὰρ ἦν ἡ θάλασσα."},{"number":346,"text":"ὁ δὲ Ὑρκανὸν ἀπολιπεῖν οὐκ ἠξίου οὐδὲ παρακινδυνεύειν τἀδελφῷ· προσελθὼν δὲ πρὸς τὸν Βαζαφράνην οὐ δίκαια ποιεῖν αὐτὸν ἔλεγεν τοιαῦτα βουλευόμενον περὶ αὐτῶν· χρημάτων τε γὰρ δεομένῳ πλείονα ἔσεσθαι παρʼ αὐτοῦ ὧν Ἀντίγονος δίδωσιν, καὶ ἄλλως δεινὸν εἶναι πρὸς αὐτὸν ἐπὶ πίστει συνελθόντας πρεσβευτὰς ἀποκτεῖναι μηδὲν ἀδικοῦντας."},{"number":347,"text":"ὁ δὲ βάρβαρος ταῦτα λέγοντος ὤμνυεν μηδὲν ἀληθὲς εἶναι τῶν ὑπονοουμένων, ἀλλὰ ψευδεῖς αὐτὸν ὑποψίας ταράξαι, ἀπῄει τε πρὸς Πάκορον."},{"number":348,"text":"Οἰχομένου δὲ τῶν Πάρθων ἐδέσμευόν τινες Ὑρκανὸν καὶ Φασάηλον πολλὰ τῆς ἐπιορκίας κακίζοντα τοὺς Πάρθους. ὁ δʼ ἐπὶ τὸν Ἡρώδην ἀπεσταλμένος εὐνοῦχος ἐντολὰς εἶχεν προαγαγὼν αὐτὸν ἔξω τοῦ τείχους συλλαμβάνειν."},{"number":349,"text":"ἔτυχον δὲ ἄγγελοι παρὰ Φασαήλου πεμφθέντες ἐπὶ δηλώσει τῆς τῶν Πάρθων ἀπιστίας, οὓς τῶν πολεμίων συλλαβόντων γνοὺς Ἡρώδης πρόσεισι Πακόρῳ καὶ Πάρθων τοῖς δυνατοῖς ὡς οὖσιν τῶν ἄλλων δεσπόταις."},{"number":350,"text":"οἱ δὲ τὸ πᾶν εἰδότες ὑπεκρίνοντο δολερῶς καὶ δεῖν αὐτὸν ἔφασαν μετὰ σφῶν ἐξελθόντα πρὸ τοῦ τείχους ὑπαντᾶν τοῖς τὰ γράμματα κομίζουσιν· οὐδέπω γὰρ αὐτοὺς εἰλῆφθαι πρὸς τῶν ἀντιστασιωτῶν, ἥκειν μέντοι δηλοῦντας ὅσα κατορθώσειε Φασάηλος."},{"number":351,"text":"τούτοις Ἡρώδης οὐκ ἐπίστευσεν· ἀκηκόει γὰρ τὴν σύλληψιν τἀδελφοῦ παρʼ ἑτέρων· καὶ παραινούσης δὲ τῆς Ὑρκανοῦ θυγατρός, ἧς ἐγγεγύητο τὴν παῖδα, ἔτι μᾶλλον ὑπώπτευε τοὺς Πάρθους. οἱ μὲν οὖν ἄλλοι ταύτῃ οὐ προσεῖχον, αὐτὸς δʼ ἐπίστευεν λίαν ἔμφρονι γυναικί."},{"number":352,"text":"Βουλευομένων δὲ τῶν Πάρθων, τί χρὴ ποιεῖν, οὐ γὰρ ἤρεσκεν αὐτοῖς ἐκ τοῦ φανεροῦ ἐπιχειρεῖν ἀνδρὶ τηλικούτῳ, καὶ ὑπερθεμένων εἰς τὴν ὑστεραίαν, ἐν τοιαύταις ταραχαῖς Ἡρώδης γενόμενος καὶ μᾶλλον οἷς ἤκουσεν περὶ τἀδελφοῦ καὶ τῆς Πάρθων ἐπιβουλῆς ἢ τοῖς ἐναντίοις προστιθέμενος, ἑσπέρας ἐπελθούσης ἔγνω ταύτῃ πρὸς φυγὴν χρήσασθαι καὶ μὴ διαμέλλειν ὡς ἐπʼ ἀδήλοις τοῖς ἀπὸ τῶν πολεμίων κινδύνοις."},{"number":353,"text":"ἄρας οὖν σὺν οἷς εἶχεν ὁπλίταις καὶ τὰς γυναῖκας τοῖς ὑποζυγίοις ἐπιθέμενος μητέρα τε αὐτοῦ καὶ ἀδελφὴν καὶ ἣν ἔμελλεν ἄξεσθαι πρὸς γάμον Ἀλεξάνδρου θυγατέρα τοῦ Ἀριστοβούλου παιδὸς τήν τε ταύτης μητέρα, Ὑρκανοῦ δʼ ἦν θυγάτηρ, καὶ τὸν νεώτατον ἀδελφὸν τήν τε θεραπείαν πᾶσαν καὶ τὸν ἄλλον ὄχλον τὸν σὺν αὐτοῖς, ἐδίωκεν τὴν ἐπὶ Ἰδουμαίας λαθὼν τοὺς πολεμίους."},{"number":354,"text":"ὧν οὐδεὶς ἂν οὕτως στερρὸς τὴν φύσιν εὑρέθη, ὃς τότε παρὼν τοῖς πραττομένοις οὐκ ἂν ᾤκτειρεν αὐτοὺς τῆς τύχης, γυναίων ἐπαγομένων νήπια τέκνα καὶ μετὰ δακρύων καὶ οἰμωγῆς ἀπολειπουσῶν τὴν πατρίδα καὶ φίλους ἐν δεσμοῖς καὶ περὶ αὐτῶν οὐδὲν ἔτι χρηστὸν προσδεχομένων."},{"number":355,"text":"Ἀλλʼ Ἡρώδης ἐπάνω τῆς ἐκ τοῦ δεινοῦ πληγῆς τὸ φρόνημα ποιησάμενος αὐτός τε ἦν πρὸς τὸ δεινὸν εὔψυχος καὶ παριὼν κατὰ τὴν ὁδὸν θαρρεῖν ἕκαστον παρεκελεύετο καὶ μὴ παρέχειν αὑτὸν ἔκδοτον τῇ λύπῃ· τοῦτο γὰρ αὐτοὺς βλάπτειν πρὸς τὴν φυγήν, ἐν ᾗ τὴν σωτηρίαν αὐτοῖς μόνῃ κεῖσθαι συμβέβηκεν."},{"number":356,"text":"καὶ οἱ μὲν ὡς Ἡρώδης παρῄνει φέρειν τὴν συμφορὰν ἐπειρῶντο. μικροῦ δʼ αὑτὸν διεχρήσατο τοῦ ζεύγους περιτραπέντος καὶ τῆς μητρὸς αὐτῷ κινδυνευσάσης ἀποθανεῖν, διά τε τὸ ἐπʼ αὐτῇ πάθος καὶ διὰ τὸ φοβεῖσθαι, μὴ καταλάβωσιν αὐτὸν οἱ πολέμιοι διώκοντες τριβῆς περὶ τὸ πταῖσμα γενομένης."},{"number":357,"text":"σπασάμενον γοῦν αὐτὸν τὸ ξίφος καὶ μέλλοντα πλήττειν αὑτὸν κατέσχον οἱ παρόντες, τῷ τε πλήθει κατισχύσαντες καὶ ὡς οὐκ ἐχρῆν αὐτοὺς ἐγκαταλιπεῖν ἐπὶ τοῖς ἐχθροῖς ἐσομένους λέγοντες· οὐ γὰρ εἶναι γενναίου τῶν δεινῶν αὑτὸν ἐλευθερώσαντα τοὺς φίλους ἐν αὐτοῖς ὑπεριδεῖν."},{"number":358,"text":"βιασθεὶς οὖν ἀποσχέσθαι τοῦ κατʼ αὐτὸν τολμήματος αἰδοῖ τε τῶν λεγομένων καὶ πλήθει τῶν οὐκ ἐπιτρεπόντων αὐτοῦ τῇ χειρὶ διακονεῖν οἷς ἐντεθύμητο, ἀνακτησάμενος τὴν μητέρα καὶ θεραπείας ἧς ὁ καιρὸς ἤπειγεν ἀξιώσας ἐβάδιζεν τὴν προκειμένην ὁδὸν συντονωτέραν ποιούμενος τὴν πορείαν εἰς Μάσαδαν τὸ ἔρυμα. πολλὰς δὲ μάχας πρὸς τοὺς ἐπεξελθόντας καὶ διώκοντας τῶν Πάρθων μαχεσάμενος πάσας ἐνίκησεν."},{"number":359,"text":"Ἔμεινε δʼ αὐτῷ παρὰ τὴν φυγὴν οὐδὲ τὰ παρὰ τῶν Ἰουδαίων ἀσφαλῆ, συνεπέθεντο δὲ καὶ οὗτοι γενομένοις ἀπὸ σταδίων ἑξήκοντα τῆς πόλεως προσβάλλοντές τε καὶ εἰς χεῖρας ἐρχόμενοι κατὰ τὴν ὁδόν."},{"number":360,"text":"οὓς δὴ καὶ τρεψάμενος καὶ κρατήσας οὐχ ὡς ἐν ἀπορίᾳ καὶ ἀνάγκῃ τις τοιαύτῃ καθεστώς, ἀλλʼ ὡς κάλλιστα καὶ μετὰ πολλοῦ τοῦ περιόντος πρὸς πόλεμον παρεσκευασμένος, ἐν ἐκείνῳ τῷ χωρίῳ, ἐν ᾧ τῶν Ἰουδαίων ἐκράτησε, μετὰ χρόνον βασιλεύσας ἔκτισε καὶ βασίλειον κατεσκεύασεν ἀξιολογώτατον καὶ πόλιν περὶ αὐτὸ Ἡρωδίαν προσαγορεύσας."},{"number":361,"text":"γενομένῳ δὲ τῆς Ἰδουμαίας ἐν Θρήσᾳ χωρίῳ οὕτω καλουμένῳ ὁ ἀδελφὸς Ἰώσηπος ὑπήντησεν καὶ βουλὴν περὶ τῶν ὅλων ἦγε, τί χρὴ ποιεῖν, πολλοῦ μὲν πλήθους ἐπαγομένου καὶ δίχα τῶν μισθοφορούντων αὐτοῖς, τοῦ δὲ χωρίου τῆς Μεσάδας, εἰς ὃ προύκειτο συμφυγεῖν ἐλάττονος ὄντος ὑποδέξασθαι τοσοῦτον ὄχλον."},{"number":362,"text":"τοὺς μὲν οὖν πλείους ἀπέλυσεν ὑπὲρ ἐννέα χιλιάδας ὄντας ἄλλον ἀλλαχῆ κελεύσας διὰ τῆς Ἰδουμαίας σώζειν αὑτούς, δοὺς ἐφόδια· ὅσοι δʼ ἦσαν κοῦφοι καὶ τοὺς ἀναγκαιοτάτους ἀναλαβὼν εἰς τὸ ἔρυμα παραγίνεται καὶ καταθέμενος αὐτόθι τάς τε γυναῖκας καὶ τοὺς ἑπομένους, ἦσαν δὲ ὡς ὀκτακόσιοι, σίτου τε ὄντος ἐν τῷ χωρίῳ καὶ ὕδατος καὶ τῶν ἄλλων ἐπιτηδείων ἁπάντων διαρκούντως αὐτοῖς ἐξώρμησεν αὐτὸς ἐπὶ Πέτρας τῆς Ἀραβίας."},{"number":363,"text":"ἅμα δʼ ἡμέρᾳ τὰ μὲν ἄλλα πάντα τῶν Ἱεροσολύμων διήρπαζον οἱ Πάρθοι καὶ τὸ βασίλειον, μόνων δὲ ἀπείχοντο τῶν Ὑρκανοῦ χρημάτων· τὰ δʼ ἦν ὡς τριακόσια τάλαντα."},{"number":364,"text":"πολλὰ δὲ τῶν Ἡρώδου διέφυγεν καὶ μάλισθʼ ὅσα προκομισθῆναι κατὰ προμήθειαν τἀνδρὸς εἰς τὴν Ἰδουμαίαν ἐφθάκει. τὰ μὲν οὖν κατὰ τὴν πόλιν οὐκ ἀπέχρησε τοῖς Πάρθοις, ἀλλὰ καὶ τὴν χώραν αὐτῶν ἐξιόντες ἐκάκουν καὶ Μάρισάν τε πόλιν δυνατὴν ἀνέστησαν."},{"number":365,"text":"Καὶ Ἀντίγονος μὲν οὕτως καταχθεὶς εἰς τὴν Ἰουδαίαν ὑπὸ τοῦ Πάρθων βασιλέως Ὑρκανὸν καὶ Φασάηλον δεσμώτας παραλαμβάνει. σφόδρα δʼ ἦν ἄθυμος τῶν γυναικῶν αὐτὸν διαφυγουσῶν, ἃς τοῖς πολεμίοις ἐνεθυμεῖτο δώσειν, τοῦτον αὐτοῖς τὸν μισθὸν μετὰ τῶν χρημάτων ὑποσχόμενος."},{"number":366,"text":"φοβούμενος δὲ τὸν Ὑρκανόν, μὴ τὸ πλῆθος αὐτῷ τὴν βασιλείαν ἀποκαταστήσῃ, παραστάς, ἐτηρεῖτο δὲ ὑπὸ τῶν Πάρθων, ἐπιτέμνει αὐτοῦ τὰ ὦτα πραγματευόμενος μηκέτʼ αὖθις εἰς αὐτὸν ἀφικέσθαι τὴν ἀρχιερωσύνην διὰ τὸ λελωβῆσθαι, τοῦ νόμου τῶν ὁλοκλήρων εἶναι τὴν τιμὴν ἀξιοῦντος."},{"number":367,"text":"Φασάηλον δʼ ἄν τις θαυμάσειε τῆς εὐψυχίας, ὃς γνοὺς αὑτὸν ἀποσφάττεσθαι μέλλοντα οὐχὶ τὸν θάνατον ἡγήσατο δεινόν, τὸ δʼ ὑπʼ ἐχθροῦ τοῦτο παθεῖν πικρότατον καὶ αἴσχιστον ὑπολαβών, τὰς χεῖρας οὐκ ἔχων ἐλευθέρας ὑπὸ δεσμῶν πρὸς ἀναίρεσιν πέτρᾳ προσαράξας τὴν κεφαλὴν ἐξήγαγε μὲν αὑτὸν ὡς ἐδόκει κάλλιστα τοῦ ζῆν παρὰ τοιαύτην ἀπορίαν, τῆς δʼ ἐξουσίας τοῦ κτεῖναι πρὸς ἡδονὴν αὐτὸν ἀφείλετο τὸν πολέμιον."},{"number":368,"text":"λέγουσι δʼ, ὡς τραύματος μεγάλου γενομένου φαρμάκοις αὐτὸν ὑποπέμψας ἰατροὺς Ἀντίγονος ὡς ἐπὶ θεραπείᾳ διέφθειρεν θανασίμοις χρησαμένων εἰς τὸ τραῦμα."},{"number":369,"text":"πρὸ μέντοι τοῦ τελέως ἀφεῖναι τὴν ψυχὴν ὁ Φασάηλος ἀκούσας παρά τινος γυναίου τὸν ἀδελφὸν Ἡρώδην τοὺς πολεμίους διαπεφευγότα σφόδρα τὴν τελευτὴν εὐθύμως ὑπέμεινεν καταλιπὼν τὸν ἐκδικῆσαι τὸν θάνατον αὐτοῦ καὶ τοὺς ἐχθροὺς τιμωρήσασθαι δυνάμενον."}],"14":[{"number":370,"text":"Ἡρώδην δὲ τὸ μέγεθος τῶν περιεστηκότων αὐτὸν κακῶν οὐ κατέπληττεν, ἀλλʼ ἐποίει δεινὸν εὑρίσκειν ἐπιβολὰς ἔργων παραβόλων. πρὸς γὰρ Μάλιχον τὸν Ἀράβων βασιλέα πολλὰ πρόσθεν εὐεργετημένον ἀπῄει τὴν ἀμοιβὴν κομιούμενος, ὅτε μάλιστα ἐδεῖτο, χρήματα ληψόμενος εἴτε δάνειον εἴτε δωρεὰν ὡς ἂν πολλῶν παρʼ αὐτοῦ τετυχηκότος."},{"number":371,"text":"οὐ γὰρ εἰδὼς τὰ κατὰ τὸν ἀδελφὸν ἔσπευδεν λυτρώσασθαι παρὰ τῶν πολεμίων αὐτὸν λύτρον ὑπὲρ αὐτοῦ καταβαλὼν νόμισμα ἕως τριακοσίων ταλάντων. ἐπήγετο δὲ καὶ τὸν Φασαήλου παῖδα διὰ ταύτην τὴν αἰτίαν ἑπταετῆ τυγχάνοντα, παρασχὼν αὐτὸν ἐνέχυρον τοῖς Ἄραψιν."},{"number":372,"text":"ἀγγέλων δʼ αὐτὸν ὑπαντησάντων παρὰ τοῦ Μαλίχου, διʼ ὧν ἐκέλευσεν αὐτὸν ἀναχωρεῖν· παρηγγελκέναι γὰρ αὐτῷ Πάρθους Ἡρώδην μὴ δέχεσθαι· ταύτῃ δʼ ἐχρῆτο προφάσει ὑπὲρ τοῦ μὴ ἀποδοῦναι τὰ χρέα καὶ τῶν ἐν τέλει παρὰ τοῖς Ἄραψιν εἰς τοῦτο ἐναγόντων, ὅπως ἀποστερήσωσιν τὰς παρακαταθήκας, ἃς παρὰ Ἀντιπάτρου λαβόντες ἔτυχον,"},{"number":373,"text":"ἀπεκρίνατο αὐτοῖς οὐδὲν ἐνοχλήσων ἀφικνεῖσθαι πρὸς αὐτούς, μόνον δὲ διαλεξόμενος περὶ τῶν ἀναγκαιοτάτων αὐτῷ πραγμάτων."},{"number":374,"text":"Ἔπειτα δόξαν ἀναχωρεῖν ἀπῄει μάλα σωφρόνως τὴν ἐπʼ Αἰγύπτου. καὶ τότε μὲν ἔν τινι ἱερῷ κατάγεται, καταλελοίπει γὰρ αὐτόθι πολλοὺς τῶν ἑπομένων, τῇ δʼ ὑστεραίᾳ παραγενόμενος εἰς Ῥινοκούρουρα ἐκεῖ καὶ τὰ περὶ τὸν ἀδελφὸν ἤκουσεν."},{"number":375,"text":"Μαλίχῳ δὲ μεταγνόντι καὶ μεταθέοντι τὸν Ἡρώδην οὐδὲν τούτου περισσότερον ἐγένετο· πορρωτάτω γὰρ ἦν ἤδη σπεύδων τὴν ἐπὶ Πηλουσίου. ἐπεὶ δʼ αὐτὸν ἐλθόντα νῆες ὁρμοῦσαι αὐτόθι εἶργον τοῦ ἐπʼ Ἀλεξανδρείας πλοῦ, τοῖς ἡγεμόσιν ἐντυγχάνει, ὑφʼ ὧν κατʼ αἰδῶ καὶ πολλὴν ἐντροπὴν προπεμφθεὶς εἰς τὴν πόλιν, ὑπὸ Κλεοπάτρας κατείχετο."},{"number":376,"text":"πεῖσαι μέντοι μένειν αὐτὸν οὐκ ἠδυνήθη εἰς Ῥώμην ἐπειγόμενον χειμῶνός τε ὄντος καὶ τῶν κατὰ τὴν Ἰταλίαν ἐν ταραχῇ καὶ σάλῳ πολλῷ δηλουμένων."},{"number":377,"text":"Ἀναχθεὶς οὖν ἐκεῖθεν ἐπὶ Παμφυλίας καὶ χειμῶνι σφοδρῷ περιπεσὼν μόλις εἰς Ῥόδον διασώζεται φορτίων ἀποβολῆς γενομένης. καὶ δύο μὲν ἐνταυθοῖ τῶν φίλων αὐτῷ συνήντησαν, Σαππῖνός τε καὶ Πτολεμαῖος."},{"number":378,"text":"εὑρὼν δὲ τὴν πόλιν ὑπὸ τοῦ πρὸς Κάσσιον πολέμου κεκακωμένην οὐδʼ ἐν ἀπόροις ὢν εὖ ποιεῖν αὐτὴν ὤκνησεν, ἀλλὰ καὶ παρὰ δύναμιν αὐτὴν ἀνεκτᾶτο. τριήρη τε κατασκευάσας, καὶ ἀναχθεὶς ἐκεῖθεν σὺν τοῖς φίλοις ἐπʼ Ἰταλίας εἰς Βρεντέσιον κατάγεται."},{"number":379,"text":"κἀκεῖθεν εἰς Ῥώμην ἀφικόμενος πρῶτον μὲν Ἀντωνίῳ φράζει τὰ συμβάντα αὐτῷ κατὰ τὴν Ἰουδαίαν, καὶ πῶς ὁ ἀδελφὸς αὐτοῦ Φασάηλος ὑπὸ Πάρθων ἀπόλοιτο συλληφθεὶς καὶ Ὑρκανὸς ὑπʼ αὐτῶν αἰχμάλωτος ἔχοιτο, καὶ ὡς Ἀντίγονον καταστήσειαν βασιλέα χρήματα δώσειν ὑποσχόμενον χίλια τάλαντα καὶ γυναῖκας πεντακοσίας, αἳ τῶν πρώτων κἀκ τοῦ γένους τοῦ αὐτῶν ἔμελλον ἔσεσθαι, καὶ ὅτι ταύτας νυκτὸς ἐκκομίσειεν καὶ διαφύγοι τὰς τῶν ἐχθρῶν χεῖρας πολλὰς ὑπομείνας ταλαιπωρίας."},{"number":380,"text":"εἶτʼ ἐπιδιακινδυνεύειν † αὐτῷ τοὺς οἰκείους πολιορκουμένους πλεύσειέ τε διὰ χειμῶνος καὶ παντὸς καταφρονήσειε δεινοῦ σπεύδων ἐπὶ τὰς ἐλπίδας τὰς παρʼ αὐτοῦ καὶ τὴν μόνην βοήθειαν."},{"number":381,"text":"Ἀντώνιον δʼ οἶκτος εἰσέρχεται τῆς Ἡρώδου μεταβολῆς, καὶ τῷ κοινῷ χρησάμενος λογισμῷ περὶ τῶν ἐν ἀξιώματι τοσούτῳ καθεστώτων ὡς κἀκείνων ὑποκειμένων τῇ τύχῃ, τὰ μὲν κατὰ μνήμην τῆς Ἀντιπάτρου ξενίας,"},{"number":382,"text":"τὰ δὲ καὶ ὑπὸ χρημάτων ὧν αὐτῷ δώσειν Ἡρώδης, εἰ γένοιτο βασιλεύς, ὑπέσχετο καθὼς καὶ πρότερον τετράρχης ἀπεδέδεικτο, πολὺ μέντοι μᾶλλον διὰ τὸ πρὸς Ἀντίγονον μῖσος, στασιαστὴν γὰρ καὶ Ῥωμαίοις ἐχθρὸν αὐτὸν ὑπελάμβανεν, πρόθυμος ἦν οἷς Ἡρώδης παρεκάλει συλλαμβάνεσθαι."},{"number":383,"text":"Καῖσαρ μὲν οὖν καὶ διὰ τὰς Ἀντιπάτρου στρατείας, ἃς κατʼ Αἴγυπτον αὐτοῦ τῷ πατρὶ συνδιήνεγκεν, καὶ τὴν ξενίαν καὶ τὴν ἐν ἅπασιν εὔνοιαν, καὶ χαριζόμενος δὲ Ἀντωνίῳ σφόδρα περὶ τὸν Ἡρώδην ἐσπουδακότι, πρὸς τὴν ἀξίωσιν καὶ τὴν ὧν ἐβούλετο Ἡρώδης συνεργίαν ἑτοιμότερος ἦν."},{"number":384,"text":"συναγαγόντες δὲ τὴν βουλὴν Μεσσάλας καὶ μετʼ αὐτὸν Ἀτρατῖνος, παραστησάμενοι τὸν Ἡρώδην τάς τε τοῦ πατρὸς εὐεργεσίας αὐτοῦ διεξῄεσαν καὶ ἣν αὐτὸς πρὸς Ῥωμαίους εἶχεν εὔνοιαν ὑπεμίμνησκον, κατηγοροῦντες ἅμα καὶ πολέμιον ἀποφαίνοντες τὸν Ἀντίγονον οὐκ ἐξ ὧν τὸ πρῶτον προσέκρουσεν αὐτοῖς μόνον, ἀλλʼ ὅτι καὶ παρὰ Πάρθων τὴν ἀρχὴν λάβοι Ῥωμαίους ὑπεριδών."},{"number":385,"text":"τῆς δὲ βουλῆς ἐπὶ τούτοις παρωξυμμένης παρελθὼν Ἀντώνιος ἐδίδασκεν αὐτούς, ὡς καὶ πρὸς τὸν κατὰ Πάρθων πόλεμον Ἡρώδην βασιλεύειν συμφέρει. καὶ δόξαν τοῦτο πᾶσι ψηφίζονται."},{"number":386,"text":"Καὶ τοῦτο τὸ μέγιστον ἦν τῆς Ἀντωνίου περὶ τὸν Ἡρώδην σπουδῆς, ὅτι μὴ μόνον αὐτῷ τὴν βασιλείαν οὐκ ἐλπίζοντι περιεποιήσατο, οὐ γὰρ πρὸς αὐτὸν ἀνέβη ταύτην αἰτησόμενος, οὐ γὰρ ἐνόμιζεν αὐτῷ τοὺς Ῥωμαίους παρέξειν τοῖς ἐκ τοῦ γένους ἔθος ἔχοντας αὐτὴν διδόναι,"},{"number":387,"text":"ἀλλὰ διὰ τὸ τῷ τῆς γυναικὸς ἀδελφῷ λαβεῖν ἀξιώσων Ἀλεξάνδρῳ υἱωνῷ τυγχάνοντι πρὸς μὲν πατρὸς Ἀριστοβούλου πρὸς δὲ μητρὸς Ὑρκανοῦ, ἀλλʼ ὅτι καὶ ἑπτὰ ταῖς πάσαις ἡμέραις παρέσχεν αὐτῷ τυχόντι τῶν οὐδὲ προσδοκηθέντων ἀπελθεῖν ἐκ τῆς Ἰταλίας."},{"number":388,"text":"τοῦτον μὲν οὖν τὸν νεανίσκον Ἡρώδης ἀπέκτεινεν, ὡς κατὰ καιρὸν δηλώσομεν· λυθείσης δὲ τῆς βουλῆς μέσον ἔχοντες Ἡρώδην Ἀντώνιος καὶ Καῖσαρ ἐξῄεσαν προαγόντων ἅμα ταῖς ἄλλαις ἀρχαῖς τῶν ὑπάτων θύσοντές τε καὶ τὸ δόγμα καταθησόμενοι εἰς τὸ Καπετώλιον."},{"number":389,"text":"ἑστιᾷ δὲ τὴν πρώτην ἡμέραν τῆς βασιλείας Ἀντώνιος. καὶ ὁ μὲν οὕτως τὴν βασιλείαν παραλαμβάνει τυχὼν αὐτῆς ἐπὶ τῆς ἑκατοστῆς καὶ ὀγδοηκοστῆς καὶ τετάρτης ὀλυμπιάδος ὑπατεύοντος Γναίου Δομετίου Καλβίνου τὸ δεύτερον καὶ Γαΐου Ἀσινίου Πωλίωνος."},{"number":390,"text":"Τοῦτον δὲ ἅπαντα τὸν χρόνον Ἀντίγονος ἐπολιόρκει τοὺς ἐν Μασάδα, τῶν μὲν ἄλλων ἐπιτηδείων αὐτοῖς ὑπαρχόντων, μόνου δὲ σπανίζοντος ὕδατος, ὡς διὰ τοῦτο καὶ τὸν ἀδελφὸν τὸν Ἡρώδου Ἰώσηπον σὺν διακοσίοις τῶν οἰκείων ἀποδρᾶναι βουλεύσασθαι πρὸς Ἄραβας· ἀκηκόει γὰρ ὡς Μάλχος τῶν εἰς Ἡρώδην ἁμαρτημάτων μετανοεῖ."},{"number":391,"text":"κατέσχε δʼ αὐτὸν ὕσας διὰ τῆς νυκτὸς ὁ θεός· τῶν γὰρ ἐκδοχείων πλησθέντων τοῦ ὕδατος οὐκέτι τῆς φυγῆς ἐδεῖτο, ἀλλὰ τεθαρσηκότες ἤδη καὶ πλέον ἢ κατὰ τὴν εὐπορίαν τοῦ σπανίζοντος, ὡς ἐκ θεοῦ προνοίας ταύτης αὐτοῖς γεγενημένης, ἐπεξιόντες καὶ συμπλεκόμενοι τοῖς περὶ τὸν Ἀντίγονον τοῖς μὲν φανερῶς, τοῖς δὲ καὶ λάθρα, πολλοὺς αὐτῶν διέφθειραν."},{"number":392,"text":"κἀν τούτῳ Βεντίδιος ὁ Ῥωμαίων στρατηγὸς πεμφθεὶς ἐκ Συρίας ὥστε Πάρθους ἀνείργειν, μετʼ ἐκείνους εἰς τὴν Ἰουδαίαν παρέβαλεν τῷ λόγῳ μὲν Ἰωσήπῳ συμμαχήσων, τὸ δʼ ὅλον ἦν αὐτῷ στρατήγημα χρήματα παρʼ Ἀντιγόνου λαβεῖν· ἔγγιστα γοῦν Ἱεροσολύμων στρατοπεδευόμενος ἀποχρώντως ἠργυρίσατο τὸν Ἀντίγονον."},{"number":393,"text":"καὶ αὐτὸς μὲν ἀνεχώρησεν σὺν τῇ πλείονι δυνάμει, ἵνα δὲ μὴ κατάφωρον γένηται τὸ λῆμμα, Σίλωνα μετὰ μέρους τινὸς τῶν στρατιωτῶν κατέλιπεν, ὃν καὶ αὐτὸν ἐθεράπευεν Ἀντίγονος, ὅπως μηδὲν ἐνοχλοίη, προσδοκῶν καὶ πάλιν αὐτῷ Πάρθους ἐπαμυνεῖν."}],"15":[{"number":394,"text":"Ἡρώδης δʼ ἐκ τῆς Ἰταλίας ἤδη καταπεπλευκὼς εἰς Πτολεμαΐδα καὶ συναγηοχὼς δύναμιν οὐκ ὀλίγην ξένων τε ἅμα καὶ ὁμοφύλων ἤλαυνε διὰ τῆς Γαλιλαίας ἐπὶ τὸν Ἀντίγονον. συνελάμβανον δʼ αὐτῷ Σίλων τε καὶ Βεντίδιος πεισθέντες ὑπὸ Δελλίου συγκατάγειν Ἡρώδην τοῦ πεμφθέντος ὑπʼ Ἀντωνίου."},{"number":395,"text":"Βεντίδιος μὲν οὖν ἐτύγχανεν τὰς ταραχὰς τὰς διὰ Πάρθους ἐν ταῖς πόλεσιν οὔσας καθιστάμενος, Σίλων δʼ ἐν Ἰουδαίᾳ χρήμασιν ὑπʼ Ἀντιγόνου διεφθαρμένος. Ἡρώδῃ μέντοι προϊόντι καθʼ ἑκάστην ἡμέραν ἡ δύναμις ηὔξετο καὶ πᾶσα Γαλιλαία πλὴν ὀλίγων αὐτῷ προστέθειτο."},{"number":396,"text":"ὡρμηκότα δʼ αὐτὸν ἐπὶ τοὺς ἐν Μεσάδα, ἀναγκαῖον γὰρ ἦν τὸ σῶσαι τοὺς ἐν τῷ φρουρίῳ πολιορκουμένους συγγενεῖς ὄντας, ἐμποδὼν Ἰόππη γίνεται· πολεμίαν γὰρ οὖσαν αὐτὴν ἐχρῆν ἐξελεῖν πρότερον, ὅπως μηδὲν ὑπολείπηται κατὰ νώτου τοῖς ἐχθροῖς ἔρυμα χωροῦντος ἐπὶ Ἱεροσολύμων."},{"number":397,"text":"ποιησαμένου δὲ καὶ Σίλωνος ταύτην πρόφασιν τῆς ἀπαναστάσεως καὶ τῶν Ἰουδαίων διωκόντων αὐτὸν Ἡρώδης μετʼ ὀλίγου στίφους ἐπέξεισιν καὶ τρέπεται μὲν τοὺς Ἰουδαίους, Σίλωνα δὲ σώζει κακῶς ἀμυνόμενον, ἑλών τε τὴν Ἰόππην ἔσπευδεν ῥυσόμενος τοὺς ἐν Μασάδα οἰκείους."},{"number":398,"text":"τῶν δʼ ἐπιχωρίων οἱ μὲν αὐτῷ διὰ τὴν πατρῴαν προσεχώρουν φιλίαν, οἱ δὲ διὰ τὴν αὐτοῦ δόξαν, ἄλλοι δὲ κατʼ ἀμοιβὴν τῆς παρʼ ἀμφοτέρων εὐεργεσίας, οἱ πλείους δὲ διὰ τὰς ἐλπίδας, ἃς ὡς ἐπὶ βασιλεῖ βεβαίῳ τὸ λοιπὸν εἶχον."},{"number":399,"text":"Ἤθροιστο δὴ δύναμις βαρεῖα, καὶ προϊόντος Ἀντίγονος τῶν παρόδων τοὺς ἐπιτηδείους τόπους ἐνέδραις καὶ λόχοις κατελάμβανεν καὶ καθάπαξ οὐδὲν ἐκ τούτου τοὺς πολεμίους ἢ μικρὰ παντάπασιν ἔβλαπτεν."},{"number":400,"text":"Ἡρώδης δὲ τοὺς ἐκ Μασάδας οἰκείους παραλαβὼν καὶ Ῥῆσαν τὸ φρούριον ᾔει πρὸς τὰ Ἱεροσόλυμα, συνῆπτε δʼ αὐτῷ τὸ μετὰ Σίλωνος στρατιωτικὸν καὶ πολλοὶ τῶν ἐκ τῆς πόλεως τὴν ἰσχὺν καταπλαγέντες."},{"number":401,"text":"στρατοπεδευσαμένου δὲ κατὰ τὸ πρὸς δύσιν τῆς πόλεως κλίμα οἱ κατὰ τοῦτο τεταγμένοι φύλακες ἠκόντιζόν τε καὶ ἐτόξευον εἰς αὐτούς,"},{"number":402,"text":"ἐνίων δὲ καὶ κατὰ στῖφος ἐξιόντων καὶ τοῖς προτεταγμένοις εἰς χεῖρας ἐρχομένων, Ἡρώδης τὸ μὲν πρῶτον ἐκέλευσεν κηρύσσειν περὶ τὸ τεῖχος, ὡς ἐπʼ ἀγαθῷ τε παρείη τοῦ δήμου καὶ ἐπὶ σωτηρίᾳ τῆς πόλεως, μηδὲν μηδὲ τοῖς φανεροῖς τῶν ἐχθρῶν μνησικακήσων, ἀλλὰ παρέξων καὶ τοῖς διαφορωτάτοις ἀμνηστίαν τῶν εἰς αὐτὸν ἁμαρτημάτων."},{"number":403,"text":"τοῦ δὲ Ἀντιγόνου πρὸς τὰ ὑπὸ τοῦ Ἡρώδου κηρυχθέντα λέγοντος πρός τε Σίλωνα καὶ τὸ τῶν Ῥωμαίων στράτευμα, ὡς παρὰ τὴν αὐτῶν δικαιοσύνην Ἡρώδῃ δώσουσιν τὴν βασιλείαν ἰδιώτῃ τε ὄντι καὶ Ἰδουμαίῳ, τουτέστιν ἡμιιουδαίῳ, δέον τοῖς ἐκ τοῦ γένους οὖσι παρέχειν ὡς ἔθος ἐστὶν αὐτοῖς."},{"number":404,"text":"καὶ γὰρ εἰ νυνὶ πρὸς αὐτὸν ἔχουσιν χαλεπῶς καὶ τὴν βασιλείαν ὡς λαβόντα παρὰ Πάρθων ἀφελέσθαι διεγνώκασιν, εἶναί γε πολλοὺς ἐκ τοῦ γένους αὐτοῦ τοὺς ληψομένους κατὰ τὸν νόμον τὴν βασιλείαν, οἳ μηδὲν ἐξημαρτηκότες αὐτοὶ πρὸς Ῥωμαίους καὶ ἱερεῖς ὄντες οὐκ ἂν εἰκότα πάσχοιεν τῆς τιμῆς στερόμενοι."},{"number":405,"text":"ταῦτα πρὸς ἀλλήλους αὐτῶν λεγόντων καὶ προελθόντων εἰς βλασφημίας Ἀντίγονος ἀμύνασθαι τοὺς ἀπὸ τοῦ τείχους ἐπέτρεπεν τοῖς ἰδίοις. οἱ δὲ τοξεύοντες καὶ πολλῇ προθυμίᾳ κατʼ αὐτῶν χρώμενοι ῥᾳδίως αὐτοὺς ἀπὸ τῶν πύργων ἐτρέψαντο."},{"number":406,"text":"Τότε καὶ Σίλων ἀπεκαλύψατο τὴν δωροδοκίαν· καθῆκε γὰρ τῶν οἰκείων στρατιωτῶν οὐκ ὀλίγους σπάνιν τῶν ἐπιτηδείων καταβοᾶν καὶ χρήματα εἰς τροφὰς αἰτεῖν καὶ χειμάσοντας ἀπάγειν εἰς τοὺς ἐπιτηδείους τόπους, τῶν περὶ τὴν πόλιν ὄντων ἐρήμων διὰ τὸ ὑπὸ τῶν Ἀντιγόνου στρατιωτῶν ἀνεσκευάσθαι, ἐκίνει τε τὸ στρατόπεδον καὶ ἀναχωρεῖν ἐπειρᾶτο."},{"number":407,"text":"Ἡρώδης δʼ ἐνέκειτο παρακαλῶν τούς τε ὑπὸ τῷ Σίλωνι ἡγεμόνας καὶ τοὺς στρατιώτας μὴ καταλιπεῖν αὐτόν, Καίσαρός τε καὶ Ἀντωνίου καὶ τῆς συγκλήτου προτρεψάντων αὐτόν· προνοήσειν γὰρ αὐτῶν τῆς εὐπορίας καὶ παρέξειν αὐτοῖς ἀφθονίαν ὧν ἐπιζητοῦσιν ῥᾳδίως."},{"number":408,"text":"καὶ μετὰ τὴν δέησιν εὐθὺς ἐξορμήσας εἰς τὴν χώραν οὐκέτʼ οὐδεμίαν Σίλωνι τῆς ἀναχωρήσεως πρόφασιν ὑπελίπετο· πλῆθος γὰρ ὅσον οὐδʼ ἤλπισέν τις τῶν ἐπιτηδείων ἐκόμισεν, τοῖς τε περὶ Σαμάρειαν ᾠκειωμένοις πρὸς αὐτὸν ἐπέστειλεν σῖτα καὶ οἶνον καὶ ἔλαιον καὶ βοσκήματα τά τε ἄλλα πάντα κατάγειν εἰς Ἱεριχοῦντα τοῦ μηδὲ τὰς ἑξῆς ἡμέρας εἰς χορηγίαν τοὺς στρατιώτας ἐπιλιπεῖν."},{"number":409,"text":"οὐκ ἐλάνθανε δὲ ταῦτʼ Ἀντίγονον, ἀλλʼ εὐθὺς ἀπέπεμψεν κατὰ τὴν χώραν τοὺς εἴρξοντας καὶ λοχήσοντας τοὺς σιτηγοῦντας, οἱ δὲ πειθόμενοι τοῖς Ἀντιγόνου προστάγμασιν καὶ πολὺ πλῆθος ὁπλιτῶν περὶ Ἱεριχοῦντα ἀθροίσαντες παρεφύλασσον ἐπὶ τῶν ὀρῶν καθεσθέντες τοὺς τὰ ἐπιτήδεια κομίζοντας."},{"number":410,"text":"οὐ μὴν Ἡρώδης τούτων πραττομένων ἠρέμει, δέκα δὲ σπείρας ἀναλαβών, ὧν πέντε μὲν Ῥωμαίων, πέντε δὲ Ἰουδαίων ἦσαν, καὶ μισθοφόρους μιγάδας πρὸς οἷς ὀλίγους τῶν ἱππέων ἐπὶ Ἱεριχοῦντα παραγίνεται, καὶ τὴν μὲν πόλιν ἐκλελειμμένην καταλαβών, πεντακοσίους δὲ τὰ ἄκρα κατειληφότας σὺν γυναιξὶν καὶ γενεαῖς, τούτους μὲν ἀπέλυσεν λαβών, Ῥωμαῖοι δὲ εἰσπεσόντες διήρπασαν τὴν πόλιν μεσταῖς ἐπιτυγχάνοντες παντοίων κειμηλίων ταῖς οἰκίαις."},{"number":411,"text":"Ἱεριχοῦντος μὲν οὖν φρουρὰν καταλιπὼν ὁ βασιλεὺς ὑπέστρεψεν καὶ χειμάσουσαν τὴν Ῥωμαίων στρατιὰν εἰς τὰς προσκεχωρηκυίας διαφῆκεν Ἰδουμαίαν καὶ Γαλιλαίαν καὶ Σαμάρειαν."},{"number":412,"text":"ἔτυχεν δὲ καὶ Ἀντίγονος παρὰ Σίλωνος ἀντὶ τῆς δωροδοκίας ὥστε ὑποδέξασθαι τοῦ στρατοῦ μοῖραν ἐν Λύδδοις θεραπεύων Ἀντώνιον. καὶ Ῥωμαῖοι μὲν ἐν ἀφθόνοις διῆγον ἀνειμένοι τῶν ὅπλων."},{"number":413,"text":"Ἡρώδῃ δʼ οὐκ ἐδόκει μένειν ἐφʼ ἡσυχίας, ἀλλʼ ἐπὶ τὴν Ἰδουμαίαν τὸν ἀδελφὸν Ἰώσηπον σὺν δισχιλίοις ὁπλίταις καὶ τετρακοσίοις ἱππεῦσιν ἐξέπεμψεν, αὐτὸς δʼ εἰς Σαμάρειαν παραγενόμενος καὶ καταθέμενος αὐτόθι τήν τε μητέρα καὶ τοὺς συγγενεῖς ἐξεληλυθότας ἤδη ἐκ τῶν Μασάδων ἐπὶ Γαλιλαίας ᾤχετο ἐξαιρήσων τινὰ τῶν χωρίων ὑπʼ Ἀντιγόνου φρουραῖς κατειλημμένα."},{"number":414,"text":"διελθὼν δὲ εἰς Σέπφωριν νίφοντος τοῦ θεοῦ καὶ τῶν Ἀντιγόνου φρουρῶν ὑπεξελθόντων ἐν ἀφθόνοις ἦν τοῖς ἐπιτηδείοις."},{"number":415,"text":"εἶτʼ ἐκεῖθεν λῃστῶν τινων ἐν σπηλαίοις κατοικούντων ἱππέων ἐπʼ αὐτοὺς ἴλην ἐκπέμπει καὶ ὁπλιτικοῦ τρία τέλη παῦσαι κακουργοῦντας ἐγνωκώς·"},{"number":416,"text":"ἔγγιστα δʼ ἦν ταῦτα κώμης Ἀρβήλων λεγομένης. εἰς δὲ τεσσαρακοστὴν ἡμέραν αὐτὸς ἧκεν πανστρατιᾷ, καὶ θρασέως ἐξελθόντων τῶν πολεμίων κλίνεται μὲν τὸ εὐώνυμον αὐτῶν κέρας τῆς φάλαγγος, ἐπιφανεὶς δʼ αὐτὸς μετὰ στίφους τρέπει μὲν εἰς φυγὴν τοὺς πάλαι νικῶντας, ἀναστρέφει δὲ τοὺς φεύγοντας."},{"number":417,"text":"ἐνέκειτο δὲ διώκων τοὺς πολεμίους ἄχρι Ἰορδάνου ποταμοῦ φεύγοντας κατʼ ἄλλας ὁδούς, καὶ προσάγεται μὲν πᾶσαν τὴν Γαλιλαίαν πλὴν τῶν ἐν τοῖς σπηλαίοις κατοικούντων, διανέμει δὲ καὶ ἀργύριον κατʼ ἄνδρα δοὺς ἑκατὸν καὶ πεντήκοντα δραχμάς, τοῖς δὲ ἡγεμόσιν πολὺ πλέον, εἰς τὰ χειμάδια διέπεμψεν."},{"number":418,"text":"καὶ ἐν τούτῳ Σίλων ἧκεν παρʼ αὐτὸν καὶ οἱ ἡγεμόνες τῶν ἐν τοῖς χειμαδίοις Ἀντιγόνου τροφὰς παρέχειν οὐ θέλοντος· μῆνα γὰρ οὐ πλέον αὐτοὺς ὁ ἀνὴρ ἔθρεψεν, διέπεμψεν δὲ καὶ πρὸς τοὺς κύκλῳ κελεύων τὰ κατὰ τὴν χώραν ἀνασκευάσασθαι καὶ εἰς τὰ ὄρη φεύγειν, ὡς μηδὲν ἔχοντες Ῥωμαῖοι λιμῷ διαφθαρεῖεν."},{"number":419,"text":"Ἡρώδης δὲ τὴν μὲν τούτων πρόνοιαν Φερώρᾳ τῷ νεωτάτῳ τῶν ἀδελφῶν ἐπιτρέπει κελεύσας αὐτὸν ἅμα τειχίζειν καὶ Ἀλεξάνδρειον. ὁ δὲ ταχέως τε τοὺς στρατιώτας ἐν ἀφθονίᾳ πολλῇ τῶν ἀναγκαίων ἐποίησεν τό τε Ἀλεξάνδρειον ἠρημωμένον ἀνέκτισεν."},{"number":420,"text":"Ὑπὸ δὲ τὸν αὐτὸν χρόνον Ἀντώνιος μὲν διέτριβεν ἐν Ἀθήναις, κατὰ δὲ Συρίαν Οὐεντίδιος Σίλωνα μεταπεμπόμενος ἐπὶ τοὺς Πάρθους ἐπέστελλεν πρῶτον μὲν Ἡρώδῃ συλλαμβάνεσθαι τοῦ πολέμου, ἔπειτα δὲ καὶ ἐπὶ τὸν σφέτερον καλεῖν τοὺς συμμάχους."},{"number":421,"text":"ὁ δʼ ἐπὶ τοὺς ἐν τοῖς σπηλαίοις λῃστὰς ἐπειγόμενος Σίλωνα μὲν ἐξέπεμψεν Οὐεντιδίῳ, αὐτὸς δʼ ἐπʼ ἐκείνους ἐξώρμησεν."},{"number":422,"text":"ἦν δʼ ἐν ὄρεσιν τὰ σπήλαια τελέως ἐξερρωγόσιν καὶ κατὰ τὸ μεσαίτατον ἀποκρήμνους ἔχοντα τὰς παρόδους καὶ πέτραις ὀξείαις ἐμπεριεχόμενα·"},{"number":423,"text":"ἐν δὴ τούτοις μετὰ πάντων τῶν οἰκείων ἐφώλευον. ὁ δὲ βασιλεὺς λάρνακας ἐπʼ αὐτοὺς πηξάμενος καθίει ταύτας σιδηραῖς ἁλύσεσιν ἐκδεδεμένας διὰ μηχανῆς ἀπὸ κορυφῆς τοῦ ὄρους, μήτε κάτωθεν ἀνιέναι διὰ τὴν ὀξύτητα τοῦ ὄρους δυναμένων μήτε ἄνωθεν καθέρπειν ἐπʼ αὐτούς."},{"number":424,"text":"αἱ δὲ λάρνακες πλήρεις ὁπλιτῶν ὑπῆρχον ἅρπας μεγάλας ἐχόντων, αἷς ἔμελλον ἐπισπώμενοι τοὺς ἀνθεστῶτας τῶν λῃστῶν κτείνειν καταφερομένους. τὴν μέντοι γε κάθεσιν τῶν λαρνάκων σφαλερὰν εἶναι συνέβαινεν κατὰ βάθους ἀπείρου γινομένην· ἔνδον μέντοι καὶ τὰ ἐπιτήδεια παρῆν αὐτοῖς."},{"number":425,"text":"ὡς δὲ καθιμήθησαν αἱ λάρνακες, ἐτόλμα δʼ οὐδεὶς προσελθεῖν τοῖς ἐπὶ τῶν στομίων, ἀλλʼ ὑπὸ δέους ἠρέμουν, μάχαιράν τις περιζωσάμενος τῶν ὁπλοφόρων καὶ ταῖν χεροῖν ἀμφοτέραιν δραξάμενος ἁλύσεως, ἀφʼ ἧς ἤρτητο ἡ λάρναξ, κατῄει ἐπὶ τὰ στόμια δυσχεράνας τὴν τριβὴν τῶν ἐπεξιέναι μὴ τολμώντων."},{"number":426,"text":"καὶ γενόμενος κατά τι στόμιον πρῶτα μὲν παλτοῖς ἀνακόπτει τοὺς πολλοὺς τῶν ἐπὶ τοῦ στομίου, ἔπειτα ἅρπῃ τοὺς ἀνθεστῶτας ἐπισπασάμενος ὠθεῖ κατὰ τοῦ κρημνοῦ, καὶ τοῖς ἔνδον ἐπεισελθὼν ἀποσφάττει τε πολλοὺς καὶ εἰσελθὼν εἰς τὴν λάρνακα ἡσύχασεν."},{"number":427,"text":"φόβος δὲ εἶχε τοὺς ἄλλους τῆς οἰμωγῆς ἀκούοντας καὶ περὶ τῆς σωτηρίας ἀπόγνωσις, τὸ μέντοι γε πᾶν ἔργον ἐπέσχεν ἐπεξελθοῦσιν· καὶ πολλοὶ συγχωρήσαντος τοῦ βασιλέως ἐπικηρυκευσάμενοι παρέδοσαν σφᾶς ὑπηκόους εἶναι."},{"number":428,"text":"τῷ δʼ αὐτῷ τρόπῳ καὶ κατὰ τὴν ἐπιοῦσαν ἐχρήσαντο τῇ προσβολῇ, μᾶλλον ἔτι τῶν ἐν τοῖς πήγμασιν ἐπεξιόντων αὐτοῖς καὶ κατὰ θύρας μαχομένων πῦρ τε ἐνιέντων."},{"number":429,"text":"ἐξαφθέντων τε τῶν ἄντρων, πολλὴ γὰρ ἦν ἐν αὐτοῖς ὕλη, πρεσβύτης τις ἀπειλημμένος ἔνδον σὺν ἑπτὰ τέκνοις καὶ γυναικί, δεομένων τούτων ἐᾶσαι σφᾶς ὑπεξελθεῖν πρὸς τοὺς πολεμίους, στὰς ἐπὶ τοῦ στομίου τὸν ἀεὶ πρῶτον ἐξιόντα τῶν παίδων ἀπέσφαττεν, εἰς ὃ πάντας διεχρήσατο, ἔπειτα δὲ καὶ τὴν γυναῖκα, καὶ ῥίψας κατὰ τοῦ κρημνοῦ τοὺς νεκροὺς ἐπικατέβαλεν ἑαυτὸν θάνατον πρὸ δουλείας ὑπομένων."},{"number":430,"text":"πολλὰ δὲ πρῶτον ὠνείδισεν τὸν Ἡρώδην εἰς ταπεινότητα καί τοι τοῦ βασιλέως, ἦν γὰρ ἄποπτα αὐτῷ τὰ γινόμενα, δεξιάν τε προτείνοντος καὶ πᾶσαν ἄδειαν. τὰ μὲν οὖν σπήλαια τούτων γενομένων ἤδη πάντα ἐκεχείρωτο."},{"number":431,"text":"Καταστήσας δʼ ὁ βασιλεὺς τοῖς αὐτόθι στρατηγὸν Πτολεμαῖον εἰς Σαμάρειαν ᾤχετο σὺν ἱππεῦσιν ἑξακοσίοις ὁπλίταις δὲ τρισχιλίοις ὡς μάχῃ κριθησόμενος πρὸς Ἀντίγονον."},{"number":432,"text":"οὐ μὴν τῷ Πτολεμαίῳ προυχώρησεν τὰ κατὰ τὴν στρατηγίαν, ἀλλʼ οἱ καὶ πρότερον τὴν Γαλιλαίαν ταράξαντες ἐπεξελθόντες αὐτὸν διεχρήσαντο καὶ τοῦτο δράσαντες συμφεύγουσιν εἴς τε τὰ ἕλη καὶ τὰ δύσβατα τῶν χωρίων, ἄγοντες καὶ διαρπάζοντες τὴν αὐτόθι πᾶσαν."},{"number":433,"text":"τιμωρεῖται δὲ τούτους Ἡρώδης ἐπανελθών· τοὺς μὲν γὰρ ἀναιρεῖ τῶν ἀποστάντων, τοὺς δʼ ἀναφυγόντας εἰς ἐρυμνὰ χωρία πολιορκίᾳ παραστησάμενος αὐτούς τε ἀπέκτεινεν καὶ τὰ ἐρύματα κατέσκαψεν. ἐζημίωσε δὲ παύσας οὕτως τὴν νεωτεροποιίαν καὶ τὰς πόλεις ἑκατὸν ταλάντοις."},{"number":434,"text":"Ἐν δὲ τῷ μεταξὺ Πακόρου πεσόντος ἐν μάχῃ καὶ τῶν Πάρθων πταισάντων πέμπει βοηθὸν ὁ Βεντίδιος Ἡρώδῃ Μαχαιρᾶν σὺν δυσὶ τάγμασι καὶ χιλίοις ἱππεῦσιν ἐπισπεύδοντος Ἀντωνίου."},{"number":435,"text":"Μαχαιρᾶς μὲν οὖν Ἀντιγόνου καλοῦντος αὐτὸν παρὰ τὴν Ἡρώδου γνώμην χρήμασι διεφθαρμένος ἀπῄει ὡς κατασκεψόμενος αὐτοῦ τὰ πράγματα. τὴν δὲ διάνοιαν ὑπιδόμενος αὐτοῦ τὴν τῆς ἀφίξεως Ἀντίγονος οὐδὲ προσεδέξατο, ἀλλὰ σφενδόναις βάλλων αὐτὸν ἀνεῖργεν, καὶ διεδήλου τὴν αὐτοῦ προαίρεσιν."},{"number":436,"text":"αἰσθόμενος δὲ τὰ βέλτιστα Ἡρώδην αὐτῷ παραινοῦντα καὶ αὐτὸν διημαρτηκότα παρακούσαντα τῆς ἐκείνου συμβουλίας, ἀνεχώρει μὲν εἰς Ἀμμαοῦν πόλιν, οἷς δὲ κατὰ τὴν ὁδὸν Ἰουδαίοις περιετύγχανεν τούτους ἀπέσφαττεν ἐχθρούς τε καὶ φίλους ὀργιζόμενος ὑπὲρ ὧν πεπόνθει."},{"number":437,"text":"παροξυνθεὶς δʼ ἐπὶ τούτοις ὁ βασιλεὺς ἐπὶ Σαμαρείας ᾔει· πρὸς γὰρ Ἀντώνιον ἐγνώκει περὶ τούτων ἀφικέσθαι· δεῖσθαι γὰρ οὐχὶ τοιούτων συμμάχων, οἳ βλάψουσι μᾶλλον αὐτὸν ἢ τοὺς πολεμίους· ἐξαρκεῖν δὲ καὶ αὐτῷ πρὸς τὴν Ἀντιγόνου καθαίρεσιν."},{"number":438,"text":"παρακολουθῶν δʼ ὁ Μαχαιρᾶς ἐδεῖτο μένειν· εἰ δὲ οὕτως ὥρμηκεν, ἀλλὰ τόν γε ἀδελφὸν αὐτοῦ Ἰώσηπον παρακαθιστάνειν σφίσι προσπολεμοῦσιν Ἀντιγόνῳ. καὶ διαλλάττεται μὲν πολλὰ τοῦ Μαχαιρᾶ δεηθέντος, καταλιπὼν δὲ τὸν Ἰώσηπον αὐτόθι σὺν στρατῷ παρῄνεσεν μὴ ἀποκινδυνεύειν μηδὲ τῷ Μαχαιρᾷ διαφέρεσθαι."},{"number":439,"text":"Αὐτὸς δὲ πρὸς Ἀντώνιον ἔσπευδεν, ἐτύγχανεν γὰρ πολιορκῶν Σαμόσατα τὸ πρὸς τῷ Εὐφράτῃ χωρίον, σὺν ἱππόταις τε καὶ πεζοῖς κατὰ συμμαχίαν αὐτῷ παροῦσιν."},{"number":440,"text":"παραγενόμενος δʼ εἰς Ἀντιόχειαν καὶ πολλοῖς ἐπιτυχὼν ἠθροισμένοις καὶ πρὸς Ἀντώνιον μὲν σπουδὴν βαδίζειν ἔχουσιν, ὑπὸ δέους δὲ διὰ τὸ κατὰ τὰς ὁδοὺς ἐπιτίθεσθαι τοὺς βαρβάρους καὶ πολλοὺς ἀναιρεῖν οὐ τολμῶντας ἐξορμᾶν, παραθαρσύνας αὐτὸς ἡγεμὼν γίνεται τῆς ὁδοῦ."},{"number":441,"text":"κατὰ δὲ σταθμὸν δεύτερον τῶν Σαμοσάτων ἐλόχα μὲν αὐτόθι τῶν βαρβάρων ἐνέδρα τοὺς φοιτῶντας πρὸς Ἀντώνιον, δρυμῶν δὲ τὰς εἰσβολὰς τὰς εἰς τὰ πεδία διαλαμβανόντων προλοχίζουσιν αὐτόθι τῶν ἱππέων οὐκ ὀλίγους ἠρεμήσοντας ἕως ἂν εἰς τὸ ἱππήλατον οἱ διεξιόντες ἔλθοιεν."},{"number":442,"text":"ὡς δʼ οἱ πρῶτοι διεξῆλθον, ὀπισθοφυλακεῖ μὲν Ἡρώδης, προσπίπτουσι δὲ ἐξαπιναίως οἱ ἐκ τῆς ἐνέδρας ὄντες εἰς πεντακοσίους, καὶ τρεψαμένων τοὺς πρώτους ἐπιδραμὼν ὁ βασιλεὺς τῇ ῥύμῃ τῇ περὶ αὐτὸν παραχρῆμα μὲν ἀνακόπτει τοὺς πολεμίους, ἐπεγείρει δὲ τὸ τῶν οἰκείων φρόνημα καὶ θαρραλέους ἀπεργάζεται, καὶ τῶν πάλαι φευγόντων ἐξ ὑποστροφῆς μαχομένων ἐκτείνοντο πάντοθεν οἱ βάρβαροι."},{"number":443,"text":"ἐπέκειτο δʼ ὁ βασιλεὺς ἀναιρῶν καὶ τὰ διηρπασμένα, πολλὰ δʼ ἦν σκευοφόρα καὶ ἀνδράποδα, πάντα ἀνασωσάμενος προῄει."},{"number":444,"text":"καὶ πλειόνων αὐτοῖς ἐπιθεμένων τῶν ἐν τοῖς δρυμῶσιν, οἳ πλησίον τῆς εἰς τὸ πεδίον ἐκβολῆς ἦσαν, καὶ τούτοις προσμίξας αὐτὸς μετὰ στίφους καρτεροῦ τρέπεται καὶ πολλοὺς αὐτῶν ἀποκτείνας ἀδεᾶ τοῖς ἑπομένοις ὁδὸν παρεῖχεν· οἱ δὲ σωτῆρα καὶ προστάτην αὐτὸν ἐκάλουν."},{"number":445,"text":"Ἐπεὶ δὲ πλησίον τῶν Σαμοσάτων γεγόνει, πέμπει τὸ στράτευμα ὑπαντησόμενον Ἀντώνιος σὺν τῷ οἰκείῳ κόσμῳ τιμὴν Ἡρώδῃ ταύτην ἀπονέμων καὶ ἐπικουρίας ἕνεκα· τὴν γὰρ τῶν βαρβάρων ἀκηκόει κατʼ αὐτῶν ἐπίθεσιν."},{"number":446,"text":"καὶ δὴ παρόντα τε εἶδεν ἀσμένως καὶ τὰ κατὰ τὴν ὁδὸν αὐτῷ πεπραγμένα μαθὼν ἐδεξιοῦτο καὶ τῆς ἀρετῆς ἐθαύμαζεν, αὐτός τε περιλαβὼν αὐτὸν Ἀντώνιος ὡς εἶδεν ἠσπάζετο προυτίμα τε νεωστὶ βασιλέα ἀποδείξας."},{"number":447,"text":"Ἀντιόχου δὲ μετʼ οὐ πολὺ τὸ ἔρυμα παραδόντος καὶ διὰ τοῦτο παυσαμένου τοῦ πολέμου Σοσσίῳ μὲν Ἀντώνιος παραδίδωσιν παρακελευσάμενος δὲ Ἡρώδῃ συμμαχεῖν αὐτὸς ἐπʼ Αἰγύπτου ἐχώρει. καὶ Σόσσιος μὲν δύο τάγματα ἐπικουρικὰ Ἡρώδῃ προύπεμψεν εἰς τὴν Ἰουδαίαν, αὐτὸς δὲ μετὰ τοῦ πλείονος στρατοῦ ἠκολούθει."},{"number":448,"text":"Ἔτυχεν δʼ ἤδη κατὰ τὴν Ἰουδαίαν τεθνεὼς Ἰώσηπος τρόπῳ τοιούτῳ· λήθην μὲν ὧν αὐτῷ παρήγγειλεν ὁ ἀδελφὸς πρὸς Ἀντώνιον ἀπερχόμενος λαμβάνει, στρατοπεδευσάμενος δὲ ἀνὰ τὰ ὄρη, πέντε γὰρ αὐτῷ σπείρας Μαχαιρᾶ δόντος ἐπὶ Ἱεριχοῦντος ἠπείγετο βουλόμενος ἐκθερίσαι τὸν σῖτον αὐτῶν,"},{"number":449,"text":"καὶ νεοσυλλέκτου τοῦ Ῥωμαίων στρατεύματος ὄντος, καὶ πολέμων ἀπείρως ἔχοντος καὶ γὰρ πολὺ ἐκ Συρίας ἦν τὸ κατειλεγμένον, ἐπιθεμένων αὐτόθι τῶν πολεμίων, ἀποληφθεὶς ἐν δυσχωρίαις αὐτός τε ἀποθνήσκει γενναίως μαχόμενος καὶ τὸ στράτευμα πᾶν ἀπέβαλεν· ἓξ γὰρ σπεῖραι διεφθάρησαν."},{"number":450,"text":"κρατήσας δὲ τῶν νεκρῶν Ἀντίγονος ἀποτέμνει τὴν Ἰωσήπου κεφαλὴν πεντήκοντα ταλάντων αὐτὴν ῥυομένου Φερώρα τἀδελφοῦ. καὶ μετὰ τοῦτο ἀποστάντες Γαλιλαῖοι τῶν παρὰ σφίσι δυνατῶν τοὺς τὰ Ἡρώδου φρονοῦντας ἐν τῇ λίμνῃ κατεπόντωσαν, καὶ τῆς Ἰουδαίας πολλὰ ἐνεωτερίσθη. Μαχαιρᾶς δὲ χωρίον Ηττον ἐξωχύρου."},{"number":451,"text":"Παρῆσαν δʼ ἄγγελοι τῶν πεπραγμένων πρὸς τὸν βασιλέα καὶ ἐν Δάφνῃ τῆς Ἀντιοχείας ἐδήλωσαν αὐτῷ τὴν κατὰ τὸν ἀδελφὸν τύχην, προσδεχομένῳ μέντοι καὶ αὐτῷ διά τινας ὀνείρων ὄψεις τρανῶς προφαινούσας τὸν τοῦ ἀδελφοῦ θάνατον."},{"number":452,"text":"ἐπειχθεὶς οὖν κατὰ τὴν πορείαν ὡς κατὰ Λίβανον τὸ ὄρος γίνεται, ὀκτακοσίους μὲν τῶν αὐτόθι προσλαμβάνει, ἔχων δὲ καὶ Ῥωμαϊκὸν ἓν τάγμα εἰς Πτολεμαΐδα παραγίνεται, κἀκεῖθεν νυκτὸς ἀναστὰς μετὰ τοῦ στρατοῦ προῄει διὰ τῆς Γαλιλαίας."},{"number":453,"text":"ὑπήντων δʼ οἱ πολέμιοι καὶ κρατηθέντες τῇ μάχῃ κατεκλείσθησαν εἰς χωρίον, ὅθεν ἦσαν ὡρμηκότες τῇ προτεραίᾳ· προσβολὰς δὴ τοὐντεῦθεν ἕωθεν ἐποιεῖτο, καὶ πολλοῦ χειμῶνος καταρραγέντος οὐδὲν ποιεῖν δυνάμενος ἀπάγει τὴν στρατιὰν εἰς τὰς πλησίον κώμας. ἐλθόντος δʼ αὐτῷ παρʼ Ἀντωνίου καὶ δευτέρου τάγματος οἱ τὸ χωρίον ἔχοντες φοβηθέντες νυκτὸς ἐξέλιπον αὐτό."},{"number":454,"text":"καὶ ὁ βασιλεὺς ἔσπευδεν ἐπὶ Ἱεριχοῦντος τιμωρήσασθαι κατὰ νοῦν ἔχων αὐτοὺς ὑπὲρ τἀδελφοῦ. ἐπεὶ δὲ κατέζευξεν, εἱστία μὲν τοὺς ἐν τέλει, μετὰ δὲ τὴν συνουσίαν παρῆλθεν εἰς τὸ δωμάτιον ἀπολύσας τοὺς παρόντας."},{"number":455,"text":"ἐνταῦθα ἴδοι τις ἂν τοῦ βασιλέως τὴν ἐκ τοῦ θεοῦ εὔνοιαν· πίπτει μὲν γὰρ ἡ στέγη τοῦ οἰκήματος, οὐδένα δὲ ἀπολαβοῦσα διέφθειρεν, ὥστε πάντας πιστεῦσαι τὸν Ἡρώδην εἶναι θεοφιλῆ, μέγαν οὕτω καὶ παράδοξον διαφυγόντα κίνδυνον."},{"number":456,"text":"Τῇ δʼ ὑστεραίᾳ τῶν πολεμίων ἑξακισχίλιοι ἀπʼ ἄκρων κατιόντες τῶν ὀρῶν εἰς μάχην ἐφόβουν τοὺς Ῥωμαίους. οἱ δὲ γυμνῆτες προσιόντες τοῖς παλτοῖς ἔβαλλον καὶ λίθοις τοὺς περὶ τὸν βασιλέα ἐξεληλυθότας αὐτόν τε παλτῷ τις παρὰ τὴν λαπάραν ἔβαλεν."},{"number":457,"text":"Ἀντίγονος δʼ ἐπὶ τὴν Σαμάρειαν πέμπει στρατηγὸν Πάππον ὄνομα σὺν δυνάμει πολλῇ βουλόμενος παρασχεῖν τοῖς πολεμίοις δόξαν πολεμοῦντος ἐκ περιουσίας. ἀλλʼ ὁ μὲν Μαχαιρᾷ τῷ στρατηγῷ προσεκάθητο· Ἡρώδης δὲ πέντε πόλεις καταλαβὼν τοὺς ἐγκαταληφθέντας περὶ δισχιλίους ὄντας ἐφόνευσεν αὐτάς τε τὰς πόλεις ἐμπρήσας ἐπανῆλθεν ἐπὶ τὸν Πάππον·"},{"number":458,"text":"ἐστρατοπεδεύσατο δʼ οὗτος περὶ κώμην Ἰσάνας καλουμένην καὶ πολλῶν αὐτῷ προσρεόντων ἐκ τῆς Ἱεριχοῦς καὶ τῆς ἄλλης Ἰουδαίας, ἐπεὶ πλησίον γίνεται, τῶν πολεμίων ἐπεξελθόντων αὐτοῖς ὑπὸ θράσους συμβαλὼν κρατεῖ τῇ μάχῃ, καὶ τιμωρῶν τἀδελφῷ φεύγουσιν εἰς τὴν κώμην εἵπετο κτείνων."},{"number":459,"text":"πεπληρωμένων δὲ τῶν οἰκήσεων ὁπλιτῶν καί τινων ἀναφευγόντων ἐπὶ τὰς στέγας κρατεῖ τούτων, καὶ τοὺς ὀρόφους τῶν οἴκων ἀνασκάπτων ἔμπλεα τὰ κάτω τῶν στρατιωτῶν ἑώρα ἀθρόων ἀπειλημμένων."},{"number":460,"text":"τούτους μὲν οὖν πέτραις ἄνωθεν βάλλοντες σωρηδὸν ἐπʼ ἀλλήλοις ἀνῄρουν· καὶ θέαμα τοῦτο δεινότατον ἦν κατὰ τόνδε τὸν πόλεμον νεκρῶν τὸ πλῆθος ἀπείρων ἐντὸς τῶν τειχῶν ἐπʼ ἀλλήλοις κειμένων."},{"number":461,"text":"τοῦτο τὸ ἔργον μάλιστα τὰ φρονήματα τῶν πολεμίων ἔκλασεν καραδοκούντων τὸ μέλλον· ἑωρῶντο γὰρ παμπληθεῖς πόρρωθεν συγγενόμενοι περὶ τὴν κώμην· οἳ τότε ἔφευγον, καὶ εἰ μὴ χειμὼν ἐπέσχεν βαθύς, ἧκεν ἂν καὶ ἐπὶ Ἱεροσόλυμα ἡ βασιλέως στρατιὰ θαρροῦσα τῷ νενικηκέναι, καὶ τὸ πᾶν ἦν ἂν εἰργασμένη· καὶ γὰρ Ἀντίγονος ἤδη τὴν παντελῆ φυγὴν ἐσκόπει καὶ ἀπανάστασιν ἐκ τῆς πόλεως."},{"number":462,"text":"Τότε μὲν οὖν ὁ βασιλεύς, ὀψία γὰρ ἦν, δειπνοποιεῖσθαι κελεύει τοὺς στρατιώτας, αὐτὸς δέ, ἐκεκμήκει γάρ, εἰσελθὼν εἴς τι δωμάτιον περὶ λουτρὸν ἦν. ἔνθα καὶ κίνδυνος αὐτῷ μέγιστος συνέπεσεν, ὃν κατὰ θεοῦ πρόνοιαν διέφυγεν·"},{"number":463,"text":"γυμνοῦ γὰρ ὄντος αὐτοῦ καὶ μετὰ παιδὸς ἑνὸς ἀκολούθου λουομένου ἐν τῷ ἐντὸς οἰκήματι τῶν πολεμίων τινὲς ὡπλισμένοι συμπεφευγότες αὐτόθι διὰ φόβον μεταξὺ λουομένου ὁ πρῶτος ὑπεξέρχεται ξίφος ἔχων γυμνὸν καὶ διὰ θυρῶν χωρεῖ, καὶ μετὰ τοῦτον δεύτερος καὶ τρίτος ὁμοίως ὡπλισμένοι, οὐδὲν βλάψαντες τὸν βασιλέα ὑπʼ ἐκπλήξεως, ἀγαπῶντες δὲ τὸ μηδὲν αὐτοὶ παθόντες εἰς τὸ πρόσθεν διεκπεσεῖν."},{"number":464,"text":"τῇ δʼ ὑστεραίᾳ τὴν μὲν Πάππου κεφαλήν, ἀνῄρητο γάρ, ἀποκόψας Φερώρᾳ ἔπεμψεν ποινὴν ἀνθʼ ὧν ὁ ἀδελφὸς αὐτοῦ πάθοι· οὗτος γὰρ ἦν αὐτόχειρ ἐκείνου γεγενημένος."},{"number":465,"text":"Λήξαντος δὲ τοῦ χειμῶνος ἄρας ἐκεῖθεν ἐγγὺς τῶν Ἱεροσολύμων ἔρχεται καὶ πλησίον στρατοπεδεύεται τῆς πόλεως· τρίτον δὲ ἔτος τοῦτο ἦν αὐτῷ ἐξ οὗ βασιλεὺς ἐν Ῥώμῃ ἀποδέδεικτο."},{"number":466,"text":"ἀναστρατοπεδευσάμενος δὲ καὶ πλησίον ἐλθὼν τοῦ τείχους κατὰ τὸ ἐπιμαχώτατον πρὸ τοῦ ἱεροῦ στρατοπεδεύεται προσβαλεῖν διεγνωκώς, ὡς καὶ πρότερόν ποτε Πομπήιος. τρισὶν δὲ διαλαβὼν χώμασιν τὸν τόπον πύργους ἀνίστα πολλῇ τε χειρὶ πρὸς τὸ ἔργον χρώμενος καὶ τέμνων τὴν πέριξ ὕλην."},{"number":467,"text":"παρακαταστήσας δὲ τοῖς ἔργοις τοὺς ἐπιτηδείους, ἱδρυμένης ἔτι τῆς στρατιᾶς αὐτὸς εἰς Σαμάρειαν ἐπὶ τὸν γάμον ᾤχετο ἀξόμενος τὴν Ἀλεξάνδρου τοῦ Ἀριστοβούλου θυγατέρα· ταύτην γὰρ ἦν ἐγγεγυημένος, ὥς μοι καὶ πρότερον εἴρηται."}],"16":[{"number":468,"text":"Μετὰ δὲ τοὺς γάμους ἦλθεν μὲν διὰ Φοινίκης Σόσσιος προεκπέμψας τὴν δύναμιν διὰ τῆς μεσογαίας, ἦλθεν δὲ καὶ ὁ στρατὸς πλῆθος ἱππέων τε καὶ πεζῶν, παρεγένετο δὲ καὶ ὁ βασιλεὺς ἐκ τῆς Σαμαρείτιδος οὐκ ὀλίγον πρὸς τῷ πάλαι στρατὸν ἄγων·"},{"number":469,"text":"περὶ τρισμυρίους γὰρ ἦσαν. πάντες δʼ ἐπὶ τὸ Ἱεροσολυμιτῶν ἠθροίζοντο τεῖχος, καὶ διεκάθητο πρὸς τῷ βορείῳ τείχει τῆς πόλεως στρατιᾶς ἕνδεκα μὲν οὖσα τέλη ὁπλιτικοῦ, ἓξ δὲ χιλιάδες ἱππέων, ἄλλα δὲ ἐπικουρικὰ ἀπὸ τῆς Συρίας, δύο δʼ ἡγεμόνες, Σόσσιος μὲν ὑπʼ Ἀντωνίου σταλεὶς σύμμαχος, Ἡρώδης δʼ ὑπὲρ αὐτοῦ, ὡς Ἀντίγονον ἀφελόμενος τὴν ἀρχὴν ἀποδειχθέντα ἐν Ῥώμῃ πολέμιον αὐτὸς ἀντʼ ἐκείνου βασιλεὺς εἴη κατὰ τὸ τῆς συγκλήτου δόγμα."},{"number":470,"text":"Μετὰ δὲ πολλῆς προθυμίας καὶ ἔριδος ἅτε σύμπαντος ἠθροισμένου τοῦ πλήθους οἱ Ἰουδαῖοι τοῖς περὶ τὸν Ἡρώδην ἀντεπολέμουν κατειληθέντες ἐντὸς τοῦ τείχους, πολλά τε ἐπεφήμιζον περὶ τὸ ἱερὸν καὶ πολλὰ ἐπʼ εὐφημίᾳ τοῦ δήμου, ὡς ῥυσομένου τῶν κινδύνων αὐτοὺς τοῦ θεοῦ."},{"number":471,"text":"τά τε ἐκτὸς τῆς πόλεως ἀπεσκευάσαντο, ὡς μηδʼ ὅσα τροφὴ δύναιτο εἶναι ὑπολιπεῖν ἢ ἀνθρώποις ἢ ὑποζυγίοις, λῃστείαις τε λάθρα χρώμενοι ἀπορίαν παρέσχον."},{"number":472,"text":"ταῦτα δʼ Ἡρώδης συνιδὼν πρὸς μὲν τὰς λῃστείας ἐν τοῖς ἐπικαιροτάτοις τόποις παρελόχιζεν, πρὸς δὲ τὰ ἐπιτήδεια πέμπων ὁπλιτικὰ τέλη πόρρωθεν ἀγορὰν συνεκόμιζεν, ὡς ὀλίγου χρόνου πολλὴν ἀφθονίαν αὐτοῖς γενέσθαι τῶν ἀναγκαίων."},{"number":473,"text":"ἦρτο δὲ συνεχῶς ἤδη πολλῆς χειρὸς ἐργαζομένης καὶ τὰ τρία χώματα εὐπετῶς· θέρος τε γὰρ ἦν καὶ οὐδὲν ἐμποδὼν πρὸς τὴν ἀνάστασιν οὔτʼ ἀπὸ τοῦ ἀέρος οὔτʼ ἀπὸ τῶν ἐργαζομένων, τά τε μηχανήματα προσάγοντες κατέσειον τὸ τεῖχος καὶ πάσαις ἐχρῶντο πείραις."},{"number":474,"text":"οὐ μὴν ἐξέπληττον τοὺς ἔνδον, ἀλλὰ ἀντετεχνῶντο κἀκεῖνοι πρὸς τὰ παρὰ τούτων γινόμενα οὐκ ὀλίγα, ἐπεκθέοντές τε τὰ μὲν ἡμίεργα ἐνεπίμπρασαν τὰ δʼ ἐξειργασμένα, εἴς τε χεῖρας ἰόντες οὐδὲν κακίους τὰς τόλμας Ῥωμαίων ἦσαν, ἐπιστήμῃ δʼ ἐλείποντο."},{"number":475,"text":"πρός τε τὰς μηχανὰς ἀντετείχιζον ἐρειπομένων τῶν πρώτων οἰκοδομημάτων, ὑπὸ γῆν τε ἀπαντῶντες ἐν ταῖς μεταλλεύσεσιν διεμάχοντο, ἀπονοίᾳ δὲ τὸ πλέον ἢ προμηθείᾳ χρώμενοι προσελιπάρουν τῷ πολέμῳ εἰς τοὔσχατον, καὶ ταῦτα μεγάλου στρατοῦ περικαθημένου σφᾶς καὶ λιμῷ ταλαιπωρούμενοι καὶ σπάνει τῶν ἐπιτηδείων· τὸν γὰρ ἑβδοματικὸν ἐνιαυτὸν συνέβη κατὰ ταῦτʼ εἶναι."},{"number":476,"text":"ἀναβαίνουσιν δὲ ἐπὶ τὸ τεῖχος πρῶτον μὲν λογάδες εἴκοσι, ἔπειτα δὲ ἑκατόνταρχοι Σοσσίου· ᾑρέθη γὰρ τὸ μὲν πρῶτον τεῖχος ἡμέραις τεσσαράκοντα, τὸ δὲ δεύτερον πεντεκαίδεκα· καί τινες τῶν περὶ τὸ ἱερὸν ἐνεπρήσθησαν στοῶν, ἃς Ἡρώδης Ἀντίγονον ἐμπρῆσαι διέβαλεν, μῖσος αὐτῷ πραγματευόμενος παρὰ τῶν Ἰουδαίων γενέσθαι."},{"number":477,"text":"ᾑρημένου δὲ τοῦ ἔξωθεν ἱεροῦ καὶ τῆς κάτω πόλεως εἰς τὸ ἔσωθεν ἱερὸν καὶ τὴν ἄνω πόλιν οἱ Ἰουδαῖοι συνέφυγον, δείσαντες δὲ μὴ διακωλύσωσιν αὐτοὺς οἱ Ῥωμαῖοι τὰς καθημερινὰς θυσίας ἐπιτελεῖν τῷ θεῷ, πρεσβεύονται ἐπιτρέψαι παρακαλοῦντες θύματα αὐτοῖς μόνον εἰσκομίζεσθαι· ὁ δʼ ὡς ἐνδωσόντων αὐτῶν συνεχώρει ταῦτα."},{"number":478,"text":"καὶ ἐπεὶ μηδὲν ἑώρα γινόμενον παρʼ αὐτῶν ὧν ὑπενόει, ἀλλὰ ἰσχυρῶς ἀντέχοντας ὑπὲρ τῆς Ἀντιγόνου βασιλείας, προσβαλὼν κατὰ κράτος εἷλεν τὴν πόλιν."},{"number":479,"text":"καὶ πάντα εὐθὺς φόνων ἦν ἀνάπλεα τῶν μὲν Ῥωμαίων ἐπὶ τῇ τριβῇ τῆς πολιορκίας διωργισμένων, τοῦ δὲ περὶ Ἡρώδην Ἰουδαϊκοῦ μηδὲν ὑπολιπεῖν σπεύδοντος ἀντίπαλον."},{"number":480,"text":"ἐσφάττοντο δὲ παμπληθεῖς ἔν τε τοῖς στενωποῖς καὶ κατὰ τὰς οἰκίας συνωθούμενοι καὶ τῷ ναῷ προσφεύγοντες, ἦν τε οὔτε νηπίων οὔτε γήρως ἔλεος οὔτε ἀσθενείας γυναικῶν φειδώ, ἀλλὰ καίτοι περιπέμποντος τοῦ βασιλέως καὶ φείδεσθαι παρακαλοῦντος οὐδεὶς ἐκράτησεν τῆς δεξιᾶς, ἀλλʼ ὥσπερ μεμηνότες πᾶσαν ἡλικίαν ἐπεξῄεσαν."},{"number":481,"text":"ἔνθα καὶ Ἀντίγονος μήτε τῆς πάλαι μήτε τῆς τότε τύχης ἔννοιαν λαβὼν κάτεισι μὲν ἀπὸ τῆς βάρεως, προσπίπτει δὲ τοῖς Σοσσίου ποσίν, κἀκεῖνος μηδὲν αὐτὸν οἰκτείρας πρὸς τὴν μεταβολὴν ἐπεκρότησεν μὲν ἀκρατῶς καὶ Ἀντιγόνην ἐκάλεσεν, οὐ μὴν ὡς γυναῖκά γε φρουρᾶς ἐλεύθερον ἀφῆκεν, ἀλλʼ ὁ μὲν δεθεὶς ἐφυλάττετο."},{"number":482,"text":"Πρόνοια δʼ ἦν Ἡρώδῃ κρατοῦντι τῶν πολεμίων τοῦ κρατῆσαι καὶ τῶν ἀλλοφύλων συμμάχων· ὥρμητο γὰρ τὸ ξενικὸν πλῆθος ἐπὶ θέᾳ τοῦ τε ἱεροῦ καὶ τῶν κατὰ τὸν ναὸν ἁγίων."},{"number":483,"text":"ὁ δὲ βασιλεὺς τοὺς μὲν παρακαλῶν τοὺς δʼ ἀπειλῶν ἔστιν δʼ οὓς καὶ τοῖς ὅπλοις ἀνέστελλεν, ἥττης χαλεπωτέραν ἡγούμενος τὴν νίκην, εἴ τι τῶν ἀθεάτων παρʼ αὐτῶν ὀφθείη."},{"number":484,"text":"διεκώλυέ τε καὶ τὰς κατὰ τὴν πόλιν ἁρπαγάς, πολλὰ διατεινάμενος πρὸς Σόσσιον, εἰ χρημάτων τε καὶ ἀνδρῶν Ῥωμαῖοι τὴν πόλιν κενώσαντες καταλείψουσιν αὐτὸν ἐρημίας βασιλέα, καὶ ὡς ἐπὶ τοσούτῳ πολιτῶν φόνῳ βραχὺ καὶ τὴν τῆς οἰκουμένης ἡγεμονίαν ἀντάλλαγμα κρίνει."},{"number":485,"text":"τοῦ δὲ ἀντὶ τῆς πολιορκίας τὰς ἁρπαγὰς δικαίως τοῖς στρατιώταις ἐπιτρέπειν φαμένου, αὐτὸς ἔφη διανεμεῖν ἐκ τῶν ἰδίων χρημάτων τοὺς μισθοὺς ἑκάστοις."},{"number":486,"text":"οὕτως τε τὴν λοιπὴν ἐξωνησάμενος πόλιν τὰς ὑποσχέσεις ἐπλήρωσεν· λαμπρῶς μὲν γὰρ ἕκαστον στρατιώτην, ἀναλόγως δὲ τοὺς ἡγεμόνας, βασιλικώτατα δʼ αὐτὸν ἐδωρήσατο Σόσσιον, ὡς πάντας ἀπελθεῖν χρημάτων εὐποροῦντας."},{"number":487,"text":"Τοῦτο τὸ πάθος συνέβη τῇ Ἱεροσολυμιτῶν πόλει ὑπατεύοντος ἐν Ῥώμῃ Μάρκου Ἀγρίππα καὶ Κανιδίου Γάλλου ἐπὶ τῆς ἑκατοστῆς ὀγδοηκοστῆς καὶ πέμπτης ὀλυμπιάδος τῷ τρίτῳ μηνὶ τῇ ἑορτῇ τῆς νηστείας, ὥσπερ ἐκ περιτροπῆς τῆς γενομένης ἐπὶ Πομπηίου τοῖς Ἰουδαίοις συμφορᾶς·"},{"number":488,"text":"καὶ γὰρ ὑπʼ ἐκείνου τῇ αὐτῇ ἑάλωσαν ἡμέρᾳ μετὰ ἔτη εἰκοσιεπτά. Σόσσιος δὲ χρυσοῦν ἀναθεὶς τῷ θεῷ στέφανον ἀνέζευξεν ἀπὸ Ἱεροσολύμων Ἀντίγονον ἄγων δεσμώτην Ἀντωνίῳ."},{"number":489,"text":"δείσας δὲ Ἡρώδης μὴ φυλαχθεὶς Ἀντίγονος ὑπʼ Ἀντωνίου καὶ κομισθεὶς εἰς Ῥώμην ὑπʼ αὐτοῦ δικαιολογήσηται πρὸς τὴν σύγκλητον, ἐπιδεικνὺς αὐτὸν μὲν ἐκ βασιλέων, Ἡρώδην δὲ ἰδιώτην, καὶ ὅτι προσῆκεν αὐτοῦ βασιλεύειν τοὺς παῖδας διὰ τὸ γένος, εἰ καὶ αὐτὸς εἰς Ῥωμαίους ἐξήμαρτεν·"},{"number":490,"text":"ταῦτα φοβούμενος πολλοῖς χρήμασι πείθει τὸν Ἀντώνιον ἀνελεῖν Ἀντίγονον. οὗ γενομένου τοῦ δέους μὲν Ἡρώδης ἀπαλλάσσεται, παύεται δʼ οὕτως ἡ τοῦ Ἀσσαμωναίου ἀρχὴ μετὰ ἔτη ἑκατὸν εἰκοσιέξ. οἶκος λαμπρὸς οὗτος ἦν καὶ διάσημος γένους τε ἕνεκα καὶ τῆς ἱερατικῆς τιμῆς ὧν τε ὑπὲρ τοῦ ἔθνους οἱ γονεῖς αὐτοῦ διεπράξαντο."},{"number":491,"text":"ἀλλʼ οὗτοι μὲν διὰ τὴν πρὸς ἀλλήλους στάσιν τὴν ἀρχὴν ἀπέβαλον, μετέβη δʼ εἰς Ἡρώδην τὸν Ἀντιπάτρου οἰκίας ὄντα δημοτικῆς καὶ γένους ἰδιωτικοῦ καὶ ὑπακούοντος τοῖς βασιλεῦσιν. καὶ τοῦτο μὲν τὸ τέλος τῆς Ἀσσαμωναίων γενεᾶς παρειλήφαμεν."}]},"count":491};a[15]={"book":15,"title":"Τάδε ἔνεστιν ἐν τῇ πεντεκαιδεκάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς ληφθείσης τῆς Ἱεροσολυμιτῶν πόλεως ὑπὸ Σοσσίου καὶ Ἡρώδου Ἀντώνιος μὲν Ἀντίγονον ἐπελέκισεν ἐν Ἀντιοχείᾳ, Ἡρώδης δὲ τεσσαρακονταπέντε τῶν ἐκείνου φίλων πρώτους Ἱεροσολυμιτῶν ἐπανείλετο καὶ τὴν πόλιν ἠργυρολόγησεν.\n\nὃν τρόπον Ὑρκανὸς ὁ πρῶτος βασιλεὺς Ἰουδαίων καὶ ἀρχιερεὺς ἀφεθεὶς ὑπὸ τοῦ τῶν Πάρθων βασιλέως Ἀρσάκου πρὸς Ἡρώδην ὑπέστρεψεν.\n\nὡς Ἡρώδης Ἀριστόβουλον τὸν τῆς γυναικὸς Μαριάμμης ἀδελφὸν ἀρχιερέα καταστήσας μετ' οὐ πολὺ διαφθαρῆναι παρεσκεύασεν.\n\nὡς Κλεοπάτρα τῇ τῶν Ἰουδαίων καὶ Ἀράβων ἐπιβουλεύουσα βασιλείᾳ μέρη λαβεῖν αὐτῶν ἴσχυνε παρ' Ἀντωνίου.\n\nΚλεοπάτρας εἰς τὴν Ἰουδαίαν παρουσία.\n\nὡς Ἡρώδης ἐπολέμησεν Ἀρέτᾳ καθ' ὃν καιρὸν Ἀντώνιος ὑπὸ Καίσαρος ἐν τῇ κατ' Ἄκτιον νικᾶται μάχῃ.\n\nπερὶ τοῦ γενομένου σεισμοῦ κατὰ τὴν Ἰουδαίαν καὶ τῆς φθορᾶς τῶν ἀνθρώπων καὶ τῶν βοσκημάτων.\n\nλόγος Ἡρώδου πρὸς τοὺς Ἰουδαίους ἀθυμοῦντας πρὸς τὰ πάθη καὶ τὴν ἧτταν τὴν γενομένην.\n\nὡς ἀνάγκην ἔχων Ἡρώδης ἀπιέναι πρὸς Καίσαρα νενικηκότα διέφθειρεν Ὑρκανόν.\n\nὡς ἔσχε καὶ παρὰ Καίσαρος τὴν βασιλείαν καὶ παρέπεμψεν αὐτὸν ἐπ' Αἰγύπτου.\n\nὡς Ἡρώδης ἀφικόμενος εἰς Ἀλεξάνδρειαν ὑπὸ Καίσαρος ἐτιμήθη.\n\nὡς ἐπανελθὼν ψευδέσι διαβολαῖς παρωξύνθη τὴν γυναῖκα Μαριάμμην ἀποκτεῖναι.\n\nπερὶ τοῦ λιμοῦ τοῦ κατὰ τὴν Ἰουδαίαν καὶ Συρίαν γεγονότος καὶ ὡς διέσωσε τὰ πλήθη καὶ τὰς πόλεις Ἡρώδης.\n\nκτίσεις πόλεων Ἑλληνίδων ἃς Ἡρώδης ἐποιήσατο.\n\nὡς καθελὼν ἐν Ἱεροσολύμοις τὸν ἀρχαῖον ναὸν ἄλλον ἀνέστησεν μετὰ ἔτη ἑξακόσια διπλοῦν τοῖς μέτροις.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ιη."},"chapters":{"1":[{"number":1,"text":"Σόσσιος μὲν οὖν καὶ Ἡρώδης ὡς κατὰ κράτος ἔλαβον Ἱεροσόλυμα καὶ πρὸς τούτοις αἰχμάλωτον Ἀντίγονον, ἡ πρὸ ταύτης ἡμῖν ἐδήλωσεν βίβλος· τὰ δʼ ἐκείνῃ συνεχῆ νῦν ἐροῦμεν."},{"number":2,"text":"ἐπειδὴ γὰρ τῆς ὅλης Ἰουδαίας ἐνεχειρίσθη τὴν ἀρχὴν Ἡρώδης, τοῦ κατὰ τὴν πόλιν πλήθους ὅσοι μὲν ἦσαν ἰδιωτεύοντες ἔτι τἀκείνου φρονοῦντες ἐν προαγωγῇ τούτους ἐποιεῖτο, τοὺς δὲ τὰ τῶν ἐναντίων ἑλομένους οὐκ ἐπέλιπε τιμωρούμενος καὶ κολάζων καθʼ ἑκάστην ἡμέραν."},{"number":3,"text":"ἐτιμῶντο δὲ μάλιστα παρʼ αὐτῷ Πολλίων ὁ Φαρισαῖος καὶ Σαμαίας ὁ τούτου μαθητής· πολιορκουμένων γὰρ τῶν Ἱεροσολύμων οὗτοι συνεβούλευον τοῖς πολίταις δέξασθαι τὸν Ἡρώδην, ἀνθʼ ὧν καὶ τὰς ἀμοιβὰς ἀπελάμβανον."},{"number":4,"text":"ὁ δὲ Πολλίων οὗτος καὶ κρινομένου ποτὲ Ἡρώδου τὴν ἐπὶ θανάτῳ προεῖπεν ὀνειδίζων Ὑρκανῷ καὶ τοῖς δικάζουσιν, ὡς περισωθεὶς Ἡρώδης ἅπαντας αὐτοὺς ἐπεξελεύσεται· καὶ τοῦτο χρόνῳ προύβη τοῦ θεοῦ τοὺς λόγους αὐτοῦ τελειώσαντος."},{"number":5,"text":"Ἐν δὲ τῷ τότε κρατήσας τῶν Ἱεροσολύμων πάντα συνεφόρει τὸν ἐν τῇ βασιλείᾳ κόσμον ἔτι καὶ τοὺς εὐπόρους ἀφαιρούμενος, καὶ συναγαγὼν πλῆθος ἀργυρίου καὶ χρυσίου παντὶ τούτῳ τὸν Ἀντώνιον ἐδωρεῖτο καὶ τοὺς περὶ αὐτὸν φίλους."},{"number":6,"text":"ἀπέκτεινε δὲ τεσσαρακονταπέντε τοὺς πρώτους ἐκ τῆς αἱρέσεως Ἀντιγόνου φύλακας περιστήσας ταῖς πύλαις τῶν τειχῶν, ἵνα μή τις συνεκκομισθῇ τοῖς τεθνεῶσι, καὶ τοὺς νεκροὺς ἠρεύνων, καὶ πᾶν τὸ εὑρισκόμενον ἀργύριον ἢ χρυσίον ἤ τι κειμήλιον ἀνεφέρετο τῷ βασιλεῖ,"},{"number":7,"text":"πέρας τε κακῶν οὐδὲν ἦν· τὰ μὲν γὰρ ἡ πλεονεξία τοῦ κρατοῦντος ἐν χρείᾳ γεγενημένου διεφόρει, τὴν δὲ χώραν μένειν ἀγεώργητον τὸ ἑβδοματικὸν ἠνάγκαζεν ἔτος· ἐνεστήκει γὰρ τότε, καὶ σπείρειν ἐν ἐκείνῳ τὴν γῆν ἀπηγορευμένον ἐστὶν ἡμῖν."},{"number":8,"text":"Ἀντώνιος δὲ λαβὼν αἰχμάλωτον τὸν Ἀντίγονον δέσμιον ἔγνω μέχρι θριάμβου φυλάττειν, ἐπεὶ δʼ ἤκουσεν νεωτερίζειν τὸ ἔθνος κἀκ τοῦ πρὸς Ἡρώδην μίσους εὔνουν Ἀντιγόνῳ διαμένον, ἔγνω τοῦτον ἐν Ἀντιοχείᾳ πελεκίσαι· σχεδὸν γὰρ οὐδαμῶς ἠρεμεῖν ἠδύναντο οἱ Ἰουδαῖοι."},{"number":9,"text":"μαρτυρεῖ δέ μου τῷ λόγῳ Στράβων ὁ Καππάδοξ λέγων οὕτως· Ἀντώνιος δὲ Ἀντίγονον τὸν Ἰουδαῖον ἀχθέντα εἰς Ἀντιόχειαν πελεκίζει. καὶ ἔδοξε μὲν οὗτος πρῶτος Ῥωμαίων βασιλέα πελεκίσαι, οὐκ οἰηθεὶς ἕτερον τρόπον μεταθεῖναι ἂν τὰς γνώμας τῶν Ἰουδαίων, ὥστε δέξασθαι τὸν ἀντʼ ἐκείνου καθεσταμένον Ἡρώδην· οὐδὲ γὰρ βασανιζόμενοι βασιλέα ἀναγορεύειν αὐτὸν ὑπέμειναν·"},{"number":10,"text":"οὕτως μέγα τι ἐφρόνουν περὶ τοῦ πρώτου βασιλέως. τὴν οὖν ἀτιμίαν ἐνόμισε μειώσειν τῆς πρὸς αὐτὸν μνήμης, μειώσειν δὲ καὶ τὸ πρὸς Ἡρώδην μῖσος. ταῦτα μὲν ὁ Στράβων."}],"2":[{"number":11,"text":"Κατασχόντος δὲ τὴν βασιλείαν Ἡρώδου πυθόμενος Ὑρκανὸς ὁ ἀρχιερεύς, ἦν δὲ παρὰ Πάρθοις αἰχμάλωτος, ἀφικνεῖται πρὸς Ἡρώδην τῆς αἰχμαλωσίας ἀπολυθεὶς τρόπῳ τοιούτῳ·"},{"number":12,"text":"Βαζαφράνης καὶ Πάκορος οἱ τῶν Πάρθων στρατηγοί, λαβόντες αἰχμαλώτους Ὑρκανὸν τὸν πρῶτον ἀρχιερέα γενόμενον εἶτα βασιλέα καὶ τὸν ἀδελφὸν Ἡρώδου Φασάηλον εἰς Πάρθους ἀνῆγον."},{"number":13,"text":"καὶ Φασάηλος μὲν οὐ φέρων τὴν ἐν τοῖς δεσμοῖς αἰσχύνην, πάσης δὲ ζωῆς κρείττονα τὸν μετὰ δόξης ἡγούμενος θάνατον αὐτὸς ἑαυτοῦ γίνεται φονεύς, καθὼς προεῖπον."},{"number":14,"text":"Ὑρκανῷ δʼ ἀναχθέντι Φραάτης ὁ τῶν Πάρθων βασιλεὺς ἐπʼ αὐτὸν ἐπιεικέστερον προσηνέχθη, τὸ τῆς εὐγενείας αὐτοῦ διάσημον προπεπυσμένος. διὰ τοῦτο δεσμῶν μὲν ἀφῆκεν, ἐν Βαβυλῶνι δὲ κατάγεσθαι παρεῖχεν, ἔνθα καὶ πλῆθος ἦν Ἰουδαίων."},{"number":15,"text":"οὗτοι τὸν Ὑρκανὸν ἐτίμων ὡς ἀρχιερέα καὶ βασιλέα καὶ πᾶν τὸ μέχρις Εὐφράτου νεμόμενον Ἰουδαίων ἔθνος· τῷ δʼ ἦν ἀγαπητὰ ταῦτα."},{"number":16,"text":"πυθόμενος δὲ τὸν Ἡρώδην παρειληφέναι τὴν βασιλείαν ἀντιμετεχώρει ταῖς ἐλπίσιν ἐξ ἀρχῆς τε φιλοστόργως διακείμενος καὶ τῆς χάριτος ἀπομνησθήσεσθαι προσδοκῶν, κρινόμενον ὅτι καὶ μέλλοντα θανάτῳ ζημιοῦσθαι τοῦ κινδύνου καὶ τῆς κολάσεως ἐρρύσατο. λόγους οὖν προσέφερε τοῖς Ἰουδαίοις ἰέναι παρʼ αὐτὸν ἐσπουδακώς."},{"number":17,"text":"οἱ δὲ περιείχοντο καὶ μένειν ἠξίουν τὰς ὑπουργίας ἅμα καὶ τὰς τιμὰς λέγοντες, ὡς οὐδὲν ἐνδεὲς αὐτῷ τῆς εἰς τοὺς ἀρχιερεῖς ἢ βασιλεῖς τιμῆς ἐξ αὐτῶν εἴη, καὶ τὸ μεῖζον, ὅτι μηδὲ ἐκεῖ τούτων μεταλαβεῖν δύναται κατὰ λώβην τοῦ σώματος, ἣν ὑπʼ Ἀντιγόνου πάθοι, τάς τε χάριτας οὐχ ὁμοίως ἀποδίδοσθαι παρὰ τῶν βασιλέων, ἃς ἔλαβον ἰδιωτεύοντες, ἐξαλλαττούσης αὐτοὺς οὐκ ἀλόγως τῆς τύχης."},{"number":18,"text":"Τοιαῦτα κατὰ τὸ συμφέρον ὑποτεινόντων Ὑρκανὸς πόθον εἶχεν ἀπιέναι, καὶ γράφων Ἡρώδης παρεκάλει δεῖσθαι Φραάτου καὶ τῶν ἐκεῖ Ἰουδαίων μὴ φθονῆσαι δυνάμει κοινὴν ἕξοντι τὴν βασιλείαν· ἄρτι γὰρ εἶναι καιρὸν αὐτῷ μὲν ἐκτῖσαι τὰς χάριτας ὧν εὖ πάθοι καὶ τραφεὶς ὑπʼ αὐτοῦ καὶ περισωθείς, ἐκείνῳ δὲ κομίζεσθαι."},{"number":19,"text":"ταῦτα γράφων Ὑρκανῷ πέμπει καὶ παρὰ τὸν Φραάτην πρεσβευτὴν Σαραμάλλαν καὶ δῶρα πλείω, μὴ διακωλῦσαι τὰς εἰς τὸν εὐεργέτην αὐτοῦ χάριτας ὁμοίως φιλανθρωπευόμενον."},{"number":20,"text":"ἦν δʼ οὐκ ἐντεῦθεν ἡ σπουδή, διὰ δὲ τὸ μὴ κατʼ ἀξίαν αὐτὸς ἄρχειν δεδοίκει τὰς ἐξ εὐλόγων μεταβολὰς καὶ τὸν Ὑρκανὸν ὑποχείριον ἔχειν ἔσπευδεν ἢ καὶ παντάπασιν ἐκποδὼν ποιήσασθαι· τοῦτο γὰρ ἔπραξεν ἐν ὑστέρῳ."},{"number":21,"text":"Τότε μέντοι γε ἐπειδὴ παρῆν πεπεισμένος ἐφέντος τε τοῦ Πάρθου καὶ τῶν Ἰουδαίων χρήματα παρασχομένων, ἁπάσῃ τιμῇ δεξάμενος αὐτὸν ἔν τε τοῖς συλλόγοις τὸν πρῶτον ἔνεμε τόπον καὶ παρὰ τὰς ἑστιάσεις προκατακλίνων ἐξηπάτα πατέρα καλῶν καὶ παντοδαπῶς τὸ τῆς ἐπιβουλῆς ἀνύποπτον πραγματευόμενος."},{"number":22,"text":"ὑποκαθίστατο δὲ καὶ τἆλλα πρὸς τὸ συμφέρον τῆς ἀρχῆς, ἐξ ὧν αὐτῷ καὶ τὰ περὶ τὴν οἰκίαν ἐστασιάσθη· φυλαττόμενος γάρ τινα τῶν ἐπισήμων ἀποδεικνύειν ἀρχιερέα τοῦ θεοῦ, μεταπεμψάμενος ἐκ τῆς Βαβυλῶνος ἱερέα τῶν ἀσημοτέρων Ἀνάνηλον ὀνόματι τούτῳ τὴν ἀρχιερωσύνην δίδωσιν."},{"number":23,"text":"Εὐθὺς οὖν οὐκ ἤνεγκεν Ἀλεξάνδρα τὴν ἐπήρειαν, θυγάτηρ μὲν Ὑρκανοῦ, γυνὴ δὲ Ἀλεξάνδρου τοῦ Ἀριστοβούλου βασιλέως, ἐξ Ἀλεξάνδρου παῖδας ἔχουσα τὸν μὲν ὥρᾳ κάλλιστον Ἀριστόβουλον καλούμενον, τὴν δὲ Ἡρώδῃ συνοικοῦσαν Μαριάμμην εὐμορφίᾳ διάσημον."},{"number":24,"text":"ἐτετάρακτο δὲ καὶ χαλεπῶς ἔφερεν τὴν ἀτιμίαν τοῦ παιδός, εἰ περιόντος ἐκείνου τῶν ἐπικλήτων τις ἀξιοῦται τῆς ἀρχιερωσύνης, καὶ γράφει Κλεοπάτρᾳ μουσουργοῦ τινος αὐτῇ συμπραγματευομένου τὰ περὶ τὴν κομιδὴν τῶν γραμμάτων αἰτεῖσθαι παρʼ Ἀντωνίου τῷ παιδὶ τὴν ἀρχιερωσύνην."},{"number":25,"text":"Ἀντωνίου δὲ ῥαθυμότερον ὑπακούοντος, ὁ φίλος αὐτοῦ Δέλλιος εἰς Ἰουδαίαν ἐλθὼν ἐπί τινας χρείας ὡς εἶδεν τὸν Ἀριστόβουλον, ἠγάσθη τε τῆς ὥρας καὶ τὸ μέγεθος καὶ κάλλος τοῦ παιδὸς ἐθαύμασεν, οὐχ ἧττον δὲ τὴν Μαριάμμην συνοικοῦσαν τῷ βασιλεῖ, καὶ δῆλος ἦν καλλίπαιδά τινα τὴν Ἀλεξάνδραν διειληφώς."},{"number":26,"text":"ἐκείνης δὲ εἰς λόγους ἐλθούσης αὐτῷ πείθει γραψαμένην ἀμφοτέρων εἰκόνας Ἀντωνίῳ διαπέμψασθαι· θεασαμένου γὰρ οὐδενὸς ἀτευκτήσειν ὧν ἀξιοῖ."},{"number":27,"text":"τούτοις ἐπαρθεῖσα τοῖς λόγοις Ἀλεξάνδρα πέμπει τὰς εἰκόνας Ἀντωνίῳ· καὶ Δέλλιος ἐτερατεύετο λέγων οὐκ ἐξ ἀνθρώπων αὐτῷ δοκεῖν, ἀλλά τινος θεοῦ γενέσθαι τοὺς παῖδας. ἐπραγματεύετο δὲ διʼ ἑαυτοῦ πρὸς τὰς ἡδονὰς ἑλκύσαι τὸν Ἀντώνιον."},{"number":28,"text":"ὁ δὲ τὴν μὲν κόρην ᾐδέσθη μεταπέμπεσθαι γεγαμημένην Ἡρώδῃ καὶ τὰς εἰς Κλεοπάτραν ἐκ τοῦ τοιούτου διαβολὰς φυλαττόμενος, ἐπέστελλε δὲ πέμπειν τὸν παῖδα σὺν εὐπρεπείᾳ προστιθείς, εἰ μὴ βαρὺ δοκοίη."},{"number":29,"text":"τούτων ἀπενεχθέντων πρὸς Ἡρώδην οὐκ ἀσφαλὲς ἔκρινεν ὥρᾳ τε κάλλιστον ὄντα τὸν Ἀριστόβουλον ἑκκαιδεκαέτης γὰρ ὢν ἐτύγχανεν, καὶ γένει προύχοντα πέμπειν παρὰ τὸν Ἀντώνιον, ἰσχύοντα μὲν ὡς οὐκ ἄλλος ἐν τῷ τότε Ῥωμαίων, ἕτοιμον δὲ τοῖς ἐρωτικοῖς αὐτὸν ὑποθεῖναι καὶ τὰς ἡδονὰς ἀπαρακαλύπτως ἐκ τοῦ δύνασθαι ποριζόμενον."},{"number":30,"text":"ἀντέγραψεν οὖν ὡς, εἰ μόνον ἐξέλθοι τῆς χώρας τὸ μειράκιον, ἅπαντα πολέμου καὶ ταραχῆς ἀναπλησθήσεται Ἰουδαίων ἐλπισάντων μεταβολὴν καὶ νεωτερισμὸν ἐπʼ ἄλλῳ βασιλεῖ."},{"number":31,"text":"Τούτοις δὲ παραιτησάμενος τὸν Ἀντώνιον ἔγνω μὴ μέχρι παντὸς ἀτιμάζειν τὸν παῖδα καὶ τὴν Ἀλεξάνδραν, ἀλλὰ καὶ τῆς γυναικὸς Μαριάμμης ἐγκειμένης λιπαρῶς ἀποδοῦναι τἀδελφῷ τὴν ἀρχιερωσύνην, καὶ συμφέρειν αὐτῷ κρίνων, ἵνα μηδʼ ἀποδημῆσαι δυνατὸν ᾖ τετιμημένῳ, σύλλογον ποιήσας τῶν φίλων ᾐτιᾶτο πολλὰ τὴν Ἀλεξάνδραν,"},{"number":32,"text":"κρύφα τε ἐπιβουλεῦσαι λέγων τῇ βασιλείᾳ καὶ διὰ τῆς Κλεοπάτρας πράττειν, ὅπως αὐτὸς μὲν ἀφαιρεθῇ τὴν ἀρχήν, τὸ δὲ μειράκιον ἀντʼ αὐτοῦ παραλάβῃ τὰ πράγματα διʼ Ἀντωνίου."},{"number":33,"text":"καὶ ταῦτα βούλεσθαι μὲν ἐκείνην οὐ δικαίως, ὁπότε καὶ τὴν θυγατέρα συναποστεροίη τῆς οὔσης αὐτῇ τιμῆς καὶ ταραχὰς ἐπὶ τῇ βασιλείᾳ πραγματεύοιτο, πολλὰ πονήσαντος αὐτοῦ καὶ κτησαμένου κινδύνοις οὐ τοῖς τυχοῦσιν."},{"number":34,"text":"οὐ μὴν ἀπομνημονεύσας αὐτὸς ὧν οὐ καλῶς ἐκείνη πράξειεν ἀποστήσεσθαι τοῦ δίκαιος εἶναι περὶ αὐτούς, ἀλλὰ καὶ νῦν ἔφη διδόναι τῷ παιδὶ τὴν ἀρχιερωσύνην καὶ πάλαι προκαταστήσασθαι τὸν Ἀνάνηλον παιδίου παντάπασιν ὄντος Ἀριστοβούλου."},{"number":35,"text":"τοιαῦτα δὲ λέγοντος οὐκ ἀσκέπτως, ἀλλʼ ὅπερ ἠξίου μάλιστα πεφροντισμένως εἰς ἀπάτην γυναικῶν καὶ τῶν συμπαραληφθέντων φίλων, περιπαθὴς ἅμα καὶ χαρᾷ τῶν οὐ προσδοκηθέντων καὶ δέει τῆς ὑποψίας Ἀλεξάνδρα μετὰ δακρύων ἀπελογεῖτο,"},{"number":36,"text":"περὶ μὲν τῆς ἱερωσύνης φαμένη πᾶν ὁτιοῦν ὑπʼ ἀδοξίας σπουδάσαι, βασιλείᾳ δὲ μήτε ἐπιτίθεσθαι μήτʼ ἄν, εἰ καὶ προσίοι, βούλεσθαι λαβεῖν, καὶ νῦν ἀποχρώντως τιμῆς ἔχουσα διὰ τὴν ἀρχὴν τὴν ἐκείνου καὶ τὴν ἀσφάλειαν τὴν ἐκ τοῦ δύνασθαι μᾶλλον ἑτέρων ἄρχειν αὐτὸν ἅπαντι τῷ γένει περιοῦσαν."},{"number":37,"text":"νῦν τε νενικημένη ταῖς εὐεργεσίαις δέχεσθαι μὲν εἰς τὸν υἱὸν τὴν τιμήν, ἔσεσθαι δὲ πρὸς πᾶν ὑπήκοος, παραιτεῖσθαι δὲ κἂν εἴ τι διὰ γένος καὶ τὴν οὖσαν αὐτῇ παρρησίαν προπετέστερον ὑπʼ ἀναξιοπαθείας δράσειεν."},{"number":38,"text":"οὕτως ἀλλήλοις ὁμιλήσαντες καὶ σπουδαιότερον ἢ θᾶττον ἐν δεξιαῖς διελύοντο πάσης ὑποψίας, ὡς ἐδόκουν, ἐξῃρημένης."}],"3":[{"number":39,"text":"Ὁ δὲ βασιλεὺς Ἡρώδης εὐθὺς μὲν ἀφαιρεῖται τὴν ἀρχιερωσύνην Ἀνάνηλον ὄντα μέν, ὡς καὶ πρότερον εἴπομεν, οὐκ ἐπιχώριον, ἀλλὰ τῶν ὑπὲρ Εὐφράτην ἀπῳκισμένων Ἰουδαίων· οὐ γὰρ ὀλίγαι μυριάδες τοῦδε τοῦ λαοῦ περὶ τὴν Βαβυλωνίαν ἀπῳκίσθησαν."},{"number":40,"text":"ἔνθεν ἦν Ἀνάνηλος ἀρχιερατικοῦ γένους καὶ πάλαι κατὰ συνήθειαν Ἡρώδῃ σπουδαζόμενος. τοῦτον αὐτὸς μὲν ἐτίμησεν, ὅτε τὴν βασιλείαν παρέλαβεν, αὐτὸς δὲ κατέλυσεν ἐπὶ τῷ παῦσαι τὰς οἰκείας ταραχὰς παράνομα ποιῶν· οὐ γὰρ ἄλλος γέ τις ἀφῃρέθη τὴν τιμὴν ἅπαξ παραλαβών."},{"number":41,"text":"ἀλλὰ πρῶτος μὲν Ἀντίοχος ὁ Ἐπιφανὴς ἔλυσε τὸν νόμον ἀφελόμενος μὲν Ἰησοῦν, καταστήσας δὲ τὸν ἀδελφὸν Ὀνίαν, δεύτερος δὲ Ἀριστόβουλος Ὑρκανὸν ἀφείλετο τὸν ἀδελφόν, Ἡρώδης δὲ τρίτος ἀντιπαρέδωκεν τὴν ἀρχὴν Ἀριστοβούλῳ τῷ παιδί."},{"number":42,"text":"Καὶ τότε μὲν ἐδόκει τεθεραπευκέναι τὰ περὶ τὴν οἰκίαν. οὐ μὴν ὅπερ εἰκὸς ἦν ἐν διαλλαγαῖς ἀνυπόπτως διετέλει, τὴν Ἀλεξάνδραν ἐπί τε τοῖς ἐγχειρηθεῖσιν ἤδη καὶ καιρὸν εἰ λάβοιτο νεωτέρων πραγμάτων ἠξιωκὼς δεδοικέναι."},{"number":43,"text":"προσέταττεν οὖν ἔν τε τοῖς βασιλείοις διατρίβειν καὶ μηδὲν ἀπʼ ἐξουσίας δρᾶν, ἐπιμελεῖς τε ἦσαν φυλακαί, λανθάνοντος οὐδʼ εἴ τι πρὸς τὴν καθʼ ἡμέραν δίαιταν ἐπιτηδεύοιτο."},{"number":44,"text":"ταῦτα πάντα κατὰ μικρὸν ἐξηγρίου αὐτὴν καὶ μῖσος ἐπεφύετο· φρονήματος γὰρ ἔμπλεως οὖσα γυναικείου τὰς ἐκ τῆς ὑποψίας ἐπιμελείας ἀνηξιοπάθει, παντὸς οὑτινοσοῦν ἀξιοῦσα μᾶλλον ἢ τῆς παρρησίας στερομένη τιμῆς εὐπρεπείᾳ μετὰ δουλείας καὶ φόβων καταζῆν."},{"number":45,"text":"ἔπεμπεν οὖν παρὰ τὴν Κλεοπάτραν ἐν οἷς εἴη συνεχὲς ὀδυρομένη καὶ παρακαλοῦσα προσβοηθεῖν αὐτῇ κατὰ δύναμιν. ἡ δὲ λαθοῦσαν ἐκέλευσεν ἐπʼ Αἰγύπτου σὺν τῷ παιδὶ πρὸς αὐτὴν ἀποδιδράσκειν."},{"number":46,"text":"ἐδόκει ταῦτα καὶ τεχνάζεται τοιάδε· δύο λάρνακας ὡς εἰς ἐκκομιδὴν νεκρῶν παρασκευασαμένη ταύταις αὐτὴν καὶ τὸν υἱὸν ἐνέβαλεν, ἐπιτάξασα τῶν οἰκετῶν τοῖς συνειδόσιν διὰ νυκτὸς ἐκφέρειν. ἦν δὲ τοὐντεῦθεν ἐπὶ θάλατταν ὁδὸς αὐτοῖς καὶ πλοῖον, ὃ διαπλεύσειν εἰς τὴν Αἴγυπτον ἔμελλεν, παρεσκευασμένον."},{"number":47,"text":"ταῦτα Σαββίωνι τῶν ἐκείνης φίλων Αἴσωπος οἰκέτης αὐτῆς ἀπαγγέλλει προπεσὼν ὡς εἰδότι φράσαι. πυθόμενος δὲ Σαββίων, καὶ γὰρ ἦν ἐχθρὸς Ἡρώδου πρότερον, ὅτι τῶν ἐπιβουλευσάντων Ἀντιπάτρῳ κατὰ τὴν φαρμακείαν εἷς ἐνομίζετο, τὸ μῖσος ὑπαλλάξεσθαι τῇ περὶ τὴν μήνυσιν εὐνοίᾳ προσεδόκησεν καὶ καταλέγει τῷ βασιλεῖ τὴν τῆς Ἀλεξάνδρας ἐπιβουλήν."},{"number":48,"text":"ὁ δὲ τὴν μὲν ἕως τῆς ἐγχειρήσεως ἐάσας προελθεῖν ἐπʼ αὐτοφώρῳ τοῦ δρασμοῦ συνέλαβεν, παρῆκεν δὲ τὴν ἁμαρτίαν, χαλεπὸν μὲν οὐδέν, εἰ καὶ σφόδρα βουλομένῳ ἦν αὐτῷ, διαθεῖναι τολμήσας, οὐ γὰρ ἂν ἀνασχέσθαι Κλεοπάτραν αἰτίαν ἐπὶ τῷ πρὸς αὐτὸν μίσει λαβοῦσαν, ἐμφαίνων δὲ μεγαλοψυχίαν μᾶλλον ἐξ ἐπιεικείας αὐτοῖς συνεγνωκέναι."},{"number":49,"text":"προύκειτο μέντοι παντάπασιν αὐτῷ τὸ μειράκιον ἐκποδὼν ποιεῖσθαι, τὸ δὲ μὴ ταχὺ μηδʼ ἅμα τοῖς πεπραγμένοις ἐδόκει πιθανώτερον εἰς τὸ λανθάνειν."},{"number":50,"text":"Καὶ τῆς σκηνοπηγίας ἐπεχούσης, ἑορτὴ δέ ἐστιν αὕτη παρʼ ἡμῖν εἰς τὰ μάλιστα τηρουμένη, ταύτας τὰς ἡμέρας ὑπερεβάλλετο καὶ πρὸς εὐφροσύναις αὐτός τε καὶ τὸ λοιπὸν πλῆθος ἦν. ἐκίνησεν δʼ αὐτὸν ὅμως κἀκ τῶν τοιούτων ἐπισπεῦσαι τὰ περὶ τὴν προαίρεσιν ἐμφανῶς παροξύνων ὁ φθόνος."},{"number":51,"text":"τὸ γὰρ μειράκιον Ἀριστόβουλος ἕβδομον ἐπὶ τοῖς δέκα γεγονὸς ἔτος, ἐπειδὴ κατὰ τὸν νόμον ἀνῆλθεν ἐπὶ τὸν βωμὸν συντελέσων τὰ θύματα, τόν τε κόσμον ἔχων τὸν τῶν ἀρχιερέων καὶ τὰ περὶ τὴν θρησκείαν ἐκτελῶν, κάλλει τε κάλλιστος καὶ μεγέθει πλέον ἢ πρὸς τὴν ἡλικίαν ὑπεράγων, τοῦ γε μὴν περὶ τὸ γένος ἀξιώματος πλεῖστον ἐν τῇ μορφῇ διαφαίνων,"},{"number":52,"text":"ὁρμή τε τῷ πλήθει πρὸς αὐτὸν εὐνοίας ἐγένετο καὶ τῶν Ἀριστοβούλῳ τῷ πάππῳ πεπραγμένων ἐναργὴς ἡ μνήμη παρέστη, νικώμενοί τε κατὰ μικρὸν ἐξηλέγχοντο τὰς διαθέσεις χαίροντες ὁμοῦ καὶ συγχεόμενοι καὶ φωνὰς εὐφήμους εἰς αὐτὸν ἀφιέντες εὐχαῖς μεμιγμένας, ὡς ἐμφανῆ γενέσθαι τὴν εὔνοιαν τῶν ὄχλων καὶ προπετεστέραν ἐν βασιλείᾳ δοκεῖν τὴν ὧν πεπόνθεσαν ὁμολογίαν."},{"number":53,"text":"ἐπὶ τούτοις ἅπασιν Ἡρώδης ἔγνω τὴν προαίρεσιν, ἣν εἶχεν εἰς τὸ μειράκιον, ἐξεργάσασθαι. καὶ τῆς ἑορτῆς παρελθούσης εἱστιᾶτο μὲν ἐν Ἱεριχοῦντι δεχομένης αὐτοὺς τῆς Ἀλεξάνδρας, φιλοφρονούμενος δὲ τὸ μειράκιον καὶ προέλκων εἰς ἀδεῆ πότον ἕτοιμος ἦν συμπαίζειν καὶ νεανιεύεσθαι κεχαρισμένως ἐκείνῳ."},{"number":54,"text":"τοῦ δὲ περὶ τὸν τόπον ἰδιώματος θερινωτέρου τυγχάνοντος συνειλεγμένοι τάχιον ἐξῆλθον ἀλύοντες, καὶ ταῖς κολυμβήθραις ἐπιστάντες, αἳ μεγάλαι περὶ τὴν αὐλὴν ἐτύγχανον, ἀνέψυχον τὸ θερμότατον τῆς μεσημβρίας."},{"number":55,"text":"καὶ πρῶτον μὲν ἑώρων τοὺς νέοντας τῶν οἰκετῶν καὶ φίλων, ἔπειτα προαχθέντος καὶ τοῦ μειρακίου τῷ καὶ τὸν Ἡρώδην παροξῦναι, τῶν φίλων οἷς ταῦτα ἐπιτέτακτο σκότους ἐπέχοντος βαροῦντες ἀεὶ καὶ βαπτίζοντες ὡς ἐν παιδιᾷ νηχόμενον οὐκ ἀνῆκαν, ἕως καὶ παντάπασιν ἀποπνῖξαι."},{"number":56,"text":"καὶ διεφθάρη μὲν οὕτως Ἀριστόβουλος, ὀκτωκαίδεκα μὲν οὐ πάντα βιοὺς ἔτη, τὴν δʼ ἱερωσύνην κατασχὼν ἐνιαυτόν, ἣν Ἀνάνηλος ἐκομίσατο πάλιν."},{"number":57,"text":"Ἐξαγγελθέντος δὲ τοῦ πάθους ταῖς γυναιξὶν εὐθὺς μὲν ἐκ μεταβολῆς θρῆνος ἦν ἐπὶ προκειμένῳ τῷ νεκρῷ καὶ πένθος ἄσχετον, ἥ τε πόλις τοῦ λόγου διαδοθέντος ὑπερήλγει πάσης ἑστίας οἰκειουμένης τὴν συμφορὰν ὡς οὐκ ἐπʼ ἀλλοτρίῳ γενομένην."},{"number":58,"text":"Ἀλεξάνδρα δὲ καὶ μᾶλλον ἐκπαθὴς ἦν συνέσει τῆς ἀπωλείας, τὸ μὲν ἀλγοῦν ἐκ τοῦ γινώσκειν ὅπως ἐπράχθη πλεῖον ἔχουσα, τὸ δʼ ἐγκαρτερεῖν ἀναγκαῖον ἐπὶ μείζονος κακοῦ προσδοκίᾳ ποιουμένη."},{"number":59,"text":"καὶ πολλάκις μὲν ἦλθεν αὐτοχειρίᾳ περιγράψασθαι τὸν βίον, ἐπέστη δʼ ὅμως, εἰ δύναιτο ζῶσα προσαρκέσαι τῷ κατʼ ἐπιβουλὰς ἀνόμως διεφθαρμένῳ, τό τε πλέον ἐντεῦθεν αὐτῇ παρεκρότει τὸν βίον, καὶ τὸ μηδεμίαν ὑποψίαν ἐνδοῦναι τοῦ κατὰ πρόνοιαν ἀπολέσθαι τὸν υἱὸν ἱκανὸν εἰς εὐκαιρίαν ἀμύνης ἐνόμιζε."},{"number":60,"text":"κἀκείνη μὲν ἐγκρατῶς ἔφερε τὴν ὑποψίαν. Ἡρώδης δὲ πᾶσι τοῖς ἔξωθεν πιθανῶς ἀπεσκευάζετο, μὴ μετὰ προνοίας γενέσθαι τῷ παιδὶ τὸν θάνατον, οὐχ ὅσα πρὸς πένθος ἐπιτηδεύων μόνον, ἀλλὰ καὶ δάκρυσι χρώμενος καὶ σύγχυσιν τῆς ψυχῆς ἐμφαίνων ἀληθινήν, τάχα μὲν καὶ τοῦ πάθους ἀπονικῶντος αὐτὸν ἐν ὄψει τῆς τε ὥρας καὶ τοῦ κάλλους, εἰ καὶ πρὸς ἀσφάλειαν ὁ θάνατος τοῦ παιδὸς ἐνομίζετο, δῆλον δʼ ὡς ἀπολογίαν αὐτὰ πραγματευόμενος."},{"number":61,"text":"τά γε μὴν εἰς τὴν πολυτέλειαν τῆς ἐκφορᾶς καὶ μᾶλλον ἐπεδείξατο, πολλὴν μὲν τὴν παρασκευὴν περί τε τὰς θήκας καὶ τὸ πλῆθος τῶν θυμιαμάτων ποιησάμενος, πολὺν δὲ συγκαταθάπτων κόσμον, ὡς ἐκπλῆξαι τὸ λυπηρὸν τῆς ἐν ταῖς γυναιξὶν ἀλγηδόνος καὶ παραμυθήσασθαι τούτῳ τῷ μέρει."},{"number":62,"text":"Τὴν δʼ Ἀλεξάνδραν ἥττησε μὲν οὐδὲν τῶν τοιούτων, ἀεὶ δὲ καὶ μᾶλλον ἡ μνήμη τοῦ κακοῦ παρέχουσα τὴν ὀδύνην ὀδυρτικὴν ἐποίει καὶ φιλόνεικον, καὶ γράφει τὴν ἐπιβουλὴν Ἡρώδου τῇ Κλεοπάτρᾳ καὶ τὴν ἀπώλειαν τοῦ παιδός."},{"number":63,"text":"ἡ δὲ καὶ πάλαι σπεύδουσα προσαρκέσαι δεομένῃ καὶ τὰς ἀτυχίας οἰκτείρουσα τῆς Ἀλεξάνδρας αὐτῆς ἐποιεῖτο τὸ πᾶν πρᾶγμα καὶ Ἀντώνιον οὐκ ἀνίει τίσασθαι τὸν φόνον τοῦ παιδὸς παροξύνουσα· οὐ γὰρ ἄξιον Ἡρώδην διʼ αὐτοῦ καταστάντα βασιλέα τῆς οὐδὲν προσηκούσης ἀρχῆς εἰς τοὺς ὄντως βασιλεῖς τοιαύτας ἐπιδείκνυσθαι παρανομίας."},{"number":64,"text":"τούτοις ἀναπειθόμενος Ἀντώνιος ὡς ἐπὶ Λαοδικείας ἐστάλη, πέμπει κελεύων Ἡρώδην ἐλθόντα τῶν εἰς Ἀριστόβουλον ἀπολύσασθαι· πεπρᾶχθαι γὰρ οὐκ ὀρθῶς τὴν ἐπιβουλήν, εἰ διʼ αὐτοῦ γέγονεν."},{"number":65,"text":"ὁ δὲ τήν τε αἰτίαν δεδοικὼς καὶ τὴν Κλεοπάτρας δυσμένειαν, ὡς οὐκ ἀνῆκεν ἐξεργαζομένη κακῶς αὐτῷ τὸν Ἀντώνιον ἔχειν, ἔγνω μὲν ὑπακούειν, οὐδὲ γὰρ ἄλλο τι πράττειν ἐνῆν, καταλιπὼν δὲ τὸν θεῖον αὐτοῦ Ἰώσηπον ἐπίτροπον τῆς ἀρχῆς καὶ τῶν ἐκεῖ πραγμάτων ἐνετείλατο λεληθότως, εἰ πάθοι τι παρʼ Ἀντωνίῳ, παραχρῆμα καὶ τὴν Μαριάμμην ἀνελεῖν·"},{"number":66,"text":"αὐτός τε γὰρ ἔχειν φιλοστόργως πρὸς τὴν γυναῖκα καὶ δεδοικέναι τὴν ὕβριν, εἰ καὶ τεθνηκότος ἐκείνη κατʼ εὐμορφίαν ἄλλῳ τινὶ σπουδάζοιτο."},{"number":67,"text":"τὸ δὲ σύμπαν ἐνέφαινεν ὁρμὴν Ἀντωνίου περὶ τὴν ἄνθρωπον, ὅτι καὶ πάλαι παρακηκοὼς ὑπὲρ τῆς εὐμορφίας ἐτύγχανεν. Ἡρώδης μὲν οὖν ἐπιστείλας ταῦτα καὶ τὰς ἐλπίδας οὐκ ἀσφαλεῖς ἔχων ὑπὲρ τῶν ὅλων ἀπῄει πρὸς Ἀντώνιον."},{"number":68,"text":"Ὁ δὲ Ἰώσηπος ἐπὶ τῆς διοικήσεως ὢν τῶν ἐν τῇ βασιλείᾳ πραγμάτων καὶ διὰ τοῦτο συνεχὲς ἐντυγχάνων τῇ Μαριάμμῃ περί τε τὰς πραγματείας καὶ τιμῆς ἕνεκεν, ἣν ἔδει βασιλευούσῃ παρʼ αὐτοῦ γενέσθαι, καθίει συνεχεῖς ὁμιλίας ὑπὲρ τῆς Ἡρώδου πρὸς αὐτὴν εὐνοίας καὶ φιλοστοργίας."},{"number":69,"text":"ἐξειρωνευομένων δὲ γυναικείως τοὺς λόγους καὶ μάλιστα τῆς Ἀλεξάνδρας, ὑπερεσπουδακὼς ὁ Ἰώσηπος ἐπιδεῖξαι τὴν διάνοιαν τοῦ βασιλέως προήχθη καὶ τὰ περὶ τὴν ἐντολὴν εἰπεῖν, πίστιν αὐτὰ ποιούμενος ὡς οὐδὲ χωρὶς ἐκείνης ζῆν δύναται κἂν εἰ πάσχοι δεινόν τι οὐκ ἀξιοῦντος οὐδὲ θανάτῳ διεζεῦχθαι."},{"number":70,"text":"ταῦτα μὲν Ἰώσηπος. αἱ δὲ γυναῖκες, ὡς εἰκός, οὐ τὸ φιλόστοργον τῆς περὶ τὸν Ἡρώδην διαθέσεως, τὸ δὲ χαλεπόν, εἰ μηδʼ ἀποθνήσκοντος ὑστερήσειεν ἀπωλείας καὶ θανάτου τυραννικοῦ, προλαμβάνουσαι χαλεπὴν τὴν ὑπόνοιαν τοῦ ῥηθέντος εἶχον."},{"number":71,"text":"Ἐν δὲ τούτῳ καὶ λόγος ἐγένετο κατὰ τὴν πόλιν τῶν Ἱεροσολυμιτῶν παρὰ τῶν ἐν ἔχθει τὸν Ἡρώδην ἐχόντων, ὡς Ἀντώνιος αἰκισάμενος αὐτὸν ἀποκτείνειεν. ἡ δὲ φήμη πάντας μὲν ἐτάραξεν, ὡς εἰκός, τοὺς περὶ τὸ βασίλειον, μάλιστα δὲ καὶ τὰς γυναῖκας."},{"number":72,"text":"Ἀλεξάνδρα δὲ καὶ τὸν Ἰώσηπον ἀναπείθει τῶν βασιλείων ἐξελθόντα σὺν αὐταῖς προσφυγεῖν τοῖς σημείοις τοῦ Ῥωμαϊκοῦ τάγματος, ὃ τότε περὶ τὴν πόλιν ἐπὶ φρουρᾷ τῆς βασιλείας ἐστρατοπέδευεν ἡγουμένου υἱοῦ ἰούδα·"},{"number":73,"text":"διὰ γὰρ τοῦτο πρῶτον μέν, εἰ καί τις ἀπαντήσειεν ταραχὴ περὶ τὴν αὐλήν, ἐν ἀσφαλεστέρῳ διάξειν αὐτοὶ Ῥωμαίους εὐμενεῖς ἔχοντες· ἔπειτα καὶ τεύξεσθαι παντὸς ἠλπικέναι τὴν Μαριάμμην Ἀντωνίου θεασαμένου, διʼ οὗ καὶ τὴν ἀρχὴν ἀναλήψεσθαι καὶ μηδενὸς ὑστερήσειν ὧν εἰκὸς τοῖς ἐν εὐγενείᾳ βασιλικῇ γεγονόσιν."},{"number":74,"text":"Ἐπὶ τούτων δὲ τῶν λογισμῶν τετυχηκόσιν αὐτοῖς γράμματα παρʼ Ἡρώδου περὶ τῶν ὅλων ἀφίκετο τῆς φήμης ἐναντία καὶ τῶν προλαληθέντων."},{"number":75,"text":"ἐπειδὴ γὰρ ἐγένετο παρʼ Ἀντωνίῳ, ταχὺ μὲν αὐτὸν ἀνεκτήσατο τοῖς δώροις ἃ φέρων ἧκεν ἐκ τῶν Ἱεροσολύμων, ταχὺ δὲ ταῖς ὁμιλίαις παρεστήσατο χαλεπῶς ἔχειν εἰς αὐτόν, οἵ τε τῆς Κλεοπάτρας λόγοι πρὸς τὴν ἐξ ἐκείνου θεραπείαν ἧττον ἠδυνήθησαν·"},{"number":76,"text":"οὐ γὰρ ἔφη καλῶς ἔχειν Ἀντώνιος βασιλέα περὶ τῶν κατὰ τὴν ἀρχὴν γεγενημένων εὐθύνας ἀπαιτεῖν· οὕτως γὰρ ἂν οὐδὲ βασιλεὺς εἴη· δόντας δὲ τὴν τιμὴν καὶ τῆς ἐξουσίας καταξιώσαντας ἐᾶν αὐτῇ χρῆσθαι. τὸ δʼ αὐτὸ καὶ τῇ Κλεοπάτρᾳ μὴ πολυπραγμονεῖσθαι τὰ περὶ τὰς ἀρχὰς συμφέρειν."},{"number":77,"text":"ὑπὲρ τούτων Ἡρώδης ἔγραφεν καὶ τὰς ἄλλας διεξῄει τιμάς, ἃς ἔχοι παρʼ Ἀντωνίῳ συνθακῶν ἐν ταῖς διαγνώσεσιν καὶ συνεστιώμενος ἐφʼ ἑκάστης ἡμέρας, καὶ τούτων ὅπως τυγχάνοι χαλεπῆς εἰς τὰς διαβολὰς αὐτῷ τῆς Κλεοπάτρας οὔσης· πόθῳ γὰρ τῆς χώρας ἐξαιτουμένη τὴν βασιλείαν αὐτῇ προσγενέσθαι πάντα τρόπον ἐκποδὼν αὐτὸν ἐσπουδάκει ποιεῖσθαι."},{"number":78,"text":"δικαίου μέντοι τυγχάνων Ἀντωνίου μηδὲν ἔτι δυσχερὲς προσδοκᾶν, ἀλλὰ καὶ θᾶττον ἥξειν βεβαιοτέραν τὴν εὔνοιαν τὴν παρʼ αὐτοῦ προσειληφὼς τῇ βασιλείᾳ καὶ τοῖς πράγμασιν."},{"number":79,"text":"καὶ τῇ Κλεοπάτρᾳ μηκέτι προσεῖναι τὴν ἐλπίδα τῆς πλεονεξίας Ἀντωνίου δόντος ἀνθʼ ὧν ἠξίου τὴν κοίλην Συρίαν καὶ διὰ τούτου παρηγορήσαντος ὁμοῦ καὶ ἀποσκευασαμένου τὰς ἐντεύξεις, ἃς ὑπὲρ τῆς Ἰουδαίας ἐποιεῖτο."},{"number":80,"text":"Τούτων τῶν γραμμάτων ἀπενεχθέντων ἐπαύσαντο μὲν ἐκείνης τῆς ὁρμῆς, ἣν ὡς ἀπολωλότος εἶχον καταφυγεῖν ἐπὶ τοὺς Ῥωμαίους, οὐ μὴν ἔλαθεν αὐτῶν ἡ προαίρεσις, ἀλλʼ ἐπεὶ παραπέμψας ὁ βασιλεὺς Ἀντώνιον ἐπὶ Πάρθους εἰς τὴν Ἰουδαίαν ὑπέστρεψεν, εὐθὺς μὲν ἥ τε ἀδελφὴ Σαλώμη καὶ ἡ μήτηρ αὐτῷ τὴν διάνοιαν ἣν ἔσχον οἱ περὶ τὴν Ἀλεξάνδραν ἀπεσήμηναν,"},{"number":81,"text":"ἡ δὲ Σαλώμη καὶ κατὰ τἀνδρὸς Ἰωσήπου λόγον εἶπεν τὸ ἐν διαβολῇ ποιοῦσα καὶ τῇ Μαριάμμῃ συγγενόμενον διατελεῖν. ἔλεγεν δὲ ταῦτα χαλεπῶς ἔχουσα πρὸς αὐτὴν ἐκ πλείονος, ὅτι κατὰ τὰς διαφορὰς φρονήματι χρωμένη μείζονι τὴν ἐκείνων ἐξωνείδιζεν δυσγένειαν."},{"number":82,"text":"Ἡρώδης δὲ θερμῶς ἀεὶ καὶ ἐρωτικῶς πρὸς τὴν Μαριάμμην ἔχων εὐθὺς ἐξετετάρακτο καὶ τὴν ζηλοτυπίαν οὐκ ἔφερεν, ἐπικρατούμενος δʼ ἀεὶ τοῦ μὴ προπετές τι ποιῆσαι διὰ τὸν ἔρωτα, συντόνῳ τῷ πάθει καὶ τῷ ζήλῳ παρωξυμμένος ἰδίᾳ τὴν Μαριάμμην ἀνέκρινεν ὑπὲρ τῶν πρὸς τὸν Ἰώσηπον."},{"number":83,"text":"ἀπομνυμένης δʼ ἐκείνης καὶ πάνθʼ ὅσα τῇ μηδὲν ἁμαρτούσῃ προσῆν εἰς ἀπολογίαν καταλογιζομένης, ἀνεπείθετο κατὰ μικρὸν ὁ βασιλεὺς καὶ μετέβαινεν ἐκ τῆς ὀργῆς ἡττώμενος τῆς περὶ τὴν γυναῖκα φιλοστοργίας, ὡς ἀπολογεῖσθαι περὶ ὧν ἔδοξεν ἀκούσας πεπιστευκέναι καὶ περὶ τῆς κοσμιότητος αὐτῇ πολλὴν ὁμολογεῖν χάριν."},{"number":84,"text":"αὐτός τε ὅπως ἔχοι στοργῆς καὶ εὐνοίας πρὸς αὐτὴν ἀνωμολογεῖτο καὶ τέλος, ὡς ἐν τοῖς ἐρωτικοῖς φιλεῖ, προύπιπτον εἰς δάκρυα μετὰ πολλῆς σπουδῆς ἐμπεφυκότες ἀλλήλοις."},{"number":85,"text":"ἀεὶ δὲ καὶ μᾶλλον τοῦ βασιλέως πιστουμένου τὴν αὐτοῦ διάθεσιν οὐ φιλοῦντος, εἶπεν ἡ Μαριάμμη, τὸ κατὰ τὴν ἐντολήν, εἰ πάσχοι τι χαλεπὸν ὑπʼ Ἀντωνίου, κἀμὲ συναπολέσθαι τὴν οὐδενὸς αἰτίαν ."},{"number":86,"text":"τούτου προπεσόντος τοῦ λόγου περιπαθήσας ὁ βασιλεὺς εὐθὺς μὲν ἐκ τῶν χειρῶν αὐτὴν ἀφῆκεν, ἐβόα δὲ καὶ τῶν αὐτὸς ἑαυτοῦ τριχῶν ἐδράττετο, περιφανὲς φώριον ἔχειν τῆς τοῦ Ἰωσήπου πρὸς αὐτὴν κοινωνίας λέγων·"},{"number":87,"text":"οὐ γὰρ ἂν ἐξειπεῖν ἃ κατʼ ἰδίαν ἤκουσεν μὴ μεγάλης αὐτοῖς πίστεως ἐγγενομένης. οὕτως δʼ ἔχων ὀλίγου μὲν ἀπέκτεινε τὴν γυναῖκα, νικώμενος δὲ τῷ πρὸς αὐτὴν ἔρωτι ταύτης μὲν τῆς ὁρμῆς ἐκράτησεν ἑαυτοῦ διακαρτερήσας ὀδυνηρῶς καὶ δυσχερῶς, τὸν μέντοι Ἰώσηπον οὐδʼ εἰς ὄψιν ἐλθόντα διαχρήσασθαι προσέταξεν καὶ τὴν Ἀλεξάνδραν ὡς ἁπάντων παραιτίαν δήσας ἐφύλαττεν."}],"4":[{"number":88,"text":"Ἐν δὲ τούτῳ καὶ τὰ περὶ τὴν Συρίαν ταραχὰς εἶχεν οὐκ ἀνιείσης τῆς Κλεοπάτρας τὸν Ἀντώνιον μὴ πᾶσιν ἐπιχειρεῖν· ἔπειθεν γὰρ ἀφαιρούμενον ἑκάστων τὰς δυναστείας αὐτῇ διδόναι καὶ πλεῖστον ἴσχυεν ἐκ τῆς ἐκείνου πρὸς αὐτὴν ἐπιθυμίας."},{"number":89,"text":"φύσει δὲ πλεονεξίᾳ χαίρουσα παρανομίας οὐδὲν ἔλιπεν, τὸν μὲν ἀδελφόν, ᾧ τὴν βασιλείαν ᾔδει γενησομένην, προανελοῦσα φαρμάκοις πεντεκαιδέκατον ἔτος ἔχοντα, τὴν δʼ ἀδελφὴν Ἀρσινόην ἱκετεύουσαν ἐν Ἐφέσῳ πρὸς τῷ τῆς Ἀρτέμιδος ἀποκτείνασα διʼ Ἀντωνίου·"},{"number":90,"text":"χρημάτων μὲν γὰρ εἵνεκεν, εἴ που μόνον ἐλπισθείη, καὶ ναοὶ καὶ τάφοι παρενομήθησαν, οὔθʼ ἱεροῦ τινος οὕτως ἀσύλου δόξαντος, ὡς μὴ περιαιρεθῆναι τὸν ἐν αὐτῷ κόσμον, οὔτε βεβήλου μὴ πᾶν ὁτιοῦν τῶν ἀπηγορευμένων παθόντος, εἰ μέλλοι μόνον εἰς εὐπορίαν τῇ τῆς ἀδικούσης πλεονεξίᾳ."},{"number":91,"text":"τὸ δʼ ὅλον οὐδὲν αὔταρκες ἦν γυναικὶ καὶ πολυτελεῖ καὶ δουλευούσῃ ταῖς ἐπιθυμίαις, μὴ καὶ τὰ πάντα πρὸς τὴν ἐπίνοιαν ἐνδεῖν ὧν ἐσπουδάκει. διὰ ταῦτα καὶ τὸν Ἀντώνιον ἤπειγεν ἀεί τι τῶν ἄλλων ἀφαιρούμενον αὐτῇ χαρίζεσθαι, καὶ διαβᾶσα σὺν ἐκείνῳ τὴν Συρίαν ἐπενόει κτῆμα ποιήσασθαι."},{"number":92,"text":"Λυσανίαν μὲν οὖν τὸν Πτολεμαίου Πάρθους αἰτιασαμένη τοῖς πράγμασιν ἐπάγειν ἀποκτίννυσιν, ᾔτει δὲ παρʼ Ἀντωνίου τήν τε Ἰουδαίαν καὶ τὴν τῶν Ἀράβων ἀξιοῦσα τοὺς βασιλεύοντας αὐτῶν ἀφελέσθαι."},{"number":93,"text":"τῷ δʼ Ἀντωνίῳ τὸ μὲν ὅλον ἡττᾶσθαι συνέβαινεν τῆς γυναικός, ὡς μὴ μόνον ἐκ τῆς ὁμιλίας, ἀλλὰ καὶ φαρμάκοις δοκεῖν ὑπακούειν εἰς ὅ τι ἂν ἐκείνη θέλῃ, τὸ μέντοι περιφανὲς τῆς ἀδικίας ἐξεδυσώπει μὴ μέχρι τοσούτου κατήκοον γινόμενον ἐπὶ μεγίστοις ἁμαρτάνειν."},{"number":94,"text":"ἵνʼ οὖν μήτʼ ἀρνηθῇ παντάπασιν μήθʼ ὅσα προσέταττεν ἐκείνη διαπραξάμενος ἐκ φανεροῦ δόξῃ κακός, μέρη τῆς χώρας ἑκατέρου παρελόμενος τούτοις αὐτὴν ἐδωρήσατο."},{"number":95,"text":"δίδωσιν δὲ καὶ τὰς ἐντὸς Ἐλευθέρου ποταμοῦ πόλεις ἄχρις Αἰγύπτου χωρὶς Τύρου καὶ Σιδῶνος, ἐκ προγόνων εἰδὼς ἐλευθέρας, πολλὰ λιπαρούσης αὐτῆς αὐτῇ δοθῆναι."},{"number":96,"text":"Τούτων ἡ Κλεοπάτρα τυχοῦσα καὶ παραπέμψασα μέχρις Εὐφράτου τὸν Ἀντώνιον ἐπʼ Ἀρμενίαν στρατευόμενον ἀνέστρεφεν καὶ γίνεται μὲν ἐν Ἀπαμείᾳ καὶ Δαμασκῷ, παρῆλθεν δὲ καὶ εἰς τὴν Ἰουδαίαν Ἡρώδου συντυχόντος αὐτῇ καὶ τῆς τε Ἀραβίας τὰ δοθέντα καὶ τὰς περὶ τὸν Ἱεριχοῦντα προσόδους Ἡρώδου μισθωσαμένου· φέρει δʼ ἡ χώρα τὸ βάλσαμον, ὃ τιμιώτατον τῶν ἐκεῖ καὶ παρὰ μόνοις φύεται, τόν τε φοίνικα πολὺν καὶ καλόν."},{"number":97,"text":"ἐν τούτοις οὖσα καὶ πλείονος αὐτῇ συνηθείας πρὸς τὸν Ἡρώδην γινομένης διεπείραζεν εἰς συνουσίαν ἐλθεῖν τῷ βασιλεῖ, φύσει μὲν ἀπαρακαλύπτως ταῖς ἐντεῦθεν ἡδοναῖς χρωμένη, τάχα δέ τι καὶ παθοῦσα πρὸς αὐτὸν ἐρωτικὸν ἢ καὶ τὸ πιθανώτερον ἀρχὴν ἐνέδρας τὴν ἐπʼ αὐτῇ γενησομένην ὕβριν ὑποκατασκευάζουσα· τὸ δὲ σύμπαν ἐξ ἐπιθυμίας ἡττῆσθαι διέφαινεν."},{"number":98,"text":"Ἡρώδης δὲ καὶ πάλαι μὲν οὐκ εὔνους ἦν τῇ Κλεοπάτρᾳ χαλεπὴν εἰς ἅπαντας ἐπιστάμενος, τότε δὲ καὶ μισεῖν ἀξιῶν, εἰ διʼ ἀσέλγειαν εἰς τοῦτο πρόεισιν, καὶ φθῆναι τιμωρούμενος, εἰ ἐνεδρεύουσα τοιούτοις ἐγχειροίη, τοὺς μὲν λόγους αὐτῆς διεκρούσατο, βουλὴν δʼ ἐποιήσατο σὺν τοῖς φίλοις ὑποχείριον ἔχων ἀποκτεῖναι·"},{"number":99,"text":"πολλῶν γὰρ ἀπαλλάξειν κακῶν ἅπαντας οἷς ἐγένετό τε ἤδη χαλεπὴ καὶ προσεδοκᾶτο· τὸ δʼ αὐτὸ τοῦτο καὶ Ἀντωνίῳ λυσιτελήσειν οὐδʼ ἐκείνῳ πιστῆς ἐσομένης, εἴ τις αὐτὸν καιρὸς ἢ χρεία κατάσχοι τοιούτων δεησόμενον."},{"number":100,"text":"ταῦτα βουλευόμενον ἐκώλυον οἱ φίλοι, πρῶτον μὲν διδάσκοντες, ὡς οὐκ ἄξιον μείζω πράττοντα κινδύνων τὸν φανερώτατον ἀναλαμβάνειν, ἐγκείμενοι δὲ καὶ δεόμενοι μηδὲν ἐκ προπετείας ἐπιτηδεύειν·"},{"number":101,"text":"οὐ γὰρ ἂν ἀνασχέσθαι τὸν Ἀντώνιον, οὐδʼ εἰ σφόδρα τις αὐτῷ τὸ συμφέρον στήσειε πρὸ τῶν ὀμμάτων· τόν τε γὰρ ἔρωτα μᾶλλον ὑπεκκαύσειν τὸ δοκεῖν βίᾳ καὶ κατʼ ἐπιβουλὴν αὐτῆς στέρεσθαι, μέτριον δὲ οὐδὲν εἰς τὴν ἀπολογίαν φανεῖσθαι, τοῦ μὲν ἐπιχειρήματος εἰς γυναῖκα γεγενημένου μέγιστον ἀξίωμα τῶν κατʼ ἐκεῖνον ἐσχηκυῖαν τὸν χρόνον, τῆς δʼ ὠφελείας, εἰ καὶ ταύτην τις οἰηθείη, σὺν αὐθαδείᾳ καὶ καταγνώσει τῆς ἐκείνου διαθέσεως φανουμένης."},{"number":102,"text":"ἐξ ὧν οὐκ ἄδηλον, ὡς μεγάλων καὶ ἀπαύστων κακῶν ἀναπλησθήσεται τὰ περὶ τὴν ἀρχὴν αὐτῷ καὶ τὸ γένος, ἐξὸν ἀποκρουσάμενον τὴν ἁμαρτίαν, εἰς ἣν ἐκείνη παρακαλεῖ, θέσθαι τὸν καιρὸν εὐσχημόνως."},{"number":103,"text":"τοιαῦτα δεδιττόμενοι καὶ τὸ κινδυνῶδες ἐξ εἰκότος παραδηλοῦντες ἐπέσχον αὐτὸν τῆς ἐπιχειρήσεως. ὁ δὲ τὴν Κλεοπάτραν δωρεαῖς θεραπεύσας ἐπʼ Αἰγύπτου προύπεμψεν."},{"number":104,"text":"Ἀντώνιος δὲ τὴν Ἀρμενίαν λαβὼν Ἀρταβάζην τὸν Τιγράνου σὺν τοῖς παισὶν σατράπαις δέσμιον εἰς Αἴγυπτον ἀποπέμπει, δωρούμενος τούτοις τὴν Κλεοπάτραν καὶ τῷ παντὶ κόσμῳ τῆς βασιλείας, ὃν ἐξ αὐτῆς ἔλαβεν."},{"number":105,"text":"Ἀρμενίας δὲ ἐβασίλευσεν Ἀρταξίας ὁ πρεσβύτατος τῶν ἐκείνου παίδων διαδρὰς ἐν τῷ τότε. καὶ τοῦτον Ἀρχέλαος καὶ Νέρων Καῖσαρ ἐκβαλόντες Τιγράνην τὸν νεώτερον ἀδελφὸν ἐπὶ τὴν βασιλείαν κατήγαγον. ταῦτα μὲν οὖν ἐν ὑστέρῳ."},{"number":106,"text":"Περὶ δὲ τοὺς φόρους, οὓς ἔδει τελεῖν τῆς ὑπʼ Ἀντωνίου δοθείσης χώρας, ὁ μὲν Ἡρώδης δίκαιος ἦν οὐκ ἀσφαλὲς ἡγούμενος διδόναι τῇ Κλεοπάτρᾳ μίσους αἰτίαν."},{"number":107,"text":"ὁ δʼ Ἄραψ Ἡρώδου τὴν φορὰν ἐπιδεξαμένου χρόνον μέν τινα παρεῖχεν ἐκείνῳ τὰ διακόσια τάλαντα, μετὰ ταῦτα δὲ κακοήθης ἦν καὶ βραδὺς εἰς τὰς ἀποδόσεις καὶ μόλις εἰ καὶ μέρη τινὰ διαλύσειεν οὐδὲ ταῦτα διδόναι δοκῶν ἀζημίως."}],"5":[{"number":108,"text":"Ἡρώδης δὲ τοῦτον τὸν τρόπον ἀγνωμονοῦντος καὶ τὸ τελευταῖον οὐδὲν ἔτι τῶν δικαίων ποιεῖν ἐθέλοντος εἶχεν μὲν ὡς ἐπεξελευσόμενος, προθεσμίᾳ δὲ ἐχρήσατο τῷ Ῥωμαϊκῷ πολέμῳ."},{"number":109,"text":"τῆς γὰρ ἐπʼ Ἀκτίῳ μάχης προσδοκωμένης, ἣν ἐπὶ τῆς ἑβδόμης καὶ ὀγδοηκοστῆς πρὸς ταῖς ἑκατὸν ὀλυμπιάδος συνέβη γενέσθαι, Καῖσαρ μὲν Ἀντωνίῳ περὶ τῶν ὅλων ἔμελλεν ἀγωνιεῖσθαι πραγμάτων, Ἡρώδης δὲ καὶ τῆς χώρας εὐβοτουμένης αὐτῷ πολὺν ἤδη χρόνον καὶ προσόδων καὶ δυνάμεως εὑρημένων, Ἀντωνίῳ συμμαχίαν κατέλεξεν ἐπιμελέστατα ταῖς παρασκευαῖς χρησάμενος."},{"number":110,"text":"Ἀντώνιος δὲ τῆς μὲν ἐκείνου συμμαχίας οὐδὲν ἔφη δεῖσθαι, τὸν δὲ Ἄραβα, καὶ γὰρ ἀκηκόει παρʼ αὐτοῦ καὶ τῆς Κλεοπάτρας τὴν ἀπιστίαν, ἐπεξελθεῖν προσέταττεν. ἠξίου γὰρ ἡ Κλεοπάτρα ταῦτα λυσιτελεῖν αὐτῇ τὸν ἕτερον ὑπὸ θατέρου κακῶς πάσχειν ἡγουμένη."},{"number":111,"text":"τούτων αὐτῷ παρʼ Ἀντωνίου λεχθέντων ὑποστρέψας Ἡρώδης συνεῖχεν τὸ στρατιωτικὸν ὡς εὐθὺς εἰς τὴν Ἀραβίαν ἐμβαλῶν, καὶ παρασκευασθέντος ἱππικοῦ καὶ πεζῆς δυνάμεως εἰς Διόσπολιν ἀφικνεῖται τῶν Ἀράβων ἐκεῖ συναντώντων· οὐ γὰρ ἐλελήθει τὰ περὶ τὸν πόλεμον αὐτούς· καὶ μάχης καρτερᾶς γενομένης ἐκράτησαν οἱ Ἰουδαῖοι."},{"number":112,"text":"μετὰ δὲ ταῦτα πολλὴ στρατιὰ τῶν Ἀράβων εἰς Κάνατα συνῄει· χωρία δʼ ἐστὶ ταῦτα τῆς κοίλης Συρίας· Ἡρώδης τε προπεπυσμένος ἧκεν ἄγων ἐπʼ αὐτοὺς τὸ πλεῖστον ἧς εἶχεν δυνάμεως, καὶ πλησιάσας ἐν καλῷ στρατοπεδεύεσθαι διεγνώκει χάρακά τε βαλόμενος ἐξ εὐκαίρου ταῖς μάχαις ἐπιχειρεῖν."},{"number":113,"text":"ταῦτα δὲ αὐτοῦ διατάττοντος ἐβόα τὸ πλῆθος τῶν Ἰουδαίων παρελόμενον τῆς τριβῆς ἄγειν ἐπὶ τοὺς Ἄραβας· ὥρμητο δὲ καὶ τῷ συντετάχθαι πιστεύειν καλῶς καὶ ταῖς προθυμίαις ἄμεινον ἐχόντων ὅσοι τὴν πρώτην μάχην νενικήκεσαν οὐδʼ εἰς χεῖρας ἐλθεῖν ἐπιτρέψαντες τοῖς ἐναντίοις."},{"number":114,"text":"θορυβούντων οὖν καὶ πᾶσαν ἐπιδεικνυμένων σπουδὴν ἔγνω τῇ προθυμίᾳ τοῦ πλήθους ὁ βασιλεὺς ἀποχρήσασθαι, καὶ προειπών, ὡς οὐ λελείψεται τῆς ἐκείνων ἀρετῆς, πρῶτος ἐν τοῖς ὅπλοις ἡγήσατο πάντων κατʼ οἰκεῖα τέλη συνακολουθησάντων."},{"number":115,"text":"ἔκπληξις δʼ εὐθὺς ἐμπίπτει τοῖς Ἄραψιν· ἀντιστάντες γὰρ εἰς ὀλίγον ὡς ἑώρων ἀμάχους ὄντας καὶ μεστοὺς φρονήματος, ἔφευγον οἱ πλείους ἐγκλίναντες κἂν διεφθάρησαν Ἀθηνίωνος μὴ κακώσαντος Ἡρώδην καὶ τοὺς Ἰουδαίους."},{"number":116,"text":"οὗτος γὰρ ὢν στρατηγὸς μὲν Κλεοπάτρας ἐπὶ τῶν ἐκεῖ, διάφορος δὲ Ἡρώδῃ, τὸ μέλλον οὐκ ἀπαρασκεύως ἐσκόπει, δρασάντων μέν τι λαμπρὸν τῶν Ἀράβων ἐγνωκὼς ἡσυχίαν ἄγειν, ἡττωμένων δέ, ὃ καὶ συνέβη, τοῖς ἀπὸ τῆς χώρας συνεληλυθόσι τῶν οἰκείων παρεσκευασμένος ἐπιτίθεσθαι τοῖς Ἰουδαίοις."},{"number":117,"text":"καὶ τότε κεκμηκόσι τε καὶ νικᾶν οἰομένοις ἀπροσδοκήτως ἐπιπεσὼν πολὺν ἐποίει φόνον· τάς τε γὰρ προθυμίας εἰς τοὺς ὁμολογουμένους ἐχθροὺς ἐκδαπανήσαντες οἱ Ἰουδαῖοι καὶ τῷ νικᾶν ἐπʼ ἀδείας χρώμενοι ταχὺ τῶν ἐπιχειρησάντων ἡττῶντο καὶ πολλὰς ἐλάμβανον πληγὰς ἐν χωρίοις ἀφίπποις καὶ πετρώδεσιν, ὧν πλείω τὴν ἐμπειρίαν εἶχον οἱ τὴν ἐπίθεσιν ποιησάμενοι."},{"number":118,"text":"κακῶς δὲ πασχόντων οἵ τε Ἄραβες αὑτοὺς ἀνειλήφεσαν καὶ πάλιν ὑποστρέψαντες ἔκτεινον ἤδη τετραμμένους. ἐγένοντο δὲ παντοδαπαὶ κτιννυμένων ἀπώλειαι, καὶ τῶν διαπιπτόντων οὐ πολλοὶ συνέφευγον εἰς τὸ στρατόπεδον."},{"number":119,"text":"ὁ δὲ βασιλεὺς Ἡρώδης ἀπεγνωκὼς τὰ κατὰ τὴν μάχην ἀφιππάζεται βοήθειαν ἄξων· οὐ μὴν ἔφθη καίπερ ἐσπουδακὼς ἐπαρκεῖν, ἀλλὰ τὸ μὲν στρατόπεδον ἥλω τῶν Ἰουδαίων, οἱ δʼ Ἄραβες οὐδὲ μετρίως εὐτυχήκεσαν ἐκ παραλόγου νίκην τε ἧς πλεῖστον ἀπεδέησαν ἀνειληφότες καὶ πολλὴν τῶν ἐναντίων ἀφῃρημένοι δύναμιν."},{"number":120,"text":"τοὐντεῦθεν ὁ μὲν Ἡρώδης λῃστείαις ἐχρῆτο καὶ τὰ πολλὰ κατατρέχων τὴν τῶν Ἀράβων ἐκάκου ταῖς ἐπιδρομαῖς στρατοπεδευόμενος ἐπὶ τῶν ὅρων, καὶ τὸ μὲν σύμπαν ἐξίστατο κατὰ τοὐμφανὲς εἰς χεῖρας ἐλθεῖν, οὐκ ἀζήμιος δὲ γινόμενος τῇ συνεχείᾳ καὶ τῷ φιλοπόνῳ τῶν τε οἰκείων ἐπεμελεῖτο παντὶ τρόπῳ τὸ πταῖσμα διορθούμενος."},{"number":121,"text":"Ἐν τούτῳ καὶ τῆς ἐπʼ Ἀκτίῳ μάχης συνεσταμένης Καίσαρι πρὸς Ἀντώνιον ἑβδόμου δʼ ὄντος Ἡρώδῃ τῆς βασιλείας ἔτους σεισθεῖσα ἡ γῆ τῶν Ἰουδαίων, ὡς οὐκ ἄλλοτε ἐδόκει, τῶν ἐν τῇ χώρᾳ κτηνῶν πολὺν φθόρον ἐποίησεν."},{"number":122,"text":"ἐφθάρησαν δὲ καὶ τῶν ἀνθρώπων ὑπὸ ταῖς πεπτωκυίαις οἰκίαις περὶ τρισμυρίους· τὸ μέντοι στρατιωτικὸν ἐν ὑπαίθρῳ διαιτώμενον οὐδὲν ὑπὸ τοῦ πάθους κατεβλάβη."},{"number":123,"text":"ταῦτα πυνθανομένοις τοῖς Ἄραψιν καὶ μᾶλλον ἢ κατʼ ἀλήθειαν ἐξαγγελλόντων αὐτοῖς ὅσοι τοὺς ὑπὲρ τῶν γεγονότων λόγους τῷ μίσει τῶν ἀκουσομένων ἐχαρίζοντο μεῖζον ἐπῄει φρονεῖν, ὡς τῆς τε χώρας ἀνατετραμμένης τοῖς πολεμίοις καὶ διεφθορότων τῶν ἀνθρώπων μηδὲν ἔτι μηδʼ εἰς αὐτοὺς ἀντίπαλον καταλελεῖφθαι δοκεῖν."},{"number":124,"text":"καὶ τῶν τε Ἰουδαίων τοὺς πρέσβεις, ἧκον γὰρ ἐπὶ τοῖς γεγενημένοις, συλλαβόντες ἀπέκτειναν καὶ μετὰ πάσης προθυμίας ἐχώρουν ἐπὶ τὸ στρατιωτικὸν αὐτῶν."},{"number":125,"text":"οἱ δʼ οὔτε τὴν ἔφοδον ἐξεδέξαντο καὶ πρὸς τὰς συμφορὰς ἀθύμως διακείμενοι προΐεντο τὰ πράγματα, πλεῖστον ἀπογνώσεως ἐπʼ αὐτοῖς πεπονθότες· οὐ γὰρ ἦν οὔτε ἰσοτιμίας ἐλπὶς προηττημένοις ἐν ταῖς μάχαις οὔτε βοηθείας κεκακωμένων αὐτοῖς τῶν οἴκοι πραγμάτων."},{"number":126,"text":"οὕτως οὖν ἐχόντων ἐπῆγεν ὁ βασιλεὺς λόγῳ τε πείθων τοὺς ἡγεμόνας καὶ πειρώμενος ἀναλαμβάνειν αὐτῶν πεπτωκότα τὰ φρονήματα. προδιακινήσας δὲ καὶ παραθαρρύνας τινὰς τῶν ἀμεινόνων ἐτόλμησεν ἤδη καὶ τῷ πλήθει διαλέγεσθαι πρότερον ὀκνῶν αὐτό, μὴ καὶ χαλεπῷ χρήσηται διὰ τὰς ἀτυχίας. παρεκάλει δὲ τοιούτους ποιούμενος εἰς τὸν ὄχλον τοὺς λόγους·"},{"number":127,"text":"οὐκ ἀγνοῶ μὲν, ἄνδρες, ὅτι πολλὰ παρὰ τόνδε τὸν καιρὸν γεγένηται πρὸς τὰς πράξεις ἡμῖν ἐναντιώματα, καὶ θαρρεῖν εἰκὸς ἐν τοῖς τοιούτοις οὐδὲ τοὺς πλεῖστον ἀνδραγαθίᾳ διενηνοχότας."},{"number":128,"text":"ἀλλʼ ἐπειδὴ κατεπείγει τε πολεμεῖν καὶ τῶν γεγονότων οὐδέν ἐστιν τοιοῦτον, ὃ μὴ διʼ ἑνὸς ἔργου καλῶς πραχθέντος ἐπανορθώσεται, παρακαλέσαι προειλόμην ὑμᾶς ἅμα καὶ διδάξαι διʼ ὧν ἂν ἐμμείναιτε τοῖς οἰκείοις φρονήμασιν."},{"number":129,"text":"βούλομαι δὲ πρῶτον μὲν ὑπὲρ τοῦ πολεμεῖν ὡς δικαίως αὐτὸ ποιοῦμεν ἐπιδεῖξαι, διὰ τὴν ὕβριν τῶν ἐναντίων ἠναγκασμένοι· μέγιστον γὰρ εἰ μάθοιτε τοῦτο προθυμίας ὑμῖν αἴτιον ἔσται· μετὰ δὲ τοῦτο δεῖξαι, διότι καὶ τῶν ἐν ἡμῖν δεινὸν οὐδέν ἐστιν καὶ πλείστας εἰς τὸ νικᾶν ἔχομεν τὰς ἐλπίδας."},{"number":130,"text":"ἄρξομαι δʼ ἀπὸ τοῦ πρώτου μάρτυρας ὑμᾶς ποιούμενος ὧν λέγω· τὴν γὰρ τῶν Ἀράβων παρανομίαν ἴστε μὲν δήπου καὶ πρὸς τοὺς ἄλλους ἅπαντας οὕτως ἀπίστως διακειμένων, ὡς εἰκὸς ἔχειν τὸ βάρβαρον καὶ ἀνεννόητον θεοῦ, πλεῖστα μέντοι προσέκρουσαν ἡμῖν πλεονεξίᾳ καὶ φθόνῳ καὶ ταῖς ταραχαῖς ἐφεδρεύοντες ἐξ ὑπογύου."},{"number":131,"text":"καὶ τὰ μὲν πολλὰ τί δεῖ λέγειν; ἀλλὰ κινδυνεύοντας αὐτοὺς τῆς οἰκείας ἀρχῆς ἐκπεσεῖν καὶ δουλεύειν Κλεοπάτρᾳ τίνες ἄλλοι τοῦ δέους ἀπήλλαξαν; ἡ γὰρ ἐμὴ πρὸς Ἀντώνιον φιλία κἀκείνου πρὸς ἡμᾶς διάθεσις αἰτία γεγένηται μηδὲ τούτους ἀνήκεστόν τι παθεῖν, φυλαττομένου τἀνδρὸς μηδὲν ἐπιτηδεύειν, ὃ δύναιτʼ ἂν ὕποπτον ἡμῖν γενέσθαι."},{"number":132,"text":"βουληθέντος δὲ ὅμως Κλεοπάτρᾳ μέρη τινὰ παρασχεῖν ἀφʼ ἑκατέρας τῆς ἀρχῆς, καὶ τοῦτο διῳκησάμην ἐγώ, καὶ πολλὰ δῶρα δοὺς ἰδίᾳ τὸ μὲν ἀσφαλὲς ἀμφοτέροις ἐπορισάμην, τὰς δὲ δαπάνας αὐτὸς ἀνέλαβον, διακόσια μὲν δοὺς τάλαντα, διακοσίων δʼ ἐγγυητὴς γενόμενος, ἃ τῇ μὲν προσοδευομένῃ γέγονεν, αὐτοὶ δʼ ὑπὸ τούτων ἀπεστερήμεθα."},{"number":133,"text":"καίτοι γε ἄξιον ἦν μηδενὶ τῶν ὄντων Ἰουδαίους φόρον ἢ τῆς χώρας ἀπόμοιραν τελεῖν, εἰ δʼ οὖν, ἀλλʼ οὐχ ὑπέρ γε τούτων οὓς αὐτοὶ σεσώκαμεν, οὐδὲ τοὺς Ἄραβας ὁμολογήσαντας ἐντεύξεως καὶ χάριτος ὅτι τὴν ἀρχὴν ἐδόκουν τυγχάνειν ἀδικεῖν ἡμᾶς ἀποστεροῦντας, καὶ ταῦτα οὐ πολεμίους ὄντας, ἀλλὰ φίλους."},{"number":134,"text":"ὡς ἥ γε πίστις ἔχουσα καὶ πρὸς τοὺς πολεμιωτάτους τόπον τοῖς γε φίλοις ἀναγκαιοτάτη τετηρῆσθαι, ἀλλʼ οὐ παρὰ τούτοις, οἳ τὸ μὲν κερδαίνειν ἐκ παντὸς τρόπου κάλλιστον ὑπειλήφασιν, τὸ δʼ ἄδικον οὐκ ἐπιζήμιον, εἰ μόνον κερδαίνειν δυνηθεῖεν."},{"number":135,"text":"ἔστιν οὖν ἔτι ζήτησις ὑμῖν, εἰ δεῖ τοὺς ἀδίκους τιμωρεῖσθαι, τοῦτο καὶ τοῦ θεοῦ βουλομένου καὶ παραγγέλλοντος ἀεὶ μισεῖν τὴν ὕβριν καὶ τὴν ἀδικίαν, καὶ ταῦτα οὐ μόνον δίκαιον, ἀλλὰ καὶ ἀναγκαῖον πόλεμον ἐξιόντων;"},{"number":136,"text":"ἃ γὰρ ὁμολογεῖται παρανομώτατα τοῖς τε Ἕλλησιν καὶ τοῖς βαρβάροις, ταῦτα ἔπραξαν εἰς τοὺς ἡμετέρους πρέσβεις ἀποσφάξαντες αὐτούς, τῶν μὲν Ἑλλήνων ἱεροὺς καὶ ἀσύλους εἶναι φαμένων τοὺς κήρυκας, ἡμῶν δὲ τὰ κάλλιστα τῶν δογμάτων καὶ τὰ ὁσιώτατα τῶν ἐν τοῖς νόμοις διʼ ἀγγέλων παρὰ τοῦ θεοῦ μαθόντων· τοῦτο γὰρ τὸ ὄνομα καὶ ἀνθρώποις θεὸν εἰς ἐμφάνειαν ἄγει καὶ πολεμίους πολεμίοις διαλλάττειν δύναται."},{"number":137,"text":"ποῖον οὖν μεῖζον ἂν γένοιτο ἀσέβημα ἢ πρέσβεις ἀποκτεῖναι τοὺς ὑπὲρ τοῦ δικαίου διαλεγομένους; πῶς δʼ ἂν ἔτι δύναιντο ἢ περὶ τὸν βίον εὐσταθεῖν ἢ περὶ τὸν πόλεμον εὐτυχεῖν τοιούτων αὐτοῖς πεπραγμένων; ἐμοὶ μὲν οὐδαμῶς δοκοῦσιν."},{"number":138,"text":"ἴσως τοίνυν τὸ μὲν ὅσιον καὶ δίκαιόν ἐστιν μεθʼ ἡμῶν, ἀνδρειότεροι δὲ ἢ πλείους ἐκεῖνοι τετυχήκασιν. ἀλλὰ πρῶτον μὲν ἀνάξιον ὑμῖν ταῦτα λέγειν· μεθʼ ὧν γὰρ τὸ δίκαιόν ἐστιν μετʼ ἐκείνων ὁ θεός, θεοῦ δὲ παρόντος καὶ πλῆθος καὶ ἀνδρεία πάρεστιν."},{"number":139,"text":"ἵνα δὲ καὶ τὰ καθʼ αὑτοὺς ἐξετάσωμεν, ἐνικήσαμεν τῇ πρώτῃ μάχῃ· συμβαλόντες τὴν δευτέραν οὐδὲ ἀντέσχον ἡμῖν, ἀλλʼ ἔφυγον εὐθὺς οὐχ ὑπομείναντες τὴν ἔφοδον καὶ τὰ φρονήματα· νικῶσιν ἡμῖν Ἀθηνίων ἐπέθετο πόλεμον ἀκήρυκτον ἐπάγων."},{"number":140,"text":"πότερον ἀνδραγαθία τοῦτʼ ἔστιν ἐκείνων ἢ δευτέρα παρανομία καὶ ἐνέδρα; τί οὖν ἔλαττον φρονοῦμεν ἐφʼ οἷς μείζους ἔχειν δεῖ τὰς ἐλπίδας; πῶς δʼ ἂν καταπλαγείημεν τοὺς ὅταν μὲν ἐξ ἀληθείας ἀγωνίζωνται πάντοτε νικωμένους, ὅταν δὲ κρατεῖν νομισθῶσιν ἐξ ἀδικίας αὐτὸ ποιοῦντας;"},{"number":141,"text":"πῶς δʼ ἄν, εἰ καὶ γενναίους ἡγεῖταί τις αὐτούς, οὐ παρʼ αὐτὸ τοῦτο καὶ μᾶλλον ὁρμηθείη; τὸ γὰρ εὔψυχον οὐκ ἐν τῷ τοῖς ἀσθενεστέροις ἐπιχειρεῖν, ἀλλʼ ἐν τῷ δύνασθαι καὶ τῶν ἰσχυροτέρων κρατεῖν."},{"number":142,"text":"εἰ δέ τινα καταπλήξεται τὰ οἰκεῖα πάθη καὶ τὰ περὶ τὸν σεισμὸν συμβεβηκότα, πρῶτον μὲν ἐννοηθήτω, διότι τοῦτʼ αὐτὸ καὶ τοὺς Ἄραβας ἐξαπατᾷ μείζω τὰ γενόμενα τῆς ἀληθείας ὑπειληφότας, ἔπειτα ὡς οὐ καλὸν ἐκείνοις τε τόλμης καὶ ἡμῖν δειλίας τὴν αὐτὴν αἰτίαν γενέσθαι·"},{"number":143,"text":"οἱ μὲν γὰρ οὐκ ἐξ οἰκείου τινὸς ἀγαθοῦ τὸ εὔψυχον ἔχουσιν, ἀλλʼ ἐκ τῆς περὶ ἡμᾶς ὡς κάμνοντας ἤδη τοῖς κακοῖς ἐλπίδος, ἡμεῖς δὲ χωρήσαντες ἐπʼ αὐτοὺς παραιρησόμεθα μὲν ἐκείνων τὸ μεῖζον φρονεῖν, ἀναληψόμεθα δʼ αὐτοὶ τὸ μηκέτι θαρροῦσιν μάχεσθαι."},{"number":144,"text":"καὶ γὰρ οὔτε κεκακώμεθα τοσοῦτον οὔθʼ, ὅπερ οἴονταί τινες, ὀργὴν θεοῦ παρέχει τὸ γεγονός, ἀλλὰ ταῦτα συμπτώματα γίνεται καὶ πάθη τινά. καὶ εἰ κατὰ θεοῦ γνώμην πέπρακται, δῆλον ὡς καὶ πέπαυται κατὰ τὴν ἐκείνου γνώμην ἀρκουμένου τοῖς γεγονόσιν· βουλόμενος γὰρ ἔτι μᾶλλον ἀδικεῖν, οὐκ ἂν μετεβάλετο."},{"number":145,"text":"τὸν δὲ πόλεμον ὅτι καὶ θέλει τοῦτον ἐνεργεῖσθαι καὶ δίκαιον οἶδεν, δεδήλωκεν αὐτός· ἐνίων γὰρ ἐν τῷ σεισμῷ περὶ τὴν χώραν ἀπολομένων οὐδεὶς οὐδὲν ἔπαθεν τῶν ἐν τοῖς ὅπλοις, ἀλλὰ πάντες ἐσώθητε, φανερὸν ποιοῦντος τοῦ θεοῦ, διότι κἂν εἰ πανδημεὶ μετὰ τέκνων καὶ γυναικῶν ἐστρατεύεσθε, περιῆν ἂν ὑμῖν μηδὲν ἀνήκεστον παθεῖν."},{"number":146,"text":"ταῦτα ἐνθυμηθέντες καὶ τὸ μεῖζον ὅτι παρὰ πάντα καιρὸν προϊστάμενον ἔχετε τὸν θεόν, ἐπεξέλθετε δικαίαις ἀνδραγαθίαις τοὺς ἀδίκους μὲν πρὸς φιλίαν, ἀσπόνδους δὲ ἐν ταῖς μάχαις, ἀνοσίους δὲ εἰς πρέσβεις, ἀεὶ δὲ τῆς ὑμετέρας ἀρετῆς ἡττημένους."},{"number":147,"text":"Ταῦτα ἀκούσαντες οἱ Ἰουδαῖοι πολὺ τὰς ψυχὰς ἀμείνους ἐγίνοντο πρὸς τὴν μάχην. Ἡρώδης δὲ θυσίας κατὰ τὰ νομιζόμενα ποιήσας καὶ μετὰ σπουδῆς ἀναλαβὼν αὐτοὺς ἦγεν ἐπὶ τοὺς Ἄραβας διαβὰς τὸν Ἰορδάνην ποταμὸν καὶ τῶν πολεμίων στρατοπεδεύεται πλησίον."},{"number":148,"text":"ἐδόκει δʼ αὐτῷ φρούριον ἐν μέσῳ κείμενον καταλαβεῖν· οὕτως γὰρ αὐτὸς μὲν ὠφεληθήσεσθαι καὶ πρὸς τὸ θᾶττον συνάψαι τὴν μάχην καὶ εἰ παρέλκειν δέοι ἐρυμνὸν αὐτῷ πεπορισμένος τὸ στρατόπεδον."},{"number":149,"text":"τὸ δʼ αὐτὸ καὶ τῶν Ἀράβων προνοούντων ἅμιλλα γίνεται περὶ τοῦ χωρίου καὶ πρῶτον μὲν ἀκροβολισμοῖς, εἶτα δὴ καὶ πλείους εἰς χεῖρας ἐρχόμενοι παρʼ ἀμφοτέρων ἕως ἡττηθέντες οἱ παρὰ τῶν Ἀράβων ἀπεχώρουν."},{"number":150,"text":"τοῦτο εὐθὺς εἰς ἐλπίδας τοῖς Ἰουδαίοις οὐ μικρὸν ἐγεγόνει. καὶ τὴν δύναμιν αὐτοῦ ἐννοούμενον πάντα μᾶλλον ἢ πρὸς μάχην ἰέναι βουλόμενον θρασύτερον ἐπεχείρησεν αὐτῶν τὸν χάρακα διασπᾶν καὶ τοῦ στρατοπέδου προσάγων ἅπτεσθαι· τούτοις γὰρ ἐκβιασθέντες προῄεσαν ἄτακτοι καὶ προθυμίας ἢ τῆς εἰς τὸ νικᾶν ἐλπίδος οὐδʼ ὁτιοῦν ἐσχηκότες."},{"number":151,"text":"ὅμως δʼ οὖν εἰς χεῖρας ᾔεσαν πλείους τε ὄντες καὶ διὰ τὸ κατεπείγειν ἐπὶ τὸ τολμηρὸν ὑπὸ τῆς ἀνάγκης στρατηγούμενοι, καὶ μάχη γίνεται καρτερὰ πιπτόντων ἑκατέρωθεν οὐκ ὀλίγων, τέλος δὲ τραπέντες οἱ Ἄραβες ἔφευγον."},{"number":152,"text":"ἦν δὲ φόνος ἐγκλινάντων, ὡς μὴ μόνον ὑπὸ τῶν πολεμίων θνήσκειν, ἀλλὰ καὶ σφίσιν αὐτοῖς παραιτίους γίνεσθαι τῶν κακῶν, ὑπό τε πλήθους καὶ φορᾶς ἀτάκτου συμπατουμένων καὶ περιπιπτόντων τοῖς οἰκείοις ὅπλοις·"},{"number":153,"text":"πεντακισχίλιοι γοῦν αὐτῶν ἐγένοντο νεκροί. τὸ δʼ ἄλλο πλῆθος ἔφθη μὲν εἰς τὸ χαράκωμα συμφυγεῖν, εἶχεν δʼ οὐκ ἐν βεβαίῳ τὴν ἐλπίδα τῆς σωτηρίας ἀπορίᾳ τῶν ἐπιτηδείων καὶ μᾶλλον ὕδατος. οἵ τε Ἰουδαῖοι διώκοντες συνεισπεσεῖν μὲν οὐ κατίσχυσαν,"},{"number":154,"text":"περικαθεζόμενοι δὲ τῷ χάρακι καὶ παρατηροῦντες εἰσόδου τε τοὺς ἐπαρκοῦντας καὶ ἐξόδου φυγεῖν βουλομένους εἶργον."},{"number":155,"text":"Ἐν τοιούτοις οὖν ὄντες οἱ Ἄραβες ἐπρεσβεύοντο πρὸς τὸν Ἡρώδην, τὸ μὲν πρῶτον ὑπὲρ διαλύσεως, ἔπειτα, τὸ γὰρ δίψος ἤπειγεν, πᾶν ὁτιοῦν ὑφιστάμενοι καὶ τυχεῖν εἰς τὸ παρὸν ἀδείας ἠξιωκότες."},{"number":156,"text":"ὁ δʼ οὔτε πρέσβεις οὔτε λύτρα τῶν ἡλωκότων οὔτʼ ἄλλο τι μέτριον προσίετο φιλόνεικος ὢν ἐκδικῆσαι τὰς παρανομίας τὰς εἰς αὐτοὺς ἐξ ἐκείνων γεγενημένας. καταναγκαζόμενοί τε τοῖς τε ἄλλοις καὶ τῷ δίψει προϊόντες αὑτοὺς ἐνεχείριζον ἄγειν καὶ δεῖν,"},{"number":157,"text":"καὶ πέντε μὲν ἡμέραις τετρακισχίλιοι τὸ πλῆθος οὕτως ἑάλωσαν, τῇ δʼ ἕκτῃ πάντες οἱ λοιποὶ διέγνωσαν ἐξιέναι πολέμου νόμῳ χωρήσαντες ἐπὶ τοὺς ἐναντίους ἐγχειρεῖν, καὶ εἰ δέοι τι πάσχειν, αἱρούμενοι καὶ μὴ διαφθείρεσθαι κατʼ ὀλίγους ἀδόξως."},{"number":158,"text":"ταῦτα δὲ γνόντες ἐξῆλθον μὲν τοῦ χαρακώματος, διήρκεσαν δʼ οὐδαμῶς τῇ μάχῃ, λαμπρῶς μὲν ἀγωνίσασθαι κεκακωμένοι καὶ τὰς ψυχὰς καὶ τὰ σώματα τόπον οὐκ ἔχοντες, κέρδος δʼ εἰ θνήσκοιεν ἐν συμφορᾷ τὸ ζῆν ποιούμενοι, καὶ πίπτουσιν αὐτῶν ἐν τῇ προτέρᾳ μάχῃ περὶ ἑπτακισχιλίους."},{"number":159,"text":"τοιαύτῃ δὲ πληγῇ χρησαμένων φρονήματος μὲν ὅσον ἦν πρότερον αὐτοῖς ἀφῄρηντο, τεθαυμακότες δὲ ἐν ταῖς οἰκείαις συμφοραῖς τὴν Ἡρώδου στρατηγίαν εἴς τε τὸ λοιπὸν εἶξαν καὶ προστάτην ἀπεφήναντο τοῦ ἔθνους."},{"number":160,"text":"ὁ δὲ πλεῖστον ἐπὶ τοῖς εὐημερήμασιν ἠξιωκὼς φρονεῖν ἀνέστρεψεν εἰς τὴν οἰκείαν, προσειληφὼς ἀξίωμα καὶ διὰ ταύτην τὴν ἀνδραγαθίαν."}],"6":[{"number":161,"text":"Τὰ μὲν οὖν ἄλλα καλῶς εἶχεν αὐτῷ δυσεπιχειρήτῳ κατὰ πάντα γεγενημένῳ, κίνδυνος δʼ ἐμπίπτει τὴν ὑπὲρ τῶν ὅλων κρίσιν ἐξάγων Ἀντώνιον Καίσαρος ἐν τῇ κατʼ Ἄκτιον μάχῃ νενικηκότος·"},{"number":162,"text":"τότε γὰρ ἀπέγνωστο αὐτῷ τε Ἡρώδῃ τὰ πράγματα καὶ τοῖς περὶ αὐτὸν ὁμοίως ἐχθροῖς τε καὶ φίλοις· οὐ γὰρ ἦν εἰκὸς ἀτιμώρητον μενεῖν τοσαύτης αὐτῷ φιλίας πρὸς Ἀντώνιον γεγενημένης."},{"number":163,"text":"ἦν οὖν τοῖς μὲν φίλοις ἀπόγνωσις τῶν κατʼ αὐτὸν ἐλπίδων, ὅσοι δʼ ἐχθρῶς εἶχον ἐδόκουν μὲν ἐξ ἐμφανοῦς συνάχθεσθαι, πάθος δὲ λεληθὸς ἐφηδομένων εἶχον ὡς ἀμείνονος τευξόμενοι τῆς μεταβολῆς."},{"number":164,"text":"αὐτός τε Ἡρώδης τὸν Ὑρκανὸν ὁρῶν μόνον ἐπʼ ἀξιώματος βασιλικοῦ συμφέρειν ᾤετο μηκέτʼ ἐμποδὼν ἐᾶν, εἰ μὲν περισωθείη καὶ διαφύγοι τὸν κίνδυνον, ἀσφαλὲς ἡγούμενος πρὸς τὸ μὴ τοῖς τοιούτοις αὐτοῦ καιροῖς ἐφορμεῖν ἄνδρα τυχεῖν τῆς βασιλείας ἀξιώτερον, εἰ δὲ καὶ πάσχοι τι διὰ Καίσαρος, φθόνῳ τὸν μόνον ἐπὶ τῆς βασιλείας γενησόμενον ἐπιθυμῶν ἐξελεῖν."},{"number":165,"text":"Ταῦτα δʼ αὐτοῦ διʼ ἐννοίας ἔχοντος ἐνεδόθη τι καὶ παρʼ ἐκείνων· ὁ μὲν γὰρ Ὑρκανὸς ἐπιεικείᾳ τρόπου καὶ τότε καὶ τὸν ἄλλον χρόνον οὐκ ἠξίου πολυπραγμονεῖν οὐδὲ νεωτέρων ἅπτεσθαι, συγχωρῶν τῇ τύχῃ πᾶν τὸ διʼ ἐκείνης γινόμενον ἠγαπηκέναι."},{"number":166,"text":"φιλόνεικος δʼ ἦν Ἀλεξάνδρα καὶ τὴν ἐλπίδα τῆς μεταβολῆς ἀκρατῶς φέρουσα λόγους ἐποιεῖτο πρὸς τὸν πατέρα, μὴ μέχρι παντὸς ἀναμεῖναι τὴν Ἡρώδου παρανομίαν εἰς τὸν αὐτῶν οἶκον, ἀλλὰ προλαβεῖν ἀσφαλείᾳ τὰς αὖθις ἐλπίδας,"},{"number":167,"text":"καὶ γράφειν ἠξίου περὶ τούτων Μάλχῳ τῷ τὴν ἀραβαρχίαν ἔχοντι δέξασθαί τε αὐτὸν καὶ διʼ ἀσφαλείας ἔχειν· ὑπεξελθόντων γὰρ εἰ τὰ περὶ τὸν Ἡρώδην οὕτως χωρήσειεν, ὡς εἰκὸς ἐν ἔχθρᾳ Καίσαρος, αὐτοὺς ἔσεσθαι τοὺς τὴν ἀρχὴν ἀπολαμβάνοντας μόνους καὶ διὰ τὸ γένος καὶ διὰ τὴν εὔνοιαν τῶν ὄχλων."},{"number":168,"text":"ταῦτα πειθούσης ὁ μὲν Ὑρκανὸς διωθεῖτο τοὺς λόγους, φιλόνεικον δέ τι καὶ γυναικεῖον αὐτῆς πεπονθυίας καὶ μήτε νύκτα μήθʼ ἡμέραν ἀπολειπομένης, ἀλλʼ ἀεὶ περὶ τούτων καὶ τῆς Ἡρώδου πρὸς αὐτοὺς ἐπιβουλῆς διαλεγομένης, ἀνεπείσθη τέλος ἐπιστολὴν δοῦναι Δοσιθέῳ τινὶ τῶν περὶ αὐτὸν φίλων, ἐν ᾗ συντέτακτο πέμπειν αὐτῷ τὸν Ἄραβα τοὺς ἀναληψομένους καὶ παραπέμψοντας ἱππέας ἐπὶ τὴν Ἀσφαλτῖτιν λίμνην· αὕτη δʼ ἀπέχει τῶν Ἱεροσολυμιτῶν ὅρων σταδίους τριακοσίους."},{"number":169,"text":"ἐπίστευεν δὲ τῷ Δοσιθέῳ θεραπεύοντος αὐτοῦ καὶ αὐτὸν καὶ τὴν Ἀλεξάνδραν καὶ τῆς πρὸς Ἡρώδην δυσνοίας οὐ μικρὰς αἰτίας ἔχοντος· Ἰωσήπου τε γάρ, ὃν ἐκεῖνος ἀνῃρήκει, συγγενὴς ἦν καὶ τῶν ἐν Τύρῳ φονευθέντων ὑπʼ Ἀντωνίου πρότερον ἀδελφός."},{"number":170,"text":"οὐ μὴν ἐπήγαγεν ταῦτα τὸν Δοσίθεον Ὑρκανῷ πιστὸν εἰς τὴν ὑπηρεσίαν γενέσθαι, προτιμήσας δὲ τῶν ἐκείνου τὰς ἐκ τοῦ βασιλεύοντος ἐλπίδας ἐπιδίδωσιν Ἡρώδῃ τὴν ἐπιστολήν."},{"number":171,"text":"ὁ δὲ τῆς εὐνοίας ἀποδεξάμενος ἔτι καὶ τοῦτο προσυπουργῆσαι παρεκελεύετο, πτύξαντα τὴν ἐπιστολὴν καὶ κατασημηνάμενον ἀποδοῦναι τῷ Μάλχῳ καὶ τὰ παρʼ ἐκείνου γράμματα λαβεῖν· οὐ γὰρ μικρὸν τὸ διάφορον καὶ τὴν ἐκείνου γνώμην αὐτὸν εἰδέναι."},{"number":172,"text":"ταῦτα δὲ τοῦ Δοσιθέου προθύμως ὑπουργήσαντος ὁ μὲν Ἄραψ ἀντεπέστελλεν αὐτόν τε Ὑρκανὸν δέχεσθαι καὶ τοὺς σὺν αὐτῷ πάντας καὶ Ἰουδαίων ὅσοι τὰ ἐκείνου φρονοῦσιν, δύναμίν τε πέμψειν τὴν μετʼ ἀσφαλείας αὐτοὺς κομιοῦσαν καὶ πρὸς μηδὲν ἐνδεήσειν ὧν ἠξίου."},{"number":173,"text":"ὡς δὲ καὶ ταύτην Ἡρώδης ἐδέξατο τὴν ἐπιστολήν, εὐθύς τε μεταπέμπεται τὸν Ὑρκανὸν καὶ περὶ τῶν γενομένων αὐτῷ συνθηκῶν πρὸς τὸν Μάλχον ἀνέκρινεν. ἀρνησαμένου δὲ τὰς ἐπιστολὰς δείξας τῷ συνεδρίῳ διεχειρίσατο τὸν ἄνδρα."},{"number":174,"text":"Ταῦτα δὲ γράφομεν ἡμεῖς, ὡς ἐν τοῖς ὑπομνήμασιν τοῖς τοῦ βασιλέως Ἡρώδου περιείχετο. τοῖς δʼ ἄλλοις οὐ κατὰ ταῦτα συμφωνεῖ· τὸν γὰρ Ἡρώδην οὐκ ἐπὶ τοιούτοις δοκοῦσιν, ἀλλʼ ἐξ ἐπιβουλῆς μᾶλλον Ὑρκανῷ τὴν αἰτίαν ἐπάγοντα κατὰ τὸν αὐτοῦ τρόπον ἀποκτεῖναι·"},{"number":175,"text":"γράφουσι γὰρ οὕτως, ἐν συμποσίῳ τινὶ μηδὲν ὑποψίας ἐνδιδόντα λόγον Ὑρκανῷ προσφέρειν, εἴ τινας ἐπιστολὰς παρὰ τοῦ Μάλχου λάβοι, καὶ τὸν μὲν ὁμολογῆσαι προσαγορευτικὰ γράμματα κομίσασθαι,"},{"number":176,"text":"τὸν δʼ, εἰ καί τινα δωρεὰν εἰληφὼς εἴη, πάλιν ἐπερέσθαι· τοῦ δὲ μηδὲν πλέον ἢ κτηνῶν ἀναβατικῶν τέτταρα πέμψαντος αὐτῷ λαβεῖν, εἰς αἰτίαν τὸ τοιοῦτον ἐπαναφέροντα δωροδοκίας καὶ προδοσίας ἀπάγχειν προστάξαι τὸν ἄνδρα."},{"number":177,"text":"τεκμήρια δὲ τοῦ μηδὲν ἁμαρτόντα τοιούτῳ τέλει περιπεσεῖν καταλογίζονται τὴν ἐπιείκειαν τοῦ τρόπου καὶ τὸ μήτʼ ἐν νεότητι θράσους ἢ προπετείας ἐπίδειξιν πεποιῆσθαι μήθʼ ὅτε τὴν βασιλείαν αὐτὸς εἶχεν, ἀλλὰ κἀν ταύτῃ τὰ πλεῖστα τῶν κατὰ τὴν διοίκησιν Ἀντιπάτρῳ παρακεχωρηκέναι."},{"number":178,"text":"τότε δʼ ἐντῶ πλείω μὲν ἢ ὀγδοήκοντα γεγονὼς ἐτύγχανεν ἔτη, κρατοῦντα δὲ μετὰ πάσης ἀσφαλείας τὸν Ἡρώδην ἠπίστατο, διαβεβήκει δὲ καὶ τὸν Εὐφράτην τοὺς ἐν τῷ πέραν τιμῶντας αὐτὸν καταλιπὼν ὡς ὅλος ἐπʼ ἐκείνῳ γενησόμενος· ἐγχειρεῖν οὖν τι καὶ καινοτέρων ἅπτεσθαι πάντων ἀπιθανώτατον καὶ οὐ πρὸς τῆς ἐκείνου φύσεως, ἀλλὰ ταῦτα σκῆψιν Ἡρώδου γενέσθαι."},{"number":179,"text":"Τοῦτο μὲν τὸ τέλος Ὑρκανῷ συνέπεσεν τοῦ βίου ποικίλαις καὶ πολυτρόποις χρησαμένῳ ταῖς ἐν τῷ ζῆν τύχαις· εὐθὺς μὲν γὰρ ἐν ἀρχῇ βασιλευούσης αὐτῷ τῆς μητρὸς Ἀλεξάνδρας ἀρχιερεὺς καταστὰς τοῦ Ἰουδαίων ἔθνους ἔτεσιν ἐννέα τὴν τιμὴν κατέσχεν."},{"number":180,"text":"παραλαβὼν δὲ τὴν βασιλείαν ἀποθανούσης τῆς μητρὸς αὐτῷ καὶ ταύτην κατασχὼν τρεῖς μῆνας ἐκπίπτει μὲν ὑπʼ Ἀριστοβούλου τοῦ ἀδελφοῦ, κατάγεται δʼ αὖθις ὑπὸ Πομπηίου καὶ πάσας τὰς τιμὰς ἀπολαβὼν ἔτη τεσσαράκοντα διετέλεσεν ἐν αὐτοῖς."},{"number":181,"text":"ἀφαιρεθεὶς δὲ τὸ δεύτερον ὑπʼ Ἀντιγόνου καὶ λωβηθεὶς τὸ σῶμα παρὰ Πάρθοις αἰχμάλωτος ἐγένετο. κἀκεῖθεν εἰς τὴν οἰκείαν ἐπανῄει χρόνῳ διὰ τὰς ἐξ Ἡρώδου προτεινομένας ἐλπίδας, ὧν οὐδὲν αὐτῷ κατὰ προσδοκίαν ἀπήντα πολυπαθείᾳ βίου χρησαμένῳ, τὸ δυσχερέστατον δέ, ὡς προειρήκαμεν, ἐν γήρᾳ τέλους οὐκ ἀξίου τυχεῖν·"},{"number":182,"text":"δοκεῖ γὰρ ἐπιεικὴς καὶ μέτριος ἐν πᾶσιν γενέσθαι καὶ τὰ πλεῖστα τῆς ἀρχῆς ὑπὸ διοικηταῖς ἄγειν, οὐ πολυπράγμων οὐδὲ δεινὸς ὢν βασιλείας ἐπιστατεῖν, Ἀντιπάτρῳ τε καὶ Ἡρώδῃ μέχρι τοῦδε προελθεῖν ἐγένετο διὰ τὴν ἐπιείκειαν τὴν ἐκείνου, καὶ τὸ πέρας οὔτε δίκαιον οὔτʼ εὐσεβὲς ἐξ αὐτῶν εὕρατο τοιούτου τέλους."},{"number":183,"text":"Ὁ δὲ Ἡρώδης ὡς καὶ τὸν Ὑρκανὸν ἐκποδὼν ἐποιήσατο, σπεύδων πρὸς Καίσαρα καὶ μηδὲν ἐλπίσαι περὶ τῶν αὐτοῦ πραγμάτων δυνάμενος χρηστὸν ἐκ τῆς γενομένης αὐτῷ πρὸς Ἀντώνιον φιλίας, ὕποπτον μὲν εἶχεν τὴν Ἀλεξάνδραν, μὴ τῷ καιρῷ συνεπιθεμένη τὸ πλῆθος ἀποστήσῃ καὶ στασιάσῃ τὰ περὶ τὴν βασιλείαν πράγματα."},{"number":184,"text":"παρετίθετο δὲ πάντα Φερώρᾳ τἀδελφῷ, καὶ τὴν μητέρα Κύπρον καὶ τὴν ἀδελφὴν καὶ τὴν γενεὰν ἅπασαν ἐν Μασάδοις κατεστήσατο παρακελευσάμενος, εἴ τι περὶ αὐτὸν ἀκούσαιεν δυσχερές, ἔχεσθαι τῶν πραγμάτων."},{"number":185,"text":"Μαριάμμην δὲ τὴν αὐτοῦ γυναῖκα, δυνατὸν γὰρ οὐκ ἦν ἐν διαφορᾷ τῇ πρὸς τὴν ἀδελφὴν καὶ τὴν μητέρα τὴν ἐκείνου δίαιταν τὴν αὐτὴν ἔχειν, ἐν Ἀλεξανδρείῳ σὺν Ἀλεξάνδρᾳ τῇ μητρὶ κατεστήσατο Ἰώσηπον τὸν ταμιαίαν καὶ τὸν Ἰτουραῖον Σόαιμον ἐπʼ αὐτῶν καταλιπών, πιστοτάτους μὲν ἐξ ἀρχῆς γενομένους αὐτῷ, τότε δὲ προφάσει τιμῆς φρουρεῖν ἀπολειφθέντας τὰς γυναῖκας."},{"number":186,"text":"ἦν δὲ κἀκείνοις ἐντολὴ μαθόντας τι περὶ αὐτοῦ δυσχερὲς ἐξ αὐτῆς ἀμφοτέρας μεταχειρίσασθαι, τὴν δὲ βασιλείαν εἰς δύναμιν τοῖς παισὶν αὐτοῦ σὺν τἀδελφῷ Φερώρᾳ διατηρεῖν."},{"number":187,"text":"Ταύτας δοὺς τὰς ἐντολὰς αὐτὸς εἰς Ῥόδον ἠπείγετο Καίσαρι συντυχεῖν. κἀπειδὴ κατέπλευσεν εἰς τὴν πόλιν, ἀφῄρητο μὲν τὸ διάδημα, τοῦ δʼ ἄλλου περὶ αὐτὸν ἀξιώματος οὐδὲν ὑφεικώς, ὅτε καὶ κοινωνῆσαι λόγου κατὰ τὴν συντυχίαν ἠξιώθη, πολὺ μᾶλλον ἐνέφηνεν τὸ μεγαλεῖον τοῦ κατʼ αὐτὸν φρονήματος,"},{"number":188,"text":"οὔτʼ εἰς ἱκεσίαν, ὡς εἰκὸς ἐπὶ τοιούτοις, τραπόμενος οὔτε δέησίν τινα προτείνων ὡς ἐφʼ ἡμαρτημένοις, ἀποδοὺς δὲ τὸν λογισμὸν τῶν πεπραγμένων ἀνυποτιμήτως."},{"number":189,"text":"ἔλεγεν γὰρ τῷ Καίσαρι καὶ φιλίαν αὐτῷ γενέσθαι μεγίστην πρὸς Ἀντώνιον καὶ πάντα πρᾶξαι κατὰ τὴν αὐτοῦ δύναμιν, ὡς ἐπʼ ἐκείνῳ γενήσεται τὰ πράγματα, στρατείας μὲν οὐ κοινωνήσας κατὰ περιολκὰς τῶν Ἀράβων, πέμψας δὲ καὶ χρήματα καὶ σῖτον ἐκείνῳ."},{"number":190,"text":"καὶ ταῦτʼ εἶναι μετριώτερα τῶν ἐπιβαλλόντων αὐτῷ γενέσθαι· τὸν γὰρ ὁμολογοῦντα μὲν εἶναι φίλον, εὐεργέτην δʼ ἐκεῖνον ἐπιστάμενον, παντὶ μέρει καὶ ψυχῆς καὶ σώματος καὶ περιουσίας συγκινδυνεύειν δέον ὧν αὐτὸς ἔλαττον ἢ καλῶς εἶχεν ἀναστραφεὶς ἀλλʼ ἐκεῖνό γε συνειδέναι καλῶς ἑαυτῷ πεποιηκότι τὸ μηδʼ ἡττηθέντα τὴν ἐν Ἀκτίῳ μάχην καταλιπεῖν,"},{"number":191,"text":"μηδὲ συμμεταβῆναι ταῖς ἐλπίσιν φανερῶς ἤδη μεταβαινούσης καὶ τῆς τύχης, φυλάξαι δʼ αὑτὸν, εἰ καὶ μὴ συναγωνιστὴν ἀξιόχρεων, ἀλλὰ σύμβουλόν γε δεξιώτατον Ἀντωνίῳ τὴν μίαν αἰτίαν τοῦ κἂν σώζεσθαι καὶ μὴ τῶν πραγμάτων ἐκπεσεῖν ὑποδεικνύντα, Κλεοπάτραν ἐπανελέσθαι·"},{"number":192,"text":"προανῃρημένης γὰρ ἐκείνης αὐτῷ τε τῶν πραγμάτων ἄρχειν ὑπεῖναι καὶ τὰς πρὸς σὲ συμβάσεις ῥᾷον εὑρίσκεσθαι τῆς ἔχθρας. ὧν οὐδὲν ἐκεῖνος ἐννοηθεὶς ἀλυσιτελῶς μὲν αὐτῷ, συμφερόντως δὲ σοὶ προετίμησεν τὴν ἀβουλίαν."},{"number":193,"text":"νῦν οὖν εἰ μὲν τῇ πρὸς Ἀντώνιον ὀργῇ κρίνεις καὶ τὴν ἐμὴν προθυμίαν, οὐκ ἂν εἴη μοι τῶν πεπραγμένων ἄρνησις οὐδʼ ἀπαξιώσω τὴν ἐμαυτοῦ πρὸς ἐκεῖνον εὔνοιαν ἐκ τοῦ φανεροῦ λέγειν, εἰ δὲ τὸ πρόσωπον ἀνελών, τίς εἰμι πρὸς τοὺς εὐεργέτας καὶ ποῖος φίλος ἐξετάζοις, ἐνέσται σοι πείρᾳ τῶν ἤδη γεγενημένων ἡμᾶς εἰδέναι· τοῦ γὰρ ὀνόματος ὑπαλλαγέντος οὐδὲν ἔλαττον αὐτὸ τὸ τῆς φιλίας βέβαιον ἐν ἡμῖν εὐδοκιμεῖν δυνήσεται."},{"number":194,"text":"Τοιαῦτα λέγων καὶ παράπαν ἐμφαίνων τὸ τῆς ψυχῆς ἐλευθέριον οὐ μετρίως ἐπεσπᾶτο τὸν Καίσαρα φιλότιμον ὄντα καὶ λαμπρόν, ὥστʼ αὐτῷ τὰς τῶν ἐγκλημάτων αἰτίας σύστασιν ἤδη τῆς πρὸς ἐκεῖνον εὐνοίας πραγματεύεσθαι."},{"number":195,"text":"καὶ τό τε διάδημα πάλιν ἀποκαθίστησιν αὐτῷ καὶ προτρεψάμενος μηδὲν ἐλάττω περὶ αὐτὸν ἢ πρότερον ἦν περὶ τὸν Ἀντώνιον φαίνεσθαι, διὰ πάσης ἦγε τιμῆς, προσθεὶς ὅτι καιταιδιος γράψειεν, ἁπάσῃ προθυμίᾳ τὰ πρὸς τοὺς μονομάχους αὐτῷ συλλαβέσθαι τὸν Ἡρώδην."},{"number":196,"text":"τοσαύτης ἀποδοχῆς ἠξιωμένος καὶ παρʼ ἐλπίδας ὁρῶν αὐτῷ πάλιν ἐξ ὑπαρχῆς βεβαιοτέραν τὴν βασιλείαν δόσει Καίσαρος καὶ δόγματι Ῥωμαίων, ὅπερ ἐκεῖνος αὐτῷ πρὸς τὸ βέβαιον ἐπραγματεύσατο, παρέπεμψεν ἐπʼ Αἰγύπτου Καίσαρα, δωρησάμενος ὑπὲρ δύναμιν αὐτόν τε καὶ τοὺς φίλους καὶ πᾶσαν ἐμφαίνων μεγαλοψυχίαν."},{"number":197,"text":"ᾐτεῖτο δὲ καὶ τῶν Ἀντωνίῳ συνήθων Ἀλέξανδρον ὡς μηδὲν ἀνήκεστον παθεῖν, ἀλλὰ τούτου μὲν οὐκ ἔτυχεν ὅρκῳ προκατειλημμένου Καίσαρος·"},{"number":198,"text":"ἐπανῄει δὲ πάλιν εἰς τὴν Ἰουδαίαν πλείονί τε τιμῇ καὶ παρρησίᾳ καὶ τοῖς τὰ ἐναντία προσδοκήσασιν ἔκπληξιν παρέσχεν ὡς ἀεὶ τὸ λαμπρότερον ἐκ τῶν κινδύνων κατʼ εὐμένειαν τοῦ θεοῦ προσεπικτώμενος. εὐθὺς οὖν περὶ τὴν ὑποδοχὴν ἐγεγόνει Καίσαρος ἀπὸ Συρίας εἰς Αἴγυπτον εἰσβαλεῖν μέλλοντος."},{"number":199,"text":"κἀπειδὴ παρῆν, δέχεται μὲν αὐτὸν ἐν Πτολεμαΐδι πάσῃ τῇ βασιλικῇ θεραπείᾳ, παρέσχεν δὲ καὶ τῷ στρατεύματι ξένια καὶ τῶν ἐπιτηδείων ἀφθονίαν. κἀν τοῖς εὐνουστάτοις ἐξητάζετο τάς τε δυνάμεις ἐκτάττοντος συνιππαζόμενος καὶ δεχόμενος αὐτὸν καὶ φίλους ἀνδρῶσιν ἑκατὸν καὶ πεντήκοντα πᾶσιν εἰς πολυτέλειαν καὶ πλοῦτον ὑπηρεσίας ἠσκημένοις."},{"number":200,"text":"παρέσχεν δὲ καὶ τὴν ἄνυδρον διερχομένοις τὴν τῶν ἐπειγόντων χορηγίαν, ὡς μήτε οἴνου μήτε ὕδατος, ὃ καὶ μᾶλλον ἦν ἐν χρείᾳ τοῖς στρατιώταις, ὑστερηθῆναι. αὐτόν γε μὴν Καίσαρα ταλάντοις ὀκτακοσίοις ἐδωρήσατο καὶ παρέστησεν ἅπασιν ἔννοιαν λαβεῖν, ὅτι τῆς βασιλείας ἧς εἶχεν πολὺ μείζω καὶ λαμπρότερα κατὰ τὰς ὑπουργίας ἐπεδείκνυτο."},{"number":201,"text":"τοῦτʼ αὐτὸν καὶ μᾶλλον εἰς πίστιν εὐνοίας καὶ προθυμίας ἐπισυνίστη καὶ πλεῖστον ἠνέγκατο τῇ χρείᾳ τοῦ καιροῦ τὸ μεγαλόψυχον ἁρμόσας. ὁ δὲ καὶ πάλιν ἐπανιόντων ἀπʼ Αἰγύπτου τῶν πρώτων οὐδενὸς τὰς ὑπηρεσίας ἥττων ἐφάνη."}],"7":[{"number":202,"text":"Τότε μέντοι γενόμενος ἐν τῇ βασιλείᾳ τεταραγμένην αὐτῷ τὴν οἰκίαν καταλαμβάνει καὶ χαλεπῶς ἐχούσας τήν τε γυναῖκα Μαριάμμην καὶ τὴν μητέρα τὴν ἐκείνης Ἀλεξάνδραν."},{"number":203,"text":"οἰηθεῖσαι γάρ, ὅπερ ἦν ὕποπτον, οὐκ εἰς ἀσφάλειαν τῶν σωμάτων εἰς ἐκεῖνο κατατεθῆναι τὸ χωρίον, ἀλλʼ ὡς φρουρᾷ μηθενὸς μήτε τῶν ἄλλων μήθʼ αὑτῶν ἐξουσίαν ἔχοιεν, χαλεπῶς ἔφερον."},{"number":204,"text":"ἥ τε Μαριάμμη τὸν μὲν ἔρωτα τοῦ βασιλέως ὑπόκρισιν ἄλλως καὶ πρὸς τὸ συμφέρον αὐτῷ γινομένην ἀπάτην ὑπελάμβανεν, ἤχθετο δὲ τῷ μηδʼ εἰ πάσχοι τι δεινὸν ἐκεῖνος ἐλπίδα τοῦ βιώσεσθαι διʼ αὐτὸν ἐσχηκέναι καὶ τὰς Ἰωσήπῳ δοθείσας ἐντολὰς ἀνεμνημόνευεν, ὥστʼ ἤδη διὰ θεραπείας εἶχεν τοὺς φρουροὺς καὶ μᾶλλον τὸν Σόαιμον, ἐν ἐκείνῳ τὸ πᾶν ἐπισταμένη."},{"number":205,"text":"Σόαιμος δὲ κατὰ μὲν τὰς ἀρχὰς πιστὸς ἦν οὐδὲν ὧν Ἡρώδης ἐνετέταλτο παριείς, λόγοις δὲ καὶ δωρεαῖς λιπαρέστερον τῶν γυναικῶν ἐκθεραπευουσῶν αὐτὸν ἡττᾶτο κατὰ μικρὸν ἤδη καὶ τέλος ἐξεῖπεν ἁπάσας τὰς ἐντολὰς τοῦ βασιλέως, μάλιστα μὲν οὐδʼ ἐλπίσας αὐτὸν ἐπὶ τῆς αὐτῆς ὑποστρέψειν ἐξουσίας·"},{"number":206,"text":"ἐν ᾧ καὶ μᾶλλον ἐκφυγὼν τὸν ἀπʼ αὐτοῦ κίνδυνον οὐ μικρὰ χαριεῖσθαι ταῖς γυναιξὶν ὑπελάμβανεν, αἷς ἦν εἰκὸς οὐκ ἀποτεύξεσθαι τοῦ περιόντος ἀξιώματος, ἀλλὰ καὶ πλέον εἰς τὴν ἀμοιβὴν ἕξειν εἰ βασιλευούσας ἢ τοῦ βασιλεύοντος ἀγχοῦ γενησομένας."},{"number":207,"text":"ἐπήλπιζε δʼ αὐτὸν οὐχ ἧττον, εἰ καὶ πάντα κατὰ νοῦν πράξας ὑποστρέψειεν Ἡρώδης, μηδὲν ὅτι τῇ γυναικὶ δυνήσεσθαι βουλομένῃ γε ἀντειπεῖν· ἠπίστατο γὰρ τὸν πρὸς τὴν Μαριάμμην ἔρωτα μείζονα λόγου τῷ βασιλεῖ."},{"number":208,"text":"ταῦτα προσεκλύσαντα τὰς ἐντολὰς ἐξαγγεῖλαι Μαριάμμη χαλεπῶς ἤκουσεν, εἰ μηδὲν πέρας αὐτῇ τῶν ἐξ Ἡρώδου κινδύνων ἔσται, χαλεπῶς δὲ διέκειτο, μηδενὸς μὲν τυχεῖν αὐτὸν τῶν ἴσων εὐχομένη, δυσύποιστον δʼ εἰ τύχοι τὸν μετʼ αὐτοῦ βίον κρίνουσα. καὶ τοῦτο διέδειξεν ἐν ὑστέρῳ μηδὲν ἐπικρυψαμένη τοῦ κατʼ αὐτὴν πάθους."},{"number":209,"text":"Ὁ μὲν γὰρ ἐπὶ μεγάλοις οἷς παρʼ ἐλπίδας εὐτυχήκει καταπεπλευκὼς πρώτῃ μέν, ὡς εἰκός, τῇ γυναικὶ περὶ τούτων εὐηγγελίζετο, μόνην δὲ ἐκ πάντων διὰ τὸν ἔρωτα καὶ τὴν οὖσαν αὐτῷ συνήθειαν προτιμῶν ἠσπάζετο."},{"number":210,"text":"τῇ δʼ οὔτε τὰς εὐημερίας διηγουμένου χαίρειν μᾶλλον ἢ χαλεπῶς φέρειν συνέβαινεν οὔτʼ ἐπικρύπτεσθαι τὸ πάθος δυνατὸν ἦν. ἀλλʼ ὑπʼ ἀδοξίας καὶ τῆς περιούσης εὐγενείας πρὸς μὲν τοὺς ἀσπασμοὺς ἀνέστενεν, τοῖς δὲ διηγήμασιν ἄχθεσθαι μᾶλλον ἢ συγχαίρειν ἐνέφαινεν, ὡς οὐχ ὕποπτα μόνον ἀλλὰ καὶ καταφανῆ γινόμενα τὸν Ἡρώδην ἐπιταράττειν."},{"number":211,"text":"ἠδημόνει μὲν γὰρ ὁρῶν τὸ παράλογον τῆς γυναικὸς εἰς αὐτὸν μῖσος οὐκ ἀποκεκρυμμένον, ἤχθετο δὲ τῷ πράγματι καὶ τὸν ἔρωτα φέρειν ἀδυνατῶν ταῖς τε ὀργαῖς καὶ ταῖς διαλλαγαῖς οὐκ ἐνέμενεν, ἀεὶ δὲ ἀπὸ θατέρου μεταβαίνων εἰς θάτερον ἐφʼ ἑκατέρῳ πολλὴν εἶχεν ἀπορίαν."},{"number":212,"text":"οὕτως οὖν ἐν μέσῳ τοῦ στυγεῖν καὶ στέργειν ἀποληφθεὶς καὶ πολλάκις ἕτοιμος ὢν ἀμύνασθαι τῆς ὑπερηφανίας αὐτὴν διὰ τὸ προκατειλῆφθαι τὴν ψυχὴν ἀσθενέστερος εἰς τὸ μεταστήσασθαι τὴν ἄνθρωπον ἐγίνετο. τὸ δὲ σύμπαν ἡδέως ἂν ἐκείνην κολάσας ἐδεδοίκει, μὴ λάθοι μείζονα παρʼ αὐτοῦ τὴν τιμωρίαν ἀποθανούσης εἰσπραττόμενος."},{"number":213,"text":"Συνιδοῦσαι δʼ οὕτως αὐτὸν ἔχοντα πρὸς τὴν Μαριάμμην ἥ τε ἀδελφὴ καὶ ἡ μήτηρ κάλλιστον ᾠήθησαν τὸν καιρὸν τοῦ πρὸς ἐκείνην μίσους εἰληφέναι καὶ διελάλουν οὐ μικρῶς παροξύνουσαι τὸν Ἡρώδην διαβολαῖς μῖσος ὁμοῦ καὶ ζηλοτυπίαν ἐμποιεῖν δυνησομέναις."},{"number":214,"text":"ὁ δʼ οὔτε τῶν τοιούτων ἀηδῶς ἤκουσεν λόγων οὔτε δρᾶν τι κατὰ τῆς γυναικὸς ὡς πεπιστευκὼς ἀπεθάρρει, χεῖρον μέντοι πρὸς αὐτὴν εἶχεν ἀεὶ καὶ τὸ πάθος ἀντεξεκαίετο, τῆς μὲν οὐκ ἀποκρυπτομένης τὴν διάθεσιν, τοῦ δὲ τὸν ἔρωτα πρὸς ὀργὴν ἀεὶ μεταλαμβάνοντος."},{"number":215,"text":"κἂν εὐθὺς ἐπράχθη τι τῶν ἀνηκέστων· νῦν δὲ Καίσαρος ἀγγελθέντος κρατεῖν τῷ πολέμῳ καὶ τεθνηκότων Ἀντωνίου καὶ Κλεοπάτρας ἔχειν Αἴγυπτον, ἐπειγόμενος εἰς τὸ Καίσαρι ἀπαντᾶν κατέλιπεν ὡς εἶχεν τὰ περὶ τὴν οἰκίαν."},{"number":216,"text":"ἐξιόντι δὲ Μαριάμμη παραστησομένη τὸν Σόαιμον πολλήν τε χάριν τῆς ἐπιμελείας ὡμολόγει καὶ μεριδαρχίαν αὐτῷ παρὰ τοῦ βασιλέως ᾐτήσατο."},{"number":217,"text":"κἀκεῖνος μὲν τυγχάνει τῆς τιμῆς. Ἡρώδης δὲ γενόμενος ἐν Αἰγύπτῳ Καίσαρί τε μετὰ πλείονος παρρησίας εἰς λόγους ἦλθεν ὡς ἤδη φίλος καὶ μεγίστων ἠξιώθη· τῶν τε γὰρ Κλεοπάτραν δορυφορούντων Γαλατῶν τετρακοσίοις αὐτὸν ἐδωρήσατο καὶ τὴν χώραν ἀπέδωκεν αὐτῷ πάλιν, ἣν διʼ ἐκείνης ἀφῃρέθη. προσέθηκεν δὲ καὶ τῇ βασιλείᾳ Γάδαρα καὶ Ἵππον καὶ Σαμάρειαν ἔτι δὲ τῆς παραλίου Γάζαν καὶ Ἀνθηδόνα καὶ Ἰόπην καὶ Στράτωνος πύργον."},{"number":218,"text":"Ἐπιτυχὼν δὲ καὶ τούτων λαμπρότερος ἦν, καὶ τὸν μὲν Καίσαρα παρέπεμψεν ἐπʼ Ἀντιοχείας, αὐτὸς δʼ ἐπανελθὼν ὅσον ᾤετο τὰ πράγματα αὐτῷ διὰ τῶν ἔξωθεν ἐπιδιδόναι πρὸς εὐδαιμονίαν, τοσοῦτον ἔκαμνεν τοῖς οἰκείοις καὶ μάλιστα περὶ τὸν γάμον, ἐν ᾧ καὶ μᾶλλον εὐτυχεῖν ἐδόκει πρότερον· ἔρωτα γὰρ οὐδενὸς ἐλάττω τῶν ἱστορουμένων ἐπεπόνθει μετὰ τοῦ δικαίου τῆς Μαριάμμης."},{"number":219,"text":"ἡ δὲ τὰ μὲν ἄλλα σώφρων καὶ πιστὴ πρὸς αὐτὸν ἦν, εἶχεν δέ τι καὶ γυναικεῖον ὁμοῦ καὶ χαλεπὸν ἐκ φύσεως, ἱκανῶς μὲν ἐντρυφῶσα δεδουλωμένῳ διὰ τὴν ἐπιθυμίαν καὶ τὸ βασιλεύεσθαι καὶ κρατεῖν ἄλλον αὐτῆς οὐ συγκαταλογιζομένη τῷ καιρῷ πολλάκις μὲν ὑβριστικῶς αὐτῷ προσηνέχθη καὶ τοῦτʼ ἐκεῖνος ἐξειρωνευόμενος ἔφερεν ἐγκρατῶς καὶ μειζόνως,"},{"number":220,"text":"ἀναφανδὸν δὲ τήν τε μητέρα καὶ τὴν ἀδελφὴν ἐπὶ δυσγενείᾳ διεχλεύαζεν καὶ κακῶς ἔλεγεν, ὥστʼ ἤδη στάσιν ἐν ταῖς γυναιξὶν εἶναι καὶ μῖσος ἄσπονδον, ἐν δὲ τῷ τότε καὶ διαβολὰς μείζονας."},{"number":221,"text":"ἥ τε ὑποψία τρεφομένη παρέτεινεν ἐνιαυτοῦ μῆκος ἐξ οὗ παρὰ Καίσαρος Ἡρώδης ὑπεστρόφει. τέλεον μέντοι προοικονομούμενον ἐκ πλείονος ἐξερράγη τοιαύτης ἀφορμῆς ἐγγενομένης·"},{"number":222,"text":"κατακλινόμενος ὁ βασιλεὺς ὡς ἀναπαύσασθαι μεσημβρίας οὔσης ἐκάλει τὴν Μαριάμμην ὑπὸ φιλοστοργίας, ἧς ἀεὶ περὶ αὐτὴν εἶχεν. ἡ δὲ εἰσῆλθεν μέν, οὐ μὴν καὶ κατεκλίθη σπουδάζοντος ἐκφαυλίσασα καὶ προσλοιδορηθεῖσα, τόν τε πατέρα καὶ τὸν ἀδελφὸν αὐτῆς ὡς ἀπεκτόνοι."},{"number":223,"text":"χαλεπῶς δʼ ἐκείνου τὴν ὕβριν ἐνηνοχότος καὶ γεγονότος εἰς προπέτειαν ἑτοίμου, τῆς ταραχῆς αἰσθομένη μείζονος ἡ τοῦ βασιλέως ἀδελφὴ Σαλώμη παρεσκευασμένον ἐκ πλείστου τὸν οἰνοχόον εἰσπέμπει κελεύουσα λέγειν, ὡς πείθοι Μαριάμμη φίλτρον αὐτῇ συγκατασκευάσαι τῷ βασιλεῖ."},{"number":224,"text":"κἂν ταραχθῇ καὶ πυνθάνηται, τί ποτε τοῦτʼ ἦν, λέγειν ὅτι φάρμακον ἐκείνης μὲν ἐχούσης αὐτοῦ δὲ διακονῆσαι παρακαλουμένου, μὴ κινηθέντος δʼ ἐπὶ τῷ φίλτρῳ τὸν λόγον ἀργὸν ἐᾶν· οὐδένα γὰρ αὐτῷ κίνδυνον φέρειν. τοιαῦτα προδιδάξασα κατʼ ἐκεῖνον τὸν καιρὸν εἰσπέμπει διαλεξόμενον."},{"number":225,"text":"ὁ δὲ πιθανῶς ἅμα καὶ μετὰ σπουδῆς εἰσῄει, δῶρα μὲν αὐτῷ τὴν Μαριάμμην παρεσχῆσθαι λέγων, ἀναπείθειν δὲ φίλτρον αὐτῷ διδόναι. πρὸς τοῦτο διακινηθέντος καὶ τί τὸ φίλτρον εἴη ἐρωτήσαντος, φάρμακον εἶπεν ὑπʼ ἐκείνης διδόμενον, οὗ τὴν δύναμιν αὐτὸς οὐκ εἰδέναι, διὸ καὶ προσαγγεῖλαι τοῦτʼ ἀσφαλέστερον αὐτῷ καὶ τῷ βασιλεῖ διειληφότα."},{"number":226,"text":"τοιούτων ἀκούσας Ἡρώδης λόγων καὶ πρότερον κακῶς διακείμενος ἔτι μᾶλλον ἠρεθίσθη, τόν τʼ εὐνοῦχον, ὃς ἦν τῇ Μαριάμμῃ πιστότατος, ἐβασάνιζεν ὑπὲρ τοῦ φαρμάκου γινώσκων, ὡς οὐ χωρὶς ἐκείνου τι δυνατὸν ἦν οὔτε μεῖζον οὔτε ἔλαττόν τι πεπρᾶχθαι."},{"number":227,"text":"γενόμενος δὲ ἐν ταῖς ἀνάγκαις ὁ ἄνθρωπος, οὐδὲν μὲν ὧν ἕνεκεν ἐβασανίζετο λέγειν εἶχεν, τὸ μέντοι τῆς γυναικὸς ἔχθος εἰς αὐτὸν ἔφη γενέσθαι διὰ τοὺς λόγους, οὓς ὁ Σόαιμος αὐτῇ φράσαι."},{"number":228,"text":"ταῦτα δʼ ἔτι λέγοντος μέγα βοήσας ὁ βασιλεὺς οὐκ ἂν ἔφη Σόαιμον πιστότατον ὄντα τόν γε ἄλλον χρόνον αὐτῷ καὶ τῇ βασιλείᾳ καταπροδοῦναι τὰς ἐντολάς, εἰ μὴ καὶ περαιτέρω προεληλύθει τῆς πρὸς τὴν Μαριάμμην κοινωνίας."},{"number":229,"text":"καὶ τὸν μὲν Σόαιμον εὐθὺς ἐκέλευσεν ἀποκτεῖναι συλλαβόντας· τῇ δὲ γυναικὶ κρίσιν ἀπεδίδου συναγαγὼν τοὺς οἰκειοτάτους αὐτῷ καὶ τὴν κατηγορίαν ἐσπουδασμένην ποιούμενος ὑπὲρ τῶν κατὰ τὰς διαβολὰς φίλτρων καὶ φαρμάκων. ἦν δὲ ἀκρατὴς ἐν τῷ λόγῳ καὶ κρίσεως ὀργιλαίτερος, καὶ τέλος οὕτως ἔχοντα γινώσκοντες αὐτὸν οἱ παρόντες θάνατον αὐτῆς κατεψηφίσαντο."},{"number":230,"text":"διενεχθείσης δὲ τῆς γνώμης ὑπεγίνετο μέν τι καὶ τοιοῦτον αὐτῷ τε καί τισιν τῶν παρόντων μὴ προπετῶς οὕτως ἀναιρεῖν, καταθέσθαι δὲ εἰς ἕν τι τῶν ἐν τῇ βασιλείᾳ φρουρίων."},{"number":231,"text":"ἐσπουδάσθη δὲ ταῖς περὶ τὴν Σαλώμην ἐκποδὼν ποιήσασθαι τὴν ἄνθρωπον καὶ μᾶλλον ἔπεισαν τὸν βασιλέα τὰς ταραχὰς τοῦ πλήθους, εἰ ζῶσα τύχοι, φυλάξασθαι συμβουλεύουσαι. Μαριάμμη μὲν οὖν οὕτως ἤγετο τὴν ἐπὶ θανάτῳ."},{"number":232,"text":"Συνθεωρήσασα δὲ τὸν καιρὸν ἡ Ἀλεξάνδρα, καὶ διότι μικρὰς ἐλπίδας ἔχοι μὴ καὶ αὐτὴ τῶν ὁμοίων ἐξ Ἡρώδου τυχεῖν, ἐναντίως πρὸς τὸ πρῶτον θράσος καὶ λίαν ἀπρεπῶς μετεβάλετο·"},{"number":233,"text":"βουλομένη γὰρ ἐμφῆναι τὴν ἄγνοιαν ὧν ἐκείνη τὰς αἰτίας εἶχεν, ἐκπηδήσασα καὶ λοιδορουμένη τῇ θυγατρὶ πάντων ἀκουόντων ἐβόα κακὴν πρὸς τὸν ἄνδρα καὶ ἀχάριστον γενέσθαι καὶ δίκαια πάσχειν ἐπὶ τοῖς τοιούτοις τολμήσασαν· οὐ γὰρ ἀμείψασθαι δεόντως τὸν πάντων αὐτῶν εὐεργέτην."},{"number":234,"text":"τοιαῦτα μεταξὺ καθυποκρινομένης ἀσχημόνως καὶ τολμώσης ἐφάπτεσθαι καὶ τῶν τριχῶν, πολλὴ μέν, ὡς εἰκός, καὶ παρὰ τῶν ἄλλων ἡ κατάγνωσις ἦν τῆς ἀπρεποῦς προσποιήσεως, μᾶλλον δὲ ἐνεφάνη παρʼ αὐτῆς τῆς ἀπολλυμένης·"},{"number":235,"text":"οὔτε γὰρ λόγον δοῦσα τὴν ἀρχὴν οὔτε ταραχθεῖσα πρὸς τὴν ἐκείνης δυσχέρειαν ἐπέβλεπεν ἀλλʼ ὡς ὑπὸ φρονήματος τὴν ἁμαρτίαν καὶ μᾶλλον ἄχθεσθαι περιφανῶς ἀσχημονούσης ἐνέφηνεν."},{"number":236,"text":"αὐτή γε μὴν ἀτρεμαίῳ τῷ καταστήματι καὶ τῇ χρόᾳ τῆς σαρκὸς ἀμεταβλήτῳ πρὸς τὸν θάνατον ἀπῄει, τὴν εὐγένειαν οὐδʼ ἐν τοῖς ἐσχάτοις ἄδηλον τοῖς ἐπιθεωροῦσιν αὐτὴν ἐμφαίνουσα."},{"number":237,"text":"Κἀκείνη μὲν οὕτως ἀπέθανεν γυνὴ καὶ πρὸς ἐγκράτειαν καὶ πρὸς μεγαλοψυχίαν ἄριστα γεγενημένη, τὸ δʼ ἐπιεικὲς ἔλιπεν αὐτῇ καὶ πλεῖον ἦν ἐν τῇ φύσει τὸ φιλόνεικον· κάλλει δὲ σώματος καὶ τῷ περὶ τὰς ἐντεύξεις ἀξιώματι μειζόνως φράσαι τὰς κατʼ αὐτὴν ὑπερῆγεν,"},{"number":238,"text":"ἥ τε πλείων ἀφορμὴ τοῦ μὴ κεχαρισμένως τῷ βασιλεῖ μηδὲ πρὸς ἡδονὴν ζῆν ἐντεῦθεν ἐγεγόνει· θεραπευομένη γὰρ διὰ τὸν ἔρωτα καὶ δυσχερὲς οὐδὲν ἐξ ἐκείνου προσδοκῶσα τὴν παρρησίαν ἀσύμμετρον εἶχεν."},{"number":239,"text":"ἠνία δʼ αὐτὴν καὶ τὰ περὶ τοὺς οἰκείους καὶ ταῦτα πάντα πρὸς ἐκεῖνον ὡς ἐπεπόνθει λέγειν ἠξίου, καὶ πέρας ἐξενίκησεν ἐχθρὰς αὐτῇ γενέσθαι τήν τε μητέρα καὶ τὴν ἀδελφὴν τοῦ βασιλέως κἀκεῖνον αὐτόν, ᾧ μόνῳ τὸ μὴ παθεῖν τι δυσχερὲς ἀπεπίστευεν."},{"number":240,"text":"Ἀναιρεθείσης δʼ αὐτῆς τότε καὶ μᾶλλον ἐξήφθη τὰ περὶ τὴν ἐπιθυμίαν τοῦ βασιλέως ἔχοντος μὲν οὕτως, ὡς καὶ πρότερον ἐδηλώσαμεν· οὐ γὰρ ἀπαθὴς οὐδʼ οἷος ἂν ἐκ συνηθείας ἦν ὁ πρὸς αὐτὴν ἔρως, ἀλλὰ καὶ πρότερον ἦρξεν ἐνθουσιαστικῶς καὶ τῇ παρρησίᾳ τῆς συμβιώσεως οὐκ ἀπενικήθη μὴ πλείων ἀεὶ γίνεσθαι·"},{"number":241,"text":"τότε μέντοι καὶ μᾶλλον ἐδόκει κατὰ νέμεσίν τινα τῆς κατὰ τὴν Μαριάμμην ἀπωλείας ἐπιθέσθαι, καὶ πολλάκις μὲν ἀνακλήσεις ἦσαν αὐτῆς, πολλάκις δὲ καὶ θρῆνος ἀσχήμων, ἐπενόει δὲ πᾶν εἴ τι δυνατὸν εἰς ψυχαγωγίαν πότους καὶ συνουσίας αὐτῷ πραγματευόμενος, καὶ τούτων οὐδὲν ἤρκει."},{"number":242,"text":"τὰς οὖν διοικήσεις τῶν κατὰ τὴν βασιλείαν παρῃτεῖτο καὶ τοσοῦτον ἥττητο τοῦ πάθους, ὥστʼ αὐτὸν ἤδη καὶ καλεῖν τὴν Μαριάμμην προστάξαι τοῖς ὑπηρέταις ὡς ζῶσαν ἔτι καὶ δυναμένην ὑπακούειν."},{"number":243,"text":"οὕτως δὲ ἔχοντος ἐπιγίνεται λοιμώδης νόσος, ἣ καὶ τῶν ὄχλων τοὺς πλείους καὶ τῶν φίλων αὐτοῦ τοὺς ἐντιμοτάτους διέφθειρεν καὶ παρέσχεν ἅπασιν ἐξυπονοῆσαι κατὰ μῆνιν τοῦτο συνενεχθῆναι τῶν κατὰ τὴν γενομένην παρανομίαν ἐπὶ τῇ Μαριάμμῃ."},{"number":244,"text":"χεῖρον οὖν διετίθει καὶ τοῦτʼ αὐτὸ τὸν βασιλέα, καὶ τέλος εἰς τὰς ἐρημίας αὑτὸν διδοὺς καὶ προφάσει κυνηγεσίων ταύταις ἐναδημονῶν οὐκ ἔφθη πλείους διενεγκεῖν ἡμέρας καὶ περιπίπτει νόσῳ δυσχερεστάτῃ·"},{"number":245,"text":"φλόγωσις γὰρ ἦν καὶ πεῖσις ἰνίου καὶ τῆς διανοίας παραλλαγή· τῶν τε θεραπευμάτων οὐδὲν ὅ τι καὶ πρὸς ὠφέλειαν ἐξήνυεν, ἀλλʼ ἐναντιούμενα τέως εἰς ἀπόγνωσιν ἦγεν."},{"number":246,"text":"ὅσοι τε περὶ αὐτὸν ἦσαν ἰατροὶ τὰ μὲν οἷς αὐτοὶ προσέφερον βοηθήμασιν οὐδὲν ὑπεικούσης τῆς νόσου, τὰ δὲ καὶ τοῦ βασιλέως οὐκ ἔχοντος ἄλλως ἢ κατὰ τὸ βιαζόμενον τῆς ἀρρωστίας διαιτᾶσθαι, πάνθʼ οἷς ἐκεῖνος ἐπενεχθείη παρέχειν ἠξίουν, τὸ δύσελπι τῆς σωτηρίας ἐν ἐξουσίᾳ τῆς διαίτης ἀνατιθέντες τῇ τύχῃ. κἀκεῖνος μὲν ἐν Σαμαρείᾳ τῇ κληθείσῃ Σεβαστῇ τοῦτον τὸν τρόπον ἐνοσηλεύετο."},{"number":247,"text":"Διατρίβουσα δὲ ἐν τοῖς Ἱεροσολύμοις Ἀλεξάνδρα καὶ πυνθανομένη τὰ κατʼ αὐτὸν ἐσπουδάκει τῶν περὶ τὴν πόλιν φρουρίων ἐγκρατὴς γενέσθαι."},{"number":248,"text":"δύο δʼ ἦν, ἓν μὲν αὐτῆς τῆς πόλεως, ἕτερον δὲ τοῦ ἱεροῦ, καὶ τούτων οἱ κρατοῦντες ὑποχείριον τὸ πᾶν ἔθνος ἐσχήκασιν· τὰς μὲν γὰρ θυσίας οὐκ ἄνευ τούτων οἷόν τε γενέσθαι, τὸ δὲ μὴ ταύτας συντελεῖν οὐδενὶ Ἰουδαίων δυνατὸν τοῦ ζῆν ἑτοιμότερον ἂν παραχωρησάντων ἢ τῆς θρησκείας, ἣν εἰς τὸν θεὸν εἰώθασιν συντελεῖν."},{"number":249,"text":"τοῖς οὖν ἐπὶ τούτων τῶν φυλακτηρίων Ἀλεξάνδρα προσήνεγκεν τοὺς λόγους, ὡς δέον αὐτῇ καὶ τοῖς ἐξ Ἡρώδου παιδίοις παραδοῦναι, μὴ καὶ φθῇ τις ἐκείνου μεταλλάξαντος ἕτερος ἀντιλαμβάνεσθαι τῶν πραγμάτων· ῥωσθέντι μὲν γὰρ οὐδεὶς ἀσφαλέστερον τῶν οἰκειοτάτων διατηρήσει."},{"number":250,"text":"τούτους τοὺς λόγους αὐτῆς οὐκ ἐπιεικῶς ἤνεγκαν, ἀλλὰ πιστοὶ καὶ τὸν ἔμπροσθεν χρόνον ὄντες ἔτι μᾶλλον ἐν τῷ τότε διέμειναν μίσει τε τῆς Ἀλεξάνδρας καὶ τῷ μηδʼ ὅσιον ὑπολαμβάνειν ζῶντα τὸν Ἡρώδην ἀπεγνωκέναι· φίλοι γὰρ ἄνωθεν ἦσαν, εἷς δʼ αὐτῶν καὶ ἀνεψιὸς τοῦ βασιλέως Ἀχίαβος."},{"number":251,"text":"εὐθὺς οὖν ἐξήγγειλαν πέμψαντες ἐκείνῳ τὴν γνώμην τῆς Ἀλεξάνδρας. ὁ δὲ τὴν μὲν οὐδὲν ἀναβαλλόμενος ἀποκτεῖναι προσέταξεν, αὐτὸς δὲ μόλις καὶ σὺν κακοπαθείᾳ διαφυγὼν τὴν νόσον χαλεπὸς ἦν ψυχῇ καὶ σώματι κεκακωμένος ὁμοῦ πρὸς τὸ δυσάρεστον καὶ πάσαις ταῖς αἰτίαις ἑτοιμοτέρως εἰς τιμωρίαν τῶν ὑποπεσόντων ἐχρῆτο."},{"number":252,"text":"φονεύει δὲ καὶ τοὺς ἀναγκαιοτάτους αὐτῷ φίλους Κοστόβαρον καὶ Λυσίμαχον καὶ τὸν Γαδία καλούμενον Ἀντίπατρον ἔτι δὲ Δοσίθεον ἐξ αἰτίας τοιαύτης·"},{"number":253,"text":"Κοστόβαρος ἦν γένει μὲν Ἰδουμαῖος, ἀξιώματος τῶν πρώτων παρʼ αὐτοῖς καὶ προγόνων ἱερατευσάντων τῷ Κωζαι· θεὸν δὲ τοῦτον Ἰδουμαῖοι νομίζουσιν."},{"number":254,"text":"Ὑρκανοῦ δὲ τὴν πολιτείαν αὐτῶν εἰς τὰ Ἰουδαίων ἔθη καὶ νόμιμα μεταστήσαντος Ἡρώδης παραλαβὼν τὴν βασιλείαν ἄρχοντα τῆς Ἰδουμαίας καὶ Γάζης ἀποδείκνυσιν τὸν Κοστόβαρον καὶ δίδωσιν αὐτῷ τὴν ἀδελφὴν Σαλώμην Ἰώσηπον ἀνελὼν τὸν εἰληφότα πρότερον αὐτήν, ὡς ἐδηλώσαμεν."},{"number":255,"text":"Κοστόβαρος δὲ τούτων τυχὼν ἀσμένως καὶ παρὰ δόξαν ἤρθη μᾶλλον ὑπὸ τῆς εὐτυχίας καὶ κατὰ μικρὸν ἐξέβαινεν, οὔθʼ αὑτῷ καλὸν ἡγούμενος ἄρχοντος Ἡρώδου τὸ προσταττόμενον ποιεῖν οὔτε τοῖς Ἰδουμαίοις τὰ Ἰουδαίων μεταλαβοῦσιν ὑπʼ ἐκείνοις εἶναι."},{"number":256,"text":"καὶ διαπέμπεται πρὸς Κλεοπάτραν τὴν Ἰδουμαίαν φάμενος ἀεὶ τῶν ἐκείνης προγόνων γεγενῆσθαι, καὶ διὰ τοῦτʼ εἶναι δίκαιον αἰτεῖσθαι παρʼ Ἀντωνίου τὴν χώραν· αὐτὸς γὰρ ἕτοιμος εἶναι μεταφέρειν τὴν εὔνοιαν εἰς ἐκείνην."},{"number":257,"text":"ἔπραττεν δὲ ταῦτα τῇ Κλεοπάτρᾳ μὲν οὐδέν τι μᾶλλον εἰς τὴν ἀρχὴν ἀρεσκόμενος, εἰ δὲ παραιρεθείη τῶν πλειόνων Ἡρώδης, εὐεπιχείρητον ἤδη νομίζων καὶ κατʼ αὐτὸν ἄρξαι τοῦ τῶν Ἰδουμαίων γένους καὶ μεῖζον πράξειν· ἐπιδιέβαινεν γὰρ ταῖς ἐλπίσιν οὐκ ὀλίγας ἀφορμὰς ἔχων γένους καὶ χρημάτων, ἃ μετὰ διηνεκοῦς αἰσχροκερδείας ἐπεπόριστο, καὶ μικρὸν οὐδὲν ἐπενόει."},{"number":258,"text":"Κλεοπάτρα μὲν οὖν Ἀντωνίου δεηθεῖσα περὶ τῆς χώρας ταύτης ἀποτυγχάνει. λέγονται δὲ πρὸς Ἡρώδην οἱ λόγοι κἀκεῖνος ἕτοιμος ὢν ἀποκτεῖναι τὸν Κοστόβαρον ὅμως τῆς ἀδελφῆς αὐτοῦ δεηθείσης καὶ τῆς μητρὸς ἀφίησιν καὶ συγγνώμης ἠξίωσεν, οὐκ ἀνύποπτον αὐτὸν εἰς τὸ λοιπὸν ἔχων τῆς ἐπιχειρήσεως τῆς τότε."},{"number":259,"text":"Χρόνου δὲ διελθόντος ἐπισυνέβη τὴν Σαλώμην στασιάσαι πρὸς τὸν Κοστόβαρον, καὶ πέμπει μὲν εὐθὺς αὐτῷ γραμμάτιον ἀπολυομένη τὸν γάμον οὐ κατὰ τοὺς Ἰουδαίων νόμους· ἀνδρὶ μὲν γὰρ ἔξεστιν παρʼ ἡμῖν τοῦτο ποιεῖν, γυναικὶ δὲ οὐδὲ διαχωρισθείσῃ καθʼ αὑτὴν γαμηθῆναι μὴ τοῦ πρότερον ἀνδρὸς ἐφιέντος."},{"number":260,"text":"οὐ μὴν ἡ Σαλώμη τὸν ἐγγενῆ νόμον, ἀλλὰ τὸν ἀπʼ ἐξουσίας ἑλομένη τήν τε συμβίωσιν προαπηγόρευσεν καὶ πρὸς τὸν ἀδελφὸν Ἡρώδην ἔλεγεν ὑπὸ τῆς εἰς ἐκεῖνον εὐνοίας ἀποστῆναι τἀνδρός· ἐγνωκέναι γὰρ αὐτὸν μετʼ Ἀντιπάτρου καὶ Λυσιμάχου καὶ Δοσιθέου νεωτέρων ἐφιέμενον. καὶ πίστιν παρεῖχεν τοῦ λόγου τοὺς Σάββα παῖδας, ὅτι διασώζοιντο παρʼ αὐτῷ χρόνον ἐνιαυτῶν ἤδη δεκαδύο."},{"number":261,"text":"τοῦτο δὲ εἶχεν οὕτως καὶ πολλὴν ἔκπληξιν ἐνεποίησεν τῷ βασιλεῖ παρʼ ἐλπίδας ἀκουσθέν, ἐκεκίνητό τε μᾶλλον ἐπὶ τῷ παραδόξῳ τοῦ λόγου· τὰ γὰρ περὶ τοὺς Σάββα παῖδας ἐσπουδάσθη μὲν αὐτῷ πρότερον ἐπεξελθεῖν αὐτοὺς δυσμενεῖς γενομένους τῇ διαθέσει, τότε δὲ διὰ τὸ μῆκος τοῦ χρόνου καὶ τῆς μνήμης ἐξεληλύθεσαν."},{"number":262,"text":"ἡ δὲ ἔχθρα πρὸς αὐτοὺς καὶ τὸ μῖσος ἀπὸ τοιούτων ἦν· Ἀντιγόνου τὴν βασιλείαν ἔχοντος Ἡρώδης μὲν ἐπολιόρκει δυνάμει τὴν τῶν Ἱεροσολυμιτῶν πόλιν, ὑπὸ δὲ χρείας κακῶν, ὅσα τοῖς πολιορκουμένοις παρίσταται, πλείους ἦσαν οἱ τὸν Ἡρώδην ἐπικαλούμενοι καὶ πρὸς ἐκεῖνον ἀπονεύοντες ἤδη ταῖς ἐλπίσιν."},{"number":263,"text":"ὄντες δὲ ἐπʼ ἀξιώματος οἱ τοῦ Σάββα παῖδες καὶ παρὰ τῷ πλήθει δυνατοί, πιστοὶ διετέλουν Ἀντιγόνῳ τόν τε Ἡρώδην διέβαλλον ἀεὶ καὶ συμφυλάττειν τοῖς βασιλεῦσιν τὴν ἐκ γένους ἀρχὴν προύτρεπον. ἐκεῖνοι μὲν οὖν ἅμα καὶ συμφέρειν αὐτὰ νομίζοντες ἐπὶ τοιούτων ἐπολιτεύοντο."},{"number":264,"text":"τῆς δὲ πόλεως ἁλισκομένης καὶ κρατοῦντος τῶν πραγμάτων Ἡρώδου Κοστόβαρος ἀποδειχθεὶς τὰς διεκβολὰς ἀναφράττειν καὶ φρουρεῖν τὴν πόλιν, ὡς μὴ διαπίπτειν ἐξ αὐτῆς τοὺς ὑπόχρεως τῶν πολιτῶν ἢ τἀναντία τῷ βασιλεῖ πολιτευομένους, εἰδὼς ἐν ὑπολήψει καὶ τιμῇ τοὺς Σάββα τῷ παντὶ πλήθει καὶ νομίζων μέγα μέρος αὐτῷ γενήσεσθαι πρὸς τὰς μεταβολὰς τῶν πραγμάτων τὴν ἐκείνων σωτηρίαν ὑπεξέθετο καὶ κατέκρυψεν ἐν οἰκείοις χωρίοις."},{"number":265,"text":"καὶ τότε μὲν Ἡρώδην, διεληλύθει γὰρ ἡ τῆς ἀληθείας ὑποψία, πιστωσάμενος ὅρκοις ἦ μὴν οὐδὲν εἰδέναι τῶν κατʼ ἐκείνους ἀφεῖτο τῆς ὑπονοίας. αὖθις δὲ κηρύγματα καὶ μήνυτρα τοῦ βασιλέως ἐκτιθέντος καὶ πάντα τρόπον ἐρεύνης ἐπινοοῦντος οὐκ ἦλθεν εἰς ὁμολογίαν, ἀλλὰ τῷ τὸ πρῶτον ἔξαρνος γενέσθαι τὸ φωραθῆναι τοὺς ἄνδρας οὐκ ἀνυποτίμητον αὐτῷ πεπεισμένος οὐ μόνον ἐκ τῆς εὐνοίας, ἀλλὰ καὶ τῆς ἀνάγκης ἤδη τοῦ λανθάνειν αὐτοὺς περιείχετο."},{"number":266,"text":"περὶ τούτων ἐξαγγελθέντων αὐτῷ διὰ τῆς ἀδελφῆς ὁ βασιλεὺς πέμψας εἰς τοὺς τόπους, ἐν οἷς διατρίβειν ἐμηνύθησαν, ἐκείνους τε καὶ τοὺς συγκαταιτιαθέντας ἀπέκτεινεν, ὥστʼ εἶναι μηδὲν ὑπόλοιπον ἐκ τῆς Ὑρκανοῦ συγγενείας, ἀλλὰ τὴν βασιλείαν αὐτεξούσιον αὐτῷ μηδενὸς ὄντος ἐπʼ ἀξιώματος ἐμποδὼν ἵστασθαι τοῖς παρανομουμένοις."}],"8":[{"number":267,"text":"Διὰ τοῦτο καὶ μᾶλλον ἐξέβαινεν τῶν πατρίων ἐθῶν καὶ ξενικοῖς ἐπιτηδεύμασιν ὑποδιέφθειρεν τὴν πάλαι κατάστασιν ἀπαρεγχείρητον οὖσαν, ἐξ ὧν οὐ μικρὰ καὶ πρὸς τὸν αὖθις χρόνον ἠδικήθημεν ἀμεληθέντων ὅσα πρότερον ἐπὶ τὴν εὐσέβειαν ἦγεν τοὺς ὄχλους·"},{"number":268,"text":"πρῶτον μὲν γὰρ ἀγῶνα πενταετηρικὸν ἀθλημάτων κατεστήσατο Καίσαρι καὶ θέατρον ἐν Ἱεροσολύμοις ᾠκοδόμησεν, αὖθίς τʼ ἐν τῷ πεδίῳ μέγιστον ἀμφιθέατρον, περίοπτα μὲν ἄμφω τῇ πολυτελείᾳ, τοῦ δὲ κατὰ τοὺς Ἰουδαίους ἔθους ἀλλότρια· χρῆσίς τε γὰρ αὐτῶν καὶ θεαμάτων τοιούτων ἐπίδειξις οὐ παραδίδοται."},{"number":269,"text":"τὴν μέντοι πανήγυριν ἐκεῖνος ἐπιφανεστάτην τὴν τῆς πενταετηρίδος συνετέλει καταγγείλας τε τοῖς πέριξ καὶ συγκαλῶν ἀπὸ τοῦ παντὸς ἔθνους. οἱ δʼ ἀθληταὶ καὶ τὰ λοιπὰ τῶν ἀγωνισμάτων ἀπὸ πάσης γῆς ἐκαλοῦντο κατʼ ἐλπίδα τῶν προκειμένων καὶ τῆς νίκης εὐδοξίᾳ, συνελέγησάν τε οἱ κορυφαιότατοι τῶν ἐν τοῖς ἐπιτηδεύμασιν·"},{"number":270,"text":"οὐ γὰρ μόνον τοῖς περὶ τὰς γυμνικὰς ἀσκήσεις, ἀλλὰ καὶ τοῖς ἐν τῇ μουσικῇ διαγινομένοις καὶ θυμελικοῖς καλουμένοις προυτίθει μέγιστα νικητήρια· καὶ διεσπούδαστο πάντας τοὺς ἐπισημοτάτους ἐλθεῖν ἐπὶ τὴν ἅμιλλαν."},{"number":271,"text":"προύθηκεν δὲ καὶ τεθρίπποις καὶ συνωρίσιν καὶ κέλησιν οὐ μικρὰς δωρεάς, καὶ πάνθʼ, ὅσα κατὰ πολυτέλειαν ἢ σεμνοπρέπειαν παρʼ ἑκάστοις ἐσπούδαστο φιλοτιμίᾳ τοῦ διάσημον αὐτῷ γενέσθαι τὴν ἐπίδειξιν ἐξεμιμήσατο."},{"number":272,"text":"τό γε μὴν θέατρον ἐπιγραφαὶ κύκλῳ περιεῖχον Καίσαρος καὶ τρόπαια τῶν ἐθνῶν, ἃ πολεμήσας ἐκεῖνος ἐκτήσατο, χρυσοῦ τε ἀπέφθου καὶ ἀργύρου πάντων αὐτῷ πεποιημένων."},{"number":273,"text":"τὰ δʼ εἰς ὑπηρεσίαν οὐδὲν οὕτως ἦν οὔτʼ ἐσθῆτος τίμιον οὔτε σκευῆς λίθων, ὃ μὴ τοῖς ὁρωμένοις ἀγωνίσμασιν συνεπεδείκνυτο. παρασκευὴ δὲ καὶ θηρίων ἐγένετο λεόντων τε πλείστων αὐτῷ συναχθέντων καὶ τῶν ἄλλων, ὅσα καὶ τὰς ἀλκὰς ὑπερβαλλούσας ἔχει καὶ τὴν φύσιν ἐστὶν σπανιώτερα·"},{"number":274,"text":"τούτων αὐτῶν τε πρὸς ἄλληλα συμπλοκαὶ καὶ μάχαι πρὸς αὐτὰ τῶν κατεγνωσμένων ἀνθρώπων ἐπετηδεύοντο, τοῖς μὲν ξένοις ἔκπληξις ὁμοῦ τῆς δαπάνης καὶ ψυχαγωγία τῶν περὶ τὴν θέαν κινδύνων, τοῖς δʼ ἐπιχωρίοις φανερὰ κατάλυσις τῶν τιμωμένων παρʼ αὐτοῖς ἐθῶν·"},{"number":275,"text":"ἀσεβὲς μὲν γὰρ ἐκ προδήλου κατεφαίνετο θηρίοις ἀνθρώπους ὑπορρίπτειν ἐπὶ τέρψει τῆς ἀνθρώπων θέας, ἀσεβὲς δὲ ξενικοῖς ἐπιτηδεύμασιν ἐξαλλάττειν τοὺς ἐθισμούς."},{"number":276,"text":"πάντων δὲ μᾶλλον ἐλύπει τὰ τρόπαια· δοκοῦντες γὰρ εἰκόνας εἶναι τὰς τοῖς ὅπλοις περιειλημμένας, ὅτι μὴ πάτριον ἦν αὐτοῖς τὰ τοιαῦτα σέβειν, οὐ μετρίως ἐδυσχέραινον."},{"number":277,"text":"Ἐλάνθανον δʼ οὐδὲ τὸν Ἡρώδην ἐκταραττόμενοι· καὶ βίαν μὲν ἐπάγειν ἄκαιρον ᾤετο, καθωμίλει δʼ ἐνίους καὶ παρηγόρει τῆς δεισιδαιμονίας ἀφαιρούμενος. οὐ μὴν ἔπειθεν, ἀλλʼ ὑπὸ δυσχερείας ὧν ἐδόκουν ἐκεῖνον πλημμελεῖν ὁμοθυμαδὸν ἐξεβόων, εἰ καὶ πάντα δοκοῖεν οἰστά, μὴ φέρειν εἰκόνας ἀνθρώπων ἐν τῇ πόλει, τὰ τρόπαια λέγοντες· οὐ γὰρ εἶναι πάτριον αὐτοῖς."},{"number":278,"text":"Ἡρώδης δὲ τεταραγμένους ὁρῶν καὶ μὴ ῥᾳδίως ἂν μεταπεσόντας, εἰ μὴ τύχοιεν παρηγορίας, καλέσας αὐτῶν τοὺς ἐπιφανεστάτους εἰς τὸ θέατρον παρήγαγεν καὶ δείξας τὰ τρόπαια, τί ποτʼ ἔστιν ὃ δοκεῖ ταῦτα αὐτοῖς ἐπύθετο."},{"number":279,"text":"τῶν δὲ ἐκβοησάντων ἀνθρώπων εἰκόνες, ἐπιτάξας ἀφαιρεθῆναι τὸν περιθέσιμον κόσμον ἐπιδείκνυσιν αὐτοῖς γυμνὰ τὰ ξύλα. τὰ δʼ εὐθὺς ἦν ἀποσυληθέντα γέλως καὶ πλεῖστον εἰς διάχυσιν ἐδυνήθη τὸ καὶ πρότερον αὐτοὺς ἐν εἰρωνείᾳ τίθεσθαι τὰς κατασκευὰς τῶν ἀγαλμάτων."},{"number":280,"text":"Τοῦτον δὲ τὸν τρόπον αὐτοῦ παρακρουσαμένου τὸ πλῆθος καὶ τὴν ὁρμὴν ἣν ἐπεπόνθεισαν ἐξ ὀργῆς διαχέαντος, οἱ μὲν πλείους εἶχον ὡς μεταβεβλῆσθαι καὶ μὴ χαλεπαίνειν ἔτι,"},{"number":281,"text":"τινὲς δʼ αὐτῶν ἐπέμενον τῇ δυσχερείᾳ τῶν οὐκ ἐξ ἔθους ἐπιτηδευμάτων, καὶ τὸ καταλύεσθαι τὰ πάτρια μεγάλων ἡγούμενοι ἀρχὴν κακῶν ὅσιον ᾠήθησαν ἀποκινδυνεῦσαι μᾶλλον ἢ δοκεῖν ἐξαλλαττομένης αὐτοῖς τῆς πολιτείας περιορᾶν Ἡρώδην πρὸς βίαν ἐπεισάγοντα τὰ μὴ διʼ ἔθους ὄντα, καὶ λόγῳ μὲν βασιλέα, τῷ δʼ ἔργῳ πολέμιον φαινόμενον τοῦ παντὸς ἔθνους."},{"number":282,"text":"ἐκ δὲ τούτου συνομοσάμενοι πάντα κίνδυνον ὑποδύεσθαι δέκα τῶν πολιτῶν ἄνδρες, ξιφίδια τοῖς ἱματίοις ὑποβαλόντες,"},{"number":283,"text":"ἦν δʼ αὐτοῖς διʼ ἀναξιοπάθειαν ὧν ἤκουεν καὶ τῶν διεφθορότων τις τοὺς ὀφθαλμοὺς συνομωμοσμένος, οὐχ ὡς ἐνεργῆσαί τι καὶ δρᾶν εἰς τὴν ἐπιχείρησιν ἱκανός, ἀλλʼ ἐν ἑτοίμῳ κατατιθεὶς αὑτὸν παθεῖν εἴ τι κἀκείνοις συμβαίνοι δυσχερές, ὥστε μὴ μετρίαν τὴν ὁρμὴν τοῖς ἐπιχειροῦσι διʼ αὐτὸν γενέσθαι,"},{"number":284,"text":"ταῦτα γνόντες ἀπὸ συνθήματος εἰς τὸ θέατρον ἐχώρουν, ἐλπίσαντες μὲν οὐδʼ αὐτὸν Ἡρώδην διαφευξεῖσθαι προσπεσόντων ἐξ ἀφανοῦς, πολλοὺς δʼ, εἰ καὶ μὴ τυγχάνοιεν ἐκείνου, τῶν περὶ αὐτὸν ἀναιρήσειν οἰόμενοι· καὶ ταῦτʼ αὐτοῖς ἀρκέσειν, εἰ καὶ θνήσκοιεν, εἰς ἔννοιαν ὧν ὁ βασιλεὺς ἐξυβρίζειν ἐδόκει τὸ πλῆθος καὶ αὐτὸν ἐκεῖνον ἀγαγεῖν."},{"number":285,"text":"ἐκεῖνοι μὲν οὖν προκαταστάντες ἐπὶ τοιαύτης ἦσαν προθυμίας· εἷς δὲ τῶν ὑφʼ Ἡρώδου πολυπραγμονεῖν καὶ διαγγέλλειν τὰ τοιαῦτα τεταγμένων ἐξευρηκὼς ὅλην τὴν ἐπίθεσιν εἰς τὸ θέατρον εἰσιέναι μέλλοντι τῷ βασιλεῖ κατεμήνυσεν."},{"number":286,"text":"ὁ δʼ, οὐ γὰρ ἀνοίκειον ᾠήθη τὸν λόγον εἴς τε τὸ μῖσος ἀφορῶν, ὃ συνῄδει παρὰ τῶν πλειόνων αὐτῷ, καὶ τὰς ταραχὰς τὰς ἐπὶ τοῖς καθʼ ἕκαστα γινομένοις παρυφισταμένας, ἀναχωρήσας εἰς τὸ βασίλειον ὀνομαστὶ τοὺς ἐν ταῖς αἰτίαις ἐκάλει."},{"number":287,"text":"προσπιπτόντων δʼ αὐτοῖς τῶν ὑπηρετῶν αὐτόφωροι λαμβανόμενοι τὸ μὲν ὡς οὐκ ἂν διαφύγοιεν ᾔδεσαν, ἐπεκόσμησαν δὲ τὴν ἀναγκαίαν καταστροφὴν τοῦ τέλους τῷ μηδὲν ὑφιέναι τοῦ φρονήματος·"},{"number":288,"text":"οὐ γὰρ ἐντραπέντες οὐδʼ ἀρνησάμενοι τὴν πρᾶξιν ἀνέδειξαν μὲν ἤδη κρατούμενα τὰ ξίφη, διωμολογήσαντο δὲ καλῶς καὶ σὺν εὐσεβείᾳ τὴν συνωμοσίαν αὐτοῖς γενέσθαι, κέρδους μὲν οὐδενὸς οὐδʼ οἰκείων ἕνεκεν παθῶν, τὸ δὲ πλέον ὑπὲρ τῶν κοινῶν ἐθῶν, ἃ καὶ πᾶσιν ἢ φυλάττειν ἢ θνήσκειν πρὸ αὐτῶν ἄξιον."},{"number":289,"text":"τοιαῦτα μὲν ἐκεῖνοι τῇ προαιρέσει τῆς ἐπιβουλῆς ἐμπαρρησιασάμενοι περιστάντων αὐτοῖς τῶν βασιλικῶν ἤγοντο καὶ πᾶσαν αἰκίαν ὑπομείναντες διεφθάρησαν. μετʼ οὐ πολὺ δὲ καὶ τὸν ταῦτα μηνύσαντα κατὰ μῖσος ἁρπασάμενοί τινες οὐκ ἀπέκτειναν μόνον, ἀλλὰ καὶ μελιστὶ διελόντες προύθεσαν κυσίν."},{"number":290,"text":"ἑωρᾶτο δὲ πολλοῖς τῶν πολιτῶν τὰ γινόμενα καὶ κατεμήνυσεν οὐδείς, ἕως Ἡρώδου πικροτέραν καὶ φιλόνεικον ποιουμένου τὴν ἔρευναν ἐκβασανισθεῖσαι γυναῖκές τινες ὡμολόγησαν ἃ πραχθέντα εἶδον. καὶ τῶν μὲν ἐνεργησάντων ἐγένετο τιμωρία πανοικὶ τὴν προπέτειαν αὐτῶν ἐπεξιόντος,"},{"number":291,"text":"ἡ δʼ ἐπιμονὴ τοῦ πάθους καὶ τὸ τῆς ὑπὲρ τῶν νόμων πίστεως ἀκατάπληκτον οὐ ῥᾴδιον ἐποίει τὸν Ἡρώδην, εἰ μὴ μετὰ πάσης ἀσφαλείας κρατοίη, καὶ διέγνω πάντοθεν περιειληφέναι τὸ πλῆθος, ὡς μὴ νεωτεριζόντων φανερὰν γενέσθαι τὴν ἀπόστασιν."},{"number":292,"text":"Ἐξωχυρωμένης οὖν αὐτῷ τῆς πόλεως μὲν ὑπὸ τῆς αὐλῆς, ἐν ᾗ διῃτᾶτο, τοῦ δὲ ἱεροῦ τῇ περὶ τὸ φρούριον ὀχυρότητι τὸ καλούμενον Ἀντωνίαν κατασκευασθὲν διʼ αὐτοῦ, τρίτον παντὶ τῷ λαῷ τὴν Σαμάρειαν ἐνόησεν ἐπιτείχισμα, καλέσας μὲν αὐτὴν Σεβαστήν,"},{"number":293,"text":"οἰόμενος δὲ κατὰ τῆς χώρας οὐδὲν ἔλαττον ἰσχυροποιεῖν τὸν τόπον, ἀπέχοντα μὲν Ἱεροσολύμων μιᾶς ὁδὸν ἡμέρας, εὔχρηστον δʼ ὄντα καὶ κοινὸν ἐπί τε τοῖς ἐν τῇ πόλει καὶ τῇ χώρᾳ γενησόμενον. τῷ δὲ ἔθνει παντὶ φρούριον ἐνῳκοδόμησεν τὸ πάλαι μὲν καλούμενον Στράτωνος πύργον, Καισάρειαν δʼ ὑπʼ αὐτοῦ προσαγορευθέν."},{"number":294,"text":"ἔν τε τῷ μεγάλῳ πεδίῳ τῶν ἐπιλέκτων ἱππέων περὶ αὐτὸν ἀποκληρώσας χωρίον συνέκτισεν ἐπί τε τῇ Γαλιλαίᾳ Γάβα καλούμενον καὶ τῇ Περαίᾳ τὴν Ἐσεβωνῖτιν."},{"number":295,"text":"ταῦτα μὲν οὖν ἐν τοῖς κατὰ μέρος αἰεί τι πρὸς ἀσφάλειαν ἐπεξευρίσκων καὶ διαλαμβάνων φυλακαῖς τὸ πᾶν ἔθνος, ὡς ἥκιστα μὲν ἀπʼ ἐξουσίας εἰς ταραχὰς προπίπτειν, αἷς καὶ μικροῦ κινήματος ἐγγενομένου συνεχὲς ἐχρῶντο, λανθάνειν δὲ μηδʼ εἰ παρακινοῖεν ἐφεστηκότων αἰεί τινων πλησίον, οἳ καὶ γινώσκειν καὶ κωλύειν ἐδύναντο."},{"number":296,"text":"τότε δὲ τὴν Σαμάρειαν ὡρμημένος τειχίζειν πολλοὺς μὲν τῶν συμμαχησάντων αὐτῷ κατὰ τοὺς πολέμους, πολλοὺς δὲ τῶν ὁμόρων συμπολίζειν ἐπετήδευεν, ὑπό τε φιλοτιμίας τοῦ νέον ἐγείρειν καὶ διʼ αὐτοῦ πρότερον οὐκ ἐν ταῖς ἐπισήμοις οὖσαν, καὶ μᾶλλον ὅτι πρὸς ἀσφάλειαν αὐτῷ τὸ φιλότιμον ἐπετηδεύετο, τήν τε προσηγορίαν ὑπήλλαττε Σεβαστὴν καλῶν καὶ τῆς χώρας ἀρίστην οὖσαν τὴν πλησίον κατεμέριζεν τοῖς οἰκήτορσιν, ὡς εὐθὺς ἐν εὐδαιμονίᾳ συνιόντας οἰκεῖν,"},{"number":297,"text":"καὶ τείχει καρτερῷ τὴν πόλιν περιέβαλεν τό τε τοῦ χωρίου πρόσαντες εἰς ἐρυμνότητα κατασκευαζόμενος καὶ μέγεθος οὐχ ὡς τὸ πρῶτον ἀλλʼ ὥστε μηδὲν ἀποδεῖν τῶν ἐλλογιμωτάτων πόλεων περιλαμβάνων· στάδιοι γὰρ ἦσαν εἴκοσιν."},{"number":298,"text":"ἐντὸς δὲ καὶ κατὰ μέσην τριῶν ἡμισταδίων τέμενος ἀνῆκεν παντοίως κεκοσμημένον καὶ ναὸν ἐν αὐτῷ μεγέθει καὶ κάλλει τῶν ἐλλογιμωτάτων ἤγειρεν, ἔν τε τοῖς κατὰ μέρος διὰ πάντων ἐκόσμει τὴν πόλιν, τὸ μὲν ἀναγκαῖον τῆς ἀσφαλείας ὁρῶν καὶ τῇ τῶν περιβόλων ἐρυμνότητι φρούριον αὐτὴν ποιούμενος ἐπὶ τῇ μείζονι, τὸ δʼ εὐπρεπὲς ὡς ἂν ἐκ τοῦ φιλοκαλεῖν καὶ μνημεῖα φιλανθρωπίας ἀπολιπεῖν ἐν ὑστέρῳ."}],"9":[{"number":299,"text":"Κατὰ τοῦτον μὲν οὖν τὸν ἐνιαυτὸν τρισκαιδέκατον ὄντα τῆς Ἡρώδου βασιλείας πάθη μέγιστα τὴν χώραν ἐπέλαβεν, εἴτε δὴ τοῦ θεοῦ μηνίσαντος ἢ καὶ κατὰ περιόδους οὕτως ἀπαντήσαντος τοῦ κακοῦ·"},{"number":300,"text":"πρῶτον μὲν γὰρ αὐχμοὶ διηνεκεῖς ἐγένοντο, καὶ διὰ τὸ τοιοῦτον ἄκαρπος ἡ γῆ μηδʼ ὅσα κατʼ αὐτὴν ἀναβλαστάνειν, ἔπειτα καὶ τῆς διαίτης κατὰ τὴν ἔνδειαν τῶν σιτίων ἐξαλλαττομένης νόσοι τῶν σωμάτων καὶ πάθος ἤδη λοιμικὸν ἐκράτει, διηνεκῶς ἀντεφοδιαζομένων αὐτοῖς τῶν κακῶν."},{"number":301,"text":"τό τε γὰρ ἠπορῆσθαι θεραπείας καὶ τροφῆς ἐπέτεινεν εἰς πλέον ἀρξαμένην ἰσχυρῶς τὴν λοιμώδη νόσον ἥ τε φθορὰ τῶν οὕτως ἀπολλυμένων ἀφῃρεῖτο καὶ τοὺς περιόντας εὐθυμίας, ἐπεὶ προσαρκεῖν ταῖς ἀπορίαις ἐξ ἐπιμελείας οὐκ ἐδύναντο."},{"number":302,"text":"φθαρέντων γε μὴν τῶν ἐπʼ ἔτος καρπῶν καὶ τῶν ὅσοι πρότερον ἀπέκειντο δεδαπανημένων, οὐδὲν εἰς ἐλπίδα χρηστὴν ὑπελείπετο μᾶλλον ἢ κατὰ προσδοκίαν ἐπιτείνοντος τοῦ κακοῦ καὶ οὐδὲ κατʼ ἐκεῖνον τὸν ἐνιαυτὸν μόνον, ὥστʼ αὐτοῖς εἶναι μὲν οὐδὲν ὑπόλοιπον, ἀπολωλέναι δὲ καὶ τῶν περιόντων τὰ σπέρματα μηδὲ τὸ δεύτερον ἀνείσης τῆς γῆς."},{"number":303,"text":"ἥ τε ἀνάγκη πολλὰ διὰ τὰς χρείας ἐκαινούργει. καὶ τὰς ἀπορίας οὐκ ἐλάττους εἶναι συνέβαινεν αὐτῷ τῷ βασιλεῖ, τῶν τε φόρων, οὓς ἐλάμβανεν ἀπὸ τῆς γῆς, ἀφῃρημένῳ καὶ τὰ χρήματα δεδαπανηκότι πρὸς φιλοτιμίαν ὧν τὰς πόλεις ἐπεσκεύαζεν."},{"number":304,"text":"ἦν δὲ οὐδὲν ὅ τι καὶ βοηθείας ἄξιον ἐδόκει προκατειληφότος τοῦ κακοῦ καὶ μῖσος εἰς αὐτὸν ἐκ τῶν ἀρχομένων· τὸ γὰρ οὐκ εὖ πράττειν φιλαίτιον αἰεὶ κατὰ τῶν προεστηκότων."},{"number":305,"text":"Ἐν τοιούτοις διενοεῖτο βοηθεῖν τῷ καιρῷ· χαλεπὸν δʼ ἦν οὔτε τῶν πλησίον ἐχόντων ἀποδόσθαι σιτία τῷ μηδʼ αὐτοὺς ἐλάττω πεπονθέναι, χρημάτων τε οὐκ ὄντων, εἰ καὶ δυνατὸν ὀλίγων ἐπὶ πολλοῖς εὐπορηθῆναι."},{"number":306,"text":"καλῶς μέντοι νομίζων ἔχειν πάντως εἰς τὴν βοήθειαν μὴ ἀμελεῖν, τὸν ὄντα κόσμον ἐν τοῖς βασιλείοις αὐτοῦ συνέκοψεν ἀργύρου καὶ χρυσοῦ, μήτε τῆς ἐν ταῖς κατασκευαῖς ἐπιμελείας μήτʼ εἴ τι τέχνῃ τίμιον ἦν τούτου φεισάμενος."},{"number":307,"text":"ἔπεμπε δʼ ἐπʼ Αἰγύπτου τὰ χρήματα Πετρωνίου τὴν ἐπαρχίαν ἀπὸ Καίσαρος εἰληφότος. οὗτος οὐκ ὀλίγων ἐπʼ αὐτὸν καταπεφευγότων διὰ τὰς αὐτὰς χρείας, ἰδίᾳ τε φίλος ὢν Ἡρώδῃ καὶ διασώσασθαι θέλων τοὺς ὑπʼ αὐτῷ, πρώτοις μὲν ἔδωκεν ἐξάγειν τὸν σῖτον, εἰς ἅπαντα δὲ κατὰ τὴν ὠνὴν καὶ τὸν ἔκπλουν συνήργησεν, ὡς μέγα μέρος ἢ τὸ πᾶν γενέσθαι ταύτης τῆς βοηθείας."},{"number":308,"text":"ὁ γὰρ Ἡρώδης, τούτων ἀφικομένων ἐν ἀφορμῇ τὴν ἐπιμέλειαν τὴν αὐτοῦ προστιθεὶς οὐ μόνον ἀντιμετέστησεν τὰς γνώμας τῶν πρότερον χαλεπῶς ἐχόντων, ἀλλὰ καὶ μεγίστην ἐποιήσατο τὴν ἐπίδειξιν τῆς εὐνοίας καὶ τῆς προστασίας."},{"number":309,"text":"πρῶτον μὲν γὰρ ὅσοις οἷόν τε διʼ αὐτῶν τὰ περὶ τὰς τροφὰς ἐκπονεῖν ἔνειμε τοῦ σίτου τὴν ἔκταξιν ἀκριβεστάτην ποιούμενος, ἔπειτα πολλῶν ὄντων, οἳ κατὰ γῆρας ἤ τινα προσοῦσαν ἄλλην ἀσθένειαν οὐχ ἱκανῶς εἶχον αὐτοῖς παρασκευάζειν τὰ σιτία, προυνόει καταστήσας ἀρτοποιοὺς καὶ παρέχων ἑτοίμας τὰς τροφάς."},{"number":310,"text":"ἐπιμέλειαν δὲ καὶ τοῦ μὴ διαχειμάσαι μετὰ κινδύνων αὐτοὺς ἐποιήσατο συγκατειληφυίας καὶ τῆς περὶ τὰς ἐσθῆτας ἀπορίας, ἐφθαρμένων καὶ παντάπασιν ἐξαναλωθέντων τῶν βοσκημάτων, ὡς οὔτε ἐρίων εἶναι χρῆσιν οὔτε τῶν ἄλλων σκεπασμάτων."},{"number":311,"text":"ἐκπορισθέντων δὲ αὐτῷ καὶ τούτων ταῖς πλησίον ἤδη πόλεσιν ἐπεβάλλετο τὰς ὠφελείας παρέχειν σπέρματα τοῖς ἐν Συρίᾳ διαδούς. καὶ τοῦτʼ ὤνησεν οὐχ ἧττον αὐτὸν εὐστοχηθείσης εἰς εὐφορίαν τῆς χάριτος, ὡς ἅπασιν ἱκανὰ τὰ περὶ τὰς τροφὰς γενέσθαι."},{"number":312,"text":"τὸ δὲ σύμπαν ἀμήτου περὶ τὴν γῆν ὑποφανέντος οὐκ ἔλαττον ἢ πέντε μυριάδας ἀνθρώπων, οὓς αὐτὸς ἔθρεψεν καὶ περιεποίησεν, εἰς τὴν χώραν διέπεμψεν, καὶ τοῦτον τὸν τρόπον κακωθεῖσαν αὐτῷ τὴν βασιλείαν ὑπὸ πάσης φιλοτιμίας καὶ σπουδῆς ἀναλαβὼν οὐχ ἥκιστα καὶ τοὺς πέριξ ἐν ταῖς αὐταῖς κακοπαθείαις ὄντας ἐπεκούφισεν."},{"number":313,"text":"οὐ γὰρ ἔσθʼ ὅστις ὑπὸ χρείας ἐντυχὼν ἀπελείφθη μὴ βοήθειαν εὕρασθαι κατὰ τὴν ἀξίαν. ἀλλὰ καὶ δῆμοι καὶ πόλεις καὶ τῶν ἰδιωτῶν ὅσοις ἀπορία διὰ τὸ πλειόνων προΐστασθαι συνετύγχανεν, ἐπʼ αὐτὸν καταφεύγοντες ἔσχον ὧν ἐδεήθησαν,"},{"number":314,"text":"ὥστε γενέσθαι λογιζομένων τοὺς μὲν ἔξω τῆς ἀρχῆς δοθέντας σίτου κόρους μυρίους, ὁ δὲ κόρος δύναται μεδίμνους Ἀττικοὺς δέκα, τοὺς δʼ εἰς αὐτὴν τὴν βασιλείαν περὶ ὀκτάκις μυρίους."},{"number":315,"text":"ταύτην δʼ αὐτοῦ τὴν ἐπιμέλειαν καὶ τὴν τῆς χάριτος εὐκαιρίαν οὕτως ἐν αὐτοῖς τε τοῖς Ἰουδαίοις ἰσχῦσαι συνέβη καὶ διαβοηθῆναι παρὰ τοῖς ἄλλοις, ὥστε τὰ μὲν πάλαι μίση κινηθέντα διὰ τὸ παραχαράττειν ἔνια τῶν ἐθῶν καὶ τῆς βασιλείας ἐξαιρεθῆναι καὶ τοῦ παντὸς ἔθνους, ἀντικατάλλαγμα δὲ φαίνεσθαι τὴν ἐν τῇ βοηθείᾳ τῶν δεινοτάτων φιλοτιμίαν."},{"number":316,"text":"εὔκλεια δὲ καὶ παρὰ τῶν ἔξωθεν ἦν, καὶ δοκεῖ τὰ δυσχερῆ συμβῆναι μὲν αὐτῷ μείζω λόγου, κακώσαντα δὲ τὴν βασιλείαν οὐχ ἥκιστα πρὸς εὐδοξίαν ὠφελῆσαι· τὸ γὰρ ἐν ταῖς ἀπορίαις μεγαλόψυχον παρὰ δόξαν ἐπιδειξάμενος ἀντιμετέστησε τοὺς πολλούς, ὡς ἐξ ὑπαρχῆς δοκεῖν οὐχ οἷον ἡ πεῖρα τῶν πάλαι γεγενημένων, ἀλλʼ οἷον ἡ μετὰ τῆς χρείας ἐπιμέλεια παρεστήσατο."},{"number":317,"text":"Περὶ δὲ τὸν χρόνον ἐκεῖνον καὶ συμμαχικὸν ἔπεμψεν Καίσαρι πεντακοσίους ἐπιλέκτους τῶν σωματοφυλάκων, οὓς Γάλλος Αἴλιος ἐπὶ τὴν Ἐρυθρὰν θάλασσαν ἦγεν εἰς πολλὰ χρησίμους αὐτῷ γενομένους."},{"number":318,"text":"πάλιν οὖν αὐτῷ τῶν πραγμάτων πρὸς ἐπίδοσιν εὐθηνουμένων βασίλειον ἐξῳκοδόμει περὶ τὴν ἄνω πόλιν ὑπερμεγέθεις οἴκους ἐγείρων καὶ κόσμῳ κατασκευάζων πολυτελεστάτῳ χρυσοῦ καὶ λίθων καὶ περιαλειμμάτων ὡς ἕκαστον αὐτῶν κλισίας μὲν ἔχειν παμπόλλους ἄνδρας ὑποδέχεσθαι κατὰ μέτρα δὲ καὶ τὰς προσηγορίας· ὁ μὲν γὰρ Καίσαρος, ὁ δὲ Ἀγρίππα κέκλητο."},{"number":319,"text":"προσέλαβεν δὲ καὶ γάμον αὐτῷ κινηθεὶς ἐξ ἐρωτικῆς ἐπιθυμίας μηδένα τοῦ κατὰ τὴν οἰκείαν ἡδονὴν ζῆν ὑπολογισμὸν ποιούμενος. ἀρχὴ δʼ αὐτῷ τῶν γάμων ἐγένετο τοιάδε·"},{"number":320,"text":"Σίμων ἦν Ἱεροσολυμίτης υἱὸς Βοηθοῦ τινος Ἀλεξανδρέως, ἱερεὺς ἐν τοῖς γνωρίμοις, εἶχεν δὲ θυγατέρα καλλίστην τῶν τότε νομιζομένην."},{"number":321,"text":"ὄντος οὖν λόγου παρὰ τοῖς Ἱεροσολυμίταις αὐτῆς τὸ μὲν πρῶτον ὑπὸ τῆς ἀκοῆς τὸν Ἡρώδη κεκινῆσθαι συνέβαινεν, ὡς δὲ καὶ θεασάμενον ἡ τῆς παιδὸς ἐξέπληξεν ὥρα, τὸ μὲν ἀπʼ ἐξουσίας χρώμενον διατελεῖν ἅπαν ἀπεδοκίμαζεν ὑποπτεύων ὅπερ ἦν, εἰς βίαν καὶ τυραννίδα διαβληθήσεσθαι, βέλτιον δʼ ᾤετο γάμῳ τὴν κόρην λαβεῖν."},{"number":322,"text":"καὶ τοῦ Σίμωνος ὄντος ἀδοξοτέρου μὲν ἢ πρὸς οἰκειότητα, μείζονος δὲ ἢ καταφρονεῖσθαι, τὸν ἐπιεικέστερον τρόπον μετῄει τὴν ἐπιθυμίαν αὔξων αὐτοὺς καὶ τιμιωτέρους ἀποφαίνων· αὐτίκα γοῦν Ἰησοῦν μὲν τὸν τοῦ Φοαβιτος ἀφαιρεῖται τὴν ἀρχιερωσύνην, Σίμωνα δὲ καθίστησιν ἐπὶ τῆς τιμῆς καὶ τὸ κῆδος πρὸς αὐτὸν συνάπτεται."},{"number":323,"text":"Τελεσθέντος δʼ αὐτῷ τοῦ γάμου προσκατεσκευάσατο φρούριον ἐπὶ τῶν τόπων, ἐν οἷς ἐνίκα Ἰουδαίους, ὅτε τῆς ἀρχῆς ἐκπεσόντος Ἀντίγονος ἐπὶ τῶν πραγμάτων ἦν."},{"number":324,"text":"τοῦτο δὲ τὸ φρούριον ἀπέχει μὲν Ἱεροσολύμων περὶ ἑξήκοντα σταδίους, φύσει δὲ ἐχυρὸν καὶ πρὸς κατασκευὴν ἐπιτηδειότατόν ἐστιν ἐγγὺς ἐπιεικῶς κολωνὸς εἰς ὕψος ἀνιὼν χειροποίητον, ὡς εἶναι μαστοειδὴς τὴν περιφοράν, διείληπται δὲ κυκλοτερέσι πύργοις ὀρθίαν ἔχων ἄνοδον ξεσταῖς βαθμίσιν ἐξῳκοδομημένην εἰς διακοσίους. ἐντὸς δʼ αὐτοῦ καταγωγαὶ βασίλειοι πολυτελεῖς εἰς ἀσφάλειαν ὁμοῦ καὶ κόσμον πεποιημέναι·"},{"number":325,"text":"περὶ δὲ τὴν βάσιν τοῦ λόφου διατριβαὶ κατασκευῆς ἀξιοθεάτου τά τε ἄλλα καὶ τῆς εἰσαγωγῆς τῶν ὑδάτων, οὐ γὰρ οὗτος ὁ τόπος ἔσχηκεν, ἐκ μακροῦ καὶ διὰ πλειόνων ἀναλωμάτων πεποιημένης. τὰ δʼ ἐπίπεδα περιῳκοδόμηται πόλις οὐδεμιᾶς ἐλάσσων τὸν λόφον ἀκρόπολιν ἔχουσα τῆς ἄλλης οἰκήσεως."},{"number":326,"text":"Πάντων δʼ αὐτῷ προκεχωρηκότων εἰς δέον ὧν ἠλπίκει τὰς μὲν ἐν αὐτῇ τῇ βασιλείᾳ ταραχὰς οὐδʼ ὁπωσοῦν διʼ ὑποψίας εἶχεν ἑκατέρωθεν ὑπηκόους παραστησάμενος, φόβῳ μὲν ὧν ἀπαραίτητος εἰς τὰς τιμωρίας, τὴν ἐπιμέλειαν δὲ ὧν μεγαλόψυχος ἐν ταῖς περιπετείαις εὑρίσκετο."},{"number":327,"text":"περιεβάλλετο δὲ τὴν ἔξωθεν ἀσφάλειαν ὥσπερ ἐπιτείχισμα καὶ τοῦτο τοῖς ἀρχομένοις ποιούμενος· πόλεσίν τε γὰρ ὡμίλει δεξιῶς καὶ φιλανθρώπως καὶ τοὺς δυνάστας ἐθεράπευεν εὐκαιρίαις ὧν ἑκάστους ἐδωρεῖτο μείζους τὰς χάριτας ἐμποιῶν καὶ τὸ μεγαλόψυχον φύσει πρὸς τὴν βασιλείαν εὐπρεπὲς ἔχων, ὥστʼ αὐτῷ πάντα διὰ πάντων αὔξεσθαι πρὸς τὸ πλεῖον ἀεὶ προχωρούντων."},{"number":328,"text":"ὑπὸ δὲ τῆς εἰς τοῦτο φιλοτιμίας καὶ τῆς θεραπείας, ἣν ἐθεράπευεν Καίσαρα καὶ Ῥωμαίων τοὺς πλεῖστον δυναμένους, ἐκβαίνειν τῶν ἐθῶν ἠναγκάζετο καὶ πολλὰ τῶν νομίμων παραχαράττειν, πόλεις τε κτίζων ὑπὸ φιλοτιμίας καὶ ναοὺς ἐγείρων, οὐκ ἐν τῇ τῶν Ἰουδαίων,"},{"number":329,"text":"οὐδὲ γὰρ ἂν ἠνέσχοντο τῶν τοιούτων ἀπηγορευμένων ἡμῖν ὡς ἀγάλματα καὶ τύπους μεμορφωμένους τιμᾶν πρὸς τὸν Ἑλληνικὸν τρόπον, τὴν δʼ ἔξω χώραν καὶ τὰ πέριξ οὕτως κατεσκευάζετο,"},{"number":330,"text":"Ἰουδαίοις μὲν ἀπολογούμενος μὴ καθʼ αὑτὸν, ἀλλʼ ἐξ ἐντολῆς καὶ προσταγμάτων αὐτὰ ποιεῖν, Καίσαρι δὲ καὶ Ῥωμαίοις τὸ μηδὲ τῶν οἰκείων ἐθῶν ὅσον τῆς ἐκείνων τιμῆς ἐστοχάσθαι χαριζόμενος, αὐτὸς μέντοι τὸ σύμπαν αὐτοῦ στοχαζόμενος ἢ καὶ φιλοτιμούμενος μείζω τὰ μνημεῖα τῆς ἀρχῆς τοῖς αὖθις ὑπολιπέσθαι. ὅθεν καὶ περὶ τὰς ἐπισκευὰς τῶν πόλεων ἐκεκίνητο καὶ πλείστας εἰς τοῦτο τὰς δαπάνας ἐποιεῖτο."},{"number":331,"text":"Κατιδὼν δὲ καὶ πρὸς τῇ θαλάττῃ χωρίον ἐπιτηδειότατον δέξασθαι πόλιν, ὃ πάλαι Στράτωνος ἐκαλεῖτο πύργος, τῇ τε διαγραφῇ μεγαλοπρεπῶς ἐπεβάλλετο καὶ τοῖς οἰκοδομήμασιν ἀνιστὰς ἅπασαν οὐ παρέργως, ἀλλʼ ἐκ λευκῆς πέτρας, καὶ διακοσμῶν καὶ βασιλείοις πολυτελεστάτοις καὶ διαίταις πολιτικαῖς,"},{"number":332,"text":"τὸ δὲ μέγιστον καὶ πλείστην ἐργασίαν παρασχόν, ἀκλύστῳ λιμένι, μέγεθος μὲν κατὰ τὸν Πειραιᾶ, καταγωγὰς δʼ ἔνδον ἔχοντι καὶ δευτέρους ὑφόρμους, τῇ δὲ δομήσει περίβλεπτον, ὅτι μηδʼ ἐκ τοῦ τόπου τὴν ἐπιτηδειότητα τῆς μεγαλουργίας εἶχεν, ἀλλʼ ἐπεισάκτοις καὶ πολλαῖς ἐξετελειώθη ταῖς δαπάναις."},{"number":333,"text":"κεῖται μὲν γὰρ ἡ πόλις ἐν τῇ Φοινίκῃ κατὰ τὸν εἰς Αἴγυπτον παράπλουν Ἰόππης μεταξὺ καὶ Δώρων, πολισμάτια ταῦτʼ ἐστὶν παράλια δύσορμα διὰ τὰς κατὰ λίβα προσβολάς, αἳ ἀεὶ τὰς ἐκ τοῦ πόντου θῖνας ἐπὶ τὴν ᾐόνα σύρουσαι καταγωγὴν οὐ διδόασιν, ἀλλʼ ἔστιν ἀναγκαῖον ἀποσαλεύειν τὰ πολλὰ τοὺς ἐμπόρους ἐπʼ ἀγκύρας."},{"number":334,"text":"τοῦτο τὸ δυσδιάθετον τῆς χώρας διορθούμενος καὶ περιγράψας τὸν κύκλον τοῦ λιμένος ἐφʼ ὅσον ἦν αὔταρκες πρὸς τῇ χέρσῳ μεγάλοις στόλοις ἐνορμεῖσθαι λίθους ὑπερμεγέθεις καθίει εἰς τὸ βάθος εἰς ὀργυιὰς εἴκοσι. πεντήκοντα ποδῶν ἦσαν οἱ πλείους τὸ μῆκος καὶ πλάτος οὐκ ἔλαττον δεκαοκτώ, βάθος δὲ ἐννέα, τούτων δὲ οἱ μὲν μείζους οἱ δὲ ἐλάττους."},{"number":335,"text":"ἡ δὲ ἐνδόμησις ὅσον ἦν † ἐβάλλετο κατὰ τῆς θαλάσσης διακοσίους πόδας. τούτων τὸ μὲν ἥμισυ προβέβλητο κυματωγαῖς, ὡς ἀπομάχεσθαι περικλώμενον ἐκεῖ τὸν κλύδωνα· προκυμία γοῦν ἐκαλεῖτο· τὸ δὲ λοιπὸν περιεῖχεν λίθινον τεῖχος πύργοις διειλημμένον,"},{"number":336,"text":"ὧν ὁ μέγιστος Δρούσιον ὀνομάζεται, πάνυ καλόν τι χρῆμα, τὴν προσηγορίαν εἰληφὼς ἀπὸ Δρούσου τοῦ Καίσαρος προγόνου τελευτήσαντος νέου."},{"number":337,"text":"ψαλίδες δὲ ἐμπεποίηνται συνεχεῖς καταγωγαὶ τοῖς ναυτίλοις, τὸ δὲ πρὸ αὐτῶν ἀπόβασις πλατεῖα κύκλῳ περιεστεφάνωκεν τὸν πάντα λιμένα, περίπατος τοῖς ἐθέλουσιν ἥδιστος. ὁ δʼ εἴσπλους καὶ τὸ στόμα πεποίηται πρὸς βορέαν ἀνέμων αἰθριώτατον."},{"number":338,"text":"βάσις δὲ τοῦ περιβόλου παντὸς ἐν ἀριστερᾷ μὲν εἰσπλεόντων πύργος νενασμένος ἐπὶ πολὺ στερρῶς ἀντέχειν, κατὰ δεξιὰν δὲ δύο λίθοι μεγάλοι καὶ τοῦ κατὰ θάτερα πύργου μείζους, ὀρθοὶ καὶ συνεζευγμένοι."},{"number":339,"text":"περίκεινται δὲ ἐν κύκλῳ τὸν λιμένα λειοτάτου λίθου κατασκευὴ συνεχεῖς οἰκήσεις κἀν τῷ μέσῳ κολωνός τις, ἐφʼ οὗ νεὼς Καίσαρος ἄποπτος τοῖς εἰσπλέουσιν ἄγαλμά τε τὸ μὲν Ῥώμης, τὸ δὲ Καίσαρος· ἥ τε πόλις αὐτὴ Καισάρεια καλεῖται καλλίστης καὶ τῆς ὕλης καὶ τῆς κατασκευῆς τετυχηκυῖα."},{"number":340,"text":"τὰ δʼ ὑπʼ αὐτὴν ὑπόνομοί τε καὶ λαῦραι πραγματείαν οὐκ ἐλάττω τῶν ὑπερῳκοδομημένων ἔχουσαι. τούτων αἱ μὲν κατὰ σύμμετρα διαστήματα φέρουσιν εἰς τὸν λιμένα καὶ τὴν θάλατταν, μία δʼ ἐγκαρσία πάσας ὑπέζωκεν, ὡς τούς τε ὄμβρους εὐμαρῶς καὶ τὰ λύματα τῶν οἰκητόρων συνεκδίδοσθαι τήν τε θάλατταν, ὅταν ἔξωθεν ἐπείγηται, διαρρεῖν καὶ τὴν σύμπασαν ὑποκλύζειν πόλιν."},{"number":341,"text":"κατεσκεύαζεν δʼ ἐν αὐτῇ καὶ θέατρον καὶ πρὸς τῷ νοτίῳ τοῦ λιμένος ὄπισθεν ἀμφιθέατρον πολὺν ὄχλον ἀνθρώπων δέχεσθαι δυνάμενον καὶ κείμενον ἐπιτηδείως ἀποπτεύειν εἰς τὴν θάλασσαν. ἡ μὲν δὴ πόλις οὕτως ἐξετελέσθη δωδεκαετεῖ χρόνῳ καὶ ταῖς ἐργασίαις οὐκ ἐγκαμόντος καὶ ταῖς δαπάναις ἐπαρκέσαντος τοῦ βασιλέως."}],"10":[{"number":342,"text":"Ἐπὶ τοιούτοις δὲ ὢν καὶ τῆς Σεβαστῆς ἤδη πεπολισμένης ἔγνω τοὺς παῖδας αὐτοῦ πέμπειν εἰς Ῥώμην Ἀλέξανδρον καὶ Ἀριστόβουλον, συντευξομένους Καίσαρι."},{"number":343,"text":"τούτοις ἀνελθοῦσιν καταγωγὴ μὲν ἦν Πολλίωνος οἶκος ἀνδρὸς τῶν μάλιστα σπουδασάντων περὶ τὴν Ἡρώδου φιλίαν, ἐφεῖτο δὲ κἀν τοῖς Καίσαρος κατάγεσθαι· καὶ γὰρ ἐξεδέξατο μετὰ πάσης φιλανθρωπίας τοὺς παῖδας· καὶ δίδωσιν Ἡρώδῃ τὴν βασιλείαν ὅτῳ βούλεται βεβαιοῦν τῶν ἐξ αὐτοῦ γεγονότων, καὶ χώραν ἔτι τόν τε Τράχωνα καὶ Βαταναίαν καὶ Αὐρανῖτιν· ἔδωκεν δὲ διὰ τοιαύτην αἰτίαν παραλαβών."},{"number":344,"text":"Ζηνόδωρός τις ἐμεμίσθωτο τὸν οἶκον τὸν Λυσανίου. τούτῳ τὰ μὲν κατὰ τὰς προσόδους οὐκ ἤρκει, τὰ λῃστήρια δὲ ἔχων ἐν τῷ Τράχωνι πλείω τὴν πρόσοδον ἔφερεν· οἰκοῦσι γὰρ ἄνδρες ἐξ ἀπονοίας ζῶντες τοὺς τόπους, οἳ τὰ Δαμασκηνῶν ἐλῄζοντο, καὶ Ζηνόδωρος οὔτʼ εἶργεν αὐτός τε τῶν ὠφελειῶν ἐκοινώνει."},{"number":345,"text":"κακῶς δὲ πάσχοντες οἱ πλησιόχωροι Οὐάρρωνος κατεβόων τοῦ τότε ἡγεμονεύοντος καὶ γράφειν ἠξίουν Καίσαρι τοῦ Ζηνοδώρου τὴν ἀδικίαν. Καῖσαρ δὲ ἀνενεχθέντων τούτων ἀντέγραφεν ἐξελεῖν τὰ λῃστήρια τήν τε χώραν Ἡρώδῃ προσένειμεν, ὡς διὰ τῆς ἐπιμελείας τῆς ἐκείνου μηκέτʼ ἂν ὀχληρῶν τῶν περὶ τὸν Τράχωνα γενησομένων τοῖς πλησίον·"},{"number":346,"text":"οὐδὲ γὰρ ῥᾴδιον ἦν ἐπισχεῖν αὐτοὺς ἐν ἔθει τὸ λῃστεύειν πεποιημένους καὶ βίον οὐκ ἄλλοθεν ἔχοντας· οὔτε γὰρ πόλεις αὐτοῖς οὔτε κτήσεις ἀγρῶν, ὑποφυγαὶ δὲ κατὰ τῆς γῆς καὶ σπήλαια καὶ κοινὴ μετὰ τῶν βοσκημάτων δίαιτα. μεμηχάνηνται δὲ καὶ συναγωγὰς ὑδάτων καὶ προπαρασκευὰς σιτίων αἳ δύνανται πλεῖστον ἐξ ἀφανοῦς ἀντέχειν."},{"number":347,"text":"αἵ γε μὴν εἴσοδοι στεναὶ καὶ καθʼ ἕνα παρερχομένων, τὰ δʼ ἔνδον ἀπίστως μεγάλα πρὸς εὐρυχωρίαν ἐξειργασμένων· τὸ δʼ ὑπὲρ τὰς οἰκήσεις ἔδαφος οὐχ ὑψηλόν, ἀλλʼ οἷον ἐξ ἐπιπέδου. πέτρα δὲ τὸ σύμπαν σκληρὰ καὶ δύσοδος, εἰ μὴ τρίβῳ χρῷτό τις ἐξ ὁδηγίας·"},{"number":348,"text":"οὐδὲ γὰρ αὗται κατʼ ὀρθὸν ἀλλὰ πολλὰς ἕλικας ἐξελίττονται. τούτοις ἐπειδὴ τῶν εἰς τοὺς πλησίον κακουργημάτων ἐκωλύοντο, καὶ κατʼ ἀλλήλων ἦν ὁ τῆς λῃστείας τρόπος, ὡς μηδὲν ἀνομίας ἐν τούτῳ λελεῖφθαι. λαβὼν δὲ τὴν χάριν Ἡρώδης παρὰ Καίσαρος καὶ παρελθὼν εἰς τὴν χώραν ὁδηγῶν ἐμπειρίᾳ τούς τε πονηρευομένους αὐτῶν κατέπαυσεν καὶ τοῖς πέριξ ἀδεῆ τὴν εἰρήνην παρέσχεν."},{"number":349,"text":"Ὁ δὲ Ζηνόδωρος ἀχθόμενος πρῶτον μὲν ἐπὶ τῇ τῆς ἐπαρχίας ἀφαιρέσει, μᾶλλον δὲ καὶ φθόνῳ τὴν ἀρχὴν Ἡρώδου μετειληφότος, ἀνῆλθεν εἰς Ῥώμην κατηγορήσων αὐτοῦ. κἀκεῖνος μὲν ἄπρακτος ἀναστρέφει."},{"number":350,"text":"πέμπεται δʼ Ἀγρίππας τῶν πέραν Ἰονίου διάδοχος Καίσαρι· καὶ τούτῳ περὶ Μιτυλήνην χειμάζοντι συντυχὼν Ἡρώδης, ἦν γὰρ εἰς τὰ μάλιστα φίλος καὶ συνήθης, πάλιν εἰς τὴν Ἰουδαίαν ἀνέστρεφεν."},{"number":351,"text":"Γαδαρέων δέ τινες ἐπʼ Ἀγρίππαν ἦλθον κατηγοροῦντες αὐτοῦ, καὶ τούτους ἐκεῖνος οὐδὲ λόγον αὐτοῖς δοὺς ἀναπέμπει τῷ βασιλεῖ δεσμίους. οἵ τε Ἄραβες καὶ πάλαι δυσμενῶς ἔχοντες πρὸς τὴν ἀρχὴν τὴν Ἡρώδου διεκεκίνηντο καὶ στασιάζειν ἐπεχείρουν αὐτῷ τὰ πράγματα τότε καὶ μετʼ αἰτίας, ὡς ἐδόκουν, εὐλογωτέρας·"},{"number":352,"text":"ὁ γὰρ Ζηνόδωρος ἀπογινώσκων ἤδη τῶν καθʼ αὑτὸν ἔφθη τῆς ἐπαρχίας μέρος τι τὴν Αὐρανῖτιν αὐτοῖς ἀποδόσθαι ταλάντων πεντήκοντα. ταύτης ἐμπεριεχομένης τῇ δωρεᾷ Καίσαρος ὡς μὴ δικαίως ἀφαιρούμενοι διημφισβήτουν, πολλάκις μὲν ταῖς καταδρομαῖς καὶ τῷ βιάζεσθαι θέλειν, ἄλλοτε δὲ καὶ πρὸς δικαιολογίαν ἰόντες."},{"number":353,"text":"ἀνέπειθον δὲ καὶ τοὺς ἀπόρους τῶν στρατιωτῶν καὶ δυσμενεῖς, ἦσαν δʼ ἐπελπίζοντες ἀεὶ καὶ πρὸς τὸν νεωτερισμὸν ἐνδιδόντες, ᾧ μάλιστα χαίρουσιν οἱ κακῶς πράττοντες τῷ βίῳ. ταῦτα δὲ ἐκ μακροῦ πραττόμενα γινώσκων Ἡρώδης ὅμως οὐκ εἰς τὸ δυσμενές, ἀλλʼ ἐξ ἐπιλογισμοῦ παρηγόρει ταῖς ταραχαῖς οὐκ ἀξιῶν ἀφορμὰς ἐνδιδόναι."},{"number":354,"text":"Ἤδη δʼ αὐτοῦ τῆς βασιλείας ἑπτακαιδεκάτου προελθόντος ἔτους Καῖσαρ εἰς Συρίαν ἀφίκετο. καὶ τότε τῶν Γάδαρα κατοικούντων οἱ πλεῖστοι κατεβόων Ἡρώδου βαρὺν αὐτὸν ἐν τοῖς ἐπιτάγμασιν καὶ τυραννικὸν εἶναι."},{"number":355,"text":"ταῦτα δὲ ἀπετόλμων μάλιστα μὲν ἐγκειμένου καὶ διαβάλλοντος αὐτὸν Ζηνοδώρου καὶ παρασχόντος ὅρκους, ὡς οὐκ ἐγκαταλείψει μὴ πάντα τρόπον ἀφελέσθαι μὲν τῆς Ἡρώδου βασιλείας, προσθήσειν δὲ τῇ διοικήσει τῇ Καίσαρος."},{"number":356,"text":"τούτοις ἀναπεισθέντες οἱ Γαδαρεῖς οὐ μικρὰν καταβοὴν ἐποιήσαντο θράσει τοῦ μηδὲ τοὺς ὑπὸ Ἀγρίππα παραδοθέντας ἐν τιμωρίᾳ γενέσθαι διιέντος Ἡρώδου καὶ μηδὲν κακὸν εἰργασμένου· καὶ γὰρ εἴ τις καὶ ἄλλος ἐδόκει δυσπαραίτητος μὲν ἐπὶ τοῖς οἰκείοις, μεγαλόψυχος δὲ ἐπὶ τοῖς ἀλλοτρίοις ἁμαρτόντας ἀφιέναι."},{"number":357,"text":"κατηγορούντων οὖν ὕβρεις καὶ ἁρπαγὰς καὶ κατασκαφὰς ἱερῶν ὁ μὲν Ἡρώδης ἀταρακτήσας ἕτοιμος ἦν εἰς τὴν ἀπολογίαν, ἐδεξιοῦτο δὲ Καῖσαρ αὐτὸν οὐδὲν ὑπὸ τῆς ταραχῆς τοῦ πλήθους μεταβαλὼν τῆς εὐνοίας."},{"number":358,"text":"καὶ κατὰ μὲν τὴν πρώτην ἡμέραν οἱ περὶ τούτων ἐρρέθησαν λόγοι, ταῖς δʼ ἑξῆς οὐ προῆλθεν ἡ διάγνωσις· οἱ γὰρ Γαδαρεῖς ὁρῶντες τὴν ῥοπὴν αὐτοῦ τε Καίσαρος καὶ τοῦ συνεδρίου καὶ προσδοκήσαντες ὅπερ ἦν εἰκὸς ἐκδοθήσεσθαι τῷ βασιλεῖ, κατὰ φόβον αἰκίας οἱ μὲν ἀπέσφαττον αὑτοὺς ἐν τῇ νυκτί, τινὲς δὲ καθʼ ὕψους ἠφίεσαν, ἄλλοι δʼ εἰς τὸν ποταμὸν ἐμπίπτοντες ἑκοντὶ διεφθείροντο."},{"number":359,"text":"ταῦτα δὲ ἐδόκει κατάγνωσις τῆς προπετείας καὶ ἁμαρτίας, ἔνθεν οὐδὲ μελλήσας ὁ Καῖσαρ ἀπέλυεν τῶν αἰτιῶν Ἡρώδην. ἐπισυμπίπτει δὲ οὐ μέτριον εὐτύχημα τοῖς ἤδη γεγονόσιν· ὁ γὰρ Ζηνόδωρος ῥαγέντος αὐτῷ τοῦ σπλάγχνου καὶ πολλοῦ κατὰ τὴν ἀσθένειαν ὑποχωροῦντος αἵματος ἐν Ἀντιοχείᾳ τῆς Συρίας ἐκλείπει τὸν βίον."},{"number":360,"text":"Καῖσαρ δὲ καὶ τὴν τούτου μοῖραν οὐκ ὀλίγην οὖσαν Ἡρώδῃ δίδωσιν, ἣ μεταξὺ τοῦ Τράχωνος ἦν καὶ τῆς Γαλιλαίας, Οὐλάθαν καὶ Πανιάδα καὶ τὴν πέριξ χώραν. ἐγκαταμίγνυσιν δʼ αὐτὴν τοῖς ἐπιτροπεύουσιν τῆς Συρίας ἐντειλάμενος μετὰ τῆς ἐκείνου γνώμης τὰ πάντα ποιεῖν."},{"number":361,"text":"τό τε σύνολον εἰς τοῦτο προῆλθεν εὐτυχίας, ὥστε δύο τούτων τὴν ἀρχὴν Ῥωμαίων διεπόντων τοσήνδε τὸ μέγεθος οὖσαν, Καίσαρος καὶ μετʼ αὐτὸν Ἀγρίππου, κατὰ τὴν πρὸς αὐτὸν εὔνοιαν Καῖσαρ μὲν οὐδένα μετὰ Ἀγρίππαν Ἡρώδου προετίμησεν, Ἀγρίππας δὲ μετὰ Καίσαρα πρῶτον ἀπεδίδου φιλίας τόπον Ἡρώδῃ."},{"number":362,"text":"τοσαύτης δὲ ἐχόμενος παρρησίας τῷ μὲν ἀδελφῷ Φερώρᾳ παρὰ Καίσαρος ᾐτήσατο τετραρχίαν αὐτὸς ἀπονείμας ἐκ τῆς βασιλείας πρόσοδον ἑκατὸν ταλάντων, ὡς εἰ καί τι πάσχοι, τὰ κατʼ ἐκεῖνον ἀσφαλῶς ἔχειν καὶ μὴ τοὺς υἱεῖς αὐτῆς κρατεῖν."},{"number":363,"text":"Καίσαρα δʼ ἐπὶ θάλατταν προπέμψας ὡς ἐπανῆκεν, ἐν τῇ Ζηνοδώρου περικαλλέστατον αὐτῷ ναὸν ἐγείρει πέτρας λευκῆς πλησίον τοῦ Πανίου καλουμένου."},{"number":364,"text":"σπήλαιον ἐν ὄρει περικαλλές ἐστιν, ὑπʼ αὐτὸ δὲ γῆς ὀλίσθημα καὶ βάθος ἀπερρωγὸς ἄβατον ὕδατος ἀκινήτου πλέον, καθύπερθε δʼ ὄρος παμμέγεθες, ὑπὸ δὲ τὸ σπήλαιον ἀνατέλλουσιν αἱ πηγαὶ τοῦ Ἰορδάνου ποταμοῦ. τοῦτον ἐπισημότατον ὄντα τὸν τόπον καὶ τῷ ναῷ προσεκόσμησεν, ὃν ἀφιέρου Καίσαρι."},{"number":365,"text":"Τότε καὶ τὸ τρίτον μέρος ἀφῆκε τῶν φόρων τοῖς ἐν τῇ βασιλείᾳ, πρόφασιν μὲν ὡς ἀναλάβοιεν ἐκ τῆς ἀφορίας, τὸ δὲ πλέον ἀνακτώμενος ἔχοντας δυσμενῶς· κατὰ γὰρ τὴν ἐξεργασίαν τῶν τοιούτων ἐπιτηδευμάτων ὡς ἂν λυομένης αὐτοῖς τῆς εὐσεβείας καὶ μεταπιπτόντων τῶν ἐθῶν χαλεπῶς ἔφερον, καὶ λόγοι δὲ πόντων ἐγίνοντο παροξυνομένων ἀεὶ καὶ ταραττομένων."},{"number":366,"text":"ὁ δὲ καὶ πρὸς τὸ τοιοῦτον πολλὴν τὴν ἐπιμέλειαν ἐπῆγεν, ἀφαιρούμενος μὲν τὰς εὐκαιρίας, ἐπιτάττων δʼ ἀεὶ γίνεσθαι πρὸς τοῖς πόνοις, ἦν δʼ οὔτε σύνοδος ἐφειμένη τοῖς περὶ τὴν πόλιν οὔτε κοινωνία περιπάτου καὶ διαίτης, ἀλλʼ ἐτετήρητο τὰ πάντα. καὶ χαλεπαὶ τῶν φωραθέντων ἦσαν αἱ κολάσεις, πολλοί τε καὶ φανερῶς καὶ λεληθότως εἰς τὸ φρούριον ἀναγόμενοι τὴν Ὑρκανίαν ἐκεῖ διεφθείροντο, κἀν τῇ πόλει κἀν ταῖς ὁδοιπορίαις ἦσαν οἱ τοὺς συνιόντας εἰς ταὐτὸν ἐπισκοποῦντες."},{"number":367,"text":"ἤδη δέ φασιν οὐδʼ αὐτὸν ἀμελεῖν τοῦ τοιούτου μέρους, ἀλλὰ πολλάκις ἰδιώτου σχῆμα λαμβάνοντα καταμίγνυσθαι νύκτωρ εἰς τοὺς ὄχλους, καὶ πεῖραν αὐτῶν, ἣν ἔχουσιν ὑπὲρ τῆς ἀρχῆς, λαμβάνειν."},{"number":368,"text":"τοὺς μὲν οὖν παντάπασιν ἐξαυθαδιζομένους πρὸς τὸ μὴ συμπεριφέρεσθαι τοῖς ἐπιτηδεύμασιν πάντας ἐπεξῄει τοὺς τρόπους, τὸ δʼ ἄλλο πλῆθος ὅρκοις ἠξίου πρὸς τὴν πίστιν ὑπάγεσθαι καὶ συνηνάγκαζεν ἐνώμοτον αὐτῷ τὴν εὔνοιαν ἦ μὴν διαφυλάξειν ἐπὶ τῆς ἀρχῆς ὁμολογεῖν."},{"number":369,"text":"οἱ μὲν οὖν πολλοὶ κατὰ θεραπείαν καὶ δέος εἶκον οἷς ἠξίου, τοὺς δὲ φρονήματος μεταποιουμένους καὶ δυσχεραίνοντας ἐπὶ τῷ καταναγκάζεσθαι πάντα τρόπον ἐκποδὼν ἐποιεῖτο."},{"number":370,"text":"συνέπειθεν δὲ καὶ τοὺς περὶ Πολλίωνα τὸν Φαρισαῖον καὶ Σαμαίαν καὶ τῶν ἐκείνοις συνδιατριβόντων τοὺς πλείστους ὀμνύειν· οἱ δʼ οὔτε συνεχώρησαν οὔθʼ ὁμοίως τοῖς ἀρνησαμένοις ἐκολάσθησαν ἐντροπῆς διὰ τὸν Πολλίωνα τυχόντες."},{"number":371,"text":"ἀφείθησαν δὲ ταύτης τῆς ἀνάγκης καὶ οἱ παρʼ ἡμῖν Ἐσσαῖοι καλούμενοι· γένος δὲ τοῦτʼ ἔστιν διαίτῃ χρώμενον τῇ παρʼ Ἕλλησιν ὑπὸ Πυθαγόρου καταδεδειγμένῃ."},{"number":372,"text":"περὶ τούτων μὲν οὖν ἐν ἄλλοις σαφέστερον διέξειμι. τοὺς δὲ Ἐσσηνοὺς ἀφʼ οἵας αἰτίας ἐτίμα μεῖζόν τι φρονῶν ἐπʼ αὐτοῖς ἢ κατὰ τὴν θνητὴν φύσιν, εἰπεῖν ἄξιον· οὐ γὰρ ἀπρεπὴς ὁ λόγος φανεῖται τῷ τῆς ἱστορίας γένει παραδηλῶν καὶ τὴν ὑπὲρ τούτων ὑπόληψιν."},{"number":373,"text":"Ἦν τις τῶν Ἐσσηνῶν Μανάημος ὄνομα καὶ τἆλλα κατὰ τὴν προαίρεσιν τοῦ βίου καλοκαγαθίαν μαρτυρούμενος καὶ πρόγνωσιν ἐκ θεοῦ τῶν μελλόντων ἔχων. οὗτος ἔτι παῖδα τὸν Ἡρώδην εἰς διδασκάλου φοιτῶντα κατιδὼν βασιλέα Ἰουδαίων προσηγόρευσεν."},{"number":374,"text":"ὁ δʼ ἀγνοεῖν ἢ κατειρωνεύεσθαι νομίζων αὐτὸν ἀνεμίμνησκεν ἰδιώτης ὤν. Μανάημος δὲ μειδιάσας ἠρέμα καὶ τύπτων τῇ χειρὶ κατὰ τῶν γλουτῶν ἀλλά τοι καὶ βασιλεύσεις, ἔφη, καὶ τὴν ἀρχὴν εὐδαιμόνως ἀπάξεις· ἠξίωσαι γὰρ ἐκ θεοῦ. καὶ μέμνησο τῶν Μαναήμου πληγῶν, ὥστε σοι καὶ τοῦτο σύμβολον εἶναι τῶν κατὰ τὴν τύχην μεταπτώσεων."},{"number":375,"text":"ἄριστος γὰρ ὁ τοιοῦτος λογισμός, εἰ καὶ δικαιοσύνην ἀγαπήσειας καὶ πρὸς τὸν θεὸν εὐσέβειαν ἐπιείκειαν δὲ πρὸς τοὺς πολίτας· ἀλλʼ οὐ γὰρ οἶδά σε τοιοῦτον ἔσεσθαι τὸ πᾶν ἐπιστάμενος."},{"number":376,"text":"εὐτυχίᾳ μὲν γὰρ ὅσον οὐκ ἄλλος διοίσεις καὶ τεύξῃ δόξης αἰωνίου, λήθην δʼ εὐσεβείας ἕξεις καὶ τοῦ δικαίου. ταῦτα δʼ οὐκ ἂν λάθοι τὸν θεὸν ἐπὶ τῇ καταστροφῇ τοῦ βίου τῆς ἀντʼ αὐτῶν ὀργῆς ἀπομνημονευομένης."},{"number":377,"text":"τούτοις αὐτίκα μὲν ἥκιστα τὸν νοῦν προσεῖχεν ἐλπίδι λειπόμενος αὐτῶν Ἡρώδης, κατὰ μικρὸν δὲ ἀρθεὶς ἕως καὶ τοῦ βασιλεύειν καὶ εὐτυχεῖν ἐν τῷ μεγέθει τῆς ἀρχῆς μεταπέμπεται τὸν Μανάημον καὶ περὶ τοῦ χρόνου πόσον ἄρξει διεπυνθάνετο."},{"number":378,"text":"Μανάημος δὲ τὸ μὲν σύμπαν οὐκ εἶπεν· ὡς δὲ σιωπῶντος αὐτοῦ, μόνον εἰ δέκα γενήσονται βασιλείας ἐνιαυτοὶ προσεπύθετο καὶ εἴκοσι καὶ τριάκοντα εἰπὼν τὸν ὅρον οὐκ ἐπέθηκε τῷ τέλει τῆς προθεσμίας, Ἡρώδης δὲ καὶ τούτοις ἀρκεσθεὶς τόν τε Μανάημον ἀφῆκεν δεξιωσάμενος καὶ πάντας ἀπʼ ἐκείνου τοὺς Ἐσσηνοὺς τιμῶν διετέλει."},{"number":379,"text":"ταῦτα μὲν οὖν εἰ καὶ παράδοξα δηλῶσαι τοῖς ἐντυγχάνουσιν ἠξιώσαμεν καὶ περὶ τῶν παρʼ ἡμῖν ἐμφῆναι, διότι πολλοὶ διὰ τοιούτων ὑπὸ καλοκαγαθίας καὶ τῆς τῶν θείων ἐμπειρίας ἀξιοῦνται."}],"11":[{"number":380,"text":"Τότε δʼ οὖν ὀκτωκαιδεκάτου τῆς Ἡρώδου βασιλείας γεγονότος ἐνιαυτοῦ μετὰ τὰς προειρημένας πράξεις ἔργον οὐ τὸ τυχὸν ἐπεβάλετο, τὸν νεὼν τοῦ θεοῦ διʼ αὐτοῦ κατασκευάσασθαι μείζω τε τὸν περίβολον καὶ πρὸς ὕψος ἀξιοπρεπέστερον ἐγείρειν, ἡγούμενος ἁπάντων αὐτῷ τῶν πεπραγμένων περισημότερον, ὥσπερ ἦν, ἐκτελεσθήσεσθαι τοῦτο καὶ πρὸς αἰώνιον μνήμην ἀρκέσειν."},{"number":381,"text":"οὐχ ἕτοιμον δὲ τὸ πλῆθος ἐπιστάμενος οὐδὲ ῥᾴδιον ἔσεσθαι πρὸς τὸ μέγεθος τῆς ἐπιχειρήσεως ἠξίου λόγῳ προκαταστησάμενος ἐγχειρῆσαι τῷ παντί, καὶ συγκαλέσας αὐτοὺς ἔλεγε τοιάδε·"},{"number":382,"text":"τὰ μὲν ἄλλα μοι τῶν κατὰ τὴν βασιλείαν πεπραγμένων, ἄνδρες ὁμόφυλοι, περισσὸν ὑπολαμβάνω λέγειν. καίτοι τοῦτον ἐγένετο τὸν τρόπον, ὡς ἐλάττω μὲν ἐμοὶ τὸν ἀπʼ αὐτῶν κόσμον, πλείω δὲ ὑμῖν τὴν ἀσφάλειαν φέρειν."},{"number":383,"text":"οὔτε γὰρ ἐν τοῖς δυσχερεστάτοις ἀμελήσας τῶν εἰς τὰς ὑμετέρας χρείας διαφερόντων οὔτε ἐν τοῖς κατασκευάσμασιν ἐπιτηδεύσας ἐμαυτῷ μᾶλλον ἢ καὶ πᾶσιν ὑμῖν τὸ ἀνεπηρέαστον, οἶμαι σὺν τῇ τοῦ θεοῦ βουλήσει πρὸς εὐδαιμονίαν ὅσον οὐ πρότερον ἀγηοχέναι τὸ Ἰουδαίων ἔθνος."},{"number":384,"text":"τὰ μὲν οὖν κατὰ μέρος ἐξεργασθέντα περὶ τὴν χώραν καὶ πόλεις ὅσας ἐν αὐτῇ καὶ τοῖς ἐπικτήτοις ἐγείραντες κόσμῳ τῷ καλλίστῳ τὸ γένος ἡμῶν ηὐξήσαμεν, περίεργά μοι δοκεῖ λέγειν εἰδόσιν. τὸ δὲ τῆς ἐπιχειρήσεως, ᾗ νῦν ἐπιχειρεῖν ἐπιβάλλομαι, παντὸς εὐσεβέστατον καὶ κάλλιστον ἐφʼ ἡμῶν γενέσθαι νῦν ἐκφανῶ·"},{"number":385,"text":"τὸν γὰρ ναὸν τοῦτον ᾠκοδόμησαν μὲν τῷ μεγίστῳ θεῷ πατέρες ἡμέτεροι μετὰ τὴν ἐκ Βαβυλῶνος ἐπάνοδον, ἐνδεῖ δʼ αὐτῷ πρὸς τὸ μέγεθος εἰς ὕψος ἑξήκοντα πήχεις· τοσοῦτον γὰρ ὑπερεῖχεν ὁ πρῶτος ἐκεῖνος, ὃν Σολομῶν ἀνῳκοδόμησεν."},{"number":386,"text":"καὶ μηδεὶς ἀμέλειαν εὐσεβείας τῶν πατέρων καταγνώτω· γέγονεν γὰρ οὐ παρʼ ἐκείνους ἐλάττων ὁ ναός, ἀλλὰ ταῦτα καὶ Κῦρος καὶ Δαρεῖος ὁ Ὑστάσπου τὰ μέτρα τῆς δομήσεως ἔδοσαν, οἷς ἐκεῖνοι καὶ τοῖς ἀπογόνοις δουλεύσαντες καὶ μετʼ ἐκείνους Μακεδόσιν οὐκ ἔσχον εὐκαιρίαν τὸ πρῶτον τῆς εὐσεβείας ἀρχέτυπον εἰς ταὐτὸν ἀναγαγεῖν μέγεθος."},{"number":387,"text":"ἐπειδὴ δὲ νῦν ἐγὼ μὲν ἄρχω θεοῦ βουλήσει, περίεστιν δὲ καὶ μῆκος εἰρήνης καὶ κτῆσις χρημάτων καὶ μέγεθος προσόδων, τὸ δὲ μέγιστον φίλοι καὶ διʼ εὐνοίας οἱ πάντων ὡς ἔπος εἰπεῖν κρατοῦντες Ῥωμαῖοι, πειράσομαι τὸ παρημελημένον ἀνάγκῃ καὶ δουλείᾳ τοῦ πρότερον χρόνου διορθούμενος τελείαν ἀποδοῦναι τῷ θεῷ τὴν ἀνθʼ ὧν ἔτυχον τῆσδε τῆς βασιλείας εὐσέβειαν."},{"number":388,"text":"Ὁ μὲν Ἡρώδης ταῦτʼ εἶπεν, ἐξέπληξε δὲ τοὺς πολλοὺς ὁ λόγος παρὰ δόξαν ἐμπεσών. καὶ τὸ μὲν τῆς ἐλπίδος ἄπιστον οὐκ ἐπήγειρεν αὐτούς, ἠδημόνουν δέ, μὴ φθάσας καταλῦσαι τὸ πᾶν ἔργον οὐκ ἐξαρκέσει πρὸς τέλος ἀγαγεῖν τὴν προαίρεσιν· ὅ τε κίνδυνος αὐτοῖς μείζων ἐφαίνετο καὶ δυσεγχείρητον ἐδόκει τὸ μέγεθος τῆς ἐπιβολῆς."},{"number":389,"text":"οὕτως δʼ αὐτῶν διακειμένων παρεθάρρυνεν ὁ βασιλεύς, οὐ πρότερον καθαιρήσειν φάμενος τὸν ναὸν μὴ πάντων αὐτῷ τῶν εἰς συντέλειαν παρεσκευασμένων. καὶ ταῦτα προειπὼν οὐκ ἐψεύσατο·"},{"number":390,"text":"χιλίας γὰρ εὐτρεπίσας ἁμάξας, αἳ βαστάσουσι τοὺς λίθους, ἐργάτας δὲ μυρίους τοὺς ἐμπειροτάτους ἐπιλεξάμενος καὶ ἱερεῦσιν τὸν ἀριθμὸν χιλίοις ἱερατικὰς ὠνησάμενος στολάς, καὶ τοὺς μὲν διδάξας οἰκοδόμους, ἑτέρους δὲ τέκτονας, ἥπτετο τῆς κατασκευῆς ἁπάντων αὐτῷ προθύμως προευτρεπισμένων."},{"number":391,"text":"Ἀνελὼν δὲ τοὺς ἀρχαίους θεμελίους καὶ καταβαλόμενος ἑτέρους ἐπʼ αὐτῶν ναὸν ἤγειρεν μήκει μὲν ἑκατὸν ὄντα πηχῶν, τὸ δʼ ὕψος εἴκοσι περιττοῖς, οὓς τῷ χρόνῳ συνιζησάντων τῶν θεμελίων ὑπέβη. καὶ τοῦτο μὲν κατὰ τοὺς Νέρωνος καιροὺς ἐπεγείρειν ἐγνώκειμεν."},{"number":392,"text":"ᾠκοδομήθη δὲ ὁ ναὸς ἐκ λίθων λευκῶν τε καὶ κραταιῶν τὸ μέγεθος ἑκάστων περὶ πέντε καὶ εἴκοσι πήχεις ἐπὶ μῆκος, ὀκτὼ δὲ ὕψος, εὖρος δὲ περὶ δώδεκα."},{"number":393,"text":"καὶ παντὸς αὐτοῦ καθότι καὶ τῆς βασιλείου στοᾶς τὸ μὲν ἔνθεν καὶ ἔνθεν ταπεινότατον, ὑψηλότατον δὲ τὸ μεσαίτατον, ὡς περίοπτον ἐκ πολλῶν σταδίων εἶναι τοῖς τὴν χώραν νεμομένοις, μᾶλλον δʼ εἴ τινες κατʼ ἐναντίον οἰκοῦντες ἢ προσιόντες τύχοιεν."},{"number":394,"text":"θύρας δὲ ἐπὶ τῆς εἰσόδου σὺν τοῖς ὑπερθυρίοις ἴσον ἐχούσας τῷ ναῷ ποικίλοις ἐμπετάσμασιν κεκόσμητο, τὰ μὲν ἄνθη ἁλουργέσιν, κίονας δὲ ἐνυφασμένους."},{"number":395,"text":"καθύπερθε δʼ αὐτῶν ὑπὸ τοῖς τριχώμασιν ἄμπελος διετέτατο χρυσῆ τοὺς βότρυας ἀπαιωρουμένους ἔχουσα, θαῦμα καὶ τοῦ μεγέθους καὶ τῆς τέχνης τοῖς ἰδοῦσιν, οἷον ἐν πολυτελείᾳ τῆς ὕλης τὸ κατασκευασθὲν ἦν."},{"number":396,"text":"περιελάμβανεν δὲ καὶ στοαῖς μεγίσταις τὸν ναὸν ἅπαντα πρὸς τὴν ἀναλογίαν ἐπιτηδεύων καὶ τὰς δαπάνας τῶν πρὶν ὑπερβαλλόμενος, ὡς οὐκ ἄλλος τις δοκεῖ ἐπικεκοσμηκέναι τὸν ναόν. ἄμφω δʼ ἦσαν μετὰ τοῦ τείχους, αὐτὸ δὲ τὸ τεῖχος ἔργον μέγιστον ἀνθρώποις ἀκουσθῆναι."},{"number":397,"text":"λόφος ἦν πετρώδης ἀνάντης ἠρέμα πρὸς τοῖς ἑῴοις μέρεσιν τῆς πόλεως ὑπτιούμενος ἐπὶ τὴν κορυφὴν ἄκραν."},{"number":398,"text":"τοῦτον ὁ πρῶτος ἡμῶν βασιλεὺς Σολομῶν κατʼ ἐπιφροσύνην μεγάλαις ἐργασίαις ἀπετείχιζεν τὰ περὶ τὴν ἄκραν ἄνωθεν, ἀπετείχιζεν δὲ κάτωθεν ἀπὸ τῆς ῥίζης ἀρχόμενος, ἣν βαθεῖα περιθεῖ φάραγξ ἠλιβάτοις πέτραις μολίβδῳ δεδεμέναις πρὸς ἀλλήλας, ἀπολαμβάνων αἰεί τι τῆς ἔσω χώρας καὶ προβαίνων εἰς βάθος,"},{"number":399,"text":"ὥστʼ ἄπειρον εἶναι τό τε μέγεθος τῆς δομῆς καὶ τὸ ὕψος τετραγώνου γεγενημένης, ὡς τὰ μὲν μεγέθη τῶν λίθων ἀπὸ μετώπου κατὰ τὴν ἐπιφάνειαν ὁρᾶσθαι, τὰ δʼ ἐντὸς σιδήρῳ διησφαλισμένα συνέχειν τὰς ἁρμογὰς ἀκινήτους τῷ παντὶ χρόνῳ."},{"number":400,"text":"τῆς δʼ ἐργασίας οὕτω συναπτούσης εἰς ἄκρον τὸν λόφον ἀπεργασάμενος αὐτοῦ τὴν κορυφὴν καὶ τὰ κοῖλα τῶν περὶ τὸ τεῖχος ἐμπλήσας ἰσόπεδον τοῖς κατὰ τὴν ἐπιφάνειαν τὴν ἄνω καὶ λεῖον ἐποίησεν. τοῦτʼ ἦν τὸ πᾶν περίβολος τεττάρων σταδίων τὸν κύκλον ἔχων, ἑκάστης γωνίας στάδιον μῆκος ἀπολαμβανούσης."},{"number":401,"text":"ἐνδοτέρω δὲ τούτου καὶ παρʼ αὐτὴν τὴν ἄκραν ἄλλο τεῖχος ἄνω λίθινον περιθεῖ, κατὰ μὲν ἑῴαν ῥάχιν ἰσομήκη τῷ τείχει στοὰν ἔχον διπλῆν, ἐν μέσῳ τοῦ νεὼ τετυχηκότος ἀφορῶσαν εἰς τὰς θύρας αὐτοῦ."},{"number":402,"text":"ταύτην πολλοὶ βασιλεῖς οἱ πρόσθεν κατεσκεύασαν. τοῦ δʼ ἱεροῦ παντὸς ἦν ἐν κύκλῳ πεπηγμένα σκῦλα βαρβαρικά, καὶ ταῦτα πάντα βασιλεὺς Ἡρώδης ἀνέθηκεν προσθεὶς ὅσα καὶ τῶν Ἀράβων ἔλαβεν."},{"number":403,"text":"Κατὰ δὲ τὴν βόρειον πλευρὰν ἀκρόπολις ἐγγώνιος εὐερκὴς ἐτετείχιστο διάφορος ἐχυρότητι. ταύτην οἱ πρὸ Ἡρώδου τοῦ Ἀσαμωναίων γένους βασιλεῖς καὶ ἀρχιερεῖς ᾠκοδόμησαν καὶ βᾶριν ἐκάλεσαν, ὡς ἐκεῖ τὴν ἱερατικὴν αὐτοῖς ἀποκεῖσθαι στολήν, ἣν ὅταν δέῃ θύειν τότε μόνον ὁ ἀρχιερεὺς ἀμφιέννυται."},{"number":404,"text":"ταύτην Ἡρώδης ὁ βασιλεὺς ἐφύλαξεν ἐν τῷ τόπῳ καὶ μετὰ τὴν ἐκείνου τελευτὴν ὑπὸ Ῥωμαίοις ἦν μέχρι τῶν Τιβερίου Καίσαρος χρόνων."},{"number":405,"text":"ἐπὶ τούτου δὲ Οὐιτέλλιος ὁ τῆς Συρίας ἡγεμὼν ἐπιδημήσας τοῖς Ἱεροσολύμοις, δεξαμένου τοῦ πλήθους αὐτὸν λαμπρότατα πάνυ θέλων αὐτοὺς τῆς εὐποιίας ἀμείψασθαι, ἐπεὶ παρεκάλεσαν τὴν ἱερὰν στολὴν ὑπὸ τὴν αὐτῶν ἐξουσίαν ἔχειν, ἔγραψεν περὶ τούτων Τιβερίῳ Καίσαρι κἀκεῖνος ἐπέτρεψεν, καὶ παρέμεινεν ἡ ἐξουσία τῆς στολῆς τοῖς Ἰουδαίοις μέχρις ἐτελεύτησεν ὁ βασιλεὺς Ἀγρίππας."},{"number":406,"text":"μετὰ τοῦτον δὲ Κάσσιος Λογγῖνος ὁ τὴν Συρίαν τότε διοικῶν καὶ Κούσπιος Φᾶδος ὁ τῆς Ἰουδαίας ἐπίτροπος κελεύουσιν τοὺς Ἰουδαίους εἰς τὴν Ἀντωνίαν καταθέσθαι τὴν στολήν· Ῥωμαίους γὰρ αὐτῆς εἶναι δεῖν κυρίους, καθὼς καὶ πρότερον ἦσαν."},{"number":407,"text":"πέμπουσιν οὖν Ἰουδαῖοι πρέσβεις πρὸς Κλαύδιον Καίσαρα περὶ τούτων παρακαλέσοντας. ὧν ἀναβάντων ὁ νεώτερος βασιλεὺς Ἀγρίππας ἐν Ῥώμῃ τυγχάνων αἰτησάμενος παρὰ τοῦ αὐτοκράτορος τὴν ἐξουσίαν ἔλαβεν ἐντειλαμένου Οὐιτελλίῳ τῷ τῆς Συρίας ἀντιστρατήγῳ."},{"number":408,"text":"πρότερον δʼ ἦν ὑπὸ σφραγῖδα τοῦ ἀρχιερέως καὶ τῶν γαζοφυλάκων, καὶ πρὸ μιᾶς ἡμέρας τῆς ἑορτῆς ἐπὶ τὸν Ῥωμαίων φρούραρχον ἀναβαίνοντες οἱ γαζοφύλακες καὶ καταμανθάνοντες τὴν ἑαυτῶν σφραγῖδα τὴν στολὴν ἐλάμβανον. εἶτʼ αὖθις τῆς ἑορτῆς παρελθούσης εἰς τὸν αὐτὸν κομίσαντες τόπον καὶ τῷ φρουράρχῳ δείξαντες σύμφωνον τὴν σφραγῖδα κατετίθεντο."},{"number":409,"text":"ταῦτα μὲν οὖν ὑπὸ τοῦ πάθους τῶν ἐπισυμβεβηκότων παρεδηλώθη. τότε δʼ οὖν ὁ τῶν Ἰουδαίων βασιλεὺς Ἡρώδης καὶ ταύτην τὴν βᾶριν ὀχυρωτέραν κατασκευάσας ἐπʼ ἀσφαλείᾳ καὶ φυλακῇ τοῦ ἱεροῦ, χαριζόμενος Ἀντωνίῳ φίλῳ μὲν αὐτοῦ Ῥωμαίων δὲ ἄρχοντι προσηγόρευσεν Ἀντωνίαν."},{"number":410,"text":"Ἐν δὲ τοῖς ἑσπερίοις μέρεσιν τοῦ περιβόλου πύλαι τέτταρες ἐφέστασαν, ἡ μὲν εἰς τὰ βασίλεια τείνουσα τῆς ἐν μέσῳ φάραγγος εἰς δίοδον ἀπειλημμένης, αἱ δύο δὲ εἰς τὸ προάστειον, ἡ λοιπὴ δʼ εἰς τὴν ἄλλην πόλιν βαθμίσιν πολλαῖς κάτω τε εἰς τὴν φάραγγα διειλημμένη καὶ ἀπὸ ταύτης ἄνω πάλιν ἐπὶ τὴν πρόσβασιν· ἄντικρυς γὰρ ἡ πόλις ἔκειτο τοῦ ἱεροῦ θεατροειδὴς οὖσα περιεχομένη βαθείᾳ φάραγγι κατὰ πᾶν τὸ νότιον κλίμα."},{"number":411,"text":"τὸ δὲ τέταρτον αὐτοῦ μέτωπον τὸ πρὸς μεσημβρίαν εἶχε μὲν καὶ αὐτὸ πύλας κατὰ μέσον, ἐπʼ αὐτοῦ δὲ τὴν βασίλειον στοὰν τριπλῆν κατὰ μῆκος διιοῦσαν ἀπὸ τῆς ἑῴας φάραγγος ἐπὶ τὴν ἑσπέριον· οὐ γὰρ ἦν ἐκτεῖναι προσωτέρω δυνατόν."},{"number":412,"text":"ἔργον δʼ ἦν ἀξιαφηγητότατον τῶν ὑφʼ ἡλίῳ· μεγάλου γὰρ ὄντος τοῦ τῆς φάραγγος ἀναλήμματος καὶ οὐδʼ ἀνεκτοῦ κατιδεῖν, εἴ τις ἄνωθεν εἰς τὸν βυθὸν εἰσκύπτοι, παμμέγεθες ὕψος ἐν αὐτῷ τὸ τῆς στοᾶς ἀνέστηκεν, ὡς εἴ τις ἀπʼ ἄκρου τοῦ ταύτης τέγους ἄμφω συντιθεὶς τὰ βάθη διοπτεύοι, σκοτοδινιᾶν οὐκ ἐξικνουμένης τῆς ὄψεως εἰς ἀμέτρητον τὸν βυθόν."},{"number":413,"text":"κίονες δʼ ἐφέστασαν κατʼ ἀντίστοιχον ἀλλήλοις ἐπὶ μῆκος τέτραχα, συνεδέδετο γὰρ ὁ τέταρτος στοῖχος λιθοδομήτῳ τείχει, καὶ πάχος ἦν ἑκάστου κίονος εἰς τρεῖς ἐπισυναπτόντων ἀλλήλοις τὰς ὀργυιὰς περιλαβεῖν, μῆκος δὲ ποδῶν ἑπτὰ καὶ εἴκοσι διπλῆς σπείρας ὑπειλημένης."},{"number":414,"text":"πλῆθος δὲ συμπάντων δύο καὶ ἑξήκοντα καὶ ἑκατὸν κιονοκράνων αὐτοῖς κατὰ τὸν Κορίνθιον τρόπον ἐπεξειργασμένων γλυφαῖς ἔκπληξιν ἐμποιούσαις διὰ τὴν τοῦ παντὸς μεγαλουργίαν."},{"number":415,"text":"τεττάρων δὲ στίχων ὄντων τρεῖς ἀπολαμβάνουσι τὰς διὰ μέσου χώρας ταῖς στοαῖς. τῶν δὲ αἱ μὲν δύο παράλληλοι τὸν αὐτὸν γεγόνασι τρόπον, εὖρος ἑκατέρας πόδες τριάκοντα, μῆκος δὲ στάδιον, ὕψος δὲ πόδες ὑπὲρ πεντήκοντα· τῆς δὲ μέσης εὖρος μὲν ἡμιόλιον, ὕψος δὲ διπλάσιον· ἀνεῖχεν γὰρ πλεῖστον παρὰ τὰς ἑκατέρωθεν."},{"number":416,"text":"αἱ δʼ ὀροφαὶ ξύλοις ἐξήσκηντο γλυφαῖς πολυτρόποις σχημάτων ἰδέαις, καὶ τὸ τῆς μέσης βάθος ἐπὶ μεῖζον ἠγείρετο περιδεδομημένου τοῖς ἐπιστυλίοις προμετωπιδίου τοίχου κίονας ἔχοντος ἐνδεδομημένους καὶ ξεστοῦ παντὸς ὄντος, ὡς ἄπιστα τοῖς οὐκ εἰδόσιν καὶ σὺν ἐκπλήξει θεατὰ τοῖς ἐντυγχάνουσιν εἶναι."},{"number":417,"text":"τοιοῦτος μὲν ὁ πρῶτος περίβολος ἦν. ἐν μέσῳ δὲ ἀπέχων οὐ πολὺ δεύτερος, προσβατὸς βαθμίσιν ὀλίγαις, ὃν περιεῖχεν ἑρκίον λιθίνου δρυφάκτου γραφῇ κωλῦον εἰσιέναι τὸν ἀλλοεθνῆ θανατικῆς ἀπειλουμένης τῆς ζημίας."},{"number":418,"text":"εἶχεν δʼ ὁ μὲν ἐντὸς περίβολος κατὰ μὲν τὸ νότιον καὶ βόρειον κλίμα τριστοίχους πυλῶνας ἀλλήλων διεστῶτας, κατὰ δὲ ἡλίου βολὰς ἕνα τὸν μέγαν, διʼ οὗ παρῄειμεν ἁγνοὶ μετὰ γυναικῶν."},{"number":419,"text":"ἐσωτέρω δὲ κἀκείνου γυναιξὶν ἄβατον ἦν τὸ ἱερόν. ἐκείνου δʼ ἐνδοτέρω τρίτον, ὅπου τοῖς ἱερεῦσιν εἰσελθεῖν ἐξὸν ἦν μόνοις. ὁ ναὸς ἐν τούτῳ καὶ πρὸ αὐτοῦ βωμὸς ἦν, ἐφʼ οὗ τὰς θυσίας ὡλοκαυτοῦμεν τῷ θεῷ."},{"number":420,"text":"τούτων εἰς οὐδένα τῶν τριῶν ὁ βασιλεὺς Ἡρώδης παρῆλθεν· ἐκεκώλυτο γὰρ οὐκ ὢν ἱερεύς. ἀλλὰ κἀν τοῖς ἔργοις τὰ περὶ τὰς στοὰς καὶ τοὺς ἔξω περιβόλους ἐπραγματεύετο καὶ ταῦτʼ ᾠκοδόμησεν ἔτεσιν ὀκτώ."},{"number":421,"text":"Τοῦ δὲ ναοῦ διὰ τῶν ἱερέων οἰκοδομηθέντος ἐνιαυτῷ καὶ μησὶν πέντε ἅπας ὁ λαὸς ἐπληρώθη χαρᾶς καὶ τοῦ τάχους πρῶτον μὲν τῷ θεῷ τὰς εὐχαριστηρίους ἐποιοῦντο, μετὰ δὲ καὶ τῆς προθυμίας τοῦ βασιλέως ἑορτάζοντες καὶ κατευφημοῦντες τὴν ἀνάκτισιν."},{"number":422,"text":"ὁ δὲ βασιλεὺς τριακοσίους ἔθυσε τῷ θεῷ βοῦς καὶ τῶν ἄλλων οἱ κατὰ δύναμιν, ὧν οὐχ οἷόν τε τὸν ἀριθμὸν εἰπεῖν· ἐκφεύγει γὰρ τὸ δύνασθαι πρὸς ἀλήθειαν εἰπεῖν·"},{"number":423,"text":"συνεπεπτώκει γὰρ τῇ προθεσμίᾳ τοῦ περὶ τὸν ναὸν ἔργου καὶ τὴν ἡμέραν τῷ βασιλεῖ τῆς ἀρχῆς, ἣν ἐξ ἔθους ἑώρταζον, ἐς ταὐτὸν ἐλθεῖν, καὶ περισημοτάτην ἐξ ἀμφοῖν τὴν ἑορτὴν γενέσθαι."},{"number":424,"text":"Κατεσκευάσθη δὲ καὶ κρυπτὴ διώρυξ τῷ βασιλεῖ, φέρουσα μὲν ἀπὸ τῆς Ἀντωνίας μέχρι τοῦ ἔσωθεν ἱεροῦ πρὸς τὴν ἀνατολικὴν θύραν, ἐφʼ ἧς αὐτῷ καὶ πύργον κατεσκεύασεν, ἵνʼ ἔχῃ διὰ τῶν ὑπογέων εἰς αὐτὸν ἀνιέναι, τὸν ἐκ τοῦ δήμου νεωτερισμὸν ἐπὶ τοῖς βασιλεῦσι φυλαττόμενος."},{"number":425,"text":"λέγεται δὲ κατʼ ἐκεῖνον τὸν καιρὸν οἰκοδομουμένου τοῦ ναοῦ τὰς μὲν ἡμέρας οὐχ ὕειν, ἐν δὲ ταῖς νυξὶ γίνεσθαι τοὺς ὄμβρους, ὡς μὴ κωλυσιεργεῖν. καὶ τοῦτον τὸν λόγον οἱ πατέρες ἡμῖν παρέδωκαν, οὐδʼ ἐστὶν ἄπιστον, εἰ καὶ πρὸς τὰς ἄλλας ἀπίδοι τις ἐμφανείας τοῦ θεοῦ. τὰ μὲν οὖν περὶ τὸν ναὸν ἐξῳκοδομήθη τοῦτον τὸν τρόπον."}]},"count":425};a[16]={"book":16,"title":"Τάδε ἔνεστιν ἐν τῇ ἑξκαιδεκάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὃν τρόπον Ἀλέξανδρος καὶ Ἀριστόβουλος ἀπὸ Ῥώμης ὑπέστρεψαν πρὸς τὸν πατέρα.\n\nὡς Σαλώμη καὶ Φερώρας οἱ τοῦ βασιλέως ἀδελφοὶ ταῖς κατ' αὐτῶν διαβολαῖς ἐχρῶντο.\n\nὡς γυναῖκας δοὺς τοῖς περὶ Ἀλέξανδρον Ἡρώδης πρὸς Ἀγρίππαν ἐξέπλευσεν εἰς Μιτυλήνην κἀκεῖθεν αὐτὸν ἔπεισεν εἰς Ἰουδαίαν παραγενέσθαι.\n\nἄφοδος Ἀγρίππα εἰς Ἰωνίαν καὶ ὡς Ἡρώδης τὸ δεύτερον ἐξέπλευσεν πρὸς Ἀγρίππαν εἰς τὸν Βόσπορον.\n\nἔντευξις τῶν κατ' Ἰωνίαν Ἰουδαίων Ἀγρίππᾳ παρόντος Ἡρώδου περὶ ὧν ᾐτιῶντο τοὺς Ἕλληνας.\n\nὡς Ἀγρίππας ἐβεβαίωσε μὲν αὐτοῖς τοὺς νόμους, Ἡρώδης δὲ εἰς Ἰουδαίαν ὑπέστρεψεν.\n\nὡς διελέξατο τοῖς Ἱεροσολυμίταις Ἡρώδης καὶ τὸ τέταρτον αὐτοῖς ἀφῆκεν τῶν φόρων τοῦ παρεληλυθότος ἔτους.\n\nὡς ἐστασιάσθη τὰ περὶ τὴν οἰκίαν Ἡρώδῃ προτιμῶντι μὲν Ἀντίπατρον τὸν πρεσβύτατον υἱὸν χαλεπῶς δὲ τῶν περὶ Ἀλέξανδρον φερόντων τὴν ὕβριν.\n\nὡς Ἀντιπάτρου διατρίβοντος ἐν Ῥώμῃ τοὺς περὶ Ἀλέξανδρον Ἡρώδης ἄγων ἐπὶ Καίσαρος αὐτῶν κατηγόρησεν.\n\nἈλεξάνδρου ἀπολογία ἐπὶ Καίσαρος καὶ διαλλαγαὶ πρὸς τὸν πατέρα.\n\nὡς ἀγῶνας ἤγαγε πεντετηρικοὺς Ἡρώδης ἐπὶ τῇ Καισαρείας κτίσει.\n\nπρεσβεία τῶν ἀπὸ Κυρήνης καὶ Ἀσίας Ἰουδαίων ὡς Καίσαρα περὶ ὧν ᾐτιῶντο τοὺς Ἕλληνας πραγμάτων.\n\nἀντίγραφα ἐπιστολῶν, ἃς Καῖσαρ καὶ Ἀγρίππας ἔγραψεν ὑπὲρ αὐτῶν ταῖς πόλεσιν.\n\nὡς ἀπορῶν χρημάτων Ἡρώδης κατῆλθεν εἰς τὸν Δαυίδου τάφον καὶ δειμάτων αὐτὸν ταραξάντων μνημεῖον ἔστησεν ἐπὶ τοῦ τάφου.\n\nὡς Ἀρχέλαος ὁ Καππαδόκων βασιλεὺς Ἀλέξανδρον τῷ πατρὶ διήλλαξεν δεθέντα ὑπ' αὐτοῦ πρότερον καὶ ὡς ὁ μὲν εἰς Καππαδοκίαν, Ἡρώδης δὲ εἰς Ῥώμην ἀνῆλθεν.\n\nἀπόστασις τῶν τὸν Τράχωνα οἰκούντων καὶ παράληψις διὰ τῶν στρατηγῶν τῆς χώρας.\n\nὡς Ἡρώδης τοὺς εἰς τὴν Ἀραβίαν διαφυγόντας τῶν ἀποστατῶν ἐξῃτεῖτο καὶ μὴ τυγχάνων ἐστράτευσεν ἐπ' αὐτοὺς ἐπιτρέποντος Σατορνίνου.\n\nὡς κατηγόρησε Σύλλαιος Ἄραψ ἐπὶ Καίσαρος περὶ τῆς ἐμβολῆς Ἡρώδου καὶ ὡς διὰ Νικολάου ἀπελύσατο τὰς αἰτίας ὀργιζομένου Καίσαρος.\n\nδιαβολαὶ Εὐρυκλέους κατὰ τῶν παίδων πρὸς Ἡρώδην, καὶ ὡς ἔδησεν αὐτοὺς ὁ πατὴρ καὶ τῷ Καίσαρι περὶ αὐτῶν ἔγραψεν.\n\nὡς Καίσαρος ἐξουσίαν δόντος ἐν Βηρυτῷ παρὰ τῷ συνεδρίῳ κατηγόρησε τῶν παίδων καὶ ὡς θανόντες ἐτάφησαν ἐν Ἀλεξανδρείῳ.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ιβ."},"chapters":{"1":[{"number":1,"text":"Ἐν δὲ τῇ διοικήσει τῶν ὅλων πραγμάτων ἐσπουδακὼς ὁ βασιλεὺς τὰς κατὰ μέρος ἀδικίας ἀναστεῖλαι τῶν περὶ τὴν πόλιν καὶ τὴν χώραν ἁμαρτανομένων τίθησι νόμον οὐδὲν ἐοικότα τοῖς πρώτοις, ὃν αὐτὸς ἐβεβαίου, τοὺς τοιχωρύχους ἀποδιδόμενος ἐπʼ ἐξαγωγῇ τῆς βασιλείας, ὅπερ ἦν οὐκ εἰς τὴν τιμωρίαν μόνον τῶν πασχόντων φορτικόν, ἀλλὰ καὶ κατάλυσιν περιεῖχεν τῶν πατρίων ἐθῶν."},{"number":2,"text":"τὸ γὰρ ἀλλοφύλοις καὶ μὴ τὴν αὐτὴν δίαιταν ἔχουσιν τοῦ ζῆν δουλεύειν καὶ βιάζεσθαι πάνθʼ ὅσα προσέταττον ἐξ ἀνάγκης ἐκεῖνοι ποιεῖν ἁμαρτία πρὸς τὴν θρησκείαν ἦν, οὐ κόλασις τῶν ἁλισκομένων, πεφυλαγμένης ἐν τοῖς πρώτοις τῆς τοιαύτης τιμωρίας·"},{"number":3,"text":"ἐκέλευον γὰρ οἱ νόμοι τετραπλᾶ καταβάλλειν τὸν κλέπτην, οὐκ ἔχοντα δὲ πιπράσκεσθαι μέν, ἀλλʼ οὔτι γε τοῖς ἀλλοφύλοις οὐδʼ ὥστε διηνεκῆ τὴν δουλείαν ὑπομένειν· ἔδει γὰρ ἀφεῖσθαι μετὰ ἑξαετίαν."},{"number":4,"text":"τὸ δʼ ὥσπερ ὡρίσθη τότε χαλεπὴν καὶ παράνομον γενέσθαι τὴν κόλασιν ὑπερηφανίας ἐδόκει μέρος, οὐ βασιλικῶς ἀλλὰ τυραννικῶς αὐτοῦ καὶ πρὸς τὰ κοινὰ τῶν ἀρχομένων ὀλιγώρως θεῖναι τὴν τιμωρίαν νενοηκότος."},{"number":5,"text":"ταῦτα μὲν οὖν καθʼ ὁμοιότητα τοῦ λοιποῦ τρόπου γιγνόμενα μέρος ἦν τῶν διαβολῶν καὶ τῆς ἐπʼ αὐτῷ δυσνοίας."},{"number":6,"text":"Ἐν δὲ τούτῳ τῷ καιρῷ καὶ τὸν εἰς τὴν Ἰταλίαν πλοῦν ἐποιήσατο Καίσαρί τε συντυχεῖν ὁρμηθεὶς καὶ θεάσασθαι τοὺς παῖδας ἐν τῇ Ῥώμῃ διατρίβοντας. Καῖσαρ δὲ τά τε ἄλλα φιλοφρόνως αὐτὸν ἐξεδέξατο καὶ τοὺς παῖδας ὡς ἤδη τελειωθέντας ἐν τοῖς μαθήμασιν ἀπέδωκεν ἄγειν εἰς τὴν οἰκείαν."},{"number":7,"text":"ὡς δʼ ἧκον ἀπὸ τῆς Ἰταλίας, σπουδὴ περὶ τὰ μειράκια τῶν ὄχλων ἦν, καὶ περίοπτοι πᾶσιν ἐγεγόνεισαν τῷ τε μεγέθει τῆς περὶ αὐτοὺς τύχης κοσμούμενοι καὶ βασιλικοῦ κατὰ τὰς μορφὰς ἀξιώματος οὐκ ἀποδέοντες."},{"number":8,"text":"ἐπίφθονοί τε εὐθέως ἐδόκουν Σαλώμῃ τε τῇ τοῦ βασιλέως ἀδελφῇ καὶ τοῖς Μαριάμμην ταῖς διαβολαῖς κατηγωνισμένοις· οὗτοι γὰρ ᾤοντο δυναστευόντων αὐτῶν δίκην δώσειν τῶν εἰς τὴν μητέρα τὴν ἐκείνων παρανομηθέντων."},{"number":9,"text":"τὴν αὐτὴν οὖν ταύτην ὑπόθεσιν τοῦ δέους εἰς τὴν κατʼ ἐκείνων διαβολὴν μετέφερον λογοποιοῦντες οὐ καθʼ ἡδονὰς συνεῖναι τῷ πατρὶ διὰ τὸν τῆς μητρὸς θάνατον, ὡς μηδὲ ὅσιον εἶναι δοκεῖν ἐπὶ ταὐτὸν συνιέναι τῷ τῆς τεκούσης φονεῖ·"},{"number":10,"text":"ταῦτα γὰρ ἀπὸ τῆς ἀληθείας ἐπὶ τὸ πιθανὸν τῆς αἰτίας φέροντες κακοῦν ἐδύναντο καὶ τῆς εὐνοίας ἧς εἶχεν εἰς τοὺς παῖδας ἀφαιρεῖν· οὐδὲ γὰρ πρὸς αὐτὸν ἄντικρυς ἔλεγον, ἀλλʼ εἰς τὸ λοιπὸν πλῆθος ἐσκόρπιζον τοὺς τοιούτους λόγους· ἐξ οὗ πρὸς τὸν Ἡρώδην ἀναφερομένων ὑποκατεσκευάζετο μῖσος οὐδʼ αὐτῇ τῇ φύσει χρόνῳ νικώμενον."},{"number":11,"text":"ἐν μέντοι τῷ τότε πάσης ὑποψίας καὶ διαβολῆς μείζονι χρώμενος ὁ βασιλεὺς τῇ τοῦ γεγεννηκέναι φιλοστοργίᾳ καὶ τιμῆς ἧς ἔδει μετεδίδου καὶ γυναῖκας ἐν ἡλικίᾳ γεγονόσιν ἐζεύγνυεν, Ἀριστοβούλῳ μὲν τὴν Σαλώμης θυγατέρα Βερενίκην, Ἀλεξάνδρῳ δὲ τὴν Ἀρχελάου τοῦ Καππαδόκων βασιλέως Γλαφύραν."}],"2":[{"number":12,"text":"Ταῦτα διοικήσας, ἐπειδὴ καὶ Μᾶρκον Ἀγρίππαν ἐπύθετο καταπεπλευκέναι πάλιν ἐκ τῆς Ἰταλίας εἰς τὴν Ἀσίαν, ἐπειχθεὶς πρὸς αὐτὸν ἠξίωσεν εἴς τε τὴν βασιλείαν αὐτοῦ παρελθεῖν καὶ τυχεῖν ὧν ἔδει παρὰ ἀνδρὸς ξένου καὶ φίλου."},{"number":13,"text":"κἀκεῖνος μὲν εἴξας λιπαρῶς ἐγκειμένου ἧκεν εἰς τὴν Ἰουδαίαν, Ἡρώδης δὲ οὐδὲν ἀρεσκείας ἀπέλιπεν ἔν τε ταῖς νεοκτίστοις πόλεσιν ὑποδεχόμενος αὐτὸν καὶ μετὰ τοῦ τὰς κατασκευὰς ἐπιδεικνύναι πᾶσαν ἀπόλαυσιν διαίτης καὶ πολυτελείας ἐξαλλάττων αὐτῷ καὶ τοῖς φίλοις ἔν τε τῇ Σεβαστῇ καὶ Καισαρείᾳ περὶ τὸν λιμένα τὸν ὑπʼ αὐτοῦ κατεσκευασμένον κἀν τοῖς ἐρύμασιν, ἃ πολλαῖς δαπάναις ἐξῳκοδόμησεν, τό τε Ἀλεξάνδρειον καὶ Ἡρώδειον καὶ τὴν Ὑρκανίαν."},{"number":14,"text":"ἦγεν δὲ καὶ εἰς τὴν πόλιν τῶν Ἱεροσολυμιτῶν ὑπαντῶντός τε τοῦ δήμου παντὸς ἐν ἑορτώδει στολῇ καὶ δεχομένου τὸν ἄνδρα σὺν εὐφημίαις. Ἀγρίππας δὲ τῷ θεῷ μὲν ἑκατόμβην κατέθυσεν, ἑστιᾷ δὲ τὸν δῆμον οὐδενὸς τῶν μεγίστων πλήθει λειπόμενον."},{"number":15,"text":"αὐτὸς δὲ ὅσον ἐπὶ τῷ καθʼ ἡδονὴν κἂν ἔτι πλείους ἐπιμείνας ἡμέρας διὰ τὸν καιρὸν ἠπείγετο· τὸν γὰρ πλοῦν ἐπιβαίνοντος τοῦ χειμῶνος οὐκ ἐνόμιζεν ἀσφαλῆ κομιζομένῳ πάλιν ἐξ ἀνάγκης εἰς τὴν Ἰωνίαν."},{"number":16,"text":"Ἐκεῖνος μὲν οὖν ἀπέπλει πολλαῖς αὐτὸν δωρεαῖς τετιμηκότος Ἡρώδου καὶ τῶν σὺν αὐτῷ τοὺς ἐπισημοτάτους. ὁ δὲ βασιλεὺς χειμάσας ἐν τοῖς οἰκείοις ἔαρος ἠπείγετο συντυχεῖν αὐτῷ τὴν εἰς Βόσπορον εἰδὼς στρατείαν προηγούμενον."},{"number":17,"text":"καὶ πλεύσας διὰ Ῥόδου καὶ Κῶ προσέσχεν, περὶ Λέσβον οἰόμενος ἐπικαταλήψεσθαι τὸν Ἀγρίππαν. ἐκεῖ δʼ αὐτὸν ἀπολαμβάνει πνεῦμα βόρειον εἶργον τὴν ἀναγωγὴν τῶν νεῶν."},{"number":18,"text":"ὁ δʼ ἐπιδιέτριβεν ἡμέρας πλείους ἐν τῇ Χίῳ καὶ πολλοὺς μὲν τῶν προσιόντων αὐτῷ δεξιούμενος ἀνελάμβανεν βασιλικαῖς δωρεαῖς, αὐτῆς δὲ τῆς πόλεως ἰδὼν πεπτωκυῖαν στοάν, ἣν ἐν τῷ Μιθριδατικῷ πολέμῳ καθαιρεθεῖσαν οὐχ ὥσπερ τὰ ἄλλα διὰ μέγεθος καὶ κάλλος ἀναστῆναι ῥᾴδιον ἦν,"},{"number":19,"text":"χρήματα δοὺς ὅσα μὴ μόνον ἐπαρκεῖν, ἀλλὰ καὶ περιττεύειν ἐδύνατο πρὸς τὴν συντέλειαν τοῦ κατασκευάσματος, ἐνετέλλετο μὴ περιορᾶν, ἀλλὰ θᾶττον ἐγείρειν ἀποκαθιστάντας τῇ πόλει τὸν ἴδιον κόσμον."},{"number":20,"text":"αὐτὸς δὲ λήξαντος τοῦ πνεύματος εἰς Μιτυλήνην κἀκεῖθεν εἰς Βυζάντιον παρακομισθείς, ὡς ἤκουσεν ἐντὸς Κυανέων ἤδη πεπλευκέναι τὸν Ἀγρίππαν, μετέσπευδεν ὡς ἐνῆν."},{"number":21,"text":"καὶ περὶ Σινώπην τὴν ἐν Πόντῳ καταλαβὼν ἀπροσδόκητος μὲν ὤφθη ταῖς ναυσὶ προσπλέων, ἄσμενος δὲ ἐφάνη πολλαί τε φιλοφρονήσεις ἦσαν, ἅτε καὶ μεγίστην πίστιν εἰληφέναι δοκοῦντος εὐνοίας καὶ φιλοστοργίας τῆς εἰς αὐτὸν Ἀγρίππου, τοσοῦτον μὲν πλοῦν ἀνύσαντος τοῦ βασιλέως, οὐκ ἀπολειφθέντος δὲ τῆς ἐκείνου χρείας, ἣν μετὰ τοῦ καταλιπεῖν ἀρχὴν καὶ διοίκησιν οἰκείων πραγμάτων προυργιαιτέραν ἔθετο."},{"number":22,"text":"πᾶν γοῦν ἦν αὐτῷ κατὰ τὴν στρατείαν Ἡρώδης, ἔν τε τοῖς πραγματικοῖς συναγωνιστὴς κἀν τοῖς κατὰ μέρος σύμβουλος, ἡδὺς δὲ κἀν ταῖς ἀνέσεσι καὶ μόνος ἁπάντων κοινωνὸς ὀχληρῶν μὲν διὰ τὴν εὔνοιαν, ἡδέων δὲ διὰ τὴν τιμήν."},{"number":23,"text":"ὡς δʼ αὐτοῖς κατείργαστο καὶ τὰ περὶ τὸν Πόντον, ὧν ἕνεκεν Ἀγρίππας ἐστάλη, τὴν ἀνακομιδὴν οὐκέτʼ ἐδόκει ποιεῖσθαι πλέουσιν, ἀλλὰ διαμειψάμενοι τήν τε Παφλαγονίαν καὶ Καππαδοκίαν κἀκεῖθεν ἐπὶ τῆς μεγάλης Φρυγίας ὁδεύσαντες εἰς Ἔφεσον ἀφίκοντο, πάλιν δὲ ἐξ Ἐφέσου διέπλευσαν εἰς Σάμον."},{"number":24,"text":"πολλαὶ μὲν οὖν καὶ κατὰ πόλιν ἑκάστην εὐεργεσίαι τῷ βασιλεῖ κατὰ τὰς χρείας τῶν ἐντυγχανόντων ἐγένοντο· καὶ γὰρ αὐτὸς ὅσα διὰ χρημάτων ἦν ηπίξεως οὐ παρέλειπεν ἐξ αὐτοῦ τὰς δαπάνας ποιούμενος καὶ τῶν παρὰ Ἀγρίππα τισὶν ἐπιζητουμένων μεσίτης ἦν καὶ διεπράττετο μηδενὸς ἀτυχῆσαι τοὺς δεομένους."},{"number":25,"text":"ὄντος δὲ κἀκείνου χρηστοῦ καὶ μεγαλοψύχου πρὸς τὸ παρέχειν ὅσα τοῖς ἠξιωκόσιν ὠφέλιμα ὄντα μηδένα τῶν ἄλλων ἐλύπει, πλεῖστον ἡ τοῦ βασιλέως ἐποίει ῥοπὴ προτρέπουσα πρὸς τὰς εὐεργεσίας οὐ βραδύνοντα τὸν Ἀγρίππαν."},{"number":26,"text":"Ἰλιεῦσι μέν γε αὐτὸν διήλλαξεν, διέλυσεν δὲ Χίοις τὰ πρὸς τοὺς Καίσαρος ἐπιτρόπους χρήματα καὶ τῶν εἰσφορῶν ἀπήλλαξεν, τοῖς δὲ ἄλλοις καθὸ δεηθεῖεν ἕκαστοι παρίστατο."},{"number":27,"text":"Τότε δὲ περὶ τὴν Ἰωνίαν αὐτῶν γενομένων πολὺ πλῆθος Ἰουδαίων, ὃ τὰς πόλεις ᾤκει, προσῄει καιροῦ καὶ παρρησίας ἐπειλημμένοι, καὶ τὰς ἐπηρείας ἔλεγον, ἃς ἐπηρεάζοντο μήτε νόμοις οἰκείοις ἐώμενοι χρῆσθαι δίκας τε ἀναγκαζόμενοι διδόναι κατʼ ἐπήρειαν τῶν εὐθυνόντων ἐν ἱεραῖς ἡμέραις,"},{"number":28,"text":"καὶ τῶν εἰς Ἱεροσόλυμα χρημάτων ἀνατιθεμένων ἀφαιροῖντο στρατειῶν καὶ λειτουργιῶν ἀναγκαζόμενοι κοινωνεῖν καὶ πρὸς ταῦτα δαπανᾶν τῶν ἱερῶν χρημάτων, ὧν ἀφείθησαν αἰεὶ Ῥωμαίων αὐτοῖς ἐπιτρεψάντων κατὰ τοὺς οἰκείους ζῆν νόμους."},{"number":29,"text":"τοιαῦτα καταβοώντων παρεστήσατο μὲν ὁ βασιλεὺς ἀκοῦσαι τὸν Ἀγρίππαν αὐτῶν δικαιολογουμένων, Νικόλαον δέ τινα τῶν αὐτοῦ φίλων ἔδωκεν εἰπεῖν ὑπὲρ αὐτῶν τὰ δίκαια."},{"number":30,"text":"τοῦ δὲ Ἀγρίππου Ῥωμαίων τε τοὺς ἐν τέλει καὶ βασιλέων καὶ δυναστῶν τοὺς παρόντας αὐτῷ συνέδρους ποιησαμένου καταστὰς ὁ Νικόλαος ὑπὲρ τῶν Ἰουδαίων ἔλεξεν·"},{"number":31,"text":"Ἅπασι μὲν, ὦ μέγιστε Ἀγρίππα, τοῖς ἐν χρείᾳ γεγενημένοις ἀνάγκη καταφεύγειν ἐπὶ τοὺς ἀφελέσθαι τὰς ἐπηρείας αὐτῶν δυνησομένους, τοῖς δὲ νῦν ἐντυγχάνουσιν καὶ παρρησία·"},{"number":32,"text":"τυχόντες γὰρ πρότερον ὑμῶν οἵους ηὔξαντο πολλάκις, τὸ μὴ τὰς χάριτας ἀφαιρεῖσθαι διʼ ὑμῶν αἰτοῦνται τῶν δεδωκότων, καὶ ταῦτα εἰληφότες μὲν αὐτὰς παρὰ τούτων, οἷς μόνοις διδόναι δύναμις, ἀφαιρούμενοι δʼ ὑπʼ οὐδενὸς κρείττονος, ἀλλʼ οὓς ἴσον ἔχειν αὐτοῖς ἀρχομένους ὁμοίως ὑμῶν ἴσασιν."},{"number":33,"text":"καίτοι γε εἴτε μεγάλων ἠξιώθησαν, ἔπαινός ἐστιν τῶν τετυχηκότων ὅτι τοσούτων παρέσχον αὑτοὺς ἀξίους, εἴτε μικρῶν, αἰσχρὸν μὴ καὶ ταῦτα βεβαιοῦν δεδωκότας."},{"number":34,"text":"οἵ γε μὴν ἐμποδὼν ὄντες καὶ πρὸς ἐπήρειαν χρώμενοι Ἰουδαίοις εὔδηλον ὡς ἄμφω ἀδικοῦσιν, τοὺς εἰληφότας, εἰ μὴ νομίζοιεν ἀγαθοὺς οἷς οἱ κρατοῦντες ἐμαρτύρησαν ἐν τῷ καὶ τοιαῦτα δεδωκέναι, καὶ τοὺς δεδωκότας, εἰ τὰς χάριτας αὐτῶν ἀβεβαίους ἀξιοῦσιν γενέσθαι."},{"number":35,"text":"εἰ δέ τις αὐτοὺς ἔροιτο δύο τούτων θάτερον ἐθέλοιεν ἂν ἀφαιρεθῆναι, τὸ ζῆν ἢ τὰ πάτρια ἔθη τὰς πομπὰς τὰς θυσίας τὰς ἑορτάς, ἃς τοῖς νομιζομένοις προσάγουσι θεοῖς, εὖ οἶδʼ, ὅτι πάντα μᾶλλον αἱρήσονται παθεῖν ἢ καταλῦσαί τι τῶν πατρίων·"},{"number":36,"text":"καὶ γὰρ τοὺς πολέμους οἱ πολλοὶ διὰ ταῦτα αἱροῦνται φυλαττόμενοι μὴ παραβαίνειν αὐτά, καὶ τὴν εὐδαιμονίαν, ἣν νῦν τὸ σύμπαν τῶν ἀνθρώπων γένος διʼ ὑμᾶς ἔχει, τούτῳ μετροῦμεν τῷ ἐξεῖναι κατὰ χώραν ἑκάστοις τὰ οἰκεῖα τιμῶσιν αὔξειν καὶ διαζῆν."},{"number":37,"text":"τοῦτο μὲν οὖν οὐκ ἂν αὐτοὶ παθεῖν ἑλόμενοι βιάζονται δρᾶν κατʼ ἄλλων ὥσπερ οὐχ ὁμοίως ἀσεβοῦντες, εἴτε τῶν οἰκείων εἰς θεοὺς ὁσίων ἀμελοῖεν, εἴτε τὰ οἰκεῖα τισὶν ἀνοσίως καταλύοιεν."},{"number":38,"text":"τόδʼ ἕτερον δʼ ἤδη σκοπήσομεν· ἔστι τις δῆμος ἢ πόλις ἢ κοινὸν ἔθνος ἀνθρώπων, οἷς οὐ μέγιστον ἀγαθῶν πέφυκε προστασία τῆς ὑμετέρας ἀρχῆς καὶ τὸ Ῥωμαϊκὸν κράτος; ἐθέλοι δʼ ἄν τις ἀκύρους τὰς ἐντεῦθεν εἶναι χάριτας;"},{"number":39,"text":"οὐδεὶς οὐδὲ μαινόμενος· οὐδὲ γὰρ εἰσὶν οἱ μὴ μετέχοντες αὐτῶν ἰδίᾳ καὶ κοινῇ. καὶ μὴν οἱ τινὰς ὧν ὑμεῖς ἔδοτε παραιρούμενοι βέβαιον οὐδʼ αὐτοῖς οὐδὲν ὧν διʼ ὑμᾶς ἔχουσιν ὑπολείπονται."},{"number":40,"text":"καίτοι τὰς μὲν τούτων χάριτας οὐδὲ μετρῆσαι δυνατόν ἐστιν· εἰ γὰρ ἐκλογίσαιντο τὴν πάλαι βασιλείαν καὶ τὴν νῦν ἀρχήν, πολλῶν ὄντων ὅσα πρὸς εὐδαιμονίαν αὐτοῖς ἐπέδωκεν, ἔτι κατὰ πάντων ἀρκεῖ τὸ μηκέτι δούλους ἀλλʼ ἐλευθέρους φαίνεσθαι."},{"number":41,"text":"τὰ δʼ ἡμέτερα καὶ λαμπρῶς πραττόντων οὐκ ἔστιν ἐπίφθονα· διʼ ὑμᾶς γὰρ καὶ μετὰ πάντων εὐτυχοῦμεν καὶ τούτου μόνου μετέχειν ἠξιώσαμεν, ἀκωλύτως τὴν πάτριον εὐσέβειαν διαφυλάττειν, ὃ καὶ καθʼ αὑτὸ δόξειεν οὐκ ἐπίφθονον καὶ πρὸς τῶν συγχωρούντων εἶναι·"},{"number":42,"text":"τὸ γὰρ θεῖον, εἰ χαίρει τιμώμενον, χαίρει τοῖς ἐπιτρέπουσι τιμᾶν, ἐθῶν τε τῶν ἡμετέρων ἀπάνθρωπον μὲν οὐδέν ἐστιν, εὐσεβῆ δὲ πάντα καὶ τῇ συνήθει δικαιοσύνῃ συγκαθωσιωμένα."},{"number":43,"text":"καὶ οὔτε ἀποκρυπτόμεθα τὰ παραγγέλματα, οἷς χρώμεθα πρὸς τὸν βίον ὑπομνήμασιν τῆς εὐσεβείας καὶ τῶν ἀνθρωπίνων ἐπιτηδευμάτων, τήν τε ἑβδόμην τῶν ἡμερῶν ἀνίεμεν τῇ μαθήσει τῶν ἡμετέρων ἐθῶν καὶ νόμου, μελέτην ὥσπερ ἄλλου τινὸς καὶ τούτων ἀξιοῦντες εἶναι διʼ ὧν οὐχ ἁμαρτησόμεθα."},{"number":44,"text":"καλὰ μὲν οὖν, ἐὰν ἐξετάζῃ τις καὶ καθʼ αὑτὰ τὰ ἔθη, παλαιὰ δʼ ἡμῖν, κἂν μή τισιν δοκῇ, ὥστʼ αὐτῶν καὶ τὸ τοῦ χρόνου τιμητὸν δυσαποδίδακτον εἶναι τοῖς ὁσίως παρειληφόσιν καὶ διαφυλάττουσιν."},{"number":45,"text":"τούτων ἡμᾶς ἀφαιροῦνται κατʼ ἐπήρειαν, χρήματα μὲν ἃ τῷ θεῷ συμφέρομεν ἐπώνυμα διαφθείροντες καὶ φανερῶς ἱεροσυλοῦντες, τέλη δʼ ἐπιτιθέντες κἀν ταῖς ἑορταῖς ἄγοντες ἐπὶ δικαστήρια καὶ πραγματείας ἄλλας, οὐ κατὰ χρείαν τῶν συναλλαγμάτων, ἀλλὰ κατʼ ἐπήρειαν τῆς θρησκείας, ἣν συνίσασιν ἡμῖν, μῖσος οὐ δίκαιον οὐδʼ αὐτεξούσιον αὐτοῖς πεπονθότες."},{"number":46,"text":"ἡ γὰρ ὑμετέρα κατὰ πάντων ἀρχὴ γενομένη μία τὴν μὲν εὔνοιαν ἐνεργὸν τὴν δὲ δύσνοιαν ἄνεργον ποιεῖ τοῖς τὸ τοιοῦτον ἀντʼ ἐκείνου προαιρουμένοις."},{"number":47,"text":"ταῦτʼ οὖν ἀξιοῦμεν, ὦ μέγιστε Ἀγρίππα, μὴ κακῶς πάσχειν μηδʼ ἐπηρεάζεσθαι μηδὲ κωλύεσθαι τοῖς ἔθεσι χρῆσθαι τοῖς ἡμετέροις μηδʼ ἀφαιρεῖσθαι τῶν ὄντων μηδʼ ἃ μὴ βιαζόμεθα τούτους ὑπὸ τούτων βιάζεσθαι· καὶ γὰρ οὐ δίκαια μόνον ἐστίν, ἀλλὰ καὶ ὑφʼ ὑμῶν δεδομένα πρότερον."},{"number":48,"text":"ἔτι καὶ δυναίμεθʼ ἂν πολλὰ δόγματα τῆς συγκλήτου καὶ τὰς ἐν τῷ Καπετωλίῳ κειμένας δέλτους ὑπὲρ τούτων ἀναγινώσκειν, ἃ δῆλον μὲν ὡς μετὰ πεῖραν τῆς ἡμετέρας εἰς ὑμᾶς πίστεως ἐδόθη, κύρια δὲ κἂν εἰ μηδενὸς ὕπαρξιν ἐχαρίσασθε."},{"number":49,"text":"σχεδὸν γὰρ οὐ μόνοις ἡμῖν ἀλλὰ πᾶσιν ἀνθρώποις τὰ μὲν ὄντα φυλάξαντες, μείζω δὲ τῶν ἐλπισθέντων προσθέντες εὐεργετεῖτε τῷ κρατεῖν, καὶ δύναιτʼ ἄν τις ἐπεξιὼν τὰς ἑκάστων εὐτυχίας, ἃς διʼ ὑμῶν ἔχουσιν, ἀπερίληπτον ποιῆσαι τὸν λόγον."},{"number":50,"text":"ἵνα μέντοι καὶ δικαίως ἁπάντων αὐτῶν τυγχάνοντας ἑαυτοὺς ἐπιδείξωμεν, ἀρκεῖ πρὸς παρρησίαν ἡμῖν τὰ πρότερον σιωπήσασιν τὸν βασιλεύοντα νῦν ἡμῶν καὶ σοὶ παρακαθεζόμενον εἰπεῖν."},{"number":51,"text":"ᾧ ποία μὲν εὔνοια πρὸς τὸν ὑμέτερον οἶκον παραλέλειπται; ποία δὲ πίστις ἐνδεής ἐστιν; τίς δὲ οὐ νενόηται τιμή; ποία δὲ χρεία μὴ εἰς πρῶτον ὁρᾷ; τί δὴ κωλύει καὶ τὰς ἡμετέρας χάριτας τῶν εἰς τοσούτων εὐεργεσιῶν ἀριθμὸν εἶναι;"},{"number":52,"text":"καλὸν δʼ ἴσως μηδὲ τὴν τοῦ πατρὸς Ἀντιπάτρου παραλιπεῖν ἀνδραγαθίαν ἀμνημόνευτον, ὃς εἰς Αἴγυπτον εἰσβεβληκότος Καίσαρος δισχιλίοις ὁπλίταις βοηθήσας οὔτʼ ἐν τοῖς κατὰ γῆν ἀγῶσιν οὔθʼ ὅτε νεῶν ἔδει δεύτερος ἐξητάζετο."},{"number":53,"text":"καὶ τί δεῖ λέγειν, ὅσην ἐκεῖνοι παρέσχον ῥοπὴν τῷ τότε καιρῷ καὶ πόσων καὶ τίνων δωρεῶν ὑπὸ Καίσαρος ἠξιώθησαν καθʼ ἕνα, δέον ἀναμνῆσαι τῶν ἐπιστολῶν, ἃς ἔγραψεν τότε Καῖσαρ τῇ συγκλήτῳ, καὶ ὡς δημοσίᾳ τιμὰς καὶ πολιτείαν ἔλαβεν Ἀντίπατρος;"},{"number":54,"text":"ἀρκέσει γὰρ ταῦτα τὰ τεκμήρια τοῦ καὶ τὰς χάριτας ἡμᾶς κατʼ ἀξίαν ἔχειν καὶ παρὰ σοῦ τὸ βέβαιον αὐτῶν αἰτεῖν, παρʼ οὗ καὶ μὴ πρότερον δοθείσας ἦν ἐλπίσαι τὴν τοῦ βασιλέως πρὸς ὑμᾶς διάθεσιν καὶ τὴν ὑμετέραν πρὸς αὐτὸν ὁρῶσιν."},{"number":55,"text":"ἀπαγγέλλεται δʼ ἡμῖν ὑπὸ τῶν ἐκεῖ Ἰουδαίων, ὡς μὲν ἐπέβης τῆς χώρας εὐμενής, ὡς δὲ ἀπέδωκας τῷ θεῷ τέλεια θύματα τιμῶν αὐτὸν ἐπὶ τελείαις εὐχαῖς, ὡς δὲ τὸν δῆμον εἱστίασας καὶ τὰ παρʼ ἐκείνου ξένια προσήκω."},{"number":56,"text":"ταῦτα γὰρ πάντα καὶ ἔθνει καὶ πόλει πρὸς ἄνδρα τοσούτων ἐπιστατοῦντα πραγμάτων δεξιώματα καὶ σύμβολα φιλίας χρὴ δοκεῖν, ἣν ἀπέδωκας τῷ Ἰουδαίων ἔθνει τῆς Ἡρώδου προξενούσης αὐτὴν ἑστίας."},{"number":57,"text":"τούτων ὑπομιμνήσκοντές σε καὶ αὐτοῦ τοῦ παρόντος καὶ συγκαθεζομένου βασιλέως ἠξιώκαμεν περιττὸν οὐδέν, ἃ δʼ αὐτοὶ δεδώκατε ταῦθʼ ὑπʼ ἄλλων μὴ περιιδεῖν ἀφαιρουμένους."},{"number":58,"text":"Τοιαῦτα μὲν τοῦ Νικολάου διελθόντος ἐγένετο οὐδεμία τῶν Ἑλλήνων ἀντικατάστασις· οὐδὲ γὰρ ὡς ἐν δικαστηρίῳ περὶ τῶν προκειμένων διελάμβανον, ἀλλʼ ἦν ἔντευξις ὧν ἐβιάζοντο."},{"number":59,"text":"κἀκείνων ἀπολογία μὲν οὐδεμία τοῦ μὴ ταῦτα ποιεῖν, πρόφασις δέ, ὡς τὴν χώραν αὐτῶν νεμόμενοι πάντα νῦν ἀδικοῖεν. οἱ δὲ ἐγγενεῖς τε αὑτοὺς ἐδείκνυσαν κἀν τῷ τὰ οἰκεῖα τιμᾶν μηδὲν λυποῦντες οἰκεῖν."},{"number":60,"text":"συνιδὼν οὖν Ἀγρίππας βιαζομένους ἀπεκρίνατο ταῦτα· διὰ μὲν τὴν Ἡρώδου πρὸς αὐτὸν εὔνοιάν τε καὶ φιλίαν ἕτοιμος εἶναι πᾶν ὁτιοῦν χαρίζεσθαι Ἰουδαίοις, ἃ δὲ ἀξιοῦσιν καὶ καθʼ αὑτὰ δίκαια δοκεῖν· ὥστʼ, εἰ μὲν ἐδέοντο καὶ πλειόνων, οὐκ ἂν ὀκνῆσαι τά γε μὴ λυποῦντα τὴν Ῥωμαίων ἀρχὴν παρασχεῖν. ἐπεὶ δὲ ἃ καὶ πρότερον εἰλήφασιν ἄκυρα μὴ γενέσθαι, βεβαιοῦν αὐτοῖς ἀνεπηρεάστοις ἐν τοῖς οἰκείοις διατελεῖν ἔθεσιν."},{"number":61,"text":"τοιαῦτα εἰπὼν διέλυε τὸν σύλλογον. Ἡρώδης δὲ προσεστὼς κατησπάζετο καὶ τῆς εἰς αὐτὸν διαθέσεως ὡμολόγει χάριν. ὁ δὲ καὶ εἰς ταῦτα φιλοφρονούμενος ἴσον αὑτὸν παρεῖχεν ἀντεμπλεκόμενος καὶ κατασπαζόμενος."},{"number":62,"text":"καὶ τότε μὲν ἀνεχώρησεν· ἀπὸ δὲ Σάμου πλεῖν ὁ βασιλεὺς ἐπʼ οἴκου διέγνω καὶ τὸν Ἀγρίππαν παραιτησάμενος ἀνήχθη, κατάγεται δʼ εἰς Καισάρειαν οὐ πολλαῖς ὕστερον ἡμέραις πνευμάτων ἐπιτηδείων τυχών. κἀκεῖθεν ἐλθὼν εἰς Ἱεροσόλυμα συνήγαγεν ἐκκλησίαν πάνδημον· ἦν δὲ πολὺς κἀκ τῆς χώρας ὄχλος."},{"number":63,"text":"ὁ δὲ παρελθὼν ἀπολογισμόν τε τῆς ὅλης ἐκδημίας ἐποιήσατο καὶ τὰ περὶ τοὺς Ἰουδαίους, ὅσοι κατὰ τὴν Ἀσίαν ἦσαν, ὡς διʼ αὐτὸν ἀνεπηρεάστως εἰς τὸ λοιπὸν ἕξουσιν διηγήσατο."},{"number":64,"text":"τό τε σύμπαν ἐπὶ ταῖς εὐτυχίαις καὶ τῇ διοικήσει τῆς ἀρχῆς ὡς οὐδενὸς παραλείποιτο τῶν ἐκείνοις συμφερόντων, ἀγαλλόμενος τὸ τέταρτον τῶν φόρων ἀφίησιν αὐτοῖς τοῦ παρεληλυθότος ἔτους."},{"number":65,"text":"οἱ δὲ καὶ τῷ λόγῳ καὶ τῇ χάριτι δεδημαγωγημένοι μετὰ πλείστης χαρᾶς ἀπῄεσαν πολλὰ ἀγαθὰ συνευχόμενοι τῷ βασιλεῖ."}],"3":[{"number":66,"text":"Προύβαινε δʼ ἀεὶ τὰ κατὰ τὴν στάσιν τῆς οἰκίας καὶ χαλεπωτέραν ἐλάμβανε τὴν ἐπίδοσιν, ἀντιμεταλαβούσης μὲν ὥσπερ ἐκ κληρονομίας τὸ κατὰ τῶν νεανίσκων μῖσος τῆς Σαλώμης καὶ πᾶν ὅσον εὐδοκιμήκει κατὰ τῆς μητρὸς αὐτῶν εἰς ἀπόνοιαν καὶ θράσος λαμβανούσης μηδένα τῶν ἐξ ἐκείνης καταλιπεῖν, ὃς δυνήσεται τιμωρῆσαι τῷ θανάτῳ τῆς διʼ αὐτὴν ἀνῃρημένης,"},{"number":67,"text":"ἐχόντων δέ τι καὶ τῶν νεανίσκων θρασὺ καὶ δύσνουν εἰς τὸν γεγεννηκότα μνήμῃ τε τῆς μητρὸς οἷα πάθοι παρὰ τὴν ἀξίαν καὶ τῇ τοῦ κρατεῖν ἐπιθυμίᾳ."},{"number":68,"text":"πάλιν τε τὸ κακὸν ὅμοιον ἐγεγόνει τοῖς πρώτοις, βλασφημίαι μὲν ἐξ ἐκείνων εἴς τε τὴν Σαλώμην καὶ τὸν Φερώραν, κακοήθειαι δὲ τούτων εἰς τὰ μειράκια καὶ μετὰ πραγματείας ἐπιβουλή·"},{"number":69,"text":"τὸ μὲν γὰρ μῖσος ἴσον ἦν ἐξ ἀλλήλων, ὁ δὲ τρόπος τοῦ μισεῖν οὐχ ὅμοιος· ἀλλʼ οἱ μὲν ἐν τῷ φανερῷ λοιδορηθῆναι καὶ προσονειδίσαι προπετεῖς εὐγενὲς ὑπὸ τῆς ἀπειρίας οἰόμενοι τὸ τῆς ὀργῆς ἀνυπόστολον, οἱ δʼ οὐ τὸν αὐτὸν τρόπον, ἀλλὰ πραγματικῶς καὶ κακοήθως ἐχρῶντο ταῖς διαβολαῖς, προέλκοντες ἀεὶ τὰ μειράκια καὶ τὸ θρασὺ καταλογιζόμενοι βίαιον ἔσεσθαι πρὸς τὸν γεγεννηκότα."},{"number":70,"text":"τὸ γὰρ οὐκ αἰδεῖσθαι ταῖς τῆς μητρὸς ἁμαρτίαις οὐδʼ οἴεσθαι δίκαια παθεῖν ἐκείνην ἄσχετον εἶναι πρὸς τὸ μὴ τὸν αἴτιον δοκοῦντα τιμωρήσεσθαι καὶ διʼ αὐτοχειρίας."},{"number":71,"text":"τέλος οὖν ἀνεπλήσθη πᾶσα ἡ πόλις τῶν τοιούτων λόγων καὶ καθάπερ ἐν τοῖς ἀγωνίσμασιν ἠλεεῖτο μὲν ἡ τῶν μειρακίων ἀπειρία, κατίσχυεν δὲ ἡ τῆς Σαλώμης ἐπιμέλεια καὶ παρʼ αὐτῶν ἐκείνων τὰς ἀφορμὰς τοῦ μὴ ψευδῆ λέγειν ἐλάμβανεν."},{"number":72,"text":"οἱ γὰρ οὕτως ἀχθόμενοι τῷ θανάτῳ τῆς μητρός, ἐπειδὴ κἀκείνην καὶ σφᾶς αὐτοὺς κακῶς ἔλεγεν, ἐφιλονείκουν ἐλεεινὴν μέν, ὥσπερ ἦν, ἀποφαίνειν τὴν καταστροφὴν τῆς μητρός, ἐλεεινοὺς δὲ αὐτούς, οἳ τοῖς ἐκείνης φονεῦσιν ἀναγκάζονται συζῆν καὶ τῶν αὐτῶν μεταλαμβάνειν."},{"number":73,"text":"Ταῦτα προῄει μειζόνως καιρὸν ἐχούσης τῆς στάσεως ἐν ἀποδημίᾳ τοῦ βασιλέως. ὡς δʼ ἐπανῆλθεν Ἡρώδης καὶ τῷ πλήθει διελέξατο, καθὼς προειρήκαμεν, προσέπιπτον εὐθὺς οἱ λόγοι παρά τε τοῦ Φερώρα καὶ τῆς Σαλώμης μέγαν αὐτῷ τὸν κίνδυνον εἶναι τὸν παρὰ τῶν νεανίσκων ἀνάφανδα διαπειλουμένων, ὡς οὐκ ἀνέξονται μὴ τισάμενοι τῆς μητρὸς τὸν φόνον."},{"number":74,"text":"προσετίθεσαν δʼ ἔτι καὶ ὡς ταῖς παρʼ Ἀρχελάου τοῦ Καππάδοκος ἐλπίσιν ἐπανέχοιεν, ὡς διʼ ἐκείνου πρός τε Καίσαρα ἀφιξόμενοι καὶ κατηγορήσοντες τοῦ πατρός."},{"number":75,"text":"Ἡρώδης δὲ ἐτετάρακτο μὲν εὐθὺς ἀκούσας τοιούτων, ἐξεπέπληκτο δὲ μᾶλλον, ὅτι καὶ τῶν ἄλλων τινὲς ἀπήγγελλον, ἀνέκαμπτε τῇ συμφορᾷ τά τε πρῶτα καταλογιζόμενος ὡς οὔτε τῶν φιλτάτων οὔτε τῆς στεργομένης αὐτῷ γυναικὸς ὤνατο διὰ τὰς ἐγγινομένας ταραχὰς κατὰ τὴν οἰκίαν, τό τε μᾶλλον τοῦ προσπεπτωκότος ἤδη βαρὺ καὶ μεῖζον ἐκείνων ὑπολαμβάνων ἐν συγχύσει τῆς ψυχῆς ἦν."},{"number":76,"text":"τῷ γὰρ ὄντι πλεῖστα μὲν καὶ παρʼ ἐλπίδας τῶν ἔξωθεν εἰς εὐτυχίαν αὐτῷ τὸ δαιμόνιον προσετίθει, μέγιστα δὲ τῶν οἴκοι καὶ μηδὲ προσδοκώμενα δυστυχεῖν αὐτῷ συνέβαινεν, ἑκατέρου προϊόντος ὡς οὐκ ἄν τις ᾠήθη καὶ παρέχοντος ἀμφήριστον τὴν ὑπερβολήν, εἰ"},{"number":77,"text":"δέον τὴν τοσαύτην εὐτυχίαν τῶν ἔξωθεν πραγμάτων ἀλλάξασθαι τῶν οἴκοι κακῶν, ἢ τοιοῦτο μέγεθος τῶν περὶ τοὺς οἰκείους συμφορῶν διαφυγεῖν ἐν τῷ μηδὲ τὰ τῆς βασιλείας θαυμαζόμενα κεκτῆσθαι."},{"number":78,"text":"Ταρασσόμενος δὲ καὶ διακείμενος τὸν τρόπον τοῦτον ἐπὶ καθαιρέσει τῶν μειρακίων ἕτερον αὐτῷ γενόμενον ἰδιωτεύοντι παῖδα προσήγετο καὶ τοῦτον ἐδόκει τιμᾶν, ἐκαλεῖτο δὲ Ἀντίπατρος, οὐχ ὥσπερ ἐν ὑστέρῳ καὶ τελέως ἡττηθεὶς αὐτοῦ καὶ πάντʼ εἰς ἐκεῖνον ἀναφέρων,"},{"number":79,"text":"οἰόμενος δὲ παραιρήσεσθαι τοῦ θράσους τοὺς ἐκ Μαριάμμης καὶ μᾶλλον εἰς νουθεσίαν τὴν ἐκείνων οἰκονομῶν αὐτό. τὸ γὰρ αὔθαδες οὐκ ἂν εἴη παρʼ αὐτοῖς, εἰ τοῦτο πεισθεῖεν, ὅτι μὴ μόνοις μηδʼ ἐξ ἀνάγκης ἡ διαδοχὴ τῆς βασιλείας ὀφείλεται."},{"number":80,"text":"διὸ καὶ καθάπερ ἔφεδρόν τινα τὸν Ἀντίπατρον εἰσῆγεν οἰόμενος ὀρθῶς προνοεῖν καὶ κατασταλέντων τῶν μειρακίων ἐξεῖναι εὐκαίρως χρῆσθαι βελτίοσιν."},{"number":81,"text":"τὸ δʼ οὐχ ὥσπερ ἐνόησεν ἀπέβη· τοῖς τε γὰρ παισὶν οὐ μετρίως ἐδόκει κεχρῆσθαι τῇ πρὸς αὐτοὺς ἐπηρείᾳ, καὶ δεινὸς ὢν τὸν τρόπον Ἀντίπατρος, ἐπειδὴ παρρησίας τινὸς τῆς οὐ πρότερον οὔσης ἐλπίδος ἀντεποιήσατο, μίαν ἔσχεν ὑπόθεσιν κακοῦ τοὺς ἀδελφοὺς μὴ παραχωρεῖν τῶν πρωτείων, ἀλλʼ ἔχεσθαι τοῦ πατρός, ἤδη μὲν ἠλλοτριωμένου ταῖς διαβολαῖς, εὐμεταχειρίστου δʼ ὄντος εἰς ὅπερ ἐσπουδάκει, πολὺ χαλεπώτερον ἀεὶ γενέσθαι τοῖς διαβεβλημένοις."},{"number":82,"text":"ἦσαν οὖν οὐ παρʼ αὐτοῦ μόνου οἱ λόγοι φυλαττομένου διʼ αὑτοῦ δόξαι τὰ τοιαῦτα καταμηνύειν, ἀλλὰ μᾶλλον ἐχρῆτο συνεργοῖς τοῖς ἀνυπόπτοις καὶ διὰ τὴν εὔνοιαν τὴν πρὸς τὸν βασιλέα πιστευθησομένοις αὐτὸ ποιεῖν."},{"number":83,"text":"ἤδη δὲ πλείους ἐγεγόνεισαν οἱ κἀκεῖνον ἐφʼ οἷς ἠλπίκει θεραπεύοντες καὶ τὸν Ἡρώδην ἐκ τοῦ δοκεῖν κατʼ εὔνοιαν τὰ τοιαῦτα λέγειν ὑπαγόμενοι. καὶ τούτων πολυπροσώπως καὶ πιστῶς ἀλλήλοις συναγωνιζομένων ἔτι καὶ μᾶλλον αἱ παρὰ τῶν μειρακίων ἀφορμαὶ προσεγίνοντο·"},{"number":84,"text":"καὶ γὰρ καὶ δάκρυα πολλάκις ἦν κατʼ ἐπήρειαν ὧν ἠτιμάζοντο καὶ τῆς μητρὸς ἀνάκλησις καὶ τὸν πατέρα φανερῶς ἤδη πρὸς τοὺς φίλους οὐ δίκαιον ἐλέγχειν ἐπετήδευον, ἅπερ ἅπαντα κακοήθως ὑπὸ τῶν περὶ τὸν Ἀντίπατρον καιροφυλακούμενα καὶ μειζόνως πρὸς τὸν Ἡρώδην ἐξαγγελλόμενα προύβαινεν οὐ μικρὰν ἀπεργαζόμενα τὴν τῆς οἰκίας στάσιν."},{"number":85,"text":"ἀχθόμενος γὰρ ὁ βασιλεὺς ταῖς διαβολαῖς καὶ ταπεινῶσαι βουλόμενος τοὺς ἐκ τῆς Μαριάμμης μείζονα ἀεὶ πρὸς τιμὴν Ἀντιπάτρῳ παρεῖχεν, καὶ τέλος ἡττηθεὶς ἐπεισήγαγε μὲν τὴν ἐκείνου μητέρα, Καίσαρι δὲ πολλάκις γράφων ὑπὲρ αὐτοῦ καὶ ἰδίᾳ συνίστη σπουδαιότερον."},{"number":86,"text":"Ἀγρίππου γε μὴν ἀνιόντος εἰς τὴν Ῥώμην μετὰ τὴν διοίκησιν τῶν ἐπὶ τῆς Ἀσίας δεκαετῆ γεγενημένην, πλεύσας ἀπὸ τῆς Ἰουδαίας καὶ συντυγχάνων μόνον τε τὸν Ἀντίπατρον ἐπήγετο καὶ παρέδωκεν εἰς Ῥώμην ἀνάγειν μετὰ πολλῶν δώρων Καίσαρι φίλον ἐσόμενον, ὥστε ἤδη πάντα δοκεῖν ἐπʼ ἐκείνῳ καὶ παρεῶσθαι παντάπασιν ἐκ τῆς ἀρχῆς τὰ μειράκια."}],"4":[{"number":87,"text":"Πρὸς μὲν οὖν τιμὴν καὶ τὸ πρῶτον εἶναι δοκεῖν Ἀντιπάτρῳ προυχώρει τὰ κατὰ τὴν ἀποδημίαν· καὶ γὰρ ἐν τῇ Ῥώμῃ πᾶσιν ἐπεσταλκότος Ἡρώδου τοῖς φίλοις διάσημος ἦν·"},{"number":88,"text":"ἤχθετο δὲ τῷ μὴ παρεῖναι μηδὲ ἔχειν ἐξ εὐκαίρου διαβάλλειν ἀεὶ τοὺς ἀδελφούς, καὶ μᾶλλον ἐδεδοίκει μεταβολὴν τοῦ πατρός, εἴ τι καὶ καθʼ αὑτὸν ἀξιώσει ἐπιεικέστερον εἰς τοὺς ἐκ τῆς Μαριάμμης φρονεῖν."},{"number":89,"text":"ταῦτα δὲ διʼ ἐννοίας ἔχων οὐκ ἀφίστατο τῆς ἑαυτοῦ προαιρέσεως, ἀλλὰ κἀκεῖθεν, ὅτε ἀνιάσειν τι καὶ παροξυνεῖν ἤλπιζεν τὸν πατέρα κατὰ τῶν ἀδελφῶν, συνεχῶς ἐπέστελλεν, πρόφασιν μὲν ὡς ὑπεραγωνιῶν αὐτοῦ, τὸ δὲ ἀληθὲς ἀφʼ ἧς εἶχεν ἐν φύσει κακοηθείας τὴν ἐλπίδα μεγάλην καὶ καθʼ ἑαυτὴν οὖσαν ἐμπορευόμενος,"},{"number":90,"text":"ἕως εἰς τοῦτο προήγαγεν τὸν Ἡρώδην ὀργῆς καὶ δυσφημίας, ὡς ἤδη μὲν ἔχων δυσμενῶς τοῖς μειρακίοις, ἐν δὲ κατοκνεῖν εἰς τοιοῦτον ἐμβῆναι πάθος, ὡς μήτʼ ἀμελῶν μήτʼ ἐκ προπετείας ἁμαρτάνοι, κρεῖττον ἡγήσατο πλεύσας εἰς Ῥώμην ἐκεῖ τῶν παίδων κατηγορεῖν παρὰ Καίσαρι, καὶ μηδὲν αὑτῷ τοιοῦτον ἐπιτρέπειν, ὃ καὶ διὰ μέγεθος τῆς ἀσεβείας ὕποπτον ἦν."},{"number":91,"text":"ὡς δὲ ἀνῆλθεν εἰς τὴν Ῥώμην, ἐγένετο μὲν μέχρι τῆς Ἀκυληίας πόλεως Καίσαρι συντυχεῖν ἐπειγόμενος, ἐλθὼν δʼ εἰς λόγους καὶ καιρὸν αἰτησάμενος ἐπὶ μεγάλοις οἷς ἐδόκει δυστυχεῖν παρεστήσατο μὲν τοὺς παῖδας, ᾐτιᾶτο δὲ τῆς ἀπονοίας καὶ τῆς ἐπιχειρήσεως,"},{"number":92,"text":"ὡς ἐχθρῶς ἔχουσιν ἅπαντα τρόπον ἐσπουδακότες μισεῖν τὸν ἑαυτῶν πατέρα μεταχειρίσασθαι καὶ τὴν βασιλείαν ὠμοτάτῳ τρόπῳ παραλαβεῖν· ὁ δʼ οὐδὲ θνήσκων ἐξ ἀνάγκης μᾶλλον ἢ κρίσει παραδοῦναι τῷ διαμείναντι πρὸς αὐτὸν εὐσεβεστέρῳ παρὰ Καίσαρος ἐξουσίαν ἔχοι."},{"number":93,"text":"τοῖς δʼ οὐχ ὑπὲρ τῆς ἀρχῆς τὸ πλέον, ἀλλʼ εἰ καὶ ταύτης στεροῖντο καὶ τοῦ ζῆν ἐλάττων λόγος, εἰ μόνον ἀποκτεῖναι τὸν πατέρα δυνηθεῖεν· οὕτως ἄγριόν τι καὶ μιαρὸν ἐντετηκέναι ταῖς ψυχαῖς αὐτῶν μῖσος. καὶ ταύτην τὴν ἀτυχίαν αὐτὸς ἐκ μακροῦ φέρων ἀναγκασθῆναι νῦν ἐξηγεῖσθαι Καίσαρι καὶ μιαίνειν αὐτοῦ τὰς ἀκοὰς τοιούτοις λόγοις."},{"number":94,"text":"καίτοι τί μὲν εἴησαν παθόντες ἐξ αὐτοῦ δυσχερές; ἐπὶ τίνι δὲ μέμφονται βαρὺν ὄντα; πῶς δʼ οἷόν τε καὶ δίκαιον ἣν αὐτὸς ἐκτήσατο πολλοῖς πόνοις καὶ κινδύνοις ἀρχήν, ταύτης οὐκ ἐᾶν κύριον εἶναι κρατεῖν τε καὶ διδόναι τῷ κατʼ ἀξίαν;"},{"number":95,"text":"ὡς τοῦτό γε μετὰ τῶν ἄλλων ἆθλον εὐσεβείας ἐκτίθεται τῷ μέλλοντι πρὸς τὸν ποτὲ γενήσεσθαι τοιούτῳ τὴν ἐπιμέλειαν, ἅτε καὶ τῆς ἀμοιβῆς τοσῆσδε οὔσης ἐπιτυγχάνειν."},{"number":96,"text":"ὅτι δὲ μηδὲ εὐσεβὲς αὐτοῖς ὑπὲρ τούτου πολυπραγμονεῖν, εὔδηλον· ὁ γὰρ ἀεί τι περὶ τῆς βασιλείας ἐνθυμούμενος συγκαταλογίζεται τὸν θάνατον τοῦ γεγεννηκότος, μεθʼ ὃν ἄλλως οὐκ ἔστιν τὴν ἀρχὴν παραλαβεῖν."},{"number":97,"text":"αὐτὸς δʼ ὅσα βασιλευομένοις καὶ βασιλέως παισὶν οὐχ ὑστέρησεν μέχρι νῦν ἀποδιδούς, οὐ κόσμον, οὐχ ὑπηρεσίαν, οὐ τρυφήν, ἀλλὰ καὶ γάμους τοὺς ἐπισημοτάτους παρεσχῆσθαι, τῷ μὲν ἐκ τῆς ἀδελφῆς, Ἀλεξάνδρῳ δὲ τὴν Ἀρχελάου τοῦ βασιλέως θυγατέρα συνοικίσας,"},{"number":98,"text":"τὸ δὲ μέγιστον οὐδʼ ἐπὶ τοιούτοις ἣν εἶχεν ἐξουσίαν ταύτῃ κατʼ αὐτῶν χρησάμενος ἀγαγεῖν ἐπὶ τὸν κοινὸν εὐεργέτην Καίσαρα, καὶ παρελόμενον αὑτοῦ πᾶν, ὅσον ἢ πατὴρ ἀσεβούμενος ἢ βασιλεὺς ἐπιβουλευόμενος δύναται, κρίσεως ἰσοτιμίᾳ παρεστακέναι·"},{"number":99,"text":"δεήσει μέντοι μὴ παντάπασιν αὐτὸν ἀτιμώρητον γενέσθαι μηδʼ ἐν τοῖς μεγίστοις φόβοις καταζῆν, οὐδʼ ἐκείνοις λυσιτελοῦντος ἐφʼ οἷς ἐνεθυμήθησαν ὁρᾶν τὸν ἥλιον, εἰ νῦν διαφύγοιεν, ἔργῳ μέγιστα τῶν ἀνθρωπείων καὶ δράσαντας καὶ πεισομένους."},{"number":100,"text":"Ταῦτα μὲν Ἡρώδης ἐμπαθῶς ᾐτιάσατο παρὰ Καίσαρι τοὺς αὐτοῦ παῖδας. τῶν δὲ νεανίσκων ἤδη μὲν καὶ λέγοντος δάκρυα καὶ σύγχυσις ἦν· μᾶλλον δʼ ἐπεὶ κατέπαυσεν Ἡρώδης τὸν λόγον τῷ μὲν ἔξω τῆς τοιαύτης ἀσεβείας γενέσθαι τὸν λόγον πιστὸν εἶχον ἐν τῷ συνειδότι,"},{"number":101,"text":"τὸ δʼ ἐκ τοῦ πατρὸς ἐπιφέρεσθαι τὰς διαβολὰς δυσαπολόγητον ὥσπερ ἦν ᾔδεσαν, οὐκ εὐσχημονοῦντος οὐδὲ τοῦ κατὰ παρρησίαν λόγου πρὸς τὸν καιρόν, εἰ μέλλοιεν ἐκ βίας ἀεὶ καὶ κατὰ σπουδὴν ἐλέγχειν πεπλανημένον."},{"number":102,"text":"ἦν οὖν ἀπορία τοῦ δύνασθαι λέγειν καὶ δάκρυα καὶ τέλος οἰμωγὴ συμπαθεστέρα, δεδοικότων μέν, εἰ δόξουσιν ἐκ τοῦ συνειδότος ἠπορῆσθαι, ῥᾳδίαν δʼ οὐχ εὑρισκομένων τὴν ἀπολογίαν ὑπό τε νεότητος καὶ ταραχῆς, ἣν ἐπεπόνθεισαν."},{"number":103,"text":"οὐ μὴν ὅ γε Καῖσαρ ἐπιβλέπων αὐτοὺς ὡς εἶχον ἀσύνετον ἐποιεῖτο τὸ μὴ κατὰ συνείδησιν ἀτοπωτέραν, ἀλλʼ ἐξ ἀπειρίας καὶ μετριότητος ὀκνεῖν, ἐλεεινοί τʼ ἐγεγόνεισαν τοῖς παροῦσιν ἰδίᾳ καὶ τὸν πατέρα διεκίνησαν ἀληθινῷ τῷ πάθει συνεχόμενον."},{"number":104,"text":"Ἐπεὶ δὲ συνεῖδον εὐμένειάν τινα καὶ παρʼ ἐκείνου καὶ παρὰ τοῦ Καίσαρος, καὶ τῶν ἄλλων δὲ ἕκαστον τοὺς μὲν συνδακρύοντας, ἅπαντας δὲ συναλγοῦντας, ἅτερος αὐτῶν Ἀλέξανδρος ἐπικαλεσάμενος αὐτὸν ἐπεχείρει διαλύειν τὰς αἰτίας καί,"},{"number":105,"text":"πάτερ, εἶπεν, ἡ μὲν σὴ πρὸς ἡμᾶς εὔνοια δήλη καὶ παρʼ αὐτὴν τὴν κρίσιν· οὐκ ἂν γάρ, εἴ τι δυσχερὲς ἐνενόεις ἐφʼ ἡμῖν, ἐπὶ τὸν πάντας σώζοντα προήγαγες·"},{"number":106,"text":"καὶ γὰρ παρούσης μὲν ἐξουσίας ὡς βασιλεῖ, παρούσης δὲ ὡς πατρὶ τοὺς ἀδικοῦντας ἐπεξιέναι, τὸ εἰς Ῥώμην ἄγειν καὶ τοῦτον ποιεῖσθαι μάρτυρα σώζοντος ἦν· οὐδεὶς γὰρ ἀποκτεῖναί τινα προαιρούμενος εἰς ἱερὰ καὶ ναοὺς ἄγει."},{"number":107,"text":"τὸ δʼ ἡμέτερον ἤδη χεῖρον· οὐ γὰρ ἂν ὑπομείναιμεν ἔτι ζῆν, εἰ τοιοῦτον ἠδικηκέναι πατέρα πεπιστεύμεθα. καὶ μήποτε τοῦτʼ ἐκείνου χεῖρον ἀντὶ τοῦ τεθνάναι μηδὲν ἀδικοῦντας τὸ ζῆν ἀδικεῖν ὑποπτευομένους."},{"number":108,"text":"εἰ μὲν οὖν εὕροι λόγον τῆς ἀληθείας ἡ παρρησία, μακάριον καὶ σὲ πεῖσαι καὶ τὸν κίνδυνον διαφυγεῖν, εἰ δʼ οὕτως ἡ διαβολὴ κρατεῖ, περιττὸς ἡμῖν ὁ νῦν ἥλιος, ὃν τί δεῖ βλέπειν μετὰ τῆς ὑποψίας;"},{"number":109,"text":"τὸ μὲν οὖν φάναι βασιλείας ἐπιθυμεῖν, εὔκαιρος εἰς νέους αἰτία, καὶ τὸ προστιθέναι τὴν τῆς ἀθλίας μητρός, ἱκανὸν ἐκ τῆς πρώτης τὴν νῦν ἀτυχίαν ἐξεργάζεσθαι."},{"number":110,"text":"βλέψον δέ, εἰ μὴ κοινὰ ταῦτα καὶ πᾶσιν ὁμοίως λέγεσθαι δυνησόμενα· κωλύσει γὰρ οὐδέν, τῷ βασιλεύοντι παῖδες εἰ εἰσὶν νέοι καὶ μήτηρ αὐτῶν ἀποθανοῦσα, πάντας ὑπόπτους εἶναι τοῦ πατρὸς ἐπιβούλους δοκεῖν. ἀλλʼ οὐ τὸ ὕποπτον πρὸς τοιαύτην ἀσέβειαν ἀρκετόν."},{"number":111,"text":"εἰπάτω δέ τις, ἡμῖν εἰ τετόλμηται τοιοῦτον, ᾧ καὶ τὰ μὴ πιστὰ πίστιν εἴωθεν ὑπʼ ἐνεργείας λαμβάνειν. φαρμάκου παρασκευὴν ἐλέγχειν δύναταί τις ἢ συνωμοσίαν ἡλικιωτῶν ἢ διαφθορὰν οἰκετῶν ἢ γράμματα κατὰ σοῦ γεγραμμένα;"},{"number":112,"text":"καίτοι τούτων ἕκαστον ἔσθʼ ὅπη καὶ μὴ γενόμενον ἐκ διαβολῆς ἐπλάσθη· χαλεπὸν γὰρ οὐχ ὁμονοῶν οἶκος ἐν βασιλείᾳ· καὶ τὴν ἀρχήν, ἣν σὺ φῂς ἔπαθλον εὐσεβείας, συμβαίνει πολλάκις αἰτίαν γενέσθαι τοῖς πονηροτάτοις ἐλπίδων, διʼ ἃς οὐδεμίαν ὑποστολὴν ποιοῦνται κακοηθείας."},{"number":113,"text":"ἀδίκημα μὲν οὖν οὐδεὶς ἐρεῖ καθʼ ἡμῶν· τὰς δὲ διαβολὰς πῶς ἂν λύσειεν ὁ ἀκοῦσαι μὴ θέλων; ἐλαλήσαμέν τι μετὰ παρρησίας. οὐκ εἰς σέ· τοῦτο γὰρ ἦν ἄδικον· ἀλλʼ εἰς τοὺς οὐδʼ ὅ τι λελάλητο μὴ σιωπῶντας."},{"number":114,"text":"τὴν μητέρα τις ἡμῶν ἔκλαυσεν. οὐχ ὅτι τέθνηκεν, ἀλλʼ ὅτι καὶ νεκρὰ κακῶς ἤκουσεν ὑπὸ τῶν οὐκ ἀξίων. ἀρχῆς ἐπιθυμοῦμεν ἧς ἴσμεν ἔχοντα τὸν πατέρα; τί καὶ θέλοντες; εἰ μὲν εἰσὶν ἡμῖν τιμαὶ βασιλέων, ὥσπερ εἰσίν, οὐ κενοσπουδοῦμεν;"},{"number":115,"text":"εἰ δʼ οὐκ εἰσίν, οὐκ ἐλπίζομεν; ἢ σὲ διαχειρισάμενοι κρατήσειν τὴν βασιλείαν προσεδοκήσαμεν, οἷς οὔτε γῆ βάσιμος οὔτε πλωτὴ θάλαττα μετὰ τοιοῦτον ἔργον; ἡ δὲ τῶν ἀρχομένων εὐσέβεια καὶ θρησκεία τοῦ παντὸς ἔθνους ἠνέσχετο ἂν πατροκτόνους ἐπὶ τῶν πραγμάτων εἶναι καὶ εἰς τὸν ἁγιώτατον ὑπὸ σοῦ κατασκευασθέντα ναὸν εἰσιέναι."},{"number":116,"text":"τί δʼ εἰ καὶ τῶν ἄλλων κατεφρονήσαμεν, ἐδύνατό τις φονεύσας ἀτιμώρητος μένειν ζῶντος Καίσαρος; οὔτʼ ἀσεβεῖς οὕτως ἐγέννησας οὔτʼ ἀλογίστους, ἀτυχεστέρους δʼ ἴσως ἢ σοὶ καλῶς εἶχεν."},{"number":117,"text":"εἰ δὲ μήτʼ αἰτίας ἔχεις μήτʼ ἐπιβουλὰς εὑρίσκεις, τί σοι πρὸς πίστιν αὔταρκες τοιαύτης δυσσεβείας; ἡ μήτηρ τέθνηκεν· ἀλλά τοι τὰ κατʼ ἐκείνην οὐδὲ παροξύνειν ἡμᾶς ἀλλὰ νουθετεῖν ἠδύνατο."},{"number":118,"text":"πλείω μὲν ἀπολογεῖσθαι δυνάμεθα, λόγον δʼ οὐκ ἐπιδέχεται τὰ μὴ γενόμενα. διόπερ ἐπὶ τῷ πάντων δεσπότῃ Καίσαρι μεσιτεύοντι τὸν παρόντα καιρὸν συντιθέμεθα ταύτην τὴν συνθήκην·"},{"number":119,"text":"εἰ μὲν ἀνύποπτον ἐξ αὐτῆς τῆς ἀληθείας τὴν πρὸς ἡμᾶς διάθεσιν ἀπολαμβάνεις, ὦ πάτερ, ζήσομεν, οὐδʼ οὕτως μὲν εὐτυχῶς· δεινὸν γὰρ τῶν μεγάλων κακῶν καὶ ψευδὴς αἰτία."},{"number":120,"text":"παρούσης δέ τινος ὀρρωδίας σὺ μὲν ἐν τῇ κατὰ σαυτὸν εὐσεβείᾳ μένε, δώσομεν δὲ λόγον ἡμεῖς ἑαυτοῖς. οὐχ οὕτως ὁ βίος ἡμῖν τίμιος, ὡς ἔχειν αὐτὸν ἐπʼ ἀδικίᾳ τοῦ δεδωκότος."},{"number":121,"text":"Τοιαῦτα δὲ λέγοντος ὅ τε Καῖσαρ οὐδὲ πρότερον πιστεύων τῷ μεγέθει τῆς διαβολῆς ἔτι μᾶλλον ἐξηλλάττετο καὶ συνεχὲς εἰς τὸν Ἡρώδην ἀπέβλεπεν ὁρῶν κἀκεῖνον ὑποσυγχυνόμενον, ἀγωνία τε τοῖς παροῦσιν ἐνεπεπτώκει καὶ περὶ τὴν αὐλὴν ὁ λόγος διαδοθεὶς ἐπίφθονον ἐποίει τὸν βασιλέα."},{"number":122,"text":"τὸ γὰρ ἄπιστον τῆς διαβολῆς καὶ τὸ περὶ τοὺς νεανίσκους ἐν ἀκμῇ καὶ κάλλει σωμάτων ἐλεεινὸν ἐπεσπᾶτο βοήθειαν· ἔτι δὲ μᾶλλον ἐπειδὴ καὶ τῷ λόγῳ δεξιῶς καὶ μετὰ φρονήσεως ὑπήντησεν Ἀλέξανδρος, ἦν οὐδʼ ἐκείνοις ἔτι ταὐτὸν σχῆμα, κλαίουσι μὲν ὅμως καὶ σὺν κατηφείᾳ πρὸς τὴν γῆν νενευκόσιν,"},{"number":123,"text":"ἡ δʼ ἐλπὶς ἀμείνων ὑπεφαίνετο, καὶ δόξας ὁ βασιλεὺς ἐξ ὧν αὐτὸν ἔπειθεν εὔλογα κατηγορηκέναι διὰ τὸ μηδὲν ἔχειν ἐξελέγχειν ἀπολογίας τινὸς ἐδεῖτο."},{"number":124,"text":"Καῖσαρ δὲ μικρὸν ἐπισχὼν τοὺς μὲν νεανίσκους, εἰ καὶ πόρρω τῆς ἐπʼ αὐτοῖς διαβολῆς δοκοῦσιν, αὐτό γε τοῦτο ἁμαρτεῖν ἔφη τὸ μὴ τοιούτους αὐτοὺς παρασχεῖν τῷ πατρί, ὡς μηδὲ γενέσθαι τὸν ἐπʼ αὐτοῖς λόγον."},{"number":125,"text":"Ἡρώδην δὲ παρεκάλει πᾶσαν ὑπόνοιαν ἐκβαλόντα διαλλάττεσθαι τοῖς παισίν· οὐ γὰρ εἶναι δίκαιον οὐδὲ πιστεύειν τὰ τοιαῦτα κατὰ τῶν ἐξ αὐτοῦ. δύνασθαι δὲ τὴν μετάνοιαν ἀμφοτέροις οὐ μόνον ἰάσασθαι τὰ συμβεβηκότα, παροξῦναι δὲ τὴν εὔνοιαν, ἐν ᾧ τὸ προπετὲς ἑκάτεροι τῆς ὑποψίας ἀπολογούμενοι σπουδῇ πλείονι περὶ ἀλλήλους ἀξιώσουσι κεχρῆσθαι."},{"number":126,"text":"τοιαῦτα νουθετῶν ἔνευσε τοῖς νεανίσκοις. ἐκείνων δὲ βουλομένων ὑποπεσεῖν ἐπὶ δεήσει προαναλαβὼν αὐτοὺς ὁ πατὴρ δακρύοντας ἠσπάζετο παρʼ ἕκαστον ἐν μέρει περιπτύσσων, ὡς μηδένα τῶν παρατυγχανόντων ἐλεύθερον ἢ δοῦλον ἀπαθῆ γενέσθαι."},{"number":127,"text":"Τότε μὲν οὖν εὐχαριστήσαντες Καίσαρι μετʼ ἀλλήλων ἀπῄεσαν καὶ σὺν αὐτοῖς Ἀντίπατρος ὑποκρινόμενος ἐφήδεσθαι ταῖς διαλλαγαῖς."},{"number":128,"text":"ἐν δὲ ταῖς ὑστέραις ἡμέραις Ἡρώδης μὲν ἐδωρεῖτο Καίσαρα τριακοσίοις ταλάντοις θέας τε καὶ διανομὰς ποιούμενον τῷ Ῥωμαίων δήμῳ, Καῖσαρ δὲ αὐτῷ τοῦ μετάλλου τοῦ Κυπρίων χαλκοῦ τὴν ἡμίσειαν πρόσοδον καὶ τῆς ἡμισείας τὴν ἐπιμέλειαν ἔδωκεν καὶ τἆλλα ξενίαις καὶ καταγωγαῖς ἐτίμησεν,"},{"number":129,"text":"καὶ περὶ τῆς βασιλείας αὐτῷ τὴν ἐξουσίαν ἐφῆκεν ὃν ἂν αἱρῆται τῶν παίδων διάδοχον καθιστάνειν ἢ καὶ διανέμειν μέρος ἑκάστῳ τῆς τιμῆς εἰς πάντας ἐλευσομένης. ἐκείνου δὲ ἤδη θέλοντος αὐτὸ ποιεῖν οὐκ ἐπιτρέψειν ἔφη ζῶντι μὴ καὶ τῆς βασιλείας καὶ τῶν παίδων κρατεῖν."},{"number":130,"text":"Ἐπὶ τούτοις ἐπανῄει πάλιν εἰς τὴν Ἰουδαίαν. ἀποδημοῦντος δὲ οὐ μικρὸν μέρος ἀπέστη τῆς ἀρχῆς τὸ περὶ τὸν Τράχωνα, καὶ τούτους οἱ καταλειφθέντες στρατηγοὶ χειρωσάμενοι πάλιν ὑπακούειν ἠνάγκασαν."},{"number":131,"text":"Ἡρώδης δὲ πλέων σὺν τοῖς παισὶν ὡς ἐγένετο κατὰ Κιλικίαν ἐν Ἐλαιούσῃ τῇ μετωνομασμένῃ νῦν Σεβαστῇ καταλαμβάνει τὸν βασιλέα τῆς Καππαδοκίας Ἀρχέλαον, ὃς αὐτὸν ἐκδέχεται φιλοφρόνως ἡδόμενος ἐπὶ ταῖς τῶν παίδων διαλλαγαῖς καὶ τῷ τὸν Ἀλέξανδρον, ὃς εἶχεν αὐτοῦ τὴν θυγατέρα, τῆς αἰτίας ἀπολελύσθαι, δωρεάς τε ἀντέδοσαν ἀλλήλοις ἃς εἰκὸς βασιλεῖς."},{"number":132,"text":"ἐντεῦθεν Ἡρώδης ἐπὶ Ἰουδαίας ἐλθὼν καὶ γενόμενος ἐν τῷ ἱερῷ περὶ τῶν πεπραγμένων κατὰ τὴν ἀποδημίαν διελέγετο, τὴν Καίσαρος εἰς αὐτὸν φιλοφροσύνην καὶ τἆλλα διεξιὼν ὅσα κατὰ μέρος αὐτῷ πραχθέντα συμφέρειν ἡγεῖτο καὶ τοὺς ἄλλους εἰδέναι."},{"number":133,"text":"τέλος ἐπὶ νουθεσίᾳ τῶν παίδων κατέστρεφε τὸν λόγον τοὺς περὶ τὴν αὐλὴν καὶ τὸ λοιπὸν πλῆθος εἰς ὁμόνοιαν παρακαλῶν καὶ τοὺς υἱοὺς μετʼ αὐτὸν ἀποδεικνύων βασιλέας γενέσθαι, πρῶτον μὲν Ἀντίπατρον, εἶτα καὶ τοὺς ἐκ Μαριάμμης Ἀλέξανδρον καὶ Ἀριστόβουλον."},{"number":134,"text":"ἐν δὲ τῷ τότε πάντας ἀποβλέπειν εἰς αὐτὸν ἀξιῶν καὶ βασιλέα καὶ δεσπότην ἁπάντων δοκεῖν μήτε γήρᾳ παραποδιζόμενον, ἐν ᾧ τοῦ χρόνου τὸ πρὸς ἀρχὴν ἐμπειρότατον ἔχειν, οὔτε τοῖς ἄλλοις ἐπιτηδεύμασιν ἐλαττούμενον, ἃ δύναται καὶ βασιλείας κρατεῖν καὶ παίδων ἄρχειν, τούς τε ἡγεμόνας καὶ τὸ στρατιωτικὸν εἰ πρὸς ἕνα βλέποιεν αὐτὸν ἀτάραχον ἔφη τὸν βίον ἕξειν καὶ πᾶσαν ἀφορμὴν εὐδαιμονίας ἐξ ἀλλήλων ἔσεσθαι."},{"number":135,"text":"ταῦτʼ εἰπὼν ἀφίησιν τὴν ἐκκλησίαν, τοῖς πλείστοις μὲν ἀρεστὰ διειλεγμένος, ἐνίοις δʼ οὐχ ὁμοίως· ἤδη γὰρ ὑπὸ τῆς ἁμίλλης καὶ τῶν ἐλπίδων ἃς ἐδεδώκει τοῖς παισὶ νενεωτέριστο πολλὰ καὶ νεωτέρων ἐφιέμενοι"}],"5":[{"number":136,"text":"Περὶ δὲ τὸν χρόνον τοῦτον συντέλειαν ἔλαβεν ἡ Καισάρεια Σεβαστή, ἣν ᾠκοδόμει δεκάτῳ μὲν ἔτει πρὸς τέλος ἐλθούσης αὐτῷ τῆς ὅλης κατασκευῆς, ἐκπεσούσης δὲ τῆς προθεσμίας εἰς ὄγδοον καὶ εἰκοστὸν ἔτος τῆς ἀρχῆς ἐπʼ ὀλυμπιάδος δευτέρας καὶ ἐνενηκοστῆς πρὸς ταῖς ἑκατόν."},{"number":137,"text":"ἦν οὖν εὐθὺς ἐν καθιερώσει μείζονες ἑορταὶ καὶ παρασκευαὶ πολυτελέσταται· κατηγγέλκει μὲν γὰρ ἀγῶνα μουσικῆς καὶ γυμνικῶν ἀθλημάτων, παρεσκευάκει δὲ πολὺ πλῆθος μονομάχων καὶ θηρίων ἵππων τε δρόμον καὶ τὰ πολυτελέστερα τῶν ἔν τε τῇ Ῥώμῃ καὶ παρʼ ἄλλοις τισὶν ἐπιτηδευμάτων."},{"number":138,"text":"ἀνετίθει δὲ καὶ τοῦτον τὸν ἀγῶνα Καίσαρι κατὰ πενταετηρίδα παρεσκευασμένος ἄγειν αὐτόν· ὁ δʼ αὐτῷ πᾶσαν τὴν εἰς τὰ τοιαῦτα παρασκευὴν ἀπὸ τῶν οἰκείων διεπέμπετο τὴν φιλοτιμίαν ἐπικοσμῶν."},{"number":139,"text":"ἰδίᾳ δὲ καὶ ἡ γυνὴ Καίσαρος Ἰουλία πολλὰ τῶν ἐκεῖ πολυτελεστάτων ἀπέστειλεν, ὡς μηδὲν ὑστερεῖν τὰ πάντα συντιμώμενα ταλάντων πεντακοσίων."},{"number":140,"text":"συνελθόντος δʼ εἰς τὴν πόλιν ὄχλου πλείονος κατὰ θεωρίαν καὶ πρεσβείας, ἃς ἔπεμπον οἱ δῆμοι διʼ ἃς ἐπεπόνθεισαν εὐεργεσίας, ἅπαντας ἐξεδέξατο καὶ καταγωγαῖς καὶ τραπέζαις καὶ διηνεκέσιν ἑορταῖς, τῆς πανηγύρεως ἐν μὲν ταῖς ἡμέραις ἐχούσης τὰς ἀπὸ τῶν θεαμάτων ψυχαγωγίας, ἐν δὲ ταῖς νυξὶ τὰς εὐφροσύνας καὶ τὴν εἰς τοῦτο πολυτέλειαν, ὡς ἐπίσημον γενέσθαι τὴν μεγαλοψυχίαν αὐτοῦ·"},{"number":141,"text":"εἰς πάντα γὰρ ἅπερ ἂν ἐπιτηδεύσειεν ἐφιλονείκει τὴν τῶν ἤδη γεγενημένων ἐπίδειξιν ὑπερβαλέσθαι, καί φασιν αὐτόν τε Καίσαρα καὶ Ἀγρίππαν πολλάκις εἰπεῖν, ὡς ἀποδέοι τὰ τῆς ἀρχῆς Ἡρώδῃ τῆς οὔσης ἐν αὐτῷ μεγαλοψυχίας· ἄξιον γὰρ εἶναι καὶ Συρίας ἁπάσης καὶ Αἰγύπτου τὴν βασιλείαν ἔχειν."},{"number":142,"text":"Μετὰ δὲ τὴν πανήγυριν ταύτην καὶ τὰς ἑορτὰς πόλιν ἄλλην ἀνήγειρεν ἐν τῷ πεδίῳ τῷ λεγομένῳ Καφαρσαβᾶ τόπον ἔνυδρον καὶ χώραν ἀρίστην φυτοῖς ἐκλέξας, ποταμοῦ τε περιρρέοντος τὴν πόλιν αὐτὴν καὶ καλλίστου κατὰ μέγεθος τῶν φυτῶν περιειληφότος ἄλσους."},{"number":143,"text":"ταύτην ἀπὸ Ἀντιπάτρου τοῦ πατρὸς Ἀντιπατρίδα προσηγόρευσεν. ἐπώνυμον δὲ καὶ τῇ μητρὶ χωρίον ὑπὲρ Ἱεριχοῦν οἰκοδομήσας ἀσφαλείᾳ τε διάφορον καὶ καταγωγαῖς ἥδιστον ἐκάλεσεν Κύπρον."},{"number":144,"text":"Φασαήλῳ τε τῷ ἀδελφῷ μνημεῖα διὰ τὴν γεγενημένην εἰς αὐτὸν φιλοστοργίαν ἀνετίθει τὰ κάλλιστα, πύργον ἐπʼ αὐτῆς τῆς πόλεως ἀναστήσας οὐδὲν ἐλάττω τοῦ κατὰ τὴν Φάρον, ὃν προσηγόρευσεν Φασάηλον, ἀσφαλείας τε τῇ πόλει μέρος ὄντα καὶ μνήμης τῷ τετελευτηκότι διὰ τὴν προσηγορίαν."},{"number":145,"text":"ὁμώνυμον δὲ αὐτῷ καὶ πόλιν περὶ τὸν αὐλῶνα τῆς Ἱεριχοῦντος ἔκτισεν ἀπιόντων κατὰ βορρᾶν ἄνεμον, διʼ ἧς καὶ τὴν πέριξ χώραν ἔρημον οὖσαν ἐνεργοτέραν ἐποίησεν ταῖς ἐπιμελείαις τῶν οἰκητόρων. Φασαηλίδα καὶ ταύτην ἐκάλει."},{"number":146,"text":"Τὰς δὲ ἄλλας εὐεργεσίας ἄπορον εἰπεῖν ὅσας ἀπέδωκεν ταῖς πόλεσιν ἔν τε Συρίᾳ καὶ κατὰ τὴν Ἑλλάδα καὶ παρʼ οἷς ποτʼ ἂν ἀποδημήσας τύχοι· καὶ γὰρ πλείους λειτουργίας καὶ δημοσίων ἔργων κατασκευὰς καὶ χρήματα τοῖς δεομένοις ἔργοις εἰς ἐπιμέλειαν τῶν προτέρων ἔργων ἐκλελοιπότων ἄφθονα χαρίσασθαι δοκεῖ."},{"number":147,"text":"τὰ δὲ μέγιστα καὶ διασημότατα τῶν πεπραγμένων αὐτῷ Ῥοδίοις μὲν τό τε Πύθιον ἀνέστησεν οἰκείοις ἀναλώμασιν καὶ παρέσχεν ἀργυρίου πολλὰ τάλαντα πρὸς ναυπηγίαν. Νικοπολίταις δὲ τοῖς ἐπʼ Ἀκτίῳ κτισθεῖσιν ὑπὸ Καίσαρος τὰ πλεῖστα τῶν δημοσίων συγκατεσκεύασεν."},{"number":148,"text":"Ἀντιοχεῦσι δὲ τοῖς ἐν Συρίᾳ μεγίστην πόλιν οἰκοῦσιν, ἣν κατὰ μῆκος τέμνει πλατεῖα, ταύτην αὐτὴν στοαῖς παρʼ ἑκάτερα καὶ λίθῳ τὴν ὕπαιθρον ὁδὸν ξεστῷ καταστορέσας πλεῖστον εἰς κόσμον καὶ τὴν τῶν οἰκούντων εὐχρηστίαν ὠφέλησεν."},{"number":149,"text":"τόν γε μὴν Ὀλυμπίασιν ἀγῶνα πολὺ τῆς προσηγορίας ἀδοξότερον ὑπʼ ἀχρηματίας διατεθειμένον τιμιώτερον ἐποίει χρημάτων προσόδους καταστήσας καὶ πρὸς θυσίας καὶ τὸν ἄλλον κόσμον ἐσεμνοποίησεν τὴν πανήγυριν. διὰ δὴ ταύτην τὴν φιλοτιμίαν διηνεκὴς ἀγωνοθέτης παρὰ τοῖς Ἠλείοις ἀνεγράφη."},{"number":150,"text":"Τοῖς μὲν οὖν ἄλλοις ἐπέρχεται θαυμάζειν τὸ διεστὸς τῆς ἐν τῇ φύσει προαιρέσεως· ὅταν μὲν γὰρ εἰς τὰς φιλοτιμίας καὶ τὰς εὐεργεσίας ἀπίδωμεν, αἷς ἐκέχρητο πρὸς ἅπαντας ἀνθρώπους, οὐκ ἔστιν ὅπως οὐκ ἄν τις αὐτὸν καὶ τῶν ἔλαττον τετιμημένων ἠρνήθη μὴ συνομολογεῖν εὐεργετικωτάτῃ κεχρῆσθαι τῇ φύσει."},{"number":151,"text":"ὅταν δὲ εἰς τὰς τιμωρίας καὶ ἀδικίας, ἃς εἰς τοὺς ἀρχομένους καὶ τοὺς οἰκειοτάτους ἐπεδείξατο βλέψῃ καὶ καταμάθῃ τὸ σκληρὸν καὶ τὸ δυσπαράκλητον τοῦ τρόπου, νικηθήσεται θηριώδη δοκεῖν καὶ πάσης μετριότητος ἀλλότριον."},{"number":152,"text":"ἔνθεν καὶ διάφορόν τινα καὶ μαχομένην ἐπʼ αὐτῷ νομίζουσιν γενέσθαι τὴν προαίρεσιν. ἐγὼ δʼ οὐχ οὕτως ἔχων μίαν αἰτίαν ἀμφοτέρων τούτων ὑπολαμβάνω·"},{"number":153,"text":"φιλότιμος γὰρ ὢν καὶ τούτου τοῦ πάθους ἡττημένος ἰσχυρῶς, προήγετο μὲν εἰς μεγαλοψυχίαν, εἴ που μνήμης εἰς αὖθις ἢ κατὰ τὸ παρὸν εὐφημίας ἐλπὶς ἐμπέσοι."},{"number":154,"text":"ταῖς δὲ δαπάναις ὑπὲρ δύναμιν χρώμενος ἠναγκάζετο χαλεπὸς εἶναι τοῖς ὑποτεταγμένοις· τὰ γὰρ εἰς οὓς ἐδαπάνα πολλὰ γενόμενα κακῶν ποριστὴν ἐξ ὧν ἐλάμβανεν ἐποίει."},{"number":155,"text":"καὶ συνειδὼς ἐφʼ οἷς ἠδίκει τοὺς ὑποτεταγμένους μισούμενον ἑαυτὸν τὸ μὲν ἐπανορθοῦσθαι τὰς ἁμαρτίας οὐ ῥᾴδιον ἐνόμιζεν· οὐδὲ γὰρ εἰς τὰς προσόδους λυσιτελὲς ἦν. ἀντεφιλονείκει δὲ τὴν δύσνοιαν αὐτὴν εὐπορίας ἀφορμὴν ποιούμενος."},{"number":156,"text":"περί γε μὴν τοὺς οἰκείους, εἴ τις ἢ λόγῳ μὴ θεραπεύοι τὸ δοῦλον ἐξομολογούμενος ἢ δόξειεν εἰς τὴν ἀρχήν τι παρακινεῖν, οὐχ ἱκανὸς ἑαυτοῦ κρατεῖν ἐγίνετο καὶ διεξῆλθεν ὁμοῦ συγγενεῖς καὶ φίλους ἴσα πολεμίοις τιμωρούμενος ἐκ τοῦ μόνος ἐθέλειν τετιμῆσθαι τὰς τοιαύτας ἁμαρτίας ἀναλαμβάνων."},{"number":157,"text":"μαρτύριον δέ μοι τούτου τοῦ πάθους, ὅτι μέγιστον περὶ αὐτὸν ἦν, καὶ τὰ γινόμενα κατὰ τὰς Καίσαρος καὶ Ἀγρίππα καὶ τῶν ἄλλων φίλων τιμάς· οἷς γὰρ ἐθεράπευεν τοὺς κρείττονας, τούτοις καὶ αὐτὸς ἠξίου θεραπεύεσθαι καὶ τὸ κάλλιστον ὧν ᾤετο παρέχων ἐν τῷ διδόναι τὴν τοῦ τυχεῖν τῶν ὁμοίων ἐπιθυμίαν ἐδήλου."},{"number":158,"text":"τό γε μὴν Ἰουδαίων ἔθνος ἠλλοτρίωται νόμῳ πρὸς πάντα τὰ τοιαῦτα καὶ συνείθισται τὸ δίκαιον ἀντὶ τοῦ πρὸς δόξαν ἠγαπηκέναι. διόπερ οὐκ ἦν αὐτῷ κεχαρισμένον, ὅτι μὴ δυνατὸν εἰκόσιν ἢ ναοῖς ἢ τοιούτοις ἐπιτηδεύμασιν κολακεύειν τοῦ βασιλέως τὸ φιλότιμον."},{"number":159,"text":"αἰτία μὲν αὕτη μοι δοκεῖ τῆς Ἡρώδου περὶ μὲν τοὺς οἰκείους καὶ συμβούλους ἁμαρτίας, περὶ δὲ τοὺς ἔξω καὶ μὴ προσήκοντας εὐεργεσίας."}],"6":[{"number":160,"text":"Τοὺς δὲ κατὰ τὴν Ἀσίαν Ἰουδαίους καὶ ὅσους ἡ πρὸς Κυρήνῃ Λιβύη κατέσχεν ἐκάκουν αἱ πόλεις, τῶν μὲν πρότερον βασιλέων ἰσονομίαν αὐτοῖς παρεσχημένων, ἐν δὲ τῷ τότε διʼ ἐπηρείας ἐχόντων τῶν Ἑλλήνων αὐτούς, ὡς καὶ χρημάτων ἱερῶν ἀφαίρεσιν ποιεῖσθαι καὶ καταβλάπτειν ἐν τοῖς ἐπὶ μέρους."},{"number":161,"text":"πάσχοντες δὲ κακῶς καὶ πέρας οὐδὲν εὑρίσκοντες τῆς τῶν Ἑλλήνων ἀπανθρωπίας ἐπρεσβεύσαντο παρὰ Καίσαρα καὶ περὶ τούτων. ὁ δʼ αὐτοῖς τὴν αὐτὴν ἰσοτέλειαν ἔδωκεν γράψας τοῖς κατὰ τὰς ἐπαρχίας, ὧν ὑπετάξαμεν τὰ ἀντίγραφα μαρτύρια τῆς διαθέσεως, ἣν ἔσχον ὑπὲρ ἡμῶν ἄνωθεν οἱ κρατοῦντες."},{"number":162,"text":"Καῖσαρ Σεβαστὸς ἀρχιερεὺς δημαρχικῆς ἐξουσίας λέγει. ἐπειδὴ τὸ ἔθνος τὸ τῶν Ἰουδαίων εὐχάριστον εὑρέθη οὐ μόνον ἐν τῷ ἐνεστῶτι καιρῷ ἀλλὰ καὶ ἐν τῷ προγεγενημένῳ καὶ μάλιστα ἐπὶ τοῦ ἐμοῦ πατρὸς αὐτοκράτορος Καίσαρος πρὸς τὸν δῆμον τὸν Ῥωμαίων ὅ τε ἀρχιερεὺς αὐτῶν Ὑρκανός,"},{"number":163,"text":"ἔδοξέ μοι καὶ τῷ ἐμῷ συμβουλίῳ μετὰ ὁρκωμοσίας γνώμῃ δήμου Ῥωμαίων τοὺς Ἰουδαίους χρῆσθαι τοῖς ἰδίοις θεσμοῖς κατὰ τὸν πάτριον αὐτῶν νόμον, καθὼς ἐχρῶντο ἐπὶ Ὑρκανοῦ ἀρχιερέως θεοῦ ὑψίστου, τά τε ἱερὰ εἶναι ἐν ἀσυλίᾳ καὶ ἀναπέμπεσθαι εἰς Ἱεροσόλυμα καὶ ἀποδίδοσθαι τοῖς ἀποδοχεῦσιν Ἱεροσολύμων, ἐγγύας τε μὴ ὁμολογεῖν αὐτοὺς ἐν σάββασιν ἢ τῇ πρὸ αὐτῆς παρασκευῇ ἀπὸ ὥρας ἐνάτης."},{"number":164,"text":"ἐὰν δέ τις φωραθῇ κλέπτων τὰς ἱερὰς βίβλους αὐτῶν ἢ τὰ ἱερὰ χρήματα ἔκ τε σαββατείου ἔκ τε ἀνδρῶνος, εἶναι αὐτὸν ἱερόσυλον καὶ τὸν βίον αὐτοῦ ἐνεχθῆναι εἰς τὸ δημόσιον τῶν Ῥωμαίων."},{"number":165,"text":"τό τε ψήφισμα τὸ δοθέν μοι ὑπʼ αὐτῶν ὑπὲρ τῆς ἐμῆς εὐσεβείας ἧς ἔχω πρὸς πάντας ἀνθρώπους καὶ ὑπὲρ Γαΐου Μαρκίου Κηνσωρίνου καὶ τοῦτο τὸ διάταγμα κελεύω ἀνατεθῆναι ἐν ἐπισημοτάτῳ τόπῳ τῷ γενηθέντι μοι ὑπὸ τοῦ κοινοῦ τῆς Ἀσίας ἐν Ἀγκύρῃ. ἐὰν δέ τις παραβῇ τι τῶν προειρημένων, δώσει δίκην οὐ μετρίαν. ἐστηλογραφήθη ἐν τῷ Καίσαρος ναῷ."},{"number":166,"text":"Καῖσαρ Νωρβανῷ Φλάκκῳ χαίρειν. Ἰουδαῖοι ὅσοι ποτʼ οὖν εἰσίν, οἳ διʼ ἀρχαίαν συνήθειαν εἰώθασιν χρήματά τε ἱερὰ φέροντες ἀναπέμπειν ἀκωλύτως τοῦτο ποιείτωσαν εἰς Ἱεροσόλυμα. καὶ ταῦτα μὲν Καῖσαρ."},{"number":167,"text":"Ἀγρίππας δὲ καὶ αὐτὸς ἔγραψεν ὑπὲρ τῶν Ἰουδαίων τὸν τρόπον τοῦτον· Ἀγρίππας Ἐφεσίων ἄρχουσι βουλῇ δήμῳ χαίρειν. τῶν εἰς τὸ ἱερὸν τὸ ἐν Ἱεροσολύμοις ἀναφερομένων ἱερῶν χρημάτων τὴν ἐπιμέλειαν καὶ φυλακὴν βούλομαι τοὺς ἐν Ἀσίᾳ Ἰουδαίους ποιεῖσθαι κατὰ τὰ πάτρια."},{"number":168,"text":"τούς τε κλέπτοντας ἱερὰ γράμματα τῶν Ἰουδαίων καταφεύγοντάς τε εἰς τὰς ἀσυλίας βούλομαι ἀποσπᾶσθαι καὶ παραδίδοσθαι τοῖς Ἰουδαίοις, ᾧ δικαίῳ ἀποσπῶνται οἱ ἱερόσυλοι. ἔγραψα δὲ καὶ Σιλανῷ τῷ στρατηγῷ, ἵνα σάββασιν μηδεὶς ἀναγκάζῃ Ἰουδαῖον ἐγγύας ὁμολογεῖν."},{"number":169,"text":"Μᾶρκος Ἀγρίππας Κυρηναίων ἄρχουσιν βουλῇ δήμῳ χαίρειν. οἱ ἐν Κυρήνῃ Ἰουδαῖοι, ὑπὲρ ὧν ἤδη ὁ Σεβαστὸς ἔπεμψεν πρὸς τὸν ἐν Λιβύῃ στρατηγὸν τόντε ὄντα Φλάβιον καὶ πρὸς τοὺς ἄλλους τοὺς τῆς ἐπαρχίας ἐπιμελουμένους, ἵνα ἀνεπικωλύτως ἀναπέμπηται τὰ ἱερὰ χρήματα εἰς Ἱεροσόλυμα, ὡς ἔστιν αὐτοῖς πάτριον,"},{"number":170,"text":"ἐνέτυχόν μοι νῦν, ὡς ὑπό τινων συκοφαντῶν ἐπηρεαζόμενοι καὶ ὡς ἐν προφάσει τελῶν μὴ ὀφειλομένων κωλύοιντο· οἷς ἀποκαθιστάνειν κατὰ μηδένα τρόπον ἐνοχλουμένοις, καὶ εἴ τινων ἱερὰ χρήματα ἀφῄρηνται τῶν πόλεων τοὺς εἰς ταῦτα ἀποκεκριμένους καὶ ταῦτα διορθώσασθαι τοῖς ἐκεῖ Ἰουδαίοις κελεύω."},{"number":171,"text":"Γάιος Νωρβανὸς Φλάκκος ἀνθύπατος Σαρδιανῶν ἄρχουσι χαίρειν. Καῖσάρ μοι ἔγραψεν κελεύων μὴ κωλύεσθαι τοὺς Ἰουδαίους ὅσα ἂν ὦσιν κατὰ τὸ πάτριον αὐτοῖς ἔθος συναγαγόντες χρήματα ἀναπέμπειν εἰς Ἱεροσόλυμα. ἔγραψα οὖν ὑμῖν, ἵνʼ εἰδῆτε, ὅτι Καῖσαρ κἀγὼ οὕτως θέλομεν γίνεσθαι."},{"number":172,"text":"Οὐδὲν ἧττον καὶ Ἰούλιος Ἀντώνιος ἀνθύπατος ἔγραψεν Ἐφεσίων ἄρχουσιν βουλῇ δήμῳ χαίρειν. οἱ ἐν τῇ Ἀσίᾳ κατοικοῦντες Ἰουδαῖοι εἰδοῖς Φεβρουαρίοις δικαιοδοτοῦντί μοι ἐν Ἐφέσῳ ὑπέδειξαν Καίσαρα τὸν Σεβαστὸν καὶ Ἀγρίππαν συγκεχωρηκέναι αὐτοῖς χρῆσθαι τοῖς ἰδίοις νόμοις καὶ ἔθεσιν, ἀπαρχάς τε, ἃς ἕκαστος αὐτῶν ἐκ τῆς ἰδίας προαιρέσεως εὐσεβείας ἕνεκα τῆς πρὸς τὸ θεῖον ἀνακομιδῆς συμπορευομένους ποιεῖν ἀνεμποδίστως."},{"number":173,"text":"ᾔτουν τε, ὅπως κἀγὼ ὁμοίως τοῖς ὑπὸ τοῦ Σεβαστοῦ καὶ Ἀγρίππα δοθεῖσιν τὴν ἐμὴν γνώμην βεβαιώσω. ὑμᾶς οὖν βούλομαι εἰδέναι ἐν τοῖς τοῦ Σεβαστοῦ καὶ Ἀγρίππα βουλήμασιν συνεπιτρέπειν αὐτοῖς χρῆσθαι καὶ ποιεῖν κατὰ τὰ πάτρια χωρὶς ἐμποδισμοῦ."},{"number":174,"text":"Ταῦτα μὲν οὖν παρεθέμην ἐξ ἀνάγκης, ἐπειδὴ μέλλουσιν αἱ τῶν ἡμετέρων πράξεων ἀναγραφαὶ τὸ πλέον εἰς τοὺς Ἕλληνας ἰέναι, δεικνὺς αὐτοῖς ὅτι πάσης τιμῆς ἄνωθεν ἐπιτυγχάνοντες οὐδὲν τῶν πατρίων ἐκωλύθημεν ὑπὸ τῶν ἀρχόντων πράττειν, ἀλλὰ καὶ συνεργούμεθα τὰ τῆς θρησκείας ἔχοντες καὶ τῶν εἰς τὸν θεὸν τιμῶν."},{"number":175,"text":"ποιοῦμαι δὲ πολλάκις αὐτῶν τὴν μνήμην ἐπιδιαλλάττων τὰ γένη καὶ τὰς ἐμπεφυκυίας τοῖς ἀλογίστοις ἡμῶν τε κἀκείνων μίσους αἰτίας ὑπεξαιρούμενος."},{"number":176,"text":"ἔθεσιν μὲν γὰρ οὐδέν ἐστιν γένος ὃ τοῖς αὐτοῖς ἀεὶ χρῆται καὶ κατὰ πόλεις ἔσθʼ ὅπη πολλῆς ἐγγιγνομένης τῆς διαφορᾶς· τὸ δίκαιον δὲ πᾶσιν ἀνθρώποις ὁμοίως ἐπιτηδεύοντες λυσιτελέστατον ὂν Ἕλλησίν τε καὶ βαρβάροις,"},{"number":177,"text":"οὗ πλεῖστον οἱ παρʼ ἡμῖν νόμοι λόγον ἔχοντες ἅπασιν ἡμᾶς, εἰ καθαρῶς ἐμμένοιμεν αὐτοῖς, εὔνους καὶ φίλους ἀπεργάζονται."},{"number":178,"text":"διὸ καὶ ταῦτα παρʼ ἐκείνων ἡμῖν ἀπαιτητέον καὶ δέον οὐκ ἐν τῇ διαφορᾷ τῶν ἐπιτηδευμάτων οἴεσθαι τὸ ἀλλότριον, ἀλλʼ ἐν τῷ πρὸς καλοκαγαθίαν ἐπιτηδείως ἔχειν· τοῦτο γὰρ κοινὸν ἅπασιν καὶ μόνον ἱκανὸν διασώζειν τὸν τῶν ἀνθρώπων βίον. ἐπάνειμι δὲ πάλιν ἐπὶ τὰ συνεχῆ τῆς ἱστορίας."}],"7":[{"number":179,"text":"Ὁ γὰρ Ἡρώδης πολλοῖς τοῖς ἀναλώμασιν εἴς τε τὰς ἔξω καὶ τὰς ἐν τῇ βασιλείᾳ χρώμενος, ἀκηκοὼς ἔτι τάχιον ὡς Ὑρκανὸς ὁ πρὸ αὐτοῦ βασιλεὺς ἀνοίξας τὸν Δαυίδου τάφον ἀργυρίου λάβοι τρισχίλια τάλαντα κειμένων πολὺ πλειόνων ἔτι καὶ δυναμένων εἰς ἅπαν ἐπαρκέσαι ταῖς χορηγίαις, ἐκ πλείονος μὲν διʼ ἐννοίας εἶχεν τὴν ἐπιχείρησιν,"},{"number":180,"text":"ἐν δὲ τῷ τότε νυκτὸς ἀνοίξας τὸν τάφον εἰσέρχεται πραγματευσάμενος ἥκιστα μὲν τῇ πόλει φανερὸς εἶναι, παρειληφὼς δὲ τοὺς πιστοτάτους τῶν φίλων."},{"number":181,"text":"ἀποθέσιμα μὲν οὖν χρήματα καθάπερ Ὑρκανὸς οὐχ εὗρεν, κόσμον δὲ χρυσοῦν καὶ κειμηλίων πολύν, ὃν ἀνείλετο πάντα. σπουδὴν δʼ εἶχεν ἐπιμελεστέραν ποιούμενος τὴν ἔρευναν ἐνδοτέρω τε χωρεῖν καὶ κατὰ τὰς θήκας, ἐν αἷς ἦν τοῦ Δαυΐδου καὶ τοῦ Σολομῶνος τὰ σώματα."},{"number":182,"text":"καὶ δύο μὲν αὐτῷ τῶν δορυφόρων διεφθάρησαν φλογὸς ἔνδοθεν εἰσιοῦσιν ἀπαντώσης, ὡς ἐλέγετο, περίφοβος δʼ αὐτὸς ἐξῄει, καὶ τοῦ δέους ἱλαστήριον μνῆμα λευκῆς πέτρας ἐπὶ τῷ στομίῳ κατεσκευάσατο πολυτελὲς τῇ δαπάνῃ."},{"number":183,"text":"τούτου καὶ Νικόλαος ὁ κατʼ αὐτὸν ἱστοριογράφος μέμνηται τοῦ κατασκευάσματος, οὐ μὴν ὅτι καὶ κατῆλθεν, οὐκ εὐπρεπῆ τὴν πρᾶξιν ἐπιστάμενος. διατελεῖ δὲ καὶ τἆλλα τοῦτον τὸν τρόπον χρώμενος τῇ γραφῇ·"},{"number":184,"text":"ζῶντι γὰρ ἐν τῇ βασιλείᾳ καὶ σὺν αὐτῷ κεχαρισμένως ἐκείνῳ καὶ καθʼ ὑπηρεσίαν ἀνέγραφεν, μόνων ἁπτόμενος τῶν εὔκλειαν αὐτῷ φερόντων, πολλὰ δὲ καὶ τῶν ἐμφανῶς ἀδίκων ἀντικατασκευάζων καὶ μετὰ πάσης σπουδῆς ἐπικρυπτόμενος,"},{"number":185,"text":"ὅς γε καὶ τὸν Μαριάμμης θάνατον καὶ τῶν παίδων αὐτῆς οὕτως ὠμῶς τῷ βασιλεῖ πεπραγμένον εἰς εὐπρέπειαν ἀνάγειν βουλόμενος ἐκείνης τε ἀσέλγειαν καὶ τῶν νεανίσκων ἐπιβουλὰς καταψεύδεται, καὶ διατετέλεκεν τῇ γραφῇ τὰ μὲν πεπραγμένα δικαίως τῷ βασιλεῖ περιττότερον ἐγκωμιάζων, ὑπὲρ δὲ τῶν παρανομηθέντων ἐσπουδασμένως ἀπολογούμενος."},{"number":186,"text":"ἐκείνῳ μὲν οὖν πολλὴν ἄν τις, ὡς ἔφην, ἔχοι τὴν συγγνώμην· οὐ γὰρ ἱστορίαν τοῖς ἄλλοις, ἀλλὰ ὑπουργίαν τῷ βασιλεῖ ταύτην ἐποιεῖτο."},{"number":187,"text":"ἡμεῖς δὲ καὶ γένους ὄντες ἀγχοῦ τῶν ἐξ Ἀσαμωναίου βασιλέων καὶ διὰ τοῦτο σὺν τιμῇ τὴν ἱερωσύνην ἔχοντες τὸ ψεύσασθαί τι περὶ αὐτῶν οὐκ εὐπρεπὲς ὑπειληφότες καθαρῶς καὶ δικαίως ἐκτίθεμεν τὰς πράξεις, πολλοὺς μὲν τῶν ἐγγόνων τῶν ἐκείνου καὶ βασιλεύοντας ἔτι διʼ ἐντροπῆς ἔχοντες, τὴν δʼ ἀλήθειαν πρὸ ἐκείνων τετιμηκότες, ἣν ὅτε δικαίως ἐγίνετο συνέβη τε παρʼ αὐτοῖς ἐκείνοις ὀργῆ τυγχάνειν."},{"number":188,"text":"Ἡρώδης δὲ διὰ τὴν ἐπιχείρησιν, ἣν ἐποιήσατο τῷ τάφῳ, χεῖρον ἐδόκει πράττειν ἐν τοῖς κατὰ τὴν οἰκίαν, εἴτε δὴ τοῦ μηνίματος ἐπιδόντος εἰς ἃ μάλιστα καὶ πρότερον ἐνόσει πλείω γενέσθαι πρὸς ἀνηκέστους ἐξελθεῖν συμφοράς, εἴτε καὶ τῆς τύχης ἐν ἐκείνῳ τὴν ἐπίθεσιν ποιουμένης ἐν οἷς τὸ κατὰ τὴν αἰτίαν εὔκαιρον οὐ μικρὰν πίστιν παρεῖχεν τοῦ διὰ τὴν ἀσέβειαν αὐτῷ τὰς συμφορὰς ἀπηντηκέναι."},{"number":189,"text":"στάσις γὰρ ἦν ὥσπερ ἐμφυλίου πολέμου κατὰ τὴν αὐλὴν καὶ μίση πρὸς ἀλλήλους ἀνθυπερβαλλομένων ταῖς διαβολαῖς."},{"number":190,"text":"ἐστρατήγει δʼ ἀεὶ κατὰ τῶν ἀδελφῶν Ἀντίπατρος δεινὸς ὢν ἔξωθεν μὲν περιβάλλειν αὐτοὺς ταῖς αἰτίαις, αὐτὸς δὲ πολλάκις ἀπολογουμένου τόπον λαμβάνων, ἵνʼ ᾖ τὸ δοκοῦν εὔνουν πιστὸν αὐτῷ πρὸς τὰς ἐπιχειρήσεις ὧν ἐδόκει. καὶ τούτῳ τῷ τρόπῳ ποικίλως ἐκπεριεληλύθει τὸν πατέρα μόνος ὑπὲρ τῆς ἐκείνου σωτηρίας ἅπαντα πράττειν αὐτὸς πεπιστευκώς."},{"number":191,"text":"ὁ δὲ καὶ Πτολεμαῖον, ὃς ἦν αὐτῷ διοικητὴς τῶν τῆς βασιλείας πραγμάτων, Ἀντιπάτρῳ συνίστη καὶ μετὰ τῆς ἐκείνου μητρὸς ὑπὲρ τῶν ἐπειγόντων ἐβουλεύετο. καὶ καθόλου τὰ πάντα ἦσαν οὗτοι καὶ πράττειν ὅσα θέλοιεν καὶ πρὸς δύσνοιαν ἄγειν τὸν βασιλέα τῶν ἔξωθεν οἷς ἐδόκει συμφέρειν."},{"number":192,"text":"οἱ δʼ ἐκ τῆς Μαριάμμης χαλεπώτερον ἀεὶ διετίθεντο, καὶ τὴν αἰτίαν ὑπʼ εὐγενείας οὐκ ἔφερον παρεωσμένοι καὶ τάξιν ἀτιμοτέραν ἔχοντες."},{"number":193,"text":"αἵ γε μὴν γυναῖκες, ἡ μὲν Ἀλεξάνδρῳ συνοικοῦσα θυγάτηρ Ἀρχελάου Γλαφύρα μῖσος εἶχεν εἰς τὴν Σαλώμην κατά τε τὴν πρὸς τὸν ἄνδρα διάθεσιν κἀκ τοῦ πρὸς τὴν ἐκείνης θυγατέρα δοκεῖν ὑπερηφανώτερον διακεῖσθαι· συνῴκει μὲν γὰρ Ἀριστοβούλῳ, τὴν δὲ ἰσοτιμίαν αὐτῆς ἀναξιοπάθει Γλαφύρα."},{"number":194,"text":"Δευτέρας οὖν ταύτης ἔριδος ἐμπεπτωκυίας οὐδʼ ὁ τοῦ βασιλέως ἀδελφὸς Φερώρας ἔξω ταραχῆς ἦν, ἰδίαν δὲ ὑπόθεσιν ὑποψίας καὶ μίσους εἶχεν· ἐμπεπτώκει μὲν γὰρ εἰς ἔρωτα δουλευούσης αὐτῷ γυναικός, ἥττητο δὲ τῆς ἀνθρώπου μεμηνότως ἐπὶ τοσοῦτον κρατούμενος, ὥστʼ αὐτῷ καὶ τῆς τοῦ βασιλέως ἐγγυηθείσης θυγατρὸς τὴν μὲν ὑπερηφανῆσαι, πρὸς δὲ τῇ δούλῃ τὸν νοῦν εἶχεν."},{"number":195,"text":"ἤχθετο δὲ ἀτιμασθεὶς Ἡρώδης τῷ πολλὰ μὲν εὐεργετῆσαι τὸν ἀδελφόν, δυνάμει δὲ καὶ κοινωνὸν ἔχειν τῆς βασιλείας, οὐχ ὅμοιον εἰς τὰς ἀμοιβὰς ὁρῶν, κἀν τῷ προσώπῳ δυστυχεῖν ᾤετο."},{"number":196,"text":"καὶ τὴν μὲν κόρην μὴ τυχὼν Φερώρα δικαίου παιδὶ Φασαήλου δίδωσιν, αὐτὸς δὲ χρόνου διελθόντος οἰόμενος ἤδη παρηκμακέναι τὴν ἐπιθυμίαν τἀδελφῷ περί τε τῶν πρώτων ᾐτιᾶτο καὶ τὴν δευτέραν ἠξίου λαμβάνειν, Κύπρος ἐκαλεῖτο."},{"number":197,"text":"Φερώρᾳ δὲ συμβουλεύει Πτολεμαῖος ἤδη ποτὲ παυσαμένῳ τῆς εἰς τὸν ἀδελφὸν ἀτιμίας καταβαλεῖν τὸν ἔρωτα· καὶ γὰρ αἰσχρὸν εἶναι δούλης ἡττώμενον ἀποστερεῖν μὲν αὑτὸν τῆς εὐνοίας τῆς παρὰ βασιλέως, αἴτιον δὲ κἀκείνῳ ταραχῆς καὶ μίσους πρὸς αὐτὸν καθίστασθαι."},{"number":198,"text":"ταῦτʼ ἐκεῖνος ἰδὼν λυσιτελήσοντα τῷ καὶ πρότερον ἐν διαβολαῖς γενόμενος συνεγνῶσθαι, τὴν μὲν ἄνθρωπον ἤδη καὶ παῖδα ἐξ αὐτῆς ἔχων ἀποπέμπεται, βασιλεῖ δʼ ὡμολόγει λήψεσθαι τὴν δευτέραν αὐτοῦ θυγατέρα καὶ τριακοστὴν ἡμέραν συνέθετο τοῦ γάμου, συνεπομνύμενος ὡς οὐδὲν ἔτι κοινώνημα πρὸς τὴν ἀποπεμφθεῖσαν ἔσται."},{"number":199,"text":"διελθουσῶν δὲ τῶν τριάκοντα ἡμερῶν τοσοῦτον ἦν ἥττων τοῦ ἔρωτος, ὥστε μηδὲν μὲν ἔτι ποιῆσαι τῶν ὡμολογημένων, πάλιν δὲ διατελεῖν ἐπὶ τῇ πρώτῃ."},{"number":200,"text":"ταῦτα φανερῶς ἤδη τὸν Ἡρώδην ἐλύπει καὶ πρὸς ὀργὴν ἦγεν. ἦσαν οὖν λόγοι τινὲς ἀεὶ παραπίπτοντες παρʼ αὐτοῦ, καὶ πολλοὶ τὴν ὀργὴν τοῦ βασιλέως ἀφορμὴν τῶν κατὰ Φερώρου διαβολῶν ἐποιοῦντο. διέλειπεν δὲ οὐκ ἔσθʼ ἥτις ἡμέρα οὐδʼ ὥρα, καθʼ ἣν ἀτρεμεῖν αὐτῷ συνέβαινεν, ἀλλʼ ἀεί τι προσέπιπτεν καινῶν ἀγωνισμάτων συγγενῶν καὶ φιλτάτων εἰς ἀλλήλους πεποιημένων."},{"number":201,"text":"τοῦτο μὲν γὰρ ἡ Σαλώμη χαλεπὴ καὶ δύσνους οὖσα τοῖς ἐκ Μαριάμμης οὐδὲ τὴν ἑαυτῆς θυγατέρα συνοικοῦσαν Ἀριστοβούλῳ θατέρῳ τῶν νεανίσκων εἴα τῇ τοῦ γάμου πρὸς ἐκεῖνον εὐνοίᾳ χρῆσθαι, λέγειν τε εἴ τι λαλήσειεν κατʼ ἰδίαν ἀναπείθουσα καὶ μηνύειν ἑαυτῇ κἀν τοῖς προσκρούμασιν, οἷα συμβαίνει, πολλὰς ὑποψίας εἰσάγουσα."},{"number":202,"text":"διʼ ὧν αὐτὴ μὲν ἅπαντα τὰ κατʼ ἐκείνους ἐμάνθανεν, δύσνουν δὲ τὴν παῖδα τῷ νεανίσκῳ πεποιήκει."},{"number":203,"text":"χαριζομένη δʼ ἐκείνη τῇ μητρὶ πολλάκις ἔλεγεν, ὡς μέμνηνται μὲν ἰδιάζοντες ἐκεῖνοι τῆς Μαριάμμης, ἐστυγήκασι δὲ τὸν πατέρα, συνεχὲς δὲ διαπειλοῦσιν, εἰ τύχοιεν αὐτοί ποτε τῆς ἀρχῆς, τοὺς μὲν ἐκ τῶν ἄλλων γυναικῶν παῖδας Ἡρώδῃ γεγενημένους κωμογραμματεῖς καταστήσειν· ἁρμόσειν γὰρ εἰς τοιαύτην χρείαν τὸ νῦν ἐπιμελὲς αὐτῶν καὶ πρὸς παιδείαν ἐσπουδασμένον."},{"number":204,"text":"τὰς δὲ γυναῖκας, εἴ ποτε καὶ ταύτας ἴδοιεν τοῦ μητρῴου κόσμου μετειληφυίας, ἀντὶ τῆς παρούσης ἁβρότητος ἀπειλεῖν, ὡς τρύχεσιν ἠμφιεσμέναι καθειργοῦνται μηδὲ τὸν ἥλιον βλέπουσαι."},{"number":205,"text":"ταῦτʼ εὐθὺς ἀπηγγέλλετο διὰ τῆς Σαλώμης τῷ βασιλεῖ· κἀκεῖνος ἤκουεν μὲν ἀλγεινῶς, ἐπειρᾶτο δὲ διορθοῦν, ἐκακοῦτο δὲ ταῖς ὑποψίαις καὶ χείρων ἀεὶ γινόμενος ἅπασιν κατὰ πάντων ἐπίστευεν. οὐ μὴν ἀλλὰ τότε μὲν ἐπιπλήξας τοῖς παισὶν ἀπολογησαμένων ῥᾴων εἰς τὸν καιρὸν ἐγίνετο, ταῖς δʼ ἑξῆς πολὺ χείρω προσέπεσεν."},{"number":206,"text":"Ὁ γὰρ Φερώρας ἐλθὼν παρὰ τὸν Ἀλέξανδρον ἔχοντα τὴν Ἀρχελάου θυγατέρα Γλαφύραν, ὡς ἐδηλώσαμεν, Σαλώμης ἔφη λεγούσης ἀκηκοέναι τὸν Ἡρώδην ἡττῆσθαι τοῦ τῆς Γλαφύρας ἔρωτος καὶ δυσπαρηγόρητον αὐτῷ τὴν ἐπιθυμίαν εἶναι."},{"number":207,"text":"τοῦτο οὖν ἐκεῖνος ἀκούσας ὑπό τε νεότητος καὶ ζηλοτυπίας ἐξεκαίετο καὶ τὰ κατὰ τιμὴν εἰς τὴν παῖδα γινόμενα παρʼ Ἡρώδου, πολλάκις δʼ ἦσαν αἱ τοιαῦται φιλοφρονήσεις, ἐπὶ τὸ χεῖρον ἐλάμβανεν ἐξ ὑπονοιῶν διὰ τὸν ἐκπεσόντα λόγον."},{"number":208,"text":"οὐκ ἐκαρτέρησέν τε τὴν ὀδύνην τοῦ πράγματος, ἀλλὰ ἐλθὼν πρὸς τὸν πατέρα καταμηνύει τὰ ὑπὸ τοῦ Φερώρα ῥηθέντα μετὰ δακρύων. Ἡρώδης δὲ πολὺ μᾶλλον ἐκπαθὴς γενόμενος καὶ τὸ σὺν αἰσχύνῃ τῆς διαβολῆς ἐψευσμένον οὐ φέρων ἐτετάρακτο."},{"number":209,"text":"καὶ πολλάκις μὲν ὠδύρετο τὴν πονηρίαν τῶν οἰκείων οἷος εἰς αὐτοὺς γενόμενος οἵων τυγχάνοι, μεταπέμπεται δὲ τὸν Φερώραν καὶ προσονειδίσας κάκιστε πάντων, εἶπεν, εἰς τοῦτο τῆς ἀμέτρου καὶ περιττῆς ἦλθες ἀχαριστίας, ὡς τοιαῦτα μὲν περὶ ἡμῶν νοῆσαι, τοιαῦτα δὲ λαλεῖν;"},{"number":210,"text":"ἆρʼ οὐχ ὁρῶ τὴν σὴν προαίρεσιν, ὡς οὐ βλασφημίας ἐστοχασμένος τοὺς τοιούτους λόγους τῷ παιδὶ προσήνεγκας, ἐπιβουλὴν δὲ καὶ φάρμακον αὐτοὺς ποιούμενος τῆς ἐμῆς ἀπωλείας; τίς γὰρ ἄν, εἰ μὴ δαιμόνων ἀγαθῶν ἔτυχεν, ὥσπερ οὗτος ὁ παῖς, ἠνέσχετο τὸν πατέρα μὴ τίσασθαι διὰ τοιαύτην ὑποψίαν;"},{"number":211,"text":"πότερον δὲ λόγον εἰς τὴν ψυχὴν ἢ ξίφος εἰς τὴν δεξιὰν ἐμβαλεῖν αὐτῷ δοκεῖς κατὰ τοῦ γεγεννηκότος; τί δέ σοι βούλεται τὸ μισοῦντά τε αὐτὸν καὶ τὸν ἀδελφὸν αὐτοῦ πρὸς μόνην τὴν κατʼ ἐμοῦ βλασφημίαν εὔνοιαν ὑποκρίνασθαι καὶ περὶ τούτων λέγειν, ἃ τῆς σῆς ἀσεβείας ἦν καὶ νοῆσαι καὶ διαβαλεῖν;"},{"number":212,"text":"ἔρρε κάκιστος εἰς εὐεργέτην καὶ ἀδελφὸν γενόμενος. καὶ σοὶ μὲν ἡ συνείδησις αὕτη συζήσειεν, ἐγὼ δὲ νικῴην ἀεὶ τοὺς ἐμοὺς μήτε ἀμυνόμενος κατʼ ἀξίαν καὶ μειζόνως εὐεργετῶν ἢ τυχεῖν εἰσι δίκαιοι."},{"number":213,"text":"Τοιαῦτα μὲν οὖν ὁ βασιλεύς. Φερώρας δʼ ἐπʼ αὐτοφώρῳ τῇ μοχθηρίᾳ Σαλώμην ἔφη ταῦτα συμπείσειν καὶ παρʼ ἐκείνης εἶναι τοὺς λόγους. ἡ δὲ ὡς μόνον ἤκουσεν, ἐτύγχανεν δὲ παροῦσα, πιθανῶς ἀνεβόησεν,"},{"number":214,"text":"ὡς οὐδὲν εἴη παρʼ αὐτῆς τοιοῦτον, καὶ ὅτι διὰ σπουδῆς ἐστιν ἅπασιν εἰς μῖσος ἀγαγεῖν αὐτὴν τοῦ βασιλέως καὶ πάντα τρόπον ἐνέχειν διὰ τὴν εὔνοιαν, ἣν ἔχοι περὶ τὸν Ἡρώδην ἀεὶ προγινώσκουσα τοὺς κινδύνους."},{"number":215,"text":"ἐν δὲ τῷ παρόντι καὶ μᾶλλον ἐπιβουλεύεσθαι· μόνη γὰρ ἀναπείθουσα τὸν ἀδελφὸν ἐκβάλλειν ἣν εἶχε γυναῖκα, λαμβάνειν δὲ θυγατέρα τὴν βασιλέως εἰκότως ὑπʼ ἐκείνου μεμισῆσθαι."},{"number":216,"text":"τοιαῦτα λεγούσης καὶ πολλάκις μὲν ἐπιδραττομένης τῶν τριχῶν, πολλάκις δὲ τυπτούσης τὰ στέρνα, ἡ μὲν ὄψις εἶχέ τι πρὸς τὴν ἄρνησιν πιθανόν, ἡ δὲ κακοήθεια τοῦ τρόπου τὴν ἐν τοῖς γινομένοις ὑπόκρισιν ἀπεσήμαινεν."},{"number":217,"text":"ὁ δὲ Φερώρας εἰς μέσον ἀπείληπτο μηδὲν εὔσχημον εἰς ἀπολογίαν ἔχων, εἰπεῖν μὲν ὡμολογηκώς, ἀκοῦσαι δʼ οὐ πιστευόμενος. ἐγένετο δʼ ἐπὶ πλεῖον ἥ τε σύγχυσις καὶ ἡ τῶν λόγων εἰς ἀλλήλους ἅμιλλα."},{"number":218,"text":"τέλος δὲ ὁ βασιλεὺς τόν τε ἀδελφὸν καὶ τὴν ἀδελφὴν μεμισηκὼς ἀπεπέμπετο καὶ τὸν υἱὸν ἐπαινέσας τῆς ἐγκρατείας καὶ τοῦ πρὸς αὐτὸν ἀνενεγκεῖν τοὺς λόγους ὀψὲ τῆς ὥρας περὶ θεραπείαν τοῦ σώματος ἐγένετο."},{"number":219,"text":"τοιαύτης δὲ τῆς μάχης ἐμπεσούσης κακῶς ἤκουσεν ἡ Σαλώμη· παρʼ αὐτῆς γὰρ ἐδόκει κεκινῆσθαι τὰ περὶ τὴν διαβολήν· αἵ τε τοῦ βασιλέως γυναῖκες ἤχθοντο φύσει δυσχερεστάτην εἰδυῖαι καὶ γινομένην ἄλλοτʼ ἄλλην κατὰ καιροὺς ἐχθρὰν καὶ φίλην. ἔλεγον οὖν ἀεί τι πρὸς τὸν Ἡρώδην κατʼ αὐτῆς καί τι συμπεσὸν ἐπὶ μεῖζον ἤγαγεν τὴν εἰς τοῦτο παρρησίαν."},{"number":220,"text":"Ἦν μὲν γὰρ ὁ τῆς Ἀραβίας βασιλεὺς Ὀβόδας ἀπράγμων καὶ νωθὴς τὴν φύσιν, Σύλλαιος δʼ αὐτῷ διῴκει τὰ πολλὰ δεινὸς ἀνὴρ καὶ τὴν ἡλικίαν νέος ἔτι καὶ καλός."},{"number":221,"text":"ὑπὸ χρείας οὖν τινος ἐλθὼν ὡς τὸν Ἡρώδην συνδειπνῶν εἶδεν τὴν Σαλώμην, καὶ τὸν νοῦν ἔσχεν πρὸς αὐτήν, γινώσκων δʼ ὅτι καὶ χήρα τυγχάνοι διελέγετο."},{"number":222,"text":"Σαλώμη δὲ καὶ χεῖρον ἢ πάλαι φερομένη παρὰ τἀδελφῷ καὶ τὸν νεανίσκον οὐκ ἀπαθῶς ὁρῶσα πρὸς τὸν γάμον ὥρμητο, ταῖς τε μεταξὺ φοιτώντων ἐπὶ τὸ δεῖπνον ἐνεφαίνετο πλείω τε καὶ μὴ μέτρια τῆς ἐκείνων πρὸς ἀλλήλους ὁμολογίας."},{"number":223,"text":"ταῦτα δὲ αἱ γυναῖκες ἀνέφερον τῷ βασιλεῖ διαγελῶσαι τὴν ἀσχημοσύνην, Ἡρώδης δὲ καὶ παρὰ τοῦ Φερώρα προσεπυνθάνετο καὶ τηρεῖν ἠξίου παρὰ τὸ δεῖπνον, πῶς τὰ πρὸς ἀλλήλους ἐσχήκασιν. ἐκεῖνος δὲ ἀπήγγελλεν, ὅτι καὶ νεύμασιν καὶ βλέμμασιν οὐκ ἄδηλοι τῆς ὁρμῆς εἰσιν ἀμφότεροι."},{"number":224,"text":"μετὰ τοῦτο ὁ μὲν Ἄραψ ὕποπτος ὢν ἀπῄει· διαλιπὼν δὲ δύο μῆνας ἢ τρεῖς ἔρχεται πάλιν ὡς ἐπʼ αὐτῷ τούτῳ καὶ λόγους Ἡρώδῃ προσέφερεν, ἀξιῶν αὐτῷ τὴν Σαλώμην δοθῆναι πρὸς γάμον· ἔσεσθαι γὰρ οὐκ ἀλυσιτελὲς τὸ κῆδος ἐπιμιξίᾳ τῆς τῶν Ἀράβων ἀρχῆς, ἣν αὐτῷ καὶ νῦν ἤδη παρεῖναι δυνάμει καὶ μᾶλλον ὀφείλεσθαι."},{"number":225,"text":"τοῦ δὲ Ἡρώδου τὸν λόγον ἀναφέροντος καὶ πυνθανομένου τῆς ἀδελφῆς, εἰ πρὸς τὸν γάμον ἑτοίμως ἔχει, ταχέως μὲν ἐκείνη προσήκατο, Σύλλαιος δὲ ἀξιούντων αὐτὸν ἐγγραφῆναι τοῖς τῶν Ἰουδαίων ἔθεσι καὶ τότε γαμεῖν, ἄλλως γὰρ οὐκ εἶναι δυνατόν, οὐχ ὑπομείνας, ἀλλὰ καὶ καταλευσθήσεσθαι πρὸς τῶν Ἀράβων εἰπών, εἰ τοῦτο πράξειεν, ἀπαλλάττεται."},{"number":226,"text":"Σαλώμην οὖν ὅ τε Φερώρας ἤδη διέβαλλεν εἰς ἀκρασίαν καὶ μᾶλλον αἱ γυναῖκες, λέγουσαι κοινωνίαν αὐτῇ γενέσθαι πρὸς τὸν Ἄραβα."},{"number":227,"text":"τήν τε κόρην, ἣν τἀδελφῷ κατενεγύησεν ὁ βασιλεύς, ἣν ὁ μὲν Φερώρας οὐκ ἔλαβεν, ὡς προεῖπον, ἡττημένος τῆς γυναικός, αἰτούσης Σαλώμης εἰς τὸν υἱὸν τὸν ἐκ Κοστοβάρου γενόμενον ὥρμητο μὲν ἐκείνῳ συνοικίσαι,"},{"number":228,"text":"μεταπείθεται δὲ ὑπὸ τοῦ Φερώρα τόν τε νεανίσκον οὐκ εὔνουν ἔσεσθαι λέγοντος διὰ τὴν ἀπώλειαν τοῦ πατρὸς καὶ δικαιότερον εἶναι λαβεῖν τὸν αὐτοῦ παῖδα τῆς τετραρχίας ὄντα διάδοχον. οὕτω δὲ συγγνώμην ᾐτεῖτο καὶ μὴ πείσας οὕτως. ἐκείνη μὲν οὖν ἀντιμετατεθείσης τῆς ἐγγύης ἐγαμεῖτο τῷ Φερώρα μειρακίῳ φερνὴν ἐπιδόντος ἑκατὸν τάλαντα τοῦ βασιλέως."}],"8":[{"number":229,"text":"Οὐκ ἀνεῖτο δὲ τὰ κατὰ τὴν οἰκίαν ἀεὶ καὶ μείζους τὰς ταραχὰς λαμβάνοντα, καὶ συμπίπτει τι τοιοῦτον ἐξ αἰτίας μὲν οὐκ εὐπρεποῦς, χωρῆσαν δὲ πρόσω κατὰ δυσχέρειαν·"},{"number":230,"text":"ἦσαν εὐνοῦχοι τῷ βασιλεῖ διὰ κάλλος οὐ μετρίως ἐσπουδασμένοι. τούτων ὁ μὲν οἰνοχοεῖν, ὁ δὲ δεῖπνον προσφέρειν, ὁ δὲ κατακοιμίζειν βασιλέα πεπίστευτο καὶ τὰ μέγιστα τῶν ἐν ταῖς ἀρχαῖς."},{"number":231,"text":"καί τις ἀγγέλλει τῷ βασιλεῖ διαφθαρῆναι τούτους ὑπὸ Ἀλεξάνδρου τοῦ παιδὸς ἐπὶ πολλοῖς χρήμασιν. ἀνακρίναντι δὲ περὶ μὲν τῆς γεγενημένης πρὸς αὐτὸν κοινωνίας καὶ μίξεως ὡμολόγουν, ἄλλο δὲ οὐδὲν δυσχερὲς εἰς τὸν πατέρα συνειδέναι."},{"number":232,"text":"βασανιζόμενοι δὲ μᾶλλον κἀν ταῖς ἀνάγκαις ὄντες ἐπιτεινόντων ἀεὶ τῶν ὑπηρετῶν καὶ χαριζομένων τῷ Ἀντιπάτρῳ τὸ τοιοῦτον, ἔλεγον ὡς εἴη δυσμένεια πρὸς τὸν πατέρα καὶ μῖσος ἔμφυτον Ἀλεξάνδρῳ."},{"number":233,"text":"παραινοίη δʼ αὐτοῖς Ἡρώδην μὲν ἀπεγνωκέναι περιττὸν ἤδη τετυχηκότα καὶ τῷ γήρᾳ παρακάλυμμα τοῦ χρόνου ποιούμενον, μελαίνοντα τὰς τρίχας καὶ κλέπτοντα τὸν ἔλεγχον τῆς ἡλικίας· εἰ δʼ αὐτῷ προσέχοιεν τὸν νοῦν, περιγενομένης τῆς βασιλείας, ἣν καὶ μὴ βουλομένου τοῦ πατρὸς οὐκ ἄλλου τινὸς εἶναι, ταχὺ τὸν πρῶτον ἕξειν ἐν αὐτῇ τόπον·"},{"number":234,"text":"οὐ γὰρ μόνον διὰ τὸ γένος, ἀλλʼ ἤδη καὶ ταῖς παρασκευαῖς ἕτοιμον αὐτῷ τὸ κρατεῖν εἶναι· πολλοὶ μὲν γὰρ τῶν ἡγεμόνων, πολλοὶ δὲ τῶν φίλων συνεστᾶσιν οὐχὶ πονηροὶ πᾶν ὁτιοῦν καὶ δρᾶν καὶ πάσχειν."},{"number":235,"text":"Τούτων τῶν λόγων ἀκούσας Ἡρώδης ὅλος ἐγένετο τῆς ἐπηρείας καὶ τοῦ δέους, τὰ μὲν εἰς ὕβριν ῥηθέντα χαλεπῶς, τὰ δʼ εἰς ὑπόνοιαν οὐκ ἀκινδύνως ἐκλαβών, ὥστε καὶ μᾶλλον ἐξ ἀμφοτέρων ἠρεθίζετο καὶ πικρὸς ὢν ἐδεδοίκει, μὴ καί τι ταῖς ἀληθείαις συνέστηκεν ἐπʼ αὐτὸν ἰσχυρότερον ἢ φυλάξασθαι πρὸς ἐκεῖνον τὸν καιρόν."},{"number":236,"text":"ἔνθεν οὐδʼ ἐκ φανεροῦ τὴν ἔρευναν ἐποιεῖτο, κατασκόπους δὲ τῶν ὑπονοουμένων διέπεμψεν. ὑποψία τε καὶ μίση πρὸς ἅπαντας ἦν, καὶ τὴν ὑπόνοιαν ἐπʼ ἀσφαλείᾳ λαμβάνων πολλὴν καὶ κατὰ τῶν οὐκ ἀξίων αὐτῇ χρώμενος διετέλει."},{"number":237,"text":"πέρας τε οὐδὲν ἦν, ἀλλὰ μένειν οἱ νομιζόμενοι μᾶλλον ὡς ἂν καὶ μᾶλλον ἰσχύοντες ἐδόκουν αὐτῷ φοβεροί· τοῖς δʼ οἷς οὐκ ἦν συνήθεια πλείων ὀνομάσαι μόνον ἐδόκει, καὶ μέρος εὐθὺς ἀσφαλείας ἐδόκουν ἀπολλύμενοι."},{"number":238,"text":"τέλος τε οἱ περὶ αὐτὸν ἐν τῷ μηδὲν ἔχειν βέβαιον εἰς ἐλπίδα σωτηρίας ἐπʼ ἀλλήλους ἐτράπησαν, νομίζοντες μέν, εἰ φθάσας ἕτερος τὸν ἕτερον διαβάλοι, τοῦτʼ αὐτῷ πρὸς σωτηρίαν φέρειν, ἐπίφθονοι δʼ εἴ ποτε τύχοιεν ὧν ἠξίουν γενόμενοι καὶ τὸ δικαίως αὐτοὶ παθεῖν ἐφʼ οἷς ἄλλους ἠδίκησαν προσλαμβάνοντες μόνον."},{"number":239,"text":"ἤδη γοῦν οἰκείας τινὲς ἔχθρας ἐπεξῄεσαν τῷ τοιούτῳ τρόπῳ καὶ καταφωραθέντες ἐν τοῖς ὁμοίοις ἐγένοντο, τὸν καιρὸν ὥσπερ ὄργανον καὶ πάγην ἐπὶ τοὺς ἐχθροὺς νοοῦντες καὶ συναλισκόμενοι τῇ πείρᾳ, καθʼ ἣν ἑτέροις ἐπεβούλευον."},{"number":240,"text":"ἥ τε γὰρ μετάνοια τῷ βασιλεῖ ταχὺ διὰ τὸ μὴ προφανῶς ἁμαρτάνοντας ἀναιρεῖν ἐπεγίνετο καὶ ταύτης τὸ χαλεπὸν οὐκ εἰς τὸ παύσασθαι τὰ ὅμοια δρᾶν, ἀλλʼ εἰς τὸ τιμωρήσασθαι τοῖς ἴσοις τοὺς ἐνδειξαμένους ἀπηρτίζετο."},{"number":241,"text":"Τοιαύτη μὲν ἦν τῶν περὶ τὴν αὐλὴν ταραχή. πολλοῖς δὲ τῶν φίλων ἤδη καὶ τοῦτʼ αὐτὸ προεῖπεν, ὡς οὔτʼ ἐμφανίζεσθαι δέον αὐτῷ λοιπὸν οὔτʼ εἰς τὸ βασίλειον εἰσιέναι. ταύτην δὲ τὴν παραγγελίαν ἐποιεῖτο καθʼ ὧν ἡ παρρησία ἐλάττονος ἢ πλείονος ἐντροπῆς μετειλήφει·"},{"number":242,"text":"καὶ γὰρ Ἀνδρόμαχον καὶ Γέμελλον ἄνδρας ἄνωθεν φίλους αὐτῷ, καὶ πολλὰ μὲν περὶ τὰς βασιλικὰς χρείας ἔν τε πρεσβείαις καὶ συμβουλίαις ὀνήσαντας αὐτοῦ τὸν οἶκον, συμπαιδεύσαντας δὲ τοὺς υἱοὺς καὶ τί γὰρ ἢ πρῶτον παρρησίας τόπον ἐσχηκότας παρῃτήσατο τότε,"},{"number":243,"text":"τὸν μὲν, ὅτι Δημήτριος ὁ παῖς αὐτοῦ συνήθης ἦν Ἀλεξάνδρῳ, Γέμελλον δὲ εὔνουν ἐπιστάμενος ἐκείνῳ· καὶ γὰρ ἐν ταῖς τροφαῖς κἀν τῇ παιδείᾳ παραγεγόνει καὶ τὴν ἐν τῇ Ῥώμῃ συνδιέτριβεν ἀποδημίαν. παρῃτήσατο δὲ καὶ τούτους ἡδέως μὲν ἂν καὶ χεῖρον, ὑπὸ δὲ τοῦ μὴ κατʼ ἀνδρῶν οὐκ ἀσήμων ἔχειν τὴν ἄχρι τοσούτων παρρησίαν τήν τε τιμὴν καὶ τὸ δύνασθαι κωλύειν ἁμαρτάνοντας παραιρούμενος"},{"number":244,"text":"Ἦν δὲ τούτων ἁπάντων αἴτιος Ἀντίπατρος, ὃς ἐπειδὴ τὸ νενοσηκὸς τῆς τοῦ πατρὸς παρρησίας κατέμαθεν, ἔκπαλαι μὲν συνεδρεύων αὐτῷ προσέκειτο καὶ μᾶλλον ἐδόκει τι περαίνειν, τῶν ἀντέχειν δυναμένων ἕκαστος εἰ ὑπεξαιρεθείη."},{"number":245,"text":"τότε γοῦν τῶν περὶ τὸν Ἀνδρόμαχον ἀπελαθέντων λόγου καὶ παρρησίας πρῶτον μὲν ὁ βασιλεὺς ὅσους ᾤετο πιστοὺς Ἀλεξάνδρῳ βασάνοις ἀνέκρινεν, εἴ τι κατʼ αὐτοῦ τολμηθὲν εἰδείησαν· οἱ δὲ ἀπέθνησκον οὐδὲν ἔχοντες λέγειν."},{"number":246,"text":"τῷ δʼ ἦν φιλονεικίας αἴτιον, εἰ μή τι τοιοῦτον οἷον ἐδόκει κακῶς εὑρίσκοιτο, καὶ δεινὸς Ἀντίπατρος τὸν μὲν ὑπʼ αὐτῆς τῆς ἀληθείας ἀναίτιον εἰς ἐγκράτειαν καὶ πίστιν διαβαλεῖν, ἐπιπαροξῦναι δὲ ζητεῖν ἐκ πλειόνων τὸ λανθάνον τῆς ἐπιχειρήσεως."},{"number":247,"text":"καί τις ἐν πολλοῖς τοῖς βασανιζομένοις εἶπεν, ὡς εἰδείη τὸν νεανίσκον λέγοντα πολλάκις, ὅταν ἐπαινούμενος αὐτὸς τύχῃ τό τε σῶμα ὡς εἴη μέγας καὶ τὴν τοξικὴν εὔστοχος καὶ τἆλλα τὰ πρὸς ἀρετὴν ὑπὲρ ἅπαντας, ὅτι ταῦτʼ αὐτῷ κακὰ μᾶλλον ἤπερ ἀγαθὰ παρὰ τῆς φύσεώς ἐστιν· ἄχθεσθαι γὰρ ἐπʼ αὐτοῖς τὸν πατέρα καὶ φθονεῖν,"},{"number":248,"text":"αὐτός τε ὅταν μὲν ἅμα περιπατῶν συστέλλειν αὑτὸν καὶ καθαιρεῖν ὡς μὴ μείζων ὁρᾶσθαι, τοξεύων δὲ ἐν τοῖς κυνηγεσίοις ἐκείνου παρόντος ἀπὸ σκοποῦ ῥίπτειν· τὴν γὰρ φιλοτιμίαν εἰδέναι τοῦ γεγεννηκότος τούτων εὐδοκιμούντων."},{"number":249,"text":"βασανιζομένῳ τῷ τε λόγῳ καὶ προσγινομένης ἀνέσεως τῷ σώματι προσετίθει δʼ ὅτι καὶ συνεργὸν ἔχων τὸν ἀδελφὸν Ἀριστόβουλον ἐν κυνηγεσίῳ λοχήσας φεύγειν εἰς Ῥώμην, ἐπειδὰν τοῦτʼ αὐτῷ πραχθῇ, τὴν βασιλείαν αἰτησόμενος."},{"number":250,"text":"εὑρέθη δὲ καὶ γράμματα τοῦ νεανίσκου πρὸς τὸν ἀδελφόν, ἐν οἷς ἐμέμφετο τὸν πατέρα μὴ δίκαια ποιεῖν, Ἀντιπάτρῳ χώραν ἀπονέμοντα πρόσοδον διακοσίων ταλάντων φέρουσαν."},{"number":251,"text":"ἐπὶ τούτοις εὐθὺς μὲν ἔδοξέν τι πιστὸν ἔχειν Ἡρώδης, ὡς ᾤετο, κατὰ τῆς τῶν παίδων ὑποψίας καὶ συλλαβὼν ἔδησεν τὸν Ἀλέξανδρον. αὖθις δὲ οὐκ ἀνίει χαλεπὸς ὤν, τὰ μὲν οὐδʼ οἷς ἤκουσεν ἄγαν πεπιστευκώς· ἀναλογιζομένῳ γὰρ ἄξιον μὲν ἐπιβουλῆς ἐξ αὐτῶν οὐδὲν ἐφαίνετο, μέμψεις δὲ καὶ νεανικαὶ φιλοτιμίαι, καὶ τὸ κτείναντα φανερῶς εἰς τὴν Ῥώμην ὁρμᾶν ἀπίθανον."},{"number":252,"text":"ἠξίου δὲ καὶ μεῖζόν τι λαβεῖν τῆς περὶ τὸν υἱὸν παρανομίας τεκμήριον καὶ φιλόνεικος ἦν μὴ δόξαι προπετῶς τὰ δεσμὰ κατεγνωκέναι. τῶν τε φίλων τῶν Ἀλεξάνδρου βασανίζων τοὺς ἐν τέλει διέφθειρεν αὐτῶν οὐκ ὀλίγους οὐδὲν εἰπόντας ὧν ἐκεῖνος ᾤετο."},{"number":253,"text":"πολλῆς δὲ τῆς εἰς τὸ τοιοῦτον ἑτοιμότητος οὔσης καὶ φόβου καὶ ταραχῆς περὶ τὸ βασίλειον, εἷς τις τῶν νεωτέρων ὡς ἐν ταῖς ἀνάγκαις ἐγένετο, διαπέμπειν ἔφη τοῖς ἐν Ῥώμῃ φίλοις τὸν Ἀλέξανδρον ἀξιοῦντα κληθῆναι θᾶττον ὑπὸ Καίσαρος· ἔχειν γὰρ αὐτῷ πρᾶξιν ἐπʼ αὐτὸν συνισταμένην μηνῦσαι Μιθριδάτην τὸν βασιλέα Πάρθων τοῦ πατρὸς ᾑρημένου κατὰ Ῥωμαίων φίλον· εἶναι δʼ αὐτῷ καὶ φάρμακον ἐν Ἀσκάλωνι παρεσκευασμένον."},{"number":254,"text":"Τούτοις ἐπίστευσεν Ἡρώδης καί τινα παραμυθίαν τῆς προπετείας εἴληφεν ἐν τοῖς κακοῖς ὑπὸ τῶν χειρόνων κολακευόμενος. καὶ τὸ μὲν φάρμακον εὐθὺς ἐσπουδακότι ζητεῖν οὐχ εὑρέθη."},{"number":255,"text":"τὴν δʼ ὑπερβολὴν τῶν κακῶν Ἀλέξανδρος ἐκ φιλονεικίας ἐπιρρῶσαι θέλων εἰς μὲν ἄρνησιν οὐκ ἐτράπετο, μετῄει δὲ τὴν προπέτειαν τοῦ πατρὸς ἁμαρτίᾳ μείζονι, τάχα δὲ καὶ διὰ τούτου βουλόμενος δυσωπῆσαι τὸ πρὸς τὰς διαβολὰς ἕτοιμον, οὐχ ἥκιστα δὲ εἰ καὶ ἔτυχεν πιστευθεὶς κακοῦν αὐτόν τε καὶ πᾶσαν τὴν βασιλείαν προῃρημένος."},{"number":256,"text":"γράμματα γὰρ γράψας ἐν βιβλίοις τέσσαρσιν ἀπέστειλεν, ὡς οὐδὲν δεῖ βασανίζειν οὐδὲ περαιτέρω χωρεῖν· γενέσθαι γὰρ τὴν ἐπιβουλὴν καὶ ταύτης συλλαμβάνειν τόν τε Φερώραν καὶ τοὺς πιστοτάτους αὐτῷ τῶν φίλων, Σαλώμην δὲ καὶ νύκτωρ ἐπεισελθοῦσαν ἄκοντι μιγῆναι·"},{"number":257,"text":"καὶ πάντας ἐπὶ ταὐτὸν ἥκειν τοὺς θᾶττον ἐκεῖνον ἐκποδὼν ποιησαμένους ἄδειαν τῆς ἀεὶ προσδοκίας ἔχειν. ἐν τούτοις καὶ Πτολεμαῖος διεβέβλητο καὶ Σαπίννιος οἱ πιστότατοι τῷ βασιλεῖ."},{"number":258,"text":"καὶ τί γὰρ ἢ καθάπερ λύττης τινὸς ἐμπεσούσης κατʼ ἀλλήλων οἱ πάλαι φίλτατοι τεθηρίωντο, μήτʼ ἀπολογίας μήτʼ ἐλέγχου τόπον ἕως ἀληθείας ἐχόντων, ἀλλʼ ἀεὶ γινομένης ἀκρίτου τινὸς εἰς ἅπαντας ἀπωλείας, καὶ τῶν μὲν δεσμά, τῶν δὲ θανάτους, τῶν δὲ τὸ ταῦτα μέλλειν ἐπʼ αὐτοῖς ὀδυρομένων, ἡσυχία τε καὶ κατήφεια τὸ βασίλειον ἀπεκόσμει τῆς πρώτης εὐδαιμονίας."},{"number":259,"text":"καὶ χαλεπὸς ἦν Ἡρώδῃ πᾶς ὁ βίος ἐκτεταραγμένῳ καὶ τὸ μηδενὶ πιστεύειν μέγα τῆς προσδοκίας κολαστήριον ἔχοντι· πολλάκις γοῦν ὡς ἐπανιστάμενον αὐτῷ τὸν υἱὸν ἢ καὶ ξιφήρη παρεστῶτα διὰ φαντασίας ἐλάμβανεν."},{"number":260,"text":"οὕτως ἡ ψυχὴ καὶ νύκτα καὶ ἡμέραν πρὸς τούτῳ γινομένη πάθος ἀνεμάξατο μανίας οὐχ ἧττον δὲ καὶ ἀνοίας. καὶ τὰ περὶ ἐκεῖνον εἶχεν οὕτως."},{"number":261,"text":"Ἀρχέλαος δὲ ὁ τῶν Καππαδόκων βασιλεύς, ὡς ἐπύθετο τὰ κατὰ τὸν Ἡρώδην, ἀγωνιῶν τε ὑπὲρ τῆς θυγατρὸς καὶ τοῦ νεανίσκου καὶ συναλγῶν ἀνδρὶ φίλῳ τῆς ἐπὶ τοσόνδε ταραχῆς, ἧκεν οὐκ ἐν παρέργῳ θέμενος τὰ πράγματα."},{"number":262,"text":"καὶ καταλαβὼν οὕτως ἔχοντα τὸ μὲν ἐπιτιμᾶν ἢ φάναι γενέσθαι τι προπετὲς αὐτῷ τελέως ἀνοίκειον εἰς τὸν καιρὸν ἡγήσατο· φιλονεικήσειν γὰρ κεκακωμένον καὶ μᾶλλον ἀπολογεῖσθαι σπεύδοντα πλείονος ὀργῆς ἀναπλησθήσεσθαι·"},{"number":263,"text":"μετῄει δὲ τάξιν ἑτέραν τὴν ἐπανόρθωσιν τῶν ἠτυχημένων, ὀργιζόμενος τῷ νεανίσκῳ κἀκεῖνον ἐπιεικῆ λέγων τῷ μηδὲν ἐκ προπετείας ἐργάσασθαι, τόν τε γάμον διαλύσειν ἔφη πρὸς τὸν Ἀλέξανδρον, καὶ μηδʼ ἂν τῆς θυγατρὸς φείσασθαι, εἴ τι συνειδυῖα τούτῳ οὐ κατεμήνυσεν."},{"number":264,"text":"τοιούτου δʼ ὄντος οὐ κατὰ προσδοκίαν ὧν Ἡρώδης ᾤετο, τὸ δὲ πλέον ὑπὲρ αὐτοῦ τὴν ὀργὴν ἐπιδεικνυμένου, μετέπιπτεν ὁ βασιλεὺς τῆς χαλεπότητος καὶ λαβὼν ἐκ τοῦ δικαίου δοκεῖν τὰ πεπραγμένα πεποιηκέναι κατὰ μικρὸν εἰς τὸ τοῦ πατρὸς ἀντιμεθίστατο πάθος."},{"number":265,"text":"οἰκτρὸς δʼ ἦν ἐν ἀμφοτέροις, ὅτε μὲν ἀπελύοντό τινες τὰς τοῦ νεανίσκου διαβολὰς εἰς ὀργὴν ἐκταραττόμενος, ἐπειδὴ δὲ Ἀρχέλαος συγκατηγόρει, πρὸς δάκρυα καὶ λύπην οὐκ ἀπαθῆ μεθιστάμενος· ἐδεῖτο γοῦν ἐκείνου μήτε διαλύειν τὸν γάμον ὀργῆς τε ἔλαττον ἔχειν ἐφʼ οἷς ὁ νεανίσκος ἠδίκησεν."},{"number":266,"text":"Ἀρχέλαος δὲ παραλαβὼν ἐπιεικέστερον εἴς τε τοὺς φίλους μετέφερεν τὰς διαβολάς, ἐκείνων εἶναι λέγων νέον ὄντα καὶ κακοηθείας ἀναίσθητον διαφθεῖραι, τόν τε ἀδελφὸν αὐτῷ μᾶλλον εἰς ὑποψίαν καθίστη·"},{"number":267,"text":"τοῦ γὰρ Ἡρώδου χαλεπῶς καὶ πρὸς τὸν Φερώραν ἔχοντος ὁ μὲν ἀπορίᾳ τοῦ διαλλάξοντος Ἀρχέλαον ὁρῶν μάλιστα δυνάμενον αὐτὸς τυχὼν πρὸς ἐκεῖνον ἐτράπετο μελανείμων καὶ πάντα τὰ σημεῖα τῆς μετὰ μικρὸν ἀπωλείας ἔχων,"},{"number":268,"text":"Ἀρχέλαος δὲ οὔτε ὑπερεῖδεν τὴν ἔντευξιν οὔτʼ ἔφη δυνατὸς εἶναι ταχὺ μεταπείθειν οὕτως ἔχοντα τὸν βασιλέα· βέλτιον δὲ εἶναι αὐτῷ προσιέναι καὶ δεῖσθαι, τῶν πάντων αἴτιον αὑτὸν ὁμολογοῦντα· ὠφελήσειν γὰρ οὕτως τοῦ θυμοῦ τὸ περιττόν, αὐτὸς δὲ συλλήψεσθαι παρών."},{"number":269,"text":"ταῦτα δὲ πεισθέντος αὐτοῦ συναμφότερον ἦν διαπεπραγμένον, αἵ τε διαβολαὶ παρὰ δόξαν ἀφῄρηντο τοῦ νεανίσκου καὶ Φερώραν Ἀρχέλαος διαλλάξας οὕτως εἰς Καππαδοκίαν ἀπῄει, κεχαρισμένος ὡς οὐκ ἄλλος ἐν τῇ τότε περιστάσει τῶν καιρῶν Ἡρώδῃ γενόμενος. ὅθεν καὶ δώροις αὐτὸν ἐτίμησεν πολυτελεστάτοις κἀν τοῖς ἄλλοις μεγαλοπρεπῶς ἐν τοῖς μάλιστα φίλτατον ἡγησάμενος."},{"number":270,"text":"ἐποιήσατο δὲ καὶ συνθήκας εἰς Ῥώμην ἐλθεῖν, ἐπειδὴ περὶ τούτων ἐγέγραπτο Καίσαρι, καὶ μέχρις Ἀντιοχείας ἐπὶ τὸ αὐτὸ παρῆλθον. ἐκεῖ καὶ τὸν ἡγεμόνα Συρίας Τίτιον ἐκ διαφορᾶς Ἀρχελάῳ κακῶς ἔχοντα διήλλαξεν Ἡρώδης καὶ πάλιν εἰς Ἰουδαίαν ὑποστρέφει."}],"9":[{"number":271,"text":"Γενομένῳ δὲ ἐν τῇ Ῥώμῃ κἀκεῖθεν ἐπανήκοντι συνέστη πόλεμος πρὸς τοὺς Ἄραβας ἐξ αἰτίας τοιαύτης· οἱ κατοικοῦντες τὸν Τράχωνα Καίσαρος ἀφελομένου Ζηνόδωρον καὶ προσθέντος Ἡρώδῃ τὴν χώραν λῃστεύειν μὲν οὐκ εἶχον ἐξουσίαν ἔτι, γεωργεῖν δὲ καὶ ζῆν ἡμέρως ἠναγκάζοντο."},{"number":272,"text":"τόδʼ ἦν ἐκείνοις οὐχ αἱρετὸν οὐδὲ λυσιτέλειαν ἔφερεν ἡ γῆ πονούντων. ὅμως δὲ κατʼ ἀρχὰς μὲν οὐκ ἐπιτρέποντος τοῦ βασιλέως ἀπείχοντο τῶν εἰς τοὺς περιοίκους ἀδικημάτων, καὶ πολλὴ διὰ τοῦτο ἦν εὐδοξία τῆς ἐπιμελείας Ἡρώδῃ."},{"number":273,"text":"πλεύσαντος δʼ εἰς τὴν Ῥώμην, ὅτε καὶ τοῦ παιδὸς Ἀλεξάνδρου κατηγόρει καὶ παραθησόμενος Ἀντίπατρον τὸν υἱὸν παρεληλύθει Καίσαρι, λόγον ὡς ἀπολωλὼς εἴη διασπείροντες οἱ τὸν Τράχωνα νεμόμενοι τῆς τε ἀρχῆς ἀπέστησαν καὶ πάλιν ἐπὶ τὰ συνήθη τοὺς πλησιοχώρους ἀδικεῖν ἐτρέποντο."},{"number":274,"text":"τότε μὲν οὖν αὐτοὺς οἱ στρατηγοὶ τοῦ βασιλέως ἀπόντος ἐχειρώσαντο. περὶ τετταράκοντα δέ τινες ἀρχιλῃσταὶ κατὰ δέος τῶν ἡλωκότων ἐξέλιπον μὲν τὴν χώραν,"},{"number":275,"text":"εἰς δὲ τὴν Ἀραβίαν ἀφορμήσαντες Συλλαίου δεξαμένου μετὰ τὴν ἀποτυχίαν τοῦ Σαλώμης γάμου, τόπον τε ἐρυμνὸν ἐκείνου δόντος ᾤκησαν καὶ κατατρέχοντες οὐ μόνον τὴν Ἰουδαίαν ἀλλὰ καὶ τὴν κοίλην Συρίαν ἅπασαν ἐλῄζοντο, παρέχοντος ὀρμητήρια τοῦ Συλλαίου καὶ κακῶς ποιοῦσιν ἄδειαν."},{"number":276,"text":"Ἡρώδης δὲ ἐπανελθὼν ἀπὸ τῆς Ῥώμης ἔγνω πολλὰ τῶν οἰκείων αὐτῷ κεκακωμένα, καὶ τῶν μὲν λῃστῶν ἐγκρατὴς γενέσθαι οὐκ ἠδυνήθη διὰ τὴν ἀσφάλειαν, ἣν ἐκ τῆς τῶν Ἀράβων προστασίας ἐπορίσαντο, χαλεπῶς δὲ ἔχων αὐτὸς τῶν ἀδικημάτων περιελθὼν τὸν Τράχωνα τοὺς οἰκείους αὐτῶν ἀπέσφαξεν."},{"number":277,"text":"ἐντεῦθεν ἐκεῖνοι καὶ μᾶλλον πρὸς ὀργὰς ὧν ἐπεπόνθεισαν ὄντος αὐτοῖς καὶ νόμου πάντα τρόπον ἐπεξιέναι τοὺς τῶν οἰκείων φονεῖς ἀνυποτιμήτως τὴν Ἡρώδου πᾶσαν ἄγοντες καὶ φέροντες διετέλουν. ἐκεῖνος δὲ διελέγετο περὶ τούτων τοῖς Καίσαρος ἡγεμόσιν Σατορνίνῳ τε καὶ Οὐολομνίῳ ἐπὶ κολάσει τοὺς λῃστὰς ἐξαιτούμενος."},{"number":278,"text":"ὅθεν ἔτι καὶ μᾶλλον ἰσχυρῶς ἐχόντων πλείους μὲν ἐγίνοντο, πάντα δὲ ἐτάραττον ἐπʼ ἀναστάσει τῆς Ἡρώδου βασιλείας χωρία καὶ κώμας πορθοῦντες καὶ τοὺς λαμβανομένους τῶν ἀνθρώπων ἀπέσφαττον, ὡς εἶναι πολέμῳ τὴν ἀδικίαν ἐοικυῖαν· ἐγεγόνεισαν γὰρ ἤδη περὶ χιλίους."},{"number":279,"text":"ἐφʼ οἷς ἀχθόμενος Ἡρώδης τούς τε λῃστὰς ἐξῄτει καὶ χρέος ὃ διὰ Συλλαίου δανείσας ἔτυχεν Ὀβάδᾳ τάλαντα ἑξήκοντα, παρηκούσης αὐτῷ τῆς προθεσμίας ἀπολαβεῖν ἠξίου."},{"number":280,"text":"Σύλλαιος δὲ τὸν μὲν Ὀβάδαν παρεωσμένος αὐτὸς δὲ ἅπαντα διοικῶν τούς τε λῃστὰς ἔξαρνος ἦν μὴ κατὰ τὴν Ἀραβίαν εἶναι καὶ περὶ τῶν χρημάτων ἀνεβάλλετο, περὶ ὧν ἐπί τε Σατορνίνου καὶ Οὐολομνίου τῶν Συρίας ἐπιστατούντων ἐγίνοντο λόγοι."},{"number":281,"text":"τέλος δὲ συνέθεντο διʼ ἐκείνων ἐντὸς ἡμερῶν τριάκοντα τά τε χρήματα τὸν Ἡρώδην ἀπολαβεῖν καὶ τοὺς ἀλλήλων ἐν ἑκατέρᾳ τῇ βασιλείᾳ καὶ παρὰ μὲν Ἡρώδῃ τῶν Ἀράβων οὐδεὶς εὑρέθη τὸ σύνολον οὔτε ἐπʼ ἀδικίας οὔτε κατʼ ἄλλον τρόπον, οἱ δʼ Ἄραβες ἠλέγχοντο τοὺς λῃστὰς παρʼ αὐτοῖς ἔχειν."},{"number":282,"text":"Διελθούσης δὲ τῆς προθεσμίας Σύλλαιος οὐδὲν τῶν δικαίων πεποιηκὼς εἰς Ῥώμην ἀνέρχεται. ῥύσια δὲ τῶν χρημάτων καὶ τῶν παρʼ ἐκείνοις λῃστῶν Ἡρώδης ἐποιεῖτο,"},{"number":283,"text":"καὶ τῶν περὶ τὸν Σατορνῖνον καὶ Οὐολόμνιον ἐπιτρεπόντων ἀγνωμονοῦντας ἐπεξιέναι στρατιάν τε ἔχων προήγαγεν εἰς τὴν Ἀραβίαν τρισὶν ἡμέραις ἑπτὰ σταθμοὺς διανύσας, καὶ γενόμενος ἐπὶ τοῦ φρουρίου τοῦ τοὺς λῃστὰς ἔχοντος αἱρεῖ μὲν ἐξ ἐφόδου πάντας αὐτούς, κατασκάπτει δὲ τὸ χωρίον Ῥάεπτα καλούμενον· τῶν δὲ ἄλλων οὐδὲν ἐλύπησεν."},{"number":284,"text":"ἐκβοηθησάντων δὲ τῶν Ἀράβων ἡγουμένου Νακέβου μάχη γίνεται, καθʼ ἣν ὀλίγοι μὲν τῶν Ἡρώδου, Νάκεβος δὲ ὁ τῶν Ἀράβων στρατηγὸς καὶ περὶ εἰκοσιπέντε τῶν σὺν αὐτῷ πίπτουσιν, οἱ δὲ ἄλλοι πρὸς φυγὴν ἐτράποντο."},{"number":285,"text":"τισάμενος δὲ τούτους τρισχιλίους Ἰδουμαίων ἐπὶ τῇ Τραχωνίτιδι κατοικίσας ἦγεν λῃστὰς τοὺς ἐκεῖ, καὶ περὶ τούτων τοῖς ἡγεμόσιν ἔπεμπεν περὶ Φοινίκην οὖσιν, ἀποδεικνὺς ὅτι μηδὲν πλέον ὧν ἀγνωμονοῦντας ἐπεξελθεῖν ἔδει τοὺς Ἄραβας αὐτῷ πέπρακται. ταῦτα μὲν οὖν ἐκεῖνοι πολυπραγμονοῦντες εὕρισκον οὐ ψευδόμενον."},{"number":286,"text":"Ἄγγελοι δὲ Συλλαίῳ καταταχήσαντες εἰς Ῥώμην τὰ πεπραγμένα διεσάφουν εἰς μεῖζον, ὡς εἰκός, ἕκαστον τῶν γεγονότων αἴροντες."},{"number":287,"text":"ὁ δὲ ἤδη μὲν ἐπεπραγμάτευτο γνώριμος εἶναι Καίσαρι, τότε δὲ περὶ τὴν αὐλὴν ἀναστρεφόμενος ὡς ἤκουσεν εὐθὺς μεταμφιέννυται μέλαιναν ἐσθῆτα καὶ παρελθὼν ἔλεγεν ὡς αὐτόν, ὅτι πολέμῳ τὰ περὶ τὴν Ἀραβίαν εἴη κεκακωμένα καὶ πᾶσα ἀνάστατος ἡ βασιλεία στρατιᾷ πορθήσαντος αὐτὴν Ἡρώδου."},{"number":288,"text":"δακρύων δὲ πεντακοσίους μὲν ἐπὶ δισχιλίοις Ἀράβων ἀπολωλέναι τοὺς πρώτους ἔλεγεν, ἀνῃρῆσθαι δὲ καὶ τὸν στρατηγὸν αὐτῶν Νάκεβον οἰκεῖον αὐτῷ καὶ συγγενῆ, πλοῦτον δὲ διηρπάσθαι τὸν ἐν Ῥαέπτοις, καταπεφρονῆσθαι δὲ τὸν Ὀβόδαν ὑπὸ ἀσθενείας οὐκ ἀρκέσαντα τῷ πολέμῳ διὰ τὸ μήτʼ αὐτὸν μήτε τὴν Ἀραβικὴν δύναμιν παρεῖναι."},{"number":289,"text":"τοιαῦτα τοῦ Συλλαίου λέγοντος καὶ προστιθέντος ἐπιφθόνως, ὡς οὐδʼ ἂν αὐτὸς ἀπέλθοι τῆς χώρας μὴ πεπιστευκὼς ὅτι Καίσαρι μέλοι τὴν εἰρήνην ἅπασιν εἶναι πρὸς ἀλλήλους, μηδʼ εἰ παρὼν ἐτύγχανεν ἐκεῖ λυσιτελῆ ποιῆσαι τὸν πόλεμον Ἡρώδῃ, παροξυνθεὶς ἐπὶ τοῖς λεγομένοις ὁ Καῖσαρ ἀνέκρινε τῶν Ἡρώδου τοὺς παρόντας καὶ τῶν ἰδίων τοὺς ἀπὸ Συρίας ἥκοντας αὐτὸ μόνον, εἰ τὴν στρατιὰν Ἡρώδης ἐξαγάγοι."},{"number":290,"text":"τῶν δὲ τοῦτο μὲν αὐτὸ λέγειν ἀνάγκην ἐχόντων, τὸ δὲ ἐφʼ ὅτῳ καὶ πῶς οὐκ ἀκούοντος, ὀργή τε μείζων ἐγίνετο τῷ Καίσαρι καὶ γράφει πρὸς τὸν Ἡρώδην τά τε ἄλλα χαλεπῶς καὶ τοῦτο τῆς ἐπιστολῆς τὸ κεφάλαιον, ὅτι πάλαι χρώμενος αὐτῷ φίλῳ νῦν ὑπηκόῳ χρήσεται."},{"number":291,"text":"γράφει δὲ καὶ Σύλλαιος ὑπὲρ τούτων τοῖς Ἄραψιν. οἱ δʼ ἐπαρθέντες οὔτε τῶν λῃστῶν ὅσοι διέφυγον ἐξεδίδοσαν οὔτε τὰ χρήματα διευλύτουν, νομάς τε ἃς ἐκείνου μισθωσάμενοι διακατεῖχον ἀμισθὶ ταύταις ἐχρῶντο, τεταπεινωμένου τοῦ τῶν Ἰουδαίων βασιλέως διὰ τὴν ὀργὴν τοῦ Καίσαρος."},{"number":292,"text":"ἐπιτίθενται δὲ τῷ καιρῷ καὶ οἱ τὴν Τραχωνῖτιν ἔχοντες τῆς τῶν Ἰδουμαίων φρουρᾶς κατεξαναστάντες καὶ λῃστηρίοις χρώμενοι μετὰ τῶν Ἀράβων, οἳ ἐλεηλάτουν τὴν ἐκείνων χώραν οὐκ ἀπὸ ὠφελείας μόνον, ἀλλὰ καὶ μνησικακίας χαλεπώτεροι τὰς ἀδικίας ὄντες."},{"number":293,"text":"Ἡρώδης δὲ ταῦτα πάντα φέρων ἠνείχετο μεταβεβληκυίας αὐτῷ τῆς παρρησίας, ἣν εἶχε διὰ Καίσαρα, καὶ τὸ μεῖζον ἀφῄρητο τοῦ φρονήματος· οὐδὲ γὰρ πέμψαντος αὐτοῦ πρεσβείαν ἀπολογησομένην ὁ Καῖσαρ ἠνέσχετο, πάλιν δὲ τοὺς συνελθόντας ἀπράκτους ἀνέπεμψεν."},{"number":294,"text":"ἦν δʼ οὖν ἐπὶ τούτοις ἀθυμία καὶ δέος, ὅ τε Σύλλαιος οὐ μετρίως ἐλύπει πιστευθείς τε καὶ παρὼν ἐν τῇ Ῥώμῃ, τότε δὲ καὶ μειζόνων ἁπτόμενος· ὁ μὲν γὰρ Ὀβόδας ἐτεθνήκει, παραλαμβάνει δὲ τὴν τῶν Ἀράβων ἀρχὴν Αἰνείας ὁ μετονομασθεὶς αὖθις Ἀρέτας."},{"number":295,"text":"τοῦτον γὰρ ἐπεχείρει διαβολαῖς παρωσάμενος αὐτὸς ἀναλαμβάνειν τὴν ἀρχήν, χρήματα μὲν πολλὰ διδοὺς τοῖς περὶ τὴν αὐλήν, πολλὰ δὲ Καίσαρι δώσειν ὑπισχνούμενος. ὁ δὲ τῷ μὴ τὸν Ἀρέταν ἐπιστείλαντα πρότερον αὐτῷ βασιλεύειν ὠργίζετο."},{"number":296,"text":"πέμπει δὲ κἀκεῖνος ἐπιστολὴν καὶ δῶρα τῷ Καίσαρι στέφανόν τε χρυσοῦν ἀπὸ πολλῶν ταλάντων· ἡ δὲ ἐπιστολὴ κατηγόρει Σύλλαιον ὄντα πονηρὸν δοῦλον Ὀβόδαν τε φαρμάκοις διαφθεῖραι καὶ ζῶντος ἔτι κρατεῖν αὐτὸν τάς τε τῶν Ἀράβων μοιχεύοντα καὶ χρήματα δανειζόμενον, ὥστʼ ἐξιδιώσασθαι τὴν ἀρχήν."},{"number":297,"text":"προσέσχεν δὲ οὐδὲ τούτοις ὁ Καῖσαρ, ἀλλʼ ἀποπέμπει μηδὲν τῶν δώρων λαβών. τὰ δὲ περὶ τὴν Ἰουδαίαν καὶ Ἀραβίαν ἀεὶ καὶ μᾶλλον ἐπεδίδου τὰ μὲν εἰς ἀταξίαν τὰ δʼ ὡς καταφθειρομένων μηδένα προεστάναι·"},{"number":298,"text":"τῶν γὰρ βασιλέων ὁ μὲν οὐδέπω τὴν ἀρχὴν βεβαίαν ἔχων οὐχ ἱκανὸς ἦν κωλύειν τοὺς ἀδικοῦντας, Ἡρώδης δὲ ἐφʼ οἷς ἠμύνατο τάχιον ὀργισθέντος αὐτῷ Καίσαρος ἁπάσας τὰς εἰς αὐτὸν παρανομίας φέρειν ἠναγκάζετο."},{"number":299,"text":"πέρας δʼ οὐδὲν ὁρῶν τῶν περιεστώτων κακῶν ἔγνω πάλιν εἰς Ῥώμην ἀποστέλλειν, εἴ τι δύναιτο μετριώτερον εὑρεῖν διά τε τῶν φίλων καὶ πρὸς αὐτὸν Καίσαρα τὴν ἐντυχίαν ποιησάμενος. κἀκεῖ μὲν ὁ Δαμασκηνὸς ἀπῄει Νικόλαος."}],"10":[{"number":300,"text":"Ἐξετετάρακτο δὲ τὰ περὶ τὴν οἰκίαν καὶ τοὺς παῖδας αὐτῷ πολὺ χεῖρον ἐσχηκότα περὶ τὸν καιρὸν ἐκεῖνον. ὅλως μὲν γὰρ οὐδὲ τὸν ἔμπροσθε χρόνον ἀσύνοπτον ἦν, ὡς τὸ μέγιστον καὶ δυσχερέστατον τῶν ἀνθρωπίνων παθῶν ἀπειλεῖται τῇ βασιλείᾳ διὰ τῆς τύχης, ἐπέβαινεν δὲ καὶ μᾶλλον ηὐξήθη τότε παρὰ τοιαύτην αἰτίαν."},{"number":301,"text":"Εὐρυκλῆς ἀπὸ Λακεδαίμονος οὐκ ἄσημος τῶν ἐκεῖ κακὸς δὲ τὴν ψυχὴν ἄνθρωπος καὶ περὶ τρυφὴν καὶ κολακείαν δεινὸς ἑκάτερον αὐτῶν ἔχειν τε καὶ μὴ δοκεῖν, ἐπιδημήσας ὡς τὸν Ἡρώδην δῶρά τε δίδωσιν αὐτῷ καὶ πλείω παρʼ ἐκείνου λαβὼν ταῖς εὐκαιρίαις τῶν ἐντεύξεων ἐπραγματεύσατο φίλος ἐν τοῖς μάλιστα γενέσθαι βασιλέως."},{"number":302,"text":"ἦν δʼ αὐτῷ καταγωγὴ μὲν ἐν τοῖς Ἀντιπάτρου, πρόσοδος δὲ καὶ συνήθεια πρὸς τὸν Ἀλέξανδρον· Ἀρχελάῳ γὰρ ἔλεγεν εἶναι τῷ Καππάδοκι διὰ σπουδῆς."},{"number":303,"text":"ὅθεν καὶ τὴν Γλαφύραν ὑπεκρίνατο τιμᾶν, καὶ πολὺς ἦν ἀφανῶς μὲν ἐκθεραπεύων ἅπαντας ἀεὶ δὲ τοῖς λαλουμένοις ἢ γινομένοις προσέχων, ὡς ἐξ αὐτῶν ἀντιχαρίζεσθαι τὰς διαβολάς."},{"number":304,"text":"τέλος δὲ τοιοῦτος ἑκάστῳ κατὰ τὰς συντυχίας ἀπέβαινεν, ὡς ἐκείνῳ μὲν εἶναι φίλος τοῖς δὲ ἄλλοις δοκεῖν κατὰ τὸ συμφέρον ἐκείνῳ προσεῖναι. οὗτος Ἀλέξανδρον παράγει νέον ὄντα καὶ περὶ ὧν ἐπεπόνθει μηδενὶ μὲν πρὸς ἐκεῖνον δὲ μόνον ἀδεῶς πεπεισμένον ἐξεῖναι λέγειν·"},{"number":305,"text":"ἐνέφαινεν οὖν ἀχθόμενος, ὡς ὁ πατὴρ ἠλλοτρίωτο, καὶ τὰ περὶ τὴν μητέρα διηγεῖτο καὶ τὸν Ἀντίπατρον, ὅτι παρωθούμενος αὐτοὺς τῆς τιμῆς τὰ πάντα ἤδη δύναται. τούτων δὲ ἀνεκτὸν οὐδὲν ἔφη κατεσκευασμένου πρὸς μῖσος ἤδη τοῦ πατρός, ὡς μηδὲ συμποσίοις ἢ συλλόγοις ἀνέχεσθαι λέγων."},{"number":306,"text":"τοιαῦτα μὲν ἐκεῖνος, ὡς εἰκός, ἐφʼ οἷς ἤλγει· τοὺς δὲ λόγους Εὐρυκλῆς Ἀντιπάτρῳ τούτους ἀνέφερεν, λέγων μὲν ὡς οὐχ ἕνεκα σοῦ τοῦτʼ αὐτὸν ποιεῖν, νικᾶσθαι δὲ ὑπὸ σοῦ τιμώμενος τῷ μεγέθει τοῦ πράγματος καὶ φυλάττεσθαι παρακελευόμενος τὸν Ἀλέξανδρον· οὐ γὰρ ἀπαθῶς τούτων ἕκαστον λέγειν, ἀλλὰ τοῖς ῥήμασιν αὐτοῖς εἶναι τὴν αὐτοχειρίαν."},{"number":307,"text":"Ἀντίπατρος μὲν οὖν εὔνουν ὑπολαμβάνων ἐκ τούτων μεγάλας αὐτῷ παρʼ ἕκαστα δωρεὰς ἐδίδου καὶ τέλος ἤδη πείθει πρὸς τὸν Ἡρώδην ἀναφέρειν τὸν λόγον."},{"number":308,"text":"ὁ δʼ οὐκ ἦν τὴν Ἀλεξάνδρου δύσνοιαν ἐξ ὧν ἔλεγεν ἀκηκοέναι διηγούμενος ἀπίθανος, ἀλλʼ οὕτω διέθηκε τὸν βασιλέα περιάγων ἀεὶ τοῖς ῥήμασι καὶ παροξύνων, ὡς ἀμετάγνωστον ποιῆσαι τὸ μῖσος. ἐδήλωσεν δὲ καὶ πρὸς αὐτὸν τὸν καιρόν·"},{"number":309,"text":"εὐθὺς γὰρ Εὐρυκλεῖ δίδωσιν πεντήκοντα τάλαντα δωρεάν. ὁ δὲ ταῦτα λαβὼν καὶ πρὸς Ἀρχέλαον ἀναβὰς τὸν βασιλέα τῶν Καππαδόκων τὸν Ἀλέξανδρον ἐπῄνει καὶ χρήσιμος ἔλεγεν αὐτῷ πολλὰ πρὸς τὰς διαλλαγὰς τὰς πρὸς τὸν πατέρα γεγενῆσθαι."},{"number":310,"text":"χρηματισάμενος δὲ καὶ παρʼ ἐκείνου πρὶν καταφωραθῆναι τῆς κακοηθείας ἀπῄει. Εὐρυκλῆς μὲν οὖν οὐδὲ ἐν τῇ Λακεδαίμονι παυσάμενος εἶναι μοχθηρὸς ἐπὶ πολλοῖς ἀδικήμασιν ἀπεστερήθη τῆς πατρίδος."},{"number":311,"text":"Ὁ δὲ τῶν Ἰουδαίων βασιλεὺς οὐχ ὥσπερ πρότερον εἶχεν πρός τε τὸν Ἀλέξανδρον καὶ τὸν Ἀριστόβουλον ἀκούειν μόνον τὰς κατʼ αὐτῶν διαβολάς, ἀλλʼ ἤδη διὰ μίσους οἰκείου γεγενημένος αὐτὸς εἰ καὶ μὴ λέγοι τις ἐξειργάζετο,"},{"number":312,"text":"παρατηρῶν ἕκαστα καὶ πυνθανόμενος καὶ πᾶσιν ἐνδιδοὺς τοῖς βουλομένοις, εἴ τις ἔχοι τι κατʼ ἐκείνων εἰπεῖν, Εὐάρατόν τε Κῷον Ἀλεξάνδρῳ συνειδέναι. καὶ τοῦτο μὲν οὖν καθʼ ἡδονὴν τὸ πάντων ἥδιστον Ἡρώδης ἐλάμβανεν."},{"number":313,"text":"Ἐπιγίνεται δὲ κατὰ τῶν νεανίσκων μεῖζόν τι σκευωρουμένης ἀεὶ τῆς κατʼ αὐτῶν διαβολῆς καὶ πᾶσιν, ὡς εἰπεῖν, ἄθλου τούτου προκειμένου λέγειν τι περὶ ἐκείνων δυσχερὲς πρὸς τῆς τοῦ βασιλεύοντος ἐδόκει σωτηρίας."},{"number":314,"text":"σωματοφύλακες ἦσαν Ἡρώδῃ δύο κατʼ ἰσχὺν καὶ μέγεθος τιμώμενοι Ἰούκουνδος καὶ Τύραννος. οὗτοι προσκρούσαντος αὐτοῖς τοῦ βασιλέως ἀπεωσμένοι περὶ Ἀλέξανδρον ἦσαν συνιππαζόμενοι καὶ κατὰ τὰ γυμνάσια τιμώμενοι καί τι χρυσίον καὶ δωρεὰς ἄλλας ἔλαβον."},{"number":315,"text":"εὐθὺς οὖν καὶ τούτους ὁ βασιλεὺς ἐν ὑποψίαις ἔχων ἐβασάνιζεν, οἱ δὲ διακαρτερήσαντες πολὺν χρόνον ὕστερον ἔλεγον, ὅτι πείθοι φονεύειν αὐτοὺς Ἡρώδην Ἀλέξανδρος, ἐπεὶ περὶ κυνηγέσιον θηρίων διώκων προλάβοι· δυνατὸν γὰρ εἶναι λέγειν ὡς ἀπὸ τοῦ ἵππου κατενεχθεὶς ἐμπαρείη ταῖς αὐτοῦ λόγχαις·"},{"number":316,"text":"καὶ γὰρ πρότερον αὐτῷ τοιοῦτον γενέσθαι πάθος. ἐπέδειξαν δὲ καὶ τὸ χρυσίον ἐν ἱππῶνι κατορωρυγμένον καὶ τὸν ἀρχικύνηγον ἐξήλεγχον, ὅτι καὶ λόγχας αὐτοῖς δοίη βασιλικὰς καὶ τοῖς Ἀλέξανδρον θεραπεύουσιν ὅπλα κελεύοντος ἐκείνου."},{"number":317,"text":"Μετὰ τούτους ὁ φρούραρχος Ἀλεξανδρείου συλληφθεὶς ἐβασανίζετο· καὶ γὰρ ἐκεῖνος αἰτίαν εἶχεν δέξεσθαι τῇ φρουρᾷ καὶ παρέξειν χρήματα τοῖς νεανίσκοις ὑπεσχῆσθαι τὰ κείμενα τῶν βασιλικῶν κατʼ ἐκεῖνο τὸ φρούριον."},{"number":318,"text":"αὐτὸς μὲν οὖν οὐδὲν ὡμολόγησεν, υἱὸς δὲ αὐτοῦ παρελθὼν ταῦτʼ ἔφη γενέσθαι, καὶ γράμματα ἐπέδωκεν ὡς εἰκάσαι τῆς Ἀλεξάνδρου χειρός· τελέσαντες σὺν θεῷ εἰπεῖν ἃ προεθέμεθα πάντα ἥξομεν πρὸς ὑμᾶς· ἀλλὰ πειράθητε, καθὼς ὑπέσχησθε, δέξασθαι ἡμᾶς τῷ φρουρίῳ."},{"number":319,"text":"μετὰ τοῦτο τὸ γραμματεῖον ὁ μὲν Ἡρώδης οὐκ ἐνδοιασίμως εἶχεν περὶ τῆς τῶν παίδων εἰς αὐτὸν ἐπιβουλῆς, Ἀλέξανδρος δὲ Διόφαντον ἔφη τὸν γραμματέα μιμήσασθαι τὸν τύπον καὶ διʼ Ἀντιπάτρου κακουργηθῆναι τὸ γραμματίδιον· ὁ γάρ τοι Διόφαντος ἐδόκει τὰ τοιαῦτα δεινὸς ἐν ὑστέρῳ τε διελεγχθεὶς ἐπʼ ἄλλοις οὕτως ἀπέθανεν."},{"number":320,"text":"Τοὺς δὲ βασανισθέντας ὁ βασιλεὺς καὶ εἰς τὸ πλῆθος προήγαγεν ἐν Ἱεριχοῦντι κατηγοροῦντας τῶν παίδων· καὶ τούτους μὲν ἐκ χειρὸς οἱ πολλοὶ βάλλοντες ἀπέκτειναν."},{"number":321,"text":"ὡρμημένων δὲ καὶ τοὺς περὶ τὸν Ἀλέξανδρον ὁμοίως κτεῖναι, τοῦτο μὲν ὁ βασιλεὺς παρῃτήσατο διὰ Πτολεμαίου καὶ Φερώρα τὸ πλῆθος ἀναστείλας, ἦν δὲ φυλακὴ καὶ τήρησις αὐτῶν καὶ προσῄει μὲν οὐδείς, πάντα δʼ ἐπεσκοπεῖτο τὰ γινόμενα καὶ λαλούμενα, καὶ τί γὰρ ἢ καταδίκων εἶχον ἀδοξίαν καὶ δέος."},{"number":322,"text":"ἕτερος δʼ αὐτῶν Ἀριστόβουλος ἐκ βαρυθυμίας ὑπαγόμενος καὶ τὴν ἑαυτοῦ τηθίδα καὶ πενθερὰν συναλγεῖν αὐτῷ ταῖς συμφοραῖς καὶ μισεῖν τὸν τοιαῦτα πειθόμενον οὐ γάρ, ἔφη, καὶ σοὶ κίνδυνος ἀπωλείας διαβεβλημένῃ Συλλαίῳ κατʼ ἐλπίδα γάμων ἅπαντα τἀνθάδε προμηνύειν;"},{"number":323,"text":"τούτους ἐκείνη ταχὺ μάλα τἀδελφῷ προσφέρει τοὺς λόγους. ὁ δʼ οὐκέτι κατασχὼν αὑτὸν δῆσαί τε κελεύει καὶ διαστήσαντας ἀπʼ ἀλλήλων ὅσα κακῶς ἐποίησαν ἐπὶ τῷ πατρὶ ταῦτα γραψαμένους ἀποφέρειν."},{"number":324,"text":"οἱ δʼ ἐπεὶ τοῦτο προσετέτακτο αὐτοῖς, ἐγγράφουσιν ἐπιβουλὴν μὲν οὔτε νοῆσαι κατὰ τοῦ γεγεννηκότος οὔτε συσκευάσασθαι, δρασμῷ δὲ ἐπιβαλέσθαι καὶ τοῦτο διʼ ἀνάγκην ὑπόπτου καὶ δυσχεροῦς ὄντος αὐτοῖς τοῦ βίου."},{"number":325,"text":"Κατὰ δὲ τὸν χρόνον ἥκοντος ἐκ Καππαδοκίας πρεσβευτοῦ παρὰ Ἀρχελάου Μήλα τινός, ὃς ἦν δυνάστης τῶν ἐκείνου, βουλόμενος Ἡρώδης ἐνδείξασθαι τὴν δύσνοιαν Ἀρχελάου πρὸς αὐτὸν ἐκάλει τὸν Ἀλέξανδρον ὡς ἦν ἐν τοῖς δεσμοῖς καὶ πάλιν ἠρώτα περὶ τῆς φυγῆς, ὅπου καὶ πῶς ἐγνώκασιν ἀποχωρεῖν."},{"number":326,"text":"ὁ δὲ Ἀλέξανδρος πρὸς Ἀρχέλαον ἔφη κἀκεῖθεν εἰς Ῥώμην ὁμολογήσαντα διαπέμψειν· ἄλλο δʼ οὐδὲν οὔτʼ ἄτοπον οὔτε δυσχερὲς ἐντεθυμῆσθαι κατὰ τοῦ πατρὸς οὐδʼ ὅσα συνεσκεύασται κακοηθείᾳ τῶν ἐναντίων ἀληθὲς εἶναί τι τούτων."},{"number":327,"text":"βούλεσθαι δʼ ἂν ἔτι ζῆν καὶ τοὺς περὶ Τύραννον εἰς ἐξέτασιν ἀσφαλεστέραν, ἀλλὰ καὶ τούτους ἀπολέσθαι θᾶττον Ἀντιπάτρου τῷ πλήθει τοὺς ἰδίους ἐγκαθιστάντος φίλους."},{"number":328,"text":"Τοιαῦτα λέγοντος ἐκέλευσεν ἅμα τόν τε Μήλαν καὶ τὸν Ἀλέξανδρον ἄγειν ὡς Γλαφύραν τὴν Ἀρχελάου καὶ πυνθάνεσθαι παρʼ αὐτῆς, εἰ μηδὲν ἠγνόει τῶν εἰς ἐπιβουλὴν Ἡρώδου γιγνομένων."},{"number":329,"text":"ὡς δὲ ἧκον, εὐθὺς μὲν Γλαφύρα δεσμώτην ἰδοῦσα τὸν Ἀλέξανδρον ἔπληξε τὴν κεφαλὴν καὶ καταπληξαμένη μέγα καὶ συμπαθὲς ἀνῴμωξεν. ἦν δὲ καὶ τοῦ νεανίσκου δάκρυα καὶ τῶν παρόντων ὀδυνηρά τις θέα, μέχρι πλείονος οὐδὲ ἐφʼ οἷς ἧκον εἰπεῖν ἢ πράττειν δυναμένων."},{"number":330,"text":"ὀψὲ δὲ τοῦ Πτολεμαίου, τούτῳ γὰρ ἄγειν αὐτὸν ἐπετέτακτο, φράζειν κελεύοντος εἴ τι τῶν πραττομένων ἡ γυνὴ σύνοιδεν αὐτῷ,"},{"number":331,"text":"τί δʼ οὐκ ἄν, ἔφη, συνέγνω τῆς ψυχῆς ἐμοὶ στεργομένη πλέον καὶ κοινωνοῦσα τέκνων; ἡ δὲ πρὸς ταῦτα μὲν ἀνεβόησεν, ὡς συνειδείη μὲν οὐδὲν ἄτοπον, εἰ δὲ φέροι πρὸς τὴν σωτηρίαν τὴν ἐκείνου τὸ καὶ καθʼ αὑτῆς τι ψεύσασθαι, πάνθʼ ὁμολογεῖν. ὁ δὲ Ἀλέξανδρος ἀσεβὲς μὲν οὐδέν, εἶπεν, οὐδʼ ὧν ὑπονοοῦσιν οὓς ἥκιστα ἐχρῆν οὔτʼ αὐτὸς ἐνόησα σύ τε οὐδὲν οἶσθα, ἀλλʼ ὅτι παρʼ Ἀρχέλαον ἀποχωρεῖν ἐγνώκειμεν κἀκεῖθεν εἰς Ῥώμην."},{"number":332,"text":"ταῦτʼ ἐκείνης ὁμολογούσης ὁ μὲν Ἡρώδης Ἀρχέλαον ἐξεληλέγχθαι τῆς πρὸς αὐτὸν δυσνοίας ὑπολαβὼν δίδωσιν Ὀλύμπῳ καὶ Οὐολομνίῳ γράμματα κελεύσας ἐν παράπλῳ μὲν Ἐλαιούσῃ τῆς Κιλικίας προσσχόντας Ἀρχελάῳ τε περὶ τούτων ἀποδοῦναι καὶ μεμψαμένους ὅτι τῆς ἐπιβουλῆς ἐφάψαιτο τοῖς παισὶν ἐκεῖθεν εἰς Ῥώμην πλεῖν."},{"number":333,"text":"κἂν εὕρωσιν ἀνύσαντά τι Νικόλαον, ὡς μηκέτʼ αὐτῷ δυσχεραίνειν Καίσαρα, διδόναι τὰς ἐπιστολὰς καὶ τοὺς ἐλέγχους τοὺς κατὰ τῶν νεανίσκων συνεσκευασμένως ἐπέστειλεν."},{"number":334,"text":"Ἀρχέλαος μὲν οὖν ἀπελογεῖτο δέξασθαι μὲν τοὺς νεανίσκους ὁμολογήσας διὰ τὸ συμφέρειν αὐτοῖς τε ἐκείνοις καὶ τῷ πατρὶ μὴ χαλεπώτερόν τι προστεθῆναι κατʼ ὀργὴν ὧν ὑπόπτως ἔχοντες ἐστασίαζον· οὐ μὴν καὶ πρὸς Καίσαρα πέμψειν οὐδʼ ἄλλο τι κατὰ δύσνοιαν τὴν πρὸς ἐκεῖνον ὁμολογῆσαι τοῖς νεανίσκοις."},{"number":335,"text":"Εἰς δὲ τὴν Ῥώμην ἀποκομισθέντες ἔσχον καιρὸν ἐπιδοῦναι τὰ γράμματα τῷ Καίσαρα διηλλαγμένον εὑρεῖν Ἡρώδῃ· τὰ γὰρ περὶ τὴν Νικολάου πρεσβείαν ἀπέβη τοῦτον τὸν τρόπον·"},{"number":336,"text":"ὡς ἀνῆλθεν εἰς τὴν Ῥώμην καὶ περὶ τὴν αὐλὴν ἐγένετο, πρῶτον μὲν οὐκ ἐφʼ οἷς ἐληλύθει μόνον ἀλλὰ καὶ Συλλαίου κατηγορεῖν ἠξίου, καὶ δῆλοι πρὸ τῆς ἐντυχίας ἦσαν ἀλλήλους πολεμοῦντες."},{"number":337,"text":"οἱ δὲ Ἄραβες ὑπονοήσαντες ἐξ αὐτοῦ καὶ τῷ Νικολάῳ προσελθόντες τὰς ἀδικίας ἁπάσας ἐμήνυον καὶ τῶν Ὀβόδου ὡς διαφθαρέντων πάντων ἐμφανῆ τεκμήρια παρέχοντες, ἦν γὰρ καὶ τῶν γραμμάτων αὐτοῦ ὃ κατὰ τὴν ἀπόστασιν ὑφῃρημένοι διὰ τούτων ἤλεγχον."},{"number":338,"text":"ὁ δὲ Νικόλαος εὐτυχίαν τινὰ ταύτην ὁρῶν αὐτῷ προσγεγενημένην διʼ αὐτῆς ἐπραγματεύετο τὸ μέλλον, ἐπείγων εἰς διαλλαγὰς ἐλθεῖν Ἡρώδῃ Καίσαρα· σαφῶς γὰρ ἠπίστατο βουλομένῳ μὲν ἀπολογεῖσθαι περὶ ὧν ἔπραξεν οὐκ ἔσεσθαι παρρησίαν, ἐθέλοντι δὲ κατηγορεῖν Συλλαίου γενήσεσθαι καιρὸν ὑπὲρ Ἡρώδου λέγειν."},{"number":339,"text":"συνεστώτων οὖν ἐπʼ ἀλλήλους καὶ δοθείσης ἡμέρας ὁ Νικόλαος παρόντων αὐτῷ τῶν Ἀρέτα πρέσβεων τά τε ἄλλα κατηγόρει τοῦ Συλλαίου, τήν τε τοῦ βασιλέως ἀπώλειαν λέγων καὶ πολλῶν Ἀράβων,"},{"number":340,"text":"χρήματά τε ὡς εἴη δεδανεισμένος ἐπʼ οὐδὲν ὑγιές, καὶ μοιχείας ἐξελέγχων οὐ τῶν ἐν Ἀραβίᾳ μόνον ἀλλὰ καὶ τῶν ἐν Ῥώμῃ γυναικῶν· προσετίθει δὲ τὸ μέγιστον, ὡς ἐξαπατήσειεν Καίσαρα μηδὲν ἀληθὲς διδάξας ὑπὲρ τῶν Ἡρώδῃ πεπραγμένων."},{"number":341,"text":"ὡς δʼ ἧκεν ἐπὶ τοῦτον τὸν τόπον, ὁ μὲν Καῖσαρ ἐξεῖργεν αὐτὸν τοῦτο μόνον ἀξιῶν ὑπὲρ Ἡρώδου λέγειν, εἰ μὴ στρατιὰν ἤγαγεν εἰς Ἀραβίαν μηδὲ δισχιλίους πεντακοσίους ἀποκτείνειεν τῶν ἐκεῖ μηδʼ αἰχμαλώτους λάβοι τὴν χώραν διαρπάσας."},{"number":342,"text":"πρὸς ταῦτα ὁ Νικόλαος ὑπὲρ τούτων ἔφη καὶ μάλιστα διδάξειν, ὅτι μηδὲν ἢ τὰ πλεῖστά γε αὐτῶν οὐ γέγονεν, ὡς σὺ ἀκήκοας καὶ δίκαιον ἦν ἐπʼ αὐτοῖς χαλεπώτερον φέρειν."},{"number":343,"text":"πρὸς δὲ τὸ παράδοξον Καίσαρος ἐνδόντος αὑτὸν ἀκροατήν, τὸ δάνειον εἰπὼν τῶν πεντακοσίων ταλάντων καὶ τὴν συγγραφήν, ἐν ᾗ καὶ τοῦτο ἦν προσγεγραμμένον ἐξεῖναι τῆς προθεσμίας παρελθούσης ῥύσια λαμβάνειν ἐξ ἁπάσης τῆς χώρας, τὴν μὲν στρατείαν οὐ στρατείαν ἔλεγεν, ἀλλʼ ἐπὶ δικαίαν τῶν ἰδίων ἀπαίτησιν χρημάτων·"},{"number":344,"text":"καὶ μηδὲ ταύτην ταχὺ μηδʼ ὡς ἐπέτρεπον αἱ συγγραφαί, πολλάκις μὲν ἐπὶ Σατορνῖνον ἐλθόντα καὶ Οὐολόμνιον τοὺς τῆς Συρίας ἡγεμόνας, τελευταῖον δὲ ἐν Βηρυτῷ τούτων ἐναντίον Συλλαίου τὴν σὴν τύχην ἐπομόσαντος, ἦ μὴν ἐντὸς ἡμερῶν τριάκοντα παρέξειν τὰ χρήματα καὶ τοὺς ἐκ τῆς ἀρχῆς τῆς Ἡρώδου πεφευγότας."},{"number":345,"text":"ὧν οὐδὲν ποιήσαντος Συλλαίου πάλιν ἐπὶ τοὺς ἡγεμόνας ἐλθεῖν Ἡρώδην κἀκείνων ἐφέντων αὐτῷ λαμβάνειν τὰ ῥύσια μόγις οὕτως ἐξελθεῖν σὺν τοῖς περὶ αὐτόν."},{"number":346,"text":"ὁ μὲν δὴ πόλεμος, ὡς οὗτοι τραγῳδοῦντες ἔλεγον, καὶ τὰ τῆς ἐπιστρατείας τοιαῦτα. καίτοι πῶς ἂν εἴη πόλεμος, ἐπιτρεψάντων μὲν τῶν σῶν ἡγεμόνων, δεδωκυίας δὲ τῆς συνθήκης, ἠσεβημένου δὲ μετὰ τῶν ἄλλων θεῶν καὶ τοῦ σοῦ, Καῖσαρ, ὀνόματος;"},{"number":347,"text":"τὰ δὲ περὶ τοὺς αἰχμαλώτους ἑξῆς ἤδη λεκτέον. λῃσταὶ τῶν τὸν Τράχωνα κατοικούντων τετταράκοντα τὸ πρῶτον εἶτʼ αὖθις πλείονες τὰς Ἡρώδου κολάσεις διαφεύγοντες ὁρμητήριον ἐποιήσαντο τὴν Ἀραβίαν. τούτους ὑπεδέξατο Σύλλαιος ἐπὶ πάντας ἀνθρώπους τρέφων καὶ χώραν ἔδωκε νέμεσθαι καὶ τὰ κέρδη τῶν λῃστῶν αὐτὸς ἐλάμβανεν."},{"number":348,"text":"ὡμολόγησε δὲ καὶ τούτους ἐπὶ τοῖς αὐτοῖς ὅρκοις ἀποδώσειν κατὰ τὴν αὐτὴν τοῦ δανείου προθεσμίαν. καὶ δύναιτʼ ἂν οὐκ ἐπιδεῖξαι κατὰ τὸ παρὸν οὔτʼ ἄλλον τινὰ τῆς Ἀράβων χώρας ἢ τούτους ἐξῃρημένους οὔτε πάντας, ἀλλʼ ὅσοι μὴ λαθεῖν ἴσχυσαν."},{"number":349,"text":"οὕτως οὖν καὶ τοῦ τῆς αἰχμαλωσίας ἐπιφθόνου συκοφαντήματος πεφηνότος μέγιστον, ὦ Καῖσαρ, κατάμαθε πλάσμα καὶ ψεῦσμα πρὸς τὴν σὴν ὀργὴν αὐτῷ ποιηθέν."},{"number":350,"text":"φημὶ γὰρ ἐπελθούσης ἡμῖν τῆς τῶν Ἀράβων δυνάμεως καὶ τῶν περὶ Ἡρώδην πεσόντος ἑνὸς καὶ δευτέρου, τότε μόλις ἀμυνομένου Νάκεβον τὸν στρατηγὸν αὐτῶν καὶ περὶ πέντε καὶ εἴκοσι τοὺς πάντας ὧν ἕκαστον αὐτὸς εἰς ἑκατὸν ἀναφέρων δισχιλίους καὶ πεντακοσίους τοὺς ἀπολωλότας ἔλεγεν."},{"number":351,"text":"Ταῦτα μᾶλλον ἐκίνει τὸν Καίσαρα καὶ πρὸς τὸν Σύλλαιον ἐπιστραφεὶς ὀργῆς μεστὸς ἀνέκρινεν, ὁπόσοι τεθνήκασιν Ἀράβων. ἀπορουμένου δʼ αὐτοῦ καὶ πεπλανῆσθαι λέγοντος αἵ τε συνθῆκαι τῶν δανείων ἀνεγινώσκοντο καὶ τὰ τῶν ἡγεμόνων γράμματα πόλεις τε ὅσαι τὰ λῃστήρια κατῃτιῶντο,"},{"number":352,"text":"καὶ πέρας εἰς τοῦτο μετέστη Καῖσαρ, ὡς τοῦ μὲν Συλλαίου καταγνῶναι θάνατον, Ἡρώδῃ δὲ διαλλάττεσθαι μετάνοιαν ἐφʼ οἷς ἐκ διαβολῆς πικρότερον ἔγραψεν αὐτῷ πεπονθώς, καί τι τοιοῦτον εἰπεῖν εἰς τὸν Σύλλαιον, ὡς ἀναγκάσειεν αὐτὸν ψευδεῖ λόγῳ πρὸς ἄνδρα φίλον ἀγνωμονῆσαι."},{"number":353,"text":"τὸ δὲ σύμπαν ὁ μὲν Σύλλαιος ἀνεπέμπετο τὰς δίκας καὶ τὰ χρέα τοῖς δεδανεικόσιν ἀποδώσων εἶθʼ οὕτω κολασθησόμενος. Ἀρέτᾳ δʼ οὐκ εὐμενὴς ἦν Καῖσαρ, ὅτι τὴν ἀρχὴν μὴ διʼ ἐκείνου καθʼ αὑτὸν δὲ ἔλαβεν. ἐγνώκει δὲ καὶ τὴν Ἀραβίαν Ἡρώδῃ διδόναι, διεκώλυσεν δὲ τὰ παρʼ ἐκείνου πεμφθέντα γράμματα."},{"number":354,"text":"τοῖς γὰρ περὶ τὸν Ὄλυμπον καὶ Οὐολόμνιον εὐμενῆ Καίσαρα πυνθανομένοις εὐθὺς ἔδοξεν ἐξ ἐντολῆς Ἡρώδου τὰ περὶ τῶν παίδων γράμματα καὶ τοὺς ἐλέγχους ἀναδιδόναι."},{"number":355,"text":"Καῖσαρ δὲ ἀναγνοὺς τὸ μὲν ἀρχὴν ἄλλην προσθεῖναι γέροντι καὶ κακῶς πράττοντι τὰ περὶ τοὺς παῖδας οὐκ ᾠήθη καλῶς ἔχειν, δεξάμενος δὲ τοὺς παρὰ Ἀρέτα καὶ τοῦτο μόνον ἐπιτιμήσας, ὡς προπετείᾳ χρήσαιτο τῷ μὴ παρʼ αὐτοῦ τὴν βασιλείαν ἀναμεῖναι λαβεῖν, τά τε δῶρα προσήκατο καὶ τὴν ἀρχὴν ἐβεβαίωσεν."}],"11":[{"number":356,"text":"Ἡρώδῃ δὲ γράφει διηλλαγμένος ἐπί τε τοῖς παισὶν ἄχθεσθαι λέγων καὶ δέον, εἰ μὲν ἀνοσιώτερόν τι τετολμήκασιν, ἐπεξιέναι πατραλόας ὄντας· αὐτῷ γὰρ ἐφεῖναι ταύτην τὴν ἐξουσίαν· εἰ δὲ δρασμὸν ἐνόησαν, ἄλλως νουθετήσαντα μηδὲν ἀνήκεστον διαπράττεσθαι."},{"number":357,"text":"συμβουλεύειν δὲ ἔχειν αὐτῷ συνέδριον ἀποδείξαντα περὶ Βηρυτόν, ἐν ᾗ κατοικοῦσιν Ῥωμαῖοι, καὶ παραλαβόντα τούς τε ἡγεμόνας καὶ τὸν βασιλέα τῶν Καππαδόκων Ἀρχέλαον ὅσους τε τῶν ἄλλων οἴεται φιλίᾳ τε καὶ ἀξιώματι ἐπιφανεῖς μετὰ τῆς ἐκείνων γνώμης ὅ τι χρὴ διαλαμβάνειν."},{"number":358,"text":"Καῖσαρ μὲν τοιαῦτα ἐπέστελλεν. ὁ δὲ Ἡρώδης τῶν γραμμάτων ὡς αὐτὸν ἀπενεχθέντων περιχαρὴς μὲν εὐθὺς ἐπὶ ταῖς διαλλαγαῖς ἐγεγόνει, περιχαρὴς δὲ καὶ τῷ πάντʼ ἐξεῖναι κατὰ τῶν παίδων αὐτῷ."},{"number":359,"text":"καί πως τὸ μὲν οὐκ εὖ πράττειν ἐν τῷ προτέρῳ χαλεπὸν μὲν ἀλλʼ οὔτε θρασὺν οὔτε προπετῆ πρὸς τὴν ἀπώλειαν τῶν τέκνων παρεῖχεν αὐτόν, ἐν δὲ τῷ τότε μεταβολῆς ἀμείνονος καὶ παρρησίας ἐπιλαβόμενος τὸ μῖσος ἐκενοδόξει τὴν ἐξουσίαν."},{"number":360,"text":"διέπεμπεν οὖν ὅσους ἐδόκει καλεῖν εἰς τὸ συνέδριον Ἀρχελάου χωρίς· ἐκεῖνον δὲ διʼ ἔχθος οὐκ ἠξίου παρατυγχάνειν ἢ καὶ τῇ προαιρέσει νομίζων ἐμποδὼν ἔσεσθαι."},{"number":361,"text":"Γενομένων δὲ ἐν Βηρυτῷ τῶν ἡγεμόνων καὶ τῶν ἄλλων ὅσους τῶν πόλεων ἐκάλεσεν, τοὺς μὲν παῖδας, οὐ γὰρ ἠξίου παράγειν εἰς τὸ συνέδριον, ἐν κώμῃ τινὶ Σιδωνίων εἶχεν Παλαεστῶ καλουμένῃ πλησίον τῆς πόλεως, ὡς ἔχειν εἰ κληθεῖεν παραστῆσαι."},{"number":362,"text":"μόνος δὲ καὶ κατʼ αὐτὸν εἰσελθὼν ἑκατὸν καὶ πεντήκοντα συγκαθημένων ἀνδρῶν κατηγόρει κατηγορίαν οὐκ ὀδυνηρὰν ὡς πρὸς ἀνάγκην ὧν ἠτύχει, πλεῖστον δὲ ἀπεοικυῖαν ᾗ πατὴρ ἐπὶ παισὶν εἴποι·"},{"number":363,"text":"βίαιος γὰρ ἦν καὶ περὶ τὴν ἀπόδειξιν τῆς αἰτίας ἐτετάρακτο καὶ μέγιστα θυμοῦ καὶ ἀγριότητος ἐνεδίδου σημεῖα, τούς τε ἐλέγχους οὐκ ἐκείνοις ἐπιτρέπων καταμαθεῖν, ἀλλὰ συνηγορίαν αὐτοῖς προτιθεὶς πατρὶ κατὰ παίδων ἀσχήμονα, καὶ τὰ γραφέντα διʼ αὐτῶν ἐκείνων ἀναγινώσκων, ἐν οἷς ἐπιβουλὴ μὲν ἤ τις ἐπίνοια δυσσεβείας οὐκ ἐγέγραπτο, μόνον δὲ ὡς φυγεῖν βουλεύοιντο καὶ λοιδορίαι τινὲς εἰς αὐτὸν ὀνείδη περιέχουσαι διὰ τὴν δύσνοιαν."},{"number":364,"text":"ἐφʼ αἷς ἐκεῖνος ὡς ἐγένετο μᾶλλόν τε ἐξεβόα καὶ τὸ περιὸν εἰς ὁμολογίαν τῆς ἐπιβουλῆς διʼ ἐκείνων ηὔξανεν ἐπομνύμενος, ὡς ἥδιον ἂν στέροιτο τοῦ ζῆν ἢ τοιούτων ἀκούειν λόγων."},{"number":365,"text":"τὸ δὲ τελευταῖον εἰπών, ὅτι καὶ τῇ φύσει καὶ τῇ Καίσαρος δόσει τὴν ἐξουσίαν αὐτὸς ἔχοι, προσέθηκεν αὐτῷ καὶ πάτριον νόμον κελεύειν, εἴ του κατηγορήσαντες οἱ γονεῖς ἐπιθοῖεν τῇ κεφαλῇ τὰς χεῖρας, ἐπάναγκες εἶναι τοῖς περιεστῶσιν βάλλειν καὶ τοῦτον ἀποκτείνειν τὸν τρόπον."},{"number":366,"text":"ὅπερ ἕτοιμος ὢν αὐτὸς ἐν τῇ πατρίδι καὶ τῇ βασιλείᾳ ποιεῖν ὅμως ἀναμεῖναι τὴν ἐκείνων κρίσιν, ἥκειν μέντοι δικαστὰς μὲν οὐχ οὕτως ἐπὶ φανεροῖς οἷς ἐκ τῶν παίδων ὀλίγου πάθοι, συνοργισθῆναι δὲ καιρὸν ἔχοντας, ὡς οὐδενὶ καὶ τῶν πόρρω γεγονότων ἀμελῆσαι τοιαύτης ἐπιβουλῆς ἄξιον."},{"number":367,"text":"Ταῦτα τοῦ βασιλέως εἰπόντος καὶ τῶν νεανίσκων οὐδὲ ἕως ἀπολογίας παρηγμένων συμφρονήσαντες οἱ κατὰ τὸ συνέδριον, ὡς ἐπιεικείας καὶ διαλλαγῶν χεῖρον ἔχοι, τὴν ἐξουσίαν ἐβεβαίουν αὐτῷ."},{"number":368,"text":"καὶ πρῶτον μὲν Σατορνῖνος ἀνὴρ ὑπατικὸς καὶ τῶν ἐπʼ ἀξιώματος ἀπεφήνατο γνώμην ἀηδεστάτῃ περιστάσει χρώμενος· ἔφη γὰρ καταδικάζειν μὲν τῶν Ἡρώδου παίδων, κτείνειν δʼ οὐκ οἴεσθαι δικαιοῦν αὐτὸς παῖδας ἔχων καὶ τοῦ πάθους μείζονος ὄντος, εἰ καὶ πάντα διʼ αὐτοὺς δεδυστύχηκεν."},{"number":369,"text":"μετʼ ἐκεῖνον οἱ Σατορνίνου παῖδες, εἵποντο γὰρ αὐτῷ πρεσβευταὶ τρεῖς ὄντες, τὴν αὐτὴν γνώμην ἀπεφήναντο, Οὐολόμνιος δὲ ἄντικρυς ἔφη κολάζειν θανάτῳ τοὺς οὕτως ἀσεβήσαντας εἰς τὸν πατέρα. τὰ δʼ αὐτὰ καὶ τῶν ἑξῆς οἱ πλείους, ὥστε καὶ μηκέτι ἄλλο τι δοκεῖν ἢ καταδεδικάσθαι τὴν ἐπὶ θανάτῳ τοὺς νεανίσκους."},{"number":370,"text":"κἀκεῖθεν μὲν εὐθὺς Ἡρώδης ἧκεν ἄγων αὐτοὺς εἰς Τύρον, καὶ τοῦ τε Νικολάου πλεύσαντος ὡς αὐτὸν ἐκ τῆς Ῥώμης ἐπυνθάνετο προδιηγησάμενος τὰ ἐν Βηρυτῷ, ἥντινʼ ἔχοιεν γνώμην περὶ τῶν παίδων αὐτοῦ καὶ οἱ ἐν Ῥώμῃ αὐτοῦ φίλοι,"},{"number":371,"text":"κἀκεῖνος εἶπεν, ὅτι δοκεῖ μὲν ἀσεβῆ εἶναι τὰ ἐκείνοις περὶ σὲ ἐγνωσμένα, χρῆναι μέντοι αὐτοὺς καθείρξαντα δεσμώτας φυλάττειν,"},{"number":372,"text":"καὶ εἰ μὲν ἑτέρως σοι δοκοίη κολάζειν αὐτούς, μὴ φαίνοιο ὀργῇ τὸ πλεῖον ἢ γνώμῃ κεχρῆσθαι, εἰ δὲ τἀναντία ἀπολύειν, μὴ ἀνεπανόρθωτον εἴη σοι τὸ ἀτύχημα. ταῦτα δοκεῖ καὶ ἐν Ῥώμη τοῖς πλείστοις τῶν σῶν φίλων. καὶ ὃς σιωπήσας ἐν πολλῇ ἐγένετο συννοίᾳ κἀκεῖνον ἐκέλευσεν συμπλεῖν αὐτῷ."},{"number":373,"text":"Ὡς δʼ ἦλθεν εἰς Καισάρειαν γίνεται λόγος οὖν ἦν εὐθὺς ἅπασιν τῶν παίδων καὶ μετέωρος ἡ βασιλεία, ποῖ ποτε χωρήσειεν τὰ κατʼ αὐτοὺς ἐκδεχομένων·"},{"number":374,"text":"δεινὸν γὰρ ὑπῄει πάντας δέος ἐκ παλαιοῦ καταστασιαζομένους εἰς αὐτὸ τὸ πέρας ἐλθεῖν, καὶ τοῖς μὲν πάθεσιν ἐδυσχέραινον, οὐκ ἦν δʼ οὔτε εἰπεῖν τι προπετὲς οὔτʼ ἄλλου λέγοντος ἀκούειν ἀκίνδυνον, ἀλλʼ ἐγκεκλεισμένοι τὸν ἔλεον ὀδυνηρῶς μὲν ἀναύδως δὲ τὴν ὑπερβολὴν τοῦ πάθους ἔφερον."},{"number":375,"text":"εἷς δὲ αὐτῶν πάλαι στρατιώτης ὄνομα Τίρων, υἱοῦ αὐτῷ καθʼ ἡλικίαν ὄντος Ἀλεξάνδρῳ φίλου, πάνθʼ ὅσα καὶ τοῖς ἄλλοις ὑποδυόμενα διʼ ἡσυχίας ἦν, αὐτὸς ὑπʼ ἐλευθεριότητος ἐξελάλει καὶ βοᾶν ἠναγκάζετο πολλάκις ἐν τοῖς πλήθεσιν ἀπαρακαλύπτως λέγων,"},{"number":376,"text":"ὡς ἀπόλοιτο μὲν ἡ ἀλήθεια, τὸ δὲ δίκαιον ἐκ τῶν ἀνθρώπων ἀνῃρημένον εἴη, κρατοίη δὲ τὰ ψεύσματα καὶ ἡ κακοήθεια καὶ τοσοῦτο νέφος ἐπάγοι τοῖς πράγμασιν, ὡς μηδὲ τὰ μέγιστα τῶν ἀνθρωπίνων παθῶν ὁρᾶσθαι τοῖς ἁμαρτάνουσιν."},{"number":377,"text":"τοιοῦτος ὢν ἐδόκει μὲν οὐκ ἀκινδύνως παρρησιάζεσθαι, τὸ δʼ εὔλογον ἐκίνει πάντας οὐκ ἀνάνδρως αὐτοῦ πρὸς τὸν καιρὸν ἱσταμένου."},{"number":378,"text":"διὸ καὶ πάνθʼ ἅπερ αὐτὸς ἕκαστος εἴποιεν ἡδέως ἤκουον ὑπʼ ἐκείνου λεγόμενα καὶ τὸ καθʼ αὑτοὺς ἀσφαλὲς ἐν τῷ σιγᾶν προορώμενοι τὴν ἐκείνου παρρησίαν ὅμως ἀπεδέχοντο· τὸ γὰρ προσδοκώμενον πάθος ἐβιάζετο πάνθʼ ὁντινοῦν ὑπὲρ αὐτοῦ λαλεῖν."},{"number":379,"text":"Ὁ δὲ καὶ πρὸς τὸν βασιλέα μετὰ πάσης παρρησίας ὠσάμενος μόνος μόνῳ λέγειν ἠξίου, καὶ συγχωρήσαντος οὐ δυνάμενος, εἶπεν, ὦ βασιλεῦ, διακαρτερεῖν ἐπὶ τοιούτῳ πάθει τὴν τολμηρὰν ταύτην παρρησίαν, ἀναγκαίαν δὲ σοὶ καὶ συμφέρουσαν, εἰ λάβοις τι χρήσιμον ἐξ αὐτῆς, προύκρινα τῆς ἐμῆς ἀσφαλείας."},{"number":380,"text":"ποῖ ποτε οἴχονταί σου καὶ πεπτώκασιν ἐκ τῆς ψυχῆς αἱ φρένες; ποῖ δὲ καὶ ὁ περιττὸς ἐκεῖνος νοῦς, ᾧ πολλὰ καὶ μεγάλα κατώρθους; τίς δὲ ἡ τῶν φίλων καὶ συγγενῶν ἐρημία;"},{"number":381,"text":"κρίνω δὲ οὐδὲ παρόντας αὐτοὺς συγγενεῖς εἶναι ἢ φίλους, οἳ περιορῶσι τοιοῦτο μῦσος ἐπὶ τῇ μακαριζομένῃ ποτὲ βασιλείᾳ. σὺ δʼ οὐ σκέψει τί τὸ πραττόμενόν ἐστιν;"},{"number":382,"text":"δύο νεανίσκους ἐκ βασιλίδος γυναικὸς γενομένους εἰς πᾶσαν ἀρετὴν ἄκρους ἀναιρήσεις σεαυτὸν ἐν γήρᾳ καταλιπὼν ἐφʼ ἑνὶ παιδὶ κακῶς οἰκονομήσαντι τὴν εἰς αὐτὸν ἐλπίδα καὶ συγγενέσιν, ὧν αὐτὸς τοσαυτάκις ἤδη κατέγνωκας θάνατον;"},{"number":383,"text":"οὐκ ἐννοεῖς, ὅτι καὶ τῶν ὄχλων ἡ σιωπὴ τὴν αμογίαν ὅμως ὁρᾷ καὶ μισεῖ τὸ πάθος, ἥ τε στρατιὰ πᾶσα καὶ ταύτης οἱ πρωτεύοντες ἔλεον μὲν τῶν ἀτυχούντων, μῖσος δὲ τῶν ταῦτα διαπραττομένων ἐσχήκασιν;"},{"number":384,"text":"ἤκουεν τούτων ὁ βασιλεὺς ἐν ἀρχῇ μὲν οὐ παντάπασιν ἀγνωμόνως, ἀλλὰ τί δεῖ καὶ λέγειν, διεκίνησεν αὐτὸν ἁψαμένου τοῦ Τίρωνος ἐναργῶς τοῦ τε πάθους καὶ τῆς περὶ τοὺς οἰκείους ἀπιστίας."},{"number":385,"text":"αὖθις δὲ ὁ μὲν ἐπεδίδου κατὰ μικρὸν ἀμέτρῳ καὶ στρατιωτικῇ χρώμενος παρρησίᾳ· τὸ γὰρ ἀπαίδευτον ὑπεξέπιπτε τοῦ καιροῦ, ταραχῆς δὲ Ἡρώδης ἐνεπίμπλατο,"},{"number":386,"text":"καὶ μᾶλλον ὀνειδίζεσθαι δοκῶν ἢ πρὸς τὸ συμφέρον ἀκούειν τῶν λόγων, ἐπειδὴ καὶ τοὺς διακειμένους στρατιώτας καὶ τοὺς ἀγανακτοῦντας ἡγεμόνας ἐπύθετο, προστάττει τῷ τε ὀνόματι δηλωθέντων ἁπάντων καὶ τὸν Τίρωνα δήσαντας ἔχειν ἐν φυλακῇ."},{"number":387,"text":"Τούτου γενηθέντος ἐπιτίθεται τῷ καιρῷ καὶ Τρύφων τις κουρεὺς τοῦ βασιλέως, ὃς ἔφη προσελθὼν ὡς πείθοι πολλάκις αὐτὸν ὁ Τίρων, ὁπόταν θεραπεύῃ βασιλέως ξυρῷ τὸν λαιμὸν ἀποτέμνειν· ἔσεσθαι γὰρ ἐν πρώτοις περὶ Ἀλέξανδρον καὶ μεγάλας λήψεσθαι δωρεάς."},{"number":388,"text":"ταῦτʼ εἰπόντα συλλαμβάνειν κελεύει, καὶ μετὰ ταῦτα βάσανος ἦν τοῦ τε Τίρωνος καὶ τοῦ παιδὸς αὐτοῦ καὶ τοῦ κουρέως."},{"number":389,"text":"διακαρτεροῦντός τε τοῦ Τίρωνος ὁρῶν ὁ νεανίσκος τὸν πατέρα χαλεπῶς μὲν ἤδη διακείμενον, ἔχοντα δὲ οὐδεμίαν ἐλπίδα σωτηρίας αὑτῷ τε τὸ μέλλον ἐκ τῆς περὶ τὸν πάσχοντα δυσχερείας προῦπτον, ἔφη μηνύσειν τῷ βασιλεῖ τὴν ἀλήθειαν, εἰ παραιτήσεται διὰ τοῦ φράσαι τῆς βασάνου καὶ τῆς αἰκίας αὐτόν τε καὶ τὸν πατέρα."},{"number":390,"text":"δόντος δὲ πίστιν ἐπὶ τούτοις ἔλεγεν ὡς εἴη τις συνθήκη ἐπιθέσθαι διʼ αὐτοχειρίας βασιλεῖ τὸν Τίρωνα, προσελθεῖν γὰρ εὔπορον εἶναι μόνον μόνῳ καὶ δράσαντα παθεῖν τι τῶν εἰκότων οὐκ ἀγεννὲς Ἀλεξάνδρῳ χαριζόμενον."},{"number":391,"text":"ταῦτα μὲν οὖν ἐκεῖνος εἰπὼν ἐξαιρεῖται τὸν πατέρα τῆς ἀνάγκης, ἄδηλον εἴτε τὴν ἀλήθειαν ἐκβιασθεὶς φράζειν, εἴτε κἂν παραγραφὴν νοήσας τινὰ ταύτην τῶν κακῶν αὐτῷ καὶ τῷ γεγεννηκότι."},{"number":392,"text":"Ὁ δὲ Ἡρώδης οὐδʼ εἴ τι πρότερον ἦν αὐτῷ ἐνδοιάσιμον περὶ τὴν τεκνοκτονίαν τούτῳ τόπον ἢ χώραν ἐν τῇ ψυχῇ καταλελοιπώς, ἀλλὰ πᾶν ἐξῃρημένος τὸ δυνησόμενον αὐτῷ μετάνοιαν ἀμείνονος λογισμοῦ παρασχεῖν ἔσπευσεν ἤδη τέλος ἐπιθεῖναι τῇ προαιρέσει."},{"number":393,"text":"καὶ προαγαγὼν εἰς ἐκκλησίαν τριακοσίους τε τῶν ἡγεμόνων τοὺς ἐν αἰτίᾳ γενομένους καὶ τὸν Τίρωνα σὺν τῷ παιδὶ καὶ τῷ πρὸ ἐκείνου διελέγχοντι κουρεῖ κατηγορίαν ἁπάντων αὐτῶν ἐποιήσατο."},{"number":394,"text":"κἀκείνους μὲν τὸ πλῆθος ἀεὶ τοῖς παρατυχοῦσιν βάλλοντες ἀπέκτειναν. Ἀλέξανδρος δὲ καὶ Ἀριστόβουλος ἀχθέντες εἰς Σεβαστὴν ἐπιτάξαντος τοῦ πατρὸς στραγγάλῃ κτείνονται. τὰ δὲ σώματα νύκτωρ εἰς Ἀλεξάνδρειον ἀπέθεντο τοῦ τε μητροπάτορος ἐκεῖ καὶ τῶν πλείστων αὐτοῖς προγόνων κειμένων."},{"number":395,"text":"Ἴσως μὲν οὖν οὐκ ἄλογον ἐνίοις καταφαίνεται τρεφόμενον ἐκ πολλοῦ τὸ μῖσος οὕτως αὐξηθῆναι καὶ περαιτέρω προελθὸν ἀπονικῆσαι τὴν φύσιν. ἐπίστασις δὲ γένοιτʼ ἂν εἰκότως, εἴτε εἰς τοὺς νεανίσκους ἀνοιστέον τὴν τοιαύτην αἰτίαν πρὸς αἰτίαν ἐνάγοντας τὸν πατέρα καὶ χρόνῳ παρασκευάσαντας ὑπὸ χαλεπότητος ἀνήκεστον αὐτοῖς,"},{"number":396,"text":"εἴτε καὶ πρὸς αὐτὸν ἐκεῖνον, ἀπαθῆ καὶ περιττὸν ὄντα περὶ τὴν ἐπιθυμίαν τῆς ἀρχῆς καὶ τῆς ἄλλης εὐδοξίας, ὡς μηδένα οἴεσθαι παραλειπτέον ἐφʼ ᾧ πᾶν τὸ βουλόμενον ἀνίκητον ἔχειν,"},{"number":397,"text":"ἢ καὶ τὴν τύχην παντὸς εὐγνώμονος λογισμοῦ μείζω τὴν δύναμιν ἐσχηκυῖαν, ὅθεν καὶ πειθόμεθα τὰς ἀνθρωπίνας πράξεις ὑπʼ ἐκείνης προκαθωσιῶσθαι τῇ τοῦ γενέσθαι πάντως ἀνάγκῃ καὶ καλοῦμεν αὐτὴν εἱμαρμένην, ὡς οὐδενὸς ὄντος, ὃ μὴ διʼ αὐτὴν γίνεται."},{"number":398,"text":"τοῦτον μὲν οὖν τὸν λόγον ὡς μείζω πρὸς ἐκεῖνον ἀρκέσει κινεῖν ἡμῖν τε αὐτοῖς ἀποδιδόντας τι καὶ τὰς διαφορὰς τῶν ἐπιτηδευμάτων οὐκ ἀνυπευθύνους ποιοῦντας, ἃ πρὸ ἡμῶν ἤδη πεφιλοσόφηται καὶ τῷ νόμῳ."},{"number":399,"text":"τῶν δὲ ἄλλων δύο τὸν μὲν ἀπὸ τῶν παίδων μέμψαιτʼ ἄν τις αἰτίαν ὑπό τε αὐθαδείας νεωτερικῆς καὶ βασιλικῆς οἰήσεως, ὅτι καὶ διαβολῶν ἠνείχοντο κατὰ τοῦ πατρὸς καὶ τῶν πραττομένων αὐτῷ περὶ τὸν βίον οὐκ εὐμενεῖς ἦσαν ἐξετασταί, καὶ κακοήθεις μὲν ὑπονοεῖν, ἀκρατεῖς δὲ λέγειν, εὐάλωται δὲ διʼ ἀμφότερα τοῖς ἐπιτηροῦσιν αὐτοὺς καὶ πρὸς χάριν καταμηνύουσιν."},{"number":400,"text":"ὁ μέντοι πατὴρ οὐδʼ ἐντροπῆς ἄξιος ἔοικεν φαίνεσθαι τοῦ περὶ ἐκείνους ἀσεβήματος, ὃς οὔτε πίστιν ἐπιβουλῆς ἐναργῆ λαβὼν οὔτε παρασκευὴν ἐπιχειρήσεως ἐλέγχειν ἔχων ἐτόλμησεν ἀποκτεῖναι τοὺς ἐξ αὐτοῦ φύντας, ἀρίστους μὲν τὰ σώματα καὶ περιποθήτους πᾶσιν τοῖς ἀλλοτρίοις, οὐκ ἀποδέοντας δὲ ἐν τοῖς ἐπιτηδεύμασιν, εἴ που θηρᾶν ἢ γυμνάζεσθαι τὰ πολέμων ἢ λέγειν ὑπὲρ τῶν ἐμπεσόντων ἔδει."},{"number":401,"text":"τούτων γὰρ ἁπάντων μετεῖχον, Ἀλέξανδρος δὲ καὶ μᾶλλον ὁ πρεσβύτερος· ἤρκει γάρ, εἰ καὶ κατέγνω, καὶ ζῶντας ὅμως ἐν δεσμοῖς ἢ ξενιτεύοντας ἀπὸ τῆς ἀρχῆς ἔχειν μεγάλην ἀσφάλειαν αὐτῷ περιβεβλημένῳ τὴν Ῥωμαίων δύναμιν, διʼ ἣν οὐδὲν οὐδʼ ἐξ ἐφόδου καὶ βίας παθεῖν ἐδύνατο."},{"number":402,"text":"τὸ δʼ ἀποκτεῖναι ταχὺ καὶ πρὸς ἡδονὴν τοῦ νικῶντος αὐτὸν πάθους ἀσεβείας τεκμήριον ἀνυποτιμήτου καὶ τῆς ἡλικίας οὔσης ἐν γήρᾳ τοσοῦτον ἐξήμαρτεν."},{"number":403,"text":"ἥ γε μὴν παρολκὴ καὶ τὸ χρονίζον οὐκ ἂν αὐτῷ συγγνώμην τινὰ φέροι· ταχὺ μὲν γὰρ ἐκπλαγέντα καὶ κεκινημένον χωρῆσαι πρός τι τῶν ἀτόπων, εἰ καὶ δυσχερές, ἀλλʼ ἀεὶ συμβαῖνον, ἐν ἐπιστάσει δὲ καὶ μήκει πολλάκις μὲν ὁρμηθέντα πολλάκις δὲ μελλήσαντα τὸ τελευταῖον ὑποστῆναι καὶ διαπράξασθαι, φονώσης καὶ δυσμετακινήτου ψυχῆς ἀπὸ τῶν χειρόνων."},{"number":404,"text":"ἐδήλωσεν δὲ καὶ τοῖς αὖθις οὐκ ἀποσχόμενος οὐδὲ τῶν περιλοίπων ὅσους ἐδόκει φιλτάτους, ἐφʼ οἷς τὸ μὲν δίκαιον ἔλαττον ἐποίει συμπαθεῖσθαι τοὺς ἀπολλυμένους, τὸ δʼ ὠμὸν ὅμοιον ἦν τὸ μηδὲ ἐκείνων φεισάμενον. διέξιμεν δὲ ὑπὲρ αὐτῶν ἑξῆς ἀφηγούμενοι."}]},"count":404};})();
